def _run_st4_010_after_use_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    opponent_type='수비', source_zone='battle', negated=False,
    dash_restart=False, defense_over_count=2,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st4_010_source(
        card_snapshot, owner, zone=source_zone, negated=negated,
    )
    opposing = _st4_010_opposing(owner, card_type=opponent_type)
    opposing_definition = _st1_001_no_effect_definition()
    if dash_restart:
        opposing.update({
            'code': 'ST1-015', 'name': '대쉬', 'type': '수비',
            'frame': None, 'damage': None, 'pos': None, 'body': None,
            'g_top': '회피', 'g_mid': '회피', 'g_bot': '회피',
        })
        opposing_definition = _st4_010_dash_definition()
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    if source_zone != 'battle':
        state['players'][owner]['zones']['battle'] = []
    if dash_restart:
        state['priority_player'] = other
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': copy.deepcopy(opposing_definition),
                },
            },
        },
        seed=(
            f'st4-010-after-use:{owner}:{event_type}:{opponent_type}:'
            f'{source_zone}:{negated}:{dash_restart}:{defense_over_count}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    battle = {
        owner: {'instance_id': source['instance_id'], 'card': live_source},
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
        'actual_damage_received': {owner: 0, other: 0},
        'damage_event_count_before': sum(
            event.get('type') == 'damage_dealt' for event in engine.events
        ),
        'fp_event_count_before': sum(
            event.get('type') == 'fp_changed' for event in engine.events
        ),
        'effect_count_before': sum(
            event.get('type') == 'effect_resolved' for event in engine.events
        ),
    }
    engine.engine_state['battle'] = battle
    engine.engine_state['defense_over_count'] = defense_over_count
    defense_over = None
    if dash_restart:
        engine.engine_state['pipeline'] = {
            'kind': 'battle', 'stage': 'after_judgment',
        }
        engine._continue()
    elif source_zone == 'battle':
        engine._battle_trigger(event_type)
        engine._continue()
        if event_type == 'after_use' and opponent_type == '수비':
            defense_over = engine._record_defense_over(battle)
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': copy.deepcopy(live_source),
            'opponent_card': copy.deepcopy(live_opposing),
        })
        engine._continue()
    return {
        'owner_fp': engine.state['players'][owner]['fp'],
        'opponent_fp': engine.state['players'][other]['fp'],
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st4-010-n2'
            for event in engine.events
        ),
        'phase': engine.state.get('phase'),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'opponent_zone': engine._find_location(opposing['instance_id'])[1],
        'phase_restarted': any(
            event.get('type') == 'phase_restarted' for event in engine.events
        ),
        'defense_over': defense_over,
        'defense_over_count': engine.engine_state.get('defense_over_count'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st4_010_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-010':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st4-010-function')
    dodge = by_id.get('st4-010-n1')
    after_use = by_id.get('st4-010-n2')
    qna_ids = [68, 242, 276, 496, 573]
    discard_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['hand'], 'min': 1, 'max': 1,
        'as_operation': 'discard',
    }
    schedule = {
        'op': 'schedule',
        'when': {'event': 'catch', 'controller': 'self'},
        'duration': 'turn', 'preserve_source': True,
        'effect': {
            'op': 'request_choice', 'player': {'controller': True},
            'prompt': '이번 턴 캐치 시 버릴 패 1장을 선택하세요.',
            'selector': discard_selector,
            'selection_key': 'st4_010_catch_discard', 'default': [],
            'then': [{
                'op': 'discard',
                'selection_key': 'st4_010_catch_discard',
                'result_key': 'st4_010_catch_discarded',
            }],
        },
    }
    after_use_condition = {
        'op': 'card_matches',
        'card': {'path': 'context.opponent_card'},
        'where': {'type_contains': '수비'},
    }
    valid = bool(
        extra_root == {'defense_rules'}
        and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('defense_rules') == [{'max_speed': 8}]
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('active_zones') == ['battle']
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and dodge and dodge.get('kind') == 'effect'
        and dodge.get('mode') == 'mandatory'
        and dodge.get('timing') == 'dodge'
        and dodge.get('active_zones') == ['battle']
        and dodge.get('trigger') == {'event': 'dodge'}
        and dodge.get('effects') == [
            {
                'op': 'change_fp',
                'player': {'controller': True}, 'amount': 7,
            },
            schedule,
        ]
        and after_use and after_use.get('kind') == 'effect'
        and after_use.get('mode') == 'mandatory'
        and after_use.get('timing') == 'after_use'
        and after_use.get('active_zones') == ['battle']
        and after_use.get('trigger') == {'event': 'after_use'}
        and after_use.get('condition') == after_use_condition
        and after_use.get('effects') == [{
            'op': 'change_fp', 'player': {'opponent': True}, 'amount': 6,
        }]
        and str((card_snapshot or {}).get('type') or '') == '수비'
        and all(
            (card_snapshot or {}).get(field) is None
            for field in (
                'frame', 'damage', 'pos', 'body', 'hit', 'guard',
                'counter', 'special',
            )
        )
        and all(
            str((card_snapshot or {}).get(field) or '') == '회피'
            for field in ('g_top', 'g_mid', 'g_bot')
        )
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st4-010', False,
                reason=(
                    '래빗 일루젼의 8속도 회피, 회피 후 캐치 버리기 예약, '
                    '사용 후 수비 조건 또는 Q&A 출처가 일치하지 않습니다.'
                ),
            )],
            'ST4-010 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-speed-eight-dodges', 'p1', {}, {
            'allowed': True, 'reference_speed': 8,
        }),
        ('owner-p2-speed-one-dodges', 'p2', {
            'opponent_speed': 1,
        }, {'allowed': True, 'reference_speed': 1}),
        ('speed-nine-is-above-boundary', 'p1', {
            'opponent_speed': 9,
        }, {'allowed': False, 'reference_speed': 9}),
        ('qna-496-effect-lowered-thirteen-to-five-dodges', 'p2', {
            'opponent_speed': 13, 'speed_modifier': -8,
        }, {'allowed': True, 'reference_speed': 5}),
        ('effect-raised-seven-to-nine-fails', 'p1', {
            'opponent_speed': 7, 'speed_modifier': 2,
        }, {'allowed': False, 'reference_speed': 9}),
        ('fp-does-not-lower-reference-speed', 'p2', {
            'opponent_speed': 13, 'opponent_fp': 8,
        }, {
            'allowed': False, 'reference_speed': 13, 'final_speed': 5,
        }),
        ('numbered-negation-preserves-numberless-boundary', 'p1', {
            'negated': True,
        }, {'allowed': True, 'reference_speed': 8}),
        ('lower-position-uses-same-boundary', 'p2', {
            'position': '하단',
        }, {'allowed': True, 'reference_speed': 8}),
    ):
        first = _run_st4_010_defense_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_010_defense_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    dodge_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-dodge-discards-selected-normal-card', 'p1', {}, {
            'owner_fp': 8, 'resolved_count': 1,
            'scheduled_after_dodge': 1, 'decision_kind': 'effect_choice',
            'decision_owner': 'p1', 'scheduled_final': 0,
        }),
        ('owner-p2-chooses-second-normal-card', 'p2', {
            'select_index': 1,
        }, {
            'owner_fp': 8, 'resolved_count': 1,
            'decision_kind': 'effect_choice', 'decision_owner': 'p2',
        }),
        ('qna-242-normal-discard-moves-to-list', 'p1', {
            'hand_types': ('공격',),
        }, {'decision_kind': 'effect_choice'}),
        ('special-technique-discard-redirects-to-break', 'p2', {
            'hand_types': ('특수',),
        }, {'decision_kind': 'effect_choice'}),
        ('protected-card-is-excluded-from-choice', 'p1', {
            'protected_indices': (0,),
        }, {'decision_kind': 'effect_choice'}),
        ('empty-hand-consumes-obligation-without-choice', 'p2', {
            'hand_types': (),
        }, {
            'owner_fp': 8, 'decision_kind': None,
            'choice_skipped_count': 1, 'scheduled_final': 0,
        }),
        ('opponent-catch-does-not-consume-owner-obligation', 'p1', {
            'fire_opponent_catch': True,
        }, {
            'scheduled_after_opponent_catch': 1,
            'decision_kind': 'effect_choice', 'scheduled_final': 0,
        }),
        ('turn-expiration-removes-unused-obligation', 'p2', {
            'expire_turn': True,
        }, {
            'owner_fp': 8, 'decision_kind': None, 'scheduled_final': 0,
        }),
        ('wrong-event-does-not-gain-fp-or-schedule', 'p1', {
            'event_type': 'guard',
        }, {
            'owner_fp': 1, 'resolved_count': 0,
            'scheduled_after_dodge': 0, 'decision_kind': None,
        }),
        ('source-in-hand-does-not-trigger', 'p2', {
            'source_zone': 'hand',
        }, {
            'owner_fp': 1, 'resolved_count': 0,
            'scheduled_after_dodge': 0, 'decision_kind': None,
        }),
        ('numbered-negation-does-not-trigger', 'p1', {
            'negated': True,
        }, {
            'owner_fp': 1, 'resolved_count': 0,
            'scheduled_after_dodge': 0, 'decision_kind': None,
        }),
    ):
        first = _run_st4_010_dodge_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_010_dodge_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        movement_ok = True
        if first['selected_id']:
            selected_type = next(
                (
                    card_type for index, card_type in enumerate(
                        kwargs.get('hand_types', ('공격', '수비'))
                    )
                    if f'{owner}-st4-010-hand-{index + 1}'
                    == first['selected_id']
                ),
                '공격',
            )
            movement_ok = first['locations'][first['selected_id']] == (
                'break' if selected_type == '특수' else 'list'
            )
        if name == 'protected-card-is-excluded-from-choice':
            movement_ok = bool(
                first['hand_ids'][0] not in first['option_ids']
                and first['locations'][first['hand_ids'][0]] == 'hand'
                and first['locations'][first['hand_ids'][1]] == 'list'
            )
        dodge_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and movement_ok and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    after_use_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-opposing-defense-gains-six-fp', 'p1', {}, {
            'opponent_fp': 6, 'resolved_count': 1,
        }),
        ('owner-p2-opposing-defense-gains-six-fp', 'p2', {}, {
            'opponent_fp': 6, 'resolved_count': 1,
        }),
        ('opposing-attack-does-not-trigger', 'p1', {
            'opponent_type': '공격',
        }, {'opponent_fp': 0, 'resolved_count': 0}),
        ('qna-573-after-judgment-is-wrong-timing', 'p2', {
            'event_type': 'after_judgment',
        }, {'opponent_fp': 0, 'resolved_count': 0}),
        ('source-in-hand-does-not-trigger', 'p1', {
            'source_zone': 'hand',
        }, {'opponent_fp': 0, 'resolved_count': 0}),
        ('numbered-negation-does-not-trigger', 'p2', {
            'negated': True,
        }, {'opponent_fp': 0, 'resolved_count': 0}),
        ('qna-276-dash-restarts-ready-before-after-use', 'p1', {
            'dash_restart': True,
        }, {
            'opponent_fp': 6, 'resolved_count': 0,
            'phase': 'ready', 'phase_restarted': True,
            'source_zone': 'list', 'opponent_zone': 'list',
        }),
        ('qna-68-resolved-effect-resets-defense-over-count', 'p2', {}, {
            'opponent_fp': 6, 'resolved_count': 1,
            'defense_over': False, 'defense_over_count': 0,
        }),
    ):
        first = _run_st4_010_after_use_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_010_after_use_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        after_use_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            function['id'], all(item['passed'] for item in defense_scenarios),
            defense_scenarios,
        ),
        AbilityReview(
            dodge['id'], all(item['passed'] for item in dodge_scenarios),
            dodge_scenarios,
        ),
        AbilityReview(
            after_use['id'],
            all(item['passed'] for item in after_use_scenarios),
            after_use_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST4-010 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_pmp_at_050_game_start_scenario(
    definition, card_snapshot, owner, event_type,
):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-pmp-at-050', 'owner': owner,
        'type': '특수', 'frame': None, 'damage': None, 'face_up': True,
    })
    other = 'p2' if owner == 'p1' else 'p1'
    opposing = _card('REVIEW-PMP-AT-050-OPPONENT', other, f'{other}-opponent')
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['battle'] = []
    state['players'][owner]['zones']['side'] = [copy.deepcopy(source)]
    engine = AutomaticGameEngine(
        state, {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'pmp-at-050-game-start:{owner}:{event_type}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
    })
    source_zone = next((
        zone for zone, cards in engine.state['players'][owner]['zones'].items()
        if any(card.get('instance_id') == source['instance_id'] for card in cards)
    ), None)
    return {
        'source_zone': source_zone,
        'move_count': sum(
            1 for event in engine.events
            if event.get('type') == 'card_moved'
            and (event.get('payload') or {}).get('card_instance_id')
            == source['instance_id']
        ),
    }


def _run_pmp_at_050_optional_scenario(
    definition, card_snapshot, owner, *, hand_count=1,
    controller_hp=3000, opponent_hp=4000, combo_number=3, accept=True,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-pmp-at-050', 'owner': owner,
        'type': '특수', 'frame': None, 'damage': None, 'face_up': True,
    })
    opposing = _card('REVIEW-PMP-AT-050-OPPONENT', other, f'{other}-combo-card')
    hand_cards = [
        _card(f'REVIEW-PMP-HAND-{index}', owner, f'{owner}-hand-{index}')
        for index in range(hand_count)
    ]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    ruleset_cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    for card in hand_cards:
        ruleset_cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': no_effect,
        }
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['battle'] = []
    state['players'][owner]['zones']['lumen'] = [copy.deepcopy(source)]
    state['players'][owner]['zones']['hand'] = copy.deepcopy(hand_cards)
    state['players'][owner]['hp'] = controller_hp
    state['players'][other]['hp'] = opponent_hp
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'pmp-at-050:{owner}:{hand_count}:{controller_hp}:'
            f'{opponent_hp}:{combo_number}:{accept}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['combo'] = {
        'owner': other, 'source': opposing['instance_id'],
        'used': [f'combo-{index}' for index in range(combo_number - 1)],
        'next_penalty': 100 * combo_number,
    }
    engine._fire('after_use', {
        'controller': other,
        'source_card_instance_id': opposing['instance_id'],
        'source_card': engine._find_card(opposing['instance_id']),
        'combo': True, 'combo_number': combo_number,
    })
    decisions = []
    while engine.engine_state.get('pending_decision'):
        decision = engine.engine_state['pending_decision']
        decisions.append({
            'kind': decision.get('kind'),
            'minimum': int(decision.get('minimum') or 0),
            'maximum': int(decision.get('maximum') or 0),
            'option_ids': sorted(
                str(option.get('id')) for option in decision.get('options') or []
            ),
        })
        if len(decisions) > 5:
            raise EffectSandboxError('PMP-AT-050 선택 단계가 5회를 초과했습니다.')
        if decision.get('kind') == 'optional_effect':
            selected = ['accept'] if accept else ['decline']
        else:
            selected = [decisions[-1]['option_ids'][0]] if decisions[-1]['option_ids'] else []
        engine._submit_decision(owner, decision.get('id'), selected)
        engine._continue()
    return {
        'decisions': decisions,
        'source_in_lumen': bool(engine._find_card(
            source['instance_id'], owner=owner, zone='lumen',
        )),
        'source_in_break': bool(engine._find_card(
            source['instance_id'], owner=owner, zone='break',
        )),
        'discarded_count': sum(
            1 for event in engine.events
            if event.get('type') == 'card_discarded' and event.get('actor') == owner
        ),
        'combo_active': bool(engine.engine_state.get('combo')),
        'pending_decision': (
            (engine.engine_state.get('pending_decision') or {}).get('kind')
        ),
        'break_replenish_count': sum(
            1 for event in engine.events
            if event.get('type') == 'decision_requested'
            and (event.get('payload') or {}).get('kind') == 'break_replenish'
        ),
    }


def _review_pmp_at_050_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'PMP-AT-050':
        return None
    abilities = definition.get('abilities') or []
    game_start = next((
        ability for ability in abilities
        if ability.get('id') == 'pmp-at-050-function'
    ), None)
    optional = next((
        ability for ability in abilities
        if ability.get('id') == 'pmp-at-050-n1'
    ), None)
    expected_condition = {
        'op': 'all', 'conditions': [
            {
                'op': 'equals', 'left': 'context.event_controller',
                'right': {'opponent': True},
            },
            {'op': 'equals', 'left': 'context.combo', 'right': True},
            {'op': 'equals', 'left': 'context.combo_number', 'right': 3},
            {
                'op': 'lt', 'left': 'context.controller_hp',
                'right': {'path': 'context.opponent_hp'},
            },
            {
                'op': 'zone_count', 'player': {'controller': True},
                'zone': 'hand', 'min': 1,
            },
        ],
    }
    selection_key = 'pmp_at_050_discard'
    expected_effects = [{
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '버릴 패 1장을 선택하세요.',
        'selector': {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['hand'], 'min': 1, 'max': 1,
            'as_operation': 'discard',
        },
        'selection_key': selection_key, 'default': [],
        'then': [
            {'op': 'discard', 'selection_key': selection_key},
            {'op': 'break_card'}, {'op': 'end_combo'},
        ],
    }]
    qna_ids = [632, 635]
    valid = bool(
        not extra_root
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and len(abilities) == 2
        and game_start
        and game_start.get('mode') == 'mandatory'
        and game_start.get('trigger') == {'event': 'game_start'}
        and game_start.get('active_zones') == ['side']
        and game_start.get('effects') == [{'op': 'move_card', 'to_zone': 'lumen'}]
        and optional
        and optional.get('mode') == 'optional'
        and optional.get('trigger') == {'event': 'after_use'}
        and optional.get('active_zones') == ['lumen']
        and optional.get('condition') == expected_condition
        and optional.get('effects') == expected_effects
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'pmp-at-050', False,
                reason='구사일생의 배치·3콤보·패 비용·브레이크 형식이 일치하지 않습니다.',
            )],
            reason='PMP-AT-050 카드별 규칙 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    game_scenarios = []
    for name, owner, event_type, expected_zone in (
        ('owner-p1-game-start', 'p1', 'game_start', 'lumen'),
        ('owner-p2-game-start', 'p2', 'game_start', 'lumen'),
        ('wrong-trigger-stays-side', 'p1', 'turn_start', 'side'),
    ):
        first = _run_pmp_at_050_game_start_scenario(
            definition, card_snapshot, owner, event_type,
        )
        second = _run_pmp_at_050_game_start_scenario(
            definition, card_snapshot, owner, event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_moves = 1 if expected_zone == 'lumen' else 0
        game_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['source_zone'] == expected_zone
                and first['move_count'] == expected_moves
            ),
            'deterministic': deterministic,
            'expected_zone': expected_zone, **first,
        })
    game_passed = all(item['passed'] for item in game_scenarios)
    game_review = AbilityReview(
        str(game_start.get('id')), game_passed, game_scenarios,
        '' if game_passed else '구사일생 게임 시작 배치 검증에 실패했습니다.',
    )
    optional_specs = (
        ('owner-p1-accepts', 'p1', 1, 3000, 4000, 3, True, True),
        ('owner-p2-chooses-one-of-two', 'p2', 2, 3000, 4000, 3, True, True),
        ('optional-declined', 'p1', 1, 3000, 4000, 3, False, False),
        ('qna-632-fourth-combo-rejected', 'p1', 1, 3000, 4000, 4, True, False),
        ('hp-not-lower', 'p1', 1, 4000, 4000, 3, True, False),
        ('no-hand-card', 'p1', 0, 3000, 4000, 3, True, False),
    )
    optional_scenarios = []
    for (
        name, owner, hand_count, controller_hp, opponent_hp,
        combo_number, accept, expected_resolution,
    ) in optional_specs:
        first = _run_pmp_at_050_optional_scenario(
            definition, card_snapshot, owner, hand_count=hand_count,
            controller_hp=controller_hp, opponent_hp=opponent_hp,
            combo_number=combo_number, accept=accept,
        )
        second = _run_pmp_at_050_optional_scenario(
            definition, card_snapshot, owner, hand_count=hand_count,
            controller_hp=controller_hp, opponent_hp=opponent_hp,
            combo_number=combo_number, accept=accept,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_decisions = (
            ['optional_effect', 'effect_choice']
            if expected_resolution else (
                ['optional_effect'] if (
                    combo_number == 3 and controller_hp < opponent_hp
                    and hand_count >= 1
                ) else []
            )
        )
        decision_kinds = [item['kind'] for item in first['decisions']]
        behavior = bool(
            decision_kinds == expected_decisions
            and first['source_in_break'] is expected_resolution
            and first['source_in_lumen'] is (not expected_resolution)
            and first['discarded_count'] == (1 if expected_resolution else 0)
            and first['combo_active'] is (not expected_resolution)
            and first['pending_decision'] is None
            and first['break_replenish_count'] == 0
            and (
                name != 'owner-p2-chooses-one-of-two'
                or len(first['decisions'][1]['option_ids']) == 2
            )
        )
        optional_scenarios.append({
            'name': name, 'passed': bool(deterministic and behavior),
            'deterministic': deterministic,
            'expected_resolution': expected_resolution,
            'combo_number': combo_number, 'hand_count': hand_count,
            'accepted': accept, **first,
        })
    optional_passed = all(item['passed'] for item in optional_scenarios)
    optional_review = AbilityReview(
        str(optional.get('id')), optional_passed, optional_scenarios,
        '' if optional_passed else '구사일생 선택·3콤보·특수 브레이크 검증에 실패했습니다.',
    )
    reviewed = [game_review, optional_review]
    passed = all(item.passed and item.scenarios for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else 'PMP-AT-050 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _pmp_at_009_engine(definition, card_snapshot, owner, *, source_zone='hand'):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-pmp-at-009', 'owner': owner,
        'type': '공격', 'frame': 13, 'damage': 700, 'face_up': True,
    })
    opposing = _card('REVIEW-PMP-AT-009-OPPONENT', other, f'{other}-opponent')
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['battle'] = []
    state['players'][owner]['zones'][source_zone] = [copy.deepcopy(source)]
    engine = AutomaticGameEngine(
        state, {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'pmp-at-009:{owner}:{source_zone}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, source, opposing, no_effect


def _run_pmp_at_009_play_cost_scenario(
    definition, card_snapshot, owner, *, spider_count,
):
    engine, source, _opposing, no_effect = _pmp_at_009_engine(
        definition, card_snapshot, owner, source_zone='hand',
    )
    spiders = []
    for index in range(spider_count):
        spider = _card('REVIEW-SPIDER-TOKEN', owner, f'{owner}-spider-{index}')
        spider.update({'kind': 'token', 'type': '특수', 'token_key': 'spider'})
        spiders.append(spider)
    wrong = _card('REVIEW-WRONG-TOKEN', owner, f'{owner}-wrong-token')
    wrong.update({'kind': 'token', 'type': '특수', 'token_key': 'not_spider'})
    engine.state['players'][owner]['zones']['lumen'] = [
        *copy.deepcopy(spiders), copy.deepcopy(wrong),
    ]
    engine.ruleset['cards']['REVIEW-SPIDER-TOKEN'] = {
        **(
            copy.deepcopy(spiders[0]) if spiders else {
                'code': 'REVIEW-SPIDER-TOKEN', 'type': '특수',
            }
        ),
        'effect_definition': no_effect,
    }
    engine.ruleset['cards'][wrong['code']] = {
        **copy.deepcopy(wrong), 'effect_definition': no_effect,
    }
    engine.state['phase'] = 'ready'
    engine.engine_state['step'] = 'ready_actions'
    legal = any(
        action.get('type') == 'ready_card'
        and (action.get('payload') or {}).get('card_instance_id')
        == source['instance_id']
        for action in engine.legal_actions(owner)
    )
    decision_kind = None
    decision_range = None
    option_ids = []
    if legal:
        engine._ready_card(owner, source['instance_id'])
        decision = engine.engine_state.get('pending_decision') or {}
        decision_kind = decision.get('kind')
        decision_range = (
            int(decision.get('minimum') or 0),
            int(decision.get('maximum') or 0),
        )
        option_ids = sorted(
            str(option.get('id')) for option in decision.get('options') or []
        )
        engine._submit_decision(owner, decision.get('id'), option_ids[:4])
        engine._continue()
    remaining_spiders = sorted(
        card.get('instance_id')
        for card in engine.state['players'][owner]['zones']['lumen']
        if card.get('token_key') == 'spider'
    )
    return {
        'legal': legal,
        'decision_kind': decision_kind,
        'decision_range': decision_range,
        'option_ids': option_ids,
        'deleted_count': sum(
            1 for event in engine.events if event.get('type') == 'token_deleted'
        ),
        'remaining_spiders': remaining_spiders,
        'wrong_token_preserved': bool(engine._find_card(wrong['instance_id'])),
        'source_in_battle': bool(engine._find_card(
            source['instance_id'], owner=owner, zone='battle',
        )),
    }


def _run_pmp_at_009_hp_cost_scenario(
    definition, card_snapshot, owner, event_type, *, hp,
):
    engine, source, _opposing, _no_effect = _pmp_at_009_engine(
        definition, card_snapshot, owner, source_zone='battle',
    )
    engine.state['players'][owner]['hp'] = hp
    before = hp
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
    })
    return {
        'before': before,
        'after': int(engine.state['players'][owner]['hp']),
        'winner': engine.engine_state.get('winner'),
        'hp_event_amounts': [
            (event.get('payload') or {}).get('amount')
            for event in engine.events
            if event.get('type') == 'hp_changed' and event.get('actor') == owner
        ],
    }


def _run_pmp_at_009_combo_heal_scenario(
    definition, card_snapshot, owner, *, combo_owner, used_count,
):
    engine, source, _opposing, _no_effect = _pmp_at_009_engine(
        definition, card_snapshot, owner, source_zone='battle',
    )
    engine.state['players'][owner]['hp'] = 3000
    used = [source['instance_id']]
    used.extend(f'{combo_owner}-combo-{index}' for index in range(1, used_count))
    engine.engine_state['combo'] = {
        'owner': combo_owner, 'source': 'combo-source',
        'used': used, 'next_penalty': 100 * (used_count + 1),
    }
    engine.end_combo()
    engine._continue()
    return {
        'before': 3000,
        'after': int(engine.state['players'][owner]['hp']),
        'hp_event_amounts': [
            (event.get('payload') or {}).get('amount')
            for event in engine.events
            if event.get('type') == 'hp_changed' and event.get('actor') == owner
        ],
    }


def _review_pmp_at_009_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'PMP-AT-009':
        return None
    abilities = definition.get('abilities') or []
    function_ability = next((
        ability for ability in abilities
        if ability.get('id') == 'pmp-at-009-function'
    ), None)
    hp_ability = next((
        ability for ability in abilities if ability.get('id') == 'pmp-at-009-n1'
    ), None)
    heal_ability = next((
        ability for ability in abilities if ability.get('id') == 'pmp-at-009-n2'
    ), None)
    expected_costs = [{
        'operation': 'delete_token',
        'selector': {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['lumen'], 'min': 4, 'max': 4,
            'where': {'token_key': 'spider'},
        },
    }]
    valid = bool(
        extra_root == {'play_costs'}
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or []) == [627]
        and len(abilities) == 3
        and definition.get('play_costs') == expected_costs
        and function_ability
        and function_ability.get('mode') == 'continuous'
        and function_ability.get('effects') == [{
            'op': 'static_rule', 'rules': ['play_costs'],
        }]
        and hp_ability
        and hp_ability.get('mode') == 'mandatory'
        and hp_ability.get('trigger') == {'event': 'use'}
        and not hp_ability.get('condition')
        and hp_ability.get('cost') == [{
            'op': 'change_hp', 'player': {'controller': True}, 'amount': -400,
        }]
        and hp_ability.get('effects') == [{
            'op': 'static_rule', 'rules': ['ability_cost'],
        }]
        and heal_ability
        and heal_ability.get('mode') == 'mandatory'
        and heal_ability.get('trigger') == {'event': 'combo_end'}
        and heal_ability.get('active_zones') == ['battle']
        and heal_ability.get('requires_combo_use') is True
        and heal_ability.get('effects') == [{
            'op': 'change_hp', 'player': {'controller': True},
            'amount': {
                'op': 'multiply',
                'values': [
                    100, {'path': 'context.combo_total_used_count'},
                ],
            },
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'pmp-at-009', False,
                reason='피의 만찬의 토큰 비용·체력 지불·콤보 회복 형식이 일치하지 않습니다.',
            )],
            reason='PMP-AT-009 카드별 규칙 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    cost_scenarios = []
    for name, owner, spider_count, expected_legal in (
        ('owner-p1-choose-four-of-five', 'p1', 5, True),
        ('owner-p2-exact-four', 'p2', 4, True),
        ('three-tokens-illegal', 'p1', 3, False),
    ):
        first = _run_pmp_at_009_play_cost_scenario(
            definition, card_snapshot, owner, spider_count=spider_count,
        )
        second = _run_pmp_at_009_play_cost_scenario(
            definition, card_snapshot, owner, spider_count=spider_count,
        )
        deterministic = _canonical(first) == _canonical(second)
        behavior = bool(
            first['legal'] is expected_legal
            and first['wrong_token_preserved']
            and (
                not expected_legal
                or (
                    first['decision_kind'] == 'play_cost'
                    and first['decision_range'] == (4, 4)
                    and len(first['option_ids']) == spider_count
                    and first['deleted_count'] == 4
                    and len(first['remaining_spiders']) == spider_count - 4
                    and first['source_in_battle']
                )
            )
        )
        cost_scenarios.append({
            'name': name, 'passed': bool(deterministic and behavior),
            'deterministic': deterministic,
            'spider_count': spider_count, 'expected_legal': expected_legal,
            **first,
        })
    cost_passed = all(item['passed'] for item in cost_scenarios)
    cost_review = AbilityReview(
        str(function_ability.get('id')), cost_passed, cost_scenarios,
        '' if cost_passed else '거미 토큰 4장 선택 비용 검증에 실패했습니다.',
    )
    hp_scenarios = []
    for name, owner, event_type, hp, expected_after, expected_winner in (
        ('owner-p1-pays-400', 'p1', 'use', 500, 100, None),
        ('qna-627-owner-p2-loses', 'p2', 'use', 300, 0, 'p1'),
        ('wrong-trigger', 'p1', 'hit', 500, 500, None),
    ):
        first = _run_pmp_at_009_hp_cost_scenario(
            definition, card_snapshot, owner, event_type, hp=hp,
        )
        second = _run_pmp_at_009_hp_cost_scenario(
            definition, card_snapshot, owner, event_type, hp=hp,
        )
        deterministic = _canonical(first) == _canonical(second)
        hp_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['after'] == expected_after
                and first['winner'] == expected_winner
            ),
            'deterministic': deterministic,
            'event': event_type, 'expected_after': expected_after,
            'expected_winner': expected_winner, **first,
        })
    hp_passed = all(item['passed'] for item in hp_scenarios)
    hp_review = AbilityReview(
        str(hp_ability.get('id')), hp_passed, hp_scenarios,
        '' if hp_passed else 'Q&A 627 체력 지불·패배 검증에 실패했습니다.',
    )
    heal_scenarios = []
    for name, owner, combo_owner, used_count, expected_heal in (
        ('owner-p1-starter-plus-two-cards', 'p1', 'p1', 2, 300),
        ('owner-p2-starter-plus-four-cards', 'p2', 'p2', 4, 500),
        ('opponent-combo-no-heal', 'p1', 'p2', 2, 0),
    ):
        first = _run_pmp_at_009_combo_heal_scenario(
            definition, card_snapshot, owner,
            combo_owner=combo_owner, used_count=used_count,
        )
        second = _run_pmp_at_009_combo_heal_scenario(
            definition, card_snapshot, owner,
            combo_owner=combo_owner, used_count=used_count,
        )
        deterministic = _canonical(first) == _canonical(second)
        heal_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['after'] == 3000 + expected_heal
            ),
            'deterministic': deterministic,
            'used_count': used_count, 'expected_heal': expected_heal,
            **first,
        })
    heal_passed = all(item['passed'] for item in heal_scenarios)
    heal_review = AbilityReview(
        str(heal_ability.get('id')), heal_passed, heal_scenarios,
        '' if heal_passed else '콤보 사용 장수별 체력 회복 검증에 실패했습니다.',
    )
    reviewed = [cost_review, hp_review, heal_review]
    passed = all(item.passed and item.scenarios for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else 'PMP-AT-009 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_named_choice_move_scenario(
    definition, card_snapshot, owner, card_code, event_type, *,
    condition_enabled=True, candidates_enabled=True, accept=True,
    condition_non_technique=False, protected_candidate_zone=None,
    protect_after_choice=False, special_candidates=False, negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-{card_code.lower()}', 'owner': owner,
        'type': source.get('type') or '공격', 'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        f'REVIEW-{card_code}-OPPONENT', other, f'{other}-{card_code.lower()}-opponent',
    )
    state = _state(source, opposing, owner)
    expected_candidates = []
    distractors = []
    initially_protected_id = None

    if card_code == 'DFR-AT-042':
        leg = _card('REVIEW-LEG', owner, f'{owner}-leg-condition')
        leg['name'] = 'LEG CONDITION' if condition_enabled else 'BODY CONDITION'
        if condition_non_technique:
            leg.update({'type': '특성', 'non_technique_while_face_down': True})
        state['players'][owner]['zones']['lumen'] = [leg]
        if candidates_enabled:
            opposing['name'] = '상대 배틀 기술'
            if special_candidates:
                opposing['type'] = '특수 기술'
            state['players'][other]['zones']['battle'] = [copy.deepcopy(opposing)]
            lumen_target = _card(
                'REVIEW-DFR-LUMEN-TARGET', other, f'{other}-dfr-lumen-target',
            )
            if special_candidates:
                lumen_target['type'] = '특수 기술'
            state['players'][other]['zones']['lumen'] = [lumen_target]
            candidates = {
                'battle': opposing, 'lumen': lumen_target,
            }
            if protected_candidate_zone in candidates:
                initially_protected_id = candidates[
                    protected_candidate_zone
                ]['instance_id']
            expected_candidates = [
                card['instance_id'] for zone, card in candidates.items()
                if not special_candidates and zone != protected_candidate_zone
            ]
            distractors = [
                card['instance_id'] for zone, card in candidates.items()
                if special_candidates or zone == protected_candidate_zone
            ]
        else:
            non_technique = _card(
                'REVIEW-DFR-NON-TECHNIQUE', other, f'{other}-dfr-non-technique',
            )
            non_technique['type'] = '특성'
            non_technique['non_technique_while_face_down'] = True
            state['players'][other]['zones']['battle'] = [non_technique]
            state['players'][other]['zones']['lumen'] = []
            distractors = [non_technique['instance_id']]
    elif card_code == 'PMP-AT-042':
        if condition_enabled:
            state['players'][owner]['passive_state']['saintess'] = {'value': True}
        other_character = _card(
            'REVIEW-NON-LITA', owner, f'{owner}-non-lita',
        )
        other_character['character_key'] = 'rin'
        list_cards = [other_character]
        distractors = [other_character['instance_id']]
        if candidates_enabled:
            for index in range(2):
                candidate = _card(
                    f'REVIEW-LITA-{index}', owner, f'{owner}-lita-{index}',
                )
                candidate['character_key'] = 'lita'
                list_cards.append(candidate)
                expected_candidates.append(candidate['instance_id'])
        state['players'][owner]['zones']['list'] = list_cards
    elif card_code == 'RFS-AT-023':
        body = _card('REVIEW-NON-ARM', owner, f'{owner}-non-arm')
        body['name'] = 'LEG UNIT'
        lumen_cards = [body]
        distractors = [body['instance_id']]
        if condition_enabled and candidates_enabled:
            for index in range(2):
                candidate = _card(
                    f'REVIEW-ARM-{index}', owner, f'{owner}-arm-{index}',
                )
                candidate['name'] = f'ARM UNIT {index}'
                lumen_cards.append(candidate)
                expected_candidates.append(candidate['instance_id'])
        state['players'][owner]['zones']['lumen'] = lumen_cards
    else:
        raise EffectSandboxError(f'지원하지 않는 카드별 선택 검토입니다: {card_code}')

    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    protected_definition = {
        **copy.deepcopy(no_effect),
        'effect_immunity': {
            'scope': 'other_cards', 'operations': ['move_card'],
            'to_zones': ['list'],
        },
    }
    ruleset_cards = {}
    for side in ('p1', 'p2'):
        for cards in state['players'][side]['zones'].values():
            for card in cards:
                ruleset_cards[card['code']] = {
                    **copy.deepcopy(card), 'effect_definition': copy.deepcopy(no_effect),
                }
    if card_code == 'DFR-AT-042' and initially_protected_id:
        protected_card = next(
            card for zone in ('battle', 'lumen')
            for card in state['players'][other]['zones'][zone]
            if card.get('instance_id') == initially_protected_id
        )
        ruleset_cards[protected_card['code']]['effect_definition'] = (
            copy.deepcopy(protected_definition)
        )
    ruleset_cards[source['code']]['effect_definition'] = copy.deepcopy(definition)
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'{card_code}:{owner}:{event_type}:{condition_enabled}:'
            f'{candidates_enabled}:{accept}:{condition_non_technique}:'
            f'{protected_candidate_zone}:{protect_after_choice}:'
            f'{special_candidates}:{negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'], owner=owner, zone='battle')
    live_opponent = next(iter(engine._zone(other, 'battle')), None)
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': (live_opponent or {}).get('instance_id'),
            'card': copy.deepcopy(live_opponent),
        },
    }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(live_opponent),
    })
    decisions = []
    selected_ids = []
    protected_after_choice_id = None
    while engine.engine_state.get('pending_decision'):
        decision = engine.engine_state['pending_decision']
        option_ids = sorted(
            str(option.get('id')) for option in decision.get('options') or []
        )
        decisions.append({
            'kind': decision.get('kind'), 'option_ids': option_ids,
            'minimum': int(decision.get('minimum') or 0),
            'maximum': int(decision.get('maximum') or 0),
        })
        if len(decisions) > 5:
            raise EffectSandboxError(f'{card_code} 선택 단계가 5회를 초과했습니다.')
        if decision.get('kind') == 'optional_effect':
            selected = ['accept'] if accept else ['decline']
        elif option_ids:
            selected = [option_ids[0]]
            selected_ids.extend(selected)
            if card_code == 'DFR-AT-042' and protect_after_choice:
                protected_after_choice_id = selected[0]
                protected_card = engine._find_card(protected_after_choice_id)
                engine.ruleset['cards'][protected_card['code']][
                    'effect_definition'
                ] = copy.deepcopy(protected_definition)
        else:
            selected = []
        engine._submit_decision(owner, decision.get('id'), selected)
        engine._continue()

    zones = {}
    for side in ('p1', 'p2'):
        zones[side] = {
            zone: sorted(str(card.get('instance_id')) for card in engine._zone(side, zone))
            for zone in ('battle', 'hand', 'list', 'side', 'lumen', 'break')
        }
    battle_source = (engine.engine_state.get('battle') or {}).get(owner, {}).get('card') or {}
    return {
        'decisions': decisions,
        'selected_ids': selected_ids,
        'expected_candidates': sorted(expected_candidates),
        'distractors': sorted(distractors),
        'initially_protected_id': initially_protected_id,
        'protected_after_choice_id': protected_after_choice_id,
        'zones': zones,
        'skip_get': bool((engine.engine_state.get('skip_get') or {}).get(other)),
        'source_damage': engine.card_stat(live_source, 'damage', owner),
        'source_hit': battle_source.get('hit'),
        'source_counter': battle_source.get('counter'),
        'choice_skipped': sum(
            1 for event in engine.events
            if event.get('type') == 'effect_choice_skipped'
        ),
        'move_ignored': sum(
            event.get('type') == 'card_effect_ignored'
            and (event.get('payload') or {}).get('operation') == 'move_card'
            for event in engine.events
        ),
    }


def _choice_move_scenarios(
    definition, card_snapshot, card_code, specs, checker,
):
    scenarios = []
    for spec in specs:
        name, owner, event_type, condition_enabled, candidates_enabled, accept = spec
        kwargs = {
            'condition_enabled': condition_enabled,
            'candidates_enabled': candidates_enabled,
            'accept': accept,
        }
        first = _run_named_choice_move_scenario(
            definition, card_snapshot, owner, card_code, event_type, **kwargs,
        )
        second = _run_named_choice_move_scenario(
            definition, card_snapshot, owner, card_code, event_type, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        scenarios.append({
            'name': name,
            'passed': bool(deterministic and checker(name, owner, first)),
            'deterministic': deterministic,
            **first,
        })
    return scenarios


def _review_dfr_at_042_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'DFR-AT-042':
        return None
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else {}
    selection_key = 'dfr_at_042_opponent_card'
    result_key = 'dfr_at_042_moved_to_list'
    valid = bool(
        not extra_root
        and ability.get('id') == 'dfr-at-042-n1'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'hit', 'events': ['hit', 'counter']}
        and ability.get('condition') == {
            'op': 'zone_count', 'player': {'controller': True},
            'zone': 'lumen', 'min': 1,
            'where': {'name_contains': 'LEG', 'is_technique': True},
        }
        and ability.get('effects') == [{
            'op': 'request_choice', 'player': {'controller': True},
            'prompt': '리스트로 보낼 상대 배틀/루멘 존의 기술을 선택하세요.',
            'selector': {
                'kind': 'card', 'player': {'opponent': True},
                'zones': ['battle', 'lumen'], 'min': 1, 'max': 1,
                'where': {'is_technique': True},
                'as_operation': 'move_card', 'to_zone': 'list',
            },
            'selection_key': selection_key, 'default': [],
            'then': [{
                'op': 'move_card', 'selection_key': selection_key,
                'to_zone': 'list', 'result_key': result_key,
            }],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'dfr-at-042-n1', False,
                reason='LEG 기술 조건과 실제 리스트 이동 가능한 상대 기술 선택 형식이 일치하지 않습니다.',
            )], reason='DFR-AT-042 카드별 규칙 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    def checker(name, owner, result):
        other = 'p2' if owner == 'p1' else 'p1'
        if name in {
            'owner-p1-hit', 'owner-p2-counter',
            'initial-protection-excludes-battle-target',
        }:
            selected = result['selected_ids'][0] if result['selected_ids'] else None
            return bool(
                [item['kind'] for item in result['decisions']] == ['effect_choice']
                and result['decisions'][0]['option_ids'] == result['expected_candidates']
                and selected in result['zones'][other]['list']
                and all(item not in result['decisions'][0]['option_ids'] for item in result['distractors'])
            )
        if name in {'no-opponent-technique', 'special-techniques-cannot-enter-list'}:
            return not result['decisions'] and result['choice_skipped'] == 1
        if name == 'late-protection-prevents-selected-move':
            selected = result['selected_ids'][0] if result['selected_ids'] else None
            return bool(
                [item['kind'] for item in result['decisions']] == ['effect_choice']
                and result['decisions'][0]['option_ids'] == result['expected_candidates']
                and selected == result['protected_after_choice_id']
                and selected not in result['zones'][other]['list']
                and selected in (
                    result['zones'][other]['battle']
                    + result['zones'][other]['lumen']
                )
                and result['move_ignored'] == 1
            )
        return not result['decisions'] and not result['selected_ids']

    specs = (
        ('owner-p1-hit', 'p1', 'hit', {}),
        ('owner-p2-counter', 'p2', 'counter', {}),
        ('leg-condition-missing', 'p1', 'hit', {
            'condition_enabled': False,
        }),
        ('leg-name-on-non-technique-does-not-qualify', 'p2', 'counter', {
            'condition_non_technique': True,
        }),
        ('no-opponent-technique', 'p1', 'hit', {
            'candidates_enabled': False,
        }),
        ('initial-protection-excludes-battle-target', 'p2', 'counter', {
            'protected_candidate_zone': 'battle',
        }),
        ('special-techniques-cannot-enter-list', 'p1', 'hit', {
            'special_candidates': True,
        }),
        ('late-protection-prevents-selected-move', 'p1', 'counter', {
            'protect_after_choice': True,
        }),
        ('numbered-effect-negated', 'p2', 'hit', {'negated': True}),
        ('wrong-trigger', 'p1', 'use', {}),
    )
    scenarios = []
    for name, owner, event_type, kwargs in specs:
        first = _run_named_choice_move_scenario(
            definition, card_snapshot, owner, 'DFR-AT-042', event_type,
            **kwargs,
        )
        second = _run_named_choice_move_scenario(
            definition, card_snapshot, owner, 'DFR-AT-042', event_type,
            **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        scenarios.append({
            'name': name,
            'passed': bool(deterministic and checker(name, owner, first)),
            'deterministic': deterministic,
            **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            str(ability.get('id')), passed, scenarios,
            '' if passed else '그라인드 프레스 대상 선택 검증에 실패했습니다.',
        )], '' if passed else 'DFR-AT-042 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _review_pmp_at_042_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'PMP-AT-042':
        return None
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else {}
    selection_key = 'pmp_at_042_lita_card'
    valid = bool(
        not extra_root
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == [589, 621]
        and ability.get('id') == 'pmp-at-042-n1'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'hit', 'events': ['hit', 'counter']}
        and ability.get('condition') == {
            'op': 'has_state', 'player': {'controller': True}, 'state': 'saintess',
        }
        and ability.get('effects') == [{
            'op': 'request_choice', 'player': {'controller': True},
            'prompt': '획득할 리타 기술을 선택하세요.',
            'selector': {
                'kind': 'card', 'player': {'controller': True},
                'zones': ['list'], 'min': 1, 'max': 1,
                'where': {'character_key': 'lita', 'is_technique': True},
            },
            'selection_key': selection_key, 'default': [],
            'then': [
                {
                    'op': 'move_card', 'selection_key': selection_key,
                    'to_zone': 'hand',
                },
                {'op': 'skip_get', 'player': {'opponent': True}},
            ],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'pmp-at-042-n1', False,
                reason='리타 획득과 상대 Get 스킵의 원자적 선택 형식이 일치하지 않습니다.',
            )], reason='PMP-AT-042 카드별 규칙 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    def checker(name, owner, result):
        other = 'p2' if owner == 'p1' else 'p1'
        if name in {'owner-p1-hit', 'owner-p2-counter'}:
            selected = result['selected_ids'][0] if result['selected_ids'] else None
            return bool(
                [item['kind'] for item in result['decisions']] == ['effect_choice']
                and result['decisions'][0]['option_ids'] == result['expected_candidates']
                and selected in result['zones'][owner]['hand']
                and result['skip_get']
                and all(item not in result['decisions'][0]['option_ids'] for item in result['distractors'])
                and other in {'p1', 'p2'}
            )
        if name == 'no-lita-candidate':
            return bool(
                not result['decisions'] and result['choice_skipped'] == 1
                and not result['skip_get']
            )
        return not result['decisions'] and not result['skip_get']

    scenarios = _choice_move_scenarios(
        definition, card_snapshot, 'PMP-AT-042', (
            ('owner-p1-hit', 'p1', 'hit', True, True, True),
            ('owner-p2-counter', 'p2', 'counter', True, True, True),
            ('saintess-missing', 'p1', 'hit', False, True, True),
            ('no-lita-candidate', 'p1', 'hit', True, False, True),
            ('wrong-trigger', 'p1', 'use', True, True, True),
        ), checker,
    )
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            str(ability.get('id')), passed, scenarios,
            '' if passed else '블레싱 윙크 획득·Get 스킵 검증에 실패했습니다.',
        )], '' if passed else 'PMP-AT-042 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _review_rfs_at_023_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'RFS-AT-023':
        return None
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else {}
    selection_key = 'rfs_at_023_arm_card'
    valid = bool(
        not extra_root
        and ability.get('id') == 'rfs-at-023-n1'
        and ability.get('mode') == 'optional'
        and ability.get('recheck_condition') is True
        and ability.get('trigger') == {'event': 'hit', 'events': ['hit', 'counter']}
        and ability.get('condition') == {
            'op': 'zone_count', 'player': {'controller': True},
            'zone': 'lumen', 'min': 1, 'where': {'name_contains': 'ARM'},
        }
        and ability.get('effects') == [{
            'op': 'request_choice', 'player': {'controller': True},
            'prompt': '사이드 덱으로 보낼 ARM 기술을 선택하세요.',
            'selector': {
                'kind': 'card', 'player': {'controller': True},
                'zones': ['lumen'], 'min': 1, 'max': 1,
                'where': {'name_contains': 'ARM', 'is_technique': True},
            },
            'selection_key': selection_key, 'default': [],
            'then': [
                {
                    'op': 'move_card', 'selection_key': selection_key,
                    'to_zone': 'side',
                },
                {
                    'op': 'modify_judgment', 'player': {'controller': True},
                    'field': 'hit', 'value': '콤보',
                },
                {
                    'op': 'modify_judgment', 'player': {'controller': True},
                    'field': 'counter', 'value': '콤보',
                },
                {
                    'op': 'modify_stat', 'player': {'controller': True},
                    'stat': 'damage', 'amount': 200, 'duration': 'battle',
                },
            ],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'rfs-at-023-n1', False,
                reason='ARM 이동과 판정·데미지 후속 처리 형식이 일치하지 않습니다.',
            )], reason='RFS-AT-023 카드별 규칙 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    base_damage = int(_sandbox_source_snapshot(card_snapshot).get('damage') or 0)

    def checker(name, owner, result):
        if name in {'owner-p1-accepts', 'owner-p2-accepts'}:
            selected = result['selected_ids'][0] if result['selected_ids'] else None
            return bool(
                [item['kind'] for item in result['decisions']]
                == ['optional_effect', 'effect_choice']
                and result['decisions'][1]['option_ids'] == result['expected_candidates']
                and selected in result['zones'][owner]['side']
                and result['source_hit'] == '콤보'
                and result['source_counter'] == '콤보'
                and result['source_damage'] == base_damage + 200
                and all(item not in result['decisions'][1]['option_ids'] for item in result['distractors'])
            )
        if name == 'declined':
            return bool(
                [item['kind'] for item in result['decisions']] == ['optional_effect']
                and not result['selected_ids']
                and result['source_damage'] == base_damage
                and result['source_hit'] != '콤보'
            )
        return not result['decisions'] and result['source_damage'] == base_damage

    scenarios = _choice_move_scenarios(
        definition, card_snapshot, 'RFS-AT-023', (
            ('owner-p1-accepts', 'p1', 'hit', True, True, True),
            ('owner-p2-accepts', 'p2', 'counter', True, True, True),
            ('declined', 'p1', 'hit', True, True, False),
            ('no-arm-candidate', 'p1', 'hit', False, False, True),
            ('wrong-trigger', 'p1', 'use', True, True, True),
        ), checker,
    )
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            str(ability.get('id')), passed, scenarios,
            '' if passed else '히트 매니퓰레이터 선택·후속 변경 검증에 실패했습니다.',
        )], '' if passed else 'RFS-AT-023 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_conditional_break_followup_scenario(
    definition, card_snapshot, owner, card_code, event_type, *,
    condition_enabled=True, candidate_count=1, blocked=False, accept=True,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-{card_code.lower()}', 'owner': owner,
        'type': source.get('type') or '공격', 'face_up': True,
    })
    opposing = _card(
        f'REVIEW-{card_code}-OPPONENT', other,
        f'{other}-{card_code.lower()}-opponent',
    )
    state = _state(source, opposing, owner)
    targets = []
    for index in range(candidate_count):
        target = _card(
            f'REVIEW-{card_code}-TARGET-{index}', owner,
            f'{owner}-{card_code.lower()}-target-{index}',
        )
        targets.append(target)
    state['players'][owner]['zones']['list'] = copy.deepcopy(targets)
    daggers = []
    if card_code == 'CB01-AT-023':
        for index in range(max(1, candidate_count)):
            token = _card(
                f'REVIEW-DAGGER-{index}', owner, f'{owner}-dagger-{index}',
            )
            token.update({
                'name': f'단검 토큰 {index}', 'type': '토큰',
                'token_key': 'dagger',
            })
            daggers.append(token)
        state['players'][owner]['zones']['side'] = copy.deepcopy(daggers)
    elif card_code == 'LMI-AT-038':
        if condition_enabled:
            state['players'][owner]['passive_state']['dark_night'] = {'value': True}
    else:
        raise EffectSandboxError(f'지원하지 않는 브레이크 후속 검토입니다: {card_code}')

    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    ruleset_cards = {}
    for side in ('p1', 'p2'):
        for cards in state['players'][side]['zones'].values():
            for card in cards:
                ruleset_cards[card['code']] = {
                    **copy.deepcopy(card), 'effect_definition': copy.deepcopy(no_effect),
                }
    ruleset_cards[source['code']]['effect_definition'] = copy.deepcopy(definition)
    if blocked and targets:
        ruleset_cards[targets[0]['code']]['effect_definition'] = {
            **copy.deepcopy(no_effect),
            'break_rules': {'forbidden_zones': ['list']},
        }
    state['players'][other]['hp'] = 1000
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'{card_code}:{owner}:{event_type}:{condition_enabled}:'
            f'{candidate_count}:{blocked}:{accept}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if card_code == 'LMI-AT-038':
        engine.engine_state['combo'] = {
            'owner': owner, 'source': source['instance_id'],
            'used': [source['instance_id']], 'next_penalty': 200,
        }
    live_source = engine._find_card(source['instance_id'], owner=owner, zone='battle')
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'combo': event_type == 'combo', 'combo_number': 2,
    })
    decisions = []
    while engine.engine_state.get('pending_decision'):
        decision = engine.engine_state['pending_decision']
        option_ids = sorted(
            str(option.get('id')) for option in decision.get('options') or []
        )
        decisions.append({
            'kind': decision.get('kind'), 'option_ids': option_ids,
            'minimum': int(decision.get('minimum') or 0),
            'maximum': int(decision.get('maximum') or 0),
        })
        if len(decisions) > 6:
            raise EffectSandboxError(f'{card_code} 선택 단계가 6회를 초과했습니다.')
        if decision.get('kind') == 'optional_effect':
            selected = ['accept'] if accept else ['decline']
        elif decision.get('kind') == 'break_replenish':
            selected = ['decline']
        else:
            selected = option_ids[:1]
        engine._submit_decision(owner, decision.get('id'), selected)
        engine._continue()
    return {
        'decisions': decisions,
        'target_ids': sorted(card['instance_id'] for card in targets),
        'dagger_ids': sorted(card['instance_id'] for card in daggers),
        'list_ids': sorted(card['instance_id'] for card in engine._zone(owner, 'list')),
        'break_ids': sorted(card['instance_id'] for card in engine._zone(owner, 'break')),
        'side_ids': sorted(card['instance_id'] for card in engine._zone(owner, 'side')),
        'lumen_ids': sorted(card['instance_id'] for card in engine._zone(owner, 'lumen')),
        'opponent_hp': engine.state['players'][other]['hp'],
        'combo_active': bool(engine.engine_state.get('combo')),
        'choice_skipped': sum(
            1 for event in engine.events if event.get('type') == 'effect_choice_skipped'
        ),
        'break_prevented': sum(
            1 for event in engine.events if event.get('type') == 'card_break_prevented'
        ),
    }


def _review_cb01_at_023_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-023':
        return None
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else {}
    selection_key = 'cb01_at_023_break_target'
    result_key = 'cb01_at_023_broken'
    token_key = 'cb01_at_023_dagger'
    expected_effects = [{
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '브레이크할 리스트의 기술을 선택하세요.',
        'selector': {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['list'], 'min': 1, 'max': 1,
            'where': {'is_technique': True},
            'as_operation': 'break_card', 'include_operation_blocked': True,
        },
        'selection_key': selection_key, 'default': [],
        'then': [
            {
                'op': 'break_card', 'selection_key': selection_key,
                'result_key': result_key,
            },
            {
                'op': 'conditional',
                'condition': {
                    'op': 'gte',
                    'left': {
                        'op': 'selection_count', 'selection_key': result_key,
                    },
                    'right': 1,
                },
                'then': [{
                    'op': 'request_choice', 'player': {'controller': True},
                    'prompt': '루멘 존에 배치할 단검 토큰을 선택하세요.',
                    'selector': {
                        'kind': 'card', 'player': {'controller': True},
                        'zones': ['side'], 'min': 1, 'max': 1,
                        'where': {'token_key': 'dagger'},
                    },
                    'selection_key': token_key, 'default': [],
                    'then': [{
                        'op': 'move_card', 'selection_key': token_key,
                        'to_zone': 'lumen',
                    }],
                }],
            },
        ],
    }]
    valid = bool(
        not extra_root
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or []) == [197]
        and ability.get('id') == 'cb01-at-023-n1'
        and ability.get('mode') == 'optional'
        and ability.get('recheck_condition') is True
        and ability.get('trigger') == {'event': 'hit', 'events': ['hit', 'counter']}
        and ability.get('condition') == {
            'op': 'zone_count', 'player': {'controller': True},
            'zone': 'list', 'min': 1, 'where': {'is_technique': True},
        }
        and ability.get('effects') == expected_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb01-at-023-n1', False,
                reason='실제 브레이크 성공 후 단검을 배치하는 형식이 일치하지 않습니다.',
            )], reason='CB01-AT-023 카드별 규칙 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    specs = (
        ('owner-p1-hit', 'p1', 'hit', True, 1, False, True),
        ('owner-p2-counter-two-options', 'p2', 'counter', True, 2, False, True),
        ('optional-declined', 'p1', 'hit', True, 1, False, False),
        ('qna-197-break-prevented', 'p1', 'hit', True, 1, True, True),
        ('no-list-candidate', 'p1', 'hit', True, 0, False, True),
        ('wrong-trigger', 'p1', 'use', True, 1, False, True),
    )
    scenarios = []
    for name, owner, event_type, condition_enabled, count, blocked, accept in specs:
        kwargs = {
            'condition_enabled': condition_enabled, 'candidate_count': count,
            'blocked': blocked, 'accept': accept,
        }
        first = _run_conditional_break_followup_scenario(
            definition, card_snapshot, owner, 'CB01-AT-023', event_type, **kwargs,
        )
        second = _run_conditional_break_followup_scenario(
            definition, card_snapshot, owner, 'CB01-AT-023', event_type, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        kinds = [item['kind'] for item in first['decisions']]
        if name in {'owner-p1-hit', 'owner-p2-counter-two-options'}:
            behavior = bool(
                kinds == ['optional_effect', 'effect_choice', 'effect_choice']
                and first['decisions'][1]['option_ids'] == first['target_ids']
                and first['decisions'][2]['option_ids'] == first['dagger_ids']
                and len(first['break_ids']) == 1 and len(first['lumen_ids']) == 1
            )
        elif name == 'optional-declined':
            behavior = kinds == ['optional_effect'] and not first['break_ids'] and not first['lumen_ids']
        elif name == 'qna-197-break-prevented':
            behavior = bool(
                kinds == ['optional_effect', 'effect_choice']
                and first['decisions'][1]['option_ids'] == first['target_ids']
                and first['target_ids'][0] in first['list_ids']
                and not first['lumen_ids'] and first['break_prevented'] == 1
            )
        else:
            behavior = not kinds and not first['break_ids'] and not first['lumen_ids']
        scenarios.append({
            'name': name, 'passed': bool(deterministic and behavior),
            'deterministic': deterministic, **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            str(ability.get('id')), passed, scenarios,
            '' if passed else '코르부스 선택·Q&A 197 검증에 실패했습니다.',
        )], '' if passed else 'CB01-AT-023 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


