def _run_owner_direct_break_scenario(definition, card_snapshot, owner, mode):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-owner-direct-guard', 'owner': owner,
        'type': '수비', 'face_up': True,
    })
    opposing = _card('REVIEW-OPPONENT', other, f'{other}-break-source')
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = []
    ruleset = {
        'version': AUTOMATIC_SCENARIO_VERSION,
        'cards': {
            source['code']: {**copy.deepcopy(source), 'effect_definition': isolated},
            opposing['code']: {
                **copy.deepcopy(opposing),
                'effect_definition': {
                    'schema_version': 1, 'reviewed': True, 'no_effect': True,
                    'source_refs': {'rulebook_pages': [], 'qna_ids': []},
                    'abilities': [],
                },
            },
        },
    }
    source_zone = 'battle' if mode == 'defense_over' else 'list'
    engine = AutomaticGameEngine(
        _state(source, opposing, owner, source_zone=source_zone), ruleset,
        seed=f'owner-direct-break:{source["code"]}:{owner}:{mode}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if mode == 'owner_direct':
        engine.break_card(
            source['instance_id'], reason='owner_direct_test',
            direct_controller=owner,
        )
    elif mode == 'opponent_effect':
        engine.break_card(
            source['instance_id'], reason='opponent_effect_test',
            effect_controller=other, effect_source=opposing['instance_id'],
        )
    else:
        engine._advance_cleanup_pipeline({
            'kind': 'battle_cleanup', 'stage': 'cards',
            'defense_over': True,
            'used_order': [(owner, source['instance_id'], 'hand')],
            'index': 0,
        })
    location = next(
        (
            zone for zone in ('battle', 'list', 'break', 'hand')
            if engine._find_card(source['instance_id'], owner=owner, zone=zone)
        ),
        None,
    )
    return {
        'zone': location,
        'prevented': any(
            event.get('type') == 'card_break_prevented'
            and (event.get('payload') or {}).get('card_instance_id')
            == source['instance_id']
            for event in engine.events
        ),
        'broken': any(
            event.get('type') == 'card_broken'
            and (event.get('payload') or {}).get('card_instance_id')
            == source['instance_id']
            for event in engine.events
        ),
    }


def _review_owner_direct_break_definition(
    definition, card_snapshot, extra_root,
):
    code = str((card_snapshot or {}).get('code') or '')
    if code not in ST1_GUARD_QNA_IDS:
        return None
    expected_qna_ids = ST1_GUARD_QNA_IDS[code]
    text = _normalized_rule_text((card_snapshot or {}).get('text') or '')
    root_abilities = [
        ability for ability in definition.get('abilities') or []
        if _normalized_rule_text(
            ability.get('draft_text') or ability.get('label') or '',
        ) == '이 기술은 자신이 직접 브레이크할 수 없다.'
    ]
    root_ability = root_abilities[0] if len(root_abilities) == 1 else None
    valid = bool(
        extra_root == {'break_rules'}
        and definition.get('break_rules') == {
            'preventions': [{'scope': 'owner_direct'}],
        }
        and '이 기술은 자신이 직접 브레이크할 수 없다.' in text
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == expected_qna_ids
        and root_ability
        and root_ability.get('kind') == 'function'
        and root_ability.get('mode') == 'continuous'
        and root_ability.get('effects') == [{
            'op': 'static_rule', 'rules': ['break_rules'],
        }]
        and sorted(
            (root_ability.get('source_refs') or {}).get('qna_ids') or []
        ) == expected_qna_ids
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                (
                    root_ability.get('id') if root_ability
                    else f'{code.lower()}-function'
                ), False,
                reason='가드의 직접 브레이크 금지 규칙·Q&A 출처가 일치하지 않습니다.',
            )],
            reason='브레이크 규칙이 카드 원문과 일치하지 않습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    specs = (
        ('owner-p1-direct-prevented', 'p1', 'owner_direct', 'list', True, False),
        ('owner-p2-direct-prevented', 'p2', 'owner_direct', 'list', True, False),
        ('opponent-effect-allowed', 'p1', 'opponent_effect', 'break', False, True),
        ('qna-569-defense-over-allowed', 'p1', 'defense_over', 'break', False, True),
    )
    scenarios = []
    for name, owner, mode, zone, prevented, broken in specs:
        first = _run_owner_direct_break_scenario(
            definition, card_snapshot, owner, mode,
        )
        second = _run_owner_direct_break_scenario(
            definition, card_snapshot, owner, mode,
        )
        deterministic = _canonical(first) == _canonical(second)
        passed = bool(
            deterministic and first['zone'] == zone
            and first['prevented'] is prevented and first['broken'] is broken
        )
        scenarios.append({
            'name': name, 'passed': passed, 'deterministic': deterministic,
            'mode': mode, 'expected_zone': zone,
            'expected_prevented': prevented, 'expected_broken': broken,
            **first,
        })
    root_review = AbilityReview(
        root_ability['id'],
        all(item['passed'] for item in scenarios), scenarios,
        '' if all(item['passed'] for item in scenarios)
        else '직접 브레이크 및 디펜스 오버 검증에 실패했습니다.',
    )
    reviewed = [root_review]
    reviewed.extend(
        _review_other_ability(definition, ability, card_snapshot)
        for ability in definition.get('abilities') or []
        if ability is not root_ability
    )
    passed = all(item.scenarios and item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '가드의 브레이크·효과 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st1_guard_self_damage_fixture(definition, ability, card_snapshot):
    code = str((card_snapshot or {}).get('code') or '')
    if code not in ST1_GUARD_QNA_IDS:
        return None
    source_text = _normalized_rule_text(
        ability.get('draft_text') or ability.get('label') or '',
    )
    if source_text != _normalized_rule_text('방어 시, 자신은 200데미지를 받는다.'):
        return None
    expected_qna_ids = ST1_GUARD_QNA_IDS[code]
    valid = bool(
        sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == expected_qna_ids
        and sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
        == expected_qna_ids
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'guard'}
        and ability.get('effects') == [{
            'op': 'deal_damage', 'player': {'controller': True}, 'amount': 200,
        }]
    )
    return {'valid': valid, 'code': code}


def _run_st1_guard_self_damage_scenario(
    definition, ability, card_snapshot, owner, event_type, *,
    damage_reduction=False, opponent_howling=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-self-damage-guard', 'owner': owner,
        'type': '수비', 'face_up': True,
    })
    opposing = _card('REVIEW-OPPONENT', other, f'{other}-opponent')
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    ruleset_cards = {
        source['code']: {**copy.deepcopy(source), 'effect_definition': isolated},
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    supports = []
    if damage_reduction:
        reduction = _sandbox_source_snapshot({
            'code': 'LMI-QNA-221-GUARD', 'name': '피해 감소', 'type': '특수',
        })
        reduction.update({
            'instance_id': f'{owner}-guard-reduction', 'owner': owner,
            'face_up': True,
        })
        ruleset_cards[reduction['code']] = {
            **copy.deepcopy(reduction),
            'effect_definition': _st5_003_support_definition('damage_reduction'),
        }
        supports.append((owner, 'lumen', reduction))
    if opponent_howling:
        howling = _sandbox_source_snapshot({
            'code': 'ST5-QNA-175-GUARD', 'name': '상대 하울링', 'type': '패시브',
        })
        howling.update({
            'instance_id': f'{other}-guard-howling', 'owner': other,
            'face_up': True,
        })
        ruleset_cards[howling['code']] = {
            **copy.deepcopy(howling),
            'effect_definition': _st5_003_support_definition('howling'),
        }
        supports.append((other, 'passive', howling))
    state = _state(source, opposing, owner)
    for side, zone, support in supports:
        state['players'][side]['zones'][zone].append(copy.deepcopy(support))
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'guard-self-damage:{source["code"]}:{owner}:{event_type}:'
            f'{damage_reduction}:{opponent_howling}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._refresh_continuous_rules()
    before = engine.state['players'][owner]['hp']
    engine._fire(event_type, {
        'controller': owner,
        'source_card': engine._find_card(source['instance_id']),
        'source_card_instance_id': source['instance_id'],
        'opponent_card': engine._find_card(opposing['instance_id']),
    })
    amounts = [
        (event.get('payload') or {}).get('amount')
        for event in engine.events
        if event.get('type') == 'damage_dealt'
        and (event.get('payload') or {}).get('target') == owner
    ]
    return {
        'before': before, 'after': engine.state['players'][owner]['hp'],
        'damage_amounts': amounts,
        'opponent_howling': (
            engine.state['players'][other].get('passive_state', {})
            .get('howling', {}).get('count', 0)
        ),
    }


def _review_st1_guard_self_damage_ability(
    definition, ability, card_snapshot,
):
    fixture = _st1_guard_self_damage_fixture(
        definition, ability, card_snapshot,
    )
    if fixture is None:
        return None
    ability_id = str(ability.get('id') or 'st1-guard-self-damage')
    if not fixture['valid']:
        return AbilityReview(
            ability_id, False,
            reason='가드 자해 데미지의 원문·Q&A·명령이 일치하지 않습니다.',
        )
    specs = (
        ('owner-p1-self-damage', 'p1', 'guard', False, False, [200], 0),
        ('owner-p2-self-damage', 'p2', 'guard', False, False, [200], 0),
        ('qna-221-damage-reduction', 'p1', 'guard', True, False, [100], 0),
        ('qna-175-no-opponent-howling', 'p1', 'guard', False, True, [200], 0),
        ('wrong-trigger', 'p1', 'dodge', False, True, [], 0),
    )
    scenarios = []
    for name, owner, event_type, reduction, howling, amounts, counter in specs:
        first = _run_st1_guard_self_damage_scenario(
            definition, ability, card_snapshot, owner, event_type,
            damage_reduction=reduction, opponent_howling=howling,
        )
        second = _run_st1_guard_self_damage_scenario(
            definition, ability, card_snapshot, owner, event_type,
            damage_reduction=reduction, opponent_howling=howling,
        )
        deterministic = _canonical(first) == _canonical(second)
        passed = bool(
            deterministic and first['damage_amounts'] == amounts
            and first['after'] == first['before'] - sum(amounts)
            and first['opponent_howling'] == counter
        )
        scenarios.append({
            'name': name, 'passed': passed, 'deterministic': deterministic,
            'event': event_type, 'damage_reduction': reduction,
            'opponent_howling_enabled': howling,
            'expected_damage_amounts': amounts,
            'expected_opponent_howling': counter, **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return AbilityReview(
        ability_id, passed, scenarios,
        '' if passed else '가드 자해 데미지 Q&A 검증에 실패했습니다.',
    )


def _st1_012_dodge_fp_fixture(definition, ability, card_snapshot):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-012':
        return None
    source_text = _normalized_rule_text(
        ability.get('draft_text') or ability.get('label') or '',
    )
    if source_text != _normalized_rule_text(
        '회피 시, 상대 기술 속도-3 만큼 FP를 얻는다.(최대 9FP)',
    ):
        return None
    qna_ids = ST1_GUARD_QNA_IDS['ST1-012']
    expected_amount = {
        'op': 'clamp',
        'value': {
            'op': 'subtract',
            'left': {'path': 'context.opponent_speed'}, 'right': 3,
        },
        'min': 0, 'max': 9,
    }
    valid = bool(
        sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'dodge'}
        and ability.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True},
            'amount': expected_amount,
        }]
    )
    return {'valid': valid}


def _run_st1_012_dodge_fp_scenario(
    definition, ability, card_snapshot, owner, event_type, *,
    opponent_speed, opponent_dodge_bonus=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-down-guard', 'owner': owner,
        'type': '수비', 'face_up': True,
    })
    opposing = _card('REVIEW-OPPONENT', other, f'{other}-dodge-opponent')
    opposing['frame'] = opponent_speed
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    opposing_definition = {
        'schema_version': 1, 'reviewed': True,
        'no_effect': opponent_dodge_bonus <= 0,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []},
        'abilities': [],
    }
    if opponent_dodge_bonus > 0:
        opposing_definition['no_effect'] = False
        opposing_definition['abilities'] = [{
            'id': 'opponent-dodge-fp-fixture',
            'kind': 'effect', 'mode': 'mandatory', 'timing': 'dodge',
            'visibility': 'public', 'active_zones': ['battle'],
            'source_refs': {'rulebook_pages': [], 'qna_ids': []},
            'trigger': {'event': 'opponent_dodge'},
            'effects': [{
                'op': 'change_fp', 'player': {'opponent': True},
                'amount': opponent_dodge_bonus,
            }],
        }]
    ruleset = {
        'version': AUTOMATIC_SCENARIO_VERSION,
        'cards': {
            source['code']: {**copy.deepcopy(source), 'effect_definition': isolated},
            opposing['code']: {
                **copy.deepcopy(opposing),
                'effect_definition': opposing_definition,
            },
        },
    }
    engine = AutomaticGameEngine(
        _state(source, opposing, owner), ruleset,
        seed=(
            f'down-guard-fp:{owner}:{event_type}:{opponent_speed}:'
            f'{opponent_dodge_bonus}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    before = engine.state['players'][owner]['fp']
    context = {
        'controller': owner, 'opponent_speed': opponent_speed,
        'source_card': engine._find_card(source['instance_id']),
        'source_card_instance_id': source['instance_id'],
        'opponent_card': engine._find_card(opposing['instance_id']),
    }
    engine._fire(event_type, context)
    after_dodge = engine.state['players'][owner]['fp']
    if event_type == 'dodge' and opponent_dodge_bonus > 0:
        # ``opponent_dodge`` belongs to the opposing Technique that was
        # dodged, not to the Defense Technique that produced ``dodge``.
        engine._fire('opponent_dodge', {
            'controller': other, 'opponent_speed': opponent_speed,
            'source_card': engine._find_card(opposing['instance_id']),
            'source_card_instance_id': opposing['instance_id'],
            'opponent_card': engine._find_card(source['instance_id']),
        })
    return {
        'before': before, 'after_dodge': after_dodge,
        'after_opponent_dodge': engine.state['players'][owner]['fp'],
    }


def _fp_catch_owner(p1_fp, p2_fp):
    # This helper verifies the FP boundary itself, independently of whether
    # the sandbox happens to contain a legal Catch card. Production now skips
    # an otherwise valid Catch window immediately when there is no candidate.
    if p1_fp > 0 and p2_fp == 0:
        return 'p1'
    if p2_fp > 0 and p1_fp == 0:
        return 'p2'
    if p1_fp == 0 and p2_fp < 0:
        return 'p1'
    if p2_fp == 0 and p1_fp < 0:
        return 'p2'
    return None


def _run_down_stance_qna_146(card_snapshot, owner, *, top_result='회피'):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-down-stance-defense', 'owner': owner,
        'kind': 'card', 'type': '수비', 'g_top': top_result, 'face_up': True,
    })
    opposing = _card('REVIEW-OPPONENT', other, f'{other}-stance-opponent')
    passive = _sandbox_source_snapshot({
        'code': 'ST3-PS1-QNA-146', 'name': '다운 스탠스 특성', 'type': '패시브',
    })
    passive.update({
        'instance_id': f'{owner}-down-stance-passive', 'owner': owner,
        'face_up': True,
    })
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    passive_definition = {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [146]},
        'abilities': [{
            'id': 'qna-146-defense-down-stance',
            'kind': 'function', 'mode': 'mandatory', 'timing': 'after_use',
            'visibility': 'public', 'active_zones': ['passive'],
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [146]},
            'trigger': {'event': 'after_use'},
            'condition': {
                'op': 'card_matches',
                'card': {'path': 'context.event_printed_card'},
                'where': {
                    'kind': 'card', 'type_contains': '수비', 'g_top': '회피',
                },
            },
            'effects': [{
                'op': 'gain_state', 'player': {'controller': True},
                'state': 'down_stance',
            }],
        }],
    }
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['passive'].append(copy.deepcopy(passive))
    engine = AutomaticGameEngine(
        state, {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {**copy.deepcopy(source), 'effect_definition': no_effect},
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
                passive['code']: {
                    **copy.deepcopy(passive),
                    'effect_definition': passive_definition,
                },
            },
        },
        seed=f'qna-146:{source["code"]}:{owner}:{top_result}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._fire('after_use', {
        'controller': owner,
        'source_card': engine._find_card(source['instance_id']),
        'source_card_instance_id': source['instance_id'],
    })
    return bool(
        engine.state['players'][owner].get('passive_state', {})
        .get('down_stance', {}).get('value')
    )


def _review_st1_012_dodge_fp_ability(
    definition, ability, card_snapshot,
):
    fixture = _st1_012_dodge_fp_fixture(
        definition, ability, card_snapshot,
    )
    if fixture is None:
        return None
    ability_id = str(ability.get('id') or 'st1-012-dodge-fp')
    if not fixture['valid']:
        return AbilityReview(
            ability_id, False,
            reason='다운 가드의 속도 비례 FP 명령·Q&A가 일치하지 않습니다.',
        )
    specs = (
        ('qna-165-own-then-opponent', 'p1', 'dodge', 7, 3, 4, 7),
        ('owner-p2-maximum-nine', 'p2', 'dodge', 15, 0, 9, 9),
        ('qna-662-minimum-zero', 'p1', 'dodge', 2, 0, 0, 0),
        ('qna-435-zero-then-nine', 'p1', 'dodge', 0, 9, 0, 9),
        ('wrong-trigger', 'p1', 'guard', 7, 0, 0, 0),
    )
    scenarios = []
    for name, owner, event_type, speed, bonus, own_gain, total_gain in specs:
        first = _run_st1_012_dodge_fp_scenario(
            definition, ability, card_snapshot, owner, event_type,
            opponent_speed=speed, opponent_dodge_bonus=bonus,
        )
        second = _run_st1_012_dodge_fp_scenario(
            definition, ability, card_snapshot, owner, event_type,
            opponent_speed=speed, opponent_dodge_bonus=bonus,
        )
        deterministic = _canonical(first) == _canonical(second)
        passed = bool(
            deterministic
            and first['after_dodge'] == first['before'] + own_gain
            and first['after_opponent_dodge'] == first['before'] + total_gain
        )
        scenarios.append({
            'name': name, 'passed': passed, 'deterministic': deterministic,
            'event': event_type, 'opponent_speed': speed,
            'opponent_dodge_bonus': bonus, 'expected_own_gain': own_gain,
            'expected_total_gain': total_gain, **first,
        })
    no_catch_first = _fp_catch_owner(3, 4)
    no_catch_second = _fp_catch_owner(3, 4)
    catch_first = _fp_catch_owner(3, 0)
    catch_second = _fp_catch_owner(3, 0)
    scenarios.append({
        'name': 'qna-391-catch-requires-zero-fp',
        'passed': bool(
            no_catch_first is None and no_catch_second is None
            and catch_first == 'p1' and catch_second == 'p1'
        ),
        'deterministic': (
            no_catch_first == no_catch_second and catch_first == catch_second
        ),
        'both_nonzero_catch_owner': no_catch_first,
        'opponent_zero_catch_owner': catch_first,
    })
    stance_p1 = _run_down_stance_qna_146(card_snapshot, 'p1')
    stance_p2 = _run_down_stance_qna_146(card_snapshot, 'p2')
    non_dodge = _run_down_stance_qna_146(
        card_snapshot, 'p1', top_result='방어',
    )
    scenarios.append({
        'name': 'qna-146-defense-dodge-enters-down-stance',
        'passed': stance_p1 and stance_p2 and not non_dodge,
        'deterministic': True,
        'owner_p1_down_stance': stance_p1,
        'owner_p2_down_stance': stance_p2,
        'non_dodge_down_stance': non_dodge,
    })
    passed = all(item['passed'] for item in scenarios)
    return AbilityReview(
        ability_id, passed, scenarios,
        '' if passed else '다운 가드 FP·캐치 Q&A 검증에 실패했습니다.',
    )


def _review_st1_014_dodge_fp_ability(definition, ability, card_snapshot):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-014':
        return None
    qna_ids = [69, 655, 656]
    expected_amount = {
        'op': 'clamp',
        'value': {
            'op': 'subtract',
            'left': {'path': 'context.opponent_speed'}, 'right': 2,
        },
        'min': 0, 'max': 8,
    }
    valid = bool(
        _normalized_rule_text(
            ability.get('draft_text') or ability.get('label') or '',
        ) == '회피 시, 상대의 기술 속도-2만큼 FP를 얻는다.(최대 8FP)'
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'dodge'}
        and ability.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True},
            'amount': expected_amount,
        }]
    )
    ability_id = str(ability.get('id') or 'st1-014-n1')
    if not valid:
        return AbilityReview(
            ability_id, False,
            reason='점프의 속도 비례 FP 명령·Q&A 출처가 일치하지 않습니다.',
        )
    specs = (
        ('qna-655-speed-eight-gains-six', 'p1', 'dodge', 8, 6),
        ('owner-p2-maximum-eight', 'p2', 'dodge', 15, 8),
        ('minimum-zero', 'p1', 'dodge', 2, 0),
        ('wrong-trigger', 'p1', 'guard', 8, 0),
    )
    scenarios = []
    for name, owner, event_type, speed, gain in specs:
        first = _run_st1_012_dodge_fp_scenario(
            definition, ability, card_snapshot, owner, event_type,
            opponent_speed=speed,
        )
        second = _run_st1_012_dodge_fp_scenario(
            definition, ability, card_snapshot, owner, event_type,
            opponent_speed=speed,
        )
        deterministic = _canonical(first) == _canonical(second)
        scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['after_dodge'] == first['before'] + gain
                and first['after_opponent_dodge'] == first['before'] + gain
            ),
            'deterministic': deterministic, 'event': event_type,
            'opponent_speed': speed, 'expected_gain': gain, **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return AbilityReview(
        ability_id, passed, scenarios,
        '' if passed else '점프의 FP 최소·최대·Q&A 655 검증에 실패했습니다.',
    )


def _run_st1_014_break_scenario(
    definition, ability, card_snapshot, owner, *,
    opponent_has_grab=True, opponent_protected=False, grab_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-jump', 'owner': owner,
        'kind': 'card', 'type': '수비', 'face_up': True,
    })
    opposing = _card('REVIEW-JUMP-OPPONENT', other, f'{other}-jump-opponent')
    opposing['special'] = '그랩' if opponent_has_grab else ''
    breaker = _card('REVIEW-JUMP-NEGATION', owner, f'{owner}-hand-grab')
    breaker['special'] = '그랩'
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    opposing_definition = copy.deepcopy(no_effect)
    if opponent_protected:
        opposing_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [656]},
            'abilities': [{
                'id': 'review-jump-break-immunity', 'kind': 'function',
                'mode': 'continuous', 'timing': 'function',
                'visibility': 'public',
                'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [656]},
                'effects': [{'op': 'static_rule', 'rules': ['break_rules']}],
            }],
            'break_rules': {'preventions': [{'scope': 'opponent_effect'}]},
        }
    ruleset = {
        'version': AUTOMATIC_SCENARIO_VERSION,
        'cards': {
            source['code']: {
                **copy.deepcopy(source), 'effect_definition': isolated,
            },
            opposing['code']: {
                **copy.deepcopy(opposing),
                'effect_definition': opposing_definition,
            },
            breaker['code']: {
                **copy.deepcopy(breaker), 'effect_definition': no_effect,
            },
        },
    }
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['hand'].append(copy.deepcopy(breaker))
    engine = AutomaticGameEngine(
        state, ruleset,
        seed=(
            f'jump-break:{owner}:{opponent_has_grab}:'
            f'{opponent_protected}:{grab_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'], 'card': live_source,
        },
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    if grab_negated:
        engine._invalidate_grab(owner, breaker['instance_id'])
    else:
        engine._fire('after_use', {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': live_source, 'opponent_card': live_opposing,
        })
    resolved = any(
        event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') == ability.get('id')
        for event in engine.events
    )
    batch_cancelled = any(
        event.get('type') == 'card_break_batch_cancelled'
        for event in engine.events
    )
    return {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'opponent_zone': engine._find_location(opposing['instance_id'])[1],
        'negation_card_zone': engine._find_location(breaker['instance_id'])[1],
        'resolved': resolved, 'batch_cancelled': batch_cancelled,
        'grab_negated_event': any(
            event.get('type') == 'grab_negated' for event in engine.events
        ),
    }


def _review_st1_014_break_ability(definition, ability, card_snapshot):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-014':
        return None
    qna_ids = [69, 655, 656]
    expected_ids = [
        {'path': 'context.opponent_card.instance_id'},
        {'path': 'context.source_card_instance_id'},
    ]
    valid = bool(
        _normalized_rule_text(
            ability.get('draft_text') or ability.get('label') or '',
        ) == (
            '사용 후, 상대 기술에 그랩판정이 있는 경우 '
            '이 기술과 해당 기술을 브레이크한다.'
        )
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'after_use'}
        and ability.get('condition') == {
            'op': 'card_matches',
            'card': {'path': 'context.opponent_card'},
            'where': {'special_contains': '그랩'},
        }
        and ability.get('effects') == [{
            'op': 'break_cards', 'card_instance_ids': expected_ids,
            'require_all': True,
        }]
    )
    ability_id = str(ability.get('id') or 'st1-014-n2')
    if not valid:
        return AbilityReview(
            ability_id, False,
            reason='점프의 그랩 조건·일괄 브레이크·Q&A 출처가 일치하지 않습니다.',
        )
    specs = (
        (
            'owner-p1-breaks-both', 'p1',
            {'opponent_has_grab': True},
            ('break', 'break', False, True, False),
        ),
        (
            'owner-p2-breaks-both', 'p2',
            {'opponent_has_grab': True},
            ('break', 'break', False, True, False),
        ),
        (
            'qna-656-protected-opponent-cancels-both', 'p1',
            {'opponent_has_grab': True, 'opponent_protected': True},
            ('battle', 'battle', True, True, False),
        ),
        (
            'non-grab-does-not-trigger', 'p1',
            {'opponent_has_grab': False},
            ('battle', 'battle', False, False, False),
        ),
        (
            'qna-69-grab-negation-skips-after-use', 'p1',
            {'opponent_has_grab': True, 'grab_negated': True},
            ('hand', 'hand', False, False, True),
        ),
    )
    scenarios = []
    for name, owner, kwargs, expected in specs:
        first = _run_st1_014_break_scenario(
            definition, ability, card_snapshot, owner, **kwargs,
        )
        second = _run_st1_014_break_scenario(
            definition, ability, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        source_zone, opponent_zone, cancelled, resolved, negated = expected
        scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['source_zone'] == source_zone
                and first['opponent_zone'] == opponent_zone
                and first['batch_cancelled'] is cancelled
                and first['resolved'] is resolved
                and first['grab_negated_event'] is negated
                and (
                    not kwargs.get('grab_negated')
                    or first['negation_card_zone'] == 'break'
                )
            ),
            'deterministic': deterministic,
            'expected_source_zone': source_zone,
            'expected_opponent_zone': opponent_zone,
            'expected_batch_cancelled': cancelled,
            'expected_resolution': resolved,
            'expected_grab_negated': negated,
            **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return AbilityReview(
        ability_id, passed, scenarios,
        '' if passed else '점프의 일괄 브레이크 Q&A 검증에 실패했습니다.',
    )


def _review_st1_014_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-014':
        return None
    qna_ids = [69, 655, 656]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st1-014-function')
    dodge_fp = by_id.get('st1-014-n1')
    break_pair = by_id.get('st1-014-n2')
    rule = {'position': '중단', 'max_speed': 7}
    valid = bool(
        extra_root == {'defense_rules'}
        and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and definition.get('defense_rules') == [rule]
        and function
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and _normalized_rule_text(
            function.get('draft_text') or function.get('label') or '',
        ) == '중단은 7속도이하 기술 회피할 수 있다.'
        and sorted((function.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and dodge_fp and break_pair
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'st1-014', False,
                reason='점프의 카드 원문·Q&A·수비 규칙 구조가 일치하지 않습니다.',
            )],
            'ST1-014 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    defense_scenarios = []
    for name, owner, allowed in (
        ('owner-p1-speed-seven', 'p1', True),
        ('owner-p2-speed-seven', 'p2', True),
        ('speed-eight-rejected', 'p1', False),
    ):
        first = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner, allowed=allowed,
        )
        second = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner, allowed=allowed,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name, 'passed': bool(first['passed'] and deterministic),
            'deterministic': deterministic,
            'result': first['result'], 'expected': first['expected'],
        })
    defense_review = AbilityReview(
        str(function.get('id') or 'st1-014-function'),
        all(item['passed'] for item in defense_scenarios), defense_scenarios,
        '' if all(item['passed'] for item in defense_scenarios)
        else '점프의 중단 회피 속도 경계 검증에 실패했습니다.',
    )
    fp_review = _review_st1_014_dodge_fp_ability(
        definition, dodge_fp, card_snapshot,
    )
    break_review = _review_st1_014_break_ability(
        definition, break_pair, card_snapshot,
    )
    reviewed = [defense_review, fp_review, break_review]
    passed = all(item and item.passed and item.scenarios for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '점프의 수비·FP·브레이크 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_st1_015_scenario(
    definition, ability, card_snapshot, owner, *,
    priority=None, damage_received=0, both_dash=False,
    preserve_turn_state=False, record_zero_damage=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-dash', 'owner': owner,
        'kind': 'card', 'type': '수비', 'face_up': True,
    })
    opposing = _card('REVIEW-DASH-OPPONENT', other, f'{other}-dash-opponent')
    opposing.update({'type': '수비' if both_dash else '공격', 'face_up': True})
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    later_definition = {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [36], 'qna_ids': [67, 276, 541, 626]},
        'abilities': [{
            'id': 'review-dash-later-after-judgment',
            'kind': 'effect', 'mode': 'mandatory',
            'timing': 'after_judgment', 'visibility': 'public',
            'source_refs': {
                'rulebook_pages': [36], 'qna_ids': [67, 276, 541, 626],
            },
            'trigger': {'event': 'after_judgment'},
            'effects': [
                {
                    'op': 'change_fp', 'player': {'controller': True},
                    'amount': 4,
                },
                {
                    'op': 'grant_catch', 'player': {'controller': True},
                    'allow_zones': ['hand'], 'where': {},
                },
            ],
        }],
    }
    if both_dash:
        opposing['code'] = source['code']
        opposing_definition = isolated
    else:
        opposing_definition = later_definition
    ruleset_cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': opposing_definition,
        },
    }
    state = _state(source, opposing, owner)
    state['priority_player'] = priority if priority in {'p1', 'p2'} else owner
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'dash:{owner}:{priority}:{damage_received}:{both_dash}:'
            f'{preserve_turn_state}:{record_zero_damage}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {'instance_id': source['instance_id'], 'card': live_source},
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
        'actual_damage_received': {
            owner: damage_received, other: 0,
        },
    }
    engine.engine_state['defense_over_count'] = 2
    if preserve_turn_state:
        engine.engine_state.setdefault('skip_get', {})[owner] = True
        engine.add_modifier({
            'op': 'modify_stat', 'player': owner,
            'scope': 'player_cards', 'stat': 'damage', 'amount': 100,
            'duration': 'battle', 'source': source['instance_id'],
        })
    if record_zero_damage:
        engine.deal_damage(
            owner, 0, source='effect',
            context={'controller': other, 'source_card': live_opposing},
        )
    engine._battle_trigger('after_judgment')
    engine._continue()
    resolved = [
        event for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') == ability.get('id')
    ]
    later_resolved = any(
        event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id')
        == 'review-dash-later-after-judgment'
        for event in engine.events
    )
    return {
        'phase': engine.state.get('phase'),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'opponent_zone': engine._find_location(opposing['instance_id'])[1],
        'owner_fp': engine.state['players'][owner]['fp'],
        'opponent_fp': engine.state['players'][other]['fp'],
        'dash_resolution_actors': [event.get('actor') for event in resolved],
        'later_resolved': later_resolved,
        'phase_restarted': any(
            event.get('type') == 'phase_restarted' for event in engine.events
        ),
        'battle_ended': any(
            event.get('type') == 'battle_end' for event in engine.events
        ),
        'defense_over_count': engine.engine_state.get('defense_over_count'),
        'skip_get_preserved': bool(
            (engine.engine_state.get('skip_get') or {}).get(owner)
        ),
        'battle_modifier_count': len(engine.engine_state.get('modifiers') or []),
        'granted_catch_count': len(
            engine.engine_state.get('granted_catches') or []
        ),
        'catch_owner': (engine.engine_state.get('catch') or {}).get('owner'),
    }


