def _run_st1_019_grab_scenario(
    definition, ability, card_snapshot, owner, mode,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-catch-drop-grab', 'owner': owner,
        'kind': 'card', 'type': '공격', 'special': '그랩',
        'frame': 10, 'damage': 500, 'face_up': True,
    })
    opposing = _card(
        'REVIEW-CATCH-DROP-GRAB-OPPONENT', other,
        f'{other}-catch-drop-grab-opponent',
    )
    breaker = _card(
        'REVIEW-CATCH-DROP-GRAB-BREAKER', other,
        f'{other}-catch-drop-grab-breaker',
    )
    breaker['special'] = '그랩'
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    cards = [source, opposing, breaker]
    state = _state(source, opposing, owner)
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    state['players'][other]['zones']['hand'].append(copy.deepcopy(breaker))
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                card['code']: {
                    **copy.deepcopy(card),
                    'effect_definition': isolated if card is source else no_effect,
                }
                for card in cards
            },
        },
        seed=f'catch-drop-grab:{owner}:{mode}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {'instance_id': source['instance_id'], 'card': live_source},
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    if mode == 'grab_negated':
        engine._invalidate_grab(other, breaker['instance_id'])
        engine._continue()
    elif mode == 'other_invalidation':
        engine.invalidate_battle_card(
            source['instance_id'], effect_controller=other,
            effect_source=opposing['instance_id'],
        )
    else:
        engine._fire('opponent_dodge', {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': live_source, 'opponent_card': live_opposing,
        })
    return {
        'owner_fp': engine.state['players'][owner]['fp'],
        'opponent_fp': engine.state['players'][other]['fp'],
        'source_zone': engine._find_location(source['instance_id'])[1],
        'breaker_zone': engine._find_location(breaker['instance_id'])[1],
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability.get('id')
            for event in engine.events
        ),
        'grab_negated': any(
            event.get('type') == 'grab_negated' for event in engine.events
        ),
        'battle_invalidated': any(
            event.get('type') == 'battle_card_invalidated'
            for event in engine.events
        ),
    }


def _run_st1_019_combo_scenario(
    definition, ability, card_snapshot, owner, *, event_type='combo',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-catch-drop-combo', 'owner': owner,
        'kind': 'card', 'type': '공격', 'special': '그랩',
        'frame': 10, 'damage': 500, 'hit': '0', 'face_up': False,
    })
    starter = _card(
        'REVIEW-CATCH-DROP-STARTER', owner,
        f'{owner}-catch-drop-starter',
    )
    starter.update({'frame': 4, 'damage': 500, 'hit': '콤보'})
    second = _card(
        'REVIEW-CATCH-DROP-SECOND', owner,
        f'{owner}-catch-drop-second',
    )
    second.update({'frame': 5, 'damage': 500, 'hit': '0'})
    third = _card(
        'REVIEW-CATCH-DROP-THIRD', owner,
        f'{owner}-catch-drop-third',
    )
    third.update({'frame': 7, 'damage': 500, 'hit': '0'})
    opposing = _card(
        'REVIEW-CATCH-DROP-COMBO-OPPONENT', other,
        f'{other}-catch-drop-combo-opponent',
    )
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    cards = [source, starter, second, third, opposing]
    ruleset_cards = {
        card['code']: {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(definition)
            if card is source else no_effect,
        }
        for card in cards
    }
    state = _state(source, opposing, owner, source_zone='hand')
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    state['players'][owner]['zones']['hand'].extend([
        copy.deepcopy(second), copy.deepcopy(third),
    ])
    state['players'][owner]['zones']['battle'] = [copy.deepcopy(starter)]
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=f'catch-drop-combo:{owner}:{event_type}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_starter = engine._find_card(starter['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': starter['instance_id'], 'card': live_starter,
        },
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    legal_chain = False
    source_alone_legal = False
    short_chain_legal = False
    if event_type == 'combo':
        engine.grant_combo(owner, source=starter['instance_id'])
        actions = engine.legal_actions(owner)
        legal_chain = any(
            (action.get('payload') or {}).get('card_instance_ids') == [
                second['instance_id'], third['instance_id'],
                source['instance_id'],
            ]
            for action in actions
        )
        source_alone_legal = any(
            action.get('type') == 'play_combo_card'
            and (action.get('payload') or {}).get('card_instance_id')
            == source['instance_id']
            for action in actions
        )
        short_chain_legal = any(
            (action.get('payload') or {}).get('card_instance_ids') == [
                second['instance_id'], source['instance_id'],
            ]
            for action in actions
        )
        if legal_chain:
            engine._play_combo(
                owner,
                [
                    second['instance_id'], third['instance_id'],
                    source['instance_id'],
                ],
                [5, 7, 10],
            )
            engine._continue()
    else:
        live_source = engine._find_card(source['instance_id'])
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': live_source, 'opponent_card': live_opposing,
        })
    scheduled_before_recovery = len(engine.engine_state.get('scheduled') or [])
    fp_before_recovery = engine.state['players'][owner]['fp']
    engine.state['phase'] = 'recovery'
    engine._fire('phase_start', {'phase': 'recovery'})
    fp_after_recovery = engine.state['players'][owner]['fp']
    engine._fire('phase_start', {'phase': 'recovery'})
    return {
        'legal_chain': legal_chain,
        'source_alone_legal': source_alone_legal,
        'short_chain_legal': short_chain_legal,
        'combo_used_ids': [
            (event.get('payload') or {}).get('card_instance_id')
            for event in engine.events if event.get('type') == 'combo_card_used'
        ],
        'combo_ended': any(
            event.get('type') == 'combo_ended' for event in engine.events
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability.get('id')
            for event in engine.events
        ),
        'scheduled_before_recovery': scheduled_before_recovery,
        'scheduled_after_recovery': len(engine.engine_state.get('scheduled') or []),
        'fp_before_recovery': fp_before_recovery,
        'fp_after_recovery': fp_after_recovery,
        'fp_after_second_recovery': engine.state['players'][owner]['fp'],
    }


def _review_st1_019_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-019':
        return None
    qna_ids = [69, 260, 408, 675]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st1-019-function')
    grab_penalty = by_id.get('st1-019-n1')
    combo_effect = by_id.get('st1-019-n2')
    expected_schedule = [{
        'op': 'schedule',
        'when': {'event': 'phase_start', 'phase': 'recovery'},
        'duration': 'turn',
        'effect': {
            'op': 'change_fp', 'player': {'controller': True}, 'amount': 1,
        },
    }]
    valid = bool(
        extra_root == {'combo_rules'}
        and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and definition.get('combo_rules') == [{
            'min_combo': 4, 'end_after_use': True,
            'numbered_effect': True,
        }]
        and function and grab_penalty and combo_effect
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and _normalized_rule_text(
            function.get('draft_text') or function.get('label') or '',
        ) == '상대는 이 기술을 방어 및 상쇄할 수 없다.'
        and function.get('effects') == [
            {
                'op': 'prevent', 'kind': 'guard',
                'player': {'opponent': True}, 'duration': 'continuous',
            },
            {
                'op': 'prevent', 'kind': 'clash',
                'player': {'opponent': True}, 'duration': 'continuous',
            },
        ]
        and grab_penalty.get('kind') == 'effect'
        and grab_penalty.get('mode') == 'mandatory'
        and grab_penalty.get('timing') == 'result'
        and grab_penalty.get('trigger') == {'event': 'grab_negated'}
        and grab_penalty.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True}, 'amount': -4,
        }]
        and combo_effect.get('kind') == 'effect'
        and combo_effect.get('mode') == 'mandatory'
        and combo_effect.get('timing') == 'combo'
        and combo_effect.get('trigger') == {'event': 'combo'}
        and combo_effect.get('effects') == expected_schedule
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'st1-019', False,
                reason='캐치 드롭의 금지·그랩 무효·4콤보·예약 효과 정의가 일치하지 않습니다.',
            )],
            'ST1-019 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    prevent_scenarios = []
    for name, owner in (
        ('owner-p1-guard-and-clash-blocked', 'p1'),
        ('owner-p2-guard-and-clash-blocked', 'p2'),
        ('dodge-remains-available', 'p1'),
    ):
        first = _run_st1_019_prevent_scenario(
            definition, function, card_snapshot, owner,
        )
        second = _run_st1_019_prevent_scenario(
            definition, function, card_snapshot, owner,
        )
        deterministic = _canonical(first) == _canonical(second)
        prevent_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['guard_blocked']
                and first['clash_blocked'] and not first['dodge_blocked']
            ),
            'deterministic': deterministic, **first,
        })
    function_review = AbilityReview(
        str(function.get('id')),
        all(item['passed'] for item in prevent_scenarios), prevent_scenarios,
        '' if all(item['passed'] for item in prevent_scenarios)
        else '캐치 드롭의 방어·상쇄 금지 검증에 실패했습니다.',
    )

    grab_specs = (
        ('owner-p1-qna-408-zero-then-minus-four', 'p1', 'grab_negated', -4, 'hand', True),
        ('owner-p2-grab-negated', 'p2', 'grab_negated', -4, 'hand', True),
        ('qna-260-dodge-is-not-grab-negation', 'p1', 'dodge', 0, 'battle', False),
        ('qna-675-other-invalidation-is-not-grab-negation', 'p1', 'other_invalidation', 0, 'hand', False),
    )
    grab_scenarios = []
    for name, owner, mode, expected_fp, expected_zone, expected_resolved in grab_specs:
        first = _run_st1_019_grab_scenario(
            definition, grab_penalty, card_snapshot, owner, mode,
        )
        second = _run_st1_019_grab_scenario(
            definition, grab_penalty, card_snapshot, owner, mode,
        )
        deterministic = _canonical(first) == _canonical(second)
        extra_ok = True
        if mode == 'grab_negated':
            extra_ok = bool(
                first['grab_negated'] and first['breaker_zone'] == 'break'
            )
        elif mode == 'other_invalidation':
            extra_ok = bool(
                first['battle_invalidated'] and not first['grab_negated']
            )
        grab_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and extra_ok
                and first['owner_fp'] == expected_fp
                and first['source_zone'] == expected_zone
                and first['resolved'] is expected_resolved
            ),
            'deterministic': deterministic,
            'expected_fp': expected_fp, 'expected_zone': expected_zone,
            'expected_resolution': expected_resolved, **first,
        })
    grab_review = AbilityReview(
        str(grab_penalty.get('id')),
        all(item['passed'] for item in grab_scenarios), grab_scenarios,
        '' if all(item['passed'] for item in grab_scenarios)
        else '캐치 드롭의 그랩 무효 전용 FP 검증에 실패했습니다.',
    )

    combo_scenarios = []
    for name, owner, event_type, expected in (
        ('owner-p1-fourth-combo-ends-and-schedules', 'p1', 'combo', True),
        ('owner-p2-fourth-combo-ends-and-schedules', 'p2', 'combo', True),
        ('wrong-trigger-does-not-schedule', 'p1', 'use', False),
    ):
        first = _run_st1_019_combo_scenario(
            definition, combo_effect, card_snapshot, owner,
            event_type=event_type,
        )
        second = _run_st1_019_combo_scenario(
            definition, combo_effect, card_snapshot, owner,
            event_type=event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        if expected:
            outcome_ok = bool(
                first['legal_chain'] and not first['source_alone_legal']
                and not first['short_chain_legal']
                and first['combo_used_ids'][-1:] == [
                    f'{owner}-catch-drop-combo',
                ]
                and first['combo_ended'] and first['resolved']
                and first['scheduled_before_recovery'] == 1
                and first['fp_after_recovery']
                == first['fp_before_recovery'] + 1
                and first['fp_after_second_recovery']
                == first['fp_after_recovery']
                and first['scheduled_after_recovery'] == 0
            )
        else:
            outcome_ok = bool(
                not first['legal_chain'] and not first['resolved']
                and first['scheduled_before_recovery'] == 0
                and first['fp_after_recovery'] == first['fp_before_recovery']
                and first['fp_after_second_recovery']
                == first['fp_before_recovery']
            )
        combo_scenarios.append({
            'name': name, 'passed': bool(deterministic and outcome_ok),
            'deterministic': deterministic,
            'expected_resolution': expected, **first,
        })
    combo_review = AbilityReview(
        str(combo_effect.get('id')),
        all(item['passed'] for item in combo_scenarios), combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '캐치 드롭의 4콤보·종료·리커버리 예약 검증에 실패했습니다.',
    )
    reviewed = [function_review, grab_review, combo_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '캐치 드롭의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st1_020_engine(definition, ability, card_snapshot, owner, *, fp=5):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-desperate-tackle', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 12,
        'damage': 900, 'hit': '4', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-DESPERATE-TACKLE-OPPONENT', other,
        f'{other}-desperate-tackle-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    state = _state(source, opposing, owner)
    state['players'][owner]['fp'] = fp
    state['players'][other]['fp'] = 0
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'desperate-tackle:{ability.get("id")}:{owner}:{fp}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {'instance_id': source['instance_id'], 'card': live_source},
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    return engine, live_source, live_opposing, other


def _run_st1_020_play_scenario(
    definition, ability, card_snapshot, owner,
):
    engine, source, _opposing, _other = _st1_020_engine(
        definition, ability, card_snapshot, owner,
    )
    return {
        use_context: engine._card_use_allowed(source, owner, use_context)
        for use_context in ('ready', 'catch', 'combo')
    }


def _run_st1_020_trigger_scenario(
    definition, ability, card_snapshot, owner, event_type, *, fp=5,
):
    engine, source, opposing, other = _st1_020_engine(
        definition, ability, card_snapshot, owner, fp=fp,
    )
    hp_before = engine.state['players'][owner]['hp']
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': source, 'opponent_card': opposing,
    })
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability.get('id')
            for event in engine.events
        ),
        'self_damage': hp_before - engine.state['players'][owner]['hp'],
        'owner_fp': engine.state['players'][owner]['fp'],
        'damage': engine.card_stat(source, 'damage', owner),
        'opponent_hp': engine.state['players'][other]['hp'],
    }


def _run_st1_020_clash_qna_scenario(
    definition, ability, card_snapshot, owner,
):
    engine, source, opposing, other = _st1_020_engine(
        definition, ability, card_snapshot, owner, fp=0,
    )
    opposing['damage'] = 900
    opposing['frame'] = 8
    engine.engine_state['battle']['result'] = {
        owner: 'clash', other: 'clash',
    }
    for event_type, context in engine._result_trigger_sequence(
        engine.engine_state['battle']['result'],
    ):
        engine._fire(event_type, context)
    engine._prepare_battle_outcomes()
    engine._prepare_battle_damage_outcomes()
    outcomes = copy.deepcopy(
        engine.engine_state['battle'].get('outcome_queue') or [],
    )
    hp_before = engine.state['players'][owner]['hp']
    for outcome in outcomes:
        engine._apply_battle_outcome(outcome)
    return {
        'result': copy.deepcopy(engine.engine_state['battle']['result']),
        'source_damage': engine.engine_state['battle']['damage'][owner],
        'opponent_damage': engine.engine_state['battle']['damage'][other],
        'damage_outcomes': outcomes,
        'owner_damage_received': hp_before - engine.state['players'][owner]['hp'],
        'resolution_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability.get('id')
            for event in engine.events
        ),
    }


def _review_st1_020_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-020':
        return None
    qna_ids = [251, 477, 540]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    no_combo = by_id.get('st1-020-n1')
    guard_damage = by_id.get('st1-020-n2')
    dodge_fp = by_id.get('st1-020-n3')
    clash_damage = by_id.get('st1-020-n4')
    valid = bool(
        extra_root == {'play_condition'}
        and len(abilities) == 4
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and definition.get('play_condition') == {
            'op': 'not_equals', 'left': 'context.use_context',
            'right': 'combo',
        }
        and no_combo and guard_damage and dodge_fp and clash_damage
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and _normalized_rule_text(
            no_combo.get('draft_text') or no_combo.get('label') or '',
        ) == '이 기술은 콤보에 사용할 수 없다.'
        and no_combo.get('trigger') == {'event': 'use'}
        and no_combo.get('effects') == [{
            'op': 'static_rule', 'rules': ['play_condition'],
        }]
        and _normalized_rule_text(
            guard_damage.get('draft_text') or guard_damage.get('label') or '',
        ) == '상대 방어 시 자신은 300데미지를 받는다.'
        and guard_damage.get('mode') == 'mandatory'
        and guard_damage.get('trigger') == {'event': 'opponent_guard'}
        and guard_damage.get('effects') == [{
            'op': 'deal_damage', 'player': {'controller': True}, 'amount': 300,
        }]
        and _normalized_rule_text(
            dodge_fp.get('draft_text') or dodge_fp.get('label') or '',
        ) == '상대 회피 시 자신은 4FP를 잃는다.'
        and dodge_fp.get('mode') == 'mandatory'
        and dodge_fp.get('trigger') == {'event': 'opponent_dodge'}
        and dodge_fp.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True}, 'amount': -4,
        }]
        and _normalized_rule_text(
            clash_damage.get('draft_text') or clash_damage.get('label') or '',
        ) == '상대 상쇄 시 이 기술 데미지-400'
        and clash_damage.get('mode') == 'mandatory'
        and clash_damage.get('trigger') == {'event': 'clash'}
        and clash_damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': -400, 'duration': 'battle',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'st1-020', False,
                reason='이판사판태클의 사용 제한·방어·회피·상쇄 정의가 일치하지 않습니다.',
            )],
            'ST1-020 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    play_scenarios = []
    for name, owner in (
        ('owner-p1-context-boundaries', 'p1'),
        ('owner-p2-context-boundaries', 'p2'),
        ('combo-only-is-blocked', 'p1'),
    ):
        first = _run_st1_020_play_scenario(
            definition, no_combo, card_snapshot, owner,
        )
        second = _run_st1_020_play_scenario(
            definition, no_combo, card_snapshot, owner,
        )
        deterministic = _canonical(first) == _canonical(second)
        play_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first == {
                    'ready': True, 'catch': True, 'combo': False,
                }
            ),
            'deterministic': deterministic, **first,
        })
    play_review = AbilityReview(
        str(no_combo.get('id')),
        all(item['passed'] for item in play_scenarios), play_scenarios,
        '' if all(item['passed'] for item in play_scenarios)
        else '이판사판태클의 콤보 전용 사용 금지 검증에 실패했습니다.',
    )

    guard_scenarios = []
    for name, owner, event_type, expected in (
        ('owner-p1-opponent-guard-self-damage', 'p1', 'opponent_guard', 300),
        ('owner-p2-opponent-guard-self-damage', 'p2', 'opponent_guard', 300),
        ('wrong-trigger-no-self-damage', 'p1', 'guard', 0),
    ):
        first = _run_st1_020_trigger_scenario(
            definition, guard_damage, card_snapshot, owner, event_type,
        )
        second = _run_st1_020_trigger_scenario(
            definition, guard_damage, card_snapshot, owner, event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        guard_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['self_damage'] == expected
                and first['resolved'] is (expected == 300)
            ),
            'deterministic': deterministic,
            'expected_self_damage': expected, **first,
        })
    guard_review = AbilityReview(
        str(guard_damage.get('id')),
        all(item['passed'] for item in guard_scenarios), guard_scenarios,
        '' if all(item['passed'] for item in guard_scenarios)
        else '이판사판태클의 상대 방어 자기 데미지 검증에 실패했습니다.',
    )

    dodge_scenarios = []
    for name, owner, event_type, initial_fp, expected_fp in (
        ('owner-p1-opponent-dodge-loses-four', 'p1', 'opponent_dodge', 5, 1),
        ('owner-p2-can-become-negative', 'p2', 'opponent_dodge', 0, -4),
        ('wrong-trigger-keeps-fp', 'p1', 'dodge', 5, 5),
    ):
        first = _run_st1_020_trigger_scenario(
            definition, dodge_fp, card_snapshot, owner, event_type,
            fp=initial_fp,
        )
        second = _run_st1_020_trigger_scenario(
            definition, dodge_fp, card_snapshot, owner, event_type,
            fp=initial_fp,
        )
        deterministic = _canonical(first) == _canonical(second)
        dodge_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['owner_fp'] == expected_fp
                and first['resolved'] is (event_type == 'opponent_dodge')
            ),
            'deterministic': deterministic,
            'initial_fp': initial_fp, 'expected_fp': expected_fp, **first,
        })
    dodge_review = AbilityReview(
        str(dodge_fp.get('id')),
        all(item['passed'] for item in dodge_scenarios), dodge_scenarios,
        '' if all(item['passed'] for item in dodge_scenarios)
        else '이판사판태클의 상대 회피 FP 검증에 실패했습니다.',
    )

    clash_scenarios = []
    for name, owner, event_type, expected_damage in (
        ('owner-p1-clash-reduces-damage', 'p1', 'clash', 500),
        ('owner-p2-clash-reduces-damage', 'p2', 'clash', 500),
        ('wrong-trigger-keeps-damage', 'p1', 'hit', 900),
    ):
        first = _run_st1_020_trigger_scenario(
            definition, clash_damage, card_snapshot, owner, event_type,
        )
        second = _run_st1_020_trigger_scenario(
            definition, clash_damage, card_snapshot, owner, event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        clash_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['damage'] == expected_damage
                and first['resolved'] is (event_type == 'clash')
            ),
            'deterministic': deterministic,
            'expected_damage': expected_damage, **first,
        })
    first = _run_st1_020_clash_qna_scenario(
        definition, clash_damage, card_snapshot, 'p1',
    )
    second = _run_st1_020_clash_qna_scenario(
        definition, clash_damage, card_snapshot, 'p1',
    )
    deterministic = _canonical(first) == _canonical(second)
    clash_scenarios.append({
        'name': 'qna-477-540-nine-hundred-minus-five-hundred',
        'passed': bool(
            deterministic
            and first['result'] == {'p1': 'clash', 'p2': 'clash'}
            and first['source_damage'] == 500
            and first['opponent_damage'] == 900
            and first['owner_damage_received'] == 400
            and first['damage_outcomes'] == [{
                'kind': 'damage', 'side': 'p1', 'amount': 400,
                'source': 'clash', 'controller': 'p2',
            }]
            and first['resolution_count'] == 1
        ),
        'deterministic': deterministic, **first,
    })
    clash_review = AbilityReview(
        str(clash_damage.get('id')),
        all(item['passed'] for item in clash_scenarios), clash_scenarios,
        '' if all(item['passed'] for item in clash_scenarios)
        else '이판사판태클의 상쇄 데미지·Q&A 477/540 검증에 실패했습니다.',
    )
    reviewed = [play_review, guard_review, dodge_review, clash_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '이판사판태클의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _review_awl_at_046_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-046':
        return None
    qna_ids = [146, 435]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-046-function')
    dodge_fp = by_id.get('awl-at-046-n1')
    rule = {'max_speed': 6}
    expected_amount = {
        'op': 'clamp',
        'value': {
            'op': 'subtract',
            'left': {'path': 'context.opponent_speed'}, 'right': 1,
        },
        'min': 0, 'max': 99,
    }
    valid = bool(
        extra_root == {'defense_rules'}
        and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and definition.get('defense_rules') == [rule]
        and function and dodge_fp
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and _normalized_rule_text(
            function.get('draft_text') or function.get('label') or '',
        ) == '이 기술은 6속도 이하 기술만 회피할 수 있다.'
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'dodge',
            'player': {'controller': True}, 'duration': 'continuous',
            'condition': {
                'op': 'gt', 'left': 'context.opponent_card.frame',
                'right': 6,
            },
        }]
        and dodge_fp.get('kind') == 'effect'
        and dodge_fp.get('mode') == 'mandatory'
        and dodge_fp.get('trigger') == {'event': 'dodge'}
        and _normalized_rule_text(
            dodge_fp.get('draft_text') or dodge_fp.get('label') or '',
        ) == '자신의 회피 시, 상대 기술 속도 -1만큼 FP를 얻는다.'
        and dodge_fp.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True},
            'amount': expected_amount,
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'awl-at-046', False,
                reason='백스텝의 6속도 회피 제한·속도 비례 FP 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-046 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, allowed, speed in (
        ('owner-p1-speed-six-boundary', 'p1', True, 6),
        ('owner-p2-speed-six-boundary', 'p2', True, 6),
        ('speed-seven-is-not-dodged', 'p1', False, 7),
    ):
        first = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner,
            allowed=allowed, speed_override=speed,
        )
        second = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner,
            allowed=allowed, speed_override=speed,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name, 'passed': bool(first['passed'] and deterministic),
            'deterministic': deterministic, 'speed': speed,
            'result': first['result'], 'expected': first['expected'],
        })
    stance_p1 = _run_down_stance_qna_146(card_snapshot, 'p1')
    stance_p2 = _run_down_stance_qna_146(card_snapshot, 'p2')
    non_dodge = _run_down_stance_qna_146(
        card_snapshot, 'p1', top_result='방어',
    )
    defense_scenarios.append({
        'name': 'qna-146-defense-dodge-enters-down-stance',
        'passed': bool(stance_p1 and stance_p2 and not non_dodge),
        'deterministic': True,
        'owner_p1_down_stance': stance_p1,
        'owner_p2_down_stance': stance_p2,
        'non_dodge_down_stance': non_dodge,
    })
    function_review = AbilityReview(
        str(function.get('id')),
        all(item['passed'] for item in defense_scenarios), defense_scenarios,
        '' if all(item['passed'] for item in defense_scenarios)
        else '백스텝의 속도 경계·다운 스탠스 검증에 실패했습니다.',
    )

    fp_scenarios = []
    for name, owner, event_type, speed, bonus, own_gain, total_gain in (
        ('owner-p1-speed-six-gains-five', 'p1', 'dodge', 6, 0, 5, 5),
        ('owner-p2-speed-one-gains-zero', 'p2', 'dodge', 1, 0, 0, 0),
        ('qna-435-zero-then-opponent-nine', 'p1', 'dodge', 0, 9, 0, 9),
        ('wrong-trigger-does-not-gain', 'p1', 'guard', 6, 0, 0, 0),
    ):
        first = _run_st1_012_dodge_fp_scenario(
            definition, dodge_fp, card_snapshot, owner, event_type,
            opponent_speed=speed, opponent_dodge_bonus=bonus,
        )
        second = _run_st1_012_dodge_fp_scenario(
            definition, dodge_fp, card_snapshot, owner, event_type,
            opponent_speed=speed, opponent_dodge_bonus=bonus,
        )
        deterministic = _canonical(first) == _canonical(second)
        fp_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['after_dodge'] == first['before'] + own_gain
                and first['after_opponent_dodge']
                == first['before'] + total_gain
            ),
            'deterministic': deterministic,
            'opponent_speed': speed, 'opponent_dodge_bonus': bonus,
            'expected_own_gain': own_gain,
            'expected_total_gain': total_gain, **first,
        })
    fp_review = AbilityReview(
        str(dodge_fp.get('id')),
        all(item['passed'] for item in fp_scenarios), fp_scenarios,
        '' if all(item['passed'] for item in fp_scenarios)
        else '백스텝의 속도 비례 FP·Q&A 435 순서 검증에 실패했습니다.',
    )
    reviewed = [function_review, fp_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '백스텝의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_awl_at_050_effect_scenario(
    definition, ability, card_snapshot, owner, event_type, *,
    dark_night_listener=False, lethal=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-rending-dagger', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 8,
        'damage': 500, 'body': '손', 'special': '상단 상쇄',
        'g_top': '상쇄', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-RENDING-DAGGER-OPPONENT', other,
        f'{other}-rending-dagger-opponent',
    )
    opposing.update({'damage': 900, 'body': '손'})
    passive = _sandbox_source_snapshot({
        'code': 'REVIEW-REVE-DARK-NIGHT', 'name': '암야 유발 검토 특성',
        'type': '패시브',
    })
    passive.update({
        'instance_id': f'{other}-dark-night-listener', 'owner': other,
        'face_up': True,
    })
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    passive_definition = {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [190]},
        'abilities': [{
            'id': 'review-qna-190-dark-night', 'kind': 'function',
            'mode': 'mandatory', 'timing': 'result',
            'visibility': 'public', 'active_zones': ['passive'],
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [190]},
            'trigger': {'event': 'damage_after'},
            'effects': [{
                'op': 'gain_state', 'player': {'controller': True},
                'state': 'dark_night',
            }],
        }],
    }
    state = _state(source, opposing, owner)
    state['players'][other]['hp'] = 100 if lethal else 4000
    if dark_night_listener:
        state['players'][other]['zones']['passive'].append(copy.deepcopy(passive))
    cards = [source, opposing, passive]
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                card['code']: {
                    **copy.deepcopy(card),
                    'effect_definition': isolated if card is source
                    else passive_definition if card is passive
                    else no_effect,
                }
                for card in cards
            },
        },
        seed=(
            f'rending-dagger:{owner}:{event_type}:'
            f'{dark_night_listener}:{lethal}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {'instance_id': source['instance_id'], 'card': live_source},
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    before = engine.state['players'][other]['hp']
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source, 'opponent_card': live_opposing,
    })
    damage_events = [
        event for event in engine.events
        if event.get('type') == 'damage_dealt'
        and (event.get('payload') or {}).get('target') == other
    ]
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability.get('id')
            for event in engine.events
        ),
        'damage': before - engine.state['players'][other]['hp'],
        'damage_amounts': [
            (event.get('payload') or {}).get('amount') for event in damage_events
        ],
        'dark_night': bool(
            engine.state['players'][other].get('passive_state', {})
            .get('dark_night', {}).get('value')
        ),
        'status': engine.engine_state.get('status'),
        'winner': engine.engine_state.get('winner'),
        'reason': engine.engine_state.get('reason'),
        'sudden_death': bool(engine.engine_state.get('sudden_death')),
    }


def _review_awl_at_050_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-050':
        return None
    qna_ids = [190, 575]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-050-function')
    effect = by_id.get('awl-at-050-n1')
    rule = {'judgment': 'clash', 'where': {'body': '손'}}
    valid = bool(
        extra_root == {'defense_rules'}
        and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and definition.get('defense_rules') == [rule]
        and function and effect
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and _normalized_rule_text(
            function.get('draft_text') or function.get('label') or '',
        ) == '이 기술은 손 판정 기술만 상쇄할 수 있다.'
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'clash',
            'player': {'controller': True}, 'duration': 'continuous',
            'condition': {
                'op': 'not_equals',
                'left': 'context.opponent_card.body', 'right': '손',
            },
        }]
        and effect.get('kind') == 'effect'
        and effect.get('mode') == 'mandatory'
        and effect.get('trigger') == {'event': 'clash'}
        and _normalized_rule_text(
            effect.get('draft_text') or effect.get('label') or '',
        ) == '상쇄 시, 상대에게 100데미지를 준다.'
        and effect.get('effects') == [{
            'op': 'deal_damage', 'player': {'opponent': True}, 'amount': 100,
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'awl-at-050', False,
                reason='렌딩 대거의 손 상쇄 제한·효과 데미지 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-050 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, allowed in (
        ('owner-p1-hand-clash', 'p1', True),
        ('owner-p2-hand-clash', 'p2', True),
        ('foot-judgment-is-not-clashed', 'p1', False),
    ):
        first = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner,
            allowed=allowed,
        )
        second = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner,
            allowed=allowed,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name, 'passed': bool(first['passed'] and deterministic),
            'deterministic': deterministic,
            'result': first['result'], 'expected': first['expected'],
        })
    function_review = AbilityReview(
        str(function.get('id')),
        all(item['passed'] for item in defense_scenarios), defense_scenarios,
        '' if all(item['passed'] for item in defense_scenarios)
        else '렌딩 대거의 손 판정 상쇄 경계 검증에 실패했습니다.',
    )

    effect_scenarios = []
    for name, owner, event_type, listener, lethal, expected in (
        ('owner-p1-clash-effect-damage', 'p1', 'clash', False, False, True),
        ('owner-p2-clash-effect-damage', 'p2', 'clash', False, False, True),
        ('qna-190-effect-damage-triggers-dark-night', 'p1', 'clash', True, False, True),
        ('qna-575-lethal-effect-finishes-before-sudden-death', 'p1', 'clash', False, True, True),
        ('wrong-trigger-does-not-deal-damage', 'p1', 'hit', False, False, False),
    ):
        first = _run_awl_at_050_effect_scenario(
            definition, effect, card_snapshot, owner, event_type,
            dark_night_listener=listener, lethal=lethal,
        )
        second = _run_awl_at_050_effect_scenario(
            definition, effect, card_snapshot, owner, event_type,
            dark_night_listener=listener, lethal=lethal,
        )
        deterministic = _canonical(first) == _canonical(second)
        outcome_ok = bool(
            first['resolved'] is expected
            and first['damage'] == (100 if expected else 0)
            and first['damage_amounts'] == ([100] if expected else [])
        )
        if listener:
            outcome_ok = outcome_ok and first['dark_night']
        if lethal:
            outcome_ok = bool(
                outcome_ok and first['status'] == 'finished'
                and first['winner'] == owner and first['reason'] == 'hp_zero'
                and not first['sudden_death']
            )
        effect_scenarios.append({
            'name': name, 'passed': bool(deterministic and outcome_ok),
            'deterministic': deterministic,
            'dark_night_listener': listener, 'lethal': lethal,
            'expected_resolution': expected, **first,
        })
    effect_review = AbilityReview(
        str(effect.get('id')),
        all(item['passed'] for item in effect_scenarios), effect_scenarios,
        '' if all(item['passed'] for item in effect_scenarios)
        else '렌딩 대거의 효과 데미지·Q&A 190/575 검증에 실패했습니다.',
    )
    reviewed = [function_review, effect_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '렌딩 대거의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_unc_at_050_hit_scenario(
    definition, ability, card_snapshot, owner, event_type,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-rolling-spinner-hit', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 12, 'damage': 500,
        'hit': '콤보', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-ROLLING-SPINNER-OPPONENT', other,
        f'{other}-rolling-spinner-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    engine = AutomaticGameEngine(
        _state(source, opposing, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'rolling-spinner-hit:{owner}:{event_type}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    before = engine.card_stat(live_source, 'damage', owner)
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source,
        'opponent_card': engine._find_card(opposing['instance_id']),
    })
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability.get('id')
            for event in engine.events
        ),
        'before_damage': before,
        'after_damage': engine.card_stat(live_source, 'damage', owner),
    }


def _run_unc_at_050_catch_scenario(
    definition, card_snapshot, owner, *, catch_max_speed,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-rolling-spinner-catch', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 12, 'damage': 500,
        'hit': '콤보', 'face_up': False,
    })
    opposing = _card(
        'REVIEW-ROLLING-SPINNER-OPPONENT', other,
        f'{other}-rolling-spinner-opponent',
    )
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    state = _state(source, opposing, owner, source_zone='hand')
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'rolling-spinner-catch:{owner}:{catch_max_speed}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    catch = {'owner': owner, 'max_speed': catch_max_speed}
    legal = source['instance_id'] in {
        card.get('instance_id')
        for card in engine._legal_catch_cards(owner, catch)
    }
    hp_before = engine.state['players'][other]['hp']
    if legal:
        engine.engine_state['catch'] = catch
        engine._play_catch(owner, source['instance_id'])
        engine._continue()
    event_types = [event.get('type') for event in engine.events]
    break_events = [
        event for event in engine.events
        if event.get('type') == 'card_broken'
        and (event.get('payload') or {}).get('reason')
        == 'card_catch_rule_after_use'
    ]
    fixed_values = [
        ((event.get('payload') or {}).get('modifier') or {}).get('value')
        for event in engine.events
        if event.get('type') == 'modifier_added'
        and ((event.get('payload') or {}).get('modifier') or {}).get('op')
        == 'fix_speed'
    ]
    return {
        'legal': legal,
        'damage': hp_before - engine.state['players'][other]['hp'],
        'zone': next((
            zone for zone in ('hand', 'battle', 'break')
            if engine._find_card(source['instance_id'], owner=owner, zone=zone)
        ), None),
        'fixed_values': fixed_values,
        'hit_resolution_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'unc-at-050-n1'
            for event in engine.events
        ),
        'catch_resolution_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'unc-at-050-n2'
            for event in engine.events
        ),
        'interrupted': 'catch_interrupted' in event_types,
        'damage_before_break': bool(
            break_events
            and 'damage_dealt' in event_types
            and event_types.index('damage_dealt')
            < event_types.index('card_broken')
        ),
    }


def _review_unc_at_050_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-050':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    hit = by_id.get('unc-at-050-n1')
    catch = by_id.get('unc-at-050-n2')
    valid = bool(
        extra_root == {'catch_rules'}
        and len(abilities) == 2
        and (definition.get('source_refs') or {}).get('qna_ids') == []
        and definition.get('catch_rules') == [{
            'fixed_speed': 9, 'break_after_use': True,
        }]
        and hit and catch
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == []
            for ability in abilities
        )
        and hit.get('mode') == 'mandatory'
        and hit.get('trigger') == {'event': 'hit'}
        and _normalized_rule_text(
            hit.get('draft_text') or hit.get('label') or '',
        ) == '히트 시, 이 기술의 데미지+100'
        and hit.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': 100, 'duration': 'battle',
        }]
        and catch.get('mode') == 'mandatory'
        and catch.get('trigger') == {'event': 'catch'}
        and _normalized_rule_text(
            catch.get('draft_text') or catch.get('label') or '',
        ) == (
            '캐치 시, 9속도로 사용할 수 있다. '
            '그 경우, 이 기술을 브레이크한다.'
        )
        and catch.get('effects') == [{
            'op': 'static_rule', 'rules': ['catch_rules'],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'unc-at-050', False,
                reason='롤링 스피너의 히트 보정·캐치 후 브레이크 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-050 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    hit_scenarios = []
    for name, owner, event_type, expected_damage, expected_resolution in (
        ('owner-p1-hit-adds-one-hundred', 'p1', 'hit', 600, True),
        ('owner-p2-hit-adds-one-hundred', 'p2', 'hit', 600, True),
        ('wrong-trigger-keeps-printed-damage', 'p1', 'guard', 500, False),
    ):
        first = _run_unc_at_050_hit_scenario(
            definition, hit, card_snapshot, owner, event_type,
        )
        second = _run_unc_at_050_hit_scenario(
            definition, hit, card_snapshot, owner, event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        hit_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['before_damage'] == 500
                and first['after_damage'] == expected_damage
                and first['resolved'] is expected_resolution
            ),
            'deterministic': deterministic,
            'expected_damage': expected_damage,
            'expected_resolution': expected_resolution,
            **first,
        })
    hit_review = AbilityReview(
        str(hit.get('id')),
        all(item['passed'] for item in hit_scenarios), hit_scenarios,
        '' if all(item['passed'] for item in hit_scenarios)
        else '롤링 스피너의 히트 데미지 보정 검증에 실패했습니다.',
    )

    catch_scenarios = []
    for name, owner, maximum, expected_legal in (
        ('owner-p1-fixed-nine-and-break-after-damage', 'p1', 9, True),
        ('owner-p2-fixed-nine-and-break-after-damage', 'p2', 9, True),
        ('catch-eight-does-not-offer-card', 'p1', 8, False),
    ):
        first = _run_unc_at_050_catch_scenario(
            definition, card_snapshot, owner, catch_max_speed=maximum,
        )
        second = _run_unc_at_050_catch_scenario(
            definition, card_snapshot, owner, catch_max_speed=maximum,
        )
        deterministic = _canonical(first) == _canonical(second)
        if expected_legal:
            outcome_ok = bool(
                first['legal'] and first['damage'] == 600
                and first['zone'] == 'break'
                and first['fixed_values'] == [9]
                and first['hit_resolution_count'] == 1
                and first['catch_resolution_count'] == 1
                and first['damage_before_break']
                and not first['interrupted']
            )
        else:
            outcome_ok = bool(
                not first['legal'] and first['damage'] == 0
                and first['zone'] == 'hand'
                and first['fixed_values'] == []
                and first['hit_resolution_count'] == 0
                and first['catch_resolution_count'] == 0
                and not first['interrupted']
            )
        catch_scenarios.append({
            'name': name, 'passed': bool(deterministic and outcome_ok),
            'deterministic': deterministic,
            'catch_max_speed': maximum,
            'expected_legal': expected_legal,
            **first,
        })
    catch_review = AbilityReview(
        str(catch.get('id')),
        all(item['passed'] for item in catch_scenarios), catch_scenarios,
        '' if all(item['passed'] for item in catch_scenarios)
        else '롤링 스피너의 고정 속도·사용 후 브레이크 순서 검증에 실패했습니다.',
    )
    reviewed = [hit_review, catch_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '롤링 스피너의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


