def _review_unc_at_049_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-049':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('unc-at-049-function')
    dodge_fp = by_id.get('unc-at-049-n1')
    play_condition = {
        'op': 'not_equals', 'left': 'context.use_context', 'right': 'combo',
    }
    valid = bool(
        extra_root == {'play_condition', 'defense_rules'}
        and len(abilities) == 2
        and (definition.get('source_refs') or {}).get('qna_ids') == []
        and definition.get('play_condition') == play_condition
        and definition.get('defense_rules') == [{'max_speed': 7}]
        and function and dodge_fp
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and _normalized_rule_text(
            function.get('draft_text') or function.get('label') or '',
        ) == (
            '이 기술은 7속도 이하 기술만 회피할 수 있다. '
            '이 기술은 콤보에 사용할 수 없다.'
        )
        and function.get('effects') == [
            {
                'op': 'prevent', 'kind': 'dodge',
                'player': {'controller': True}, 'duration': 'continuous',
                'condition': {
                    'op': 'gt', 'left': 'context.opponent_card.frame',
                    'right': 7,
                },
            },
            {
                'op': 'prevent', 'kind': 'combo',
                'player': {'controller': True}, 'duration': 'continuous',
            },
        ]
        and dodge_fp.get('mode') == 'mandatory'
        and dodge_fp.get('trigger') == {'event': 'dodge'}
        and _normalized_rule_text(
            dodge_fp.get('draft_text') or dodge_fp.get('label') or '',
        ) == '자신의 회피 시, 상대는 1FP를 얻는다.'
        and dodge_fp.get('effects') == [{
            'op': 'change_fp', 'player': {'opponent': True}, 'amount': 1,
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'unc-at-049', False,
                reason='메이 슬라이드의 회피 속도·콤보 금지·상대 FP 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-049 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    rule_scenarios = []
    for name, owner, speed, expected_owner, expected_opponent in (
        ('owner-p1-speed-seven-dodges', 'p1', 7, 'counter', 'countered'),
        ('owner-p2-speed-seven-dodges', 'p2', 7, 'counter', 'countered'),
        ('speed-eight-disables-dodge', 'p1', 8, 'countered', 'counter'),
    ):
        first = _run_unc_at_049_rule_scenario(
            definition, card_snapshot, owner, opponent_speed=speed,
        )
        second = _run_unc_at_049_rule_scenario(
            definition, card_snapshot, owner, opponent_speed=speed,
        )
        deterministic = _canonical(first) == _canonical(second)
        rule_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['owner_result'] == expected_owner
                and first['opponent_result'] == expected_opponent
                and first['ready_allowed'] and first['catch_allowed']
                and not first['combo_allowed']
            ),
            'deterministic': deterministic,
            'opponent_speed': speed,
            'expected_owner_result': expected_owner,
            'expected_opponent_result': expected_opponent,
            **first,
        })
    function_review = AbilityReview(
        str(function.get('id')),
        all(item['passed'] for item in rule_scenarios), rule_scenarios,
        '' if all(item['passed'] for item in rule_scenarios)
        else '메이 슬라이드의 공격 카드 회피·콤보 금지 검증에 실패했습니다.',
    )

    fp_scenarios = []
    for name, owner, event_type, expected_gain in (
        ('owner-p1-dodge-gives-opponent-one', 'p1', 'dodge', 1),
        ('owner-p2-dodge-gives-opponent-one', 'p2', 'dodge', 1),
        ('wrong-trigger-gives-no-fp', 'p1', 'hit', 0),
    ):
        first = _run_unc_at_049_fp_scenario(
            definition, dodge_fp, card_snapshot, owner, event_type,
        )
        second = _run_unc_at_049_fp_scenario(
            definition, dodge_fp, card_snapshot, owner, event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        fp_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['after_opponent_fp']
                == first['before_opponent_fp'] + expected_gain
                and first['resolved'] is (expected_gain == 1)
            ),
            'deterministic': deterministic,
            'expected_gain': expected_gain,
            **first,
        })
    fp_review = AbilityReview(
        str(dodge_fp.get('id')),
        all(item['passed'] for item in fp_scenarios), fp_scenarios,
        '' if all(item['passed'] for item in fp_scenarios)
        else '메이 슬라이드의 회피 시 상대 FP 검증에 실패했습니다.',
    )
    reviewed = [function_review, fp_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '메이 슬라이드의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


