def _review_unc_at_051_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-051':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    no_dodge = by_id.get('unc-at-051-n1')
    fourth_combo = by_id.get('unc-at-051-n2')
    qna_ids = [396]
    damage_effect = [{
        'op': 'modify_stat', 'player': {'controller': True},
        'stat': 'damage', 'amount': 200, 'duration': 'battle',
    }]
    valid = bool(
        extra_root == set()
        and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and no_dodge and fourth_combo
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and no_dodge.get('mode') == 'mandatory'
        and no_dodge.get('trigger') == {'event': 'before_judgment'}
        and no_dodge.get('condition') == {
            'op': 'not',
            'condition': {
                'op': 'card_matches',
                'card': {'path': 'context.opponent_card'},
                'where': {'battle_judgment_contains': '회피'},
            },
        }
        and no_dodge.get('effects') == damage_effect
        and fourth_combo.get('mode') == 'mandatory'
        and fourth_combo.get('trigger') == {'event': 'combo'}
        and fourth_combo.get('condition') == {
            'op': 'equals', 'left': 'context.combo_number', 'right': 4,
        }
        and fourth_combo.get('effects') == damage_effect
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'unc-at-051', False,
                reason='세츠메이 롤링의 회피 부재·4콤보 데미지 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-051 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    dodge_scenarios = []
    for name, owner, event_type, opponent_kind, expected_damage in (
        ('qna-396-attack-without-dodge', 'p1', 'before_judgment', 'attack-no-dodge', 600),
        ('attack-special-dodge-blocks-bonus', 'p2', 'before_judgment', 'attack-dodge', 400),
        ('qna-396-defense-without-dodge', 'p2', 'before_judgment', 'defense-no-dodge', 600),
        ('defense-position-dodge-blocks-bonus', 'p1', 'before_judgment', 'defense-dodge', 400),
        ('wrong-trigger-does-not-add-damage', 'p1', 'use', 'attack-no-dodge', 400),
    ):
        first = _run_unc_at_051_damage_scenario(
            definition, no_dodge, card_snapshot, owner, event_type,
            opponent_kind=opponent_kind,
        )
        second = _run_unc_at_051_damage_scenario(
            definition, no_dodge, card_snapshot, owner, event_type,
            opponent_kind=opponent_kind,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_resolution = expected_damage == 600
        dodge_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['before_damage'] == 400
                and first['after_damage'] == expected_damage
                and first['resolved'] is expected_resolution
            ),
            'deterministic': deterministic,
            'opponent_kind': opponent_kind,
            'expected_damage': expected_damage,
            'expected_resolution': expected_resolution,
            **first,
        })
    dodge_review = AbilityReview(
        str(no_dodge.get('id')),
        all(item['passed'] for item in dodge_scenarios), dodge_scenarios,
        '' if all(item['passed'] for item in dodge_scenarios)
        else '세츠메이 롤링의 회피 판정 부재·Q&A 396 검증에 실패했습니다.',
    )

    combo_scenarios = []
    for name, owner, event_type, combo_number, expected_damage in (
        ('owner-p1-fourth-combo-adds-two-hundred', 'p1', 'combo', 4, 600),
        ('owner-p2-fourth-combo-adds-two-hundred', 'p2', 'combo', 4, 600),
        ('third-combo-does-not-add-damage', 'p1', 'combo', 3, 400),
        ('wrong-trigger-does-not-add-damage', 'p1', 'hit', 4, 400),
    ):
        first = _run_unc_at_051_damage_scenario(
            definition, fourth_combo, card_snapshot, owner, event_type,
            combo_number=combo_number,
        )
        second = _run_unc_at_051_damage_scenario(
            definition, fourth_combo, card_snapshot, owner, event_type,
            combo_number=combo_number,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_resolution = expected_damage == 600
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['before_damage'] == 400
                and first['after_damage'] == expected_damage
                and first['resolved'] is expected_resolution
            ),
            'deterministic': deterministic,
            'combo_number': combo_number,
            'expected_damage': expected_damage,
            'expected_resolution': expected_resolution,
            **first,
        })
    combo_review = AbilityReview(
        str(fourth_combo.get('id')),
        all(item['passed'] for item in combo_scenarios), combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '세츠메이 롤링의 4콤보 데미지 검증에 실패했습니다.',
    )
    reviewed = [dodge_review, combo_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '세츠메이 롤링의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_unc_at_052_defense_scenario(
    definition, card_snapshot, owner, *, opponent_speed,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-air-slash-kick-defense', 'owner': owner,
        'type': '공격', 'frame': 13, 'damage': 600,
        'pos': '중단', 'special': '하단 회피', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-AIR-SLASH-KICK-OPPONENT', other,
        f'{other}-air-slash-kick-opponent',
    )
    opposing.update({
        'frame': opponent_speed, 'pos': '하단', 'damage': 500,
        'special': '', 'face_up': True,
    })
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    engine = AutomaticGameEngine(
        _state(source, opposing, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'air-slash-defense:{owner}:{opponent_speed}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {'instance_id': source['instance_id'], 'card': live_source},
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    engine._capture_battle_speed()
    engine._resolve_battle_judgment()
    return {
        'owner_result': engine.engine_state['battle']['result'][owner],
        'opponent_result': engine.engine_state['battle']['result'][other],
    }


