def _run_unc_at_052_damage_scenario(
    definition, ability, card_snapshot, owner, event_type,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-air-slash-kick-damage', 'owner': owner,
        'type': '공격', 'frame': 13, 'damage': 600,
        'special': '하단 회피', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-AIR-SLASH-KICK-OPPONENT', other,
        f'{other}-air-slash-kick-damage-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    engine = AutomaticGameEngine(
        _state(source, opposing, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'air-slash-damage:{owner}:{event_type}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    before = engine.card_stat(live_source, 'damage', owner)
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source,
        'opponent_card': engine._find_card(opposing['instance_id']),
        'combo': event_type == 'combo', 'combo_number': 5,
    })
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability.get('id')
            for event in engine.events
        ),
        'before_damage': before,
        'after_damage': engine.card_stat(live_source, 'damage', owner),
    }


def _review_unc_at_052_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-052':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    defense = by_id.get('unc-at-052-function')
    late_combo = by_id.get('unc-at-052-n1')
    damage = by_id.get('unc-at-052-n2')
    valid = bool(
        extra_root == {'combo_rules', 'defense_rules'}
        and len(abilities) == 3
        and (definition.get('source_refs') or {}).get('qna_ids') == []
        and definition.get('defense_rules') == [{
            'min_speed': 7, 'max_speed': 9,
        }]
        and definition.get('combo_rules') == [{
            'min_combo': 5, 'numbered_effect': True,
        }]
        and defense and late_combo and damage
        and defense.get('mode') == 'continuous'
        and defense.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and late_combo.get('mode') == 'mandatory'
        and late_combo.get('trigger') == {'event': 'combo'}
        and late_combo.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and damage.get('mode') == 'mandatory'
        and damage.get('trigger') == {'event': 'combo'}
        and damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': 300, 'duration': 'battle',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'unc-at-052', False,
                reason='에어 슬래시 킥의 회피 범위·5콤보·데미지 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-052 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, speed, expected_owner, expected_opponent in (
        ('owner-p1-speed-seven-lower-boundary', 'p1', 7, 'counter', 'countered'),
        ('owner-p2-speed-nine-upper-boundary', 'p2', 9, 'counter', 'countered'),
        ('speed-six-is-not-dodged', 'p1', 6, 'countered', 'counter'),
        ('speed-ten-is-not-dodged', 'p1', 10, 'countered', 'counter'),
    ):
        first = _run_unc_at_052_defense_scenario(
            definition, card_snapshot, owner, opponent_speed=speed,
        )
        second = _run_unc_at_052_defense_scenario(
            definition, card_snapshot, owner, opponent_speed=speed,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['owner_result'] == expected_owner
                and first['opponent_result'] == expected_opponent
            ),
            'deterministic': deterministic, 'opponent_speed': speed,
            'expected_owner_result': expected_owner,
            'expected_opponent_result': expected_opponent,
            **first,
        })
    defense_review = AbilityReview(
        str(defense.get('id')),
        all(item['passed'] for item in defense_scenarios), defense_scenarios,
        '' if all(item['passed'] for item in defense_scenarios)
        else '에어 슬래시 킥의 7~9속도 회피 범위 검증에 실패했습니다.',
    )

    combo_scenarios = []
    for name, owner, combo_number, expected_legal in (
        ('owner-p1-fifth-combo-is-legal', 'p1', 5, True),
        ('owner-p2-fifth-combo-is-legal', 'p2', 5, True),
        ('fourth-combo-is-too-early', 'p1', 4, False),
    ):
        first = _run_unc_at_052_combo_rule_scenario(
            definition, card_snapshot, owner, combo_number=combo_number,
        )
        second = _run_unc_at_052_combo_rule_scenario(
            definition, card_snapshot, owner, combo_number=combo_number,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['legal'] is expected_legal
                and first['maximum'] is None
                and first['rules'] == [{
                    'min_combo': 5, 'numbered_effect': True,
                }]
            ),
            'deterministic': deterministic,
            'combo_number': combo_number, 'expected_legal': expected_legal,
            **first,
        })
    combo_review = AbilityReview(
        str(late_combo.get('id')),
        all(item['passed'] for item in combo_scenarios), combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '에어 슬래시 킥의 5콤보 합법 행동 검증에 실패했습니다.',
    )

    damage_scenarios = []
    for name, owner, event_type, expected_damage in (
        ('owner-p1-combo-adds-three-hundred', 'p1', 'combo', 900),
        ('owner-p2-combo-adds-three-hundred', 'p2', 'combo', 900),
        ('wrong-trigger-keeps-printed-damage', 'p1', 'hit', 600),
    ):
        first = _run_unc_at_052_damage_scenario(
            definition, damage, card_snapshot, owner, event_type,
        )
        second = _run_unc_at_052_damage_scenario(
            definition, damage, card_snapshot, owner, event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['before_damage'] == 600
                and first['after_damage'] == expected_damage
                and first['resolved'] is (event_type == 'combo')
            ),
            'deterministic': deterministic,
            'expected_damage': expected_damage,
            **first,
        })
    damage_review = AbilityReview(
        str(damage.get('id')),
        all(item['passed'] for item in damage_scenarios), damage_scenarios,
        '' if all(item['passed'] for item in damage_scenarios)
        else '에어 슬래시 킥의 콤보 데미지 검증에 실패했습니다.',
    )
    reviewed = [defense_review, combo_review, damage_review]
    passed = all(item.passed for item in reviewed)
    return DefinitionReview(
        passed, False, reviewed,
        '' if passed else '에어 슬래시 킥의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _unc_at_053_engine(
    definition, card_snapshot, owner, *, source_zone='lumen', hp=4000,
    copies=1, phase='lumen', with_ready_card=False, fighting_spirit=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-fighting-spirit-1', 'owner': owner,
        'type': '특수', 'frame': None, 'damage': None, 'face_up': True,
    })
    opposing = _card(
        'REVIEW-FIGHTING-SPIRIT-OPPONENT', other,
        f'{other}-fighting-spirit-opponent',
    )
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = phase
    state['players'][owner]['hp'] = hp
    sources = [source]
    for index in range(2, copies + 1):
        extra = copy.deepcopy(source)
        extra['instance_id'] = f'{owner}-fighting-spirit-{index}'
        state['players'][owner]['zones'][source_zone].append(extra)
        sources.append(extra)
    ready_card = None
    if with_ready_card:
        ready_card = _card(
            'REVIEW-FIGHTING-SPIRIT-READY', owner,
            f'{owner}-fighting-spirit-ready',
        )
        ready_card.update({'frame': 6, 'damage': 400, 'face_up': True})
        state['players'][owner]['zones']['battle'] = [copy.deepcopy(ready_card)]
    if fighting_spirit:
        state['players'][owner]['passive_state']['fighting_spirit'] = {
            'value': True, 'label': '기합', 'owner': owner,
        }
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []}, 'abilities': [],
    }
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if ready_card:
        cards[ready_card['code']] = {
            **copy.deepcopy(ready_card), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'fighting-spirit:{owner}:{source_zone}:{hp}:{copies}:{phase}:'
            f'{with_ready_card}:{fighting_spirit}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, sources, ready_card


def _resolve_unc_at_053_decisions(engine, *, accept=True):
    kinds = []
    for _index in range(20):
        decision = engine.engine_state.get('pending_decision') or {}
        if not decision:
            break
        kind = decision.get('kind')
        kinds.append(kind)
        options = [str(item.get('id')) for item in decision.get('options') or []]
        if kind == 'effect_order':
            selected = list(decision.get('default') or options[:1])[:1]
        elif kind == 'optional_effect':
            selected = ['accept' if accept else 'decline']
        else:
            break
        engine._submit_decision(decision.get('owner'), decision.get('id'), selected)
        engine._continue()
    return kinds


def _run_unc_at_053_deploy_scenario(
    definition, card_snapshot, owner, *, hp, accept, phase='recovery',
):
    engine, sources, _ready = _unc_at_053_engine(
        definition, card_snapshot, owner, source_zone='side', hp=hp, phase=phase,
    )
    engine._fire('phase_start', {'phase': phase})
    kinds = _resolve_unc_at_053_decisions(engine, accept=accept)
    instance_id = sources[0]['instance_id']
    return {
        'decision_kinds': kinds,
        'in_side': engine._find_card(instance_id, owner=owner, zone='side') is not None,
        'in_lumen': engine._find_card(instance_id, owner=owner, zone='lumen') is not None,
        'decision_visibility': next((
            (event.get('visibility') or '')
            for event in engine.events if event.get('type') == 'decision_requested'
        ), None),
    }


def _run_unc_at_053_enter_scenario(
    definition, card_snapshot, owner, *, accept, copies=1, phase='lumen',
    after=None,
):
    engine, sources, _ready = _unc_at_053_engine(
        definition, card_snapshot, owner, copies=copies, phase=phase,
    )
    engine._fire('phase_start', {'phase': phase})
    kinds = _resolve_unc_at_053_decisions(engine, accept=accept)
    resolved_count = sum(
        event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id')
        == 'unc-at-053-fighting-spirit-enter'
        for event in engine.events
    )
    if after == 'ready_restart':
        engine.state['phase'] = 'battle'
        engine.restart_phase_without_ending_battle('ready')
    elif after == 'battle_end':
        engine.state['phase'] = 'battle'
        engine._fire('battle_end', {})
    return {
        'decision_kinds': kinds,
        'state': bool(
            engine.state['players'][owner].get('passive_state', {})
            .get('fighting_spirit', {}).get('value')
        ),
        'scheduled_battle_end': sum(
            (item.get('when') or {}).get('event') == 'battle_end'
            for item in engine.engine_state.get('scheduled') or []
        ),
        'scheduled_turn_start': sum(
            (item.get('when') or {}).get('event') == 'turn_start'
            for item in engine.engine_state.get('scheduled') or []
        ),
        'card_stays_lumen': engine._find_card(
            sources[0]['instance_id'], owner=owner, zone='lumen',
        ) is not None,
        'phase_after': engine.state.get('phase'),
        'usage': (
            engine.engine_state.get('usage', {}).get('turn', {})
            .get(owner, {}).get('unc-at-053-fighting-spirit-enter', 0)
        ),
        'resolved_count': resolved_count,
    }


def _run_unc_at_053_ready_scenario(
    definition, card_snapshot, owner, *, fighting_spirit=True, event_type='use',
    combo=False, catch=False, copies=1, fixed_speed=None,
):
    engine, _sources, ready_card = _unc_at_053_engine(
        definition, card_snapshot, owner, copies=copies,
        with_ready_card=True, fighting_spirit=fighting_spirit, phase='battle',
    )
    live_ready = engine._find_card(ready_card['instance_id'])
    if fixed_speed is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'stat': 'frame', 'value': fixed_speed,
            'player': owner, 'where': {'instance_id': ready_card['instance_id']},
            'duration': 'battle',
        })
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': ready_card['instance_id'],
        'source_card': live_ready, 'combo': combo, 'catch': catch,
    })
    kinds = _resolve_unc_at_053_decisions(engine)
    return {
        'decision_kinds': kinds,
        'damage': engine.card_stat(live_ready, 'damage', owner),
        'frame': engine.card_stat(live_ready, 'frame', owner),
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'unc-at-053-fighting-spirit-ready-use'
            for event in engine.events
        ),
    }


def _run_unc_at_053_lost_scenario(
    definition, card_snapshot, owner, *, state='fighting_spirit', player=None,
    lifecycle=False,
):
    engine, sources, _ready = _unc_at_053_engine(
        definition, card_snapshot, owner, fighting_spirit=True,
    )
    player = player or owner
    engine._fire('state_lost', {
        'controller': player, 'player': player, 'state': state,
    })
    scheduled_turn_start = sum(
        (item.get('when') or {}).get('event') == 'turn_start'
        for item in engine.engine_state.get('scheduled') or []
    )
    blocked_next_turn = False
    offered_following_turn = False
    if lifecycle:
        engine._reset_usage('turn')
        engine._fire('turn_start', {'turn': 2})
        engine.state['phase'] = 'lumen'
        engine._fire('phase_start', {'phase': 'lumen'})
        blocked_next_turn = not bool(engine.engine_state.get('pending_decision'))
        engine._reset_usage('turn')
        engine._fire('turn_start', {'turn': 3})
        engine._fire('phase_start', {'phase': 'lumen'})
        offered_following_turn = (
            (engine.engine_state.get('pending_decision') or {}).get('kind')
            == 'optional_effect'
        )
    return {
        'scheduled_turn_start': scheduled_turn_start,
        'card_stays_lumen': engine._find_card(
            sources[0]['instance_id'], owner=owner, zone='lumen',
        ) is not None,
        'blocked_next_turn': blocked_next_turn,
        'offered_following_turn': offered_following_turn,
    }


def _review_unc_at_053_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-053':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    deploy = by_id.get('unc-at-053-side-deploy')
    enter = by_id.get('unc-at-053-fighting-spirit-enter')
    ready = by_id.get('unc-at-053-fighting-spirit-ready-use')
    lost = by_id.get('unc-at-053-fighting-spirit-lost')
    expected_qnas = [71, 72, 373, 378, 386, 404, 615, 658]
    valid = bool(
        extra_root == set() and len(abilities) == 4
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == expected_qnas
        and (definition.get('source_refs') or {}).get('general_qna_ids') == [597]
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == expected_qnas
            and (ability.get('source_refs') or {}).get('general_qna_ids') == [597]
            for ability in abilities
        )
        and deploy and deploy.get('mode') == 'optional'
        and deploy.get('visibility') == 'private'
        and deploy.get('active_zones') == ['side']
        and deploy.get('trigger') == {'event': 'phase_start'}
        and deploy.get('condition') == {
            'op': 'all', 'conditions': [
                {'op': 'phase_is', 'phase': 'recovery'},
                {'op': 'lte', 'left': 'context.controller_hp', 'right': 1500},
            ],
        }
        and deploy.get('effects') == [{'op': 'move_card', 'to_zone': 'lumen'}]
        and enter and enter.get('mode') == 'optional'
        and enter.get('active_zones') == ['lumen']
        and enter.get('condition') == {'op': 'phase_is', 'phase': 'lumen'}
        and enter.get('limit') == {
            'scope': 'turn', 'max': 99,
            'key': 'unc-at-053-fighting-spirit-enter',
        }
        and ready and ready.get('mode') == 'mandatory'
        and ready.get('active_zones') == ['lumen']
        and ready.get('trigger') == {'event': 'use'}
        and ready.get('effects') == [
            {
                'op': 'modify_stat', 'player': {'controller': True},
                'stat': 'damage', 'amount': 100, 'duration': 'battle',
                'target_card': 'event_card',
            },
            {
                'op': 'modify_stat', 'player': {'controller': True},
                'stat': 'frame', 'amount': 1, 'duration': 'battle',
                'target_card': 'event_card',
            },
        ]
        and lost and lost.get('mode') == 'mandatory'
        and lost.get('active_zones') == ['lumen']
        and lost.get('trigger') == {'event': 'state_lost'}
        and lost.get('effects') == [{
            'op': 'schedule', 'when': {'event': 'turn_start'},
            'duration': 'game',
            'effect': {
                'op': 'set_usage_limit', 'scope': 'turn',
                'key': 'unc-at-053-fighting-spirit-enter', 'value': 99,
            },
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'unc-at-053', False,
                reason='기합의 배치·상태·수치·쿨다운 정의 또는 Q&A 출처가 일치하지 않습니다.',
            )],
            'UNC-AT-053 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    reviews = []
    deploy_scenarios = []
    for name, owner, hp, accept, expected_lumen in (
        ('owner-p1-hp-boundary-deploys', 'p1', 1500, True, True),
        ('owner-p2-below-boundary-deploys', 'p2', 1499, True, True),
        ('above-hp-boundary-is-not-offered', 'p1', 1501, True, False),
        ('optional-decline-stays-in-side', 'p1', 1000, False, False),
    ):
        first = _run_unc_at_053_deploy_scenario(
            definition, card_snapshot, owner, hp=hp, accept=accept,
        )
        second = _run_unc_at_053_deploy_scenario(
            definition, card_snapshot, owner, hp=hp, accept=accept,
        )
        deterministic = _canonical(first) == _canonical(second)
        offered = hp <= 1500
        deploy_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['in_lumen'] is expected_lumen
                and first['in_side'] is (not expected_lumen)
                and (('optional_effect' in first['decision_kinds']) is offered)
            ),
            'deterministic': deterministic, 'hp': hp, 'accepted': accept,
            'expected_lumen': expected_lumen, **first,
        })
    reviews.append(AbilityReview(
        deploy['id'], all(item['passed'] for item in deploy_scenarios),
        deploy_scenarios,
        '' if all(item['passed'] for item in deploy_scenarios)
        else '기합의 리커버리 사이드 덱 배치 검증에 실패했습니다.',
    ))

    enter_scenarios = []
    for (
        name, owner, accept, copies, phase, after, expected_state,
        expected_count, expected_battle_end,
    ) in (
        ('owner-p1-enters-fighting-spirit', 'p1', True, 1, 'lumen', None, True, 1, 1),
        ('owner-p2-enters-fighting-spirit', 'p2', True, 1, 'lumen', None, True, 1, 1),
        ('optional-decline-does-not-enter', 'p1', False, 1, 'lumen', None, False, 0, 0),
        ('qna-71-two-copies-resolve-by-chosen-order', 'p1', True, 2, 'lumen', None, True, 2, 2),
        ('qna-404-ready-restart-preserves-state', 'p1', True, 1, 'lumen', 'ready_restart', True, 1, 1),
        ('battle-end-releases-state-and-keeps-card', 'p1', True, 1, 'lumen', 'battle_end', False, 1, 0),
        ('wrong-phase-is-not-offered', 'p1', True, 1, 'recovery', None, False, 0, 0),
    ):
        first = _run_unc_at_053_enter_scenario(
            definition, card_snapshot, owner, accept=accept,
            copies=copies, phase=phase, after=after,
        )
        second = _run_unc_at_053_enter_scenario(
            definition, card_snapshot, owner, accept=accept,
            copies=copies, phase=phase, after=after,
        )
        deterministic = _canonical(first) == _canonical(second)
        order_ok = copies == 1 or 'effect_order' in first['decision_kinds']
        after_ok = bool(
            (after != 'ready_restart' or first['phase_after'] == 'ready')
            and (after != 'battle_end' or first['scheduled_turn_start'] == 1)
            and first['card_stays_lumen']
        )
        enter_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['state'] is expected_state
                and first['resolved_count'] == expected_count
                and first['scheduled_battle_end'] == expected_battle_end
                and order_ok and after_ok
            ),
            'deterministic': deterministic, 'accepted': accept,
            'copies': copies, 'phase': phase, 'after': after,
            'expected_resolved_count': expected_count, **first,
        })
    reviews.append(AbilityReview(
        enter['id'], all(item['passed'] for item in enter_scenarios),
        enter_scenarios,
        '' if all(item['passed'] for item in enter_scenarios)
        else '기합 상태 부여·복수 카드 순서 선택 검증에 실패했습니다.',
    ))

    ready_scenarios = []
    for (
        name, owner, state_active, combo, catch, copies, fixed_speed,
        expected_damage, expected_frame, expected_count,
    ) in (
        ('owner-p1-ready-use-modifies-card', 'p1', True, False, False, 1, None, 500, 7, 1),
        ('owner-p2-ready-use-modifies-card', 'p2', True, False, False, 1, None, 500, 7, 1),
        ('without-state-keeps-printed-stats', 'p1', False, False, False, 1, None, 400, 6, 0),
        ('combo-is-not-ready-technique', 'p1', True, True, False, 1, None, 400, 6, 0),
        ('catch-is-not-ready-technique', 'p1', True, False, True, 1, None, 400, 6, 0),
        ('qna-71-two-copies-stack', 'p1', True, False, False, 2, None, 600, 8, 2),
        ('qna-658-fixed-speed-ignores-slowing', 'p1', True, False, False, 1, 5, 500, 5, 1),
    ):
        first = _run_unc_at_053_ready_scenario(
            definition, card_snapshot, owner, fighting_spirit=state_active,
            combo=combo, catch=catch, copies=copies, fixed_speed=fixed_speed,
        )
        second = _run_unc_at_053_ready_scenario(
            definition, card_snapshot, owner, fighting_spirit=state_active,
            combo=combo, catch=catch, copies=copies, fixed_speed=fixed_speed,
        )
        deterministic = _canonical(first) == _canonical(second)
        ready_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['damage'] == expected_damage
                and first['frame'] == expected_frame
                and first['resolved_count'] == expected_count
            ),
            'deterministic': deterministic, 'state_active': state_active,
            'combo': combo, 'catch': catch, 'copies': copies,
            'fixed_speed': fixed_speed, 'expected_damage': expected_damage,
            'expected_frame': expected_frame, **first,
        })
    reviews.append(AbilityReview(
        ready['id'], all(item['passed'] for item in ready_scenarios),
        ready_scenarios,
        '' if all(item['passed'] for item in ready_scenarios)
        else '기합 상태의 레디 기술 데미지·속도 검증에 실패했습니다.',
    ))

    lost_scenarios = []
    for name, owner, state_key, player, lifecycle, expected_schedule in (
        ('owner-p1-loss-schedules-next-turn-lock', 'p1', 'fighting_spirit', 'p1', True, 1),
        ('owner-p2-loss-schedules-next-turn-lock', 'p2', 'fighting_spirit', 'p2', True, 1),
        ('other-state-does-not-schedule', 'p1', 'charge', 'p1', False, 0),
        ('opponent-state-loss-does-not-schedule', 'p1', 'fighting_spirit', 'p2', False, 0),
    ):
        first = _run_unc_at_053_lost_scenario(
            definition, card_snapshot, owner, state=state_key,
            player=player, lifecycle=lifecycle,
        )
        second = _run_unc_at_053_lost_scenario(
            definition, card_snapshot, owner, state=state_key,
            player=player, lifecycle=lifecycle,
        )
        deterministic = _canonical(first) == _canonical(second)
        lifecycle_ok = not lifecycle or (
            first['blocked_next_turn'] and first['offered_following_turn']
        )
        lost_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['scheduled_turn_start'] == expected_schedule
                and first['card_stays_lumen'] and lifecycle_ok
            ),
            'deterministic': deterministic, 'state': state_key,
            'event_player': player, 'lifecycle': lifecycle,
            'expected_schedule': expected_schedule, **first,
        })
    reviews.append(AbilityReview(
        lost['id'], all(item['passed'] for item in lost_scenarios),
        lost_scenarios,
        '' if all(item['passed'] for item in lost_scenarios)
        else '기합 해제 후 다음 턴 사용 금지 검증에 실패했습니다.',
    ))

    passed = all(item.passed for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '기합의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


