def _st1_001_fixture_card(
    code, owner, instance_id, *, face_up=True, card_type='공격', token=False,
):
    if token:
        return {
            'instance_id': instance_id, 'kind': 'token', 'owner': owner,
            'code': code, 'name': code, 'type': '', 'face_up': face_up,
        }
    card = _card(code, owner, instance_id)
    card['type'] = card_type
    card['face_up'] = face_up
    if not face_up:
        # Q&A 544: Secret Time's face-down card is not known to be a
        # Technique and therefore cannot be selected by Lap Cats.
        card['non_technique_while_face_down'] = True
    if card_type == '수비':
        card.update({'frame': None, 'damage': None, 'g_top': '방어'})
    elif card_type == '특수':
        card.update({'frame': None, 'damage': None})
    return card


def _run_st1_001_scenario(
    definition, card_snapshot, owner, *, fixture, over_limit=False,
    event_type='after_use', result='hit', selected_index=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-lap-cats', 'owner': owner,
        'type': '공격', 'frame': 5, 'damage': 400, 'face_up': True,
    })
    opposing = _card(
        'REVIEW-LAP-CATS-OPPONENT', other, f'{other}-lap-cats-opponent',
    )
    list_cards = []
    lumen_cards = []
    include_passive = False
    hidden_id = None
    token_id = None
    if fixture == 'list-multiple':
        list_cards = [
            _st1_001_fixture_card(
                'REVIEW-LAP-CATS-LIST-A', owner, f'{owner}-list-a',
            ),
            _st1_001_fixture_card(
                'REVIEW-LAP-CATS-LIST-B', owner, f'{owner}-list-b',
                card_type='수비',
            ),
        ]
    elif fixture == 'list-single':
        list_cards = [_st1_001_fixture_card(
            'REVIEW-LAP-CATS-LIST-A', owner, f'{owner}-list-a',
        )]
    elif fixture == 'list-token-only':
        token_id = f'{owner}-list-token'
        list_cards = [_st1_001_fixture_card(
            'REVIEW-LAP-CATS-LIST-TOKEN', owner, token_id, token=True,
        )]
    elif fixture == 'qna-650-state-change':
        list_cards = [_st1_001_fixture_card(
            'REVIEW-LAP-CATS-FOURTH', owner, f'{owner}-fourth-technique',
        )]
        lumen_cards = [
            _st1_001_fixture_card(
                f'REVIEW-LAP-CATS-LUMEN-{index}', owner,
                f'{owner}-existing-lumen-{index}',
            )
            for index in range(3)
        ]
        include_passive = True
    elif fixture == 'lumen-mixed':
        hidden_id = f'{owner}-hidden-technique'
        token_id = f'{owner}-lumen-token'
        lumen_cards = [
            _st1_001_fixture_card(
                'REVIEW-LAP-CATS-LUMEN-A', owner, f'{owner}-lumen-a',
            ),
            _st1_001_fixture_card(
                'REVIEW-LAP-CATS-LUMEN-B', owner, f'{owner}-lumen-b',
                card_type='수비',
            ),
            _st1_001_fixture_card(
                'REVIEW-LAP-CATS-HIDDEN', owner, hidden_id, face_up=False,
            ),
            _st1_001_fixture_card(
                'REVIEW-LAP-CATS-LUMEN-TOKEN', owner, token_id, token=True,
            ),
        ]
    elif fixture == 'lumen-single':
        lumen_cards = [_st1_001_fixture_card(
            'REVIEW-LAP-CATS-LUMEN-A', owner, f'{owner}-lumen-a',
        )]
    elif fixture == 'lumen-hidden-only':
        hidden_id = f'{owner}-hidden-technique'
        lumen_cards = [_st1_001_fixture_card(
            'REVIEW-LAP-CATS-HIDDEN', owner, hidden_id, face_up=False,
        )]
    else:
        raise EffectSandboxError(f'알 수 없는 랩 캐츠 검수 fixture: {fixture}')

    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['list'] = copy.deepcopy(list_cards)
    state['players'][owner]['zones']['lumen'] = copy.deepcopy(lumen_cards)
    if over_limit:
        state['players'][owner]['passive_state']['over_limit'] = {
            'value': True, 'label': '오버 리미트',
        }
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': copy.deepcopy(no_effect),
        },
    }
    for card in [*list_cards, *lumen_cards]:
        cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(no_effect),
        }
    if include_passive:
        passive = {
            'instance_id': f'{owner}-over-limit-passive',
            'kind': 'card', 'owner': owner,
            'code': 'REVIEW-ST1-PS1', 'name': '오버 리미트',
            'type': '특성', 'face_up': True,
        }
        state['players'][owner]['zones']['passive'] = [copy.deepcopy(passive)]
        cards[passive['code']] = {
            **copy.deepcopy(passive),
            'effect_definition': _st1_001_over_limit_definition(),
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'lap-cats:{owner}:{fixture}:{over_limit}:{event_type}:'
            f'{result}:{selected_index}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source, 'event_card': live_source,
        'battle_result': result,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    option_ids = [
        str(option.get('id')) for option in (decision or {}).get('options') or []
    ]
    selected_id = None
    if decision and option_ids:
        selected_id = option_ids[min(selected_index, len(option_ids) - 1)]
        engine._submit_decision(owner, decision.get('id'), [selected_id])
        engine._continue()

    def zone_of(instance_id):
        if not instance_id:
            return None
        _side, zone, _index, _card_value = engine._find_location(instance_id)
        return zone

    def face_up_of(instance_id):
        card = engine._find_card(instance_id) if instance_id else None
        return bool(card and card.get('face_up'))

    resolution_counts = {
        ability_id: sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability_id
            for event in engine.events
        )
        for ability_id in ('st1-001-n1', 'st1-001-n2')
    }
    return {
        'decision_kind': (decision or {}).get('kind'),
        'decision_owner': (decision or {}).get('owner'),
        'minimum': int((decision or {}).get('minimum') or 0),
        'maximum': int((decision or {}).get('maximum') or 0),
        'option_ids': option_ids, 'selected_id': selected_id,
        'selected_zone': zone_of(selected_id),
        'selected_face_up': face_up_of(selected_id),
        'hidden_offered': bool(hidden_id and hidden_id in option_ids),
        'token_offered': bool(token_id and token_id in option_ids),
        'over_limit_after': bool(
            engine.state['players'][owner].get('passive_state', {})
            .get('over_limit', {}).get('value')
        ),
        'resolution_counts': resolution_counts,
        'pending': bool(engine.engine_state.get('pending_decision')),
        'move_count': sum(
            event.get('type') == 'card_moved'
            for event in engine.events
        ),
    }


def _review_st1_001_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-001':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    without_over_limit = by_id.get('st1-001-n1')
    with_over_limit = by_id.get('st1-001-n2')
    qna_ids = [328, 544, 650]
    list_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['list'], 'min': 1, 'max': 1,
        'where': {'is_technique': True},
    }
    lumen_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['lumen'], 'min': 1, 'max': 1,
        'where': {'is_technique': True, 'face_up': True},
    }
    expected_without_effects = [{
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '루멘 존으로 이동할 리스트의 기술을 선택하세요.',
        'selector': list_selector,
        'selection_key': 'st1_001_list_to_lumen', 'default': [],
        'then': [{
            'op': 'move_card',
            'selection_key': 'st1_001_list_to_lumen',
            'to_zone': 'lumen',
        }],
    }]
    expected_with_effects = [{
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '리스트로 이동할 앞면 루멘 존 기술을 선택하세요.',
        'selector': lumen_selector,
        'selection_key': 'st1_001_lumen_to_list', 'default': [],
        'then': [{
            'op': 'move_card',
            'selection_key': 'st1_001_lumen_to_list',
            'to_zone': 'list',
        }],
    }]
    valid = bool(
        extra_root == set() and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids
            for ability in abilities
        )
        and without_over_limit
        and without_over_limit.get('mode') == 'mandatory'
        and without_over_limit.get('active_zones') == ['battle']
        and without_over_limit.get('trigger') == {'event': 'after_use'}
        and without_over_limit.get('condition') == {
            'op': 'not', 'condition': {
                'op': 'has_state', 'player': {'controller': True},
                'state': 'over_limit',
            },
        }
        and without_over_limit.get('availability_selector') == list_selector
        and without_over_limit.get('effects') == expected_without_effects
        and with_over_limit
        and with_over_limit.get('mode') == 'mandatory'
        and with_over_limit.get('active_zones') == ['battle']
        and with_over_limit.get('trigger') == {'event': 'after_use'}
        and with_over_limit.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'over_limit',
        }
        and with_over_limit.get('availability_selector') == lumen_selector
        and with_over_limit.get('effects') == expected_with_effects
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'st1-001', False,
                reason='랩 캐츠의 상태별 강제 선택·앞면 기술 정의가 일치하지 않습니다.',
            )],
            'ST1-001 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    without_scenarios = []
    for (
        name, owner, fixture, event_type, result, selected_index,
        expected_options, expected_zone, expected_state, expected_n1,
    ) in (
        ('owner-p1-selects-second-list-technique', 'p1', 'list-multiple', 'after_use', 'hit', 1, 2, 'lumen', False, 1),
        ('qna-328-owner-p2-dodged-still-moves', 'p2', 'list-single', 'after_use', 'dodged', 0, 1, 'lumen', False, 1),
        ('qna-328-clashed-still-moves', 'p1', 'list-single', 'after_use', 'clash', 0, 1, 'lumen', False, 1),
        ('token-only-list-has-no-legal-candidate', 'p1', 'list-token-only', 'after_use', 'hit', 0, 0, None, False, 0),
        ('qna-650-state-change-does-not-replay-second-effect', 'p1', 'qna-650-state-change', 'after_use', 'hit', 0, 1, 'lumen', True, 1),
        ('wrong-trigger-does-not-move', 'p1', 'list-single', 'after_judgment', 'hit', 0, 0, None, False, 0),
    ):
        first = _run_st1_001_scenario(
            definition, card_snapshot, owner, fixture=fixture,
            event_type=event_type, result=result, selected_index=selected_index,
        )
        second = _run_st1_001_scenario(
            definition, card_snapshot, owner, fixture=fixture,
            event_type=event_type, result=result, selected_index=selected_index,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_decision = expected_options > 0
        without_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and len(first['option_ids']) == expected_options
                and (first['decision_kind'] == 'effect_choice') is expected_decision
                and first['decision_owner'] == (owner if expected_decision else None)
                and first['selected_zone'] == expected_zone
                and (expected_zone != 'lumen' or first['selected_face_up'])
                and first['over_limit_after'] is expected_state
                and first['resolution_counts']['st1-001-n1'] == expected_n1
                and first['resolution_counts']['st1-001-n2'] == 0
                and not first['token_offered'] and not first['pending']
            ),
            'deterministic': deterministic, 'fixture': fixture,
            'event_type': event_type, 'battle_result': result,
            'expected_options': expected_options,
            'expected_zone': expected_zone, **first,
        })
    without_review = AbilityReview(
        without_over_limit['id'],
        all(item['passed'] for item in without_scenarios),
        without_scenarios,
        '' if all(item['passed'] for item in without_scenarios)
        else '랩 캐츠의 비 오버 리미트 선택·Q&A 328/650 검증에 실패했습니다.',
    )

    with_scenarios = []
    for (
        name, owner, fixture, state_active, event_type, result,
        selected_index, expected_options, expected_zone, expected_n2,
    ) in (
        ('owner-p1-selects-second-face-up-technique', 'p1', 'lumen-mixed', True, 'after_use', 'hit', 1, 2, 'list', 1),
        ('qna-328-owner-p2-guarded-still-moves', 'p2', 'lumen-single', True, 'after_use', 'guarded', 0, 1, 'list', 1),
        ('qna-328-countered-still-moves', 'p1', 'lumen-single', True, 'after_use', 'countered', 0, 1, 'list', 1),
        ('qna-544-face-down-card-is-not-selectable', 'p1', 'lumen-hidden-only', True, 'after_use', 'hit', 0, 0, None, 0),
        ('without-state-second-effect-is-not-collected', 'p1', 'lumen-single', False, 'after_use', 'hit', 0, 0, None, 0),
        ('wrong-trigger-does-not-move', 'p2', 'lumen-single', True, 'before_judgment', 'hit', 0, 0, None, 0),
    ):
        first = _run_st1_001_scenario(
            definition, card_snapshot, owner, fixture=fixture,
            over_limit=state_active, event_type=event_type,
            result=result, selected_index=selected_index,
        )
        second = _run_st1_001_scenario(
            definition, card_snapshot, owner, fixture=fixture,
            over_limit=state_active, event_type=event_type,
            result=result, selected_index=selected_index,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_decision = expected_options > 0
        with_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and len(first['option_ids']) == expected_options
                and (first['decision_kind'] == 'effect_choice') is expected_decision
                and first['decision_owner'] == (owner if expected_decision else None)
                and first['selected_zone'] == expected_zone
                and first['resolution_counts']['st1-001-n1'] == 0
                and first['resolution_counts']['st1-001-n2'] == expected_n2
                and not first['hidden_offered'] and not first['token_offered']
                and not first['pending']
            ),
            'deterministic': deterministic, 'fixture': fixture,
            'state_active': state_active, 'event_type': event_type,
            'battle_result': result, 'expected_options': expected_options,
            'expected_zone': expected_zone, **first,
        })
    with_review = AbilityReview(
        with_over_limit['id'],
        all(item['passed'] for item in with_scenarios),
        with_scenarios,
        '' if all(item['passed'] for item in with_scenarios)
        else '랩 캐츠의 오버 리미트 선택·앞면 기술 검증에 실패했습니다.',
    )
    reviews = [without_review, with_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '랩 캐츠의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st1_002_engine(
    definition, card_snapshot, owner, *, source_zone='battle',
    over_limit=False, owner_fp=0, opponent_fp=0,
    opponent_type='공격', opponent_body='손', opponent_speed=7,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-cats-muffins', 'owner': owner,
        'type': '공격', 'frame': 6, 'damage': 400,
        'body': '손', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-CATS-MUFFINS-OPPONENT', other,
        f'{other}-cats-muffins-opponent',
    )
    opposing.update({
        'type': opponent_type, 'body': opponent_body,
        'frame': opponent_speed, 'face_up': True,
    })
    if opponent_type == '수비':
        opposing.update({'damage': None, 'g_top': '방어'})
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['players'][owner]['fp'] = owner_fp
    state['players'][other]['fp'] = opponent_fp
    if over_limit:
        state['players'][owner]['passive_state']['over_limit'] = {
            'value': True, 'label': '오버 리미트',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state, {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': copy.deepcopy(no_effect),
                },
            },
        },
        seed=(
            f'cats-muffins:{owner}:{source_zone}:{over_limit}:{owner_fp}:'
            f'{opponent_fp}:{opponent_type}:{opponent_body}:{opponent_speed}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, source, opposing


def _run_st1_002_combo_scenario(
    definition, card_snapshot, owner, *, over_limit, damage_bonus=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, _opposing = _st1_002_engine(
        definition, card_snapshot, owner,
        source_zone='hand', over_limit=over_limit,
    )
    opener = _card(
        'REVIEW-CATS-MUFFINS-OPENER', owner,
        f'{owner}-cats-muffins-opener',
    )
    opener.update({'frame': 5, 'damage': 500, 'face_up': True})
    engine.state['players'][owner]['zones']['battle'] = [copy.deepcopy(opener)]
    engine.ruleset['cards'][opener['code']] = {
        **copy.deepcopy(opener),
        'effect_definition': _st1_001_no_effect_definition(),
    }
    if damage_bonus:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': opener['instance_id'], 'stat': 'damage',
            'amount': damage_bonus, 'duration': 'battle',
            'where': {'instance_id': source['instance_id']},
        })
    engine._refresh_continuous_rules()
    live_source = engine._find_card(source['instance_id'])
    combo = {
        'owner': owner, 'source': opener['instance_id'], 'used': [],
        'last_speed': 5, 'next_penalty': 100,
    }
    damage = engine.card_stat(live_source, 'damage', owner)
    return {
        'damage': damage, 'penalty': 100,
        'final_damage': damage - 100,
        'legal': engine._combo_card_legal(owner, live_source, combo),
        'modifier_count': sum(
            modifier.get('stat') == 'damage'
            and (modifier.get('where') or {}).get('instance_id')
            == source['instance_id']
            for modifier in engine.engine_state.get('modifiers') or []
        ),
        'other_player': other,
    }


def _run_st1_002_fp_scenario(
    definition, card_snapshot, owner, *, event_type='before_judgment',
    owner_fp=1, opponent_fp=0, opponent_type='공격', opponent_body='손',
    opponent_speed=7, opponent_speed_delta=0, opponent_fixed_speed=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st1_002_engine(
        definition, card_snapshot, owner,
        owner_fp=owner_fp, opponent_fp=opponent_fp,
        opponent_type=opponent_type, opponent_body=opponent_body,
        opponent_speed=opponent_speed,
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'], 'card': live_source,
        },
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    if opponent_speed_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': other, 'player': other,
            'source': opposing['instance_id'], 'stat': 'frame',
            'amount': opponent_speed_delta, 'duration': 'battle',
            'where': {'instance_id': opposing['instance_id']},
        })
    if opponent_fixed_speed is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': other,
            'source': opposing['instance_id'], 'stat': 'frame',
            'value': opponent_fixed_speed, 'duration': 'battle',
            'where': {'instance_id': opposing['instance_id']},
        })
    engine._refresh_continuous_rules()
    reference_before = engine.card_stat(
        live_opposing, 'frame', other, include_fp=False,
    )
    engine._battle_trigger(event_type)
    engine._capture_battle_speed()
    battle = engine.engine_state['battle']
    return {
        'owner_fp_before': owner_fp,
        'owner_fp_after': engine.state['players'][owner]['fp'],
        'opponent_fp': opponent_fp,
        'opponent_reference_before': reference_before,
        'owner_reference_speed': battle['reference_speed'][owner],
        'opponent_reference_speed': battle['reference_speed'][other],
        'owner_final_speed': battle['speed'][owner],
        'opponent_final_speed': battle['speed'][other],
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st1-002-n2'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st1_002_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-002':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    damage_down = by_id.get('st1-002-n1')
    fp_gain = by_id.get('st1-002-n2')
    qna_ids = [235, 322]
    damage_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'over_limit',
    }
    damage_effects = [{
        'op': 'modify_stat', 'player': {'controller': True},
        'stat': 'damage', 'amount': -300, 'duration': 'continuous',
    }]
    fp_condition = {
        'op': 'all', 'conditions': [
            {
                'op': 'card_matches',
                'card': {'path': 'context.opponent_card'},
                'where': {'type_contains': '공격', 'body': '손'},
            },
            {
                'op': 'lte', 'left': 'context.opponent_speed',
                'right': 7,
            },
        ],
    }
    fp_effects = [{
        'op': 'change_fp', 'player': {'controller': True}, 'amount': 2,
    }]
    valid = bool(
        extra_root == set() and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids
            for ability in abilities
        )
        and damage_down
        and damage_down.get('mode') == 'continuous'
        and damage_down.get('timing') == 'function'
        and damage_down.get('condition') == damage_condition
        and damage_down.get('effects') == damage_effects
        and not damage_down.get('trigger')
        and 'active_zones' not in damage_down
        and fp_gain and fp_gain.get('mode') == 'mandatory'
        and fp_gain.get('timing') == 'before_judgment'
        and fp_gain.get('trigger') == {'event': 'before_judgment'}
        and fp_gain.get('condition') == fp_condition
        and fp_gain.get('effects') == fp_effects
        and 'active_zones' not in fp_gain
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'st1-002', False,
                reason='캐츠 머핀즈의 오버 리미트 대미지·판정 전 FP 정의가 일치하지 않습니다.',
            )],
            'ST1-002 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    damage_scenarios = []
    for (
        name, owner, active, damage_bonus,
        expected_damage, expected_final, expected_legal,
    ) in (
        ('qna-322-owner-p1-final-zero-is-illegal', 'p1', True, 0, 100, 0, False),
        ('qna-322-owner-p2-final-zero-is-illegal', 'p2', True, 0, 100, 0, False),
        ('external-plus-one-hundred-restores-legality', 'p1', True, 100, 200, 100, True),
        ('without-over-limit-printed-damage-is-legal', 'p1', False, 0, 400, 300, True),
    ):
        first = _run_st1_002_combo_scenario(
            definition, card_snapshot, owner,
            over_limit=active, damage_bonus=damage_bonus,
        )
        second = _run_st1_002_combo_scenario(
            definition, card_snapshot, owner,
            over_limit=active, damage_bonus=damage_bonus,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['damage'] == expected_damage
                and first['final_damage'] == expected_final
                and first['legal'] is expected_legal
            ),
            'deterministic': deterministic, 'over_limit': active,
            'damage_bonus': damage_bonus,
            'expected_damage': expected_damage,
            'expected_final_damage': expected_final,
            'expected_legal': expected_legal, **first,
        })
    damage_review = AbilityReview(
        damage_down['id'], all(item['passed'] for item in damage_scenarios),
        damage_scenarios,
        '' if all(item['passed'] for item in damage_scenarios)
        else '캐츠 머핀즈의 대미지 감소·Q&A 322 콤보 검증에 실패했습니다.',
    )

    fp_scenarios = []
    for spec in (
        {
            'name': 'qna-235-owner-p1-speed-seven-gains-before-fp',
            'owner': 'p1', 'opponent_speed': 7,
            'expected_resolved': 1, 'expected_fp': 3,
            'expected_reference': 7, 'expected_owner_speed': 3,
            'expected_opponent_speed': 7,
        },
        {
            'name': 'qna-235-owner-p2-speed-six-gains-before-fp',
            'owner': 'p2', 'opponent_speed': 6,
            'expected_resolved': 1, 'expected_fp': 3,
            'expected_reference': 6, 'expected_owner_speed': 3,
            'expected_opponent_speed': 6,
        },
        {
            'name': 'effect-modified-eight-to-seven-is-eligible',
            'owner': 'p1', 'opponent_speed': 8, 'opponent_speed_delta': -1,
            'expected_resolved': 1, 'expected_fp': 3,
            'expected_reference': 7, 'expected_owner_speed': 3,
            'expected_opponent_speed': 7,
        },
        {
            'name': 'opponent-fp-does-not-lower-condition-speed',
            'owner': 'p1', 'opponent_speed': 8, 'opponent_fp': 3,
            'expected_resolved': 0, 'expected_fp': 1,
            'expected_reference': 8, 'expected_owner_speed': 5,
            'expected_opponent_speed': 5,
        },
        {
            'name': 'fixed-speed-six-is-eligible',
            'owner': 'p1', 'opponent_speed': 10, 'opponent_fixed_speed': 6,
            'expected_resolved': 1, 'expected_fp': 3,
            'expected_reference': 6, 'expected_owner_speed': 3,
            'expected_opponent_speed': 6,
        },
        {
            'name': 'foot-attack-does-not-trigger',
            'owner': 'p1', 'opponent_speed': 7, 'opponent_body': '발',
            'expected_resolved': 0, 'expected_fp': 1,
            'expected_reference': 7, 'expected_owner_speed': 5,
            'expected_opponent_speed': 7,
        },
        {
            'name': 'hand-defense-does-not-trigger',
            'owner': 'p2', 'opponent_speed': 7, 'opponent_type': '수비',
            'expected_resolved': 0, 'expected_fp': 1,
            'expected_reference': 7, 'expected_owner_speed': 5,
            'expected_opponent_speed': 7,
        },
        {
            'name': 'wrong-trigger-does-not-gain-fp',
            'owner': 'p1', 'event_type': 'use', 'opponent_speed': 7,
            'expected_resolved': 0, 'expected_fp': 1,
            'expected_reference': 7, 'expected_owner_speed': 5,
            'expected_opponent_speed': 7,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'expected_resolved', 'expected_fp',
                'expected_reference', 'expected_owner_speed',
                'expected_opponent_speed',
            }
        }
        first = _run_st1_002_fp_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st1_002_fp_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        fp_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['resolved_count'] == spec['expected_resolved']
                and first['owner_fp_after'] == spec['expected_fp']
                and first['opponent_reference_speed']
                == spec['expected_reference']
                and first['owner_final_speed']
                == spec['expected_owner_speed']
                and first['opponent_final_speed']
                == spec['expected_opponent_speed']
                and not first['pending']
            ),
            'deterministic': deterministic, **kwargs,
            'expected_resolved': spec['expected_resolved'],
            'expected_fp': spec['expected_fp'],
            'expected_reference_speed': spec['expected_reference'],
            **first,
        })
    fp_review = AbilityReview(
        fp_gain['id'], all(item['passed'] for item in fp_scenarios),
        fp_scenarios,
        '' if all(item['passed'] for item in fp_scenarios)
        else '캐츠 머핀즈의 상대 조건·Q&A 235 FP 타이밍 검증에 실패했습니다.',
    )
    reviews = [damage_review, fp_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '캐츠 머핀즈의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st1_003_card(
    code, owner, instance_id, *, name=None, frame=6, damage=600,
    position='상단', body='손', keyword='', definition=None,
):
    card = _card(code, owner, instance_id)
    card.update({
        'name': name or code, 'frame': frame, 'damage': damage,
        'pos': position, 'body': body, 'special': '',
        'keyword': keyword, 'face_up': True,
    })
    return card, (
        copy.deepcopy(definition)
        if definition is not None else _st1_001_no_effect_definition()
    )


def _run_st1_003_battle_scenario(
    definition, card_snapshot, owner, *, opponent_position='상단',
    opponent_body='손', opponent_speed=6,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-rai-bounce', 'owner': owner,
        'type': '공격', 'frame': 7, 'damage': 400,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': '3', 'guard': '-4', 'counter': '3', 'face_up': True,
    })
    opposing, opposing_definition = _st1_003_card(
        'REVIEW-RAI-BOUNCE-OPPONENT', other,
        f'{other}-rai-bounce-opponent', frame=opponent_speed,
        position=opponent_position, body=opponent_body,
    )
    engine = AutomaticGameEngine(
        _state(source, opposing, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': opposing_definition,
                },
            },
        },
        seed=(
            f'rai-bounce-battle:{owner}:{opponent_position}:'
            f'{opponent_body}:{opponent_speed}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {'instance_id': source['instance_id'], 'card': live_source},
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    engine._capture_battle_speed()
    engine._resolve_battle_judgment()
    trigger_index = 0
    while True:
        triggers = engine.engine_state['battle'].get('trigger_sequence') or []
        if trigger_index < len(triggers):
            event_type, context = triggers[trigger_index]
            trigger_index += 1
            engine._fire(event_type, context)
            continue
        late = engine._late_combo_result_triggers()
        if not late:
            break
        triggers.extend(late)
    opened = engine._open_combo_from_battle()
    return {
        'owner_result': engine.engine_state['battle']['result'][owner],
        'opponent_result': engine.engine_state['battle']['result'][other],
        'hit_after': live_source.get('hit'),
        'n1_resolution_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st1-003-n1'
            for event in engine.events
        ),
        'n2_resolution_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st1-003-n2'
            for event in engine.events
        ),
        'combo_event_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st1-003-n2'
            for event in engine.events
        ),
        'combo_opened': opened is True,
        'combo_owner': (engine.engine_state.get('combo') or {}).get('owner'),
        'trigger_types': [event_type for event_type, _context in (
            engine.engine_state['battle'].get('trigger_sequence') or []
        )],
    }


def _st1_003_combo_engine(
    definition, card_snapshot, owner, *, previous_name='레피! 파이어!',
    previous_keyword='레피/', previous_speed=14, extra_hand=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-rai-bounce-combo', 'owner': owner,
        'type': '공격', 'frame': 7, 'damage': 400,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': '3', 'guard': '-4', 'counter': '3', 'face_up': True,
    })
    previous, previous_definition = _st1_003_card(
        'REVIEW-RAI-BOUNCE-PREVIOUS', owner,
        f'{owner}-rai-bounce-previous', name=previous_name,
        frame=previous_speed, damage=800, keyword=previous_keyword,
    )
    opposing, opposing_definition = _st1_003_card(
        'REVIEW-RAI-BOUNCE-OPPONENT', other,
        f'{other}-rai-bounce-combo-opponent',
    )
    state = _state(previous, opposing, owner)
    state['players'][owner]['zones']['hand'] = [
        copy.deepcopy(source), *copy.deepcopy(extra_hand or []),
    ]
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        previous['code']: {
            **copy.deepcopy(previous),
            'effect_definition': previous_definition,
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': opposing_definition,
        },
    }
    for card in extra_hand or []:
        cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st1_001_no_effect_definition(),
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'rai-bounce-combo:{owner}:{previous_name}:'
            f'{previous_keyword}:{previous_speed}:'
            f'{[card.get("instance_id") for card in extra_hand or []]}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    combo = {
        'owner': owner, 'source': previous['instance_id'], 'used': [],
        'last_speed': previous_speed, 'next_penalty': 100,
        'proposal_submitted': False,
    }
    engine.engine_state['combo'] = combo
    engine.engine_state['step'] = 'combo'
    return engine, source, previous, combo


def _run_st1_003_combo_candidate_scenario(
    definition, card_snapshot, owner, *, previous_is_lefi, previous_speed=14,
):
    engine, source, _previous, combo = _st1_003_combo_engine(
        definition, card_snapshot, owner,
        previous_name=(
            '레피! 파이어!' if previous_is_lefi else '평범한 기술'
        ),
        previous_keyword='레피/' if previous_is_lefi else '',
        previous_speed=previous_speed,
    )
    live_source = engine._find_card(source['instance_id'])
    rules = engine._combo_rules(owner, live_source, combo)
    return {
        'legal_at_printed_speed': engine._combo_card_legal(
            owner, live_source, combo, selected_speed=7,
        ),
        'speed_options': engine._combo_speed_options(
            owner, live_source, combo, rules=rules,
        ),
        'rules': [{
            key: value for key, value in rule.items()
            if key not in {'controller', 'player', 'source'}
        } for rule in rules],
        'effective_speed': engine.card_stat(
            live_source, 'frame', owner, include_fp=False,
        ),
    }


def _run_st1_003_followup_scenario(
    definition, card_snapshot, owner, *, followup_speed,
):
    followup, _followup_definition = _st1_003_card(
        f'REVIEW-RAI-BOUNCE-FOLLOW-{followup_speed}', owner,
        f'{owner}-rai-bounce-follow-{followup_speed}',
        frame=followup_speed, damage=700,
    )
    engine, source, previous, combo = _st1_003_combo_engine(
        definition, card_snapshot, owner,
        previous_name='레피! 파이어!', previous_keyword='레피/',
        previous_speed=14, extra_hand=[followup],
    )
    combo.update({
        'used': [source['instance_id']], 'last_speed': 7,
        'next_penalty': 200,
    })
    live_followup = engine._find_card(followup['instance_id'])
    return {
        'legal': engine._combo_card_legal(
            owner, live_followup, combo, selected_speed=followup_speed,
        ),
        'last_speed': combo['last_speed'],
        'previous_speed': previous['frame'],
        'bounce_speed': source['frame'],
    }


def _run_st1_003_pair_scenario(definition, card_snapshot, owner):
    lefi, _lefi_definition = _st1_003_card(
        'REVIEW-RAI-BOUNCE-LEFI', owner, f'{owner}-rai-bounce-lefi',
        name='레피! 파이어!', frame=12, damage=800, keyword='레피/',
    )
    engine, source, previous, combo = _st1_003_combo_engine(
        definition, card_snapshot, owner,
        previous_name='콤보 시동 기술', previous_keyword='',
        previous_speed=5, extra_hand=[lefi],
    )
    actions = engine._combo_actions(owner, combo)
    expected_ids = [lefi['instance_id'], source['instance_id']]
    matching = next((
        action for action in actions
        if action.get('type') == 'play_combo_pair'
        and (action.get('payload') or {}).get('card_instance_ids')
        == expected_ids
    ), None)
    return {
        'pair_available': matching is not None,
        'pair_speeds': (
            (matching.get('payload') or {}).get('combo_speeds')
            if matching else None
        ),
        'action_count': len(actions),
        'source_speed': previous['frame'],
    }


def _review_st1_003_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST1-003':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    clash_rule = by_id.get('st1-003-function')
    clash_combo = by_id.get('st1-003-n1')
    combo_link = by_id.get('st1-003-n2')
    qna_ids = [20, 318, 532]
    defense_rules = [{
        'judgment': 'clash', 'position': '상단', 'grant': True,
        'where': {'body': '손'},
    }]
    combo_rules = [{
        'ignore_speed': True,
        'after_where': {'keyword_any': ['레피']},
    }]
    valid = bool(
        extra_root == {'combo_rules', 'defense_rules'}
        and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids
            for ability in abilities
        )
        and definition.get('defense_rules') == defense_rules
        and definition.get('combo_rules') == combo_rules
        and clash_rule and clash_rule.get('mode') == 'continuous'
        and clash_rule.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and not clash_rule.get('trigger')
        and clash_combo and clash_combo.get('mode') == 'mandatory'
        and clash_combo.get('timing') == 'clash'
        and clash_combo.get('trigger') == {'event': 'clash'}
        and clash_combo.get('effects') == [{
            'op': 'modify_judgment', 'player': {'controller': True},
            'field': 'hit', 'value': '콤보',
        }]
        and combo_link and combo_link.get('mode') == 'mandatory'
        and combo_link.get('trigger') == {'event': 'combo'}
        and combo_link.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False,
            [AbilityReview(
                'st1-003', False,
                reason='라이! 바운스!의 상쇄 부여·콤보 판정·연계 정의가 일치하지 않습니다.',
            )],
            'ST1-003 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    battle_specs = (
        ('owner-p1-high-hand-clashes', 'p1', '상단', '손', 'clash'),
        ('owner-p2-high-hand-clashes', 'p2', '상단', '손', 'clash'),
        ('high-foot-does-not-clash', 'p1', '상단', '발', 'countered'),
        ('middle-hand-does-not-clash', 'p1', '중단', '손', 'countered'),
    )
    defense_scenarios = []
    combo_judgment_scenarios = []
    for name, owner, position, body, expected_result in battle_specs:
        first = _run_st1_003_battle_scenario(
            definition, card_snapshot, owner,
            opponent_position=position, opponent_body=body,
        )
        second = _run_st1_003_battle_scenario(
            definition, card_snapshot, owner,
            opponent_position=position, opponent_body=body,
        )
        deterministic = _canonical(first) == _canonical(second)
        clashes = expected_result == 'clash'
        defense_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['owner_result'] == expected_result
            ),
            'deterministic': deterministic,
            'opponent_position': position, 'opponent_body': body,
            'expected_owner_result': expected_result, **first,
        })
        combo_judgment_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['hit_after'] == ('콤보' if clashes else '3')
                and first['n1_resolution_count'] == (1 if clashes else 0)
                and first['n2_resolution_count'] == (1 if clashes else 0)
                and first['combo_opened'] is clashes
                and first['combo_owner'] == (owner if clashes else None)
                and first['trigger_types'].count('combo') == (1 if clashes else 0)
            ),
            'deterministic': deterministic,
            'opponent_position': position, 'opponent_body': body,
            'expected_combo': clashes, **first,
        })
    defense_review = AbilityReview(
        clash_rule['id'], all(item['passed'] for item in defense_scenarios),
        defense_scenarios,
        '' if all(item['passed'] for item in defense_scenarios)
        else '라이! 바운스!의 상단·손 상쇄 판정 검증에 실패했습니다.',
    )
    clash_review = AbilityReview(
        clash_combo['id'],
        all(item['passed'] for item in combo_judgment_scenarios),
        combo_judgment_scenarios,
        '' if all(item['passed'] for item in combo_judgment_scenarios)
        else '라이! 바운스!의 상쇄 후 콤보 판정 검증에 실패했습니다.',
    )

    combo_scenarios = []
    for name, owner, previous_is_lefi, expected_legal in (
        ('qna-318-owner-p1-lefi-fourteen-to-seven', 'p1', True, True),
        ('qna-318-owner-p2-lefi-fourteen-to-seven', 'p2', True, True),
        ('non-lefi-fourteen-does-not-ignore-speed', 'p1', False, False),
    ):
        first = _run_st1_003_combo_candidate_scenario(
            definition, card_snapshot, owner,
            previous_is_lefi=previous_is_lefi,
        )
        second = _run_st1_003_combo_candidate_scenario(
            definition, card_snapshot, owner,
            previous_is_lefi=previous_is_lefi,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['legal_at_printed_speed'] is expected_legal
                and first['effective_speed'] == 7
                and (
                    not previous_is_lefi
                    or first['speed_options'] == [7]
                )
            ),
            'deterministic': deterministic,
            'previous_is_lefi': previous_is_lefi,
            'expected_legal': expected_legal, **first,
        })
    for name, followup_speed, expected_legal in (
        ('qna-20-followup-speed-eight-is-legal', 8, True),
        ('qna-20-followup-speed-seven-is-not-ascending', 7, False),
    ):
        first = _run_st1_003_followup_scenario(
            definition, card_snapshot, 'p1', followup_speed=followup_speed,
        )
        second = _run_st1_003_followup_scenario(
            definition, card_snapshot, 'p1', followup_speed=followup_speed,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['legal'] is expected_legal
                and first['last_speed'] == 7
            ),
            'deterministic': deterministic,
            'followup_speed': followup_speed,
            'expected_legal': expected_legal, **first,
        })
    for name, owner in (
        ('qna-532-owner-p1-simultaneous-lefi-then-bounce', 'p1'),
        ('qna-532-owner-p2-simultaneous-lefi-then-bounce', 'p2'),
    ):
        first = _run_st1_003_pair_scenario(definition, card_snapshot, owner)
        second = _run_st1_003_pair_scenario(definition, card_snapshot, owner)
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['pair_available']
                and first['pair_speeds'] == [12, 7]
            ),
            'deterministic': deterministic, **first,
        })
    combo_review = AbilityReview(
        combo_link['id'], all(item['passed'] for item in combo_scenarios),
        combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '라이! 바운스!의 Q&A 20/318/532 콤보 연계 검증에 실패했습니다.',
    )
    reviews = [defense_review, clash_review, combo_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '라이! 바운스!의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st1_005_technique(
    code, owner, instance_id, *, card_type='공격', frame=6,
    damage=600, face_up=True,
):
    card = _card(code, owner, instance_id)
    card.update({
        'name': code, 'type': card_type, 'frame': frame,
        'damage': damage, 'face_up': bool(face_up),
    })
    if card_type == '수비':
        card.update({'frame': None, 'damage': None, 'g_mid': '방어'})
    elif card_type == '특수':
        card.update({'frame': None, 'damage': None})
    return card


