def _review_unc_at_016_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-016':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    marker = by_id.get('unc-at-016-n1-dodge')
    delayed = by_id.get('unc-at-016-n1-break-after-use')
    damage = by_id.get('unc-at-016-n2')
    catch_lock = by_id.get('unc-at-016-n3')
    skip_get = by_id.get('unc-at-016-n4')
    qna_ids = [360, 388, 485]
    valid = bool(
        not extra_root and len(abilities) == 5
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and marker and marker.get('trigger') == {'event': 'dodge'}
        and marker.get('effects') == [{
            'op': 'log', 'text': '사용 후 브레이크 예약',
        }]
        and delayed and delayed.get('trigger') == {'event': 'after_use'}
        and delayed.get('condition') == {
            'op': 'ability_resolved', 'player': {'controller': True},
            'ability_id': 'unc-at-016-n1-dodge', 'same_source': True,
        }
        and delayed.get('effects') == [{'op': 'break_card'}]
        and damage and damage.get('trigger') == {'event': 'use'}
        and damage.get('condition') == {
            'op': 'zone_count', 'player': {'controller': True},
            'zone': 'lumen',
            'where': {'code': 'AWL-SP-001', 'face_up': True}, 'min': 1,
        }
        and damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': 100, 'duration': 'battle',
        }]
        and catch_lock and catch_lock.get('trigger') == {'event': 'after_use'}
        and catch_lock.get('effects') == [{
            'op': 'prevent', 'kind': 'catch',
            'player': {'controller': True}, 'duration': 'turn',
        }]
        and skip_get and skip_get.get('trigger') == {'event': 'after_use'}
        and skip_get.get('effects') == [{
            'op': 'skip_get', 'player': {'controller': True},
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'unc-at-016', False,
                reason='파워풀 스윕의 지연 브레이크·올인 차지·사용 후 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-016 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    delayed_scenarios = []
    for spec in (
        {
            'name': 'qna-360-owner-p1-breaks-only-after-use',
            'owner': 'p1', 'event_type': 'dodge', 'side_count': 2,
            'replenish_index': 1, 'include_after_use_siblings': True,
            'expected': True,
        },
        {
            'name': 'qna-388-owner-p2-mutual-dodge-breaks-after-use',
            'owner': 'p2', 'event_type': 'dodge', 'expected': True,
        },
        {
            'name': 'qna-485-prevented-dodge-does-not-mark-or-break',
            'owner': 'p1', 'event_type': 'guard', 'expected': False,
        },
        {
            'name': 'opponent-dodge-does-not-mark-own-card',
            'owner': 'p2', 'event_type': 'opponent_dodge',
            'expected': False,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected'}
        }
        first = _run_unc_at_016_delayed_break_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_unc_at_016_delayed_break_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        integrated_ok = True
        if spec.get('include_after_use_siblings'):
            integrated_ok = bool(
                first['catch_blocked'] and first['get_skipped']
                and first['decision_kinds'][:2]
                == ['effect_order', 'break_replenish']
                and first['selected_zone'] == 'list'
            )
        delayed_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and integrated_ok
                and first['marker_resolved'] is spec['expected']
                and first['break_resolved'] is spec['expected']
                and first['zone_after_result'] == 'battle'
                and first['source_zone']
                == ('break' if spec['expected'] else 'battle')
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': spec['expected'], **first,
        })
    reviews = [
        AbilityReview(
            marker['id'], all(item['passed'] for item in delayed_scenarios),
            delayed_scenarios,
            '' if all(item['passed'] for item in delayed_scenarios)
            else '회피 결과의 사용 후 브레이크 예약 검증에 실패했습니다.',
        ),
        AbilityReview(
            delayed['id'], all(item['passed'] for item in delayed_scenarios),
            copy.deepcopy(delayed_scenarios),
            '' if all(item['passed'] for item in delayed_scenarios)
            else '동일 카드 사용 후 지연 브레이크 검증에 실패했습니다.',
        ),
    ]

    damage_scenarios = []
    for name, owner, present, face_up, event_type, expected in (
        ('owner-p1-face-up-charge-adds-one-hundred', 'p1', True, True, 'use', True),
        ('owner-p2-face-up-charge-adds-one-hundred', 'p2', True, True, 'use', True),
        ('missing-charge-does-not-add-damage', 'p1', False, True, 'use', False),
        ('face-down-charge-does-not-satisfy-condition', 'p2', True, False, 'use', False),
        ('wrong-trigger-does-not-add-damage', 'p1', True, True, 'before_judgment', False),
    ):
        first = _run_unc_at_016_charge_damage_scenario(
            definition, damage, card_snapshot, owner,
            present=present, face_up=face_up, event_type=event_type,
        )
        second = _run_unc_at_016_charge_damage_scenario(
            definition, damage, card_snapshot, owner,
            present=present, face_up=face_up, event_type=event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is expected
                and first['after'] == first['before'] + (100 if expected else 0)
            ),
            'deterministic': deterministic,
            'expected_resolution': expected, **first,
        })
    reviews.append(AbilityReview(
        damage['id'], all(item['passed'] for item in damage_scenarios),
        damage_scenarios,
        '' if all(item['passed'] for item in damage_scenarios)
        else '올인 차지 루멘 조건 데미지 검증에 실패했습니다.',
    ))

    for ability, field, label in (
        (catch_lock, 'catch_blocked', '사용 후 캐치 금지'),
        (skip_get, 'get_skipped', '사용 후 겟 스킵'),
    ):
        scenarios = []
        for name, owner, event_type, expected in (
            ('owner-p1-after-use', 'p1', 'after_use', True),
            ('owner-p2-after-use', 'p2', 'after_use', True),
            ('wrong-trigger', 'p1', 'use', False),
        ):
            first = _run_unc_at_016_after_use_rule_scenario(
                definition, ability, card_snapshot, owner, event_type,
            )
            second = _run_unc_at_016_after_use_rule_scenario(
                definition, ability, card_snapshot, owner, event_type,
            )
            deterministic = _canonical(first) == _canonical(second)
            scenarios.append({
                'name': name,
                'passed': bool(
                    deterministic and first['resolved'] is expected
                    and first[field] is expected
                ),
                'deterministic': deterministic,
                'expected_resolution': expected, **first,
            })
        reviews.append(AbilityReview(
            ability['id'], all(item['passed'] for item in scenarios),
            scenarios,
            '' if all(item['passed'] for item in scenarios)
            else f'{label} 검증에 실패했습니다.',
        ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '파워풀 스윕의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _unc_at_017_source(card_snapshot, owner, suffix):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-instant-smash-{suffix}', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 8, 'damage': 400,
        'pos': '상단', 'body': '손', 'special': '상단 상쇄',
        'hit': '4', 'guard': '-6', 'counter': '4', 'face_up': True,
    })
    return source


def _unc_at_017_engine(
    definition, card_snapshot, owner, *, ability_ids=None,
    hand_cards=None, battle_source=True,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_017_source(card_snapshot, owner, 'source')
    opposing = _card(
        'REVIEW-INSTANT-SMASH-OPPONENT', other,
        f'{other}-instant-smash-opponent',
    )
    isolated = copy.deepcopy(definition)
    if ability_ids is not None:
        wanted = set(ability_ids)
        isolated['abilities'] = [
            copy.deepcopy(ability)
            for ability in definition.get('abilities') or []
            if ability.get('id') in wanted
        ]
    no_effect = _st1_001_no_effect_definition()
    state = _state(
        source, opposing, owner,
        source_zone='battle' if battle_source else 'hand',
    )
    state['players'][owner]['zones']['hand'].extend(
        copy.deepcopy(hand_cards or []),
    )
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    for card in hand_cards or []:
        cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'instant-smash:{owner}:{ability_ids}:{battle_source}:'
            f'{[card.get("instance_id") for card in hand_cards or []]}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, source, opposing


def _run_unc_at_017_charge_scenario(
    definition, card_snapshot, owner, *, charged,
    event_type='before_judgment', fixed_before=None, later_delta=-4,
):
    engine, source, opposing = _unc_at_017_engine(
        definition, card_snapshot, owner,
        ability_ids=['unc-at-017-n1'],
    )
    other = 'p2' if owner == 'p1' else 'p1'
    if charged:
        engine.state['players'][owner]['passive_state']['charge'] = {
            'value': True, 'label': 'charge',
        }
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'], 'card': live_source,
        },
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    if fixed_before is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': owner,
            'source': f'{other}-earlier-fix',
            'where': {'instance_id': source['instance_id']},
            'stat': 'frame', 'value': fixed_before, 'duration': 'battle',
        })
    before_damage = engine.card_stat(live_source, 'damage', owner)
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source, 'opponent_card': live_opposing,
        'controller_speed': engine.card_stat(
            live_source, 'frame', owner, include_fp=False,
        ),
        'opponent_speed': engine.card_stat(
            live_opposing, 'frame', other, include_fp=False,
        ),
        'source_only_event': True,
    })
    if later_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-later-speed-change',
            'where': {'instance_id': source['instance_id']},
            'stat': 'frame', 'amount': later_delta, 'duration': 'battle',
        })
    battle_card = (engine.engine_state.get('battle') or {}).get(owner, {}).get('card') or {}
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'unc-at-017-n1'
            for event in engine.events
        ),
        'speed': engine.card_stat(live_source, 'frame', owner, include_fp=False),
        'fixed_speed': engine._fixed_stat(live_source, 'frame', owner),
        'before_damage': before_damage,
        'damage': engine.card_stat(live_source, 'damage', owner),
        'hit': battle_card.get('hit'),
        'special': battle_card.get('special'),
        'speed_fixed_events': sum(
            event.get('type') == 'speed_fixed' for event in engine.events
        ),
    }


def _run_unc_at_017_clash_break_scenario(
    definition, card_snapshot, owner, *, candidate_count,
    selected_index=0, event_type='clash',
):
    candidates = [
        {
            **_card(
                f'REVIEW-INSTANT-SMASH-HAND-{index}', owner,
                f'{owner}-instant-smash-hand-{index}',
            ),
            'type': '수비' if index % 2 else '공격',
        }
        for index in range(candidate_count)
    ]
    engine, source, opposing = _unc_at_017_engine(
        definition, card_snapshot, owner,
        ability_ids=['unc-at-017-n2'], hand_cards=candidates,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    option_ids = [
        str(item.get('id')) for item in (decision or {}).get('options') or []
    ]
    selected_id = None
    if decision and option_ids:
        selected_id = option_ids[min(selected_index, len(option_ids) - 1)]
        engine._submit_decision(owner, decision['id'], [selected_id])
        engine._continue()
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'unc-at-017-n2'
            for event in engine.events
        ),
        'decision_kind': (decision or {}).get('kind'),
        'decision_owner': (decision or {}).get('owner'),
        'option_ids': option_ids, 'selected_id': selected_id,
        'candidate_ids': [card['instance_id'] for card in candidates],
        'selected_zone': (
            engine._find_location(selected_id)[1] if selected_id else None
        ),
        'choice_skipped': any(
            event.get('type') == 'effect_choice_skipped'
            and (event.get('payload') or {}).get('reason')
            == 'insufficient_candidates'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_unc_at_017_combo_scenario(
    definition, card_snapshot, owner, *, next_has_charge,
    insert_non_charge=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    primary = _card(
        'REVIEW-INSTANT-SMASH-PRIMARY', owner,
        f'{owner}-instant-smash-primary',
    )
    primary.update({'frame': 5, 'damage': 400})
    source = _unc_at_017_source(card_snapshot, owner, 'combo')
    source.update({'frame': 6, 'damage': 400})
    immediate = _card(
        'REVIEW-INSTANT-SMASH-IMMEDIATE', owner,
        f'{owner}-instant-smash-immediate',
    )
    immediate.update({'frame': 7, 'damage': 500})
    if next_has_charge and not insert_non_charge:
        immediate['text'] = '[[state:charge]]: 검토용 차지 효과'
    later = None
    if insert_non_charge:
        later = _card(
            'REVIEW-INSTANT-SMASH-LATER-CHARGE', owner,
            f'{owner}-instant-smash-later-charge',
        )
        later.update({
            'frame': 8, 'damage': 500,
            'text': '[[state:charge]]: 검토용 차지 효과',
        })
    opposing = _card(
        'REVIEW-INSTANT-SMASH-COMBO-OPPONENT', other,
        f'{other}-instant-smash-combo-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'unc-at-017-n3'
    ]
    no_effect = _st1_001_no_effect_definition()
    state = _state(primary, opposing, owner)
    hand = [source, immediate, *([later] if later else [])]
    state['players'][owner]['zones']['hand'] = copy.deepcopy(hand)
    cards = {
        primary['code']: {**copy.deepcopy(primary), 'effect_definition': no_effect},
        source['code']: {**copy.deepcopy(source), 'effect_definition': isolated},
        immediate['code']: {**copy.deepcopy(immediate), 'effect_definition': no_effect},
        opposing['code']: {**copy.deepcopy(opposing), 'effect_definition': no_effect},
    }
    if later:
        cards[later['code']] = {
            **copy.deepcopy(later), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=f'instant-smash-combo:{owner}:{next_has_charge}:{insert_non_charge}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.grant_combo(owner, source=primary['instance_id'], trigger_event=False)
    ids = [source['instance_id'], immediate['instance_id']]
    speeds = [6, 7]
    if later:
        engine.engine_state['combo']['max_combo'] = 4
        ids.append(later['instance_id'])
        speeds.append(8)
    engine._play_combo(owner, ids, speeds, [False] * len(ids))
    engine._continue()
    used_events = [
        event for event in engine.events
        if event.get('type') == 'combo_card_used'
    ]
    damages = {
        (event.get('payload') or {}).get('card_instance_id'):
        (event.get('payload') or {}).get('damage')
        for event in used_events
    }
    modifier = next((
        copy.deepcopy((event.get('payload') or {}).get('modifier'))
        for event in engine.events
        if event.get('type') == 'modifier_added'
        and ((event.get('payload') or {}).get('modifier') or {}).get('op')
        == 'modify_combo'
        and ((event.get('payload') or {}).get('modifier') or {}).get('source')
        == source['instance_id']
    ), None)
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'unc-at-017-n3'
            for event in engine.events
        ),
        'used_ids': [
            (event.get('payload') or {}).get('card_instance_id')
            for event in used_events
        ],
        'damages': damages,
        'immediate_id': immediate['instance_id'],
        'later_id': later['instance_id'] if later else None,
        'modifier_where': (modifier or {}).get('where'),
        'modifier_after_where': (modifier or {}).get('after_where'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_unc_at_017_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-017':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    charge = by_id.get('unc-at-017-n1')
    clash = by_id.get('unc-at-017-n2')
    combo = by_id.get('unc-at-017-n3')
    qna_ids = [470, 552, 583, 657, 691]
    expected_charge = [
        {
            'op': 'fix_speed', 'player': {'controller': True},
            'stat': 'frame', 'value': 7, 'duration': 'battle',
        },
        {
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': -100, 'duration': 'battle',
        },
        {
            'op': 'modify_judgment', 'player': {'controller': True},
            'field': 'hit', 'value': '+3',
        },
    ]
    expected_break = [{
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '브레이크할 자신의 패 1장을 선택하세요.',
        'selector': {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['hand'], 'min': 1, 'max': 1,
            'as_operation': 'break_card',
        },
        'default': [], 'selection_key': 'unc_at_017_clash_hand',
        'skip_if_unavailable': True,
        'then': [{
            'op': 'break_card',
            'selection_key': 'unc_at_017_clash_hand',
        }],
    }]
    expected_combo = [{
        'op': 'modify_combo', 'player': {'controller': True},
        'where': {'text_contains': '[[state:charge]]'},
        'after_source': True, 'damage_bonus': 100,
        'duration': 'battle',
    }]
    valid = bool(
        not extra_root and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and charge and charge.get('mode') == 'mandatory'
        and charge.get('trigger') == {'event': 'before_judgment'}
        and charge.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'charge',
        }
        and charge.get('effects') == expected_charge
        and clash and clash.get('mode') == 'mandatory'
        and clash.get('trigger') == {'event': 'clash'}
        and clash.get('effects') == expected_break
        and combo and combo.get('mode') == 'mandatory'
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('effects') == expected_combo
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'unc-at-017', False,
                reason='인스턴트 스매시의 차지·상쇄 선택·다음 콤보 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-017 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    charge_scenarios = []
    for spec in (
        {
            'name': 'qna-470-owner-p1-charge-fixes-seven',
            'owner': 'p1', 'charged': True, 'expected_speed': 7,
            'expected_resolution': True,
        },
        {
            'name': 'owner-p2-charge-ignores-later-speed-change',
            'owner': 'p2', 'charged': True, 'later_delta': 5,
            'expected_speed': 7, 'expected_resolution': True,
        },
        {
            'name': 'qna-691-earlier-fixed-speed-keeps-priority',
            'owner': 'p1', 'charged': True, 'fixed_before': 9,
            'expected_speed': 9, 'expected_resolution': True,
        },
        {
            'name': 'without-charge-does-not-change-card',
            'owner': 'p2', 'charged': False, 'later_delta': 0,
            'expected_speed': 8, 'expected_resolution': False,
        },
        {
            'name': 'wrong-trigger-does-not-change-card',
            'owner': 'p1', 'charged': True, 'event_type': 'use',
            'later_delta': 0, 'expected_speed': 8,
            'expected_resolution': False,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected_speed', 'expected_resolution'}
        }
        first = _run_unc_at_017_charge_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_unc_at_017_charge_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected = spec['expected_resolution']
        charge_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is expected
                and first['speed'] == spec['expected_speed']
                and first['fixed_speed']
                == (spec['expected_speed'] if expected else None)
                and first['damage']
                == first['before_damage'] - (100 if expected else 0)
                and first['hit'] == ('+3' if expected else '4')
                and first['special'] == '상단 상쇄'
            ),
            'deterministic': deterministic,
            'expected_resolution': expected, **first,
        })
    reviews = [AbilityReview(
        charge['id'], all(item['passed'] for item in charge_scenarios),
        charge_scenarios,
        '' if all(item['passed'] for item in charge_scenarios)
        else '차지 조건의 속도 고정·데미지·히트 변경 검증에 실패했습니다.',
    )]

    clash_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-selects-second-hand-card',
            'owner': 'p1', 'candidate_count': 2, 'selected_index': 1,
            'expected_choice': True,
        },
        {
            'name': 'owner-p2-selects-first-hand-card',
            'owner': 'p2', 'candidate_count': 2, 'selected_index': 0,
            'expected_choice': True,
        },
        {
            'name': 'qna-583-empty-hand-skips-without-breaking',
            'owner': 'p1', 'candidate_count': 0,
            'expected_choice': False, 'expected_skip': True,
        },
        {
            'name': 'wrong-trigger-does-not-request-choice',
            'owner': 'p2', 'candidate_count': 2, 'event_type': 'hit',
            'expected_choice': False, 'expected_skip': False,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected_choice', 'expected_skip'}
        }
        first = _run_unc_at_017_clash_break_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_unc_at_017_clash_break_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        choice = spec['expected_choice']
        expected_skip = spec.get('expected_skip', False)
        expected_resolved = spec.get('event_type', 'clash') == 'clash'
        selected_ok = (
            first['selected_zone'] == 'break'
            and first['selected_id'] in first['candidate_ids']
            if choice else first['selected_id'] is None
        )
        clash_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is expected_resolved
                and bool(first['decision_kind']) is choice
                and (first['decision_owner'] == spec['owner'] if choice else True)
                and sorted(first['option_ids'])
                == (sorted(first['candidate_ids']) if choice else [])
                and selected_ok
                and first['choice_skipped'] is expected_skip
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_choice': choice, **first,
        })
    reviews.append(AbilityReview(
        clash['id'], all(item['passed'] for item in clash_scenarios),
        clash_scenarios,
        '' if all(item['passed'] for item in clash_scenarios)
        else '상쇄 시 패 브레이크의 실제 선택·빈 패 처리를 검증하지 못했습니다.',
    ))

    combo_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-immediate-charge-gets-one-hundred',
            'owner': 'p1', 'next_has_charge': True,
            'expected_immediate_damage': 400,
        },
        {
            'name': 'owner-p2-immediate-non-charge-gets-no-bonus',
            'owner': 'p2', 'next_has_charge': False,
            'expected_immediate_damage': 300,
        },
        {
            'name': 'later-charge-is-not-the-next-card',
            'owner': 'p1', 'next_has_charge': True,
            'insert_non_charge': True,
            'expected_immediate_damage': 300,
            'expected_later_damage': 200,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'expected_immediate_damage', 'expected_later_damage',
            }
        }
        first = _run_unc_at_017_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_unc_at_017_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        later_ok = True
        if first['later_id']:
            later_ok = (
                first['damages'].get(first['later_id'])
                == spec['expected_later_damage']
            )
        combo_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved']
                and first['damages'].get(first['immediate_id'])
                == spec['expected_immediate_damage']
                and later_ok
                and first['modifier_where']
                == {'text_contains': '[[state:charge]]'}
                and first['modifier_after_where']
                == {'instance_id': f'{spec["owner"]}-instant-smash-combo'}
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        combo['id'], all(item['passed'] for item in combo_scenarios),
        combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '바로 다음 차지 콤보에만 적용되는 데미지 검증에 실패했습니다.',
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '인스턴트 스매시의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_unc_at_018_position_scenario(
    definition, card_snapshot, owner, *, opponent_type='공격',
    special='', g_top='', g_mid='', g_bot='', sequence='static',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-gear-change', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 6, 'damage': 400,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': '2', 'guard': '-4', 'counter': '3', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-GEAR-CHANGE-OPPONENT', other,
        f'{other}-gear-change-opponent',
    )
    opposing.update({
        'type': opponent_type, 'special': special,
        'g_top': g_top, 'g_mid': g_mid, 'g_bot': g_bot,
    })
    if opponent_type == '수비':
        opposing.update({'frame': None, 'damage': None})
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'unc-at-018-n1'
    ]
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, opposing, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'gear-change:{owner}:{opponent_type}:{special}:'
            f'{g_top}:{g_mid}:{g_bot}:{sequence}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'], 'card': live_source,
        },
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }

    def fire_gear_change():
        engine._fire('before_judgment', {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': live_source, 'opponent_card': live_opposing,
            'source_only_event': True,
        })

    if sequence == 'dodge_first':
        engine.modify_judgment(
            other, 'special', '중단 회피',
            source='review-gear-change-dodge', effect_controller=other,
        )
        fire_gear_change()
    elif sequence == 'gear_first':
        fire_gear_change()
        engine.modify_judgment(
            other, 'special', '중단 회피',
            source='review-gear-change-dodge', effect_controller=other,
        )
    else:
        fire_gear_change()
    battle = engine.engine_state.get('battle') or {}
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'unc-at-018-n1'
            for event in engine.events
        ),
        'position': (battle.get(owner) or {}).get('card', {}).get('pos'),
        'opponent_special': (
            (battle.get(other) or {}).get('card', {}).get('special')
        ),
        'judgment_changes': sum(
            event.get('type') == 'judgment_modified'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_unc_at_018_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-018':
        return None
    abilities = definition.get('abilities') or []
    ability = next((
        item for item in abilities if item.get('id') == 'unc-at-018-n1'
    ), None)
    qna_ids = [669]
    valid = bool(
        not extra_root and len(abilities) == 1
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and ability
        and sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'before_judgment'}
        and ability.get('condition') == {
            'op': 'card_matches',
            'card': {'path': 'context.opponent_card'},
            'where': {'battle_judgment_contains': '회피'},
        }
        and ability.get('effects') == [{
            'op': 'modify_judgment',
            'player': {'controller': True},
            'field': 'pos', 'value': '중단',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'unc-at-018-n1', False,
                reason='기어체인지의 상대 회피 판정·위치 변경 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-018 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    scenarios = []
    for spec in (
        {
            'name': 'attack-special-dodge-changes-to-middle',
            'owner': 'p1', 'opponent_type': '공격',
            'special': '상단 회피', 'expected': True,
        },
        {
            'name': 'defense-dodge-judgment-changes-to-middle',
            'owner': 'p2', 'opponent_type': '수비',
            'g_mid': '회피', 'expected': True,
        },
        {
            'name': 'attack-clash-is-not-a-dodge',
            'owner': 'p1', 'opponent_type': '공격',
            'special': '상단 상쇄', 'expected': False,
        },
        {
            'name': 'defense-guard-is-not-a-dodge',
            'owner': 'p2', 'opponent_type': '수비',
            'g_top': '방어', 'expected': False,
        },
        {
            'name': 'qna-669-route-priority-does-not-look-ahead',
            'owner': 'p1', 'opponent_type': '공격',
            'sequence': 'gear_first', 'expected': False,
        },
        {
            'name': 'qna-669-lin-priority-sees-gained-dodge',
            'owner': 'p1', 'opponent_type': '공격',
            'sequence': 'dodge_first', 'expected': True,
        },
    ):
        kwargs = {key: value for key, value in spec.items() if key not in {'name', 'expected'}}
        first = _run_unc_at_018_position_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_unc_at_018_position_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected = spec['expected']
        scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is expected
                and first['position'] == ('중단' if expected else '상단')
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': expected, **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            ability['id'], passed, scenarios,
            '' if passed else '상대 회피 판정과 우선권 순서 검증에 실패했습니다.',
        )],
        '' if passed else '기어체인지의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _lmi_at_016_source(card_snapshot, owner, suffix):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-stormbringer-{suffix}', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 14, 'damage': 600,
        'pos': '상단', 'body': '', 'special': '',
        'hit': '콤보', 'guard': '-8', 'counter': '콤보', 'face_up': True,
    })
    return source


def _run_lmi_at_016_play_scenario(
    definition, card_snapshot, owner, *, location='lumen',
    face_up=True, use_context='ready',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_016_source(card_snapshot, owner, 'play')
    opposing = _card(
        'REVIEW-STORMBRINGER-PLAY-OPPONENT', other,
        f'{other}-stormbringer-play-opponent',
    )
    charge = _card(
        'AWL-SP-001', owner, f'{owner}-stormbringer-all-in-charge',
    )
    charge.update({
        'name': '올 인 차지', 'type': '특수',
        'frame': None, 'damage': None, 'face_up': face_up,
    })
    if not face_up:
        charge.update({
            'non_technique_while_face_down': True,
            'effects_negated': True,
        })
    state = _state(source, opposing, owner, source_zone='hand')
    if location in state['players'][owner]['zones']:
        state['players'][owner]['zones'][location].append(copy.deepcopy(charge))
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
                charge['code']: {
                    **copy.deepcopy(charge), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'stormbringer-play:{owner}:{location}:{face_up}:{use_context}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    return {
        'allowed': engine._card_use_allowed(
            live_source, owner, use_context,
        ),
        'use_context': use_context,
        'charge_location': location,
        'charge_face_up': face_up,
    }


def _run_lmi_at_016_lock_scenario(
    definition, card_snapshot, owner, *, charged,
    source_zone='battle',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_016_source(card_snapshot, owner, 'lock')
    opposing = _card(
        'REVIEW-STORMBRINGER-LOCK-OPPONENT', other,
        f'{other}-stormbringer-lock-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'lmi-at-016-n1'
    ]
    state = _state(source, opposing, owner, source_zone=source_zone)
    if charged:
        state['players'][owner]['passive_state']['charge'] = {
            'value': True, 'label': 'charge',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'stormbringer-lock:{owner}:{charged}:{source_zone}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if source_zone == 'battle':
        engine.engine_state['battle'] = {
            owner: {
                'instance_id': source['instance_id'],
                'card': engine._find_card(source['instance_id']),
            },
            other: {
                'instance_id': opposing['instance_id'],
                'card': engine._find_card(opposing['instance_id']),
            },
        }
    engine._refresh_continuous_rules()
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    return {
        'blocked': {
            kind: engine._rule_blocked(
                kind, other, live_opposing, live_source,
            )
            for kind in ('guard', 'dodge', 'clash')
        },
        'replacement_kinds': sorted(
            item.get('kind')
            for item in engine.engine_state.get('replacements') or []
        ),
    }


def _run_lmi_at_016_charge_speed_scenario(
    definition, card_snapshot, owner, *, charged,
    event_type='use', fixed_before=None, later_delta=-5,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_016_source(card_snapshot, owner, 'charge')
    opposing = _card(
        'REVIEW-STORMBRINGER-CHARGE-OPPONENT', other,
        f'{other}-stormbringer-charge-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'lmi-at-016-n2'
    ]
    state = _state(source, opposing, owner)
    state['players'][owner]['fp'] = 6
    if charged:
        state['players'][owner]['passive_state']['charge'] = {
            'value': True, 'label': 'charge',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'stormbringer-charge:{owner}:{charged}:{event_type}:'
            f'{fixed_before}:{later_delta}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'], 'card': live_source,
        },
        other: {
            'instance_id': opposing['instance_id'], 'card': live_opposing,
        },
    }
    if fixed_before is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': owner,
            'source': f'{other}-earlier-fix',
            'where': {'instance_id': source['instance_id']},
            'stat': 'frame', 'value': fixed_before, 'duration': 'battle',
        })
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source, 'opponent_card': live_opposing,
        'source_only_event': True,
    })
    if later_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-later-speed-change',
            'where': {'instance_id': source['instance_id']},
            'stat': 'frame', 'amount': later_delta, 'duration': 'battle',
        })
    battle_card = (engine.engine_state.get('battle') or {}).get(owner, {}).get('card') or {}
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-016-n2'
            for event in engine.events
        ),
        'fixed_speed': engine._fixed_stat(live_source, 'frame', owner),
        'speed_with_fp': engine.card_stat(
            live_source, 'frame', owner, include_fp=True,
        ),
        'special': battle_card.get('special'),
    }


def _review_lmi_at_016_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-016':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    play_rule = by_id.get('lmi-at-016-function')
    charge_lock = by_id.get('lmi-at-016-n1')
    charge_speed = by_id.get('lmi-at-016-n2')
    qna_ids = [586, 588, 691]
    play_condition = {
        'op': 'zone_count', 'player': {'controller': True},
        'zone': 'lumen',
        'where': {'code': 'AWL-SP-001', 'face_up': True},
        'min': 1,
    }
    lock_effects = [
        {
            'op': 'prevent', 'kind': kind,
            'player': {'opponent': True}, 'duration': 'continuous',
        }
        for kind in ('guard', 'dodge', 'clash')
    ]
    speed_effects = [
        {
            'op': 'fix_speed', 'player': {'controller': True},
            'stat': 'frame', 'value': 14, 'duration': 'battle',
        },
        {
            'op': 'modify_judgment', 'player': {'controller': True},
            'field': 'special', 'value': '하단 상쇄', 'mode': 'append',
        },
    ]
    charge_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'charge',
    }
    valid = bool(
        extra_root == {'play_condition'} and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('play_condition') == play_condition
        and play_rule and play_rule.get('mode') == 'continuous'
        and play_rule.get('effects') == [{
            'op': 'static_rule', 'rules': ['play_condition'],
        }]
        and charge_lock and charge_lock.get('mode') == 'continuous'
        and charge_lock.get('active_zones') == ['battle']
        and charge_lock.get('condition') == charge_condition
        and charge_lock.get('effects') == lock_effects
        and charge_speed and charge_speed.get('mode') == 'mandatory'
        and charge_speed.get('trigger') == {'event': 'use'}
        and charge_speed.get('condition') == charge_condition
        and charge_speed.get('effects') == speed_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-016', False,
                reason='스톰브링거의 사용 조건·차지 금지·속도 고정 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-016 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    play_scenarios = []
    for spec in (
        {
            'name': 'face-up-all-in-charge-allows-ready',
            'owner': 'p1', 'location': 'lumen', 'face_up': True,
            'use_context': 'ready', 'expected': True,
        },
        {
            'name': 'qna-586-face-up-all-in-charge-allows-catch',
            'owner': 'p2', 'location': 'lumen', 'face_up': True,
            'use_context': 'catch', 'expected': True,
        },
        {
            'name': 'qna-588-missing-required-card-rejects-ready',
            'owner': 'p1', 'location': 'side', 'face_up': True,
            'use_context': 'ready', 'expected': False,
        },
        {
            'name': 'face-down-card-does-not-reveal-or-satisfy-condition',
            'owner': 'p2', 'location': 'lumen', 'face_up': False,
            'use_context': 'combo', 'expected': False,
        },
    ):
        kwargs = {key: value for key, value in spec.items() if key not in {'name', 'expected'}}
        first = _run_lmi_at_016_play_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_lmi_at_016_play_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        play_scenarios.append({
            'name': spec['name'],
            'passed': bool(deterministic and first['allowed'] is spec['expected']),
            'deterministic': deterministic,
            'expected_allowed': spec['expected'], **first,
        })
    reviews = [AbilityReview(
        play_rule['id'], all(item['passed'] for item in play_scenarios),
        play_scenarios,
        '' if all(item['passed'] for item in play_scenarios)
        else '올 인 차지 사용 조건의 영역·공개 상태·사용 맥락 검증에 실패했습니다.',
    )]

    lock_scenarios = []
    for name, owner, charged, source_zone, expected in (
        ('owner-p1-charge-blocks-all-three', 'p1', True, 'battle', True),
        ('owner-p2-charge-blocks-all-three', 'p2', True, 'battle', True),
        ('without-charge-blocks-none', 'p1', False, 'battle', False),
        ('source-outside-battle-blocks-none', 'p2', True, 'hand', False),
    ):
        first = _run_lmi_at_016_lock_scenario(
            definition, card_snapshot, owner,
            charged=charged, source_zone=source_zone,
        )
        second = _run_lmi_at_016_lock_scenario(
            definition, card_snapshot, owner,
            charged=charged, source_zone=source_zone,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_map = {kind: expected for kind in ('guard', 'dodge', 'clash')}
        lock_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['blocked'] == expected_map
                and first['replacement_kinds']
                == (['clash', 'dodge', 'guard'] if expected else [])
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        charge_lock['id'], all(item['passed'] for item in lock_scenarios),
        lock_scenarios,
        '' if all(item['passed'] for item in lock_scenarios)
        else '차지 상태의 방어·회피·상쇄 금지 검증에 실패했습니다.',
    ))

    speed_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-charge-fixes-fourteen-and-adds-clash',
            'owner': 'p1', 'charged': True,
            'expected_resolution': True, 'expected_speed': 14,
        },
        {
            'name': 'owner-p2-fixed-speed-ignores-fp-and-later-change',
            'owner': 'p2', 'charged': True, 'later_delta': 4,
            'expected_resolution': True, 'expected_speed': 14,
        },
        {
            'name': 'qna-691-earlier-fix-keeps-its-speed',
            'owner': 'p1', 'charged': True, 'fixed_before': 11,
            'expected_resolution': True, 'expected_speed': 11,
        },
        {
            'name': 'without-charge-does-not-add-special-judgment',
            'owner': 'p2', 'charged': False, 'later_delta': 0,
            'expected_resolution': False, 'expected_speed': 8,
        },
        {
            'name': 'wrong-trigger-does-not-resolve',
            'owner': 'p1', 'charged': True, 'event_type': 'before_judgment',
            'later_delta': 0, 'expected_resolution': False,
            'expected_speed': 8,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected_resolution', 'expected_speed'}
        }
        first = _run_lmi_at_016_charge_speed_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_lmi_at_016_charge_speed_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected = spec['expected_resolution']
        speed_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is expected
                and first['speed_with_fp'] == spec['expected_speed']
                and first['fixed_speed']
                == (spec['expected_speed'] if expected else None)
                and first['special'] == ('하단 상쇄' if expected else '')
            ),
            'deterministic': deterministic,
            'expected_resolution': expected, **first,
        })
    reviews.append(AbilityReview(
        charge_speed['id'], all(item['passed'] for item in speed_scenarios),
        speed_scenarios,
        '' if all(item['passed'] for item in speed_scenarios)
        else '차지 사용 시 속도 고정·하단 상쇄 추가 검증에 실패했습니다.',
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '스톰브링거의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_st5_001_combo_scenario(
    definition, card_snapshot, owner, *, intimidation,
    previous_pos='중단', previous_damage=500,
    previous_damage_modifier=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    previous = _card(
        'REVIEW-WOLF-CUTTER-PREVIOUS', owner,
        f'{owner}-wolf-cutter-previous',
    )
    previous.update({
        'frame': 10, 'damage': previous_damage,
        'pos': previous_pos, 'body': '손',
    })
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-wolf-cutter', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 5, 'damage': 400,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': '2', 'guard': '-2', 'counter': '2', 'face_up': True,
    })
    next_six = _card(
        'REVIEW-WOLF-CUTTER-NEXT-SIX', owner,
        f'{owner}-wolf-cutter-next-six',
    )
    next_six.update({'frame': 6, 'damage': 500})
    next_five = _card(
        'REVIEW-WOLF-CUTTER-NEXT-FIVE', owner,
        f'{owner}-wolf-cutter-next-five',
    )
    next_five.update({'frame': 5, 'damage': 500})
    opposing = _card(
        'REVIEW-WOLF-CUTTER-OPPONENT', other,
        f'{other}-wolf-cutter-opponent',
    )
    state = _state(previous, opposing, owner)
    state['players'][owner]['zones']['hand'] = copy.deepcopy([
        source, next_six, next_five,
    ])
    if intimidation:
        state['players'][owner]['passive_state']['intimidation'] = {
            'value': True, 'label': 'intimidation',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                previous['code']: {
                    **copy.deepcopy(previous), 'effect_definition': no_effect,
                },
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                next_six['code']: {
                    **copy.deepcopy(next_six), 'effect_definition': no_effect,
                },
                next_five['code']: {
                    **copy.deepcopy(next_five), 'effect_definition': no_effect,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'wolf-cutter:{owner}:{intimidation}:{previous_pos}:'
            f'{previous_damage}:{previous_damage_modifier}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if previous_damage_modifier:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-previous-damage-modifier',
            'where': {'instance_id': previous['instance_id']},
            'stat': 'damage', 'amount': previous_damage_modifier,
            'duration': 'battle',
        })
    engine.grant_combo(
        owner, source=previous['instance_id'], trigger_event=False,
    )
    combo_state = engine.engine_state['combo']
    combo_state['last_speed'] = int(previous.get('frame') or 1)
    live_source = engine._find_card(source['instance_id'])
    rules = engine._combo_rules(owner, live_source, combo_state)
    legal = engine._combo_card_legal(owner, live_source, combo_state)
    bonus = sum(int(rule.get('damage_bonus') or 0) for rule in rules)
    damage = max(
        0, engine.card_stat(live_source, 'damage', owner)
        - int(combo_state.get('next_penalty') or 100) + bonus,
    )
    engine._fire('combo', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source, 'combo': True,
        'source_only_event': True,
    })
    combo_state['used'] = [source['instance_id']]
    combo_state['last_speed'] = 5
    combo_state['next_penalty'] = 200
    next_six_legal = engine._combo_card_legal(
        owner, engine._find_card(next_six['instance_id']), combo_state,
    )
    next_five_legal = engine._combo_card_legal(
        owner, engine._find_card(next_five['instance_id']), combo_state,
    )
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st5-001-n1'
            for event in engine.events
        ),
        'legal': legal,
        'ignore_speed': any(rule.get('ignore_speed') for rule in rules),
        'damage_bonus': bonus, 'combo_damage': damage,
        'printed_previous_damage': previous_damage,
        'effective_previous_damage': engine.card_stat(
            engine._find_card(previous['instance_id']), 'damage', owner,
        ),
        'next_six_legal': next_six_legal,
        'next_five_legal': next_five_legal,
    }


def _review_st5_001_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST5-001':
        return None
    abilities = definition.get('abilities') or []
    ability = next((
        item for item in abilities if item.get('id') == 'st5-001-n1'
    ), None)
    qna_ids = [20]
    state_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'intimidation',
    }
    combo_rules = [
        {
            'ignore_speed': True,
            'after_where': {'pos': '중단'},
            'condition': copy.deepcopy(state_condition),
        },
        {
            'damage_bonus': 200,
            'condition': {
                'op': 'all',
                'conditions': [
                    copy.deepcopy(state_condition),
                    {
                        'op': 'lte',
                        'left': 'context.opponent_card.damage',
                        'right': 500,
                    },
                ],
            },
        },
    ]
    valid = bool(
        extra_root == {'combo_rules'} and len(abilities) == 1
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and ability
        and sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and definition.get('combo_rules') == combo_rules
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('trigger') == {'event': 'combo'}
        and ability.get('condition') == state_condition
        and ability.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st5-001-n1', False,
                reason='울프 커터의 위압 콤보 연결·원래 데미지 보너스 정의가 일치하지 않습니다.',
            )],
            'ST5-001 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    scenarios = []
    for spec in (
        {
            'name': 'owner-p1-middle-five-hundred-ignores-speed-and-adds-two-hundred',
            'owner': 'p1', 'intimidation': True,
            'previous_pos': '중단', 'previous_damage': 500,
            'expected_legal': True, 'expected_bonus': 200,
        },
        {
            'name': 'owner-p2-middle-six-hundred-ignores-speed-without-bonus',
            'owner': 'p2', 'intimidation': True,
            'previous_pos': '중단', 'previous_damage': 600,
            'expected_legal': True, 'expected_bonus': 0,
        },
        {
            'name': 'original-damage-is-used-despite-positive-modifier',
            'owner': 'p1', 'intimidation': True,
            'previous_pos': '중단', 'previous_damage': 500,
            'previous_damage_modifier': 300,
            'expected_legal': True, 'expected_bonus': 200,
        },
        {
            'name': 'without-intimidation-cannot-ignore-descending-speed',
            'owner': 'p2', 'intimidation': False,
            'previous_pos': '중단', 'previous_damage': 500,
            'expected_legal': False, 'expected_bonus': 0,
        },
        {
            'name': 'high-previous-card-does-not-enable-speed-ignore',
            'owner': 'p1', 'intimidation': True,
            'previous_pos': '상단', 'previous_damage': 500,
            'expected_legal': False, 'expected_bonus': 200,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected_legal', 'expected_bonus'}
        }
        first = _run_st5_001_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st5_001_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_bonus = spec['expected_bonus']
        scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['resolved'] is spec['intimidation']
                and first['legal'] is spec['expected_legal']
                and first['ignore_speed']
                is (spec['intimidation'] and spec['previous_pos'] == '중단')
                and first['damage_bonus'] == expected_bonus
                and first['combo_damage'] == 300 + expected_bonus
                and first['next_six_legal']
                and not first['next_five_legal']
            ),
            'deterministic': deterministic,
            'expected_legal': spec['expected_legal'],
            'expected_bonus': expected_bonus, **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            ability['id'], passed, scenarios,
            '' if passed else '위압 콤보 연결·원래 데미지·후속 오름차순 검증에 실패했습니다.',
        )],
        '' if passed else '울프 커터의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_st5_002_guard_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-hunting-head-guard', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 6, 'damage': 400,
        'pos': '상단', 'body': '손', 'special': '그랩',
        'hit': '1', 'guard': 'X', 'counter': '3', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-HUNTING-HEAD-GUARD-OPPONENT', other,
        f'{other}-hunting-head-guard-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'st5-002-function'
    ]
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, opposing, owner, source_zone=source_zone),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'hunting-head-guard:{owner}:{source_zone}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._refresh_continuous_rules()
    return {
        'guard_blocked': engine._rule_blocked(
            'guard', other, engine._find_card(opposing['instance_id']),
            engine._find_card(source['instance_id']),
        ),
        'dodge_blocked': engine._rule_blocked(
            'dodge', other, engine._find_card(opposing['instance_id']),
            engine._find_card(source['instance_id']),
        ),
        'replacement_kinds': [
            item.get('kind')
            for item in engine.engine_state.get('replacements') or []
        ],
    }


def _run_st5_002_combo_scenario(
    definition, card_snapshot, owner, *, intimidation, selected_speed,
):
    other = 'p2' if owner == 'p1' else 'p1'
    previous = _card(
        'REVIEW-HUNTING-HEAD-PREVIOUS', owner,
        f'{owner}-hunting-head-previous',
    )
    previous.update({'frame': 5, 'damage': 400})
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-hunting-head', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 6, 'damage': 400,
        'pos': '상단', 'body': '손', 'special': '그랩',
        'hit': '1', 'guard': 'X', 'counter': '3', 'face_up': True,
    })
    next_ten = _card(
        'REVIEW-HUNTING-HEAD-NEXT-TEN', owner,
        f'{owner}-hunting-head-next-ten',
    )
    next_ten.update({'frame': 10, 'damage': 500})
    next_eleven = _card(
        'REVIEW-HUNTING-HEAD-NEXT-ELEVEN', owner,
        f'{owner}-hunting-head-next-eleven',
    )
    next_eleven.update({'frame': 11, 'damage': 500})
    opposing = _card(
        'REVIEW-HUNTING-HEAD-COMBO-OPPONENT', other,
        f'{other}-hunting-head-combo-opponent',
    )
    state = _state(previous, opposing, owner)
    state['players'][owner]['zones']['hand'] = copy.deepcopy([
        source, next_ten, next_eleven,
    ])
    if intimidation:
        state['players'][owner]['passive_state']['intimidation'] = {
            'value': True, 'label': 'intimidation',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                previous['code']: {
                    **copy.deepcopy(previous), 'effect_definition': no_effect,
                },
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                next_ten['code']: {
                    **copy.deepcopy(next_ten), 'effect_definition': no_effect,
                },
                next_eleven['code']: {
                    **copy.deepcopy(next_eleven), 'effect_definition': no_effect,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'hunting-head-combo:{owner}:{intimidation}:{selected_speed}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.grant_combo(
        owner, source=previous['instance_id'], trigger_event=False,
    )
    combo_state = engine.engine_state['combo']
    combo_state['last_speed'] = 5
    live_source = engine._find_card(source['instance_id'])
    rules = engine._combo_rules(owner, live_source, combo_state)
    speeds = engine._combo_speed_options(owner, live_source, combo_state, rules=rules)
    legal = engine._combo_card_legal(
        owner, live_source, combo_state, selected_speed=selected_speed,
    )
    penalty = engine._combo_applied_penalty(
        owner, live_source, combo_state, 100, rules=rules,
    )
    bonus = engine._combo_damage_bonus(rules, selected_speed)
    damage = max(0, engine.card_stat(live_source, 'damage', owner) - penalty + bonus)
    engine._fire('combo', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source, 'combo': True,
        'source_only_event': True,
    })
    combo_state['used'] = [source['instance_id']]
    combo_state['last_speed'] = selected_speed
    combo_state['next_penalty'] = 200
    next_ten_legal = engine._combo_card_legal(
        owner, engine._find_card(next_ten['instance_id']), combo_state,
    )
    next_eleven_legal = engine._combo_card_legal(
        owner, engine._find_card(next_eleven['instance_id']), combo_state,
    )
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st5-002-n2'
            for event in engine.events
        ),
        'speed_options': speeds, 'selected_legal': legal,
        'damage_bonus': bonus, 'combo_damage': damage,
        'next_ten_legal': next_ten_legal,
        'next_eleven_legal': next_eleven_legal,
    }


def _review_st5_002_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST5-002':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st5-002-function')
    negated = by_id.get('st5-002-n1-grab-negated')
    dodged = by_id.get('st5-002-n1-opponent-dodge')
    combo = by_id.get('st5-002-n2')
    qna_ids = [260, 675]
    state_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'intimidation',
    }
    combo_rules = [{
        'speed_options': [10], 'damage_bonus': 200,
        'damage_bonus_speed': 10,
        'condition': copy.deepcopy(state_condition),
    }]
    fp_effect = [{
        'op': 'change_fp', 'player': {'opponent': True}, 'amount': 5,
    }]
    valid = bool(
        extra_root == {'combo_rules'} and len(abilities) == 4
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('combo_rules') == combo_rules
        and function and function.get('mode') == 'continuous'
        and function.get('active_zones') == ['battle']
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'guard',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and negated and negated.get('trigger') == {'event': 'grab_negated'}
        and negated.get('effects') == fp_effect
        and dodged and dodged.get('trigger') == {'event': 'opponent_dodge'}
        and dodged.get('effects') == fp_effect
        and combo and combo.get('trigger') == {'event': 'combo'}
        and combo.get('condition') == state_condition
        and combo.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st5-002', False,
                reason='헌팅 헤드의 방어 금지·그랩 무효/회피·10속도 콤보 정의가 일치하지 않습니다.',
            )],
            'ST5-002 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    guard_scenarios = []
    for name, owner, zone, expected in (
        ('owner-p1-battle-blocks-guard-only', 'p1', 'battle', True),
        ('owner-p2-battle-blocks-guard-only', 'p2', 'battle', True),
        ('outside-battle-does-not-block-guard', 'p1', 'hand', False),
    ):
        first = _run_st5_002_guard_scenario(
            definition, card_snapshot, owner, source_zone=zone,
        )
        second = _run_st5_002_guard_scenario(
            definition, card_snapshot, owner, source_zone=zone,
        )
        deterministic = _canonical(first) == _canonical(second)
        guard_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['guard_blocked'] is expected
                and not first['dodge_blocked']
                and first['replacement_kinds'] == (['guard'] if expected else [])
            ),
            'deterministic': deterministic, **first,
        })
    reviews = [AbilityReview(
        function['id'], all(item['passed'] for item in guard_scenarios),
        guard_scenarios,
        '' if all(item['passed'] for item in guard_scenarios)
        else '배틀 중 상대 방어 금지 범위 검증에 실패했습니다.',
    )]

    for ability, proper_event, wrong_event, label in (
        (negated, 'grab_negated', 'card_invalidated', '그랩 무효'),
        (dodged, 'opponent_dodge', 'guard', '상대 회피'),
    ):
        scenarios = []
        for name, owner, event_type, expected in (
            (f'owner-p1-{proper_event}-gives-opponent-five', 'p1', proper_event, True),
            (f'owner-p2-{proper_event}-gives-opponent-five', 'p2', proper_event, True),
            (f'qna-675-{wrong_event}-does-not-count', 'p1', wrong_event, False),
        ):
            first = _run_scenario(definition, ability, owner, event_type)
            second = _run_scenario(definition, ability, owner, event_type)
            deterministic = _canonical(first) == _canonical(second)
            other = 'p2' if owner == 'p1' else 'p1'
            opponent_fp = first['state']['players'][other]['fp']
            scenarios.append({
                'name': name,
                'passed': bool(
                    deterministic and first['resolved'] is expected
                    and opponent_fp == (10 if expected else 5)
                ),
                'deterministic': deterministic,
                'expected_resolution': expected,
                'opponent_fp': opponent_fp,
            })
        reviews.append(AbilityReview(
            ability['id'], all(item['passed'] for item in scenarios),
            scenarios,
            '' if all(item['passed'] for item in scenarios)
            else f'{label} 시 상대 5FP 획득 검증에 실패했습니다.',
        ))

    combo_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-intimidation-selects-ten-with-bonus',
            'owner': 'p1', 'intimidation': True, 'selected_speed': 10,
            'expected_options': [6, 10], 'expected_legal': True,
            'expected_bonus': 200, 'expected_damage': 500,
        },
        {
            'name': 'owner-p2-intimidation-printed-six-has-no-bonus',
            'owner': 'p2', 'intimidation': True, 'selected_speed': 6,
            'expected_options': [6, 10], 'expected_legal': True,
            'expected_bonus': 0, 'expected_damage': 300,
        },
        {
            'name': 'without-intimidation-ten-is-not-an-option',
            'owner': 'p1', 'intimidation': False, 'selected_speed': 10,
            'expected_options': [6], 'expected_legal': False,
            'expected_bonus': 0, 'expected_damage': 300,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if not key.startswith('expected_') and key != 'name'
        }
        first = _run_st5_002_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st5_002_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        qna20_ok = True
        if spec['selected_speed'] == 10:
            qna20_ok = bool(
                not first['next_ten_legal'] and first['next_eleven_legal']
            )
        combo_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['resolved'] is spec['intimidation']
                and first['speed_options'] == spec['expected_options']
                and first['selected_legal'] is spec['expected_legal']
                and first['damage_bonus'] == spec['expected_bonus']
                and first['combo_damage'] == spec['expected_damage']
                and qna20_ok
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        combo['id'], all(item['passed'] for item in combo_scenarios),
        combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '선택한 10속도에만 붙는 데미지와 후속 속도 검증에 실패했습니다.',
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '헌팅 헤드의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_cb01_at_016_howling_scenario(
    definition, ability, card_snapshot, owner, *, howling=5, amount=1,
    accept=True, source_zone='ultimate', phase='lumen',
    numbered_effects_negated=False,
):
    source = _sandbox_source_snapshot(card_snapshot)
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    payload = start_effect_sandbox(
        source, definition, ability.get('id'), {}, {
            'event': 'phase_start', 'controller': owner,
            'phase': phase, 'source_zone': source_zone,
            'fixture_mode': 'minimal',
            'players': {
                'p1': {
                    'hp': 4000, 'fp': 5,
                    'passive_state': (
                        {'howling': {'count': howling}}
                        if owner == 'p1' and howling else {}
                    ),
                },
                'p2': {
                    'hp': 4000, 'fp': 5,
                    'passive_state': (
                        {'howling': {'count': howling}}
                        if owner == 'p2' and howling else {}
                    ),
                },
            },
        },
    )
    decisions = []
    while (payload.get('state') or {}).get('engine', {}).get('pending_decision'):
        decision = payload['state']['engine']['pending_decision']
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        decisions.append({
            'kind': decision.get('kind'),
            'minimum': decision.get('minimum'),
            'maximum': decision.get('maximum'),
            'option_ids': option_ids,
        })
        if len(decisions) > 5:
            raise EffectSandboxError('사냥 개시 선택 단계가 5회를 초과했습니다.')
        if decision.get('kind') == 'optional_effect':
            selected = ['accept' if accept else 'decline']
        elif decision.get('kind') == 'effect_amount':
            selected = [str(amount)]
        else:
            selected = option_ids[:int(decision.get('minimum') or 0)]
        payload = continue_effect_sandbox(payload, selected)
        if not accept:
            break
    result = project_effect_sandbox(payload)
    other = 'p2' if owner == 'p1' else 'p1'
    passive = result['players'][owner].get('passive_state') or {}
    return {
        'decisions': decisions,
        'howling': int((passive.get('howling') or {}).get('count') or 0),
        'opponent_fp': int(result['players'][other]['fp']),
        'resolved': result.get('resolved'),
        'pending': bool((result.get('engine') or {}).get('pending_decision')),
    }


def _run_cb01_at_016_break_scenario(
    definition, ability, card_snapshot, owner, *, hp=2500,
    source_zone='ultimate', phase='lumen', numbered_effects_negated=False,
    break_protected=False,
):
    source = _sandbox_source_snapshot(card_snapshot)
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    runtime_definition = copy.deepcopy(definition)
    if break_protected:
        runtime_definition['break_rules'] = {
            'forbidden_zones': [source_zone],
        }
    payload = start_effect_sandbox(
        source, runtime_definition, ability.get('id'), {}, {
            'event': 'phase_start', 'controller': owner,
            'phase': phase, 'source_zone': source_zone,
            'fixture_mode': 'minimal',
            'players': {
                'p1': {'hp': hp if owner == 'p1' else 4000, 'fp': 5},
                'p2': {'hp': hp if owner == 'p2' else 4000, 'fp': 5},
            },
        },
    )
    decisions = []
    while (payload.get('state') or {}).get('engine', {}).get('pending_decision'):
        decision = payload['state']['engine']['pending_decision']
        decisions.append(decision.get('kind'))
        if len(decisions) > 5:
            raise EffectSandboxError('사냥 개시 브레이크 단계가 5회를 초과했습니다.')
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        selected = (
            ['decline'] if 'decline' in option_ids
            else option_ids[:int(decision.get('minimum') or 0)]
        )
        payload = continue_effect_sandbox(payload, selected)
    result = project_effect_sandbox(payload)
    source_zone_after = next((
        zone for zone, cards in result['players'][owner]['zones'].items()
        if any(
            card.get('instance_id') == 'sandbox-source' for card in cards
        )
    ), None)
    return {
        'source_zone': source_zone_after,
        'resolved': result.get('resolved'),
        'decision_kinds': decisions,
        'break_ignored': any(
            event.get('type') == 'card_break_prevented'
            for event in result.get('events') or []
        ),
        'pending': bool((result.get('engine') or {}).get('pending_decision')),
    }


def _review_cb01_at_016_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-016':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    howling = by_id.get('cb01-at-016-n1')
    self_break = by_id.get('cb01-at-016-n2')
    qna_ids = [659, 666]
    selection_key = 'howling_counter_amount'
    selected_value = {
        'op': 'selected_value', 'selection_key': selection_key,
    }
    expected_source = {
        'code': 'CB01-AT-016', 'name': '사냥 개시',
        'type': '특수', 'ultimate': True,
        'frame': None, 'damage': None, 'pos': None,
        'body': None, 'special': None,
        'hit': '0', 'guard': '0', 'counter': '0',
    }
    snapshot = card_snapshot or {}
    valid = bool(
        not extra_root and len(abilities) == 2
        and {key: snapshot.get(key) for key in expected_source}
        == expected_source
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and howling and howling.get('mode') == 'optional'
        and howling.get('trigger') == {'event': 'phase_start'}
        and howling.get('active_zones') == ['ultimate']
        and howling.get('condition') == {
            'op': 'all', 'conditions': [
                {'op': 'phase_is', 'phase': 'lumen'},
                {
                    'op': 'counter_at_least',
                    'player': {'controller': True},
                    'counter': 'howling', 'value': 1,
                },
            ],
        }
        and howling.get('effects') == [{
            'op': 'request_amount', 'player': {'controller': True},
            'prompt': '제거할 Howling 카운터 수를 선택하세요.',
            'min': 1,
            'max': {
                'op': 'counter_count', 'player': {'controller': True},
                'counter': 'howling',
            },
            'selection_key': selection_key,
            'then': [
                {
                    'op': 'change_counter',
                    'player': {'controller': True},
                    'counter': 'howling',
                    'amount': {'op': 'negate', 'value': selected_value},
                    'min': 0,
                },
                {
                    'op': 'change_fp', 'player': {'opponent': True},
                    'amount': {'op': 'negate', 'value': selected_value},
                },
            ],
        }]
        and self_break and self_break.get('mode') == 'mandatory'
        and self_break.get('trigger') == {'event': 'phase_start'}
        and self_break.get('active_zones') == ['ultimate']
        and self_break.get('condition') == {
            'op': 'all', 'conditions': [
                {
                    'op': 'lte', 'left': 'context.controller_hp',
                    'right': 2500,
                },
                {'op': 'phase_is', 'phase': 'lumen'},
            ],
        }
        and self_break.get('effects') == [{'op': 'break_card'}]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb01-at-016', False,
                reason=(
                    '사냥 개시의 기본 수치·Howling 임의 수량·상대 FP·'
                    '체력 경계 브레이크 정의가 일치하지 않습니다.'
                ),
            )],
            'CB01-AT-016 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    howling_scenarios = []
    howling_specs = (
        ('owner-p1-selects-two-of-five-howling', 'p1', {'howling': 5, 'amount': 2}, 3, 3, True, ['optional_effect', 'effect_amount']),
        ('owner-p2-selects-all-three-howling', 'p2', {'howling': 3, 'amount': 3}, 0, 2, True, ['optional_effect', 'effect_amount']),
        ('decline-removes-no-howling-or-fp', 'p1', {'howling': 4, 'accept': False}, 4, 5, False, ['optional_effect']),
        ('zero-howling-offers-no-effect', 'p1', {'howling': 0}, 0, 5, False, []),
        ('outside-ultimate-does-not-offer-effect', 'p2', {'howling': 3, 'source_zone': 'lumen'}, 3, 5, False, []),
        ('wrong-recovery-phase-does-not-offer-effect', 'p1', {'howling': 2, 'phase': 'recovery'}, 2, 5, False, []),
        ('numbered-negation-does-not-offer-effect', 'p2', {'howling': 3, 'numbered_effects_negated': True}, 3, 5, False, []),
    )
    for name, owner, kwargs, expected_count, expected_fp, resolved, kinds in howling_specs:
        first = _run_cb01_at_016_howling_scenario(
            definition, howling, snapshot, owner, **kwargs,
        )
        second = _run_cb01_at_016_howling_scenario(
            definition, howling, snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        howling_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['howling'] == expected_count
                and first['opponent_fp'] == expected_fp
                and first['resolved'] is resolved
                and [item['kind'] for item in first['decisions']] == kinds
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_howling': expected_count,
            'expected_opponent_fp': expected_fp, **first,
        })
    howling_review = AbilityReview(
        howling['id'], all(item['passed'] for item in howling_scenarios),
        howling_scenarios,
        '' if all(item['passed'] for item in howling_scenarios)
        else 'Howling 임의 수량 선택·제거·상대 FP 손실 검증에 실패했습니다.',
    )

    break_scenarios = []
    break_specs = (
        ('owner-p1-hp-2500-breaks-special-ultimate', 'p1', {'hp': 2500}, 'break', True, False),
        ('owner-p2-hp-2499-breaks-special-ultimate', 'p2', {'hp': 2499}, 'break', True, False),
        ('hp-2501-does-not-break', 'p1', {'hp': 2501}, 'ultimate', False, False),
        ('outside-ultimate-does-not-break', 'p2', {'hp': 2500, 'source_zone': 'lumen'}, 'lumen', False, False),
        ('wrong-recovery-phase-does-not-break', 'p1', {'hp': 2500, 'phase': 'recovery'}, 'ultimate', False, False),
        ('numbered-negation-does-not-break', 'p2', {'hp': 2500, 'numbered_effects_negated': True}, 'ultimate', False, False),
        ('break-protected-source-survives', 'p1', {'hp': 2500, 'break_protected': True}, 'ultimate', True, True),
    )
    for name, owner, kwargs, zone, resolved, ignored in break_specs:
        first = _run_cb01_at_016_break_scenario(
            definition, self_break, snapshot, owner, **kwargs,
        )
        second = _run_cb01_at_016_break_scenario(
            definition, self_break, snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        break_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['source_zone'] == zone
                and first['resolved'] is resolved
                and first['break_ignored'] is ignored
                and first['decision_kinds'] == []
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_zone': zone, 'expected_resolution': resolved, **first,
        })
    break_review = AbilityReview(
        self_break['id'], all(item['passed'] for item in break_scenarios),
        break_scenarios,
        '' if all(item['passed'] for item in break_scenarios)
        else '체력 2500 경계·얼티밋 영역·특수 카드 브레이크 검증에 실패했습니다.',
    )

    reviews = [howling_review, break_review]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '사냥 개시의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_cb01_at_031_ember_scenario(
    definition, ability, card_snapshot, owner, *, ember=5,
    event_type='use', numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-cb01-at-031-ember', 'owner': owner,
        'face_up': True,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-CB01-AT-031-OPPONENT', other,
        f'{other}-cb01-at-031-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = _st1_001_no_effect_definition()
    state = _state(source, opposing, owner)
    if ember:
        state['players'][owner]['passive_state']['ember'] = {'count': ember}
    engine = AutomaticGameEngine(
        state, {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'cb01-at-031-ember:{owner}:{ember}:{event_type}:{numbered_effects_negated}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    before = engine.card_stat(live_source, 'damage', owner, include_fp=False)
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source,
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True,
    })
    passive = engine.state['players'][owner].get('passive_state') or {}
    return {
        'before_damage': before,
        'after_damage': engine.card_stat(
            live_source, 'damage', owner, include_fp=False,
        ),
        'ember': int((passive.get('ember') or {}).get('count') or 0),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability['id']
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_031_cleanup_scenario(
    definition, ability, card_snapshot, owner, *, event_type='after_use',
    combo=False, side_card=False, numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-cb01-at-031-cleanup', 'owner': owner,
        'face_up': True,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-CB01-AT-031-CLEANUP-OPPONENT', other,
        f'{other}-cb01-at-031-cleanup-opponent',
    )
    replacement = _card(
        'REVIEW-CB01-AT-031-SIDE', owner,
        f'{owner}-cb01-at-031-side',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = _st1_001_no_effect_definition()
    state = _state(source, opposing, owner)
    if side_card:
        state['players'][owner]['zones']['side'] = [copy.deepcopy(replacement)]
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if side_card:
        cards[replacement['code']] = {
            **copy.deepcopy(replacement), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=f'cb01-at-031-cleanup:{owner}:{event_type}:{combo}:{side_card}:{numbered_effects_negated}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if combo:
        engine.engine_state['combo'] = {
            'owner': owner, 'source': source['instance_id'],
            'used': [source['instance_id']], 'last_speed': 14,
            'next_penalty': 100, 'proposal_submitted': False,
        }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'combo': combo, 'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    selected = None
    if decision and decision.get('kind') == 'break_replenish':
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        candidates = [option for option in option_ids if option != 'decline']
        selected = candidates[0] if candidates else 'decline'
        engine._submit_decision(owner, decision['id'], [selected])
        engine._continue()
    location = engine._find_location(source['instance_id'])
    return {
        'source_zone': location[1] if location else None,
        'combo_active': bool(engine.engine_state.get('combo')),
        'decision_kind': (decision or {}).get('kind'),
        'selected_replenishment': selected,
        'replacement_in_list': bool(
            selected and selected != 'decline'
            and engine._find_card(selected, owner=owner, zone='list')
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability['id']
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb01_at_031_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-031':
        return None
    abilities = definition.get('abilities') or []
