def _run_st5_008_dodge_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st5_008_source(card_snapshot, owner, 'dodge')
    opposing = _card(
        'REVIEW-DEMISE-END-DODGE-OPPONENT', other,
        f'{other}-demise-end-dodge-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'st5-008-function'
    ]
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, opposing, owner, source_zone=source_zone),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'demise-end-dodge:{owner}:{source_zone}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._refresh_continuous_rules()
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    return {
        'dodge_blocked': engine._rule_blocked(
            'dodge', other, live_opposing, live_source,
        ),
        'guard_blocked': engine._rule_blocked(
            'guard', other, live_opposing, live_source,
        ),
    }


def _run_st5_008_repeat_scenario(
    definition, card_snapshot, owner, *, intimidation,
    event_type='hit',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st5_008_source(card_snapshot, owner, 'repeat')
    opposing = _card(
        'REVIEW-DEMISE-END-REPEAT-OPPONENT', other,
        f'{other}-demise-end-repeat-opponent',
    )
    state = _state(source, opposing, owner)
    if intimidation:
        state['players'][owner]['passive_state']['intimidation'] = {
            'value': True, 'label': 'intimidation',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'demise-end-repeat:{owner}:{intimidation}:{event_type}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': engine._find_card(source['instance_id']),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': engine._find_card(opposing['instance_id']),
        },
    }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True,
    })
    engine._continue()
    if engine.engine_state.get('repeat_phase'):
        engine._advance_phase()
        engine._continue()
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st5-008-n1'
            for event in engine.events
        ),
        'phase': engine.state.get('phase'),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'phase_restarted': any(
            event.get('type') in {'phase_restarted', 'phase_repeat_scheduled'}
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_st5_008_combo_scenario(
    definition, card_snapshot, owner, *, previous_pos,
    previous_speed, select_ignore,
):
    other = 'p2' if owner == 'p1' else 'p1'
    previous = _card(
        'REVIEW-DEMISE-END-PREVIOUS', owner,
        f'{owner}-demise-end-previous',
    )
    previous.update({
        'frame': previous_speed, 'damage': 500,
        'pos': previous_pos, 'body': '손',
    })
    source = _st5_008_source(card_snapshot, owner, 'combo')
    next_thirteen = _card(
        'REVIEW-DEMISE-END-NEXT-THIRTEEN', owner,
        f'{owner}-demise-end-next-thirteen',
    )
    next_thirteen.update({'frame': 13, 'damage': 500})
    next_twelve = _card(
        'REVIEW-DEMISE-END-NEXT-TWELVE', owner,
        f'{owner}-demise-end-next-twelve',
    )
    next_twelve.update({'frame': 12, 'damage': 500})
    opposing = _card(
        'REVIEW-DEMISE-END-COMBO-OPPONENT', other,
        f'{other}-demise-end-combo-opponent',
    )
    state = _state(previous, opposing, owner)
    state['players'][owner]['zones']['hand'] = copy.deepcopy([
        source, next_thirteen, next_twelve,
    ])
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                previous['code']: {
                    **copy.deepcopy(previous), 'effect_definition': no_effect,
                },
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                next_thirteen['code']: {
                    **copy.deepcopy(next_thirteen),
                    'effect_definition': no_effect,
                },
                next_twelve['code']: {
                    **copy.deepcopy(next_twelve),
                    'effect_definition': no_effect,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'demise-end-combo:{owner}:{previous_pos}:{previous_speed}:'
            f'{select_ignore}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.grant_combo(
        owner, source=previous['instance_id'], trigger_event=False,
    )
    combo = engine.engine_state['combo']
    combo['last_speed'] = previous_speed
    live_source = engine._find_card(source['instance_id'])
    normal_legal = engine._combo_card_legal(
        owner, live_source, combo, selected_speed=12,
    )
    ignore_legal = engine._combo_card_legal(
        owner, live_source, combo, selected_speed=12,
        use_optional_speed_ignore=True,
    )
    source_action_flags = set()
    for action in engine._combo_actions(owner, combo):
        payload = action.get('payload') or {}
        action_ids = payload.get('card_instance_ids') or [
            payload.get('card_instance_id')
        ]
        if not action_ids or action_ids[0] != source['instance_id']:
            continue
        flags = payload.get('ignore_speed') or [False]
        source_action_flags.add(bool(flags[0]))
    projected = copy.deepcopy(combo)
    projected['used'] = [source['instance_id']]
    projected['last_speed'] = 12
    projected['next_penalty'] = 200
    next_thirteen_legal = engine._combo_card_legal(
        owner, engine._find_card(next_thirteen['instance_id']), projected,
    )
    next_twelve_legal = engine._combo_card_legal(
        owner, engine._find_card(next_twelve['instance_id']), projected,
    )
    hp_before = int(engine.state['players'][other]['hp'])
    selected_legal = ignore_legal if select_ignore else normal_legal
    if selected_legal:
        engine._play_combo(
            owner, [source['instance_id']], [12], [False],
            [select_ignore],
        )
        engine._continue()
    return {
        'normal_legal': normal_legal,
        'ignore_legal': ignore_legal,
        'source_action_flags': sorted(source_action_flags),
        'selected_legal': selected_legal,
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st5-008-n2'
            for event in engine.events
        ),
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'damage_events': [
            copy.deepcopy(event.get('payload') or {})
            for event in engine.events if event.get('type') == 'damage_dealt'
        ],
        'event_types': [event.get('type') for event in engine.events],
        'pipeline': copy.deepcopy(engine.engine_state.get('pipeline')),
        'step': engine.engine_state.get('step'),
        'next_thirteen_legal': next_thirteen_legal,
        'next_twelve_legal': next_twelve_legal,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st5_008_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST5-008':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st5-008-function')
    repeat = by_id.get('st5-008-n1')
    combo = by_id.get('st5-008-n2')
    qna_ids = [20, 186]
    combo_rules = [{
        'optional_ignore_speed': True,
        'after_where': {'pos': '하단'},
    }]
    repeat_effects = [
        {
            'op': 'conditional',
            'condition': {
                'op': 'has_state', 'player': {'controller': True},
                'state': 'intimidation',
            },
            'then': [{
                'op': 'move_card', 'to_zone': 'list',
                'continue_resolution': True,
            }],
            'else': [],
        },
        {
            'op': 'repeat_phase', 'phase': 'ready',
            'after_current': True,
        },
    ]
    valid = bool(
        extra_root == {'combo_rules'} and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('combo_rules') == combo_rules
        and function and function.get('mode') == 'continuous'
        and function.get('active_zones') == ['battle']
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'dodge',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and repeat and repeat.get('trigger') == {'event': 'hit'}
        and repeat.get('effects') == repeat_effects
        and combo and combo.get('mode') == 'mandatory'
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('condition') == {
            'op': 'equals',
            'left': 'context.combo_speed_ignored', 'right': True,
        }
        and combo.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': -100, 'duration': 'battle',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st5-008', False,
                reason='데미스 엔드의 회피 금지·레디 반복·선택 콤보 정의가 일치하지 않습니다.',
            )],
            'ST5-008 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    dodge_scenarios = []
    for name, owner, zone, expected in (
        ('owner-p1-battle-blocks-dodge', 'p1', 'battle', True),
        ('owner-p2-battle-blocks-dodge', 'p2', 'battle', True),
        ('hand-card-does-not-block-dodge', 'p1', 'hand', False),
    ):
        first = _run_st5_008_dodge_scenario(
            definition, card_snapshot, owner, source_zone=zone,
        )
        second = _run_st5_008_dodge_scenario(
            definition, card_snapshot, owner, source_zone=zone,
        )
        deterministic = _canonical(first) == _canonical(second)
        dodge_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['dodge_blocked'] is expected
                and not first['guard_blocked']
            ),
            'deterministic': deterministic, **first,
        })
    reviews = [AbilityReview(
        function['id'], all(item['passed'] for item in dodge_scenarios),
        dodge_scenarios,
        '' if all(item['passed'] for item in dodge_scenarios)
        else '배틀 중 상대 회피만 금지하는 검증에 실패했습니다.',
    )]

    repeat_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-hit-restarts-ready', 'owner': 'p1',
            'intimidation': False, 'event_type': 'hit',
            'expected': True, 'expected_zone': 'battle',
        },
        {
            'name': 'owner-p2-intimidation-moves-to-list-before-restart',
            'owner': 'p2', 'intimidation': True, 'event_type': 'hit',
            'expected': True, 'expected_zone': 'list',
        },
        {
            'name': 'counter-does-not-restart-ready', 'owner': 'p1',
            'intimidation': True, 'event_type': 'counter',
            'expected': False, 'expected_zone': 'battle',
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected', 'expected_zone'}
        }
        first = _run_st5_008_repeat_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st5_008_repeat_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        repeat_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is spec['expected']
                and first['phase'] == ('ready' if spec['expected'] else 'battle')
                and first['source_zone'] == spec['expected_zone']
                and first['phase_restarted'] is spec['expected']
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        repeat['id'], all(item['passed'] for item in repeat_scenarios),
        repeat_scenarios,
        '' if all(item['passed'] for item in repeat_scenarios)
        else '히트 레디 반복과 위압 리스트 이동 순서 검증에 실패했습니다.',
    ))

    combo_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-lower-descending-uses-speed-ignore',
            'owner': 'p1', 'previous_pos': '하단', 'previous_speed': 13,
            'select_ignore': True, 'expected_normal': False,
            'expected_ignore': True, 'expected_damage': 400,
            'expected_resolved': True, 'expected_action_flags': [True],
        },
        {
            'name': 'owner-p2-lower-descending-uses-speed-ignore',
            'owner': 'p2', 'previous_pos': '하단', 'previous_speed': 13,
            'select_ignore': True, 'expected_normal': False,
            'expected_ignore': True, 'expected_damage': 400,
            'expected_resolved': True, 'expected_action_flags': [True],
        },
        {
            'name': 'normally-legal-lower-combo-keeps-full-damage',
            'owner': 'p1', 'previous_pos': '하단', 'previous_speed': 10,
            'select_ignore': False, 'expected_normal': True,
            'expected_ignore': True, 'expected_damage': 500,
            'expected_resolved': False,
            'expected_action_flags': [False, True],
        },
        {
            'name': 'middle-descending-combo-cannot-use-exception',
            'owner': 'p2', 'previous_pos': '중단', 'previous_speed': 13,
            'select_ignore': True, 'expected_normal': False,
            'expected_ignore': False, 'expected_damage': 0,
            'expected_resolved': False, 'expected_action_flags': [],
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'expected_normal', 'expected_ignore',
                'expected_damage', 'expected_resolved',
                'expected_action_flags',
            }
        }
        first = _run_st5_008_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st5_008_combo_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['normal_legal'] is spec['expected_normal']
                and first['ignore_legal'] is spec['expected_ignore']
                and first['source_action_flags']
                == spec['expected_action_flags']
                and first['resolved'] is spec['expected_resolved']
                and first['damage'] == spec['expected_damage']
                and first['next_thirteen_legal']
                and not first['next_twelve_legal']
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        combo['id'], all(item['passed'] for item in combo_scenarios),
        combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '선택적 속도 무시·-100·후속 속도 검증에 실패했습니다.',
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '데미스 엔드의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st5_009_source(card_snapshot, owner, suffix='source'):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-chasing-fang-{suffix}', 'owner': owner,
        'kind': 'card', 'type': '공격', 'frame': 13, 'damage': 900,
        'pos': '상단', 'body': '손', 'special': '하단 회피',
        'hit': '3', 'guard': '-9', 'counter': '콤보', 'face_up': True,
    })
    return source


def _run_st5_009_defense_scenario(
    definition, card_snapshot, owner, *, attack_damage,
    damage_modifier=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st5_009_source(card_snapshot, owner, 'defense')
    attack = _card(
        'REVIEW-CHASING-FANG-ATTACK', other,
        f'{other}-chasing-fang-attack',
    )
    attack.update({
        'owner': other, 'type': '공격', 'frame': 8,
        'damage': attack_damage, 'pos': '하단', 'body': '발',
        'special': '', 'face_up': True,
    })
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, attack, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                attack['code']: {
                    **copy.deepcopy(attack), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'chasing-fang-defense:{owner}:{attack_damage}:'
            f'{damage_modifier}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if damage_modifier:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': other, 'player': other,
            'source': f'{other}-chasing-fang-damage-modifier',
            'where': {'instance_id': attack['instance_id']},
            'stat': 'damage', 'amount': damage_modifier,
            'duration': 'battle',
        })
    live_source = engine._find_card(source['instance_id'])
    live_attack = engine._find_card(attack['instance_id'])
    return {
        'allowed': engine._defense_judgment_allowed(
            live_source, live_attack, 'dodge', other,
        ),
        'printed_damage': attack_damage,
        'effective_damage': engine.card_stat(
            live_attack, 'damage', other, include_fp=False,
        ),
    }


def _run_st5_009_speed_scenario(
    definition, card_snapshot, owner, *, opponent_speed=8,
    opponent_type='공격', opponent_speed_modifier=0,
    source_speed_modifier=0, prior_fixed_speed=None,
    source_fp=0, test_middle_dodge=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st5_009_source(card_snapshot, owner, 'speed')
    opposing = _card(
        'REVIEW-CHASING-FANG-SPEED-OPPONENT', other,
        f'{other}-chasing-fang-speed-opponent',
    )
    opposing.update({
        'owner': other, 'type': opponent_type, 'frame': opponent_speed,
        'damage': 500, 'pos': '하단', 'body': '발',
        'special': '중단 회피' if test_middle_dodge else '',
        'face_up': True,
    })
    state = _state(source, opposing, owner)
    state['players'][owner]['fp'] = source_fp
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'chasing-fang-speed:{owner}:{opponent_speed}:{opponent_type}:'
            f'{opponent_speed_modifier}:{source_speed_modifier}:'
            f'{prior_fixed_speed}:{source_fp}:{test_middle_dodge}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if source_speed_modifier:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': other, 'player': owner,
            'source': f'{other}-chasing-fang-source-speed-modifier',
            'where': {'instance_id': source['instance_id']},
            'stat': 'frame', 'amount': source_speed_modifier,
            'duration': 'battle',
        })
    if prior_fixed_speed is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': owner,
            'source': f'{other}-chasing-fang-prior-fix',
            'where': {'instance_id': source['instance_id']},
            'stat': 'frame', 'value': prior_fixed_speed,
            'duration': 'battle',
        })
    if opponent_speed_modifier:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': other, 'player': other,
            'source': f'{other}-chasing-fang-opponent-speed-modifier',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'amount': opponent_speed_modifier,
            'duration': 'battle',
        })
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    battle_source = engine.engine_state['battle'][owner]['card']
    battle_opposing = engine.engine_state['battle'][other]['card']
    context = {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': battle_source, 'opponent_card': battle_opposing,
        'controller_speed': engine.card_stat(
            battle_source, 'frame', owner, include_fp=False,
        ),
        'opponent_speed': engine.card_stat(
            battle_opposing, 'frame', other, include_fp=False,
        ),
        'source_only_event': True,
    }
    engine._fire('before_judgment', context)
    engine._continue()
    result = None
    if test_middle_dodge:
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        result = copy.deepcopy(engine.engine_state['battle']['result'])
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st5-009-n1'
            for event in engine.events
        ),
        'opponent_reference_speed': context['opponent_speed'],
        'position': battle_source.get('pos'),
        'fixed_speed': engine._fixed_stat(battle_source, 'frame', owner),
        'speed_without_fp': engine.card_stat(
            battle_source, 'frame', owner, include_fp=False,
        ),
        'speed_with_fp': engine.card_stat(
            battle_source, 'frame', owner, include_fp=True,
        ),
        'battle_result': result,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_st5_009_combo_break_scenario(
    definition, card_snapshot, owner, *, combo_number,
):
    other = 'p2' if owner == 'p1' else 'p1'
    previous = _card(
        'REVIEW-CHASING-FANG-PREVIOUS', owner,
        f'{owner}-chasing-fang-previous',
    )
    previous.update({'frame': 12, 'damage': 500})
    source = _st5_009_source(card_snapshot, owner, 'combo')
    opposing = _card(
        'REVIEW-CHASING-FANG-COMBO-OPPONENT', other,
        f'{other}-chasing-fang-combo-opponent',
    )
    state = _state(previous, opposing, owner)
    state['players'][owner]['zones']['hand'] = [copy.deepcopy(source)]
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'st5-009-n2'
    ]
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                previous['code']: {
                    **copy.deepcopy(previous), 'effect_definition': no_effect,
                },
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'chasing-fang-combo:{owner}:{combo_number}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.grant_combo(
        owner, source=previous['instance_id'], trigger_event=False,
    )
    combo = engine.engine_state['combo']
    preceding_parts = max(0, combo_number - 2)
    combo['used'] = [
        f'{owner}-chasing-fang-used-{index}'
        for index in range(preceding_parts)
    ]
    if combo_number > 3:
        combo['max_combo'] = combo_number
    combo['last_speed'] = 12
    combo['next_penalty'] = 100 * (preceding_parts + 1)
    hp_before = int(engine.state['players'][other]['hp'])
    legal = engine._combo_card_legal(
        owner, engine._find_card(source['instance_id']), combo,
        selected_speed=13,
    )
    if legal:
        engine._play_combo(owner, [source['instance_id']], [13], [False])
        engine._continue()
    return {
        'legal': legal,
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st5-009-n2'
            for event in engine.events
        ),
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'combo_interrupted': any(
            event.get('type') == 'combo_interrupted' for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st5_009_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST5-009':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st5-009-function')
    speed = by_id.get('st5-009-n1')
    combo = by_id.get('st5-009-n2')
    qna_ids = [188, 215, 358, 601, 611, 644, 657, 691]
    defense_rules = [{'judgment': 'dodge', 'max_damage': 500}]
    speed_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'card_matches',
                'card': {'path': 'context.opponent_card'},
                'where': {'type_contains': '공격'},
            },
            {
                'op': 'gte', 'left': 'context.opponent_speed',
                'right': 8,
            },
        ],
    }
    combo_condition = {
        'op': 'all',
        'conditions': [
            {'op': 'gte', 'left': 'context.combo_number', 'right': 2},
            {'op': 'lte', 'left': 'context.combo_number', 'right': 3},
        ],
    }
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('defense_rules') == defense_rules
        and function and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and speed and speed.get('trigger') == {'event': 'before_judgment'}
        and speed.get('condition') == speed_condition
        and speed.get('effects') == [
            {
                'op': 'fix_speed', 'player': {'controller': True},
                'stat': 'frame', 'value': 7, 'duration': 'battle',
            },
            {
                'op': 'modify_judgment', 'player': {'controller': True},
                'field': 'pos', 'value': '중단',
            },
        ]
        and combo and combo.get('trigger') == {'event': 'combo'}
        and combo.get('condition') == combo_condition
        and combo.get('effects') == [{
            'op': 'break_card', 'continue_resolution': True,
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st5-009', False,
                reason='체이싱 팽의 데미지 회피·속도 고정·콤보 브레이크 정의가 일치하지 않습니다.',
            )],
            'ST5-009 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for spec in (
        {
            'name': 'five-hundred-damage-can-be-dodged',
            'owner': 'p1', 'attack_damage': 500,
            'expected': True,
        },
        {
            'name': 'five-hundred-one-damage-cannot-be-dodged',
            'owner': 'p2', 'attack_damage': 501,
            'expected': False,
        },
        {
            'name': 'qna-358-modified-six-hundred-cannot-be-dodged',
            'owner': 'p1', 'attack_damage': 500, 'damage_modifier': 100,
            'expected': False,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected'}
        }
        first = _run_st5_009_defense_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st5_009_defense_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['allowed'] is spec['expected']
            ),
            'deterministic': deterministic, **first,
        })
    reviews = [AbilityReview(
        function['id'], all(item['passed'] for item in defense_scenarios),
        defense_scenarios,
        '' if all(item['passed'] for item in defense_scenarios)
        else '500데미지 회피 경계·효과 데미지 검증에 실패했습니다.',
    )]

    speed_scenarios = []
    speed_specs = (
        {
            'name': 'qna-188-owner-p1-negative-fp-still-fixed-seven',
            'owner': 'p1', 'opponent_speed': 8, 'source_fp': -3,
            'expected': True, 'expected_speed': 7,
        },
        {
            'name': 'owner-p2-speed-seven-does-not-trigger',
            'owner': 'p2', 'opponent_speed': 7,
            'expected': False, 'expected_speed': 13,
        },
        {
            'name': 'defense-technique-speed-eight-does-not-trigger',
            'owner': 'p1', 'opponent_speed': 8,
            'opponent_type': '수비',
            'expected': False, 'expected_speed': 13,
        },
        {
            'name': 'qna-601-earlier-speed-change-below-eight-prevents-trigger',
            'owner': 'p2', 'opponent_speed': 8,
            'opponent_speed_modifier': -2,
            'expected': False, 'expected_speed': 13,
        },
        {
            'name': 'qna-657-earlier-slowdown-is-overwritten-by-seven-fix',
            'owner': 'p1', 'opponent_speed': 8,
            'source_speed_modifier': 4,
            'expected': True, 'expected_speed': 7,
        },
        {
            'name': 'qna-691-earlier-fix-keeps-first-speed-but-position-changes',
            'owner': 'p2', 'opponent_speed': 8,
            'prior_fixed_speed': 13,
            'expected': True, 'expected_speed': 13,
        },
        {
            'name': 'qna-215-middle-change-allows-opponent-dodge',
            'owner': 'p1', 'opponent_speed': 8,
            'test_middle_dodge': True,
            'expected': True, 'expected_speed': 7,
            'expected_result': 'dodge',
        },
    )
    for spec in speed_specs:
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'expected', 'expected_speed', 'expected_result',
            }
        }
        first = _run_st5_009_speed_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st5_009_speed_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        result_ok = True
        if spec.get('expected_result'):
            result_ok = bool(
                first['battle_result']
                and first['battle_result'].get(spec['owner'])
                == spec['expected_result']
            )
        speed_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is spec['expected']
                and first['speed_without_fp'] == spec['expected_speed']
                and first['speed_with_fp'] == spec['expected_speed']
                and first['position']
                == ('중단' if spec['expected'] else '상단')
                and result_ok and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        speed['id'], all(item['passed'] for item in speed_scenarios),
        speed_scenarios,
        '' if all(item['passed'] for item in speed_scenarios)
        else '상대 효과 속도·우선권·7속도 고정·중단 변경 검증에 실패했습니다.',
    ))

    combo_scenarios = []
    for name, owner, number, expected_break, expected_damage in (
        ('owner-p1-two-combo-breaks-after-eight-hundred', 'p1', 2, True, 800),
        ('owner-p2-three-combo-breaks-after-seven-hundred', 'p2', 3, True, 700),
        ('four-combo-does-not-break', 'p1', 4, False, 600),
    ):
        first = _run_st5_009_combo_break_scenario(
            definition, card_snapshot, owner, combo_number=number,
        )
        second = _run_st5_009_combo_break_scenario(
            definition, card_snapshot, owner, combo_number=number,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['legal']
                and first['resolved'] is expected_break
                and first['damage'] == expected_damage
                and first['source_zone']
                == ('break' if expected_break else 'list')
                and not first['combo_interrupted'] and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        combo['id'], all(item['passed'] for item in combo_scenarios),
        combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '2·3콤보 브레이크와 현재 대미지 지속 검증에 실패했습니다.',
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '체이싱 팽의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st5_010_source(card_snapshot, owner, suffix='source'):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-tabula-{suffix}', 'owner': owner,
        'kind': 'card', 'type': '수비', 'frame': None, 'damage': None,
        'g_top': '회피', 'g_mid': '상쇄', 'g_bot': '',
        'face_up': True,
    })
    return source


def _run_st5_010_defense_scenario(
    definition, card_snapshot, owner, *, attack_pos, attack_speed,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st5_010_source(card_snapshot, owner, 'defense')
    attack = _card(
        'REVIEW-TABULA-ATTACK', other, f'{other}-tabula-attack',
    )
    attack.update({
        'owner': other, 'type': '공격', 'frame': attack_speed,
        'damage': 500, 'pos': attack_pos, 'face_up': True,
    })
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, attack, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                attack['code']: {
                    **copy.deepcopy(attack), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'tabula-defense:{owner}:{attack_pos}:{attack_speed}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    result = engine._attack_vs_defense(
        engine._find_card(attack['instance_id']),
        engine._find_card(source['instance_id']), other, owner,
    )
    return {'result': list(result)}


def _run_st5_010_dodge_scenario(
    definition, card_snapshot, owner, *, event_type='dodge',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st5_010_source(card_snapshot, owner, 'dodge')
    opposing = _card(
        'REVIEW-TABULA-DODGE-OPPONENT', other,
        f'{other}-tabula-dodge-opponent',
    )
    state = _state(source, opposing, owner)
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'tabula-dodge:{owner}:{event_type}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    hp_before = int(engine.state['players'][other]['hp'])
    fp_before = int(engine.state['players'][owner]['fp'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True,
    })
    engine._continue()
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st5-010-n1'
            for event in engine.events
        ),
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'fp_gain': int(engine.state['players'][owner]['fp']) - fp_before,
        'controller_catch_blocked': engine._rule_blocked(
            'catch', owner, engine._find_card(source['instance_id']),
            engine._find_card(opposing['instance_id']),
        ),
        'opponent_catch_blocked': engine._rule_blocked(
            'catch', other, engine._find_card(opposing['instance_id']),
            engine._find_card(source['instance_id']),
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_st5_010_clash_scenario(
    definition, card_snapshot, owner, *, opponent_hp=4000,
    reset_after_combo=False, event_type='clash',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st5_010_source(card_snapshot, owner, 'clash')
    opposing = _card(
        'REVIEW-TABULA-CLASH-OPPONENT', other,
        f'{other}-tabula-clash-opponent',
    )
    opposing.update({'frame': 8, 'damage': 700, 'pos': '중단'})
    state = _state(source, opposing, owner)
    state['players'][other]['hp'] = opponent_hp
    state['players'][other]['fp'] = 7
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'tabula-clash:{owner}:{opponent_hp}:'
            f'{reset_after_combo}:{event_type}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    hp_before = int(engine.state['players'][other]['hp'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine.engine_state['battle'][owner]['card'],
        'opponent_card': engine.engine_state['battle'][other]['card'],
        'source_only_event': True,
    })
    engine._continue()
    fp_after_effect = int(engine.state['players'][other]['fp'])
    opposing_after_effect = (
        engine.engine_state.get('battle', {}).get(other, {}).get('card')
        or engine._find_card(opposing['instance_id']) or opposing
    )
    opponent_damage_after_effect = engine.card_stat(
        opposing_after_effect, 'damage', other, include_fp=False,
    )
    if reset_after_combo and engine.engine_state.get('status') == 'running':
        engine.grant_combo(other, source=opposing['instance_id'])
        engine.end_combo()
        engine._continue()
    live_opposing = engine.engine_state.get('battle', {}).get(other, {}).get('card')
    if not live_opposing:
        live_opposing = engine._find_card(opposing['instance_id']) or opposing
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st5-010-n2'
            for event in engine.events
        ),
        'opponent_damage': engine.card_stat(
            live_opposing, 'damage', other, include_fp=False,
        ),
        'opponent_damage_after_effect': opponent_damage_after_effect,
        'effect_damage': hp_before - int(engine.state['players'][other]['hp']),
        'fp_after_effect': fp_after_effect,
        'fp_after_combo': int(engine.state['players'][other]['fp']),
        'controller_fp_after_combo': int(engine.state['players'][owner]['fp']),
        'winner': engine.engine_state.get('winner'),
        'reason': engine.engine_state.get('reason'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st5_010_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST5-010':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st5-010-function')
    dodge = by_id.get('st5-010-n1')
    clash = by_id.get('st5-010-n2')
    qna_ids = [171, 341, 575]
    defense_rules = [
        {'judgment': 'dodge', 'max_speed': 9},
        {'judgment': 'clash', 'max_speed': 9},
    ]
    dodge_effects = [
        {
            'op': 'deal_damage', 'player': {'opponent': True},
            'amount': 300,
        },
        {
            'op': 'change_fp', 'player': {'controller': True},
            'amount': 5,
        },
        {
            'op': 'prevent', 'kind': 'catch',
            'player': {'controller': True}, 'duration': 'turn',
        },
    ]
    clash_effects = [
        {
            'op': 'modify_stat', 'player': {'opponent': True},
            'stat': 'damage', 'amount': -400, 'duration': 'battle',
        },
        {
            'op': 'deal_damage', 'player': {'opponent': True},
            'amount': 200,
        },
        {'op': 'reset_fp', 'player': {'opponent': True}},
        {
            'op': 'change_fp', 'player': {'opponent': True}, 'amount': 1,
        },
    ]
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('defense_rules') == defense_rules
        and function and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and dodge and dodge.get('trigger') == {'event': 'dodge'}
        and dodge.get('effects') == dodge_effects
        and clash and clash.get('trigger') == {'event': 'clash'}
        and clash.get('effects') == clash_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st5-010', False,
                reason='타뷸라의 속도 수비·회피·상쇄 정의가 일치하지 않습니다.',
            )],
            'ST5-010 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, pos, speed_value, expected in (
        ('upper-speed-nine-dodges', 'p1', '상단', 9, ['opponent_dodge', 'dodge']),
        ('middle-speed-nine-clashes', 'p2', '중단', 9, ['clash', 'clash']),
        ('upper-speed-ten-fails', 'p1', '상단', 10, ['hit', 'failed_defense']),
        ('middle-speed-ten-fails', 'p2', '중단', 10, ['hit', 'failed_defense']),
        ('qna-341-empty-lower-remains-no-defense', 'p1', '하단', 8, ['hit', 'failed_defense']),
    ):
        first = _run_st5_010_defense_scenario(
            definition, card_snapshot, owner,
            attack_pos=pos, attack_speed=speed_value,
        )
        second = _run_st5_010_defense_scenario(
            definition, card_snapshot, owner,
            attack_pos=pos, attack_speed=speed_value,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name,
            'passed': bool(deterministic and first['result'] == expected),
            'deterministic': deterministic, **first,
        })
    reviews = [AbilityReview(
        function['id'], all(item['passed'] for item in defense_scenarios),
        defense_scenarios,
        '' if all(item['passed'] for item in defense_scenarios)
        else '상단 회피·중단 상쇄·빈 하단 및 속도 경계 검증에 실패했습니다.',
    )]

    dodge_scenarios = []
    for name, owner, event_type, expected in (
        ('owner-p1-dodge-applies-all-effects', 'p1', 'dodge', True),
        ('owner-p2-dodge-applies-all-effects', 'p2', 'dodge', True),
        ('opponent-dodge-does-not-trigger', 'p1', 'opponent_dodge', False),
    ):
        first = _run_st5_010_dodge_scenario(
            definition, card_snapshot, owner, event_type=event_type,
        )
        second = _run_st5_010_dodge_scenario(
            definition, card_snapshot, owner, event_type=event_type,
        )
        deterministic = _canonical(first) == _canonical(second)
        dodge_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is expected
                and first['damage'] == (300 if expected else 0)
                and first['fp_gain'] == (5 if expected else 0)
                and first['controller_catch_blocked'] is expected
                and not first['opponent_catch_blocked'] and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        dodge['id'], all(item['passed'] for item in dodge_scenarios),
        dodge_scenarios,
        '' if all(item['passed'] for item in dodge_scenarios)
        else '회피 300데미지·5FP·자신 캐치 금지 검증에 실패했습니다.',
    ))

    clash_scenarios = []
    clash_specs = (
        {
            'name': 'owner-p1-clash-reduces-damage-and-adjusts-fp',
            'owner': 'p1', 'expected': True,
        },
        {
            'name': 'qna-171-combo-end-clears-adjusted-fp',
            'owner': 'p2', 'reset_after_combo': True,
            'expected': True,
        },
        {
            'name': 'qna-575-effect-damage-wins-before-clash-damage',
            'owner': 'p1', 'opponent_hp': 200,
            'expected': True, 'expected_winner': 'p1',
        },
        {
            'name': 'wrong-guard-trigger-does-nothing',
            'owner': 'p2', 'event_type': 'guard',
            'expected': False,
        },
    )
    for spec in clash_specs:
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected', 'expected_winner'}
        }
        first = _run_st5_010_clash_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_st5_010_clash_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected = spec['expected']
        combo_reset_ok = (
            first['fp_after_combo'] == 0
            and first['controller_fp_after_combo'] == 0
        ) if spec.get('reset_after_combo') else True
        winner_ok = (
            first['winner'] == spec.get('expected_winner')
        ) if spec.get('expected_winner') else first['winner'] is None
        clash_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is expected
                and first['opponent_damage_after_effect']
                == (300 if expected else 700)
                and first['effect_damage'] == (200 if expected else 0)
                and first['fp_after_effect'] == (1 if expected else 7)
                and combo_reset_ok and winner_ok and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        clash['id'], all(item['passed'] for item in clash_scenarios),
        clash_scenarios,
        '' if all(item['passed'] for item in clash_scenarios)
        else '상쇄 -400·별도 200데미지·FP +1 조정 검증에 실패했습니다.',
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '타뷸라의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


