def _run_awl_at_036_lock_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_036_source(card_snapshot, owner, 'lock')
    opposing = _card(
        'REVIEW-DICETIED-LOCK-OPPONENT', other,
        f'{other}-dicetied-lock-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'awl-at-036-function'
    ]
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, opposing, owner, source_zone=source_zone),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'dicetied-lock:{owner}:{source_zone}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._refresh_continuous_rules()
    return {
        'clash_blocked': engine._rule_blocked(
            'clash', other, engine._find_card(opposing['instance_id']),
            engine._find_card(source['instance_id']),
        ),
        'dodge_blocked': engine._rule_blocked(
            'dodge', other, engine._find_card(opposing['instance_id']),
            engine._find_card(source['instance_id']),
        ),
    }


def _run_awl_at_036_damage_scenario(
    definition, card_snapshot, owner, *, event_type='opponent_guard',
    qna_priority=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_036_source(card_snapshot, owner, 'damage')
    opposing = _card(
        'REVIEW-DICETIED-FORCE-PARRYING', other,
        f'{other}-dicetied-force-parrying',
    )
    opposing.update({
        'type': '수비', 'g_top': '방어', 'g_mid': '방어', 'g_bot': '방어',
    })
    opposing_definition = _st1_001_no_effect_definition()
    if qna_priority:
        opposing_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [36], 'qna_ids': [576]},
            'abilities': [{
                'id': 'review-force-parrying-guard-damage',
                'label': '방어 시 상대에게 500데미지',
                'kind': 'effect', 'mode': 'mandatory',
                'timing': 'guard', 'visibility': 'public',
                'source_refs': {'rulebook_pages': [36], 'qna_ids': [576]},
                'trigger': {'event': 'guard'},
                'effects': [{
                    'op': 'deal_damage', 'player': {'opponent': True},
                    'amount': 500,
                }],
            }],
        }
    state = _state(source, opposing, owner)
    if qna_priority:
        state['players'][owner]['hp'] = 500
        state['players'][other]['hp'] = 100
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': opposing_definition,
                },
            },
        },
        seed=f'dicetied-damage:{owner}:{event_type}:{qna_priority}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    hp_before = int(engine.state['players'][other]['hp'])
    trigger_order = []
    if qna_priority:
        sequence = engine._result_trigger_sequence({
            owner: 'guarded', other: 'guard',
        })
        trigger_order = [item[0] for item in sequence]
        for queued_event, context in sequence:
            if engine.engine_state.get('status') != 'running':
                break
            engine._fire(queued_event, context)
            engine._continue()
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': engine.engine_state['battle'][owner]['card'],
            'opponent_card': engine.engine_state['battle'][other]['card'],
            'source_only_event': True,
        })
        engine._continue()
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'awl-at-036-n1'
            for event in engine.events
        ),
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'winner': engine.engine_state.get('winner'),
        'trigger_order': trigger_order,
        'force_parrying_resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'review-force-parrying-guard-damage'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_036_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-036':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-036-function')
    guarded = by_id.get('awl-at-036-n1')
    qna_ids = [576]
    valid = bool(
        not extra_root and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and function and function.get('active_zones') == ['battle']
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'clash',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and guarded and guarded.get('trigger') == {'event': 'opponent_guard'}
        and guarded.get('effects') == [{
            'op': 'deal_damage', 'player': {'opponent': True},
            'amount': 100,
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-036', False,
                reason='다이스티드의 상쇄 금지·상대 방어 데미지 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-036 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    lock_scenarios = []
    for name, owner, zone, expected in (
        ('owner-p1-battle-blocks-clash', 'p1', 'battle', True),
        ('owner-p2-battle-blocks-clash', 'p2', 'battle', True),
        ('hand-card-does-not-block-clash', 'p1', 'hand', False),
    ):
        first = _run_awl_at_036_lock_scenario(
            definition, card_snapshot, owner, source_zone=zone,
        )
        second = _run_awl_at_036_lock_scenario(
            definition, card_snapshot, owner, source_zone=zone,
        )
        deterministic = _canonical(first) == _canonical(second)
        lock_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['clash_blocked'] is expected
                and not first['dodge_blocked']
            ),
            'deterministic': deterministic, **first,
        })
    reviews = [AbilityReview(
        function['id'], all(item['passed'] for item in lock_scenarios),
        lock_scenarios,
        '' if all(item['passed'] for item in lock_scenarios)
        else '배틀 중 상대 상쇄만 금지하는 검증에 실패했습니다.',
    )]

    damage_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-opponent-guard-deals-one-hundred',
            'owner': 'p1', 'event_type': 'opponent_guard',
            'expected': True,
        },
        {
            'name': 'owner-p2-opponent-guard-deals-one-hundred',
            'owner': 'p2', 'event_type': 'opponent_guard',
            'expected': True,
        },
        {
            'name': 'own-guard-event-does-not-trigger',
            'owner': 'p1', 'event_type': 'guard',
            'expected': False,
        },
        {
            'name': 'qna-576-guard-effect-wins-before-opponent-guard-effect',
            'owner': 'p1', 'qna_priority': True,
            'expected': False, 'expected_winner': 'p2',
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected', 'expected_winner'}
        }
        first = _run_awl_at_036_damage_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_awl_at_036_damage_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        qna_ok = True
        if spec.get('expected_winner'):
            qna_ok = bool(
                first['winner'] == spec['expected_winner']
                and first['trigger_order'][:2]
                == ['guard', 'opponent_guard']
                and first['force_parrying_resolved']
            )
        damage_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is spec['expected']
                and first['damage'] == (100 if spec['expected'] else 0)
                and qna_ok and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        guarded['id'], all(item['passed'] for item in damage_scenarios),
        damage_scenarios,
        '' if all(item['passed'] for item in damage_scenarios)
        else '방어/상대 방어 타이밍과 100데미지 검증에 실패했습니다.',
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '다이스티드의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


