def _review_awl_at_021_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-021':
        return None
    qna_ids = [680, 681, 682, 683]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-021-function')
    effect = by_id.get('awl-at-021-n1')
    fixed_condition = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'opponent': True},
    }
    effect_nodes = [
        {
            'op': 'fix_speed', 'player': {'controller': True},
            'stat': 'frame',
            'value': {'path': 'context.fixed_speed'},
            'duration': 'battle',
        },
        {
            'op': 'prevent', 'kind': 'damage',
            'player': {'controller': True},
            'duration': 'battle', 'max_uses': 1,
        },
    ]
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 2
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and definition.get('defense_rules') == [{
            'judgment': 'clash', 'min_speed': 9,
        }]
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and not function.get('trigger') and not function.get('condition')
        and not function.get('active_zones')
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and effect and effect.get('kind') == 'effect'
        and effect.get('mode') == 'mandatory'
        and effect.get('timing') == 'use'
        and effect.get('active_zones') == ['battle']
        and effect.get('trigger') == {'event': 'speed_fixed'}
        and effect.get('condition') == fixed_condition
        and effect.get('effects') == effect_nodes
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-021', False,
                reason='상쇄 속도 제한·속도 고정 반응·다음 피해 1회 무효 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-021 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    function_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-speed-nine-boundary-allows-clash',
            'owner': 'p1', 'opponent_speed': 9,
            'expected_allowed': True, 'expected_result': 'clash',
        },
        {
            'name': 'owner-p2-speed-nine-boundary-allows-clash',
            'owner': 'p2', 'opponent_speed': 9,
            'expected_allowed': True, 'expected_result': 'clash',
        },
        {
            'name': 'speed-eight-is-below-clash-limit',
            'owner': 'p1', 'opponent_speed': 8,
            'expected_allowed': False, 'expected_result': 'countered',
        },
        {
            'name': 'speed-twelve-passes-rule-although-wingstar-counters',
            'owner': 'p2', 'opponent_speed': 12,
            'expected_allowed': True, 'expected_result': 'counter',
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected_allowed', 'expected_result'}
        }
        first = _run_awl_at_021_clash_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_awl_at_021_clash_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        function_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['allowed'] is spec['expected_allowed']
                and first['stage'] == 'after_judgment'
                and first['result'].get(spec['owner'])
                == spec['expected_result']
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    effect_scenarios = []
    direct_specs = (
        {
            'name': 'owner-p1-copies-eight-and-prevents-only-first-damage',
            'owner': 'p1', 'fixed_speed': 8,
            'damage_amounts': (500, 300),
            'expected_resolved': True, 'expected_speed': 8,
            'expected_actual': [0, 300], 'expected_loss': 300,
            'expected_before': 1, 'expected_after': 0,
        },
        {
            'name': 'owner-p2-copies-twelve-and-prevents-next-damage',
            'owner': 'p2', 'fixed_speed': 12,
            'damage_amounts': (700,),
            'expected_resolved': True, 'expected_speed': 12,
            'expected_actual': [0], 'expected_loss': 0,
            'expected_before': 1, 'expected_after': 0,
        },
        {
            'name': 'own-speed-fixed-event-does-not-trigger',
            'owner': 'p1', 'event_controller': 'self',
            'fixed_speed': 7, 'damage_amounts': (500,),
            'expected_resolved': False, 'expected_speed': 10,
            'expected_actual': [500], 'expected_loss': 500,
            'expected_before': 0, 'expected_after': 0,
        },
        {
            'name': 'hand-zone-wingstar-does-not-react',
            'owner': 'p2', 'source_zone': 'hand', 'fixed_speed': 8,
            'damage_amounts': (), 'expected_resolved': False,
            'expected_speed': 10, 'expected_actual': [], 'expected_loss': 0,
            'expected_before': 0, 'expected_after': 0,
        },
        {
            'name': 'numbered-negation-suppresses-reaction',
            'owner': 'p1', 'fixed_speed': 8,
            'numbered_effects_negated': True,
            'damage_amounts': (500,), 'expected_resolved': False,
            'expected_speed': 10, 'expected_actual': [500],
            'expected_loss': 500, 'expected_before': 0,
            'expected_after': 0,
        },
        {
            'name': 'unused-prevention-expires-at-battle-end',
            'owner': 'p2', 'fixed_speed': 8, 'expire_battle': True,
            'damage_amounts': (500,), 'expected_resolved': True,
            'expected_speed': 10, 'expected_actual': [500],
            'expected_loss': 500, 'expected_before': 1,
            'expected_after': 0,
        },
    )
    for spec in direct_specs:
        expected_keys = {
            'expected_resolved', 'expected_speed', 'expected_actual',
            'expected_loss', 'expected_before', 'expected_after', 'name',
        }
        kwargs = {
            key: value for key, value in spec.items()
            if key not in expected_keys
        }
        first = _run_awl_at_021_reaction_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_awl_at_021_reaction_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        effect_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['resolved'] is spec['expected_resolved']
                and first['source_speed'] == spec['expected_speed']
                and first['actual_damage'] == spec['expected_actual']
                and first['hp_loss'] == spec['expected_loss']
                and first['replacements_before_expiry']
                == spec['expected_before']
                and first['replacements_after'] == spec['expected_after']
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    for spec in (
        {
            'name': 'qna-680-wingstar-priority-reacts-after-use-lock',
            'owner': 'p1', 'priority': 'wingstar', 'fixed_speed': 8,
        },
        {
            'name': 'qna-680-lock-owner-priority-still-triggers-wingstar',
            'owner': 'p2', 'priority': 'opponent', 'fixed_speed': 8,
        },
    ):
        first = _run_awl_at_021_use_lock_scenario(
            definition, card_snapshot, **{
                key: value for key, value in spec.items() if key != 'name'
            },
        )
        second = _run_awl_at_021_use_lock_scenario(
            definition, card_snapshot, **{
                key: value for key, value in spec.items() if key != 'name'
            },
        )
        deterministic = _canonical(first) == _canonical(second)
        effect_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['stage'] == 'after_judgment'
                and first['source_speed'] == 8
                and first['opponent_speed'] == 8
                and first['result'] == {'p1': 'hit', 'p2': 'hit'}
                and first['source_hp_loss'] == 0
                and first['opponent_hp_loss'] == 500
                and first['wingstar_resolutions'] == 1
                and first['lock_resolutions'] == 1
                and first['combo_result'] == 'mutual'
                and first['mutual_combo_events'] == 1
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    for spec in (
        {
            'name': 'qna-681-charging-nine-counters-for-zero-and-gains-five-fp',
            'owner': 'p1', 'priority': 'wingstar', 'charging_speed': 9,
            'expected_result': 'countered', 'expected_fp': 5,
        },
        {
            'name': 'qna-681-priority-does-not-change-nine-vs-ten-order',
            'owner': 'p2', 'priority': 'opponent', 'charging_speed': 9,
            'expected_result': 'countered', 'expected_fp': 5,
        },
        {
            'name': 'qna-681-charging-eleven-leaves-wingstar-counter',
            'owner': 'p1', 'priority': 'opponent', 'charging_speed': 11,
            'expected_result': 'counter', 'expected_fp': 0,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'expected_result', 'expected_fp'}
        }
        first = _run_awl_at_021_charging_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_awl_at_021_charging_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        effect_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['stage'] == 'after_judgment'
                and first['source_speed'] == 10
                and first['charging_speed'] == spec['charging_speed']
                and first['result'].get(spec['owner'])
                == spec['expected_result']
                and first['source_hp_loss'] == 0
                and first['charging_fp'] == spec['expected_fp']
                and first['wingstar_resolutions'] == 1
                and first['charging_resolutions'] == 1
                and first['wingstar_fixed_values'] == [10, spec['charging_speed']]
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            function['id'],
            all(item['passed'] for item in function_scenarios),
            function_scenarios,
            '' if all(item['passed'] for item in function_scenarios)
            else '9속도 경계의 중단 상쇄 제한 검증에 실패했습니다.',
        ),
        AbilityReview(
            effect['id'], all(item['passed'] for item in effect_scenarios),
            effect_scenarios,
            '' if all(item['passed'] for item in effect_scenarios)
            else '속도 고정 후속 처리·피해 1회 무효·콤보 Q&A 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '윙스타의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_at_023_source(card_snapshot, owner, suffix):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-dominate-{suffix}', 'owner': owner,
        'code': 'AWL-AT-023', 'name': '도미네이트', 'type': '수비',
        'frame': None, 'damage': None, 'pos': None, 'body': '',
        'special': '', 'hit': '', 'guard': '', 'counter': '',
        'g_top': '회피', 'g_mid': '회피', 'g_bot': '회피',
        'face_up': True,
    })
    return source


def _run_awl_at_023_dodge_scenario(
    definition, card_snapshot, owner, *, opponent_speed,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_023_source(card_snapshot, owner, 'dodge')
    opposing = _card(
        'REVIEW-DOMINATE-DODGE-OPPONENT', other,
        f'{other}-dominate-dodge-opponent-{opponent_speed}',
    )
    opposing.update({
        'frame': opponent_speed, 'damage': 400,
        'pos': '중단', 'special': '', 'hit': '0', 'counter': '0',
        'face_up': True,
    })
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'awl-at-023-function'
    ]
    no_effect = _st1_001_no_effect_definition()
    state = _state(source, opposing, owner)
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': no_effect,
                },
            },
        },
        seed=f'dominate-dodge:{owner}:{opponent_speed}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    allowed = engine._defense_judgment_allowed(
        engine._find_card(source['instance_id']),
        engine._find_card(opposing['instance_id']), 'dodge', other,
    )
    pipeline = _advance_review_battle_to_after_judgment(engine, {
        owner: source['instance_id'], other: opposing['instance_id'],
    })
    battle = engine.engine_state.get('battle') or {}
    return {
        'allowed': allowed, 'stage': pipeline.get('stage'),
        'result': copy.deepcopy(battle.get('result') or {}),
        'hp_loss': 4000 - int(engine.state['players'][owner]['hp']),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _awl_at_023_stormbringer_definition():
    play_condition = {
        'op': 'zone_count', 'player': {'controller': True},
        'zone': 'lumen',
        'where': {'code': 'AWL-SP-001', 'face_up': True},
        'min': 1,
    }
    return {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [], 'qna_ids': [586]},
        'play_condition': play_condition,
        'abilities': [{
            'id': 'review-stormbringer-play-condition',
            'label': '루멘 존에 공개 올 인 차지가 있어야 사용할 수 있다',
            'kind': 'function', 'mode': 'continuous',
            'timing': 'function', 'visibility': 'public',
            'source_refs': {'rulebook_pages': [], 'qna_ids': [586]},
            'effects': [{
                'op': 'static_rule', 'rules': ['play_condition'],
            }],
        }],
    }


def _run_awl_at_023_catch_scenario(
    definition, card_snapshot, owner, *, event_type='dodge',
    source_zone='battle', numbered_effects_negated=False,
    include_ordinary=True, include_storm=False, all_in='none',
    include_list_charge=True, include_mention=True, select=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_023_source(card_snapshot, owner, 'catch')
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-DOMINATE-CATCH-OPPONENT', other,
        f'{other}-dominate-catch-opponent',
    )
    opposing.update({'damage': 400, 'face_up': True})
    ordinary = _card(
        'REVIEW-DOMINATE-CHARGE', owner,
        f'{owner}-dominate-charge',
    )
    ordinary.update({
        'name': '차지 효과 기술', 'frame': 7, 'damage': 500,
        'text': '①[[state:charge]]: 이 기술 데미지+100',
        'hit': '2', 'counter': '1', 'face_up': False,
    })
    plain = _card(
        'REVIEW-DOMINATE-PLAIN', owner,
        f'{owner}-dominate-plain',
    )
    plain.update({'name': '차지 없는 기술', 'text': '', 'face_up': False})
    mention = _card(
        'REVIEW-DOMINATE-CHARGE-MENTION', owner,
        f'{owner}-dominate-charge-mention',
    )
    mention.update({
        'name': '차지를 언급만 하는 기술',
        'text': '①사용 후, [[state:charge]]상태를 해제한다.',
        'face_up': False,
    })
    listed = _card(
        'REVIEW-DOMINATE-LIST-CHARGE', owner,
        f'{owner}-dominate-list-charge',
    )
    listed.update({
        'name': '리스트 차지 기술',
        'text': '[[state:charge]]: 이 기술 데미지+200',
        'face_up': True,
    })
    special = _card(
        'REVIEW-DOMINATE-SPECIAL-CHARGE', owner,
        f'{owner}-dominate-special-charge',
    )
    special.update({
        'name': '특수 차지 기술', 'type': '특수',
        'frame': None, 'damage': None,
        'text': '[[state:charge]]: 테스트', 'face_up': False,
    })
    storm = _card(
        'LMI-AT-016', owner, f'{owner}-dominate-stormbringer',
    )
    storm.update({
        'name': '스톰브링거', 'frame': 14, 'damage': 600,
        'pos': '상단', 'body': '', 'special': '',
        'hit': '3', 'counter': '3',
        'text': '[[state:charge]]: 이 기술은 14속도로 고정된다.',
        'face_up': False,
    })
    all_in_card = _card(
        'AWL-SP-001', owner, f'{owner}-dominate-all-in-charge',
    )
    all_in_card.update({
        'name': '올 인 차지', 'type': '특수',
        'frame': None, 'damage': None,
        'face_up': all_in == 'face_up',
    })
    if all_in == 'face_down':
        all_in_card.update({
            'non_technique_while_face_down': True,
            'effects_negated': True,
        })

    state = _state(source, opposing, owner, source_zone=source_zone)
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    hand = [plain, special]
    if include_ordinary:
        hand.append(ordinary)
    if include_mention:
        hand.append(mention)
    if include_storm:
        hand.append(storm)
    state['players'][owner]['zones']['hand'].extend(copy.deepcopy(hand))
    if include_list_charge:
        state['players'][owner]['zones']['list'].append(copy.deepcopy(listed))
    if all_in != 'none':
        state['players'][owner]['zones']['lumen'].append(
            copy.deepcopy(all_in_card)
        )
    cards = [source, opposing, *hand]
    if include_list_charge:
        cards.append(listed)
    if all_in != 'none':
        cards.append(all_in_card)
    no_effect = _st1_001_no_effect_definition()
    definitions = {
        storm['code']: _awl_at_023_stormbringer_definition(),
    }
    ruleset_cards = {
        card['code']: {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(
                definition if card['code'] == source['code']
                else definitions.get(card['code'], no_effect)
            ),
        }
        for card in cards
    }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'dominate-catch:{owner}:{event_type}:{source_zone}:'
            f'{int(numbered_effects_negated)}:{int(include_ordinary)}:'
            f'{int(include_storm)}:{all_in}:{int(include_list_charge)}:'
            f'{int(include_mention)}:{select}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(engine._find_card(source['instance_id'])),
        'opponent_card': copy.deepcopy(
            engine._find_card(opposing['instance_id'])
        ),
        'source_only_event': True,
    })
    grants = copy.deepcopy(engine.engine_state.get('granted_catches') or [])
    legal_ids = []
    selected_id = None
    selected_location = ()
    hp_before = int(engine.state['players'][other]['hp'])
    if grants:
        engine._open_catch_or_cleanup()
        legal_ids = sorted(
            card['instance_id']
            for card in engine._legal_catch_cards(
                owner, engine.engine_state.get('catch') or {},
            )
        )
        selected_id = {
            'ordinary': ordinary['instance_id'],
            'storm': storm['instance_id'],
        }.get(select)
        if selected_id and selected_id in legal_ids:
            engine._play_catch(owner, selected_id)
            selected_location = engine._find_location(selected_id)
            engine._continue()
    if selected_id and not selected_location:
        selected_location = engine._find_location(selected_id)
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-023-n1' for event in engine.events
        ),
        'grant_count': len(grants),
        'grant_zones': (grants[0].get('allow_zones') if grants else []),
        'grant_where': (grants[0].get('where') if grants else {}),
        'legal_ids': legal_ids,
        'ordinary_id': ordinary['instance_id'],
        'plain_id': plain['instance_id'],
        'mention_id': mention['instance_id'],
        'list_id': listed['instance_id'],
        'special_id': special['instance_id'],
        'storm_id': storm['instance_id'],
        'selected_id': selected_id,
        'selected_zone': selected_location[1] if selected_location else None,
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'catch_damage_events': [
            (event.get('payload') or {}).get('amount')
            for event in engine.events
            if event.get('type') == 'damage_dealt'
            and (event.get('payload') or {}).get('source') == 'catch'
        ],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_023_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-023':
        return None
    qna_ids = [586, 667]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-023-function')
    catch = by_id.get('awl-at-023-n1')
    defense_rules = [{
        'judgment': 'dodge', 'min_speed': 8, 'max_speed': 9,
    }]
    catch_effects = [{
        'op': 'grant_catch', 'player': {'controller': True},
        'allow_zones': ['hand'],
        'where': {'text_effect_prefix': '[[state:charge]]'},
    }]
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 2
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and definition.get('defense_rules') == defense_rules
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and not function.get('trigger') and not function.get('condition')
        and not function.get('active_zones')
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and catch and catch.get('kind') == 'effect'
        and catch.get('mode') == 'mandatory'
        and catch.get('timing') == 'dodge'
        and catch.get('active_zones') == ['battle']
        and catch.get('trigger') == {'event': 'dodge'}
        and not catch.get('condition')
        and catch.get('effects') == catch_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-023', False,
                reason='8~9속도 회피 제한과 패의 차지 효과 기술 캐치 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-023 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    dodge_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-speed-eight-lower-bound-dodges',
            'owner': 'p1', 'opponent_speed': 8,
            'expected_allowed': True, 'expected_result': 'dodge',
            'expected_damage': 0,
        },
        {
            'name': 'owner-p2-speed-nine-upper-bound-dodges',
            'owner': 'p2', 'opponent_speed': 9,
            'expected_allowed': True, 'expected_result': 'dodge',
            'expected_damage': 0,
        },
        {
            'name': 'speed-seven-is-below-range',
            'owner': 'p1', 'opponent_speed': 7,
            'expected_allowed': False, 'expected_result': 'failed_defense',
            'expected_damage': 400,
        },
        {
            'name': 'speed-ten-is-above-range',
            'owner': 'p2', 'opponent_speed': 10,
            'expected_allowed': False, 'expected_result': 'failed_defense',
            'expected_damage': 400,
        },
    ):
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'expected_allowed', 'expected_result',
                'expected_damage',
            }
        }
        first = _run_awl_at_023_dodge_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_awl_at_023_dodge_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        dodge_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['allowed'] is spec['expected_allowed']
                and first['stage'] == 'after_judgment'
                and first['result'].get(spec['owner'])
                == spec['expected_result']
                and first['hp_loss'] == spec['expected_damage']
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    catch_scenarios = []
    for spec in (
        {
            'name': 'owner-p1-hand-charge-is-selected-and-catches',
            'owner': 'p1', 'select': 'ordinary',
            'expect_grant': True, 'expect_ordinary': True,
            'expected_damage': 500,
        },
        {
            'name': 'owner-p2-hand-charge-is-selected-and-catches',
            'owner': 'p2', 'select': 'ordinary',
            'expect_grant': True, 'expect_ordinary': True,
            'expected_damage': 500,
        },
        {
            'name': 'wrong-trigger-does-not-grant-catch',
            'owner': 'p1', 'event_type': 'hit',
            'expect_grant': False, 'expect_ordinary': False,
            'expected_damage': 0,
        },
        {
            'name': 'numbered-negation-does-not-grant-catch',
            'owner': 'p2', 'numbered_effects_negated': True,
            'expect_grant': False, 'expect_ordinary': False,
            'expected_damage': 0,
        },
        {
            'name': 'source-outside-battle-does-not-grant-catch',
            'owner': 'p1', 'source_zone': 'hand',
            'expect_grant': False, 'expect_ordinary': False,
            'expected_damage': 0,
        },
        {
            'name': 'qna-667-list-charge-is-not-a-catch-candidate',
            'owner': 'p2', 'include_ordinary': False,
            'include_mention': False, 'include_list_charge': True,
            'expect_grant': True, 'expect_ordinary': False,
            'expected_legal': [], 'expected_damage': 0,
        },
        {
            'name': 'charge-mention-without-effect-prefix-is-excluded',
            'owner': 'p1', 'include_ordinary': False,
            'include_mention': True, 'include_list_charge': False,
            'expect_grant': True, 'expect_ordinary': False,
            'expected_legal': [], 'expected_damage': 0,
        },
        {
            'name': 'qna-586-stormbringer-without-use-condition-is-excluded',
            'owner': 'p2', 'include_ordinary': False,
            'include_storm': True, 'include_mention': False,
            'include_list_charge': False,
            'expect_grant': True, 'expect_ordinary': False,
            'expected_legal': [], 'expected_damage': 0,
        },
        {
            'name': 'qna-586-face-up-all-in-charge-enables-stormbringer-catch',
            'owner': 'p1', 'include_ordinary': False,
            'include_storm': True, 'all_in': 'face_up',
            'include_mention': False, 'include_list_charge': False,
            'select': 'storm', 'expect_grant': True,
            'expect_ordinary': False, 'expect_storm': True,
            'expected_damage': 600,
        },
        {
            'name': 'face-down-all-in-charge-does-not-enable-stormbringer',
            'owner': 'p2', 'include_ordinary': False,
            'include_storm': True, 'all_in': 'face_down',
            'include_mention': False, 'include_list_charge': False,
            'expect_grant': True, 'expect_ordinary': False,
            'expected_legal': [], 'expected_damage': 0,
        },
    ):
        expected_keys = {
            'name', 'expect_grant', 'expect_ordinary', 'expect_storm',
            'expected_legal', 'expected_damage',
        }
        kwargs = {
            key: value for key, value in spec.items()
            if key not in expected_keys
        }
        first = _run_awl_at_023_catch_scenario(
            definition, card_snapshot, **kwargs,
        )
        second = _run_awl_at_023_catch_scenario(
            definition, card_snapshot, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_grants = 1 if spec['expect_grant'] else 0
        expected_legal = spec.get('expected_legal')
        legal_ok = (
            first['legal_ids'] == expected_legal
            if expected_legal is not None else True
        )
        ordinary_ok = (
            first['ordinary_id'] in first['legal_ids']
        ) is spec['expect_ordinary']
        storm_ok = (
            first['storm_id'] in first['legal_ids']
        ) is spec.get('expect_storm', False)
        distractors_excluded = all(
            card_id not in first['legal_ids']
            for card_id in (
                first['plain_id'], first['mention_id'],
                first['list_id'], first['special_id'],
            )
        )
        selected_ok = True
        if spec.get('select'):
            selected_ok = bool(
                first['selected_id'] in first['legal_ids']
                and first['selected_zone'] == 'battle'
            )
        catch_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['grant_count'] == expected_grants
                and first['resolved'] is spec['expect_grant']
                and (
                    not spec['expect_grant']
                    or (
                        first['grant_zones'] == ['hand']
                        and first['grant_where'] == {
                            'text_effect_prefix': '[[state:charge]]',
                        }
                    )
                )
                and legal_ok and ordinary_ok and storm_ok
                and distractors_excluded and selected_ok
                and first['damage'] == spec['expected_damage']
                and first['catch_damage_events'] == (
                    [spec['expected_damage']]
                    if spec['expected_damage'] else []
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            function['id'], all(item['passed'] for item in dodge_scenarios),
            dodge_scenarios,
            '' if all(item['passed'] for item in dodge_scenarios)
            else '8~9속도 회피 경계 검증에 실패했습니다.',
        ),
        AbilityReview(
            catch['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
            '' if all(item['passed'] for item in catch_scenarios)
            else '차지 효과 접두어·패 영역·사용 조건 캐치 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '도미네이트의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_at_025_source(card_snapshot, owner, *, negated=False):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-mountain-sense', 'owner': owner,
        'code': 'AWL-AT-025', 'name': '마운틴 센스',
        'type': '공격', 'frame': 9, 'damage': 600,
        'pos': '중단', 'body': '손', 'special': None,
        'hit': '4', 'guard': '-6', 'counter': '4', 'face_up': False,
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _run_awl_at_025_combo_scenario(
    definition, card_snapshot, owner, *, negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_025_source(card_snapshot, owner, negated=negated)
    previous = _card(
        'REVIEW-MOUNTAIN-PREVIOUS', owner,
        f'{owner}-mountain-previous',
    )
    previous.update({
        'name': '마운틴 센스 이전 기술', 'type': '공격',
        'frame': 8, 'damage': 400, 'pos': '하단', 'face_up': True,
    })
    opposing = _card(
        'REVIEW-MOUNTAIN-OPPONENT', other,
        f'{other}-mountain-opponent',
    )
    state = _state(previous, opposing, owner)
    state['players'][owner]['zones']['hand'].append(copy.deepcopy(source))
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                previous['code']: {
                    **copy.deepcopy(previous),
                    'effect_definition': copy.deepcopy(no_effect),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': copy.deepcopy(no_effect),
                },
            },
        },
        seed=f'mountain-combo:{owner}:{negated}',
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    engine.grant_combo(
        owner, source=previous['instance_id'], trigger_event=False,
    )
    combo = engine.engine_state.get('combo') or {}
    combo['last_speed'] = 8
    live_source = engine._find_card(source['instance_id'])
    engine._refresh_continuous_rules()
    return {
        'combo_legal': engine._combo_card_legal(
            owner, live_source, combo, selected_speed=9,
        ),
        'combo_rule_blocked': engine._rule_blocked(
            'combo', owner, live_source,
        ),
        'ready_allowed': engine._card_use_allowed(
            live_source, owner, 'ready', ignore_cost=True,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_025_catch_scenario(
    definition, card_snapshot, owner, *, history='lower_attack',
    history_turn=None, down_stance=False, negated=False,
    max_speed=9, selection='optional',
    clear_history_after_declaration=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_025_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-MOUNTAIN-CATCH-OPPONENT', other,
        f'{other}-mountain-catch-opponent',
    )
    state = _state(source, opposing, owner, source_zone='hand')
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = 0
    if down_stance:
        state['players'][owner]['passive_state']['down_stance'] = {
            'value': True, 'label': 'down_stance', 'trait_origin': False,
        }
    prior = None
    if history != 'none':
        prior = _card(
            'REVIEW-MOUNTAIN-HISTORY', owner,
            f'{owner}-mountain-history',
        )
        prior.update({
            'name': '이번 턴 사용 기술',
            'type': '수비' if history == 'lower_defense' else '공격',
            'frame': None if history == 'lower_defense' else 7,
            'damage': None if history == 'lower_defense' else 400,
            'pos': '상단' if history == 'upper_attack' else '하단',
            'face_up': True,
        })
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': copy.deepcopy(no_effect),
        },
    }
    if prior:
        cards[prior['code']] = {
            **copy.deepcopy(prior),
            'effect_definition': copy.deepcopy(no_effect),
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'mountain-catch:{owner}:{history}:{history_turn}:'
            f'{down_stance}:{negated}:{max_speed}:{selection}:'
            f'{clear_history_after_declaration}'
        ),
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    if prior:
        engine.engine_state['card_use_history'] = [{
            'turn': (
                int(history_turn) if history_turn is not None
                else int(engine.state.get('turn') or 1)
            ),
            'player': owner, 'use_context': 'ready',
            'instance_id': prior['instance_id'], 'card': copy.deepcopy(prior),
        }]
    catch = {
        'owner': owner, 'source': 'review-catch',
        'allow_zones': ['hand'], 'max_speed': max_speed,
    }
    options = [
        option for option in engine._legal_catch_options(owner, catch)
        if (option.get('card') or {}).get('instance_id')
        == source['instance_id']
    ]
    variants = sorted([
        {
            'rule_index': option.get('catch_rule_index'),
            'fixed_speed': option.get('fixed_speed'),
        }
        for option in options
    ], key=lambda item: (
        item.get('rule_index') is not None,
        int(item.get('fixed_speed') or 0),
    ))
    desired_rule = None if selection == 'printed' else 0
    selected = next((
        option for option in options
        if option.get('catch_rule_index') == desired_rule
    ), None)
    hp_before = int(engine.state['players'][other]['hp'])
    selected_fixed_speed = None
    declared_speed = None
    if selected:
        engine.engine_state.update({
            'catch': copy.deepcopy(catch), 'catch_queue': [],
            'granted_catches': [], 'catch_fp_history': [], 'step': 'catch',
        })
        engine._play_catch(
            owner, source['instance_id'],
            catch_rule_index=selected.get('catch_rule_index'),
        )
        selected_fixed_speed = (
            engine.engine_state.get('pipeline') or {}
        ).get('fixed_speed')
        declared_speed = engine.card_stat(
            engine._find_card(source['instance_id']), 'frame', owner,
            include_fp=False,
        )
        if clear_history_after_declaration:
            engine.engine_state['card_use_history'] = []
        engine._continue()
    live_source = engine._find_card(source['instance_id']) or source
    return {
        'variants': variants, 'played': bool(selected),
        'selected_fixed_speed': selected_fixed_speed,
        'effective_speed': (
            declared_speed
            if selected else None
        ),
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'source_damage': (
            hp_before - int(engine.state['players'][other]['hp'])
            if selected else engine.card_stat(live_source, 'damage', owner)
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-025-n1'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_025_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-025':
        return None
    qna_ids = [152, 155]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-025-function')
    catch = by_id.get('awl-at-025-n1')
    used_lower_attack = {
        'op': 'used_card', 'player': {'controller': True},
        'where': {'pos': '하단', 'type_contains': '공격'}, 'min': 1,
    }
    catch_selection = {
        'op': 'all', 'conditions': [
            {
                'op': 'equals',
                'left': 'context.catch_rule_index', 'right': 0,
            },
            {
                'op': 'equals',
                'left': 'context.fixed_speed', 'right': 3,
            },
        ],
    }
    valid = bool(
        extra_root == {'catch_rules', 'play_condition'}
        and set(by_id) == {'awl-at-025-function', 'awl-at-025-n1'}
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and definition.get('play_condition') == {
            'op': 'not_equals', 'left': 'context.use_context',
            'right': 'combo',
        }
        and definition.get('catch_rules') == [{
            'optional_fixed_speed': 3,
            'condition': used_lower_attack,
            'numbered_effect': True,
        }]
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and not function.get('trigger') and not function.get('active_zones')
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'combo',
            'player': {'controller': True}, 'duration': 'continuous',
        }]
        and catch and catch.get('kind') == 'effect'
        and catch.get('mode') == 'mandatory'
        and catch.get('timing') == 'catch'
        and catch.get('active_zones') == ['battle']
        and catch.get('trigger') == {'event': 'catch'}
        and catch.get('condition') == catch_selection
        and catch.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': -500, 'duration': 'battle',
        }]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'AWL-AT-025', 'name': '마운틴 센스',
            'type': '공격', 'frame': 9, 'damage': 600,
            'pos': '중단', 'body': '손', 'special': None,
            'hit': '4', 'guard': '-6', 'counter': '4',
            'character_id': 4,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-025', False,
                reason='마운틴 센스의 콤보 금지·하단 공격 이력·선택 3속도 캐치 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-025 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    function_scenarios = _st2_scenarios(
        _run_awl_at_025_combo_scenario, definition, card_snapshot,
        (
            ('owner-p1-cannot-use-in-combo', 'p1', {}, {
                'combo_legal': False, 'combo_rule_blocked': True,
                'ready_allowed': True, 'pending': False}),
            ('owner-p2-cannot-use-in-combo', 'p2', {}, {
                'combo_legal': False, 'combo_rule_blocked': True,
                'ready_allowed': True, 'pending': False}),
            ('numbered-negation-keeps-numberless-prohibition', 'p1', {
                'negated': True,
            }, {'combo_legal': False, 'combo_rule_blocked': True,
                'ready_allowed': True}),
        ),
    )
    catch_scenarios = _st2_scenarios(
        _run_awl_at_025_catch_scenario, definition, card_snapshot,
        (
            ('owner-p1-lower-attack-enables-speed-three', 'p1', {}, {
                'played': True, 'selected_fixed_speed': 3,
                'effective_speed': 3, 'damage': 100,
                'source_damage': 100, 'resolved': 1, 'pending': False}),
            ('owner-p2-lower-attack-enables-speed-three', 'p2', {}, {
                'played': True, 'selected_fixed_speed': 3,
                'damage': 100, 'resolved': 1}),
            ('printed-speed-nine-keeps-printed-damage', 'p1', {
                'selection': 'printed',
            }, {'played': True, 'selected_fixed_speed': None,
                'effective_speed': 9, 'damage': 600,
                'source_damage': 600, 'resolved': 0}),
            ('qna-155-lower-defense-does-not-enable-option', 'p2', {
                'history': 'lower_defense', 'max_speed': 3,
            }, {'played': False, 'variants': [], 'resolved': 0}),
            ('upper-attack-does-not-enable-option', 'p1', {
                'history': 'upper_attack', 'max_speed': 3,
            }, {'played': False, 'variants': [], 'resolved': 0}),
            ('prior-turn-lower-attack-does-not-enable-option', 'p2', {
                'history_turn': 0, 'max_speed': 3,
            }, {'played': False, 'variants': [], 'resolved': 0}),
            ('qna-152-down-stance-does-not-disable-option', 'p1', {
                'down_stance': True, 'max_speed': 3,
            }, {'played': True, 'selected_fixed_speed': 3,
                'damage': 100, 'resolved': 1}),
            ('numbered-negation-removes-speed-three-option', 'p2', {
                'negated': True, 'max_speed': 3,
            }, {'played': False, 'variants': [], 'resolved': 0}),
            ('declaration-locks-selected-catch-branch', 'p1', {
                'max_speed': 3, 'clear_history_after_declaration': True,
            }, {'played': True, 'selected_fixed_speed': 3,
                'damage': 100, 'resolved': 1}),
            ('speed-two-window-has-no-legal-variant', 'p2', {
                'max_speed': 2,
            }, {'played': False, 'variants': [], 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            function['id'],
            all(item['passed'] for item in function_scenarios),
            function_scenarios,
        ),
        AbilityReview(
            catch['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '마운틴 센스 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_at_026_source(card_snapshot, owner, *, negated=False):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-panning-stun', 'owner': owner,
        'code': 'AWL-AT-026', 'name': '패닝 스턴',
        'type': '공격', 'frame': 8, 'damage': 500,
        'pos': '상단', 'body': '', 'special': '',
        'hit': '3', 'guard': '-4', 'counter': '6', 'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _awl_at_026_engine(
    definition, card_snapshot, owner, *, source_zone='battle', hand_count=2,
    protected_index=None, down_stance=False, negated=False,
    opponent_speed=7, opponent_position='상단', opponent_conversion=False,
    priority='source',
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_026_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-PANNING-OPPONENT', other, f'{other}-panning-opponent',
    )
    opposing.update({
        'name': '상대 공격 기술', 'type': '공격',
        'frame': opponent_speed, 'damage': 400,
        'pos': opponent_position, 'special': '', 'face_up': True,
    })
    hand = []
    for index in range(hand_count):
        card = _card(
            f'REVIEW-PANNING-HAND-{index + 1}', owner,
            f'{owner}-panning-hand-{index + 1}',
        )
        card.update({'name': f'버릴 패 {index + 1}', 'face_up': False})
        hand.append(card)
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = 'battle'
    state['priority_player'] = owner if priority == 'source' else other
    state['players'][owner]['zones']['hand'].extend(copy.deepcopy(hand))
    if down_stance:
        state['players'][owner]['passive_state']['down_stance'] = {
            'value': True, 'label': 'down_stance', 'trait_origin': False,
        }
    no_effect = _st1_001_no_effect_definition()
    opposing_definition = copy.deepcopy(no_effect)
    if opponent_conversion:
        opposing_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [], 'qna_ids': [348]},
            'abilities': [{
                'id': 'review-awl-at-010-convert',
                'label': '상대 특수 판정을 상단 상쇄로 변경',
                'kind': 'effect', 'mode': 'mandatory',
                'timing': 'before_judgment', 'visibility': 'public',
                'source_refs': {'rulebook_pages': [], 'qna_ids': [348]},
                'active_zones': ['battle'],
                'trigger': {'event': 'before_judgment'},
                'condition': {
                    'op': 'card_matches',
                    'card': {'path': 'context.opponent_card'},
                    'where': {'special_truthy': True},
                },
                'effects': [{
                    'op': 'modify_judgment',
                    'player': {'opponent': True},
                    'field': 'special', 'value': '상단 상쇄',
                    'mode': 'replace',
                }],
            }],
        }
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': definition,
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': opposing_definition,
        },
    }
    for index, card in enumerate(hand):
        hand_definition = copy.deepcopy(no_effect)
        if protected_index == index:
            hand_definition['effect_immunity'] = {
                'scope': 'other_cards', 'operations': ['move_card'],
            }
        cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': hand_definition,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'panning:{owner}:{source_zone}:{hand_count}:{protected_index}:'
            f'{down_stance}:{negated}:{opponent_speed}:{opponent_position}:'
            f'{opponent_conversion}:{priority}'
        ),
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    if source_zone == 'battle':
        engine.engine_state['battle'] = {
            owner: {
                'instance_id': source['instance_id'],
                'card': engine._find_card(source['instance_id']),
            },
            other: {
                'instance_id': opposing['instance_id'],
                'card': engine._find_card(opposing['instance_id']),
            },
        }
    return engine, source, opposing, hand


def _run_awl_at_026_clash_lock_scenario(
    definition, card_snapshot, owner, *, source_zone='battle', negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing, _hand = _awl_at_026_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, hand_count=0, negated=negated,
    )
    engine._refresh_continuous_rules()
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    return {
        'opponent_clash_blocked': engine._rule_blocked(
            'clash', other, live_opposing, live_source,
        ),
        'owner_clash_blocked': engine._rule_blocked(
            'clash', owner, live_source, live_opposing,
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_026_discard_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    event_type='hit', hand_count=2, selected_index=0, accept=True,
    protected_index=None, protect_after_choice=False, negated=False,
):
    engine, source, opposing, hand = _awl_at_026_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, hand_count=hand_count,
        protected_index=protected_index, negated=negated,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_battle_card_only': True,
    })
    activation = copy.deepcopy(engine.engine_state.get('pending_decision'))
    choice = None
    selected_id = None
    if activation and activation.get('kind') == 'optional_effect':
        engine._submit_decision(
            owner, activation['id'], ['accept' if accept else 'decline'],
        )
        choice = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if accept and choice and choice.get('kind') == 'effect_choice':
            option_ids = {
                str(item.get('id')) for item in choice.get('options') or []
            }
            if (
                0 <= selected_index < len(hand)
                and hand[selected_index]['instance_id'] in option_ids
            ):
                selected_id = hand[selected_index]['instance_id']
                if protect_after_choice:
                    selected = engine._find_card(selected_id)
                    engine.ruleset['cards'][selected['code']][
                        'effect_definition'
                    ] = {
                        **copy.deepcopy(_st1_001_no_effect_definition()),
                        'effect_immunity': {
                            'scope': 'other_cards',
                            'operations': ['move_card'],
                        },
                    }
                engine._submit_decision(owner, choice['id'], [selected_id])
    live_source = engine._find_card(source['instance_id'])
    battle_source = (
        (engine.engine_state.get('battle') or {}).get(owner) or {}
    ).get('card') or live_source or {}
    return {
        'activation_kind': (activation or {}).get('kind'),
        'choice_kind': (choice or {}).get('kind'),
        'choice_range': (
            ((choice or {}).get('minimum'), (choice or {}).get('maximum'))
            if choice else None
        ),
        'option_ids': [
            str(item.get('id')) for item in (choice or {}).get('options') or []
        ],
        'hand_ids': [card['instance_id'] for card in hand],
        'selected_id': selected_id,
        'hand_zones': {
            card['instance_id']: engine._find_location(card['instance_id'])[1]
            for card in hand
        },
        'source_hit': battle_source.get('hit'),
        'source_damage': engine.card_stat(battle_source, 'damage', owner),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-026-n1'
            for event in engine.events
        ),
        'discard_ignored': any(
            event.get('type') == 'card_effect_ignored'
            and (event.get('payload') or {}).get('operation') == 'move_card'
            for event in engine.events
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_026_dodge_scenario(
    definition, card_snapshot, owner, *, down_stance=True,
    opponent_speed=7, opponent_position='상단', negated=False,
    source_zone='battle', opponent_conversion=False, priority='source',
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing, _hand = _awl_at_026_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, hand_count=0,
        down_stance=down_stance, negated=negated,
        opponent_speed=opponent_speed, opponent_position=opponent_position,
        opponent_conversion=opponent_conversion, priority=priority,
    )
    if source_zone == 'battle':
        engine._battle_trigger('before_judgment')
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
    battle = engine.engine_state.get('battle') or {}
    source_live = (battle.get(owner) or {}).get('card') or {}
    resolved_order = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') in {
            'awl-at-026-n2', 'review-awl-at-010-convert',
        }
    ]
    return {
        'source_special': source_live.get('special', ''),
        'result': copy.deepcopy((battle.get('result') or {}).get(owner)),
        'opponent_result': copy.deepcopy(
            (battle.get('result') or {}).get(other)
        ),
        'resolved_order': resolved_order,
        'source_resolved': 'awl-at-026-n2' in resolved_order,
        'conversion_resolved': 'review-awl-at-010-convert' in resolved_order,
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_026_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-026':
        return None
    qna_ids = [242, 348]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-026-function')
    discard = by_id.get('awl-at-026-n1')
    dodge = by_id.get('awl-at-026-n2')
    down_stance = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'down_stance',
    }
    defense_rules = [{
        'judgment': 'dodge', 'position': '상단', 'max_speed': 7,
        'condition': down_stance, 'numbered_effect': True,
    }]
    selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['hand'], 'min': 1, 'max': 1,
        'as_operation': 'discard',
    }
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 3
        and function and discard and dodge
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and definition.get('defense_rules') == defense_rules
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('active_zones') == ['battle']
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'clash',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and discard.get('kind') == 'effect'
        and discard.get('mode') == 'optional'
        and discard.get('active_zones') == ['battle']
        and discard.get('trigger') == {'event': 'hit'}
        and discard.get('availability_selector') == selector
        and (discard.get('effects') or [{}])[0].get('selector') == selector
        and (discard.get('effects') or [{}])[0].get(
            'then', [{}]
        )[0].get('result_key') == 'awl_at_026_discarded'
        and (discard.get('effects') or [{}])[0].get(
            'then', [{}, {}]
        )[1].get('op') == 'conditional'
        and dodge.get('kind') == 'effect'
        and dodge.get('mode') == 'mandatory'
        and dodge.get('active_zones') == ['battle']
        and dodge.get('trigger') == {'event': 'before_judgment'}
        and dodge.get('condition') == down_stance
        and dodge.get('effects') == [{
            'op': 'modify_judgment',
            'player': {'controller': True},
            'field': 'special', 'value': '상단 회피', 'mode': 'append',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-026', False,
                reason='패닝 스턴의 상쇄 금지·선택 버림·다운 스탠스 회피 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-026 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    reviews = []
    lock_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-battle-blocks-opponent-clash', 'p1', {}, True),
        ('owner-p2-battle-blocks-opponent-clash', 'p2', {}, True),
        ('source-outside-battle-does-not-block', 'p1', {
            'source_zone': 'hand',
        }, False),
        ('numbered-negation-does-not-remove-numberless-lock', 'p2', {
            'negated': True,
        }, True),
    ):
        first = _run_awl_at_026_clash_lock_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_026_clash_lock_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        lock_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['opponent_clash_blocked'] is expected
                and not first['owner_clash_blocked'] and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        function['id'], all(item['passed'] for item in lock_scenarios),
        lock_scenarios,
        '' if all(item['passed'] for item in lock_scenarios)
        else '패닝 스턴의 상대 한정 상쇄 금지 검증에 실패했습니다.',
    ))

    discard_scenarios = []
    for name, owner, kwargs, offered, discarded, hit, damage in (
        ('owner-p1-selects-first-hand-card', 'p1', {}, True, 1, '+5', 600),
        ('owner-p2-selects-second-hand-card', 'p2', {
            'selected_index': 1,
        }, True, 1, '+5', 600),
        ('decline-keeps-hand-and-printed-values', 'p1', {
            'accept': False,
        }, True, 0, '3', 500),
        ('no-hand-card-is-not-offered', 'p2', {
            'hand_count': 0,
        }, False, 0, '3', 500),
        ('wrong-event-is-not-offered', 'p1', {
            'event_type': 'counter',
        }, False, 0, '3', 500),
        ('protected-card-is-excluded-and-second-selected', 'p2', {
            'protected_index': 0, 'selected_index': 1,
        }, True, 1, '+5', 600),
        ('protection-after-choice-stops-followups', 'p1', {
            'hand_count': 1, 'protect_after_choice': True,
        }, True, 0, '3', 500),
        ('numbered-negation-is-not-offered', 'p2', {
            'negated': True,
        }, False, 0, '3', 500),
        ('source-outside-battle-is-not-offered', 'p1', {
            'source_zone': 'hand',
        }, False, 0, '3', 500),
    ):
        first = _run_awl_at_026_discard_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_026_discard_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        discarded_count = sum(
            zone == 'list' for zone in first['hand_zones'].values()
        )
        protected_id = (
            first['hand_ids'][kwargs['protected_index']]
            if kwargs.get('protected_index') is not None else None
        )
        accepted = offered and kwargs.get('accept', True)
        discard_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and (first['activation_kind'] == 'optional_effect') is offered
                and (first['choice_kind'] == 'effect_choice') is accepted
                and discarded_count == discarded
                and first['source_hit'] == hit
                and first['source_damage'] == damage
                and first['resolved'] is accepted
                and (
                    protected_id not in first['option_ids']
                    if protected_id else True
                )
                and first['discard_ignored'] is bool(
                    kwargs.get('protect_after_choice')
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        discard['id'], all(item['passed'] for item in discard_scenarios),
        discard_scenarios,
        '' if all(item['passed'] for item in discard_scenarios) else (
            '패닝 스턴 ①의 실제 패 선택·Q&A 242 리스트 이동·성공 연동 검증에 실패했습니다.'
        ),
    ))

    dodge_scenarios = []
    for name, owner, kwargs, special, result, resolved, converted in (
        ('owner-p1-down-stance-speed-seven-dodges', 'p1', {}, '상단 회피', 'counter', True, False),
        ('owner-p2-down-stance-speed-six-dodges', 'p2', {
            'opponent_speed': 6,
        }, '상단 회피', 'counter', True, False),
        ('speed-eight-exceeds-dodge-limit', 'p1', {
            'opponent_speed': 8,
        }, '상단 회피', 'hit', True, False),
        ('middle-position-is-not-dodged', 'p2', {
            'opponent_position': '중단',
        }, '상단 회피', 'countered', True, False),
        ('without-down-stance-does-not-add-special', 'p1', {
            'down_stance': False,
        }, '', 'countered', False, False),
        ('numbered-negation-does-not-add-special', 'p2', {
            'negated': True,
        }, '', 'countered', False, False),
        ('source-outside-battle-does-not-trigger', 'p1', {
            'source_zone': 'hand',
        }, '', None, False, False),
        ('qna-348-panning-priority-creates-then-converts', 'p2', {
            'opponent_conversion': True, 'priority': 'source',
        }, '상단 상쇄', 'clash', True, True),
        ('qna-348-opponent-priority-misses-before-dodge-exists', 'p1', {
            'opponent_conversion': True, 'priority': 'opponent',
        }, '상단 회피', 'counter', True, False),
    ):
        first = _run_awl_at_026_dodge_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_026_dodge_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        dodge_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['source_special'] == special
                and first['result'] == result
                and first['source_resolved'] is resolved
                and first['conversion_resolved'] is converted
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        dodge['id'], all(item['passed'] for item in dodge_scenarios),
        dodge_scenarios,
        '' if all(item['passed'] for item in dodge_scenarios) else (
            '패닝 스턴 ②의 다운 스탠스·7속도 경계·Q&A 348 우선권 검증에 실패했습니다.'
        ),
    ))
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '패닝 스턴의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_at_027_source(card_snapshot, owner, *, negated=False):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-force-parrying', 'owner': owner,
        'code': 'AWL-AT-027', 'name': '포스 패링', 'type': '수비',
        'frame': None, 'damage': None, 'pos': None, 'body': '',
        'special': '', 'hit': '', 'guard': '', 'counter': '',
        'g_top': '방어', 'g_mid': '방어', 'g_bot': '방어',
        'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _awl_at_027_engine(
    definition, card_snapshot, owner, *, source_zone='battle', negated=False,
    opponent_damage=600, qna_priority=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_027_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-FORCE-PARRYING-OPPONENT', other,
        f'{other}-force-parrying-opponent',
    )
    opposing.update({
        'name': '상대 공격 기술', 'type': '공격', 'frame': 7,
        'damage': opponent_damage, 'pos': '상단', 'special': '',
        'face_up': True,
    })
    opposing_definition = copy.deepcopy(_st1_001_no_effect_definition())
    if qna_priority:
        opposing.update({
            'code': 'AWL-AT-036', 'name': '다이스티드',
            'damage': 500,
        })
        opposing_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [576]},
            'abilities': [{
                'id': 'review-dicetied-opponent-guard-damage',
                'label': '상대 방어 시 상대에게 100데미지',
                'kind': 'effect', 'mode': 'mandatory',
                'timing': 'opponent_guard', 'visibility': 'public',
                'source_refs': {
                    'rulebook_pages': [48, 49], 'qna_ids': [576],
                },
                'active_zones': ['battle'],
                'trigger': {'event': 'opponent_guard'},
                'effects': [{
                    'op': 'deal_damage', 'player': {'opponent': True},
                    'amount': 100,
                }],
            }],
        }
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = 'battle'
    if qna_priority:
        state['players'][owner]['hp'] = 100
        state['players'][other]['hp'] = 500
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': opposing_definition,
                },
            },
        },
        seed=(
            f'force-parrying:{owner}:{source_zone}:{negated}:'
            f'{opponent_damage}:{qna_priority}'
        ),
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    if source_zone == 'battle':
        engine.engine_state['battle'] = {
            owner: {
                'instance_id': source['instance_id'],
                'card': engine._find_card(source['instance_id']),
            },
            other: {
                'instance_id': opposing['instance_id'],
                'card': engine._find_card(opposing['instance_id']),
            },
        }
    return engine, source, opposing


def _run_awl_at_027_guard_scenario(
    definition, card_snapshot, owner, *, event_type='guard',
    source_zone='battle', negated=False, opponent_damage=600,
    qna_priority=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _awl_at_027_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, negated=negated,
        opponent_damage=opponent_damage, qna_priority=qna_priority,
    )
    hp_before = int(engine.state['players'][other]['hp'])
    trigger_order = []
    if qna_priority:
        sequence = engine._result_trigger_sequence({
            owner: 'guard', other: 'guarded',
        })
        trigger_order = [item[0] for item in sequence]
        for queued_event, context in sequence:
            if engine.engine_state.get('status') != 'running':
                break
            engine._fire(queued_event, context)
            engine._continue()
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': engine._find_card(source['instance_id']),
            'opponent_card': engine._find_card(opposing['instance_id']),
            'source_only_event': True,
        })
        engine._continue()
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-027-n1'
            for event in engine.events
        ),
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'winner': engine.engine_state.get('winner'),
        'trigger_order': trigger_order,
        'dicetied_resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'review-dicetied-opponent-guard-damage'
            for event in engine.events
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_027_after_use_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    source_zone='battle', negated=False,
):
    engine, source, opposing = _awl_at_027_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, negated=negated,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True,
    })
    engine._continue()
    state_value = (
        engine.state['players'][owner].get('passive_state') or {}
    ).get('down_stance')
    return {
        'down_stance': bool(
            state_value.get('value')
            if isinstance(state_value, dict) else state_value
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-027-n2'
            for event in engine.events
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_027_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-027':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    guard_damage = by_id.get('awl-at-027-n1')
    down_stance = by_id.get('awl-at-027-n2')
    qna_ids = [576]
    valid = bool(
        not extra_root and len(abilities) == 2
        and guard_damage and down_stance
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and guard_damage.get('kind') == 'effect'
        and guard_damage.get('mode') == 'mandatory'
        and guard_damage.get('active_zones') == ['battle']
        and guard_damage.get('trigger') == {'event': 'guard'}
        and guard_damage.get('effects') == [{
            'op': 'deal_damage', 'player': {'opponent': True},
            'amount': {'path': 'context.opponent_card.damage'},
        }]
        and down_stance.get('kind') == 'effect'
        and down_stance.get('mode') == 'mandatory'
        and down_stance.get('active_zones') == ['battle']
        and down_stance.get('trigger') == {'event': 'after_use'}
        and down_stance.get('effects') == [{
            'op': 'gain_state', 'player': {'controller': True},
            'state': 'down_stance',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-027', False,
                reason='포스 패링의 방어 데미지·사용 후 다운 스탠스 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-027 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    guard_scenarios = []
    for name, owner, kwargs, expected, damage, winner in (
        ('owner-p1-guard-reflects-opponent-damage', 'p1', {}, True, 600, None),
        ('owner-p2-guard-uses-current-opponent-damage', 'p2', {
            'opponent_damage': 750,
        }, True, 750, None),
        ('wrong-opponent-guard-event-does-not-trigger', 'p1', {
            'event_type': 'opponent_guard',
        }, False, 0, None),
        ('numbered-negation-does-not-deal-damage', 'p2', {
            'negated': True,
        }, False, 0, None),
        ('source-outside-battle-does-not-trigger', 'p1', {
            'source_zone': 'hand',
        }, False, 0, None),
        ('qna-576-guard-resolves-before-opponent-guard', 'p2', {
            'qna_priority': True,
        }, True, 500, 'p2'),
    ):
        first = _run_awl_at_027_guard_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_027_guard_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        qna_ok = True
        if kwargs.get('qna_priority'):
            qna_ok = bool(
                first['trigger_order'][:2] == ['guard', 'opponent_guard']
                and not first['dicetied_resolved']
            )
        guard_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is expected
                and first['damage'] == damage and first['winner'] == winner
                and qna_ok and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    guard_review = AbilityReview(
        guard_damage['id'], all(item['passed'] for item in guard_scenarios),
        guard_scenarios,
        '' if all(item['passed'] for item in guard_scenarios)
        else '방어 데미지와 Q&A 576의 타이밍 우선순위 검증에 실패했습니다.',
    )

    stance_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-after-use-gains-down-stance', 'p1', {}, True),
        ('owner-p2-after-use-gains-down-stance', 'p2', {}, True),
        ('wrong-use-event-does-not-gain-state', 'p1', {
            'event_type': 'use',
        }, False),
        ('numbered-negation-does-not-gain-state', 'p2', {
            'negated': True,
        }, False),
        ('source-outside-battle-does-not-gain-state', 'p1', {
            'source_zone': 'hand',
        }, False),
    ):
        first = _run_awl_at_027_after_use_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_027_after_use_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        stance_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['down_stance'] is expected
                and first['resolved'] is expected and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    stance_review = AbilityReview(
        down_stance['id'], all(item['passed'] for item in stance_scenarios),
        stance_scenarios,
        '' if all(item['passed'] for item in stance_scenarios)
        else '사용 후 다운 스탠스 획득 검증에 실패했습니다.',
    )
    reviews = [guard_review, stance_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '포스 패링의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_at_030_source(card_snapshot, owner, *, negated=False):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-near-cutting', 'owner': owner,
        'code': 'AWL-AT-030', 'name': '니어 커팅', 'type': '공격',
        'frame': 8, 'damage': 400, 'pos': '하단', 'body': '',
        'special': '', 'hit': '4', 'guard': '-8', 'counter': '4',
        'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _awl_at_030_engine(
    definition, card_snapshot, owner, *, source_zone='battle',
    negated=False, hand_count=3, protected_indexes=(),
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_030_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-NEAR-CUTTING-OPPONENT', other,
        f'{other}-near-cutting-opponent',
    )
    opposing.update({
        'name': '상대 기술', 'type': '공격', 'frame': 6,
        'damage': 500, 'pos': '하단', 'face_up': True,
    })
    hand = []
    for index in range(hand_count):
        card = _card(
            f'REVIEW-NEAR-CUTTING-HAND-{index + 1}', other,
            f'{other}-near-cutting-hand-{index + 1}',
        )
        card.update({'name': f'상대 패 {index + 1}', 'face_up': False})
        hand.append(card)
    spare = _card(
        'REVIEW-NEAR-CUTTING-SPARE', owner,
        f'{owner}-near-cutting-spare',
    )
    spare.update({'name': '별도 브레이크 기술', 'face_up': True})
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = 'battle'
    state['players'][other]['zones']['hand'].extend(copy.deepcopy(hand))
    state['players'][owner]['zones']['list'].append(copy.deepcopy(spare))
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': copy.deepcopy(no_effect),
        },
        spare['code']: {
            **copy.deepcopy(spare),
            'effect_definition': copy.deepcopy(no_effect),
        },
    }
    for index, card in enumerate(hand):
        hand_definition = copy.deepcopy(no_effect)
        if index in set(protected_indexes):
            hand_definition['effect_immunity'] = {
                'scope': 'other_cards', 'operations': ['move_card'],
            }
        cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': hand_definition,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'near-cutting:{owner}:{source_zone}:{negated}:'
            f'{hand_count}:{tuple(protected_indexes)}'
        ),
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    return engine, source, opposing, hand, spare


def _run_awl_at_030_discard_scenario(
    definition, card_snapshot, owner, *, event_type='hit',
    use_context='ready', source_zone='battle', negated=False,
    hand_count=3, protected_indexes=(),
):
    engine, source, opposing, hand, _spare = _awl_at_030_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, negated=negated,
        hand_count=hand_count, protected_indexes=protected_indexes,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True, 'use_context': use_context,
    })
    engine._continue()
    zones = {
        card['instance_id']: engine._find_location(card['instance_id'])[1]
        for card in hand
    }
    random_events = [
        event for event in engine.events
        if event.get('type') == 'random_resolved'
    ]
    selected = list(
        ((random_events[-1].get('payload') or {}).get('selected') or [])
        if random_events else []
    )
    return {
        'hand_ids': [card['instance_id'] for card in hand],
        'zones': zones,
        'selected': selected,
        'discarded': sorted(
            instance_id for instance_id, zone in zones.items()
            if zone == 'list'
        ),
        'random_count': len(random_events),
        'random_visibility': (
            random_events[-1].get('visibility') if random_events else None
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-030-n1'
            for event in engine.events
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_030_break_scenario(
    definition, card_snapshot, owner, *, break_source=True,
    negated=False, event_type='card_broken',
):
    engine, source, _opposing, _hand, spare = _awl_at_030_engine(
        definition, card_snapshot, owner,
        negated=negated, hand_count=0,
    )
    target = source if break_source else spare
    if event_type == 'card_broken':
        engine.break_card(target['instance_id'], reason='review-near-cutting')
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': target['instance_id'],
            'source_card': engine._find_card(target['instance_id']),
        })
    return {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'target_zone': engine._find_location(target['instance_id'])[1],
        'owner_skip_get': bool(
            (engine.engine_state.get('skip_get') or {}).get(owner)
        ),
        'opponent_skip_get': bool(
            (engine.engine_state.get('skip_get') or {}).get(
                'p2' if owner == 'p1' else 'p1'
            )
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-030-n2'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_030_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-030':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    random_discard = by_id.get('awl-at-030-n1')
    skip_get = by_id.get('awl-at-030-n2')
    qna_ids = [242, 394]
    selection_key = 'awl_at_030_random_discard'
    selector = {
        'kind': 'card', 'player': {'opponent': True},
        'zones': ['hand'], 'min': 0, 'max': 1,
        'as_operation': 'discard',
    }
    discard_effects = [
        {
            'op': 'random_select', 'selector': selector, 'count': 1,
            'selection_key': selection_key, 'visibility': 'private',
        },
        {
            'op': 'discard', 'selection_key': selection_key,
            'result_key': 'awl_at_030_discarded',
        },
    ]
    skip_effects = [
        {'op': 'skip_get', 'player': {'controller': True}},
        {'op': 'skip_get', 'player': {'opponent': True}},
    ]
    valid = bool(
        not extra_root and len(abilities) == 2
        and random_discard and skip_get
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and random_discard.get('kind') == 'effect'
        and random_discard.get('mode') == 'mandatory'
        and random_discard.get('active_zones') == ['battle']
        and random_discard.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and random_discard.get('effects') == discard_effects
        and skip_get.get('kind') == 'effect'
        and skip_get.get('mode') == 'mandatory'
        and skip_get.get('trigger') == {'event': 'card_broken'}
        and not skip_get.get('active_zones')
        and skip_get.get('effects') == skip_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-030', False,
                reason='니어 커팅의 무작위 버리기·브레이크 시 겟 스킵 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-030 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    discard_scenarios = []
    for name, owner, kwargs, expected_resolved, discarded in (
        ('owner-p1-hit-randomly-discards-one', 'p1', {}, True, 1),
        ('owner-p2-counter-randomly-discards-one', 'p2', {
            'event_type': 'counter',
        }, True, 1),
        ('qna-394-catch-hit-randomly-discards-one', 'p1', {
            'use_context': 'catch',
        }, True, 1),
        ('no-opponent-hand-resolves-without-discard', 'p2', {
            'hand_count': 0,
        }, True, 0),
        ('protected-cards-are-excluded-before-random-choice', 'p1', {
            'protected_indexes': (0, 1),
        }, True, 1),
        ('all-protected-cards-produce-no-random-target', 'p2', {
            'hand_count': 2, 'protected_indexes': (0, 1),
        }, True, 0),
        ('wrong-event-does-not-randomly-discard', 'p1', {
            'event_type': 'guard',
        }, False, 0),
        ('numbered-negation-does-not-randomly-discard', 'p2', {
            'negated': True,
        }, False, 0),
        ('source-outside-battle-does-not-trigger', 'p1', {
            'source_zone': 'hand',
        }, False, 0),
    ):
        first = _run_awl_at_030_discard_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_030_discard_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        protected_ids = {
            first['hand_ids'][index]
            for index in kwargs.get('protected_indexes', ())
            if index < len(first['hand_ids'])
        }
        discard_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is expected_resolved
                and len(first['discarded']) == discarded
                and first['selected'] == first['discarded']
                and protected_ids.isdisjoint(first['selected'])
                and first['random_count'] == (
                    1 if expected_resolved else 0
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    discard_review = AbilityReview(
        random_discard['id'],
        all(item['passed'] for item in discard_scenarios),
        discard_scenarios,
        '' if all(item['passed'] for item in discard_scenarios) else (
            '히트·카운터·캐치 히트의 보호 후보 제외 무작위 버리기 검증에 실패했습니다.'
        ),
    )

    skip_scenarios = []
    for name, owner, kwargs, source_zone, target_zone, expected in (
        ('owner-p1-source-break-skips-both-get-phases', 'p1', {}, 'break', 'break', True),
        ('owner-p2-source-break-skips-both-get-phases', 'p2', {}, 'break', 'break', True),
        ('unrelated-card-break-does-not-skip-get', 'p1', {
            'break_source': False,
        }, 'battle', 'break', False),
        ('numbered-negation-does-not-skip-get', 'p2', {
            'negated': True,
        }, 'break', 'break', False),
        ('wrong-event-does-not-skip-get', 'p1', {
            'event_type': 'card_moved',
        }, 'battle', 'battle', False),
    ):
        first = _run_awl_at_030_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_030_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        skip_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['source_zone'] == source_zone
                and first['target_zone'] == target_zone
                and first['owner_skip_get'] is expected
                and first['opponent_skip_get'] is expected
                and first['resolved'] is expected and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    skip_review = AbilityReview(
        skip_get['id'], all(item['passed'] for item in skip_scenarios),
        skip_scenarios,
        '' if all(item['passed'] for item in skip_scenarios)
        else '자기 브레이크 시 양쪽 겟 페이즈 스킵 검증에 실패했습니다.',
    )
    reviews = [discard_review, skip_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '니어 커팅의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


