def _awl_at_031_engine(
    definition, card_snapshot, owner, *, source_zone='battle',
    negated=False, advance_notice=True, owner_fp=7, opponent_fp=0,
    with_down_guard=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_031_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-BUNNY-JAM-OPPONENT', other,
        f'{other}-bunny-jam-opponent',
    )
    opposing.update({
        'name': '상대 기술', 'type': '수비' if with_down_guard else '공격',
        'frame': None if with_down_guard else 7,
        'damage': None if with_down_guard else 400,
        'g_top': '회피' if with_down_guard else '',
        'g_mid': '회피' if with_down_guard else '',
        'g_bot': '회피' if with_down_guard else '',
        'face_up': True,
    })
    opposing_definition = copy.deepcopy(_st1_001_no_effect_definition())
    if with_down_guard:
        opposing.update({'code': 'ST1-012', 'name': '다운 가드'})
        opposing_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [391]},
            'abilities': [{
                'id': 'review-down-guard-gain-three-fp',
                'label': '회피 시 3FP를 얻는다',
                'kind': 'effect', 'mode': 'mandatory',
                'timing': 'dodge', 'visibility': 'public',
                'source_refs': {
                    'rulebook_pages': [48, 49], 'qna_ids': [391],
                },
                'active_zones': ['battle'],
                'trigger': {'event': 'dodge'},
                'effects': [{
                    'op': 'change_fp',
                    'player': {'controller': True}, 'amount': 3,
                }],
            }],
        }
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = 'battle'
    state['players'][owner]['fp'] = owner_fp
    state['players'][other]['fp'] = opponent_fp
    if advance_notice:
        state['players'][owner]['passive_state']['advance_notice'] = {
            'value': True, 'label': 'advance_notice',
        }
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': opposing_definition,
                },
            },
        },
        seed=(
            f'bunny-jam:{owner}:{source_zone}:{negated}:{advance_notice}:'
            f'{owner_fp}:{opponent_fp}:{with_down_guard}'
        ),
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    if source_zone == 'battle':
        engine.engine_state['battle'] = {
            owner: {
                'instance_id': source['instance_id'],
                'card': engine._find_card(source['instance_id']),
            },
            other: {
                'instance_id': opposing['instance_id'],
                'card': engine._find_card(opposing['instance_id']),
            },
        }
    return engine, source, opposing


def _run_awl_at_031_combo_scenario(
    definition, card_snapshot, owner, *, penalty=200,
    event_type='combo', negated=False,
):
    engine, source, opposing = _awl_at_031_engine(
        definition, card_snapshot, owner, negated=negated,
    )
    live_source = engine._find_card(source['instance_id'])
    combo = {
        'owner': owner, 'source': f'{owner}-bunny-previous',
        'used': [f'{owner}-bunny-previous'], 'last_speed': 8,
        'next_penalty': penalty,
    }
    rules = engine._combo_rules(owner, live_source, combo)
    applied_penalty = engine._combo_applied_penalty(
        owner, live_source, combo, penalty, rules=rules,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': live_source,
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True, 'combo': True,
    })
    return {
        'rule_count': len(rules),
        'ignore_damage_penalty': any(
            rule.get('ignore_damage_penalty') for rule in rules
        ),
        'applied_penalty': applied_penalty,
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-031-n1'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_031_speed_scenario(
    definition, card_snapshot, owner, *, event_type='before_judgment',
    source_zone='battle', advance_notice=True, negated=False,
):
    engine, source, opposing = _awl_at_031_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, advance_notice=advance_notice,
        negated=negated,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': engine._find_card(source['instance_id']),
        'opponent_card': engine._find_card(opposing['instance_id']),
        'source_only_event': True,
    })
    live_source = engine._find_card(source['instance_id'])
    return {
        'frame': engine.card_stat(live_source, 'frame', owner),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-031-n2-speed'
            for event in engine.events
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_031_dodge_fp_scenario(
    definition, card_snapshot, owner, *, event_type='opponent_dodge',
    source_zone='battle', advance_notice=True, negated=False,
    owner_fp=7, opponent_fp=0, with_down_guard=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _awl_at_031_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, advance_notice=advance_notice,
        negated=negated, owner_fp=owner_fp, opponent_fp=opponent_fp,
        with_down_guard=with_down_guard,
    )
    trigger_order = []
    if with_down_guard:
        sequence = engine._result_trigger_sequence({
            owner: 'opponent_dodge', other: 'dodge',
        })
        trigger_order = [item[0] for item in sequence]
        for queued_event, context in sequence:
            engine._fire(queued_event, context)
            engine._continue()
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': engine._find_card(source['instance_id']),
            'opponent_card': engine._find_card(opposing['instance_id']),
            'source_only_event': True,
        })
        engine._continue()
    final_fp = {
        owner: int(engine.state['players'][owner]['fp']),
        other: int(engine.state['players'][other]['fp']),
    }
    catch_owner = _fp_catch_owner(final_fp['p1'], final_fp['p2'])
    return {
        'owner_fp': final_fp[owner],
        'opponent_fp': final_fp[other],
        'catch_owner': catch_owner,
        'trigger_order': trigger_order,
        'down_guard_resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'review-down-guard-gain-three-fp'
            for event in engine.events
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-at-031-n2-dodge-fp'
            for event in engine.events
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_031_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-031':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    combo = by_id.get('awl-at-031-n1')
    speed = by_id.get('awl-at-031-n2-speed')
    dodge_fp = by_id.get('awl-at-031-n2-dodge-fp')
    qna_ids = [391]
    advance_notice = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'advance_notice',
    }
    valid = bool(
        extra_root == {'combo_rules'} and len(abilities) == 3
        and combo and speed and dodge_fp
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and definition.get('combo_rules') == [{
            'ignore_damage_penalty': True, 'numbered_effect': True,
        }]
        and combo.get('mode') == 'mandatory'
        and combo.get('active_zones') == ['battle']
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and speed.get('mode') == 'mandatory'
        and speed.get('active_zones') == ['battle']
        and speed.get('trigger') == {'event': 'before_judgment'}
        and speed.get('condition') == advance_notice
        and speed.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'frame', 'amount': -2, 'duration': 'battle',
        }]
        and dodge_fp.get('mode') == 'mandatory'
        and dodge_fp.get('active_zones') == ['battle']
        and dodge_fp.get('trigger') == {'event': 'opponent_dodge'}
        and dodge_fp.get('condition') == advance_notice
        and dodge_fp.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True},
            'amount': -4,
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-031', False,
                reason='버니 잼의 콤보 보정·예고장 속도·상대 회피 FP 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-031 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    combo_scenarios = []
    for name, owner, kwargs, expected_penalty, expected in (
        ('owner-p1-combo-ignores-one-hundred-penalty', 'p1', {
            'penalty': 100,
        }, 0, True),
        ('owner-p2-combo-ignores-two-hundred-penalty', 'p2', {}, 0, True),
        ('numbered-negation-restores-normal-penalty', 'p1', {
            'negated': True,
        }, 200, False),
        ('wrong-event-does-not-resolve-combo-effect', 'p2', {
            'event_type': 'hit',
        }, 0, False),
    ):
        first = _run_awl_at_031_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_031_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['applied_penalty'] == expected_penalty
                and first['ignore_damage_penalty'] is (expected_penalty == 0)
                and first['resolved'] is expected and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    combo_review = AbilityReview(
        combo['id'], all(item['passed'] for item in combo_scenarios),
        combo_scenarios,
        '' if all(item['passed'] for item in combo_scenarios)
        else '콤보 데미지 보정 무시 검증에 실패했습니다.',
    )

    speed_scenarios = []
    for name, owner, kwargs, expected_frame, expected in (
        ('owner-p1-advance-notice-speeds-up-by-two', 'p1', {}, 4, True),
        ('owner-p2-advance-notice-speeds-up-by-two', 'p2', {}, 4, True),
        ('without-advance-notice-keeps-six-speed', 'p1', {
            'advance_notice': False,
        }, 6, False),
        ('wrong-event-keeps-six-speed', 'p2', {
            'event_type': 'after_judgment',
        }, 6, False),
        ('numbered-negation-keeps-six-speed', 'p1', {
            'negated': True,
        }, 6, False),
        ('source-outside-battle-keeps-six-speed', 'p2', {
            'source_zone': 'hand',
        }, 6, False),
    ):
        first = _run_awl_at_031_speed_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_031_speed_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        speed_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['frame'] == expected_frame
                and first['resolved'] is expected and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    speed_review = AbilityReview(
        speed['id'], all(item['passed'] for item in speed_scenarios),
        speed_scenarios,
        '' if all(item['passed'] for item in speed_scenarios)
        else '예고장 판정 전 속도 -2 검증에 실패했습니다.',
    )

    dodge_scenarios = []
    for name, owner, kwargs, expected_fp, expected, catch_owner in (
        ('owner-p1-opponent-dodge-loses-four-fp', 'p1', {}, 3, True, None),
        ('owner-p2-opponent-dodge-can-reach-zero', 'p2', {
            'owner_fp': 4,
        }, 0, True, 'p1'),
        ('without-advance-notice-does-not-lose-fp', 'p1', {
            'advance_notice': False,
        }, 7, False, None),
        ('wrong-event-does-not-lose-fp', 'p2', {
            'event_type': 'dodge',
        }, 7, False, None),
        ('numbered-negation-does-not-lose-fp', 'p1', {
            'negated': True,
        }, 7, False, None),
        ('source-outside-battle-does-not-lose-fp', 'p2', {
            'source_zone': 'hand',
        }, 7, False, None),
        ('qna-391-both-nonzero-after-down-guard-cannot-catch', 'p1', {
            'with_down_guard': True,
        }, 3, True, None),
        ('qna-391-zero-boundary-allows-other-player-catch', 'p1', {
            'with_down_guard': True, 'owner_fp': 4,
        }, 0, True, 'p2'),
    ):
        first = _run_awl_at_031_dodge_fp_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_031_dodge_fp_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        qna_ok = True
        if kwargs.get('with_down_guard'):
            qna_ok = bool(
                first['trigger_order'][:2] == ['dodge', 'opponent_dodge']
                and first['down_guard_resolved']
                and first['opponent_fp'] == 3
            )
        dodge_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['owner_fp'] == expected_fp
                and first['resolved'] is expected
                and (
                    first['catch_owner'] == catch_owner
                    if kwargs.get('with_down_guard') else True
                )
                and qna_ok and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    dodge_review = AbilityReview(
        dodge_fp['id'], all(item['passed'] for item in dodge_scenarios),
        dodge_scenarios,
        '' if all(item['passed'] for item in dodge_scenarios) else (
            '상대 회피 FP -4와 Q&A 391의 다운 가드·캐치 경계 검증에 실패했습니다.'
        ),
    )
    reviews = [combo_review, speed_review, dodge_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '버니 잼의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_at_032_source(card_snapshot, owner, *, negated=False):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-mirror-step', 'owner': owner,
        'code': 'AWL-AT-032', 'name': '미러스 스텝', 'type': '공격',
        'frame': 13, 'damage': 600, 'pos': '중단', 'body': '',
        'special': '', 'hit': '6', 'guard': '-8', 'counter': '콤보',
        'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _awl_at_032_engine(
    definition, card_snapshot, owner, *, source_zone='battle',
    negated=False, advance_notice=True, owner_hand=2, opponent_hand=2,
    opponent_speed=7, charging_smash=False, priority='source',
    with_gaon=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_at_032_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-MIRROR-STEP-OPPONENT', other,
        f'{other}-mirror-step-opponent',
    )
    opposing.update({
        'name': '상대 기술', 'type': '공격', 'frame': opponent_speed,
        'damage': 500, 'pos': '중단', 'special': '', 'face_up': True,
    })
    opposing_definition = copy.deepcopy(_st1_001_no_effect_definition())
    if charging_smash:
        opposing.update({'code': 'ST2-005', 'name': '차징 스매시'})
        opposing_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [392]},
            'abilities': [{
                'id': 'review-charging-smash-fix-both',
                'label': '판정 전 서로 현재 속도를 고정한다',
                'kind': 'effect', 'mode': 'mandatory',
                'timing': 'before_judgment', 'visibility': 'public',
                'source_refs': {
                    'rulebook_pages': [48, 49], 'qna_ids': [392],
                },
                'active_zones': ['battle'],
                'trigger': {'event': 'before_judgment'},
                'effects': [
                    {
                        'op': 'fix_speed',
                        'player': {'controller': True},
                        'stat': 'frame',
                        'value': {'path': 'context.controller_speed'},
                        'duration': 'battle',
                    },
                    {
                        'op': 'fix_speed',
                        'player': {'opponent': True},
                        'stat': 'frame',
                        'value': {'path': 'context.opponent_speed'},
                        'duration': 'battle',
                    },
                ],
            }],
        }
    runtime_definition = copy.deepcopy(definition)
    if with_gaon:
        runtime_definition['abilities'].append({
            'id': 'review-gaon-speed-change',
            'label': '소원의 가온 판정 전 속도 2 증가',
            'kind': 'effect', 'mode': 'mandatory',
            'timing': 'before_judgment', 'visibility': 'public',
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [101]},
            'active_zones': ['battle'],
            'trigger': {'event': 'before_judgment'},
            'effects': [{
                'op': 'modify_stat', 'player': {'controller': True},
                'stat': 'frame', 'amount': -2, 'duration': 'battle',
            }],
        })
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = 'battle'
    state['priority_player'] = owner if priority == 'source' else other
    if advance_notice:
        state['players'][owner]['passive_state']['advance_notice'] = {
            'value': True, 'label': 'advance_notice',
        }
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': runtime_definition,
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': opposing_definition,
        },
    }
    for side, count in ((owner, owner_hand), (other, opponent_hand)):
        for index in range(count):
            hand_card = _card(
                f'REVIEW-MIRROR-HAND-{side}-{index + 1}', side,
                f'{side}-mirror-hand-{index + 1}',
            )
            hand_card.update({'name': '패 매수 검수 카드', 'face_up': False})
            state['players'][side]['zones']['hand'].append(
                copy.deepcopy(hand_card)
            )
            cards[hand_card['code']] = {
                **copy.deepcopy(hand_card),
                'effect_definition': copy.deepcopy(no_effect),
            }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'mirror-step:{owner}:{source_zone}:{negated}:{advance_notice}:'
            f'{owner_hand}:{opponent_hand}:{opponent_speed}:'
            f'{charging_smash}:{priority}:{with_gaon}'
        ),
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    if source_zone == 'battle':
        engine.engine_state['battle'] = {
            owner: {
                'instance_id': source['instance_id'],
                'card': engine._find_card(source['instance_id']),
            },
            other: {
                'instance_id': opposing['instance_id'],
                'card': engine._find_card(opposing['instance_id']),
            },
        }
    return engine, source, opposing


def _run_awl_at_032_lock_scenario(
    definition, card_snapshot, owner, *, source_zone='battle', negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _awl_at_032_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, negated=negated,
    )
    engine._refresh_continuous_rules()
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    return {
        'opponent_dodge_blocked': engine._rule_blocked(
            'dodge', other, live_opposing, live_source,
        ),
        'owner_dodge_blocked': engine._rule_blocked(
            'dodge', owner, live_source, live_opposing,
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_at_032_swap_scenario(
    definition, card_snapshot, owner, *, event_type='before_judgment',
    source_zone='battle', negated=False, advance_notice=True,
    owner_hand=2, opponent_hand=2, opponent_speed=7,
    charging_smash=False, priority='source', with_gaon=False,
    first_ability_id=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _awl_at_032_engine(
        definition, card_snapshot, owner,
        source_zone=source_zone, negated=negated,
        advance_notice=advance_notice, owner_hand=owner_hand,
        opponent_hand=opponent_hand, opponent_speed=opponent_speed,
        charging_smash=charging_smash, priority=priority,
        with_gaon=with_gaon,
    )
    decision_kinds = []
    chosen_order = []
    if source_zone == 'battle' and event_type == 'before_judgment':
        engine._battle_trigger('before_judgment')
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': engine._find_card(source['instance_id']),
            'opponent_card': engine._find_card(opposing['instance_id']),
            'source_only_event': True,
        })
    for _index in range(10):
        decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if not decision:
            break
        decision_kinds.append(decision.get('kind'))
        if decision.get('kind') != 'effect_order':
            break
        option = next((
            item for item in decision.get('options') or []
            if item.get('ability_id') == first_ability_id
        ), (decision.get('options') or [{}])[0])
        chosen_order.append(option.get('ability_id'))
        engine._submit_decision(
            decision.get('owner'), decision.get('id'), [option.get('id')],
        )
        engine._continue()
    battle = engine.engine_state.get('battle') or {}
    source_live = (battle.get(owner) or {}).get('card') or engine._find_card(
        source['instance_id']
    )
    opposing_live = (battle.get(other) or {}).get('card') or engine._find_card(
        opposing['instance_id']
    )
    resolution_order = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') in {
            'awl-at-032-n1', 'review-charging-smash-fix-both',
            'review-gaon-speed-change',
        }
    ]
    return {
        'source_speed': engine.card_stat(
            source_live, 'frame', owner, include_fp=False,
        ),
        'opponent_speed': engine.card_stat(
            opposing_live, 'frame', other, include_fp=False,
        ),
        'source_fixed': engine._fixed_stat(source_live, 'frame', owner),
        'opponent_fixed': engine._fixed_stat(
            opposing_live, 'frame', other,
        ),
        'resolved': 'awl-at-032-n1' in resolution_order,
        'charging_resolved': (
            'review-charging-smash-fix-both' in resolution_order
        ),
        'decision_kinds': decision_kinds,
        'chosen_order': chosen_order,
        'resolution_order': resolution_order,
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_at_032_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-AT-032':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('awl-at-032-function')
    swap = by_id.get('awl-at-032-n1')
    qna_ids = [101, 392]
    hand_equal = {
        'op': 'equals',
        'left': {
            'op': 'zone_count', 'player': {'controller': True},
            'zone': 'hand',
        },
        'right': {
            'op': 'zone_count', 'player': {'opponent': True},
            'zone': 'hand',
        },
    }
    advance_notice = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'advance_notice',
    }
    controller_delta = {
        'op': 'subtract',
        'left': {'path': 'context.opponent_speed'},
        'right': {'path': 'context.controller_speed'},
    }
    opponent_delta = {
        'op': 'subtract',
        'left': {'path': 'context.controller_speed'},
        'right': {'path': 'context.opponent_speed'},
    }
    valid = bool(
        not extra_root and len(abilities) == 2 and function and swap
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('active_zones') == ['battle']
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'dodge',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and swap.get('kind') == 'effect'
        and swap.get('mode') == 'mandatory'
        and swap.get('active_zones') == ['battle']
        and swap.get('trigger') == {'event': 'before_judgment'}
        and swap.get('condition') == {
            'op': 'all', 'conditions': [hand_equal, advance_notice],
        }
        and swap.get('effects') == [
            {
                'op': 'modify_stat', 'player': {'controller': True},
                'stat': 'frame', 'amount': controller_delta,
                'duration': 'battle',
            },
            {
                'op': 'modify_stat', 'player': {'opponent': True},
                'stat': 'frame', 'amount': opponent_delta,
                'duration': 'battle',
            },
        ]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-at-032', False,
                reason='미러스 스텝의 회피 금지·예고장 패 매수 속도 교환 정의가 일치하지 않습니다.',
            )],
            'AWL-AT-032 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    lock_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-battle-blocks-opponent-dodge', 'p1', {}, True),
        ('owner-p2-battle-blocks-opponent-dodge', 'p2', {}, True),
        ('source-outside-battle-does-not-block-dodge', 'p1', {
            'source_zone': 'hand',
        }, False),
        ('numbered-negation-keeps-numberless-dodge-lock', 'p2', {
            'negated': True,
        }, True),
    ):
        first = _run_awl_at_032_lock_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_at_032_lock_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        lock_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['opponent_dodge_blocked'] is expected
                and not first['owner_dodge_blocked'] and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    lock_review = AbilityReview(
        function['id'], all(item['passed'] for item in lock_scenarios),
        lock_scenarios,
        '' if all(item['passed'] for item in lock_scenarios)
        else '상대 한정 회피 금지 검증에 실패했습니다.',
    )

    swap_scenarios = []
    specs = (
        {
            'name': 'owner-p1-equal-hand-swaps-thirteen-and-seven',
            'owner': 'p1', 'expected': (7, 13), 'resolved': True,
        },
        {
            'name': 'owner-p2-equal-hand-swaps-thirteen-and-nine',
            'owner': 'p2', 'opponent_speed': 9,
            'expected': (9, 13), 'resolved': True,
        },
        {
            'name': 'unequal-hand-count-does-not-swap',
            'owner': 'p1', 'opponent_hand': 1,
            'expected': (13, 7), 'resolved': False,
        },
        {
            'name': 'without-advance-notice-does-not-swap',
            'owner': 'p2', 'advance_notice': False,
            'expected': (13, 7), 'resolved': False,
        },
        {
            'name': 'wrong-event-does-not-swap',
            'owner': 'p1', 'event_type': 'after_judgment',
            'expected': (13, 7), 'resolved': False,
        },
        {
            'name': 'numbered-negation-does-not-swap',
            'owner': 'p2', 'negated': True,
            'expected': (13, 7), 'resolved': False,
        },
        {
            'name': 'source-outside-battle-does-not-swap',
            'owner': 'p1', 'source_zone': 'hand',
            'expected': (13, 7), 'resolved': False,
        },
        {
            'name': 'qna-392-charging-priority-fix-blocks-swap',
            'owner': 'p1', 'charging_smash': True,
            'priority': 'opponent', 'expected': (13, 7),
            'fixed': (13, 7), 'resolved': True,
        },
        {
            'name': 'qna-392-mirror-priority-swap-blocks-later-fix',
            'owner': 'p2', 'charging_smash': True,
            'priority': 'source', 'expected': (7, 13),
            'fixed': (None, None), 'resolved': True,
        },
        {
            'name': 'qna-101-owner-chooses-mirror-before-gaon',
            'owner': 'p1', 'with_gaon': True,
            'first_ability_id': 'awl-at-032-n1',
            'expected': (5, 13), 'resolved': True,
            'order': ['awl-at-032-n1', 'review-gaon-speed-change'],
        },
        {
            'name': 'qna-101-owner-chooses-gaon-before-mirror',
            'owner': 'p2', 'with_gaon': True,
            'first_ability_id': 'review-gaon-speed-change',
            'expected': (5, 13), 'resolved': True,
            'order': ['review-gaon-speed-change', 'awl-at-032-n1'],
        },
    )
    for spec in specs:
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {'name', 'owner', 'expected', 'fixed', 'resolved', 'order'}
        }
        first = _run_awl_at_032_swap_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        second = _run_awl_at_032_swap_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        order_ok = True
        if spec.get('order'):
            order_ok = bool(
                'effect_order' in first['decision_kinds']
                and first['resolution_order'][:2] == spec['order']
            )
        swap_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and (first['source_speed'], first['opponent_speed'])
                == spec['expected']
                and (first['source_fixed'], first['opponent_fixed'])
                == spec.get('fixed', (None, None))
                and first['resolved'] is spec['resolved']
                and order_ok and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    swap_review = AbilityReview(
        swap['id'], all(item['passed'] for item in swap_scenarios),
        swap_scenarios,
        '' if all(item['passed'] for item in swap_scenarios) else (
            '패 매수 조건 속도 교환과 Q&A 101·392 우선권 검증에 실패했습니다.'
        ),
    )
    reviews = [lock_review, swap_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '미러스 스텝의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_sp_002_source(card_snapshot, owner, *, negated=False, suffix='source'):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-rubiette-{suffix}', 'owner': owner,
        'code': 'AWL-SP-002', 'name': '홍련의 루비에트',
        'type': '특수', 'token_key': 'calling_card',
        'frame': None, 'damage': None, 'pos': None, 'body': '',
        'special': '', 'hit': '', 'guard': '', 'counter': '',
        'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _awl_sp_002_engine(
    definition, card_snapshot, owner, *, source_zone='lumen',
    negated=False, owner_fp=0, opponent_fp=0, technique_count=2,
    with_kissing=False, side_calling_cards=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_sp_002_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-RUBIETTE-OPPONENT', other,
        f'{other}-rubiette-opponent',
    )
    opposing.update({
        'name': '상대 기술', 'type': '공격', 'frame': 8,
        'damage': 400, 'face_up': True,
    })
    techniques = []
    for index in range(technique_count):
        card = _card(
            f'REVIEW-RUBIETTE-TECHNIQUE-{index + 1}', owner,
            f'{owner}-rubiette-technique-{index + 1}',
        )
        card.update({
            'name': f'브레이크 기술 {index + 1}', 'type': '공격',
            'frame': 9 + index, 'damage': 300, 'face_up': True,
        })
        techniques.append(card)
    if with_kissing and techniques:
        techniques[0].update({
            'code': 'REVIEW-KISSING-YOU', 'name': '키싱 유♥',
        })
    non_technique = _card(
        'REVIEW-RUBIETTE-NON-TECHNIQUE', owner,
        f'{owner}-rubiette-non-technique',
    )
    non_technique.update({
        'name': '기술이 아닌 토큰', 'type': '토큰', 'face_up': True,
    })
    speed_card = _card(
        'REVIEW-RUBIETTE-SPEED', owner,
        f'{owner}-rubiette-speed',
    )
    speed_card.update({
        'name': '제로-섬 속도 검수', 'type': '공격',
        'frame': 10, 'damage': 500, 'face_up': True,
    })
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = 'battle'
    state['players'][owner]['fp'] = owner_fp
    state['players'][other]['fp'] = opponent_fp
    state['players'][owner]['zones']['list'].extend(
        copy.deepcopy(techniques + [non_technique, speed_card])
    )
    side_cards = []
    for index in range(side_calling_cards):
        card = _awl_sp_002_source(
            card_snapshot, owner, suffix=f'side-{index + 1}',
        )
        side_cards.append(card)
        state['players'][owner]['zones']['side'].append(copy.deepcopy(card))
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': copy.deepcopy(no_effect),
        },
        non_technique['code']: {
            **copy.deepcopy(non_technique),
            'effect_definition': copy.deepcopy(no_effect),
        },
        speed_card['code']: {
            **copy.deepcopy(speed_card),
            'effect_definition': copy.deepcopy(no_effect),
        },
    }
    kissing_definition = {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [116]},
        'abilities': [{
            'id': 'review-kissing-you-break-fp',
            'label': '브레이크 시 2FP를 얻는다',
            'kind': 'effect', 'mode': 'mandatory',
            'timing': 'cleanup', 'visibility': 'public',
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [116]},
            'trigger': {'event': 'card_broken'},
            'effects': [{
                'op': 'change_fp', 'player': {'controller': True},
                'amount': 2,
            }],
        }],
    }
    for card in techniques:
        cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': (
                copy.deepcopy(kissing_definition)
                if card.get('code') == 'REVIEW-KISSING-YOU'
                else copy.deepcopy(no_effect)
            ),
        }
    for card in side_cards:
        cards.setdefault(card['code'], {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(definition),
        })
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'rubiette:{owner}:{source_zone}:{negated}:{owner_fp}:'
            f'{opponent_fp}:{technique_count}:{with_kissing}:'
            f'{side_calling_cards}'
        ),
        now=datetime(2026, 8, 20, tzinfo=timezone.utc),
    )
    return engine, source, opposing, techniques, non_technique, speed_card


def _resolve_awl_sp_002_decisions(
    engine, owner, *, branch='gain_self_fp', first_ability_id=None,
):
    kinds = []
    selections = []
    for _index in range(30):
        decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if not decision:
            break
        kind = decision.get('kind')
        kinds.append(kind)
        options = decision.get('options') or []
        if kind == 'effect_order':
            option = next((
                item for item in options
                if item.get('ability_id') == first_ability_id
            ), options[0] if options else {})
            selected = [option.get('id')]
        elif kind == 'effect_branch':
            option = next((
                item for item in options if item.get('id') == branch
            ), options[0] if options else {})
            selected = [option.get('id')]
            selections.extend(selected)
        elif kind == 'break_replenish':
            selected = list(decision.get('default') or [])
        else:
            break
        engine._submit_decision(
            decision.get('owner') or owner, decision.get('id'), selected,
        )
        engine._continue()
    return kinds, selections


def _run_awl_sp_002_break_choice_scenario(
    definition, card_snapshot, owner, *, source_zone='lumen',
    negated=False, branch='gain_self_fp', break_count=1,
    break_owner='self', break_non_technique=False, with_kissing=False,
    first_ability_id=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing, techniques, non_technique, speed_card = (
        _awl_sp_002_engine(
            definition, card_snapshot, owner,
            source_zone=source_zone, negated=negated,
            technique_count=max(2, break_count),
            with_kissing=with_kissing,
        )
    )
    targets = []
    if break_owner == 'opponent':
        targets = [opposing]
    elif break_non_technique:
        targets = [non_technique]
    else:
        targets = techniques[:break_count]
    decision_kinds = []
    selections = []
    for target in targets:
        engine.break_card(target['instance_id'], reason='review-rubiette')
        kinds, chosen = _resolve_awl_sp_002_decisions(
            engine, owner, branch=branch,
            first_ability_id=first_ability_id,
        )
        decision_kinds.extend(kinds)
        selections.extend(chosen)
    resolution_order = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') in {
            'awl-sp-002-function', 'review-kissing-you-break-fp',
        }
    ]
    return {
        'owner_fp': int(engine.state['players'][owner]['fp']),
        'opponent_fp': int(engine.state['players'][other]['fp']),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'target_zones': [
            engine._find_location(target['instance_id'])[1]
            for target in targets
        ],
        'decision_kinds': decision_kinds,
        'selections': selections,
        'resolution_order': resolution_order,
        'rubiette_resolved': resolution_order.count('awl-sp-002-function'),
        'kissing_resolved': resolution_order.count(
            'review-kissing-you-break-fp'
        ),
        'speed_with_fp': engine.card_stat(
            engine._find_card(speed_card['instance_id']),
            'frame', owner, include_fp=True,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_sp_002_threshold_scenario(
    definition, card_snapshot, owner, *, source_zone='lumen',
    negated=False, owner_fp=0, opponent_fp=0, change_owner='self',
    change_amount=7, event_type='fp_changed', reset_after=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing, _techniques, _non, _speed = (
        _awl_sp_002_engine(
            definition, card_snapshot, owner,
            source_zone=source_zone, negated=negated,
            owner_fp=owner_fp, opponent_fp=opponent_fp,
            technique_count=0,
        )
    )
    affected = owner if change_owner == 'self' else other
    if event_type == 'fp_changed':
        engine.change_fp(affected, change_amount, source='review', context={
            'controller': affected,
            'source_card_instance_id': opposing['instance_id'],
            'source_card': engine._find_card(opposing['instance_id']),
        })
    else:
        engine._fire(event_type, {
            'controller': affected,
            'source_card_instance_id': opposing['instance_id'],
            'source_card': engine._find_card(opposing['instance_id']),
        })
    zone_at_threshold = engine._find_location(source['instance_id'])[1]
    fp_at_threshold = (
        int(engine.state['players'][owner]['fp']),
        int(engine.state['players'][other]['fp']),
    )
    if reset_after:
        engine.set_fp(owner, 0, source='review-reset', context={
            'controller': owner,
            'source_card_instance_id': opposing['instance_id'],
            'source_card': engine._find_card(opposing['instance_id']),
        })
        engine.set_fp(other, 0, source='review-reset', context={
            'controller': other,
            'source_card_instance_id': opposing['instance_id'],
            'source_card': engine._find_card(opposing['instance_id']),
        })
    return {
        'zone_at_threshold': zone_at_threshold,
        'source_zone': engine._find_location(source['instance_id'])[1],
        'fp_at_threshold': fp_at_threshold,
        'final_fp': (
            int(engine.state['players'][owner]['fp']),
            int(engine.state['players'][other]['fp']),
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-sp-002-fp-threshold'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_sp_002_qna_72_scenario(definition, card_snapshot, owner):
    engine, source, _opposing, _techniques, _non, _speed = (
        _awl_sp_002_engine(
            definition, card_snapshot, owner,
            source_zone='lumen', technique_count=0,
        )
    )
    engine.move_card(source['instance_id'], 'list', reason='review-qna-72')
    return {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'invalid_break': any(
            event.get('type') == 'card_broken'
            and (event.get('payload') or {}).get('reason')
            == 'invalid_special_destination'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_sp_002_qna_484_scenario(definition, card_snapshot, owner):
    engine, source, _opposing, _techniques, _non, _speed = (
        _awl_sp_002_engine(
            definition, card_snapshot, owner,
            source_zone='side', technique_count=0,
            side_calling_cards=4,
        )
    )
    calling_cards = [
        card
        for card in engine.state['players'][owner]['zones']['side']
        if card.get('token_key') == 'calling_card'
    ]
    return {
        'calling_card_count': len(calling_cards),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'has_deck_limit': 'deck_limit' in definition,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_sp_002_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-SP-002':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    broken = by_id.get('awl-sp-002-function')
    threshold = by_id.get('awl-sp-002-fp-threshold')
    qna_ids = [72, 116, 361, 444, 484]
    own_technique_broken = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals', 'left': 'context.event_controller',
                'right': {'controller': True},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.event_card'},
                'where': {'is_technique': True},
            },
        ],
    }
    choose_effect = {
        'op': 'choose_effect', 'player': {'controller': True},
        'prompt': '적용할 FP 효과를 선택하세요.',
        'default': 'gain_self_fp',
        'options': [
            {
                'id': 'gain_self_fp', 'label': '2FP 획득',
                'effects': [{
                    'op': 'change_fp',
                    'player': {'controller': True}, 'amount': 2,
                }],
            },
            {
                'id': 'lose_opponent_fp', 'label': '상대 2FP 감소',
                'effects': [{
                    'op': 'change_fp',
                    'player': {'opponent': True}, 'amount': -2,
                }],
            },
        ],
    }
    fp_difference = {
        'op': 'abs',
        'value': {
            'op': 'subtract',
            'left': {'path': 'context.controller_fp'},
            'right': {'path': 'context.opponent_fp'},
        },
    }
    valid = bool(
        not extra_root and len(abilities) == 2 and broken and threshold
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and broken.get('kind') == 'function'
        and broken.get('mode') == 'mandatory'
        and broken.get('active_zones') == ['lumen']
        and broken.get('trigger') == {'event': 'card_broken'}
        and broken.get('condition') == own_technique_broken
        and broken.get('effects') == [choose_effect]
        and threshold.get('kind') == 'function'
        and threshold.get('mode') == 'mandatory'
        and threshold.get('active_zones') == ['lumen']
        and threshold.get('trigger') == {'event': 'fp_changed'}
        and threshold.get('condition') == {
            'op': 'gte', 'left': fp_difference, 'right': 7,
        }
        and threshold.get('effects') == [{
            'op': 'move_card', 'to_zone': 'side',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-sp-002', False,
                reason='홍련의 루비에트의 기술 브레이크 선택·FP 차이 해제 정의가 일치하지 않습니다.',
            )],
            'AWL-SP-002 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    broken_scenarios = []
    specs = (
        {
            'name': 'owner-p1-break-chooses-self-two-fp',
            'owner': 'p1', 'branch': 'gain_self_fp',
            'expected_fp': (2, 0), 'resolved': 1,
        },
        {
            'name': 'owner-p2-break-chooses-opponent-minus-two-fp',
            'owner': 'p2', 'branch': 'lose_opponent_fp',
            'expected_fp': (0, -2), 'resolved': 1,
        },
        {
            'name': 'qna-444-two-breaks-grant-four-fp-before-speed',
            'owner': 'p1', 'break_count': 2,
            'expected_fp': (4, 0), 'resolved': 2,
            'expected_speed': 6,
        },
        {
            'name': 'qna-116-kissing-break-and-rubiette-total-four-fp',
            'owner': 'p2', 'with_kissing': True,
            'first_ability_id': 'awl-sp-002-function',
            'expected_fp': (4, 0), 'resolved': 1,
            'kissing': 1,
        },
        {
            'name': 'opponent-technique-break-does-not-offer-choice',
            'owner': 'p1', 'break_owner': 'opponent',
            'expected_fp': (0, 0), 'resolved': 0,
        },
        {
            'name': 'own-non-technique-break-does-not-offer-choice',
            'owner': 'p2', 'break_non_technique': True,
            'expected_fp': (0, 0), 'resolved': 0,
        },
        {
            'name': 'source-outside-lumen-does-not-offer-choice',
            'owner': 'p1', 'source_zone': 'side',
            'expected_fp': (0, 0), 'resolved': 0,
        },
        {
            'name': 'numbered-negation-keeps-numberless-break-choice',
            'owner': 'p2', 'negated': True,
            'expected_fp': (2, 0), 'resolved': 1,
        },
    )
    for spec in specs:
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'owner', 'expected_fp', 'resolved',
                'expected_speed', 'kissing',
            }
        }
        first = _run_awl_sp_002_break_choice_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        second = _run_awl_sp_002_break_choice_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_owner_fp, expected_opponent_fp = spec['expected_fp']
        choice_expected = spec['resolved'] > 0
        broken_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['owner_fp'] == expected_owner_fp
                and first['opponent_fp'] == expected_opponent_fp
                and first['rubiette_resolved'] == spec['resolved']
                and first['kissing_resolved'] == spec.get('kissing', 0)
                and first['speed_with_fp']
                == spec.get('expected_speed', max(1, 10 - expected_owner_fp))
                and ('effect_branch' in first['decision_kinds'])
                is choice_expected
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    broken_review = AbilityReview(
        broken['id'], all(item['passed'] for item in broken_scenarios),
        broken_scenarios,
        '' if all(item['passed'] for item in broken_scenarios) else (
            '기술 브레이크 실제 FP 선택과 Q&A 116·444 검증에 실패했습니다.'
        ),
    )

    threshold_scenarios = []
    threshold_specs = (
        {
            'name': 'owner-p1-positive-seven-difference-moves-side',
            'owner': 'p1', 'expected_zone': 'side', 'resolved': True,
        },
        {
            'name': 'owner-p2-opponent-negative-seven-difference-moves-side',
            'owner': 'p2', 'change_owner': 'opponent',
            'change_amount': -7, 'expected_zone': 'side', 'resolved': True,
        },
        {
            'name': 'six-difference-keeps-calling-card-in-lumen',
            'owner': 'p1', 'change_amount': 6,
            'expected_zone': 'lumen', 'resolved': False,
        },
        {
            'name': 'qna-361-threshold-moves-before-later-fp-reset',
            'owner': 'p2', 'owner_fp': 6, 'change_amount': 1,
            'reset_after': True, 'expected_zone': 'side',
            'resolved': True, 'final_fp': (0, 0),
        },
        {
            'name': 'source-outside-lumen-does-not-react',
            'owner': 'p1', 'source_zone': 'side',
            'expected_zone': 'side', 'resolved': False,
        },
        {
            'name': 'wrong-event-does-not-check-fp-difference',
            'owner': 'p2', 'owner_fp': 7, 'event_type': 'hp_changed',
            'expected_zone': 'lumen', 'resolved': False,
        },
        {
            'name': 'numbered-negation-keeps-numberless-threshold',
            'owner': 'p1', 'negated': True,
            'expected_zone': 'side', 'resolved': True,
        },
    )
    for spec in threshold_specs:
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'owner', 'expected_zone', 'resolved', 'final_fp',
            }
        }
        first = _run_awl_sp_002_threshold_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        second = _run_awl_sp_002_threshold_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        threshold_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['source_zone'] == spec['expected_zone']
                and first['resolved'] is spec['resolved']
                and first['final_fp'] == spec.get(
                    'final_fp', first['fp_at_threshold']
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    qna72_first = _run_awl_sp_002_qna_72_scenario(
        definition, card_snapshot, 'p1',
    )
    qna72_second = _run_awl_sp_002_qna_72_scenario(
        definition, card_snapshot, 'p1',
    )
    threshold_scenarios.append({
        'name': 'qna-72-invalid-special-destination-breaks-card',
        'passed': bool(
            _canonical(qna72_first) == _canonical(qna72_second)
            and qna72_first['source_zone'] == 'break'
            and qna72_first['invalid_break'] and not qna72_first['pending']
        ),
        'deterministic': _canonical(qna72_first) == _canonical(qna72_second),
        **qna72_first,
    })
    qna484_first = _run_awl_sp_002_qna_484_scenario(
        definition, card_snapshot, 'p2',
    )
    qna484_second = _run_awl_sp_002_qna_484_scenario(
        definition, card_snapshot, 'p2',
    )
    threshold_scenarios.append({
        'name': 'qna-484-five-calling-cards-have-no-card-deck-limit',
        'passed': bool(
            _canonical(qna484_first) == _canonical(qna484_second)
            and qna484_first['calling_card_count'] == 5
            and not qna484_first['has_deck_limit']
            and not qna484_first['pending']
        ),
        'deterministic': (
            _canonical(qna484_first) == _canonical(qna484_second)
        ),
        **qna484_first,
    })
    threshold_review = AbilityReview(
        threshold['id'],
        all(item['passed'] for item in threshold_scenarios),
        threshold_scenarios,
        '' if all(item['passed'] for item in threshold_scenarios) else (
            'FP 차이 7 해제와 Q&A 72·361·484 검증에 실패했습니다.'
        ),
    )
    reviews = [broken_review, threshold_review]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '홍련의 루비에트의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _awl_sp_001_source(card_snapshot, owner, suffix):
    source = _card('AWL-SP-001', owner, f'{owner}-all-in-charge-{suffix}')
    source.update({
        **copy.deepcopy(card_snapshot or {}),
        'instance_id': f'{owner}-all-in-charge-{suffix}',
        'kind': 'card', 'owner': owner, 'code': 'AWL-SP-001',
        'name': '올 인 차지', 'type': '특수', 'character_key': 'route',
        'frame': None, 'damage': None, 'face_up': True,
    })
    return source


def _awl_sp_001_engine(
    definition, card_snapshot, owner, *, ability_ids, source_zone='lumen',
    phase='battle', hp=4000, charge=False, event_owner='self',
    event_character='route', event_type_name='공격',
    with_fighting_spirit=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _awl_sp_001_source(card_snapshot, owner, '-'.join(ability_ids))
    opposing = _card(
        'REVIEW-ALL-IN-CHARGE-OPPONENT', other,
        f'{other}-all-in-charge-opponent',
    )
    opposing.update({'frame': 8, 'damage': 300, 'character_key': 'review-other'})
    event_controller = owner if event_owner == 'self' else other
    event_card = _card(
        'REVIEW-ALL-IN-CHARGE-EVENT', event_controller,
        f'{event_controller}-all-in-charge-event',
    )
    event_card.update({
        'name': '올 인 차지 검수 기술',
        'type': event_type_name, 'character_key': event_character,
        'frame': 6, 'damage': 400,
    })
    if event_owner == 'opponent':
        opposing = event_card

    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = phase
    state['players'][owner]['hp'] = hp
    if charge:
        state['players'][owner]['passive_state']['charge'] = {
            'value': True, 'label': '차지',
        }
    if event_owner == 'self':
        state['players'][owner]['zones']['battle'].append(
            copy.deepcopy(event_card)
        )

    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') in set(ability_ids)
    ]
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': copy.deepcopy(no_effect),
        },
        event_card['code']: {
            **copy.deepcopy(event_card),
            'effect_definition': copy.deepcopy(no_effect),
        },
    }
    fighting_spirit = None
    if with_fighting_spirit:
        fighting_spirit = _card(
            'UNC-AT-053', owner, f'{owner}-fighting-spirit-side',
        )
        fighting_spirit.update({
            'name': '기합', 'type': '특수', 'frame': None,
            'damage': None, 'face_up': False,
        })
        state['players'][owner]['zones']['side'].append(
            copy.deepcopy(fighting_spirit)
        )
        fighting_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [], 'qna_ids': [378]},
            'abilities': [{
                'id': 'review-fighting-spirit-deploy',
                'label': '기합을 사이드에서 루멘으로 배치',
                'kind': 'effect', 'mode': 'optional', 'timing': 'function',
                'visibility': 'private', 'active_zones': ['side'],
                'source_refs': {'rulebook_pages': [], 'qna_ids': [378]},
                'trigger': {'event': 'phase_start'},
                'condition': {
                    'op': 'all', 'conditions': [
                        {'op': 'phase_is', 'phase': 'recovery'},
                        {
                            'op': 'lte', 'left': 'context.controller_hp',
                            'right': 1500,
                        },
                    ],
                },
                'effects': [{
                    'op': 'move_card',
                    'card_instance_id': {
                        'path': 'context.source_card_instance_id',
                    },
                    'to_zone': 'lumen',
                }],
            }],
        }
        cards[fighting_spirit['code']] = {
            **copy.deepcopy(fighting_spirit),
            'effect_definition': fighting_definition,
        }

    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'all-in-charge:{owner}:{ability_ids}:{source_zone}:{phase}:{hp}:'
            f'{int(charge)}:{event_owner}:{event_character}:{event_type_name}:'
            f'{int(with_fighting_spirit)}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, source, event_card, fighting_spirit


def _run_awl_sp_001_deploy_scenario(
    definition, card_snapshot, owner, *, hp=1000, phase='recovery',
    source_zone='side', accept=True, with_fighting_spirit=False,
    first_ability_id=None,
):
    engine, source, _event_card, fighting_spirit = _awl_sp_001_engine(
        definition, card_snapshot, owner,
        ability_ids=['awl-sp-001-deploy'], source_zone=source_zone,
        phase=phase, hp=hp, with_fighting_spirit=with_fighting_spirit,
    )
    engine._fire('phase_start', {'phase': phase})
    decision_kinds = []
    chosen_order = []
    for _index in range(8):
        decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if not decision:
            break
        decision_kinds.append(decision.get('kind'))
        if decision.get('kind') == 'effect_order':
            option = next((
                item for item in decision.get('options') or []
                if item.get('ability_id') == first_ability_id
            ), (decision.get('options') or [{}])[0])
            chosen_order.append(option.get('ability_id'))
            engine._submit_decision(owner, decision.get('id'), [option.get('id')])
        elif decision.get('kind') == 'optional_effect':
            item = (decision.get('continuation') or {}).get('item') or {}
            ability_id = (item.get('ability') or {}).get('id')
            selected = (
                ['accept']
                if ability_id != 'awl-sp-001-deploy' or accept
                else ['decline']
            )
            engine._submit_decision(owner, decision.get('id'), selected)
        else:
            break
        engine._continue()
    resolution_order = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') in {
            'awl-sp-001-deploy', 'review-fighting-spirit-deploy',
        }
    ]
    return {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'fighting_spirit_zone': (
            engine._find_location(fighting_spirit['instance_id'])[1]
            if fighting_spirit else None
        ),
        'decision_kinds': decision_kinds,
        'chosen_order': chosen_order,
        'resolution_order': resolution_order,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_sp_001_damage_scenario(
    definition, card_snapshot, owner, *, source_zone='lumen', phase='battle',
    charge=True, event_owner='self', event_character='route',
    event_type_name='공격', event_type='use',
):
    engine, _source, event_card, _fighting = _awl_sp_001_engine(
        definition, card_snapshot, owner,
        ability_ids=['awl-sp-001-charge-damage'], source_zone=source_zone,
        phase=phase, charge=charge, event_owner=event_owner,
        event_character=event_character, event_type_name=event_type_name,
    )
    event_controller = owner if event_owner == 'self' else (
        'p2' if owner == 'p1' else 'p1'
    )
    live_event = engine._find_card(event_card['instance_id'])
    engine._fire(event_type, {
        'controller': event_controller,
        'source_card_instance_id': event_card['instance_id'],
        'source_card': copy.deepcopy(live_event),
    })
    live_event = engine._find_card(event_card['instance_id'])
    final_damage = engine.card_stat(live_event, 'damage', event_controller)
    target = 'p2' if event_controller == 'p1' else 'p1'
    hp_before = int(engine.state['players'][target]['hp'])
    actual_damage = engine.deal_damage(
        target, final_damage, source='battle',
    )
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-sp-001-charge-damage' for event in engine.events
        ),
        'final_damage': final_damage, 'actual_damage': actual_damage,
        'hp_loss': hp_before - int(engine.state['players'][target]['hp']),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_awl_sp_001_lost_scenario(
    definition, card_snapshot, owner, *, source_zone='lumen',
    state_owner='self', state_key='charge', initially_active=True,
    regain_source=None, refresh_occurrences=None,
):
    engine, _source, _event_card, _fighting = _awl_sp_001_engine(
        definition, card_snapshot, owner,
        ability_ids=['awl-sp-001-charge-lost'], source_zone=source_zone,
        phase='recovery', charge=(initially_active and state_owner == 'self'),
    )
    other = 'p2' if owner == 'p1' else 'p1'
    affected = owner if state_owner == 'self' else other
    if initially_active and affected != owner:
        engine.state['players'][affected]['passive_state'][state_key] = {
            'value': True, 'label': state_key,
        }
    elif initially_active and state_key != 'charge':
        engine.state['players'][affected]['passive_state'].pop('charge', None)
        engine.state['players'][affected]['passive_state'][state_key] = {
            'value': True, 'label': state_key,
        }
    hp_before = int(engine.state['players'][owner]['hp'])
    refresh_remaining = []
    if refresh_occurrences is not None:
        root_astra = _card(
            'CRS-AT-024', owner, f'{owner}-root-astra-refresh',
        )
        engine.set_passive(
            owner, 'charge', value=True, source_card=root_astra,
            expires={
                'event': 'phase_end', 'phase': 'recovery',
                'occurrences': refresh_occurrences,
            },
        )
        for _index in range(refresh_occurrences):
            engine._expire_state_durations('phase_end', phase='recovery')
            entry = (
                engine.state['players'][owner].get('passive_state') or {}
            ).get('charge') or {}
            expiration = next(iter(
                engine.engine_state.get('state_expirations') or []
            ), {})
            refresh_remaining.append({
                'active': bool(entry.get('value')),
                'remaining': expiration.get('remaining'),
                'hp_loss': hp_before - int(engine.state['players'][owner]['hp']),
            })
    else:
        engine.set_passive(affected, state_key, value=False)

    regain_result = None
    if regain_source:
        regain_card = _card(
            'ST2-PS1' if regain_source == 'trait' else 'CRS-AT-024',
            owner, f'{owner}-{regain_source}-charge-source',
        )
        regain_card['type'] = '특성' if regain_source == 'trait' else '공격'
        regain_result = engine.set_passive(
            owner, 'charge', value=True, source_card=regain_card,
        )
    charge_entry = (
        engine.state['players'][owner].get('passive_state') or {}
    ).get('charge') or {}
    return {
        'resolved': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'awl-sp-001-charge-lost' for event in engine.events
        ),
        'hp_loss': hp_before - int(engine.state['players'][owner]['hp']),
        'charge_active': bool(charge_entry.get('value')),
        'regain_result': regain_result,
        'state_gain_prevented': sum(
            event.get('type') == 'state_gain_prevented'
            for event in engine.events
        ),
        'game_preventions': sum(
            item.get('op') == 'prevent'
            and item.get('kind') == 'state_gain'
            and item.get('duration') == 'game'
            for item in engine.engine_state.get('replacements') or []
        ),
        'refresh_remaining': refresh_remaining,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_awl_sp_001_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'AWL-SP-001':
        return None
    qna_ids = [162, 164, 376, 378, 509]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    deploy = by_id.get('awl-sp-001-deploy')
    damage = by_id.get('awl-sp-001-charge-damage')
    lost = by_id.get('awl-sp-001-charge-lost')
    deploy_effects = [{
        'op': 'move_card',
        'card_instance_id': {'path': 'context.source_card_instance_id'},
        'to_zone': 'lumen',
    }]
    damage_condition = {
        'op': 'all', 'conditions': [
            {'op': 'phase_is', 'phase': 'battle'},
            {
                'op': 'has_state', 'player': {'controller': True},
                'state': 'charge',
            },
            {
                'op': 'equals', 'left': 'context.event_controller',
                'right': {'controller': True},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.event_card'},
                'where': {'character_key': 'route', 'type_contains': '공격'},
            },
        ],
    }
    lost_effects = [
        {
            'op': 'deal_damage', 'player': {'controller': True},
            'amount': 500,
        },
        {
            'op': 'prevent', 'kind': 'state_gain',
            'player': {'controller': True},
            'where': {'state': 'charge'},
            'against_where': {'code': 'ST2-PS1'},
            'duration': 'game',
        },
    ]
    valid = bool(
        not extra_root and len(abilities) == 3
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and deploy and deploy.get('kind') == 'effect'
        and deploy.get('mode') == 'optional'
        and deploy.get('timing') == 'function'
        and deploy.get('visibility') == 'private'
        and deploy.get('active_zones') == ['side']
        and deploy.get('trigger') == {'event': 'phase_start'}
        and deploy.get('condition') == {
            'op': 'all', 'conditions': [
                {'op': 'phase_is', 'phase': 'recovery'},
                {'op': 'lte', 'left': 'context.controller_hp', 'right': 1000},
            ],
        }
        and deploy.get('effects') == deploy_effects
        and damage and damage.get('kind') == 'effect'
        and damage.get('mode') == 'mandatory'
        and damage.get('timing') == 'use'
        and damage.get('active_zones') == ['lumen']
        and damage.get('trigger') == {'event': 'use'}
        and damage.get('condition') == damage_condition
        and damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'target_card': 'event_card', 'stat': 'damage', 'amount': 100,
            'duration': 'battle',
        }]
        and lost and lost.get('kind') == 'effect'
        and lost.get('mode') == 'mandatory'
        and lost.get('timing') == 'result'
        and lost.get('active_zones') == ['lumen']
        and lost.get('trigger') == {'event': 'state_lost'}
        and lost.get('condition') == {
            'op': 'all', 'conditions': [
                {'op': 'equals', 'left': 'context.state', 'right': 'charge'},
                {
                    'op': 'equals', 'left': 'context.player',
                    'right': {'controller': True},
                },
            ],
        }
        and lost.get('effects') == lost_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'awl-sp-001', False,
                reason='리커버리 배치·루트 공격 보정·차지 해제 후 금지 정의가 일치하지 않습니다.',
            )],
            'AWL-SP-001 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    deploy_scenarios = []
    deploy_specs = (
        {
            'name': 'owner-p1-threshold-accepts', 'owner': 'p1',
            'expected_zone': 'lumen', 'expected_order': ['awl-sp-001-deploy'],
        },
        {
            'name': 'owner-p2-threshold-declines', 'owner': 'p2',
            'accept': False, 'expected_zone': 'side', 'expected_order': [],
        },
        {
            'name': 'below-threshold-is-offered', 'owner': 'p1', 'hp': 500,
            'expected_zone': 'lumen', 'expected_order': ['awl-sp-001-deploy'],
        },
        {
            'name': 'above-threshold-is-not-offered', 'owner': 'p2', 'hp': 1001,
            'expected_zone': 'side', 'expected_order': [],
        },
        {
            'name': 'wrong-phase-is-not-offered', 'owner': 'p1', 'phase': 'lumen',
            'expected_zone': 'side', 'expected_order': [],
        },
        {
            'name': 'wrong-zone-is-not-offered', 'owner': 'p2',
            'source_zone': 'break', 'expected_zone': 'break',
            'expected_order': [],
        },
        {
            'name': 'qna-378-all-in-charge-can-resolve-before-fighting-spirit',
            'owner': 'p1', 'with_fighting_spirit': True,
            'first_ability_id': 'awl-sp-001-deploy',
            'expected_zone': 'lumen', 'expected_fighting_zone': 'lumen',
            'expected_first': 'awl-sp-001-deploy',
            'expected_order': [
                'awl-sp-001-deploy', 'review-fighting-spirit-deploy',
            ],
        },
        {
            'name': 'qna-378-fighting-spirit-can-resolve-before-all-in-charge',
            'owner': 'p2', 'with_fighting_spirit': True,
            'first_ability_id': 'review-fighting-spirit-deploy',
            'expected_zone': 'lumen', 'expected_fighting_zone': 'lumen',
            'expected_first': 'review-fighting-spirit-deploy',
            'expected_order': [
                'review-fighting-spirit-deploy', 'awl-sp-001-deploy',
            ],
        },
    )
    for spec in deploy_specs:
        expected_keys = {
            'name', 'expected_zone', 'expected_fighting_zone',
            'expected_first', 'expected_order',
        }
        kwargs = {key: value for key, value in spec.items() if key not in expected_keys}
        owner = kwargs.pop('owner')
        first = _run_awl_sp_001_deploy_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_sp_001_deploy_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_fighting = spec.get('expected_fighting_zone')
        deploy_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['source_zone'] == spec['expected_zone']
                and first['resolution_order'] == spec['expected_order']
                and (
                    expected_fighting is None
                    or first['fighting_spirit_zone'] == expected_fighting
                )
                and (
                    spec.get('expected_first') is None
                    or first['chosen_order'][:1] == [spec['expected_first']]
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    damage_scenarios = []
    damage_specs = (
        {
            'name': 'owner-p1-route-attack-gains-one-hundred', 'owner': 'p1',
            'expected_resolved': True, 'expected_damage': 500,
        },
        {
            'name': 'owner-p2-route-attack-gains-one-hundred', 'owner': 'p2',
            'expected_resolved': True, 'expected_damage': 500,
        },
        {
            'name': 'non-route-attack-does-not-gain-damage', 'owner': 'p1',
            'event_character': 'nya', 'expected_resolved': False,
            'expected_damage': 400,
        },
        {
            'name': 'route-defense-does-not-gain-damage', 'owner': 'p2',
            'event_type_name': '수비', 'expected_resolved': False,
            'expected_damage': 400,
        },
        {
            'name': 'without-charge-does-not-gain-damage', 'owner': 'p1',
            'charge': False, 'expected_resolved': False,
            'expected_damage': 400,
        },
        {
            'name': 'source-outside-lumen-is-inactive', 'owner': 'p2',
            'source_zone': 'side', 'expected_resolved': False,
            'expected_damage': 400,
        },
        {
            'name': 'outside-battle-phase-is-inactive', 'owner': 'p1',
            'phase': 'recovery', 'expected_resolved': False,
            'expected_damage': 400,
        },
        {
            'name': 'opponent-route-attack-is-not-modified', 'owner': 'p2',
            'event_owner': 'opponent', 'expected_resolved': False,
            'expected_damage': 400,
        },
    )
    for spec in damage_specs:
        expected_keys = {'name', 'expected_resolved', 'expected_damage'}
        kwargs = {key: value for key, value in spec.items() if key not in expected_keys}
        owner = kwargs.pop('owner')
        first = _run_awl_sp_001_damage_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_sp_001_damage_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is spec['expected_resolved']
                and first['final_damage'] == spec['expected_damage']
                and first['actual_damage'] == spec['expected_damage']
                and first['hp_loss'] == spec['expected_damage']
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    lost_scenarios = []
    lost_specs = (
        {
            'name': 'owner-p1-loses-charge-takes-five-hundred-and-blocks-trait',
            'owner': 'p1', 'regain_source': 'trait',
            'expected_resolved': 1, 'expected_loss': 500,
            'expected_active': False, 'expected_regain': False,
            'expected_prevented': 1, 'expected_preventions': 1,
        },
        {
            'name': 'owner-p2-loses-charge-takes-five-hundred-and-blocks-trait',
            'owner': 'p2', 'regain_source': 'trait',
            'expected_resolved': 1, 'expected_loss': 500,
            'expected_active': False, 'expected_regain': False,
            'expected_prevented': 1, 'expected_preventions': 1,
        },
        {
            'name': 'other-card-can-still-grant-charge-after-penalty',
            'owner': 'p1', 'regain_source': 'external',
            'expected_resolved': 1, 'expected_loss': 500,
            'expected_active': True, 'expected_regain': True,
            'expected_prevented': 0, 'expected_preventions': 1,
        },
        {
            'name': 'source-outside-lumen-does-not-apply-penalty',
            'owner': 'p2', 'source_zone': 'side', 'regain_source': 'trait',
            'expected_resolved': 0, 'expected_loss': 0,
            'expected_active': True, 'expected_regain': True,
            'expected_prevented': 0, 'expected_preventions': 0,
        },
        {
            'name': 'opponent-charge-loss-does-not-apply-owner-penalty',
            'owner': 'p1', 'state_owner': 'opponent',
            'expected_resolved': 0, 'expected_loss': 0,
            'expected_active': False, 'expected_regain': None,
            'expected_prevented': 0, 'expected_preventions': 0,
        },
        {
            'name': 'different-state-loss-does-not-trigger',
            'owner': 'p2', 'state_key': 'intimidation',
            'expected_resolved': 0, 'expected_loss': 0,
            'expected_active': False, 'expected_regain': None,
            'expected_prevented': 0, 'expected_preventions': 0,
        },
        {
            'name': 'inactive-charge-does-not-emit-loss',
            'owner': 'p1', 'initially_active': False,
            'expected_resolved': 0, 'expected_loss': 0,
            'expected_active': False, 'expected_regain': None,
            'expected_prevented': 0, 'expected_preventions': 0,
        },
        {
            'name': 'qna-509-root-astra-refresh-delays-one-penalty',
            'owner': 'p2', 'refresh_occurrences': 2,
            'expected_resolved': 1, 'expected_loss': 500,
            'expected_active': False, 'expected_regain': None,
            'expected_prevented': 0, 'expected_preventions': 1,
            'expected_refresh': [
                {'active': True, 'remaining': 1, 'hp_loss': 0},
                {'active': False, 'remaining': None, 'hp_loss': 500},
            ],
        },
    )
    for spec in lost_specs:
        expected_keys = {
            'name', 'expected_resolved', 'expected_loss', 'expected_active',
            'expected_regain', 'expected_prevented', 'expected_preventions',
            'expected_refresh',
        }
        kwargs = {key: value for key, value in spec.items() if key not in expected_keys}
        owner = kwargs.pop('owner')
        first = _run_awl_sp_001_lost_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_awl_sp_001_lost_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        lost_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] == spec['expected_resolved']
                and first['hp_loss'] == spec['expected_loss']
                and first['charge_active'] is spec['expected_active']
                and first['regain_result'] is spec['expected_regain']
                and first['state_gain_prevented'] == spec['expected_prevented']
                and first['game_preventions'] == spec['expected_preventions']
                and first['refresh_remaining'] == spec.get('expected_refresh', [])
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            deploy['id'], all(item['passed'] for item in deploy_scenarios),
            deploy_scenarios,
            '' if all(item['passed'] for item in deploy_scenarios)
            else '리커버리 HP 경계·선택·동시 유발 순서 검증에 실패했습니다.',
        ),
        AbilityReview(
            damage['id'], all(item['passed'] for item in damage_scenarios),
            damage_scenarios,
            '' if all(item['passed'] for item in damage_scenarios)
            else '차지·루트 공격·사용 주체 데미지 보정 검증에 실패했습니다.',
        ),
        AbilityReview(
            lost['id'], all(item['passed'] for item in lost_scenarios),
            lost_scenarios,
            '' if all(item['passed'] for item in lost_scenarios)
            else '차지 해제 피해·갱신·특성 재진입 금지 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '올 인 차지의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _unc_at_041_source(card_snapshot, owner, suffix, *, source_zone='battle'):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-lenore-knock-{suffix}',
        'kind': 'card', 'owner': owner, 'code': 'UNC-AT-041',
        'name': '레노어 노크', 'type': '공격', 'character_key': 'reve',
        'frame': 8, 'damage': 400, 'pos': '하단', 'body': '',
        'special': '하단 상쇄', 'hit': '4', 'guard': '-4',
        'counter': '3', 'face_up': source_zone == 'battle',
    })
    return source


def _run_unc_at_041_dark_night_scenario(
    definition, ability, card_snapshot, owner, *, event_type='clash',
    dark_night=True, source_zone='battle', numbered_effects_negated=False,
    opponent_damage=600, existing_modifier=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_041_source(
        card_snapshot, owner, 'dark-night', source_zone=source_zone,
    )
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-LENORE-KNOCK-OPPONENT', other,
        f'{other}-lenore-knock-opponent',
    )
    opposing.update({
        'type': '공격', 'frame': 7, 'damage': opponent_damage,
        'pos': '하단', 'body': '손', 'special': '', 'face_up': True,
    })
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    no_effect = _st1_001_no_effect_definition()
    state = _state(source, opposing, owner, source_zone=source_zone)
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'lenore-knock-dark-night:{owner}:{event_type}:{dark_night}:'
            f'{source_zone}:{numbered_effects_negated}:{opponent_damage}:'
            f'{existing_modifier}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    if existing_modifier:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': other, 'player': other,
            'source': f'{other}-lenore-knock-existing-modifier',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'damage', 'amount': existing_modifier,
            'duration': 'battle',
        })
    before_damage = engine.card_stat(
        live_opposing, 'damage', other, include_fp=False,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(live_opposing),
        'source_only_event': True,
    })
    after_damage = engine.card_stat(
        live_opposing, 'damage', other, include_fp=False,
    )
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == ability.get('id') for event in engine.events
        ),
        'before_damage': before_damage, 'after_damage': after_damage,
        'modifier_count': sum(
            item.get('stat') == 'damage'
            and item.get('where') == {'instance_id': opposing['instance_id']}
            for item in engine.engine_state.get('modifiers') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_unc_at_041_combined_scenario(
    definition, card_snapshot, owner, *, first_ability_id,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_041_source(card_snapshot, owner, 'combined')
    opposing = _card(
        'REVIEW-LENORE-KNOCK-COMBINED-OPPONENT', other,
        f'{other}-lenore-knock-combined-opponent',
    )
    opposing.update({
        'type': '공격', 'frame': 7, 'damage': 600,
        'pos': '하단', 'body': '손', 'special': '', 'face_up': True,
    })
    state = _state(source, opposing, owner)
    state['players'][owner]['passive_state']['dark_night'] = {
        'value': True, 'label': '암야',
    }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': no_effect,
                },
            },
        },
        seed=f'lenore-knock-combined:{owner}:{first_ability_id}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    hp_before = int(engine.state['players'][other]['hp'])
    engine._fire('clash', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(live_opposing),
        'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    option_ids = {
        item.get('ability_id'): item.get('id')
        for item in (decision or {}).get('options') or []
    }
    if decision and first_ability_id in option_ids:
        engine._submit_decision(
            owner, decision.get('id'), [option_ids[first_ability_id]],
        )
        engine._continue()
    resolution_order = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') in {
            'unc-at-041-n1', 'unc-at-041-n2',
        }
    ]
    return {
        'decision_kind': (decision or {}).get('kind'),
        'option_abilities': sorted(option_ids),
        'resolution_order': resolution_order,
        'effect_damage': hp_before - int(engine.state['players'][other]['hp']),
        'opponent_damage': engine.card_stat(
            live_opposing, 'damage', other, include_fp=False,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_unc_at_041_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-041':
        return None
    qna_ids = [190, 575]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    damage = by_id.get('unc-at-041-n1')
    dark_night = by_id.get('unc-at-041-n2')
    valid = bool(
        not extra_root and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and damage and damage.get('kind') == 'effect'
        and damage.get('mode') == 'mandatory'
        and damage.get('timing') == 'clash'
        and damage.get('active_zones') == ['battle']
        and damage.get('trigger') == {'event': 'clash'}
        and not damage.get('condition')
        and damage.get('effects') == [{
            'op': 'deal_damage', 'player': {'opponent': True},
            'amount': 100,
        }]
        and dark_night and dark_night.get('kind') == 'effect'
        and dark_night.get('mode') == 'mandatory'
        and dark_night.get('timing') == 'clash'
        and dark_night.get('active_zones') == ['battle']
        and dark_night.get('trigger') == {'event': 'clash'}
        and dark_night.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'dark_night',
        }
        and dark_night.get('effects') == [{
            'op': 'modify_stat', 'player': {'opponent': True},
            'stat': 'damage', 'amount': -100, 'duration': 'battle',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'unc-at-041', False,
                reason='상쇄 효과 피해와 암야 상대 기술 데미지 감소 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-041 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    damage_scenarios = []
    for name, owner, event_type, listener, lethal, expected in (
        ('owner-p1-clash-deals-one-hundred', 'p1', 'clash', False, False, True),
        ('owner-p2-clash-deals-one-hundred', 'p2', 'clash', False, False, True),
        ('qna-190-effect-damage-triggers-dark-night', 'p1', 'clash', True, False, True),
        ('qna-575-lethal-effect-wins-without-sudden-death', 'p2', 'clash', False, True, True),
        ('wrong-trigger-does-not-deal-damage', 'p1', 'hit', False, False, False),
    ):
        first = _run_awl_at_050_effect_scenario(
            definition, damage, card_snapshot, owner, event_type,
            dark_night_listener=listener, lethal=lethal,
        )
        second = _run_awl_at_050_effect_scenario(
            definition, damage, card_snapshot, owner, event_type,
            dark_night_listener=listener, lethal=lethal,
        )
        deterministic = _canonical(first) == _canonical(second)
        outcome_ok = bool(
            first['resolved'] is expected
            and first['damage'] == (100 if expected else 0)
            and first['damage_amounts'] == ([100] if expected else [])
        )
        if listener:
            outcome_ok = outcome_ok and first['dark_night']
        if lethal:
            outcome_ok = bool(
                outcome_ok and first['status'] == 'finished'
                and first['winner'] == owner and first['reason'] == 'hp_zero'
                and not first['sudden_death']
            )
        damage_scenarios.append({
            'name': name, 'passed': bool(deterministic and outcome_ok),
            'deterministic': deterministic, 'dark_night_listener': listener,
            'lethal': lethal, 'expected_resolution': expected, **first,
        })

    dark_scenarios = []
    dark_specs = (
        {
            'name': 'owner-p1-dark-night-reduces-opponent-damage',
            'owner': 'p1', 'expected': True, 'before': 600, 'after': 500,
            'modifiers': 1,
        },
        {
            'name': 'owner-p2-dark-night-reduces-opponent-damage',
            'owner': 'p2', 'expected': True, 'before': 600, 'after': 500,
            'modifiers': 1,
        },
        {
            'name': 'without-dark-night-does-not-reduce', 'owner': 'p1',
            'dark_night': False, 'expected': False, 'before': 600,
            'after': 600, 'modifiers': 0,
        },
        {
            'name': 'wrong-trigger-does-not-reduce', 'owner': 'p2',
            'event_type': 'hit', 'expected': False, 'before': 600,
            'after': 600, 'modifiers': 0,
        },
        {
            'name': 'source-outside-battle-does-not-reduce', 'owner': 'p1',
            'source_zone': 'hand', 'expected': False, 'before': 600,
            'after': 600, 'modifiers': 0,
        },
        {
            'name': 'numbered-negation-does-not-reduce', 'owner': 'p2',
            'numbered_effects_negated': True, 'expected': False,
            'before': 600, 'after': 600, 'modifiers': 0,
        },
        {
            'name': 'existing-plus-two-hundred-then-minus-one-hundred',
            'owner': 'p1', 'existing_modifier': 200,
            'expected': True, 'before': 800, 'after': 700,
            'modifiers': 2,
        },
    )
    for spec in dark_specs:
        expected_keys = {'name', 'expected', 'before', 'after', 'modifiers'}
        kwargs = {key: value for key, value in spec.items() if key not in expected_keys}
        owner = kwargs.pop('owner')
        first = _run_unc_at_041_dark_night_scenario(
            definition, dark_night, card_snapshot, owner, **kwargs,
        )
        second = _run_unc_at_041_dark_night_scenario(
            definition, dark_night, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        dark_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic and first['resolved'] is spec['expected']
                and first['before_damage'] == spec['before']
                and first['after_damage'] == spec['after']
                and first['modifier_count'] == spec['modifiers']
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    for owner, first_ability_id in (
        ('p1', 'unc-at-041-n1'), ('p2', 'unc-at-041-n2'),
    ):
        first = _run_unc_at_041_combined_scenario(
            definition, card_snapshot, owner,
            first_ability_id=first_ability_id,
        )
        second = _run_unc_at_041_combined_scenario(
            definition, card_snapshot, owner,
            first_ability_id=first_ability_id,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_order = [
            first_ability_id,
            'unc-at-041-n2' if first_ability_id == 'unc-at-041-n1'
            else 'unc-at-041-n1',
        ]
        dark_scenarios.append({
            'name': f'{owner}-chooses-{first_ability_id}-first',
            'passed': bool(
                deterministic and first['decision_kind'] == 'effect_order'
                and first['option_abilities']
                == ['unc-at-041-n1', 'unc-at-041-n2']
                and first['resolution_order'] == expected_order
                and first['effect_damage'] == 100
                and first['opponent_damage'] == 500
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            damage['id'], all(item['passed'] for item in damage_scenarios),
            damage_scenarios,
            '' if all(item['passed'] for item in damage_scenarios)
            else '상쇄 효과 피해·암야 유발·치명 승패 검증에 실패했습니다.',
        ),
        AbilityReview(
            dark_night['id'], all(item['passed'] for item in dark_scenarios),
            dark_scenarios,
            '' if all(item['passed'] for item in dark_scenarios)
            else '암야 상태·영역·동시 해결 상대 데미지 감소 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '레노어 노크의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


