def _run_unc_at_042_effect_scenario(
    definition, ability, card_snapshot, owner, *, event_type='clash',
    dark_night=False, source_zone='battle', numbered_effects_negated=False,
    source_hit='5', opponent_hit='3', opponent_damage=600,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_042_source(
        card_snapshot, owner, 'direct', source_zone=source_zone,
    )
    source['hit'] = source_hit
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-MIDNIGHT-OPPONENT', other,
        f'{other}-midnight-opponent',
    )
    opposing.update({
        'type': '공격', 'frame': 9, 'damage': opponent_damage,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': opponent_hit, 'counter': '+2', 'face_up': True,
    })
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    state = _state(source, opposing, owner, source_zone=source_zone)
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': _st1_001_no_effect_definition(),
                },
            },
        },
        seed=(
            f'midnight-direct:{ability.get("id")}:{owner}:{event_type}:'
            f'{dark_night}:{source_zone}:{numbered_effects_negated}:'
            f'{source_hit}:{opponent_hit}:{opponent_damage}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    source_battle = engine.engine_state['battle'][owner]['card']
    opposing_battle = engine.engine_state['battle'][other]['card']
    before_damage = engine.card_stat(
        opposing_battle, 'damage', other, include_fp=False,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source_battle),
        'opponent_card': copy.deepcopy(opposing_battle),
        'source_only_event': True,
    })
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == ability.get('id') for event in engine.events
        ),
        'source_hit': source_battle.get('hit'),
        'opponent_hit': opposing_battle.get('hit'),
        'opponent_damage_before': before_damage,
        'opponent_damage_after': engine.card_stat(
            opposing_battle, 'damage', other, include_fp=False,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_unc_at_042_combined_scenario(
    definition, card_snapshot, owner, *, dark_night,
    preferred_order,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_042_source(card_snapshot, owner, 'combined')
    opposing = _card(
        'REVIEW-MIDNIGHT-COMBINED-OPPONENT', other,
        f'{other}-midnight-combined-opponent',
    )
    opposing.update({
        'type': '공격', 'frame': 9, 'damage': 600,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': '콤보', 'counter': '+2', 'face_up': True,
    })
    state = _state(source, opposing, owner)
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': _st1_001_no_effect_definition(),
                },
            },
        },
        seed=f'midnight-combined:{owner}:{dark_night}:{preferred_order}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    engine._fire('clash', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(
            engine.engine_state['battle'][owner]['card'],
        ),
        'opponent_card': copy.deepcopy(
            engine.engine_state['battle'][other]['card'],
        ),
        'source_only_event': True,
    })
    decisions = []
    preferred = list(preferred_order)
    for _step in range(5):
        decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if not decision:
            break
        option_ids = {
            option.get('ability_id'): option.get('id')
            for option in decision.get('options') or []
        }
        decisions.append({
            'kind': decision.get('kind'),
            'abilities': sorted(option_ids),
        })
        selected_ability = next((
            ability_id for ability_id in preferred
            if ability_id in option_ids
        ), None)
        if selected_ability is None and option_ids:
            selected_ability = sorted(option_ids)[0]
        if decision.get('kind') != 'effect_order' or selected_ability is None:
            break
        preferred = [
            ability_id for ability_id in preferred
            if ability_id != selected_ability
        ]
        engine._submit_decision(
            owner, decision.get('id'), [option_ids[selected_ability]],
        )
        engine._continue()
    source_battle = engine.engine_state['battle'][owner]['card']
    opposing_battle = engine.engine_state['battle'][other]['card']
    resolution_order = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') in {
            'unc-at-042-n1', 'unc-at-042-n2', 'unc-at-042-n3',
        }
    ]
    return {
        'decisions': decisions, 'resolution_order': resolution_order,
        'source_hit': source_battle.get('hit'),
        'opponent_hit': opposing_battle.get('hit'),
        'opponent_damage': engine.card_stat(
            opposing_battle, 'damage', other, include_fp=False,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_unc_at_042_qna_250_scenario(definition, card_snapshot, owner):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_042_source(card_snapshot, owner, 'qna-250')
    opposing = _card(
        'REVIEW-MIDNIGHT-ZERO-DAMAGE', other,
        f'{other}-midnight-zero-damage',
    )
    opposing.update({
        'type': '공격', 'frame': 9, 'damage': 200,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': '3', 'counter': '3', 'face_up': False,
    })
    state = _state(source, opposing, owner)
    state['phase'] = 'battle'
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': _st1_001_no_effect_definition(),
                },
            },
        },
        seed=f'midnight-qna-250:{owner}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['ready_cards'] = {
        owner: source['instance_id'], other: opposing['instance_id'],
    }
    pipeline = {'kind': 'battle', 'stage': 'start'}
    engine.engine_state['pipeline'] = pipeline
    decision_kinds = []
    for _step in range(80):
        decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if decision:
            decision_kinds.append(decision.get('kind'))
            options = decision.get('options') or []
            if decision.get('kind') != 'effect_order' or not options:
                break
            option = sorted(
                options, key=lambda item: str(item.get('ability_id') or '')
            )[0]
            engine._submit_decision(owner, decision.get('id'), [option['id']])
            continue
        if pipeline.get('stage') == 'after_judgment':
            break
        engine._advance_battle_pipeline(pipeline)
    battle = engine.engine_state.get('battle') or {}
    return {
        'stage': pipeline.get('stage'),
        'result': copy.deepcopy(battle.get('result')),
        'owner_fp': int(engine.state['players'][owner]['fp']),
        'opponent_fp': int(engine.state['players'][other]['fp']),
        'owner_hp_loss': 4000 - int(engine.state['players'][owner]['hp']),
        'opponent_hp_loss': 4000 - int(
            engine.state['players'][other]['hp']
        ),
        'source_hit': (battle.get(owner) or {}).get('card', {}).get('hit'),
        'opponent_damage': engine.card_stat(
            (battle.get(other) or {}).get('card'),
            'damage', other, include_fp=False,
        ),
        'decision_kinds': decision_kinds,
        'damage_events': [
            (event.get('payload') or {}).get('amount')
            for event in engine.events if event.get('type') == 'damage_dealt'
        ],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_unc_at_042_qna_406_scenario(
    definition, card_snapshot, owner, *, action,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_042_source(card_snapshot, owner, 'qna-406')
    opposing = _card(
        'REVIEW-MIDNIGHT-EFFECT-CATCH-SOURCE', other,
        f'{other}-midnight-effect-catch-source',
    )
    catch_card = _card(
        'REVIEW-MIDNIGHT-EFFECT-CATCH-CARD', other,
        f'{other}-midnight-effect-catch-card',
    )
    catch_card.update({'frame': 8, 'damage': 400, 'face_up': False})
    state = _state(source, opposing, owner)
    state['players'][owner]['fp'] = 7
    state['players'][other]['fp'] = 0
    state['players'][other]['zones']['hand'] = [copy.deepcopy(catch_card)]
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
                catch_card['code']: {
                    **copy.deepcopy(catch_card), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'midnight-qna-406:{owner}:{action}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': engine._find_card(source['instance_id']),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': engine._find_card(opposing['instance_id']),
        },
    }
    engine.engine_state['granted_catches'] = [{
        'owner': other, 'source': opposing['instance_id'],
        'allow_zones': ['hand'], 'max_speed': 9,
    }]
    engine._open_catch_or_cleanup()
    first_catch = copy.deepcopy(engine.engine_state.get('catch') or {})
    if action == 'play':
        engine._play_catch(other, catch_card['instance_id'])
    elif action == 'decline':
        engine.end_catch()
    after_catch = copy.deepcopy(engine.engine_state.get('catch') or {})
    return {
        'first_owner': first_catch.get('owner'),
        'first_source': first_catch.get('source'),
        'after_owner': after_catch.get('owner'),
        'after_source': after_catch.get('source'),
        'owner_fp': int(engine.state['players'][owner]['fp']),
        'opponent_fp': int(engine.state['players'][other]['fp']),
        'catch_card_zone': engine._find_location(catch_card['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_unc_at_042_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-042':
        return None
    qna_ids = [250, 406]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    own_hit = by_id.get('unc-at-042-n1')
    damage = by_id.get('unc-at-042-n2')
    dark_hit = by_id.get('unc-at-042-n3')
    common = lambda ability: bool(
        ability and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('timing') == 'clash'
        and ability.get('active_zones') == ['battle']
        and ability.get('trigger') == {'event': 'clash'}
    )
    valid = bool(
        not extra_root and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and common(own_hit) and not own_hit.get('condition')
        and own_hit.get('effects') == [{
            'op': 'modify_judgment', 'player': {'controller': True},
            'field': 'hit', 'value': '+7',
        }]
        and common(damage) and not damage.get('condition')
        and damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'opponent': True},
            'stat': 'damage', 'amount': -200, 'duration': 'battle',
        }]
        and common(dark_hit)
        and dark_hit.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'dark_night',
        }
        and dark_hit.get('effects') == [{
            'op': 'modify_judgment', 'player': {'opponent': True},
            'field': 'hit', 'value': '+0',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'unc-at-042', False,
                reason='상쇄 판정·상대 데미지·암야 판정 변경 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-042 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    own_hit_scenarios = []
    for name, owner, kwargs, expected, resolves in (
        ('owner-p1-clash-changes-five-to-plus-seven', 'p1', {}, '+7', True),
        ('owner-p2-clash-replaces-combo-with-plus-seven', 'p2', {'source_hit': '콤보'}, '+7', True),
        ('wrong-trigger-keeps-printed-hit', 'p1', {'event_type': 'hit'}, '5', False),
        ('source-outside-battle-does-not-change-hit', 'p2', {'source_zone': 'hand'}, '5', False),
        ('numbered-negation-keeps-printed-hit', 'p1', {'numbered_effects_negated': True}, '5', False),
    ):
        first = _run_unc_at_042_effect_scenario(
            definition, own_hit, card_snapshot, owner, **kwargs,
        )
        second = _run_unc_at_042_effect_scenario(
            definition, own_hit, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        own_hit_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is resolves
                and first['source_hit'] == expected and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': resolves, 'expected_hit': expected,
            **first,
        })

    damage_scenarios = []
    for name, owner, kwargs, expected, resolves in (
        ('owner-p1-clash-reduces-six-hundred-to-four-hundred', 'p1', {}, 400, True),
        ('owner-p2-clash-reduces-two-hundred-to-zero', 'p2', {'opponent_damage': 200}, 0, True),
        ('wrong-trigger-does-not-reduce', 'p1', {'event_type': 'guard'}, 600, False),
        ('source-outside-battle-does-not-reduce', 'p2', {'source_zone': 'hand'}, 600, False),
        ('numbered-negation-does-not-reduce', 'p1', {'numbered_effects_negated': True}, 600, False),
    ):
        first = _run_unc_at_042_effect_scenario(
            definition, damage, card_snapshot, owner, **kwargs,
        )
        second = _run_unc_at_042_effect_scenario(
            definition, damage, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is resolves
                and first['opponent_damage_after'] == expected
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': resolves,
            'expected_opponent_damage': expected, **first,
        })
    for owner in ('p1', 'p2'):
        first = _run_unc_at_042_qna_250_scenario(
            definition, card_snapshot, owner,
        )
        second = _run_unc_at_042_qna_250_scenario(
            definition, card_snapshot, owner,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': f'qna-250-{owner}-zero-damage-still-applies-hit-fp',
            'passed': bool(
                deterministic and first['stage'] == 'after_judgment'
                and first['result'] == {'p1': 'clash', 'p2': 'clash'}
                and first['owner_fp'] == 7 and first['opponent_fp'] == 3
                and first['owner_hp_loss'] == 0
                and first['opponent_hp_loss'] == 600
                and first['source_hit'] == '+7'
                and first['opponent_damage'] == 0
                and first['damage_events'] == [600]
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    dark_scenarios = []
    for name, owner, kwargs, expected, resolves in (
        ('owner-p1-dark-night-changes-combo-to-plus-zero', 'p1', {'dark_night': True, 'opponent_hit': '콤보'}, '+0', True),
        ('owner-p2-dark-night-changes-minus-five-to-plus-zero', 'p2', {'dark_night': True, 'opponent_hit': '-5'}, '+0', True),
        ('without-dark-night-keeps-opponent-hit', 'p1', {'opponent_hit': '콤보'}, '콤보', False),
        ('wrong-trigger-does-not-change-opponent-hit', 'p2', {'event_type': 'counter', 'dark_night': True, 'opponent_hit': '-5'}, '-5', False),
        ('source-outside-battle-does-not-change-opponent-hit', 'p1', {'source_zone': 'list', 'dark_night': True, 'opponent_hit': '콤보'}, '콤보', False),
        ('numbered-negation-keeps-opponent-hit', 'p2', {'dark_night': True, 'numbered_effects_negated': True, 'opponent_hit': '-5'}, '-5', False),
    ):
        first = _run_unc_at_042_effect_scenario(
            definition, dark_hit, card_snapshot, owner, **kwargs,
        )
        second = _run_unc_at_042_effect_scenario(
            definition, dark_hit, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        dark_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is resolves
                and first['opponent_hit'] == expected and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': resolves, 'expected_hit': expected,
            **first,
        })
    for owner, dark_night, order in (
        ('p1', False, ('unc-at-042-n2', 'unc-at-042-n1')),
        ('p2', True, ('unc-at-042-n3', 'unc-at-042-n1', 'unc-at-042-n2')),
    ):
        first = _run_unc_at_042_combined_scenario(
            definition, card_snapshot, owner,
            dark_night=dark_night, preferred_order=order,
        )
        second = _run_unc_at_042_combined_scenario(
            definition, card_snapshot, owner,
            dark_night=dark_night, preferred_order=order,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_ids = {
            'unc-at-042-n1', 'unc-at-042-n2',
            *({'unc-at-042-n3'} if dark_night else set()),
        }
        dark_scenarios.append({
            'name': f'{owner}-same-timing-effects-resolve-in-selected-order',
            'passed': bool(
                deterministic
                and set(first['resolution_order']) == expected_ids
                and first['resolution_order'][0] == order[0]
                and first['source_hit'] == '+7'
                and first['opponent_hit'] == ('+0' if dark_night else '콤보')
                and first['opponent_damage'] == 400
                and first['decisions']
                and all(
                    item['kind'] == 'effect_order'
                    for item in first['decisions']
                )
                and not first['pending']
            ),
            'deterministic': deterministic, 'dark_night': dark_night,
            **first,
        })

    catch_scenarios = []
    for name, owner, action, expected in (
        ('qna-406-effect-catch-is-offered-before-owner-fp-catch', 'p1', 'observe', ('p2', 'p2-midnight-effect-catch-source', 'p2', 'p2-midnight-effect-catch-source', 7, 0, 'hand')),
        ('qna-406-playing-effect-catch-resets-fp-before-fp-catch', 'p2', 'play', ('p1', 'p1-midnight-effect-catch-source', 'p1', 'p1-midnight-effect-catch-source', 0, 0, 'battle')),
        ('qna-406-declining-effect-catch-skips-unusable-fp-catch', 'p1', 'decline', ('p2', 'p2-midnight-effect-catch-source', None, None, 7, 0, 'hand')),
    ):
        first = _run_unc_at_042_qna_406_scenario(
            definition, card_snapshot, owner, action=action,
        )
        second = _run_unc_at_042_qna_406_scenario(
            definition, card_snapshot, owner, action=action,
        )
        deterministic = _canonical(first) == _canonical(second)
        actual = (
            first['first_owner'], first['first_source'],
            first['after_owner'], first['after_source'],
            first['owner_fp'], first['opponent_fp'],
            first['catch_card_zone'],
        )
        catch_scenarios.append({
            'name': name, 'passed': bool(
                deterministic and actual == expected and not first['pending']
            ),
            'deterministic': deterministic, 'action': action,
            'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            own_hit['id'], all(item['passed'] for item in own_hit_scenarios),
            own_hit_scenarios,
            '' if all(item['passed'] for item in own_hit_scenarios)
            else '미드나잇의 상쇄 시 자체 히트 판정 변경 검증에 실패했습니다.',
        ),
        AbilityReview(
            damage['id'], all(item['passed'] for item in damage_scenarios),
            damage_scenarios,
            '' if all(item['passed'] for item in damage_scenarios)
            else '미드나잇의 상대 데미지 감소·0데미지 판정 검증에 실패했습니다.',
        ),
        AbilityReview(
            dark_hit['id'], all(item['passed'] for item in dark_scenarios),
            dark_scenarios,
            '' if all(item['passed'] for item in dark_scenarios)
            else '미드나잇의 암야 상대 히트 판정·동시 해결 검증에 실패했습니다.',
        ),
        AbilityReview(
            'unc-at-042-qna-406-catch-priority',
            all(item['passed'] for item in catch_scenarios), catch_scenarios,
            '' if all(item['passed'] for item in catch_scenarios)
            else 'Q&A 406의 효과 캐치 우선순위 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '미드나잇의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _unc_at_043_source(card_snapshot, owner, suffix, *, source_zone='battle'):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-la-nuit-blanche-{suffix}',
        'kind': 'card', 'owner': owner, 'code': 'UNC-AT-043',
        'name': '라 뉘 블랑쉬', 'type': '공격', 'character_key': 'reve',
        'frame': 11, 'damage': 700, 'pos': '중단', 'body': '',
        'special': '중단 상쇄', 'hit': '5', 'guard': '-8',
        'counter': '4', 'face_up': source_zone == 'battle',
    })
    return source


def _run_unc_at_043_effect_scenario(
    definition, ability, card_snapshot, owner, *, event_type='clash',
    dark_night=False, source_zone='battle', numbered_effects_negated=False,
    source_hit='5', opponent_hit='콤보', source_damage=700,
    opponent_damage=700, combo_number=2,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_043_source(
        card_snapshot, owner, 'direct', source_zone=source_zone,
    )
    source.update({'hit': source_hit, 'damage': source_damage})
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-LA-NUIT-BLANCHE-OPPONENT', other,
        f'{other}-la-nuit-blanche-opponent',
    )
    opposing.update({
        'type': '공격', 'frame': 9, 'damage': opponent_damage,
        'pos': '중단', 'body': '손', 'special': '',
        'hit': opponent_hit, 'counter': '+2', 'face_up': True,
    })
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(ability)]
    state = _state(source, opposing, owner, source_zone=source_zone)
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': _st1_001_no_effect_definition(),
                },
            },
        },
        seed=(
            f'la-nuit-blanche-direct:{ability.get("id")}:{owner}:'
            f'{event_type}:{dark_night}:{source_zone}:'
            f'{numbered_effects_negated}:{source_hit}:{opponent_hit}:'
            f'{source_damage}:{opponent_damage}:{combo_number}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    source_battle = engine.engine_state['battle'][owner]['card']
    opposing_battle = engine.engine_state['battle'][other]['card']
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source_battle),
        'opponent_card': copy.deepcopy(opposing_battle),
        'source_only_event': True,
        'combo': event_type == 'combo',
        'combo_number': combo_number,
    })
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == ability.get('id') for event in engine.events
        ),
        'source_hit': source_battle.get('hit'),
        'opponent_hit': opposing_battle.get('hit'),
        'source_damage': engine.card_stat(
            source_battle, 'damage', owner, include_fp=False,
        ),
        'opponent_damage': engine.card_stat(
            opposing_battle, 'damage', other, include_fp=False,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_unc_at_043_combined_scenario(
    definition, card_snapshot, owner, *, preferred_order,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_043_source(card_snapshot, owner, 'combined')
    opposing = _card(
        'REVIEW-LA-NUIT-BLANCHE-COMBINED', other,
        f'{other}-la-nuit-blanche-combined',
    )
    opposing.update({
        'type': '공격', 'frame': 9, 'damage': 700,
        'pos': '중단', 'body': '손', 'special': '',
        'hit': '콤보', 'counter': '+2', 'face_up': True,
    })
    state = _state(source, opposing, owner)
    state['players'][owner]['passive_state']['dark_night'] = {
        'value': True, 'label': '암야',
    }
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': _st1_001_no_effect_definition(),
                },
            },
        },
        seed=f'la-nuit-blanche-combined:{owner}:{preferred_order}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    engine._fire('clash', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(
            engine.engine_state['battle'][owner]['card'],
        ),
        'opponent_card': copy.deepcopy(
            engine.engine_state['battle'][other]['card'],
        ),
        'source_only_event': True,
    })
    decisions = []
    remaining_order = list(preferred_order)
    for _step in range(4):
        decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if not decision:
            break
        option_ids = {
            option.get('ability_id'): option.get('id')
            for option in decision.get('options') or []
        }
        decisions.append({
            'kind': decision.get('kind'),
            'abilities': sorted(option_ids),
        })
        selected_ability = next((
            ability_id for ability_id in remaining_order
            if ability_id in option_ids
        ), None)
        if decision.get('kind') != 'effect_order' or selected_ability is None:
            break
        remaining_order.remove(selected_ability)
        engine._submit_decision(
            owner, decision.get('id'), [option_ids[selected_ability]],
        )
        engine._continue()
    source_battle = engine.engine_state['battle'][owner]['card']
    opposing_battle = engine.engine_state['battle'][other]['card']
    resolution_order = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events
        if event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') in {
            'unc-at-043-n1', 'unc-at-043-n2',
        }
    ]
    return {
        'decisions': decisions, 'resolution_order': resolution_order,
        'source_hit': source_battle.get('hit'),
        'opponent_hit': opposing_battle.get('hit'),
        'opponent_damage': engine.card_stat(
            opposing_battle, 'damage', other, include_fp=False,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_unc_at_043_qna_237_scenario(
    definition, card_snapshot, owner, *, accept,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _unc_at_043_source(card_snapshot, owner, 'qna-237')
    opposing = _card(
        'REVIEW-QNA-237-BLADE-OF-SANCTUS', other,
        f'{other}-qna-237-blade',
    )
    opposing.update({
        'name': '블레이드 오브 상투스', 'type': '공격',
        'frame': 8, 'damage': 600, 'pos': '중단', 'body': '검',
        'special': '', 'hit': '5', 'counter': '+2', 'face_up': True,
    })
    source_definition = copy.deepcopy(definition)
    source_definition['abilities'] = [
        copy.deepcopy(next(
            ability for ability in definition.get('abilities') or []
            if ability.get('id') == 'unc-at-043-n1'
        )),
    ]
    blade_definition = {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [237]},
        'abilities': [{
            'id': 'review-qna-237-blade-paladin-hit',
            'label': '팔라딘: 히트 판정을 콤보로 변경',
            'kind': 'effect', 'mode': 'optional', 'timing': 'hit_counter',
            'visibility': 'public', 'active_zones': ['battle'],
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [237]},
            'trigger': {'event': 'hit'},
            'effects': [{
                'op': 'modify_judgment',
                'player': {'controller': True},
                'field': 'hit', 'value': '콤보',
            }],
        }],
    }
    engine = AutomaticGameEngine(
        _state(source, opposing, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': source_definition,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': blade_definition,
                },
            },
        },
        seed=f'la-nuit-blanche-qna-237:{owner}:{accept}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    source_battle = engine.engine_state['battle'][owner]['card']
    opposing_battle = engine.engine_state['battle'][other]['card']
    engine._fire('hit', {
        'controller': other,
        'source_card_instance_id': opposing['instance_id'],
        'source_card': copy.deepcopy(opposing_battle),
        'opponent_card': copy.deepcopy(source_battle),
        'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    if decision:
        engine._submit_decision(
            other, decision.get('id'), ['accept' if accept else 'decline'],
        )
        engine._continue()
    blade_hit_before_clash = opposing_battle.get('hit')
    engine._fire('clash', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source_battle),
        'opponent_card': copy.deepcopy(opposing_battle),
        'source_only_event': True,
    })
    la_nuit_resolved = any(
        event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') == 'unc-at-043-n1'
        for event in engine.events
    )
    return {
        'decision_kind': (decision or {}).get('kind'),
        'blade_hit_before_clash': blade_hit_before_clash,
        'la_nuit_resolved': la_nuit_resolved,
        'source_hit': source_battle.get('hit'),
        'opponent_hit': opposing_battle.get('hit'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_unc_at_043_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'UNC-AT-043':
        return None
    qna_ids = [237, 359]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('unc-at-043-function')
    judgment_swap = by_id.get('unc-at-043-n1')
    dark_damage = by_id.get('unc-at-043-n2')
    combo_damage = by_id.get('unc-at-043-n3')
    common = lambda ability, timing: bool(
        ability and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('timing') == timing
        and ability.get('active_zones') == ['battle']
        and ability.get('trigger') == {'event': timing}
    )
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 4
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('defense_rules') == [{
            'judgment': 'clash', 'min_speed': 8,
        }]
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and not function.get('trigger') and not function.get('condition')
        and not function.get('active_zones')
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and common(judgment_swap, 'clash')
        and judgment_swap.get('condition') == {
            'op': 'equals',
            'left': 'context.opponent_card.hit', 'right': '콤보',
        }
        and judgment_swap.get('effects') == [
            {
                'op': 'modify_judgment',
                'player': {'opponent': True},
                'field': 'hit', 'value': '+0',
            },
            {
                'op': 'modify_judgment',
                'player': {'controller': True},
                'field': 'hit', 'value': '콤보',
            },
        ]
        and common(dark_damage, 'clash')
        and dark_damage.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'dark_night',
        }
        and dark_damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'opponent': True},
            'stat': 'damage', 'amount': -200, 'duration': 'battle',
        }]
        and common(combo_damage, 'combo')
        and combo_damage.get('condition') == {
            'op': 'gt', 'left': 'context.combo_number', 'right': 1,
        }
        and combo_damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': -200, 'duration': 'battle',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'unc-at-043', False,
                reason='상쇄 속도·판정 교환·암야·콤보 데미지 정의가 일치하지 않습니다.',
            )],
            'UNC-AT-043 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    function_scenarios = []
    for name, owner, speed, allowed in (
        ('qna-359-owner-p1-speed-eight-with-fp-is-allowed', 'p1', 8, True),
        ('qna-359-owner-p2-speed-eight-with-fp-is-allowed', 'p2', 8, True),
        ('speed-seven-is-below-clash-limit', 'p1', 7, False),
        ('speed-twelve-is-above-clash-limit', 'p2', 12, True),
    ):
        rule = definition['defense_rules'][0]
        first = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner,
            allowed=allowed, speed_override=speed,
        )
        second = _run_defense_rule_scenario(
            definition, function, rule, card_snapshot, owner,
            allowed=allowed, speed_override=speed,
        )
        deterministic = _canonical(first) == _canonical(second)
        function_scenarios.append({
            'name': name,
            'passed': bool(first['passed'] and deterministic),
            'deterministic': deterministic,
            'printed_or_effect_speed': speed,
            'attacker_fp': 5,
            'fp_adjusted_speed': max(1, speed - 5),
            **first,
        })

    swap_scenarios = []
    for name, owner, kwargs, expected_source, expected_opponent, resolves in (
        ('owner-p1-opponent-combo-swaps-both-hit-values', 'p1', {}, '콤보', '+0', True),
        ('owner-p2-opponent-combo-swaps-both-hit-values', 'p2', {'source_hit': '-3'}, '콤보', '+0', True),
        ('opponent-non-combo-does-not-trigger', 'p1', {'opponent_hit': '+5'}, '5', '+5', False),
        ('wrong-trigger-does-not-swap', 'p2', {'event_type': 'hit'}, '5', '콤보', False),
        ('source-outside-battle-does-not-swap', 'p1', {'source_zone': 'hand'}, '5', '콤보', False),
        ('numbered-negation-does-not-swap', 'p2', {'numbered_effects_negated': True}, '5', '콤보', False),
    ):
        first = _run_unc_at_043_effect_scenario(
            definition, judgment_swap, card_snapshot, owner, **kwargs,
        )
        second = _run_unc_at_043_effect_scenario(
            definition, judgment_swap, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        swap_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is resolves
                and first['source_hit'] == expected_source
                and first['opponent_hit'] == expected_opponent
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': resolves,
            'expected_source_hit': expected_source,
            'expected_opponent_hit': expected_opponent,
            **first,
        })
    for owner, accept in (('p1', True), ('p2', True), ('p1', False)):
        first = _run_unc_at_043_qna_237_scenario(
            definition, card_snapshot, owner, accept=accept,
        )
        second = _run_unc_at_043_qna_237_scenario(
            definition, card_snapshot, owner, accept=accept,
        )
        deterministic = _canonical(first) == _canonical(second)
        swap_scenarios.append({
            'name': f'qna-237-{owner}-blade-effect-{"accepted" if accept else "declined"}',
            'passed': bool(
                deterministic
                and first['decision_kind'] == 'optional_effect'
                and first['blade_hit_before_clash'] == ('콤보' if accept else '5')
                and first['la_nuit_resolved'] is accept
                and first['source_hit'] == ('콤보' if accept else '5')
                and first['opponent_hit'] == ('+0' if accept else '5')
                and not first['pending']
            ),
            'deterministic': deterministic, 'accepted': accept, **first,
        })

    dark_scenarios = []
    for name, owner, kwargs, expected, resolves in (
        ('owner-p1-dark-night-reduces-seven-hundred-to-five-hundred', 'p1', {'dark_night': True}, 500, True),
        ('owner-p2-dark-night-reduces-two-hundred-to-zero', 'p2', {'dark_night': True, 'opponent_damage': 200}, 0, True),
        ('without-dark-night-does-not-reduce', 'p1', {}, 700, False),
        ('wrong-trigger-does-not-reduce', 'p2', {'dark_night': True, 'event_type': 'guard'}, 700, False),
        ('source-outside-battle-does-not-reduce', 'p1', {'dark_night': True, 'source_zone': 'list'}, 700, False),
        ('numbered-negation-does-not-reduce', 'p2', {'dark_night': True, 'numbered_effects_negated': True}, 700, False),
    ):
        first = _run_unc_at_043_effect_scenario(
            definition, dark_damage, card_snapshot, owner, **kwargs,
        )
        second = _run_unc_at_043_effect_scenario(
            definition, dark_damage, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        dark_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is resolves
                and first['opponent_damage'] == expected
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': resolves,
            'expected_opponent_damage': expected, **first,
        })
    for owner, order in (
        ('p1', ('unc-at-043-n1', 'unc-at-043-n2')),
        ('p2', ('unc-at-043-n2', 'unc-at-043-n1')),
    ):
        first = _run_unc_at_043_combined_scenario(
            definition, card_snapshot, owner, preferred_order=order,
        )
        second = _run_unc_at_043_combined_scenario(
            definition, card_snapshot, owner, preferred_order=order,
        )
        deterministic = _canonical(first) == _canonical(second)
        dark_scenarios.append({
            'name': f'{owner}-same-timing-effects-use-selected-order',
            'passed': bool(
                deterministic and first['resolution_order'] == list(order)
                and first['source_hit'] == '콤보'
                and first['opponent_hit'] == '+0'
                and first['opponent_damage'] == 500
                and first['decisions']
                and all(
                    item['kind'] == 'effect_order'
                    for item in first['decisions']
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    combo_scenarios = []
    for name, owner, kwargs, expected, resolves in (
        ('owner-p1-first-combo-keeps-seven-hundred', 'p1', {'combo_number': 1}, 700, False),
        ('owner-p1-second-combo-reduces-to-five-hundred', 'p1', {'combo_number': 2}, 500, True),
        ('owner-p2-third-combo-reduces-to-five-hundred', 'p2', {'combo_number': 3}, 500, True),
        ('wrong-trigger-does-not-reduce', 'p1', {'event_type': 'clash', 'combo_number': 2}, 700, False),
        ('source-outside-battle-does-not-reduce', 'p2', {'source_zone': 'hand', 'combo_number': 2}, 700, False),
        ('numbered-negation-does-not-reduce', 'p1', {'numbered_effects_negated': True, 'combo_number': 3}, 700, False),
    ):
        event_type = kwargs.get('event_type', 'combo')
        scenario_kwargs = {
            key: value for key, value in kwargs.items()
            if key != 'event_type'
        }
        first = _run_unc_at_043_effect_scenario(
            definition, combo_damage, card_snapshot, owner,
            event_type=event_type, **scenario_kwargs,
        )
        second = _run_unc_at_043_effect_scenario(
            definition, combo_damage, card_snapshot, owner,
            event_type=event_type, **scenario_kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['resolved'] is resolves
                and first['source_damage'] == expected
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolution': resolves,
            'expected_source_damage': expected, **first,
        })

    reviews = [
        AbilityReview(
            function['id'],
            all(item['passed'] for item in function_scenarios),
            function_scenarios,
            '' if all(item['passed'] for item in function_scenarios)
            else 'FP 적용 전 8속도 상쇄 경계 검증에 실패했습니다.',
        ),
        AbilityReview(
            judgment_swap['id'],
            all(item['passed'] for item in swap_scenarios), swap_scenarios,
            '' if all(item['passed'] for item in swap_scenarios)
            else '상대 콤보 판정 교환 및 Q&A 237 검증에 실패했습니다.',
        ),
        AbilityReview(
            dark_damage['id'],
            all(item['passed'] for item in dark_scenarios), dark_scenarios,
            '' if all(item['passed'] for item in dark_scenarios)
            else '암야 데미지 감소 및 동시 해결 검증에 실패했습니다.',
        ),
        AbilityReview(
            combo_damage['id'],
            all(item['passed'] for item in combo_scenarios), combo_scenarios,
            '' if all(item['passed'] for item in combo_scenarios)
            else '1콤보 경계 및 후속 콤보 데미지 감소 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '라 뉘 블랑쉬의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _lmi_at_036_source(card_snapshot, owner, suffix, *, source_zone='battle'):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-noir-{suffix}',
        'kind': 'card', 'owner': owner, 'code': 'LMI-AT-036',
        'name': '느와르', 'type': '공격', 'character_key': 'reve',
        'frame': 13, 'damage': None, 'pos': '상단', 'body': '',
        'special': '', 'hit': '4', 'guard': '-9', 'counter': '8',
        'face_up': source_zone == 'battle',
    })
    return source


def _lmi_at_036_candidate_definition(*, protected=False, future_mid=False):
    definition = {
        'schema_version': 1, 'reviewed': True, 'no_effect': not future_mid,
        'source_refs': {
            'rulebook_pages': [48, 49],
            'qna_ids': [197] if protected else ([448] if future_mid else []),
        },
        'abilities': [],
    }
    if protected:
        definition['break_rules'] = {
            'preventions': [{
                'scope': 'all',
                'condition': {
                    'op': 'has_state', 'player': {'controller': True},
                    'state': 'dark_night',
                },
            }],
        }
    if future_mid:
        definition['no_effect'] = False
        definition['abilities'] = [{
            'id': 'review-qna-448-future-mid-clash',
            'label': '판정 전 중단 상쇄 획득',
            'kind': 'effect', 'mode': 'mandatory',
            'timing': 'before_judgment', 'visibility': 'public',
            'active_zones': ['battle'],
            'source_refs': {
                'rulebook_pages': [48, 49], 'qna_ids': [448],
            },
            'trigger': {'event': 'before_judgment'},
            'effects': [{
                'op': 'modify_judgment',
                'player': {'controller': True},
                'field': 'special', 'value': '중단 상쇄', 'mode': 'append',
            }],
        }]
    return definition


def _lmi_at_036_candidate(
    owner, index, *, damage=400, special='', card_type='공격',
    g_top='', g_mid='', g_bot='', protected=False, future_mid=False,
    speed_limit=None,
):
    card = _card(
        f'REVIEW-NOIR-CANDIDATE-{owner.upper()}-{index}', owner,
        f'{owner}-noir-candidate-{index}',
    )
    card.update({
        'name': f'느와르 선택 기술 {index}', 'type': card_type,
        'frame': 8 + index, 'damage': damage,
        'pos': '상단', 'body': '손', 'special': special,
        'g_top': g_top, 'g_mid': g_mid, 'g_bot': g_bot,
        'hit': '+1', 'guard': '0', 'counter': '+1', 'face_up': False,
    })
    candidate_definition = _lmi_at_036_candidate_definition(
        protected=protected, future_mid=future_mid,
    )
    if speed_limit is not None:
        candidate_definition['defense_rules'] = [{
            'judgment': 'clash', 'max_speed': speed_limit,
        }]
    card['effect_definition'] = candidate_definition
    return card


def _run_lmi_at_036_use_scenario(
    definition, card_snapshot, owner, *, dark_night=False,
    candidate_specs=(), selected_indexes=(), event_type='use',
    source_zone='battle', numbered_effects_negated=False,
    judge_after=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_036_source(
        card_snapshot, owner, 'use', source_zone=source_zone,
    )
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-NOIR-OPPONENT', other, f'{other}-noir-opponent',
    )
    opposing.update({
        'type': '공격', 'frame': 12, 'damage': 500,
        'pos': '상단', 'body': '손', 'special': '',
        'hit': '+2', 'counter': '+2', 'face_up': True,
    })
    candidates = [
        _lmi_at_036_candidate(owner, index + 1, **spec)
        for index, spec in enumerate(candidate_specs)
    ]
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['players'][owner]['zones']['hand'].extend(copy.deepcopy(candidates))
    state['players']['p1']['fp'] = 0
    state['players']['p2']['fp'] = 0
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(next(
            ability for ability in definition.get('abilities') or []
            if ability.get('id') == 'lmi-at-036-n1'
        )),
    ]
    ruleset_cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': _st1_001_no_effect_definition(),
        },
    }
    for candidate in candidates:
        ruleset_cards[candidate['code']] = {
            **copy.deepcopy(candidate),
            'effect_definition': copy.deepcopy(candidate['effect_definition']),
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'noir-use:{owner}:{dark_night}:{candidate_specs}:'
            f'{selected_indexes}:{event_type}:{source_zone}:'
            f'{numbered_effects_negated}:{judge_after}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    source_battle = engine.engine_state['battle'][owner]['card']
    opposing_battle = engine.engine_state['battle'][other]['card']
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source_battle),
        'opponent_card': copy.deepcopy(opposing_battle),
        'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    option_ids = [
        str(option.get('id')) for option in (decision or {}).get('options') or []
    ]
    selected_ids = [
        candidates[index]['instance_id'] for index in selected_indexes
        if 0 <= index < len(candidates)
    ]
    if decision and selected_ids:
        engine._submit_decision(owner, decision.get('id'), selected_ids)
        engine._continue()
    while (
        (engine.engine_state.get('pending_decision') or {}).get('kind')
        == 'break_replenish'
    ):
        replenish = engine.engine_state['pending_decision']
        engine._submit_decision(owner, replenish.get('id'), ['decline'])
        engine._continue()
    battle_result = None
    if judge_after and not engine.engine_state.get('pending_decision'):
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        battle_result = copy.deepcopy(
            (engine.engine_state.get('battle') or {}).get('result'),
        )
    copied_event = next((
        event for event in reversed(engine.events)
        if event.get('type') == 'clash_judgments_copied'
    ), None)
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-036-n1' for event in engine.events
        ),
        'decision_kind': (decision or {}).get('kind'),
        'minimum': (decision or {}).get('minimum'),
        'maximum': (decision or {}).get('maximum'),
        'option_ids': option_ids, 'selected_ids': selected_ids,
        'broken_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'break')
            if card.get('instance_id') in {
                candidate['instance_id'] for candidate in candidates
            }
        ),
        'hand_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'hand')
        ),
        'source_damage': engine.card_stat(
            source_battle, 'damage', owner, include_fp=False,
        ),
        'source_special': source_battle.get('special') or '',
        'copied_positions': list(
            ((copied_event or {}).get('payload') or {}).get('positions') or []
        ),
        'choice_skipped': any(
            event.get('type') == 'effect_choice_skipped'
            for event in engine.events
        ),
        'battle_result': battle_result,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_036_combo_rule_scenario(
    definition, card_snapshot, owner, *, dark_night,
    opponent_hp, numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_036_source(card_snapshot, owner, 'combo-rule')
    source['damage'] = 700
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    previous = _card(
        'REVIEW-NOIR-COMBO-PREVIOUS', owner,
        f'{owner}-noir-combo-previous',
    )
    previous.update({'frame': 10, 'damage': 500, 'face_up': True})
    opposing = _card(
        'REVIEW-NOIR-COMBO-OPPONENT', other,
        f'{other}-noir-combo-opponent',
    )
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['list'].append(copy.deepcopy(previous))
    state['players'][other]['hp'] = opponent_hp
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    ruleset = {
        'version': AUTOMATIC_SCENARIO_VERSION,
        'cards': {
            source['code']: {
                **copy.deepcopy(source),
                'effect_definition': copy.deepcopy(definition),
            },
            previous['code']: {
                **copy.deepcopy(previous),
                'effect_definition': _st1_001_no_effect_definition(),
            },
            opposing['code']: {
                **copy.deepcopy(opposing),
                'effect_definition': _st1_001_no_effect_definition(),
            },
        },
    }
    engine = AutomaticGameEngine(
        state, ruleset,
        seed=(
            f'noir-combo-rule:{owner}:{dark_night}:{opponent_hp}:'
            f'{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    combo = {
        'owner': owner, 'source': previous['instance_id'],
        'used': [previous['instance_id']], 'last_speed': 10,
        'next_penalty': 200,
    }
    rules = engine._combo_rules(owner, live_source, combo)
    applied_penalty = engine._combo_applied_penalty(
        owner, live_source, combo, 200, rules=rules,
    )
    engine._fire('combo', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(
            engine.engine_state['battle'][owner]['card'],
        ),
        'opponent_card': copy.deepcopy(
            engine.engine_state['battle'][other]['card'],
        ),
        'source_only_event': True,
        'combo': True, 'combo_number': 2,
        'controller_hp': engine.state['players'][owner]['hp'],
        'opponent_hp': engine.state['players'][other]['hp'],
    })
    return {
        'rule_count': len(rules),
        'ignore_damage_penalty': any(
            rule.get('ignore_damage_penalty') for rule in rules
        ),
        'applied_penalty': applied_penalty,
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-036-n2' for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_036_after_use_scenario(
    definition, card_snapshot, owner, *, dark_night=False,
    gain_dark_before=False, event_type='after_use', source_zone='battle',
    numbered_effects_negated=False, combo_pipeline=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_036_source(
        card_snapshot, owner, 'after-use', source_zone=source_zone,
    )
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-NOIR-AFTER-USE-OPPONENT', other,
        f'{other}-noir-after-use-opponent',
    )
    state = _state(source, opposing, owner, source_zone=source_zone)
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(next(
            ability for ability in definition.get('abilities') or []
            if ability.get('id') == 'lmi-at-036-n3'
        )),
    ]
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': _st1_001_no_effect_definition(),
                },
            },
        },
        seed=(
            f'noir-after-use:{owner}:{dark_night}:{gain_dark_before}:'
            f'{event_type}:{source_zone}:{numbered_effects_negated}:'
            f'{combo_pipeline}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    if gain_dark_before:
        engine.set_passive(
            owner, 'dark_night', value=True, label='암야',
            source_card=engine.engine_state['battle'][owner]['card'],
        )
    if combo_pipeline:
        engine.engine_state['pipeline'] = {
            'kind': 'combo_resolution',
            'owner': owner, 'card_instance_id': source['instance_id'],
            'card': copy.deepcopy(engine.engine_state['battle'][owner]['card']),
        }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(
            engine.engine_state['battle'][owner]['card'],
        ),
        'opponent_card': copy.deepcopy(
            engine.engine_state['battle'][other]['card'],
        ),
        'source_only_event': True,
    })
    location = engine._find_location(source['instance_id'])
    pipeline = engine.engine_state.get('pipeline') or {}
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-036-n3' for event in engine.events
        ),
        'source_zone': location[1],
        'continue_after_source_left': bool(
            pipeline.get('continue_after_source_left')
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_036_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-036':
        return None
    qna_ids = [59, 197, 407, 448, 449, 450, 461]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    use = by_id.get('lmi-at-036-n1')
    combo = by_id.get('lmi-at-036-n2')
    cleanup = by_id.get('lmi-at-036-n3')
    dark_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'dark_night',
    }
    dark_low_hp = {
        'op': 'all',
        'conditions': [
            copy.deepcopy(dark_condition),
            {'op': 'lte', 'left': 'context.opponent_hp', 'right': 1000},
        ],
    }
    required_count = {
        'op': 'if', 'condition': copy.deepcopy(dark_condition),
        'then': 2, 'else': 1,
    }
    damage_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['hand'], 'min': required_count, 'max': required_count,
        'where': {'is_technique': True},
        'as_operation': 'break_card',
        'include_operation_blocked': True,
    }
    use_effects = (use or {}).get('effects') or []
    request = use_effects[0] if len(use_effects) == 1 else {}
    selector = request.get('selector') or {}
    then = request.get('then') or []
    cleanup_effects = (cleanup or {}).get('effects') or []
    cleanup_branch = cleanup_effects[0] if len(cleanup_effects) == 1 else {}
    common = lambda ability, timing: bool(
        ability and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('timing') == timing
        and ability.get('active_zones') == ['battle']
        and ability.get('trigger') == {'event': timing}
    )
    valid = bool(
        extra_root == {'combo_rules'} and len(abilities) == 3
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('combo_rules') == [
            {
                'project_damage_from_selector': {
                    'selector': damage_selector, 'field': 'damage',
                },
                'numbered_effect': True,
            },
            {
                'ignore_damage_penalty': True,
                'numbered_effect': True,
                'condition': dark_low_hp,
            },
        ]
        and common(use, 'use') and not use.get('condition')
        and request.get('op') == 'request_choice'
        and selector == damage_selector
        and [effect.get('op') for effect in then] == [
            'break_card', 'modify_stat', 'copy_clash_judgments',
        ]
        and then[0].get('result_key') == 'lmi_at_036_broken'
        and then[1] == {
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'fixed': True,
            'value': {
                'op': 'selected_cards_field_sum',
                'selection_key': 'lmi_at_036_broken',
                'field': 'damage', 'default': 0,
            },
            'duration': 'battle',
        }
        and then[2] == {
            'op': 'copy_clash_judgments',
            'player': {'controller': True},
            'selection_key': 'lmi_at_036_broken',
        }
        and common(combo, 'combo') and combo.get('condition') == dark_low_hp
        and combo.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and common(cleanup, 'after_use') and not cleanup.get('condition')
        and cleanup_branch.get('op') == 'conditional'
        and cleanup_branch.get('condition') == dark_condition
        and cleanup_branch.get('then') == [{
            'op': 'move_card',
            'card_instance_id': {'path': 'context.source_card_instance_id'},
            'to_zone': 'side', 'continue_resolution': True,
        }]
        and cleanup_branch.get('else') == [{
            'op': 'break_card',
            'card_instance_id': {'path': 'context.source_card_instance_id'},
            'continue_resolution': True,
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-036', False,
                reason='강제 브레이크·상쇄 계승·콤보 보정·사용 후 이동 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-036 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    use_specs = (
        {
            'name': 'owner-p1-selects-one-attack-and-copies-upper-clash',
            'owner': 'p1',
            'candidate_specs': ({'damage': 400, 'special': '상단 상쇄'},),
            'selected_indexes': (0,), 'expected_range': (1, 1),
            'expected_damage': 400, 'expected_special': '상단 상쇄',
            'expected_broken': 1,
        },
        {
            'name': 'qna-59-owner-p2-defense-zero-damage-still-copies-mid-clash',
            'owner': 'p2',
            'candidate_specs': ({'damage': 0, 'card_type': '수비', 'g_mid': '상쇄'},),
            'selected_indexes': (0,), 'expected_range': (1, 1),
            'expected_damage': 0, 'expected_special': '중단 상쇄',
            'expected_broken': 1,
        },
        {
            'name': 'qna-450-dark-night-selects-two-and-copies-two-clashes',
            'owner': 'p1', 'dark_night': True,
            'candidate_specs': (
                {'damage': 300, 'special': '상단 상쇄'},
                {'damage': 500, 'special': '하단 상쇄'},
            ),
            'selected_indexes': (0, 1), 'expected_range': (2, 2),
            'expected_damage': 800,
            'expected_special': '상단 상쇄 · 하단 상쇄',
            'expected_broken': 2,
        },
        {
            'name': 'qna-448-future-mid-clash-is-not-copied-at-use',
            'owner': 'p2',
            'candidate_specs': ({
                'damage': 600, 'special': '상단 상쇄', 'future_mid': True,
            },),
            'selected_indexes': (0,), 'expected_range': (1, 1),
            'expected_damage': 600, 'expected_special': '상단 상쇄',
            'expected_broken': 1,
        },
        {
            'name': 'qna-449-copies-clash-but-not-source-speed-limit',
            'owner': 'p1',
            'candidate_specs': ({
                'damage': 500, 'special': '상단 상쇄', 'speed_limit': 5,
            },),
            'selected_indexes': (0,), 'expected_range': (1, 1),
            'expected_damage': 500, 'expected_special': '상단 상쇄',
            'expected_broken': 1, 'judge_after': True,
            'expected_result': {'p1': 'clash', 'p2': 'clash'},
        },
        {
            'name': 'qna-197-protected-card-contributes-neither-damage-nor-clash',
            'owner': 'p2', 'dark_night': True,
            'candidate_specs': (
                {'damage': 900, 'special': '상단 상쇄', 'protected': True},
                {'damage': 300, 'special': '하단 상쇄'},
            ),
            'selected_indexes': (0, 1), 'expected_range': (2, 2),
            'expected_damage': 300, 'expected_special': '하단 상쇄',
            'expected_broken': 1, 'expected_hand': 1,
        },
        {
            'name': 'dark-night-with-one-candidate-aborts-required-choice',
            'owner': 'p1', 'dark_night': True,
            'candidate_specs': ({'damage': 400},),
            'selected_indexes': (), 'expected_range': (None, None),
            'expected_damage': 0, 'expected_special': '',
            'expected_broken': 0, 'expected_hand': 1,
            'expected_skipped': True,
        },
        {
            'name': 'wrong-trigger-does-not-request-or-break',
            'owner': 'p2', 'event_type': 'after_use',
            'candidate_specs': ({'damage': 400},),
            'selected_indexes': (), 'expected_range': (None, None),
            'expected_damage': 0, 'expected_special': '',
            'expected_broken': 0, 'expected_hand': 1,
            'expected_resolved': False,
        },
        {
            'name': 'numbered-negation-does-not-request-or-break',
            'owner': 'p1', 'numbered_effects_negated': True,
            'candidate_specs': ({'damage': 400},),
            'selected_indexes': (), 'expected_range': (None, None),
            'expected_damage': 0, 'expected_special': '',
            'expected_broken': 0, 'expected_hand': 1,
            'expected_resolved': False,
        },
    )
    use_scenarios = []
    for spec in use_specs:
        kwargs = {
            key: value for key, value in spec.items()
            if key not in {
                'name', 'owner', 'expected_range', 'expected_damage',
                'expected_special', 'expected_broken', 'expected_hand',
                'expected_skipped', 'expected_resolved', 'expected_result',
            }
        }
        first = _run_lmi_at_036_use_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        second = _run_lmi_at_036_use_scenario(
            definition, card_snapshot, spec['owner'], **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        use_scenarios.append({
            'name': spec['name'],
            'passed': bool(
                deterministic
                and first['resolved'] is spec.get('expected_resolved', True)
                and (first['minimum'], first['maximum'])
                == spec['expected_range']
                and first['source_damage'] == spec['expected_damage']
                and first['source_special'] == spec['expected_special']
                and len(first['broken_ids']) == spec['expected_broken']
                and len([
                    instance_id for instance_id in first['hand_ids']
                    if 'noir-candidate' in instance_id
                ]) == spec.get('expected_hand', 0)
                and first['choice_skipped']
                is spec.get('expected_skipped', False)
                and first['battle_result'] == spec.get('expected_result')
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    combo_scenarios = []
    for name, owner, dark_night, opponent_hp, negated, expected in (
        ('owner-p1-dark-night-at-1000-ignores-penalty', 'p1', True, 1000, False, 0),
        ('owner-p2-dark-night-below-1000-ignores-penalty', 'p2', True, 600, False, 0),
        ('opponent-1001-does-not-ignore-penalty', 'p1', True, 1001, False, 200),
        ('without-dark-night-does-not-ignore-penalty', 'p2', False, 1000, False, 200),
        ('numbered-negation-restores-normal-penalty', 'p1', True, 1000, True, 200),
    ):
        first = _run_lmi_at_036_combo_rule_scenario(
            definition, card_snapshot, owner,
            dark_night=dark_night, opponent_hp=opponent_hp,
            numbered_effects_negated=negated,
        )
        second = _run_lmi_at_036_combo_rule_scenario(
            definition, card_snapshot, owner,
            dark_night=dark_night, opponent_hp=opponent_hp,
            numbered_effects_negated=negated,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_active = expected == 0
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['ignore_damage_penalty'] is expected_active
                and first['applied_penalty'] == expected
                and first['resolved'] is expected_active
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_penalty': expected, **first,
        })

    cleanup_scenarios = []
    for name, owner, kwargs, zone, resolved, continues in (
        ('owner-p1-without-dark-night-breaks-after-use', 'p1', {}, 'break', True, False),
        ('owner-p2-dark-night-sends-to-side', 'p2', {'dark_night': True}, 'side', True, False),
        ('qna-407-dark-night-gained-before-after-use-sends-to-side', 'p1', {'gain_dark_before': True}, 'side', True, False),
        ('dark-night-combo-move-allows-resolution-to-continue', 'p2', {'dark_night': True, 'combo_pipeline': True}, 'side', True, True),
        ('wrong-trigger-keeps-source-in-battle', 'p1', {'event_type': 'after_judgment'}, 'battle', False, False),
        ('source-outside-battle-does-not-move', 'p2', {'source_zone': 'hand'}, 'hand', False, False),
        ('numbered-negation-keeps-source-in-battle', 'p1', {'numbered_effects_negated': True}, 'battle', False, False),
    ):
        first = _run_lmi_at_036_after_use_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_036_after_use_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        cleanup_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['source_zone'] == zone
                and first['resolved'] is resolved
                and first['continue_after_source_left'] is continues
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_zone': zone, 'expected_resolution': resolved, **first,
        })

    reviews = [
        AbilityReview(
            use['id'], all(item['passed'] for item in use_scenarios),
            use_scenarios,
            '' if all(item['passed'] for item in use_scenarios)
            else '패 강제 선택·성공 브레이크 합산·상쇄 판정 계승 검증에 실패했습니다.',
        ),
        AbilityReview(
            combo['id'], all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
            '' if all(item['passed'] for item in combo_scenarios)
            else '암야 및 상대 HP 경계의 콤보 데미지 보정 검증에 실패했습니다.',
        ),
        AbilityReview(
            cleanup['id'], all(item['passed'] for item in cleanup_scenarios),
            cleanup_scenarios,
            '' if all(item['passed'] for item in cleanup_scenarios)
            else '사용 후 브레이크·암야 대체 이동 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '느와르의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_lmi_at_039_scenario(
    definition, card_snapshot, owner, *, opponent_type='공격',
    opponent_special='', dark_night=False, gain_dark_before=False,
    include_dark_trait=False, event_type='before_judgment',
    source_zone='battle', numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-night-talon', 'owner': owner,
        'type': '공격', 'frame': 6, 'damage': 400,
        'pos': '중단', 'special': '', 'face_up': True,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-NIGHT-TALON-OPPONENT', other,
        f'{other}-night-talon-opponent',
    )
    opposing.update({
        'type': opponent_type, 'special': opponent_special,
        'face_up': True,
    })
    passive = _card(
        'AWL-PS-001', owner, f'{owner}-veiled-blade',
    )
    passive.update({
        'name': '「장막을 두른 칼날」', 'type': '특성',
        'frame': None, 'damage': None, 'face_up': True,
    })
    dark_trait_definition = {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {
            'rulebook_pages': [48, 49], 'qna_ids': [584],
            'card_text': True,
        },
        'abilities': [{
            'id': 'awl-ps-001-n2',
            'label': '암야 상태에서 상대 기술의 특수 판정을 항상 제거한다',
            'kind': 'effect', 'mode': 'continuous',
            'timing': 'function', 'visibility': 'public',
            'source_refs': {
                'rulebook_pages': [48, 49], 'qna_ids': [584],
                'card_text': True,
            },
            'active_zones': ['passive'],
            'condition': {
                'op': 'has_state', 'player': {'controller': True},
                'state': 'dark_night',
            },
            'effects': [{
                'op': 'modify_judgment', 'player': {'opponent': True},
                'field': 'special', 'value': '', 'mode': 'clear',
                'duration': 'continuous', 'scope': 'all_zones',
                'target_zones': [
                    'hand', 'list', 'battle', 'side', 'break',
                    'lumen', 'ultimate',
                ],
                'where': {'is_technique': True},
            }],
        }],
    }
    state = _state(source, opposing, owner, source_zone=source_zone)
    if include_dark_trait:
        state['players'][owner]['zones']['passive'].append(
            copy.deepcopy(passive),
        )
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야',
        }
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [copy.deepcopy(
        (definition.get('abilities') or [{}])[0],
    )]
    ruleset_cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': _st1_001_no_effect_definition(),
        },
    }
    if include_dark_trait:
        ruleset_cards[passive['code']] = {
            **copy.deepcopy(passive),
            'effect_definition': dark_trait_definition,
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'night-talon:{owner}:{opponent_type}:{opponent_special}:'
            f'{dark_night}:{gain_dark_before}:{include_dark_trait}:'
            f'{event_type}:{source_zone}:{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    if gain_dark_before:
        engine.set_passive(
            owner, 'dark_night', value=True, label='암야',
            source_card=(engine._find_card(passive['instance_id']) or passive),
        )
    if event_type == 'before_judgment':
        engine._battle_trigger(event_type)
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': copy.deepcopy(
                engine.engine_state['battle'][owner]['card'],
            ),
            'opponent_card': copy.deepcopy(
                engine.engine_state['battle'][other]['card'],
            ),
            'source_only_event': True,
        })
    live_source = engine.engine_state['battle'][owner]['card']
    live_opponent = engine.engine_state['battle'][other]['card']
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-039-n1' for event in engine.events
        ),
        'source_damage': engine.card_stat(
            live_source, 'damage', owner, include_fp=False,
        ),
        'opponent_special': live_opponent.get('special') or '',
        'dark_night': bool(
            engine.state['players'][owner].get('passive_state', {})
            .get('dark_night', {}).get('value')
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_039_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-039':
        return None
    qna_ids = [584]
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else None
    expected_condition = {
        'op': 'card_matches',
        'card': {'path': 'context.opponent_card'},
        'where': {'type_contains': '공격', 'special_truthy': False},
    }
    expected_effect = {
        'op': 'modify_stat', 'player': {'controller': True},
        'stat': 'damage', 'amount': 100, 'duration': 'battle',
    }
    valid = bool(
        not extra_root and ability
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
        and ability.get('id') == 'lmi-at-039-n1'
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('timing') == 'before_judgment'
        and ability.get('active_zones') == ['battle']
        and ability.get('trigger') == {'event': 'before_judgment'}
        and ability.get('condition') == expected_condition
        and ability.get('effects') == [expected_effect]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-039-n1', False,
                reason='상대 공격·특수 판정 부재·데미지 증가 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-039 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    specs = (
        (
            'owner-p1-opposing-attack-without-special-gains-one-hundred',
            'p1', {}, True, 500, '',
        ),
        (
            'owner-p2-opposing-attack-without-special-gains-one-hundred',
            'p2', {}, True, 500, '',
        ),
        (
            'opposing-attack-with-grab-does-not-trigger', 'p1',
            {'opponent_special': '그랩'}, False, 400, '그랩',
        ),
        (
            'opposing-defense-without-special-does-not-trigger', 'p2',
            {'opponent_type': '수비'}, False, 400, '',
        ),
        (
            'qna-584-dark-night-clears-grab-before-condition-p1', 'p1',
            {
                'opponent_special': '그랩', 'dark_night': True,
                'include_dark_trait': True,
            }, True, 500, '',
        ),
        (
            'qna-584-dark-night-clears-grab-before-condition-p2', 'p2',
            {
                'opponent_special': '그랩 · 상단 회피',
                'dark_night': True, 'include_dark_trait': True,
            }, True, 500, '',
        ),
        (
            'qna-584-dark-night-gained-after-use-refreshes-before-judgment',
            'p1',
            {
                'opponent_special': '그랩', 'gain_dark_before': True,
                'include_dark_trait': True,
            }, True, 500, '',
        ),
        (
            'dark-trait-without-state-keeps-opposing-special', 'p2',
            {
                'opponent_special': '그랩',
                'include_dark_trait': True,
            }, False, 400, '그랩',
        ),
        (
            'wrong-trigger-does-not-change-damage', 'p1',
            {'event_type': 'use'}, False, 400, '',
        ),
        (
            'source-outside-battle-does-not-trigger', 'p2',
            {'source_zone': 'hand'}, False, 400, '',
        ),
        (
            'numbered-effect-negation-does-not-change-damage', 'p1',
            {'numbered_effects_negated': True}, False, 400, '',
        ),
    )
    scenarios = []
    for name, owner, kwargs, expected_resolved, expected_damage, expected_special in specs:
        first = _run_lmi_at_039_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_039_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['resolved'] is expected_resolved
                and first['source_damage'] == expected_damage
                and first['opponent_special'] == expected_special
                and not first['pending']
            ),
            'deterministic': deterministic,
            'expected_resolved': expected_resolved,
            'expected_damage': expected_damage,
            'expected_opponent_special': expected_special,
            **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            ability['id'], passed, scenarios,
            '' if passed else '나이트 탈론의 조건·암야 연동 검증에 실패했습니다.',
        )],
        '' if passed else '나이트 탈론의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_lmi_at_040_scenario(
    definition, card_snapshot, owner, *, event_type='hit',
    source_zone='battle', numbered_effects_negated=False,
    traits_negated=False, expire_battles=False, attempt_get=False,
    release_turn=False, catch_pipeline=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-wicked-shadow', 'owner': owner,
        'type': '공격', 'frame': 5, 'damage': 200,
        'pos': '하단', 'special': '', 'face_up': source_zone == 'battle',
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-WICKED-SHADOW-OPPONENT', other,
        f'{other}-wicked-shadow-opponent',
    )
    negator = _card(
        'REVIEW-WICKED-SHADOW-NEGATOR', other,
        f'{other}-wicked-shadow-negator',
    )
    negator.update({
        'type': '특수 기술', 'frame': None, 'damage': None,
        'face_up': True,
    })
    no_effect = _st1_001_no_effect_definition()
    negator_definition = {
        **copy.deepcopy(no_effect),
        'trait_negation': {
            'players': 'both', 'active_zones': ['lumen'],
        },
    }
    state = _state(source, opposing, owner, source_zone=source_zone)
    if traits_negated:
        state['players'][other]['zones']['lumen'].append(
            copy.deepcopy(negator),
        )
    ruleset_cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if traits_negated:
        ruleset_cards[negator['code']] = {
            **copy.deepcopy(negator),
            'effect_definition': negator_definition,
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'wicked-shadow:{owner}:{event_type}:{source_zone}:'
            f'{numbered_effects_negated}:{traits_negated}:{expire_battles}:'
            f'{attempt_get}:{release_turn}:{catch_pipeline}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    if catch_pipeline:
        engine.engine_state['pipeline'] = {
            'kind': 'catch_resolution', 'owner': owner,
            'card_instance_id': source['instance_id'],
            'card': copy.deepcopy(engine.engine_state['battle'][owner]['card']),
        }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(
            engine.engine_state['battle'][owner]['card'],
        ),
        'opponent_card': copy.deepcopy(
            engine.engine_state['battle'][other]['card'],
        ),
        'source_only_event': True,
    })
    engine._reconcile_trait_states()
    state_entry = (
        engine.state['players'][owner].get('passive_state', {})
        .get('dark_night', {})
    )
    dark_after_effect = bool(state_entry.get('value'))
    trait_origin = state_entry.get('trait_origin')
    dark_after_current_battle = None
    dark_after_next_battle = None
    if expire_battles and dark_after_effect:
        engine._expire_state_durations('phase_end', phase='battle')
        dark_after_current_battle = bool(
            engine.state['players'][owner]['passive_state']
            ['dark_night']['value']
        )
        engine._expire_state_durations('phase_end', phase='battle')
        dark_after_next_battle = bool(
            engine.state['players'][owner]['passive_state']
            ['dark_night']['value']
        )
    phase_after_get = None
    get_prevented = False
    get_completed = False
    if attempt_get and engine._find_card(
        source['instance_id'], owner=owner, zone='list',
    ):
        engine.state['phase'] = 'get'
        engine.engine_state.update({
            'step': 'get_actions', 'current_actor': owner,
            'get_order': [owner], 'get_done': [],
        })
        engine._get_card(owner, source['instance_id'])
        phase_after_get = engine.state.get('phase')
        get_prevented = any(
            event.get('type') == 'card_move_prevented'
            and (event.get('payload') or {}).get('card_instance_id')
            == source['instance_id'] for event in engine.events
        )
        get_completed = any(
            event.get('type') == 'get_completed'
            and (event.get('payload') or {}).get('card_instance_id')
            == source['instance_id'] for event in engine.events
        )
    hand_after_turn = False
    if release_turn and engine._find_card(
        source['instance_id'], owner=owner, zone='list',
    ):
        engine._complete_turn()
        moved = engine.move_card(
            source['instance_id'], 'hand', reason='review_after_turn_end',
        )
        hand_after_turn = moved is not None
    location = engine._find_location(source['instance_id'])
    live = location[3] or {}
    pipeline = engine.engine_state.get('pipeline') or {}
    return {
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-040-n1' for event in engine.events
        ),
        'source_zone': location[1],
        'blocked_until': live.get('move_to_hand_blocked_until'),
        'dark_after_effect': dark_after_effect,
        'trait_origin': trait_origin,
        'traits_negated': engine._traits_negated(),
        'dark_after_current_battle': dark_after_current_battle,
        'dark_after_next_battle': dark_after_next_battle,
        'phase_after_get': phase_after_get,
        'get_prevented': get_prevented,
        'get_completed': get_completed,
        'hand_after_turn': hand_after_turn,
        'continue_after_source_left': bool(
            pipeline.get('continue_after_source_left')
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_040_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-040':
        return None
    qna_ids = [220, 652]
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else None
    expected_effects = [
        {
            'op': 'gain_state', 'player': {'controller': True},
            'state': 'dark_night', 'label': '암야',
            'expires': {
                'event': 'phase_end', 'phase': 'battle', 'occurrences': 2,
            },
        },
        {
            'op': 'move_card',
            'card_instance_id': {
                'path': 'context.source_card_instance_id',
            },
            'to_zone': 'list', 'block_hand_until': 'turn',
            'continue_resolution': True,
        },
    ]
    valid = bool(
        not extra_root and ability
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
        and ability.get('id') == 'lmi-at-040-n1'
        and ability.get('kind') == 'effect'
        and ability.get('mode') == 'mandatory'
        and ability.get('timing') == 'hit_counter'
        and ability.get('active_zones') == ['battle']
        and ability.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and not ability.get('condition')
        and ability.get('effects') == expected_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-040-n1', False,
                reason='암야 만료·리스트 이동·패 이동 금지 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-040 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    specs = (
        (
            'owner-p1-hit-gains-dark-night-and-moves-to-list', 'p1', {},
            lambda result: (
                result['resolved'] and result['dark_after_effect']
                and result['source_zone'] == 'list'
                and result['blocked_until'] == 'turn'
            ),
        ),
        (
            'owner-p2-counter-gains-dark-night-and-moves-to-list', 'p2',
            {'event_type': 'counter'},
            lambda result: (
                result['resolved'] and result['dark_after_effect']
                and result['source_zone'] == 'list'
                and result['blocked_until'] == 'turn'
            ),
        ),
        (
            'next-battle-expiration-keeps-current-then-clears-next', 'p1',
            {'expire_battles': True},
            lambda result: (
                result['dark_after_current_battle'] is True
                and result['dark_after_next_battle'] is False
            ),
        ),
        (
            'qna-220-technique-grants-state-while-traits-are-negated', 'p2',
            {'traits_negated': True},
            lambda result: (
                result['traits_negated'] and result['dark_after_effect']
                and result['trait_origin'] is False
            ),
        ),
        (
            'qna-652-blocked-get-stays-in-list-and-ends-get', 'p1',
            {'attempt_get': True},
            lambda result: (
                result['get_prevented'] and result['get_completed']
                and result['source_zone'] == 'list'
                and result['phase_after_get'] == 'recovery'
            ),
        ),
        (
            'turn-end-removes-hand-lock-and-allows-move', 'p2',
            {'release_turn': True},
            lambda result: (
                result['hand_after_turn']
                and result['source_zone'] == 'hand'
                and result['blocked_until'] is None
            ),
        ),
        (
            'catch-hit-move-does-not-interrupt-remaining-resolution', 'p1',
            {'catch_pipeline': True},
            lambda result: result['continue_after_source_left'],
        ),
        (
            'wrong-trigger-keeps-source-in-battle', 'p2',
            {'event_type': 'before_judgment'},
            lambda result: (
                not result['resolved'] and not result['dark_after_effect']
                and result['source_zone'] == 'battle'
            ),
        ),
        (
            'source-outside-battle-does-not-trigger', 'p1',
            {'source_zone': 'hand'},
            lambda result: (
                not result['resolved'] and not result['dark_after_effect']
                and result['source_zone'] == 'hand'
            ),
        ),
        (
            'numbered-effect-negation-does-not-trigger', 'p2',
            {'numbered_effects_negated': True},
            lambda result: (
                not result['resolved'] and not result['dark_after_effect']
                and result['source_zone'] == 'battle'
            ),
        ),
    )
    scenarios = []
    for name, owner, kwargs, assertion in specs:
        first = _run_lmi_at_040_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_040_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and assertion(first) and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(
            ability['id'], passed, scenarios,
            '' if passed else '위키드 섀도우의 상태·이동·Get 검증에 실패했습니다.',
        )],
        '' if passed else '위키드 섀도우의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_lmi_at_041_scenario(
    definition, card_snapshot, owner, *, ability_ids=None,
    side_count=0, lumen_count=1, dagger_count=0, side_dagger_count=0,
    event_type='clash',
    event_controller=None, dark_night=False, accept_optional=True,
    numbered_effects_negated=False, damage_reduction=False,
    support_combo_token=False, repeat_combo=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    event_controller = event_controller or owner
    event_source = _card(
        'REVIEW-BLACK-FEATHER-EVENT', owner,
        f'{owner}-black-feather-event',
    )
    opposing = _card(
        'REVIEW-BLACK-FEATHER-OPPONENT', other,
        f'{other}-black-feather-opponent',
    )
    opposing.update({'damage': 600, 'face_up': True})
    feather_template = _sandbox_source_snapshot(card_snapshot)
    feather_template.update({
        'type': '특수 기술', 'frame': None, 'damage': None,
        'face_up': True,
    })
    feathers = []
    for zone, count in (('side', side_count), ('lumen', lumen_count)):
        for index in range(count):
            card = copy.deepcopy(feather_template)
            card.update({
                'instance_id': f'{owner}-black-feather-{zone}-{index}',
                'owner': owner, 'face_up': zone != 'side',
            })
            if numbered_effects_negated:
                card['numbered_effects_negated'] = True
            feathers.append((zone, card))
    daggers = []
    for zone, count in (('lumen', dagger_count), ('side', side_dagger_count)):
        for index in range(count):
            daggers.append((zone, {
                'instance_id': f'{owner}-black-feather-dagger-{zone}-{index}',
                'kind': 'token', 'owner': owner, 'code': 'LMI-AT-059',
                'name': '단검', 'type': '토큰', 'token_key': 'dagger',
                'frame': None, 'damage': None, 'face_up': zone != 'side',
            }))
    isolated = copy.deepcopy(definition)
    if ability_ids is not None:
        selected = set(ability_ids)
        isolated['abilities'] = [
            copy.deepcopy(ability)
            for ability in definition.get('abilities') or []
            if ability.get('id') in selected
        ]
    no_effect = _st1_001_no_effect_definition()
    state = _state(event_source, opposing, owner)
    for zone, card in feathers:
        state['players'][owner]['zones'][zone].append(copy.deepcopy(card))
    for zone, dagger in daggers:
        state['players'][owner]['zones'][zone].append(copy.deepcopy(dagger))
    if dark_night:
        state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야', 'trait_origin': False,
        }
    support = None
    support_definition = None
    if support_combo_token:
        support = _card(
            'REVIEW-BLACK-FEATHER-COMBO-TOKEN', owner,
            f'{owner}-black-feather-combo-token',
        )
        support.update({'type': '특수 기술', 'face_up': True})
        state['players'][owner]['zones']['lumen'].append(copy.deepcopy(support))
        support_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [], 'qna_ids': []},
            'abilities': [{
                'id': 'review-black-feather-create-combo-token',
                'label': '콤보 시 단검 토큰 1장 배치',
                'kind': 'effect', 'mode': 'mandatory',
                'timing': 'combo', 'visibility': 'public',
                'source_refs': {'rulebook_pages': [], 'qna_ids': []},
                'active_zones': ['lumen'],
                'trigger': {'event': 'combo'},
                'condition': {
                    'op': 'equals', 'left': 'context.event_controller',
                    'right': {'controller': True},
                },
                'effects': [{
                    'op': 'create_token',
                    'player': {'controller': True}, 'zone': 'lumen',
                    'name': '단검', 'code': 'LMI-AT-059', 'type': '토큰',
                    'face_up': True, 'max_zone_count': 6,
                    'card': {'token_key': 'dagger'},
                }],
            }],
        }
    ruleset_cards = {
        event_source['code']: {
            **copy.deepcopy(event_source), 'effect_definition': no_effect,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
        feather_template['code']: {
            **copy.deepcopy(feather_template),
            'effect_definition': isolated,
        },
    }
    if daggers:
        ruleset_cards['LMI-AT-059'] = {
            **copy.deepcopy(daggers[0][1]), 'instance_id': None,
            'effect_definition': no_effect,
        }
    if support is not None:
        ruleset_cards[support['code']] = {
            **copy.deepcopy(support),
            'effect_definition': support_definition,
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'black-feather:{owner}:{ability_ids}:{side_count}:{lumen_count}:'
            f'{dagger_count}:{side_dagger_count}:{event_type}:'
            f'{event_controller}:{dark_night}:'
            f'{accept_optional}:{numbered_effects_negated}:'
            f'{damage_reduction}:{support_combo_token}:{repeat_combo}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': event_source['instance_id'],
            'card': copy.deepcopy(engine._find_card(event_source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    if damage_reduction:
        engine.engine_state.setdefault('replacements', []).append({
            'op': 'modify_damage', 'kind': 'damage', 'player': other,
            'amount': -100, 'duration': 'continuous',
            'controller': other, 'source': 'review-light-lumen',
        })

    decisions = []

    def drain_decisions():
        for _step in range(30):
            decision = copy.deepcopy(
                engine.engine_state.get('pending_decision') or {},
            )
            if not decision:
                break
            options = decision.get('options') or []
            selected = None
            if decision.get('kind') == 'effect_order':
                preferred = next((
                    option for option in options
                    if option.get('ability_id')
                    == 'review-black-feather-create-combo-token'
                ), None)
                selected = (preferred or sorted(
                    options, key=lambda item: (
                        str(item.get('ability_id') or ''),
                        str(item.get('id') or ''),
                    ),
                )[0]).get('id')
            elif decision.get('kind') == 'optional_effect':
                selected = 'accept' if accept_optional else 'decline'
            elif decision.get('kind') == 'effect_choice' and options:
                selected = sorted(
                    options, key=lambda item: str(item.get('id') or ''),
                )[0].get('id')
            else:
                break
            decisions.append({
                'kind': decision.get('kind'),
                'ability_ids': sorted(
                    str(option.get('ability_id')) for option in options
                    if option.get('ability_id')
                ),
                'selected': selected,
            })
            engine._submit_decision(
                decision.get('owner'), decision.get('id'), [selected],
            )
            engine._continue()

    def fire_once():
        controller_entry = engine.engine_state['battle'][event_controller]
        opposing_entry = engine.engine_state['battle'][
            'p2' if event_controller == 'p1' else 'p1'
        ]
        engine._fire(event_type, {
            'controller': event_controller,
            'source_card_instance_id': controller_entry['instance_id'],
            'source_card': copy.deepcopy(controller_entry['card']),
            'opponent_card': copy.deepcopy(opposing_entry['card']),
            'source_battle_card_only': True,
        })
        drain_decisions()

    before_hp = int(engine.state['players'][other]['hp'])
    fire_once()
    if repeat_combo:
        fire_once()
    live_opposing = engine.engine_state['battle'][other]['card']
    lumen_cards = engine._zone(owner, 'lumen')
    side_cards = engine._zone(owner, 'side')
    return {
        'resolved_abilities': [
            (event.get('payload') or {}).get('ability_id')
            for event in engine.events
            if event.get('type') == 'effect_resolved'
            and str((event.get('payload') or {}).get('ability_id') or '')
            .startswith('lmi-at-041')
        ],
        'decisions': decisions,
        'optional_count': sum(
            decision.get('kind') == 'optional_effect'
            for decision in decisions
        ),
        'side_feathers': sum(
            card.get('code') == 'LMI-AT-041' for card in side_cards
        ),
        'lumen_feathers': sum(
            card.get('code') == 'LMI-AT-041' for card in lumen_cards
        ),
        'dagger_count': sum(
            card.get('token_key') == 'dagger' for card in lumen_cards
        ),
        'side_dagger_count': sum(
            card.get('token_key') == 'dagger' for card in side_cards
        ),
        'dagger_types': sorted(
            str(card.get('type') or '') for card in lumen_cards
            if card.get('token_key') == 'dagger'
        ),
        'opponent_damage': engine.card_stat(
            live_opposing, 'damage', other, include_fp=False,
        ),
        'opponent_hp_loss': before_hp - int(
            engine.state['players'][other]['hp']
        ),
        'damage_amounts': [
            (event.get('payload') or {}).get('amount')
            for event in engine.events
            if event.get('type') == 'damage_dealt'
        ],
        'creation_skipped': any(
            event.get('type') in {'token_creation_skipped', 'card_move_skipped'}
            for event in engine.events
        ),
        'break_count': len(engine._zone(owner, 'break')),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_041_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-041':
        return None
    qna_ids = [
        202, 250, 451, 452, 453, 501, 525, 543, 597, 617,
        634, 639, 650, 663, 674,
    ]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    deploy = by_id.get('lmi-at-041-side-placement')
    clash = by_id.get('lmi-at-041-clash')
    combo = by_id.get('lmi-at-041-dark-night-combo')
    own_event = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'controller': True},
    }
    dark_combo = {
        'op': 'all',
        'conditions': [
            copy.deepcopy(own_event),
            {
                'op': 'has_state', 'player': {'controller': True},
                'state': 'dark_night',
            },
            {
                'op': 'zone_count', 'player': {'controller': True},
                'zone': 'lumen', 'min': 1,
                'where': {'token_key': 'dagger'},
            },
        ],
    }
    expected_dagger_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['lumen'], 'all': True,
        'where': {'token_key': 'dagger'},
    }
    valid = bool(
        extra_root == {'deck_limit'} and definition.get('deck_limit') == 2
        and len(abilities) == 3
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and deploy and deploy.get('kind') == 'function'
        and deploy.get('mode') == 'optional'
        and deploy.get('timing') == 'clash'
        and deploy.get('visibility') == 'private'
        and deploy.get('active_zones') == ['side']
        and deploy.get('trigger') == {'event': 'clash'}
        and deploy.get('condition') == own_event
        and deploy.get('dedupe_trigger_key') == 'lmi-at-041-side-placement'
        and deploy.get('limit') == {
            'scope': 'turn', 'max': 1,
            'key': 'lmi-at-041-side-placement',
        }
        and len(deploy.get('effects') or []) == 1
        and (deploy.get('effects') or [{}])[0].get('op') == 'request_choice'
        and ((deploy.get('effects') or [{}])[0].get('selector') or {}).get('where')
        == {'code': 'LMI-AT-041'}
        and [item.get('op') for item in (
            (deploy.get('effects') or [{}])[0].get('then') or []
        )] == ['move_card']
        and clash and clash.get('kind') == 'effect'
        and clash.get('mode') == 'mandatory'
        and clash.get('timing') == 'clash'
        and clash.get('active_zones') == ['lumen']
        and clash.get('trigger') == {'event': 'clash'}
        and clash.get('condition') == own_event
        and [effect.get('op') for effect in clash.get('effects') or []]
        == ['modify_stat', 'move_card']
        and (clash.get('effects') or [{}, {}])[0] == {
            'op': 'modify_stat', 'player': {'opponent': True},
            'stat': 'damage', 'amount': -100, 'duration': 'battle',
        }
        and (clash.get('effects') or [{}, {}])[1].get('to_zone') == 'lumen'
        and (clash.get('effects') or [{}, {}])[1].get('max_zone_count') == 6
        and (((clash.get('effects') or [{}, {}])[1].get('selector') or {})
             .get('where')) == {'token_key': 'dagger'}
        and combo and combo.get('kind') == 'effect'
        and combo.get('mode') == 'optional'
        and combo.get('timing') == 'combo'
        and combo.get('active_zones') == ['lumen']
        and combo.get('trigger') == {
            'event': 'combo', 'events': ['combo', 'combo_window'],
        }
        and combo.get('condition') == dark_combo
        and combo.get('recheck_condition') is True
        and [effect.get('op') for effect in combo.get('effects') or []]
        == ['capture_selection', 'delete_token', 'deal_damage']
        and (combo.get('effects') or [{}])[0].get('selector')
        == expected_dagger_selector
        and (combo.get('effects') or [{}, {}, {}])[1].get('selection_key')
        == 'lmi_at_041_all_daggers'
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-041', False,
                reason='배치·상쇄·단검 상한·암야 콤보 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-041 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    groups = {key: [] for key in ('deploy', 'clash', 'combo')}

    def add(group, name, owner, kwargs, assertion):
        first = _run_lmi_at_041_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_041_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        groups[group].append({
            'name': name,
            'passed': bool(
                deterministic and assertion(first) and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    deploy_only = {
        'ability_ids': ['lmi-at-041-side-placement'], 'lumen_count': 0,
    }
    add('deploy', 'owner-p1-accepts-side-deployment', 'p1', {
        **deploy_only, 'side_count': 1,
    }, lambda value: value['side_feathers'] == 0 and value['lumen_feathers'] == 1)
    add('deploy', 'owner-p2-accepts-side-deployment', 'p2', {
        **deploy_only, 'side_count': 1,
    }, lambda value: value['side_feathers'] == 0 and value['lumen_feathers'] == 1)
    add('deploy', 'qna-501-two-copies-share-one-turn-limit', 'p1', {
        **deploy_only, 'side_count': 2,
    }, lambda value: (
        value['side_feathers'] == 1 and value['lumen_feathers'] == 1
        and value['optional_count'] == 1
    ))
    add('deploy', 'declining-keeps-side-card-hidden', 'p2', {
        **deploy_only, 'side_count': 1, 'accept_optional': False,
    }, lambda value: value['side_feathers'] == 1 and value['lumen_feathers'] == 0)
    add('deploy', 'wrong-trigger-does-not-deploy', 'p1', {
        **deploy_only, 'side_count': 1, 'event_type': 'hit',
    }, lambda value: value['side_feathers'] == 1 and value['optional_count'] == 0)

    clash_only = {'ability_ids': ['lmi-at-041-clash']}
    add('clash', 'owner-p1-reduces-damage-and-moves-one-dagger', 'p1', {
        **clash_only, 'side_dagger_count': 1,
    }, lambda value: (
        value['opponent_damage'] == 500 and value['dagger_count'] == 1
        and value['side_dagger_count'] == 0
    ))
    add('clash', 'qna-202-two-feathers-stack-and-move-two-daggers', 'p2', {
        **clash_only, 'lumen_count': 2, 'side_dagger_count': 2,
    }, lambda value: (
        value['opponent_damage'] == 400 and value['dagger_count'] == 2
        and value['side_dagger_count'] == 0
    ))
    add('clash', 'qna-202-global-six-cap-leaves-second-dagger-in-side', 'p1', {
        **clash_only, 'lumen_count': 2, 'dagger_count': 5,
        'side_dagger_count': 2,
    }, lambda value: (
        value['dagger_count'] == 6 and value['side_dagger_count'] == 1
        and value['creation_skipped']
    ))
    add('clash', 'opponent-clash-event-does-not-trigger-owner-feather', 'p1', {
        **clash_only, 'event_controller': 'p2', 'side_dagger_count': 1,
    }, lambda value: (
        value['opponent_damage'] == 600 and value['dagger_count'] == 0
        and value['side_dagger_count'] == 1
    ))
    add('clash', 'numbered-negation-suppresses-both-bullets', 'p2', {
        **clash_only, 'numbered_effects_negated': True,
        'side_dagger_count': 1,
    }, lambda value: (
        value['opponent_damage'] == 600 and value['dagger_count'] == 0
        and value['side_dagger_count'] == 1
    ))
    add('clash', 'qna-451-newly-deployed-copy-misses-current-clash', 'p1', {
        'side_count': 1, 'lumen_count': 1, 'side_dagger_count': 1,
    }, lambda value: (
        value['lumen_feathers'] == 2 and value['opponent_damage'] == 500
        and value['dagger_count'] == 1
    ))
    add('clash', 'qna-543-physical-dagger-remains-non-technique-token', 'p1', {
        **clash_only, 'side_dagger_count': 1,
    }, lambda value: (
        value['dagger_types'] == ['토큰'] and value['break_count'] == 0
    ))

    combo_only = {
        'ability_ids': ['lmi-at-041-dark-night-combo'],
        'event_type': 'combo',
    }
    add('combo', 'three-daggers-delete-for-single-two-hundred-damage', 'p1', {
        **combo_only, 'dagger_count': 3, 'dark_night': True,
    }, lambda value: (
        value['dagger_count'] == 0 and value['opponent_hp_loss'] == 200
        and value['damage_amounts'] == [200] and value['break_count'] == 0
    ))
    add('combo', 'qna-525-six-daggers-deal-one-four-hundred-hit-reduced-once', 'p2', {
        **combo_only, 'dagger_count': 6, 'dark_night': True,
        'damage_reduction': True,
    }, lambda value: (
        value['dagger_count'] == 0 and value['opponent_hp_loss'] == 300
        and value['damage_amounts'] == [300]
    ))
    add('combo', 'two-daggers-may-be-deleted-for-zero-damage', 'p1', {
        **combo_only, 'dagger_count': 2, 'dark_night': True,
    }, lambda value: value['dagger_count'] == 0 and value['opponent_hp_loss'] == 0)
    add('combo', 'declining-keeps-all-daggers', 'p2', {
        **combo_only, 'dagger_count': 3, 'dark_night': True,
        'accept_optional': False,
    }, lambda value: value['dagger_count'] == 3 and value['opponent_hp_loss'] == 0)
    add('combo', 'without-dark-night-offers-no-effect', 'p1', {
        **combo_only, 'dagger_count': 3,
    }, lambda value: value['optional_count'] == 0 and value['dagger_count'] == 3)
    add('combo', 'qna-639-sibling-combo-effect-creates-third-dagger-first', 'p2', {
        **combo_only, 'dagger_count': 2, 'dark_night': True,
        'support_combo_token': True,
    }, lambda value: value['dagger_count'] == 0 and value['opponent_hp_loss'] == 200)
    add('combo', 'qna-663-optional-effect-is-offered-at-each-combo-event', 'p1', {
        **combo_only, 'dagger_count': 3, 'dark_night': True,
        'accept_optional': False, 'repeat_combo': True,
    }, lambda value: value['optional_count'] == 2 and value['dagger_count'] == 3)
    add('combo', 'numbered-negation-suppresses-dark-night-combo', 'p2', {
        **combo_only, 'dagger_count': 3, 'dark_night': True,
        'numbered_effects_negated': True,
    }, lambda value: value['optional_count'] == 0 and value['dagger_count'] == 3)

    reviews = [
        AbilityReview(
            deploy['id'], all(item['passed'] for item in groups['deploy']),
            groups['deploy'],
            '' if all(item['passed'] for item in groups['deploy'])
            else '검은 깃털의 사이드 배치·공유 턴 제한 검증에 실패했습니다.',
        ),
        AbilityReview(
            clash['id'], all(item['passed'] for item in groups['clash']),
            groups['clash'],
            '' if all(item['passed'] for item in groups['clash'])
            else '검은 깃털의 상쇄 데미지·단검 이동·전역 상한 검증에 실패했습니다.',
        ),
        AbilityReview(
            combo['id'], all(item['passed'] for item in groups['combo']),
            groups['combo'],
            '' if all(item['passed'] for item in groups['combo'])
            else '검은 깃털의 암야 콤보·단일 데미지 검증에 실패했습니다.',
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '검은 깃털의 카드별 Q&A 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_lmi_at_043_break_scenario(
    definition, card_snapshot, owner, *, break_source=True,
    numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-butterfly-break-source', 'owner': owner,
        'type': '공격', 'frame': 8, 'damage': 300,
        'face_up': True,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    target = _card(
        'REVIEW-BUTTERFLY-OTHER', owner,
        f'{owner}-butterfly-other',
    )
    opposing = _card(
        'REVIEW-BUTTERFLY-OPPONENT', other,
        f'{other}-butterfly-opponent',
    )
    no_effect = _st1_001_no_effect_definition()
    state = _state(source, opposing, owner, source_zone='list')
    state['players'][owner]['zones']['list'].append(copy.deepcopy(target))
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': definition,
                },
                target['code']: {
                    **copy.deepcopy(target), 'effect_definition': no_effect,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'butterfly-break:{owner}:{break_source}:'
            f'{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    before_fp = int(engine.state['players'][owner]['fp'])
    broken_id = source['instance_id'] if break_source else target['instance_id']
    engine.break_card(
        broken_id, reason='review',
        effect_controller=other, effect_source=opposing['instance_id'],
    )
    decision = engine.engine_state.get('pending_decision') or {}
    if decision.get('kind') == 'break_replenish':
        engine._submit_decision(
            decision.get('owner'), decision.get('id'), ['decline'],
        )
        engine._continue()
    return {
        'before_fp': before_fp,
        'after_fp': int(engine.state['players'][owner]['fp']),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'other_zone': engine._find_location(target['instance_id'])[1],
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-043-n1'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_043_combo_scenario(
    definition, card_snapshot, owner, *, combo_number=2,
    previous_character='tao', previous_pos='하단', previous_speed=10,
    harmony=False, numbered_effects_negated=False, execute=False,
    propose_followup=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-butterfly-combo-source', 'owner': owner,
        'type': '공격', 'frame': 8, 'damage': 300, 'pos': '상단',
        'special': '그랩', 'hit': '3', 'face_up': False,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    starter = _card(
        'REVIEW-BUTTERFLY-STARTER', owner,
        f'{owner}-butterfly-starter',
    )
    starter.update({
        'character_key': previous_character,
        'pos': previous_pos, 'frame': previous_speed,
    })
    previous = _card(
        'REVIEW-BUTTERFLY-PREVIOUS', owner,
        f'{owner}-butterfly-previous',
    )
    previous.update({
        'character_key': previous_character,
        'pos': previous_pos, 'frame': previous_speed,
    })
    followup = _card(
        'REVIEW-BUTTERFLY-FOLLOWUP', owner,
        f'{owner}-butterfly-followup',
    )
    followup.update({'frame': 9, 'damage': 500})
    opposing = _card(
        'REVIEW-BUTTERFLY-COMBO-OPPONENT', other,
        f'{other}-butterfly-combo-opponent',
    )
    no_effect = _st1_001_no_effect_definition()
    state = _state(source, opposing, owner, source_zone='hand')
    state['players'][owner]['zones']['battle'] = [copy.deepcopy(starter)]
    state['players'][owner]['zones']['hand'].append(copy.deepcopy(followup))
    used = []
    if combo_number >= 3:
        state['players'][owner]['zones']['list'].append(copy.deepcopy(previous))
        used = [previous['instance_id']]
    if harmony:
        state['players'][owner]['passive_state']['harmony'] = {
            'value': True, 'label': '조화',
        }
    cards = [source, starter, previous, followup, opposing]
    ruleset_cards = {
        card['code']: {
            **copy.deepcopy(card),
            'effect_definition': (
                copy.deepcopy(definition) if card is source
                else copy.deepcopy(no_effect)
            ),
        }
        for card in cards
    }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'butterfly-combo:{owner}:{combo_number}:{previous_character}:'
            f'{previous_pos}:{previous_speed}:{harmony}:'
            f'{numbered_effects_negated}:{execute}:{propose_followup}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': starter['instance_id'],
            'card': copy.deepcopy(engine._find_card(starter['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    engine.engine_state['combo'] = {
        'owner': owner, 'source': starter['instance_id'], 'special': False,
        'used': list(used),
        'next_penalty': 100 if combo_number == 2 else 200,
        'last_speed': previous_speed,
        'proposal_submitted': False,
    }
    engine.engine_state['step'] = 'combo'
    if propose_followup:
        engine.engine_state.setdefault('modifiers', []).append({
            'op': 'modify_combo', 'player': owner, 'controller': owner,
            'max_combo': 4, 'duration': 'battle',
            'source': 'review-butterfly-extension',
        })
    actions = engine.legal_actions(owner)

    def action_ids(action):
        payload = action.get('payload') or {}
        return list(payload.get('card_instance_ids') or [
            payload.get('card_instance_id'),
        ])

    source_actions = [
        action for action in actions
        if source['instance_id'] in action_ids(action)
        and action_ids(action)[0] == source['instance_id']
    ]
    pair = next((
        action for action in source_actions
        if action_ids(action) == [
            source['instance_id'], followup['instance_id'],
        ]
    ), None)
    single = next((
        action for action in source_actions
        if action_ids(action) == [source['instance_id']]
    ), None)
    selected_action = pair if propose_followup else single
    if execute and selected_action:
        engine.submit_action(
            owner, selected_action['action_id'], {},
            command_id=f'butterfly-combo-{owner}',
        )
    used_ids = [
        (event.get('payload') or {}).get('card_instance_id')
        for event in engine.events if event.get('type') == 'combo_card_used'
    ]
    source_damage = next((
        (event.get('payload') or {}).get('damage')
        for event in engine.events
        if event.get('type') == 'combo_card_used'
        and (event.get('payload') or {}).get('card_instance_id')
        == source['instance_id']
    ), None)
    scheduled_before_recovery = len(engine.engine_state.get('scheduled') or [])
    fp_before_recovery = int(engine.state['players'][owner]['fp'])
    engine.state['phase'] = 'recovery'
    engine._fire('phase_start', {'phase': 'recovery'})
    engine._continue()
    fp_after_recovery = int(engine.state['players'][owner]['fp'])
    engine._fire('phase_start', {'phase': 'recovery'})
    engine._continue()
    return {
        'source_legal': bool(source_actions),
        'single_legal': bool(single), 'pair_legal': bool(pair),
        'source_speed_options': sorted({
            (action.get('payload') or {}).get('combo_speed')
            for action in source_actions
            if (action.get('payload') or {}).get('combo_speed') is not None
        }),
        'used_ids': used_ids, 'source_damage': source_damage,
        'combo_ended': any(
            event.get('type') == 'combo_ended' for event in engine.events
        ),
        'harmony_resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-043-n3'
            for event in engine.events
        ),
        'scheduled_before_recovery': scheduled_before_recovery,
        'scheduled_after_recovery': len(engine.engine_state.get('scheduled') or []),
        'fp_before_recovery': fp_before_recovery,
        'fp_after_recovery': fp_after_recovery,
        'fp_after_second_recovery': int(engine.state['players'][owner]['fp']),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_043_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-043':
        return None
    qna_ids = [227, 489]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    broken = by_id.get('lmi-at-043-n1')
    speed_rule = by_id.get('lmi-at-043-n2')
    harmony_combo = by_id.get('lmi-at-043-n3')
    harmony_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'harmony',
    }
    expected_rules = [
        {
            'ignore_speed': True,
            'after_where': {'character_key': 'tao', 'pos': '하단'},
            'numbered_effect': True,
        },
        {
            'min_combo': 3, 'ignore_damage_penalty': True,
            'end_after_use': True, 'numbered_effect': True,
            'condition': copy.deepcopy(harmony_condition),
        },
    ]
    expected_schedule = [{
        'op': 'schedule',
        'when': {'event': 'phase_start', 'phase': 'recovery'},
        'duration': 'turn',
        'effect': {
            'op': 'change_fp', 'player': {'controller': True}, 'amount': 2,
        },
    }]
    valid = bool(
        extra_root == {'combo_rules'} and len(abilities) == 3
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and definition.get('combo_rules') == expected_rules
        and broken and speed_rule and harmony_combo
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and broken.get('mode') == 'mandatory'
        and broken.get('trigger') == {'event': 'card_broken'}
        and broken.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True}, 'amount': 1,
        }]
        and speed_rule.get('kind') == 'function'
        and speed_rule.get('mode') == 'continuous'
        and speed_rule.get('trigger') is None
        and speed_rule.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and harmony_combo.get('mode') == 'mandatory'
        and harmony_combo.get('trigger') == {'event': 'combo'}
        and harmony_combo.get('condition') == harmony_condition
        and harmony_combo.get('effects') == expected_schedule
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-043', False,
                reason='화접의 브레이크·콤보·조화 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-043 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    break_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-broken-gains-one-fp', 'p1', {}, True),
        ('owner-p2-qna-227-external-break-gains-one-fp', 'p2', {}, True),
        ('another-card-break-does-not-trigger', 'p1', {'break_source': False}, False),
        ('numbered-negation-suppresses-break-gain', 'p2', {
            'numbered_effects_negated': True,
        }, False),
    ):
        first = _run_lmi_at_043_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_043_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        break_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and first['resolved'] is expected
                and first['after_fp']
                == first['before_fp'] + (1 if expected else 0)
            ),
            'deterministic': deterministic, **first,
        })

    speed_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-tao-low-ignores-speed-order', 'p1', {}, True),
        ('owner-p2-tao-middle-does-not-ignore-speed', 'p2', {
            'previous_pos': '중단',
        }, False),
        ('non-tao-low-does-not-ignore-speed', 'p1', {
            'previous_character': 'other',
        }, False),
        ('numbered-negation-removes-speed-exception', 'p2', {
            'numbered_effects_negated': True,
        }, False),
    ):
        first = _run_lmi_at_043_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_043_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        speed_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['source_legal'] is expected
                and (8 in first['source_speed_options']) is expected
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    harmony_specs = (
        ('qna-489-harmony-cannot-use-at-two-combo', 'p1', {
            'harmony': True,
        }, 'blocked'),
        ('owner-p1-third-combo-ignores-penalty-ends-and-schedules', 'p1', {
            'combo_number': 3, 'previous_speed': 7, 'harmony': True,
            'execute': True, 'propose_followup': True,
        }, 'resolved'),
        ('owner-p2-third-combo-ignores-penalty-ends-and-schedules', 'p2', {
            'combo_number': 3, 'previous_speed': 7, 'harmony': True,
            'execute': True, 'propose_followup': True,
        }, 'resolved'),
        ('without-harmony-followup-resolves-and-no-fp-is-scheduled', 'p1', {
            'combo_number': 3, 'previous_speed': 7,
            'execute': True, 'propose_followup': True,
        }, 'ordinary'),
        ('numbered-negation-disables-harmony-rule-and-schedule', 'p2', {
            'harmony': True, 'numbered_effects_negated': True,
            'previous_speed': 7,
        }, 'ordinary-two'),
    )
    harmony_scenarios = []
    for name, owner, kwargs, expected in harmony_specs:
        first = _run_lmi_at_043_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_043_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        if expected == 'blocked':
            outcome_ok = bool(
                not first['source_legal'] and not first['harmony_resolved']
                and first['scheduled_before_recovery'] == 0
            )
        elif expected == 'resolved':
            outcome_ok = bool(
                first['pair_legal']
                and first['used_ids'] == [f'{owner}-butterfly-combo-source']
                and first['source_damage'] == 300 and first['combo_ended']
                and first['harmony_resolved']
                and first['scheduled_before_recovery'] == 1
                and first['fp_after_recovery']
                == first['fp_before_recovery'] + 2
                and first['fp_after_second_recovery']
                == first['fp_after_recovery']
                and first['scheduled_after_recovery'] == 0
            )
        elif expected == 'ordinary':
            outcome_ok = bool(
                first['pair_legal']
                and first['used_ids'] == [
                    f'{owner}-butterfly-combo-source',
                    f'{owner}-butterfly-followup',
                ]
                and first['source_damage'] == 100
                and not first['harmony_resolved']
                and first['scheduled_before_recovery'] == 0
                and first['fp_after_recovery'] == first['fp_before_recovery']
            )
        else:
            outcome_ok = bool(
                first['source_legal'] and not first['harmony_resolved']
                and first['scheduled_before_recovery'] == 0
            )
        harmony_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and outcome_ok and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            broken['id'], all(item['passed'] for item in break_scenarios),
            break_scenarios,
            '' if all(item['passed'] for item in break_scenarios)
            else '화접의 브레이크 시 FP 획득 검증에 실패했습니다.',
        ),
        AbilityReview(
            speed_rule['id'], all(item['passed'] for item in speed_scenarios),
            speed_scenarios,
            '' if all(item['passed'] for item in speed_scenarios)
            else '화접의 타오 하단 콤보 속도 예외 검증에 실패했습니다.',
        ),
        AbilityReview(
            harmony_combo['id'],
            all(item['passed'] for item in harmony_scenarios),
            harmony_scenarios,
            '' if all(item['passed'] for item in harmony_scenarios)
            else '화접의 조화 3콤보·종료·리커버리 예약 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        item.passed and len(item.scenarios) >= 3 for item in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '화접의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_lmi_at_044_event_scenario(
    definition, card_snapshot, owner, ability_id, *, event_type,
    yin=0, yang=0, selected_option=None, numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-wave-cannon', 'owner': owner,
        'type': '공격', 'frame': 10, 'damage': 400,
        'face_up': True,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-WAVE-CANNON-OPPONENT', other,
        f'{other}-wave-cannon-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == ability_id
    ]
    state = _state(source, opposing, owner)
    state['players'][owner]['passive_state'].update({
        'yin': {'count': yin, 'label': '음'},
        'yang': {'count': yang, 'label': '양'},
    })
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'wave-cannon:{owner}:{ability_id}:{event_type}:{yin}:{yang}:'
            f'{selected_option}:{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    option_ids = [
        str(option.get('id')) for option in decision.get('options') or []
    ]
    if decision.get('kind') == 'effect_branch' and selected_option:
        engine._submit_decision(
            decision.get('owner'), decision.get('id'), [selected_option],
        )
        engine._continue()
    passive = engine.state['players'][owner]['passive_state']
    return {
        'yin_before': yin, 'yang_before': yang,
        'yin_after': int((passive.get('yin') or {}).get('count') or 0),
        'yang_after': int((passive.get('yang') or {}).get('count') or 0),
        'decision_kind': decision.get('kind'),
        'decision_owner': decision.get('owner'),
        'option_ids': option_ids,
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == ability_id
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_044_harmony_scenario(
    definition, card_snapshot, owner, *, harmony=False,
    numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-wave-cannon-harmony', 'owner': owner,
        'type': '공격', 'frame': 10, 'damage': 400,
        'face_up': True,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    sibling = _card(
        'REVIEW-WAVE-CANNON-SIBLING', owner,
        f'{owner}-wave-cannon-sibling',
    )
    sibling.update({'damage': 400})
    opposing = _card(
        'REVIEW-WAVE-CANNON-HARMONY-OPPONENT', other,
        f'{other}-wave-cannon-harmony-opponent',
    )
    isolated = copy.deepcopy(definition)
    isolated['abilities'] = [
        copy.deepcopy(ability)
        for ability in definition.get('abilities') or []
        if ability.get('id') == 'lmi-at-044-n3'
    ]
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['hand'].append(copy.deepcopy(sibling))
    if harmony:
        state['players'][owner]['passive_state']['harmony'] = {
            'value': True, 'label': '조화',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': isolated,
                },
                sibling['code']: {
                    **copy.deepcopy(sibling), 'effect_definition': no_effect,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'wave-cannon-harmony:{owner}:{harmony}:{numbered_effects_negated}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._refresh_continuous_rules()
    live_source = engine._find_card(source['instance_id'])
    live_sibling = engine._find_card(sibling['instance_id'])
    return {
        'source_damage': engine.card_stat(live_source, 'damage', owner),
        'sibling_damage': engine.card_stat(live_sibling, 'damage', owner),
        'modifier_count': sum(
            modifier.get('source') == source['instance_id']
            and modifier.get('stat') == 'damage'
            for modifier in engine.engine_state.get('modifiers') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_044_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-044':
        return None
    qna_ids = [212, 428, 429]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    spend = by_id.get('lmi-at-044-n1')
    gain = by_id.get('lmi-at-044-n2')
    harmony_damage = by_id.get('lmi-at-044-n3')
    harmony_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'harmony',
    }
    expected_spend = [
        {
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'yin', 'amount': -1, 'min': 0,
        },
        {
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'yang', 'amount': -1, 'min': 0,
        },
    ]
    gain_effect = (gain.get('effects') or [{}])[0] if gain else {}
    valid = bool(
        not extra_root and len(abilities) == 3
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and spend and gain and harmony_damage
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and spend.get('mode') == 'mandatory'
        and spend.get('trigger') == {'event': 'use'}
        and spend.get('effects') == expected_spend
        and spend.get('availability_selector') is None
        and gain.get('mode') == 'mandatory'
        and gain.get('trigger') == {'event': 'hit'}
        and gain_effect.get('op') == 'choose_effect'
        and gain_effect.get('default') == 'yin_2'
        and [
            option.get('id') for option in gain_effect.get('options') or []
        ] == ['yin_2', 'yang_2']
        and (gain_effect.get('options') or [{}, {}])[0].get('effects') == [{
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'yin', 'amount': 2, 'min': 0, 'max': 4,
        }]
        and (gain_effect.get('options') or [{}, {}])[1].get('effects') == [{
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'yang', 'amount': 2, 'min': 0, 'max': 4,
        }]
        and harmony_damage.get('mode') == 'continuous'
        and harmony_damage.get('condition') == harmony_condition
        and harmony_damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': 100, 'duration': 'continuous',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-044', False,
                reason='파동포요권의 카운터·조화 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-044 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    spend_specs = (
        ('owner-p1-removes-one-of-each', 'p1', 'use', 3, 2, False, (2, 1, True)),
        ('owner-p2-qna-212-removes-existing-yin-only', 'p2', 'use', 1, 0, False, (0, 0, True)),
        ('qna-428-zero-counters-do-not-block-use-effect', 'p1', 'use', 0, 0, False, (0, 0, True)),
        ('wrong-trigger-does-not-spend', 'p2', 'hit', 2, 2, False, (2, 2, False)),
        ('numbered-negation-does-not-spend', 'p1', 'use', 2, 2, True, (2, 2, False)),
    )
    spend_scenarios = []
    for name, owner, event_type, yin, yang, negated, expected in spend_specs:
        kwargs = {
            'event_type': event_type, 'yin': yin, 'yang': yang,
            'numbered_effects_negated': negated,
        }
        first = _run_lmi_at_044_event_scenario(
            definition, card_snapshot, owner, 'lmi-at-044-n1', **kwargs,
        )
        second = _run_lmi_at_044_event_scenario(
            definition, card_snapshot, owner, 'lmi-at-044-n1', **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        spend_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and (first['yin_after'], first['yang_after'], first['resolved'])
                == expected and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    gain_specs = (
        ('owner-p1-chooses-two-yin', 'p1', 'hit', 'yin_2', 1, 1, (3, 1, True)),
        ('owner-p2-chooses-two-yang', 'p2', 'hit', 'yang_2', 1, 1, (1, 3, True)),
        ('qna-429-split-choice-is-not-offered', 'p1', 'hit', 'yin_2', 1, 1, (3, 1, True)),
        ('counter-result-does-not-offer-hit-effect', 'p2', 'counter', None, 1, 1, (1, 1, False)),
        ('counter-cap-four-is-enforced', 'p1', 'hit', 'yin_2', 3, 1, (4, 1, True)),
    )
    gain_scenarios = []
    for name, owner, event_type, selected, yin, yang, expected in gain_specs:
        kwargs = {
            'event_type': event_type, 'yin': yin, 'yang': yang,
            'selected_option': selected,
        }
        first = _run_lmi_at_044_event_scenario(
            definition, card_snapshot, owner, 'lmi-at-044-n2', **kwargs,
        )
        second = _run_lmi_at_044_event_scenario(
            definition, card_snapshot, owner, 'lmi-at-044-n2', **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        choice_ok = (
            first['option_ids'] == ['yin_2', 'yang_2']
            if event_type == 'hit' else first['option_ids'] == []
        )
        gain_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and choice_ok
                and (first['yin_after'], first['yang_after'], first['resolved'])
                == expected and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    harmony_scenarios = []
    for name, owner, harmony, negated, expected_damage in (
        ('owner-p1-harmony-adds-one-hundred', 'p1', True, False, 500),
        ('owner-p2-harmony-adds-one-hundred', 'p2', True, False, 500),
        ('without-harmony-keeps-printed-damage', 'p1', False, False, 400),
        ('numbered-negation-removes-harmony-bonus', 'p2', True, True, 400),
    ):
        first = _run_lmi_at_044_harmony_scenario(
            definition, card_snapshot, owner,
            harmony=harmony, numbered_effects_negated=negated,
        )
        second = _run_lmi_at_044_harmony_scenario(
            definition, card_snapshot, owner,
            harmony=harmony, numbered_effects_negated=negated,
        )
        deterministic = _canonical(first) == _canonical(second)
        harmony_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['source_damage'] == expected_damage
                and first['sibling_damage'] == 400 and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            spend['id'], all(item['passed'] for item in spend_scenarios),
            spend_scenarios,
            '' if all(item['passed'] for item in spend_scenarios)
            else '파동포요권의 음·양 강제 제거 검증에 실패했습니다.',
        ),
        AbilityReview(
            gain['id'], all(item['passed'] for item in gain_scenarios),
            gain_scenarios,
            '' if all(item['passed'] for item in gain_scenarios)
            else '파동포요권의 히트 카운터 선택 검증에 실패했습니다.',
        ),
        AbilityReview(
            harmony_damage['id'],
            all(item['passed'] for item in harmony_scenarios),
            harmony_scenarios,
            '' if all(item['passed'] for item in harmony_scenarios)
            else '파동포요권의 조화 자체 데미지 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        item.passed and len(item.scenarios) >= 3 for item in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '파동포요권의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_lmi_at_045_defense_scenario(
    definition, card_snapshot, owner, *, printed_speed, fixed_speed=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-dodge-roll-defense', 'owner': owner,
        'type': '수비', 'frame': None, 'damage': None,
        'g_top': '회피', 'g_mid': '', 'g_bot': '', 'face_up': True,
    })
    attack = _card(
        'REVIEW-DODGE-ROLL-ATTACK', other,
        f'{other}-dodge-roll-attack',
    )
    attack.update({'frame': printed_speed, 'pos': '상단', 'damage': 400})
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, attack, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': definition,
                },
                attack['code']: {
                    **copy.deepcopy(attack), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'dodge-roll-defense:{owner}:{printed_speed}:{fixed_speed}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if fixed_speed is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': other,
            'source': attack['instance_id'],
            'where': {'instance_id': attack['instance_id']},
            'stat': 'frame', 'value': fixed_speed, 'duration': 'battle',
        })
    result = engine._attack_vs_defense(
        engine._find_card(attack['instance_id']),
        engine._find_card(source['instance_id']),
        other, owner,
    )
    return {
        'printed_speed': printed_speed,
        'reference_speed': engine.card_stat(
            engine._find_card(attack['instance_id']), 'frame', other,
            include_fp=False,
        ),
        'result': list(result),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_045_catch_scenario(
    definition, card_snapshot, owner, *, yang=1, harmony=False,
    event_type='dodge', resolve=None, caught_combo=False,
    selected_index=0, acquired_count=2, numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-dodge-roll-source', 'owner': owner,
        'type': '수비', 'frame': None, 'damage': None,
        'g_top': '회피', 'g_mid': '', 'g_bot': '', 'face_up': True,
    })
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-DODGE-ROLL-OPPONENT', other,
        f'{other}-dodge-roll-opponent',
    )
    opposing.update({'pos': '상단', 'frame': 7, 'damage': 300})
    catch_card = _card(
        'REVIEW-DODGE-ROLL-CATCH', owner,
        f'{owner}-dodge-roll-catch',
    )
    catch_card.update({
        'character_key': 'tao', 'frame': 7, 'damage': 300,
        'hit': '콤보' if caught_combo else '+1',
    })
    too_fast = _card(
        'REVIEW-DODGE-ROLL-FAST', owner,
        f'{owner}-dodge-roll-fast',
    )
    too_fast.update({'character_key': 'tao', 'frame': 8})
    wrong_character = _card(
        'REVIEW-DODGE-ROLL-OTHER', owner,
        f'{owner}-dodge-roll-other',
    )
    wrong_character.update({'character_key': 'other', 'frame': 6})
    acquired = []
    for index in range(acquired_count):
        candidate = _card(
            f'REVIEW-DODGE-ROLL-ACQUIRE-{index}', owner,
            f'{owner}-dodge-roll-acquire-{index}',
        )
        candidate.update({
            'character_key': 'tao', 'frame': 8 + index,
            'damage': 400 + (index * 100),
        })
        acquired.append(candidate)
    non_tao_list = _card(
        'REVIEW-DODGE-ROLL-LIST-OTHER', owner,
        f'{owner}-dodge-roll-list-other',
    )
    non_tao_list.update({'character_key': 'other'})
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['hand'] = [
        copy.deepcopy(catch_card), copy.deepcopy(too_fast),
        copy.deepcopy(wrong_character),
    ]
    state['players'][owner]['zones']['list'] = [
        *copy.deepcopy(acquired), copy.deepcopy(non_tao_list),
    ]
    state['players'][owner]['passive_state']['yang'] = {
        'count': yang, 'label': '양',
    }
    if harmony:
        state['players'][owner]['passive_state']['harmony'] = {
            'value': True, 'label': '조화',
        }
    no_effect = _st1_001_no_effect_definition()
    cards = [source, opposing, catch_card, too_fast, wrong_character,
             *acquired, non_tao_list]
    ruleset_cards = {
        card['code']: {
            **copy.deepcopy(card),
            'effect_definition': (
                copy.deepcopy(definition)
                if card['code'] == source['code']
                else copy.deepcopy(no_effect)
            ),
        }
        for card in cards
    }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'dodge-roll-catch:{owner}:{yang}:{harmony}:{event_type}:'
            f'{resolve}:{caught_combo}:{selected_index}:{acquired_count}:'
            f'{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': source['instance_id'],
            'card': copy.deepcopy(engine._find_card(source['instance_id'])),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        },
    }
    live_source = engine._find_card(source['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        'source_only_event': True,
    })
    grants = copy.deepcopy(engine.engine_state.get('granted_catches') or [])
    catch_action_ids = []
    if grants and resolve in {'play', 'decline', 'offer'}:
        engine._open_catch_or_cleanup()
        catch_action_ids = sorted(
            (action.get('payload') or {}).get('card_instance_id')
            for action in engine.legal_actions(owner)
            if action.get('type') == 'play_catch_card'
        )
        if resolve == 'play':
            engine._play_catch(owner, catch_card['instance_id'])
            engine._continue()
        elif resolve == 'decline':
            engine.end_catch()
            engine._continue()
    decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    decision_options = [
        str(option.get('id')) for option in decision.get('options') or []
    ]
    caught_zone_at_choice = engine._find_location(catch_card['instance_id'])[1]
    acquired_zones_at_choice = {
        card['instance_id']: engine._find_location(card['instance_id'])[1]
        for card in acquired
    }
    selected_id = None
    if decision.get('kind') == 'effect_choice' and decision_options:
        selected_id = decision_options[
            min(selected_index, len(decision_options) - 1)
        ]
        engine._submit_decision(owner, decision['id'], [selected_id])
        engine._continue()
    combo_action_card_ids = set()
    if engine.engine_state.get('combo'):
        for action in engine.legal_actions(owner):
            if action.get('type') not in {
                'play_combo_sequence', 'play_combo_pair', 'play_combo_card',
            }:
                continue
            payload = action.get('payload') or {}
            combo_action_card_ids.update(
                payload.get('card_instance_ids')
                or [payload.get('card_instance_id')]
            )
    resolved_ids = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events if event.get('type') == 'effect_resolved'
    ]
    opportunity_events = [
        event.get('payload') or {} for event in engine.events
        if event.get('type') == 'catch_opportunity_resolved'
    ]
    return {
        'yang_before': yang,
        'yang_after': int(
            engine.state['players'][owner]['passive_state']
            .get('yang', {}).get('count') or 0
        ),
        'grant_count': len(grants),
        'grant_max_speed': grants[0].get('max_speed') if grants else None,
        'grant_where': grants[0].get('where') if grants else None,
        'catch_action_ids': catch_action_ids,
        'decision_kind': decision.get('kind'),
        'decision_owner': decision.get('owner'),
        'decision_options': decision_options,
        'selected_id': selected_id,
        'caught_zone_at_choice': caught_zone_at_choice,
        'acquired_zones_at_choice': acquired_zones_at_choice,
        'selected_zone_after': (
            engine._find_location(selected_id)[1] if selected_id else None
        ),
        'combo_started': bool(engine.engine_state.get('combo')),
        'combo_action_card_ids': sorted(
            card_id for card_id in combo_action_card_ids if card_id
        ),
        'n1_resolved': 'lmi-at-045-n1' in resolved_ids,
        'n2_resolved': 'lmi-at-045-n2' in resolved_ids,
        'opportunity_events': opportunity_events,
        'choice_skipped': any(
            event.get('type') == 'effect_choice_skipped'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_045_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-045':
        return None
    qna_ids = [215, 447, 490, 539, 558]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    defense = by_id.get('lmi-at-045-function')
    dodge_catch = by_id.get('lmi-at-045-n1')
    acquire = by_id.get('lmi-at-045-n2')
    expected_counter_condition = {
        'op': 'counter_at_least', 'player': {'controller': True},
        'counter': 'yang', 'value': 1,
    }
    expected_catch_effects = [
        {
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'yang', 'amount': -1, 'min': 0,
        },
        {
            'op': 'grant_catch', 'player': {'controller': True},
            'allow_zones': ['hand'], 'max_speed': 7,
            'where': {'is_technique': True, 'character_key': 'tao'},
        },
    ]
    acquire_effect = (acquire.get('effects') or [{}])[0] if acquire else {}
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 3
        and definition.get('defense_rules') == [{'max_speed': 9}]
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and defense and dodge_catch and acquire
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and defense.get('kind') == 'function'
        and defense.get('mode') == 'continuous'
        and defense.get('trigger') is None
        and defense.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and dodge_catch.get('mode') == 'mandatory'
        and dodge_catch.get('trigger') == {'event': 'dodge'}
        and dodge_catch.get('condition') == expected_counter_condition
        and dodge_catch.get('effects') == expected_catch_effects
        and acquire.get('mode') == 'mandatory'
        and acquire.get('trigger') == {
            'event': 'catch_opportunity_resolved',
        }
        and acquire.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'harmony',
        }
        and acquire_effect.get('op') == 'request_choice'
        and (acquire_effect.get('selector') or {}).get('zones') == ['list']
        and (acquire_effect.get('selector') or {}).get('min') == 1
        and (acquire_effect.get('selector') or {}).get('max') == 1
        and (acquire_effect.get('selector') or {}).get('where') == {
            'is_technique': True, 'character_key': 'tao',
        }
        and acquire_effect.get('then') == [{
            'op': 'move_card',
            'selection_key': 'lmi_at_045_acquire',
            'to_zone': 'hand',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-045', False,
                reason='무적풍아륜의 회피·캐치·획득 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-045 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, printed, fixed, expected in (
        ('speed-nine-can-be-dodged', 'p1', 9, None, ['opponent_dodge', 'dodge']),
        ('speed-ten-cannot-be-dodged', 'p2', 10, None, ['hit', 'failed_defense']),
        ('qna-215-fixed-seven-can-be-dodged', 'p1', 11, 7, ['opponent_dodge', 'dodge']),
        ('effect-fixed-ten-cannot-be-dodged', 'p2', 8, 10, ['hit', 'failed_defense']),
    ):
        first = _run_lmi_at_045_defense_scenario(
            definition, card_snapshot, owner,
            printed_speed=printed, fixed_speed=fixed,
        )
        second = _run_lmi_at_045_defense_scenario(
            definition, card_snapshot, owner,
            printed_speed=printed, fixed_speed=fixed,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['result'] == expected
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    catch_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-spends-yang-and-offers-only-tao-seven', 'p1', {
            'yang': 1, 'resolve': 'offer',
        }, (0, 1, True)),
        ('owner-p2-spends-one-of-two-yang', 'p2', {
            'yang': 2, 'resolve': 'offer',
        }, (1, 1, True)),
        ('qna-558-zero-yang-dodges-without-followup', 'p1', {
            'yang': 0, 'resolve': 'offer',
        }, (0, 0, False)),
        ('wrong-event-does-not-grant-catch', 'p2', {
            'yang': 1, 'event_type': 'guard', 'resolve': 'offer',
        }, (1, 0, False)),
        ('numbered-negation-suppresses-counter-and-catch', 'p1', {
            'yang': 1, 'resolve': 'offer',
            'numbered_effects_negated': True,
        }, (1, 0, False)),
    ):
        first = _run_lmi_at_045_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_045_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_yang, expected_grants, expected_resolved = expected
        legal_ok = (
            first['catch_action_ids'] == [f'{owner}-dodge-roll-catch']
            if expected_grants else first['catch_action_ids'] == []
        )
        catch_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and legal_ok
                and first['yang_after'] == expected_yang
                and first['grant_count'] == expected_grants
                and first['n1_resolved'] is expected_resolved
                and first['decision_kind'] is None
            ),
            'deterministic': deterministic, **first,
        })

    acquisition_scenarios = []
    acquisition_specs = (
        ('qna-490-play-catch-then-choose-and-use-acquired-in-combo', 'p1', {
            'harmony': True, 'resolve': 'play', 'caught_combo': True,
            'selected_index': 1,
        }, 'play'),
        ('owner-p2-decline-catch-then-mandatory-acquire-choice', 'p2', {
            'harmony': True, 'resolve': 'decline', 'selected_index': 0,
        }, 'decline'),
        ('without-harmony-does-not-acquire', 'p1', {
            'harmony': False, 'resolve': 'play',
        }, 'none'),
        ('qna-558-failed-counter-removal-does-not-acquire', 'p2', {
            'yang': 0, 'harmony': True, 'resolve': 'offer',
        }, 'none'),
        ('no-list-candidate-skips-mandatory-choice-safely', 'p1', {
            'harmony': True, 'resolve': 'decline', 'acquired_count': 0,
        }, 'skip'),
    )
    for name, owner, kwargs, expected in acquisition_specs:
        first = _run_lmi_at_045_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_045_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_options = [
            f'{owner}-dodge-roll-acquire-0',
            f'{owner}-dodge-roll-acquire-1',
        ]
        if expected == 'play':
            selected = f'{owner}-dodge-roll-acquire-1'
            outcome = bool(
                first['decision_kind'] == 'effect_choice'
                and first['decision_owner'] == owner
                and first['decision_options'] == expected_options
                and first['caught_zone_at_choice'] == 'battle'
                and all(
                    zone == 'list'
                    for zone in first['acquired_zones_at_choice'].values()
                )
                and first['selected_id'] == selected
                and first['selected_zone_after'] == 'hand'
                and first['combo_started']
                and selected in first['combo_action_card_ids']
                and first['opportunity_events'][-1].get('declined') is False
                and first['n2_resolved']
            )
        elif expected == 'decline':
            outcome = bool(
                first['decision_kind'] == 'effect_choice'
                and first['decision_owner'] == owner
                and first['decision_options'] == expected_options
                and first['selected_id'] == expected_options[0]
                and first['selected_zone_after'] == 'hand'
                and first['opportunity_events'][-1].get('declined') is True
                and first['n2_resolved'] and not first['combo_started']
            )
        elif expected == 'skip':
            outcome = bool(
                first['decision_kind'] is None
                and first['choice_skipped'] and first['n2_resolved']
            )
        else:
            outcome = bool(
                first['decision_kind'] is None
                and not first['n2_resolved']
                and first['selected_id'] is None
            )
        acquisition_scenarios.append({
            'name': name,
            'passed': bool(deterministic and outcome and not first['pending']),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            defense['id'], all(item['passed'] for item in defense_scenarios),
            defense_scenarios,
            '' if all(item['passed'] for item in defense_scenarios)
            else '무적풍아륜의 효과 적용 후 속도 기준 회피 제한 검증에 실패했습니다.',
        ),
        AbilityReview(
            dodge_catch['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
            '' if all(item['passed'] for item in catch_scenarios)
            else '무적풍아륜의 양 제거 및 캐치 후보 검증에 실패했습니다.',
        ),
        AbilityReview(
            acquire['id'],
            all(item['passed'] for item in acquisition_scenarios),
            acquisition_scenarios,
            '' if all(item['passed'] for item in acquisition_scenarios)
            else '무적풍아륜의 캐치 후 강제 획득 선택 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        item.passed and len(item.scenarios) >= 3 for item in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '무적풍아륜의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _wolf_pack_source(card_snapshot, owner):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-wolf-pack-rush', 'owner': owner,
        'type': '공격', 'frame': 10, 'damage': 300,
        'pos': '중단', 'body': '발', 'special': '',
        'hit': '5', 'counter': '6', 'face_up': True,
        'character_key': 'tao',
    })
    return source


def _wolf_pack_bagua_definition():
    return {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [653]},
        'abilities': [{
            'id': 'review-bagua-yang-counter',
            'label': '이벤트 시작 시 양 상태였다면 타오 카운터 데미지 +100',
            'kind': 'effect', 'mode': 'mandatory',
            'timing': 'hit_counter', 'visibility': 'public',
            'active_zones': ['passive'],
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [653]},
            'trigger': {'event': 'counter'},
            'condition': {
                'op': 'all', 'conditions': [
                    {
                        'op': 'has_state',
                        'player': {'controller': True}, 'state': 'yang',
                    },
                    {
                        'op': 'equals', 'left': 'context.event_controller',
                        'right': {'controller': True},
                    },
                    {
                        'op': 'card_matches',
                        'card': {'path': 'context.event_card'},
                        'where': {'character_key': 'tao'},
                    },
                ],
            },
            'effects': [{
                'op': 'modify_stat', 'player': {'controller': True},
                'target_card': 'event_card', 'stat': 'damage',
                'amount': 100, 'duration': 'battle',
            }],
        }],
    }


def _run_wolf_pack_counter_scenario(
    definition, card_snapshot, owner, *, event_type='hit', yin=3, yang=0,
    accept=True, amount=1, with_bagua=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _wolf_pack_source(card_snapshot, owner)
    opposing = _card(
        'REVIEW-WOLF-PACK-OPPONENT', other,
        f'{other}-wolf-pack-opponent',
    )
    state = _state(source, opposing, owner)
    state['players'][owner]['passive_state'].update({
        'yin': {'count': yin, 'label': '음'},
        'yang': {'count': yang, 'label': '양'},
    })
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': definition,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if with_bagua:
        bagua = _card(
            'REVIEW-WOLF-PACK-BAGUA', owner,
            f'{owner}-wolf-pack-bagua',
        )
        bagua.update({'type': '특성', 'frame': None, 'damage': None})
        state['players'][owner]['zones']['passive'] = [copy.deepcopy(bagua)]
        cards[bagua['code']] = {
            **copy.deepcopy(bagua),
            'effect_definition': _wolf_pack_bagua_definition(),
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'wolf-pack-counter:{source["code"]}:{owner}:{event_type}:'
            f'{yin}:{yang}:{accept}:{amount}:{with_bagua}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    engine._fire(event_type, {
        'controller': owner, 'event_controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'event_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        'source_battle_card_only': True,
    })
    order_decisions = _resolve_bagua_effect_orders(
        engine, owner, preferred_ability_id='review-bagua-yang-counter',
    )
    optional = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    amount_decision = {}
    amount_options = []
    if optional.get('kind') == 'optional_effect':
        engine._submit_decision(
            owner, optional['id'], ['accept' if accept else 'decline'],
        )
        engine._continue()
        amount_decision = copy.deepcopy(
            engine.engine_state.get('pending_decision') or {}
        )
        if amount_decision.get('kind') == 'effect_amount':
            amount_options = [
                str(option.get('id'))
                for option in amount_decision.get('options') or []
            ]
            engine._submit_decision(
                owner, amount_decision['id'], [str(amount)],
            )
            engine._continue()
    passive = engine.state['players'][owner]['passive_state']
    resolved_ids = [
        (event.get('payload') or {}).get('ability_id')
        for event in engine.events if event.get('type') == 'effect_resolved'
    ]
    return {
        'optional_kind': optional.get('kind'),
        'optional_owner': optional.get('owner'),
        'amount_kind': amount_decision.get('kind'),
        'amount_options': amount_options,
        'yin_after': int((passive.get('yin') or {}).get('count') or 0),
        'yang_after': int((passive.get('yang') or {}).get('count') or 0),
        'damage_after': engine.card_stat(live_source, 'damage', owner),
        'source_resolved': any(
            str(ability_id or '').endswith('-n1')
            for ability_id in resolved_ids
        ),
        'bagua_resolved': 'review-bagua-yang-counter' in resolved_ids,
        'order_decisions': order_decisions,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_wolf_pack_combo_limit_scenario(
    definition, card_snapshot, owner, *, combo_number,
    numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _wolf_pack_source(card_snapshot, owner)
    source['face_up'] = False
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    starter = _card(
        'REVIEW-WOLF-PACK-STARTER', owner,
        f'{owner}-wolf-pack-starter',
    )
    starter.update({'frame': 5, 'damage': 400})
    prior = [
        _card(
            f'REVIEW-WOLF-PACK-PRIOR-{index}', owner,
            f'{owner}-wolf-pack-prior-{index}',
        )
        for index in range(max(0, combo_number - 2))
    ]
    for index, card in enumerate(prior):
        card.update({'frame': 6 + index, 'damage': 400})
    opposing = _card(
        'REVIEW-WOLF-PACK-COMBO-OPPONENT', other,
        f'{other}-wolf-pack-combo-opponent',
    )
    state = _state(starter, opposing, owner)
    state['players'][owner]['zones']['hand'] = [copy.deepcopy(source)]
    state['players'][owner]['zones']['list'] = copy.deepcopy(prior)
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': definition,
        },
        starter['code']: {
            **copy.deepcopy(starter), 'effect_definition': no_effect,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
        **{
            card['code']: {
                **copy.deepcopy(card), 'effect_definition': no_effect,
            }
            for card in prior
        },
    }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'wolf-pack-combo:{source["code"]}:{owner}:{combo_number}:'
            f'{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    combo = {
        'owner': owner, 'source': starter['instance_id'],
        'special': combo_number == 1,
        'used': [card['instance_id'] for card in prior],
        'next_penalty': max(0, (combo_number - 1) * 100),
        'last_speed': 9, 'proposal_submitted': False,
    }
    if combo_number >= 4:
        engine.engine_state.setdefault('modifiers', []).append({
            'op': 'modify_combo', 'player': owner, 'controller': owner,
            'max_combo': 4, 'duration': 'battle',
            'source': 'review-wolf-pack-extension',
        })
    live_source = engine._find_card(source['instance_id'])
    return {
        'combo_number': combo_number,
        'legal': engine._combo_card_legal(owner, live_source, combo),
        'rule_count': len(engine._combo_rules(owner, live_source, combo)),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_wolf_pack_harmony_scenario(
    definition, card_snapshot, owner, *, harmony=True, yin=3,
    card_damage_bonus=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _wolf_pack_source(card_snapshot, owner)
    opposing = _card(
        'REVIEW-WOLF-PACK-HARMONY-OPPONENT', other,
        f'{other}-wolf-pack-harmony-opponent',
    )
    state = _state(source, opposing, owner)
    state['players'][owner]['passive_state']['yin'] = {
        'count': yin, 'label': '음',
    }
    if harmony:
        state['players'][owner]['passive_state']['harmony'] = {
            'value': True, 'label': '조화',
        }
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': definition,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'wolf-pack-harmony:{source["code"]}:{owner}:{harmony}:'
            f'{yin}:{card_damage_bonus}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    if card_damage_bonus:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': 'review-wolf-pack-card-bonus',
            'where': {'instance_id': source['instance_id']},
            'stat': 'damage', 'amount': card_damage_bonus,
            'duration': 'battle',
        })
    hp_before = engine.state['players'][other]['hp']
    engine._fire('combo', {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'source_only_event': True, 'combo': True, 'combo_number': 2,
    })
    return {
        'card_damage': engine.card_stat(live_source, 'damage', owner),
        'hp_loss': hp_before - engine.state['players'][other]['hp'],
        'effect_damage_events': [
            int((event.get('payload') or {}).get('amount') or 0)
            for event in engine.events
            if event.get('type') == 'damage_dealt'
            and (event.get('payload') or {}).get('source') == 'effect'
        ],
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and str((event.get('payload') or {}).get('ability_id') or '')
            .endswith('-n3')
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_wolf_pack_catch_lock_scenario(
    definition, card_snapshot, owner, *, event_type='after_use', expire=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _wolf_pack_source(card_snapshot, owner)
    opposing = _card(
        'REVIEW-WOLF-PACK-LOCK-OPPONENT', other,
        f'{other}-wolf-pack-lock-opponent',
    )
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        _state(source, opposing, owner),
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': definition,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'wolf-pack-lock:{source["code"]}:{owner}:{event_type}:{expire}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'source_only_event': True,
    })
    blocked_before = engine._rule_blocked(
        'catch', owner, live_source, live_opposing,
    )
    opponent_blocked = engine._rule_blocked(
        'catch', other, live_opposing, live_source,
    )
    if expire:
        engine._expire_modifiers('turn')
    return {
        'blocked_before': blocked_before,
        'blocked_after': engine._rule_blocked(
            'catch', owner, live_source, live_opposing,
        ),
        'opponent_blocked': opponent_blocked,
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and str((event.get('payload') or {}).get('ability_id') or '')
            .endswith('-n4')
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_wolf_pack_definition(definition, card_snapshot, extra_root):
    code = str((card_snapshot or {}).get('code') or '')
    if code not in {'UNC-AT-006', 'LMI-AT-046'}:
        return None
    prefix = code.lower()
    qna_ids = [382, 604, 618, 653]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    counter_damage = by_id.get(f'{prefix}-n1')
    combo_limit = by_id.get(f'{prefix}-n2')
    harmony_damage = by_id.get(f'{prefix}-n3')
    catch_lock = by_id.get(f'{prefix}-n4')
    selection_key = f'{prefix.replace("-", "_")}_yin_amount'
    selected_value = {
        'op': 'selected_value', 'selection_key': selection_key,
    }
    counter_effect = (
        (counter_damage.get('effects') or [{}])[0]
        if counter_damage else {}
    )
    valid = bool(
        extra_root == {'combo_rules'} and len(abilities) == 4
        and definition.get('combo_rules') == [{
            'min_combo': 2, 'max_combo': 3, 'numbered_effect': True,
        }]
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and counter_damage and combo_limit and harmony_damage and catch_lock
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and counter_damage.get('mode') == 'optional'
        and counter_damage.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and counter_damage.get('recheck_condition') is True
        and counter_damage.get('condition') == {
            'op': 'counter_at_least',
            'player': {'controller': True},
            'counter': 'yin', 'value': 1,
        }
        and counter_effect.get('op') == 'request_amount'
        and counter_effect.get('min') == 1
        and counter_effect.get('max') == {
            'op': 'counter_count', 'player': {'controller': True},
            'counter': 'yin',
        }
        and counter_effect.get('selection_key') == selection_key
        and [
            effect.get('op') for effect in counter_effect.get('then') or []
        ] == ['change_counter', 'modify_stat', 'change_counter']
        and (counter_effect.get('then') or [])[0].get('amount') == {
            'op': 'negate', 'value': selected_value,
        }
        and (counter_effect.get('then') or [None, {}])[1].get('amount') == {
            'op': 'multiply', 'values': [100, selected_value],
        }
        and (counter_effect.get('then') or [None, None, {}])[2] == {
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'yang', 'amount': 1, 'min': 0, 'max': 4,
        }
        and combo_limit.get('kind') == 'function'
        and combo_limit.get('mode') == 'continuous'
        and combo_limit.get('trigger') is None
        and combo_limit.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and harmony_damage.get('trigger') == {'event': 'combo'}
        and harmony_damage.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'harmony',
        }
        and (harmony_damage.get('effects') or [{}])[0].get('op')
        == 'deal_damage'
        and catch_lock.get('trigger') == {'event': 'after_use'}
        and catch_lock.get('effects') == [{
            'op': 'prevent', 'kind': 'catch',
            'player': {'controller': True}, 'duration': 'turn',
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                prefix, False,
                reason='연랑의 카운터·콤보·조화·캐치 금지 정의가 일치하지 않습니다.',
            )],
            f'{code} 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    counter_scenarios = []
    counter_specs = (
        ('owner-p1-hit-chooses-two-of-three-yin', 'p1', {
            'event_type': 'hit', 'yin': 3, 'yang': 0,
            'accept': True, 'amount': 2,
        }, (1, 1, 500, True)),
        ('owner-p2-counter-chooses-one-yin', 'p2', {
            'event_type': 'counter', 'yin': 2, 'yang': 1,
            'accept': True, 'amount': 1,
        }, (1, 2, 400, True)),
        ('qna-382-zero-yin-does-not-gain-yang', 'p1', {
            'event_type': 'hit', 'yin': 0, 'yang': 0,
        }, (0, 0, 300, False)),
        ('decline-removes-nothing-and-gains-no-yang', 'p2', {
            'event_type': 'hit', 'yin': 3, 'yang': 0,
            'accept': False,
        }, (3, 0, 300, False)),
        ('wrong-trigger-does-not-offer-effect', 'p1', {
            'event_type': 'guard', 'yin': 2, 'yang': 0,
        }, (2, 0, 300, False)),
        ('qna-653-new-yang-misses-current-counter-window', 'p2', {
            'event_type': 'counter', 'yin': 1, 'yang': 0,
            'accept': True, 'amount': 1, 'with_bagua': True,
        }, (0, 1, 400, True)),
        ('qna-653-existing-yang-applies-bagua-counter-effect', 'p1', {
            'event_type': 'counter', 'yin': 1, 'yang': 1,
            'accept': True, 'amount': 1, 'with_bagua': True,
        }, (0, 2, 500, True)),
        ('yang-counter-cap-four-is-enforced', 'p1', {
            'event_type': 'hit', 'yin': 1, 'yang': 4,
            'accept': True, 'amount': 1,
        }, (0, 4, 400, True)),
    )
    for name, owner, kwargs, expected in counter_specs:
        first = _run_wolf_pack_counter_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_wolf_pack_counter_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_yin, expected_yang, expected_damage, expected_resolved = expected
        counter_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['yin_after'] == expected_yin
                and first['yang_after'] == expected_yang
                and first['damage_after'] == expected_damage
                and first['source_resolved'] is expected_resolved
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    combo_scenarios = []
    for name, owner, combo_number, negated, expected in (
        ('special-first-combo-is-blocked', 'p1', 1, False, False),
        ('owner-p1-second-combo-is-legal', 'p1', 2, False, True),
        ('owner-p2-third-combo-is-legal', 'p2', 3, False, True),
        ('extended-fourth-combo-is-blocked', 'p2', 4, False, False),
        ('numbered-negation-removes-first-combo-restriction', 'p1', 1, True, True),
    ):
        first = _run_wolf_pack_combo_limit_scenario(
            definition, card_snapshot, owner,
            combo_number=combo_number,
            numbered_effects_negated=negated,
        )
        second = _run_wolf_pack_combo_limit_scenario(
            definition, card_snapshot, owner,
            combo_number=combo_number,
            numbered_effects_negated=negated,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['legal'] is expected
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    harmony_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-three-yin-deals-three-hundred', 'p1', {
            'harmony': True, 'yin': 3,
        }, (300, True)),
        ('owner-p2-one-yin-deals-one-hundred', 'p2', {
            'harmony': True, 'yin': 1,
        }, (100, True)),
        ('without-harmony-deals-no-effect-damage', 'p1', {
            'harmony': False, 'yin': 4,
        }, (0, False)),
        ('zero-yin-resolves-to-zero-without-damage-event', 'p2', {
            'harmony': True, 'yin': 0,
        }, (0, True)),
        ('qna-618-card-damage-bonus-does-not-scale-effect-damage', 'p1', {
            'harmony': True, 'yin': 2, 'card_damage_bonus': 100,
        }, (200, True)),
    ):
        first = _run_wolf_pack_harmony_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_wolf_pack_harmony_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_damage, expected_resolved = expected
        harmony_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['hp_loss'] == expected_damage
                and sum(first['effect_damage_events']) == expected_damage
                and first['resolved'] is expected_resolved
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    catch_scenarios = []
    for name, owner, event_type, expire, expected in (
        ('owner-p1-after-use-blocks-own-catch', 'p1', 'after_use', False, (True, True)),
        ('owner-p2-after-use-blocks-own-catch', 'p2', 'after_use', False, (True, True)),
        ('wrong-trigger-does-not-block-catch', 'p1', 'use', False, (False, False)),
        ('turn-end-expiration-removes-catch-lock', 'p2', 'after_use', True, (True, False)),
    ):
        first = _run_wolf_pack_catch_lock_scenario(
            definition, card_snapshot, owner,
            event_type=event_type, expire=expire,
        )
        second = _run_wolf_pack_catch_lock_scenario(
            definition, card_snapshot, owner,
            event_type=event_type, expire=expire,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_before, expected_after = expected
        catch_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['blocked_before'] is expected_before
                and first['blocked_after'] is expected_after
                and not first['opponent_blocked']
                and first['resolved'] is expected_before
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            counter_damage['id'],
            all(item['passed'] for item in counter_scenarios),
            counter_scenarios,
            '' if all(item['passed'] for item in counter_scenarios)
            else '연랑의 음 제거 수 선택·데미지·양 획득 검증에 실패했습니다.',
        ),
        AbilityReview(
            combo_limit['id'], all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
            '' if all(item['passed'] for item in combo_scenarios)
            else '연랑의 2~3콤보 사용 제한 검증에 실패했습니다.',
        ),
        AbilityReview(
            harmony_damage['id'],
            all(item['passed'] for item in harmony_scenarios),
            harmony_scenarios,
            '' if all(item['passed'] for item in harmony_scenarios)
            else '연랑의 조화 효과 데미지 검증에 실패했습니다.',
        ),
        AbilityReview(
            catch_lock['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
            '' if all(item['passed'] for item in catch_scenarios)
            else '연랑의 사용 후 캐치 금지 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        item.passed and len(item.scenarios) >= 3 for item in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '연랑의 카드별 Q&A 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_token_usage_scenario(
    definition, card_snapshot, owner, *, zone, create=False, delete=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-token-usage-source', 'owner': owner,
        'type': '토큰', 'frame': None, 'damage': None,
        'face_up': zone != 'side',
    })
    opposing = _card(
        'REVIEW-TOKEN-USAGE-OPPONENT', other,
        f'{other}-token-usage-opponent',
    )
    source_zone = 'side' if create else zone
    state = _state(source, opposing, owner, source_zone=source_zone)
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'token-usage:{source["code"]}:{owner}:{zone}:'
            f'{create}:{delete}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if create:
        live = engine.create_token(owner, {
            'code': source['code'], 'name': source.get('name'),
            'type': '토큰', 'zone': zone,
        })
    else:
        live = engine._find_card(source['instance_id'])
    instance_id = live['instance_id']
    before = {
        'token_key': live.get('token_key'),
        'token_usage': copy.deepcopy(live.get('token_usage') or []),
        'kind': live.get('kind'),
        'zone': engine._find_location(instance_id)[1],
    }
    if delete:
        engine.delete_token(instance_id)
    return {
        **before,
        'zone_after': engine._find_location(instance_id)[1],
        'created_event': any(
            event.get('type') == 'token_created'
            and (event.get('payload') or {}).get('card_instance_id')
            == instance_id
            for event in engine.events
        ),
        'deleted_event': any(
            event.get('type') == 'token_deleted'
            and (event.get('payload') or {}).get('card_instance_id')
            == instance_id
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_token_usage_definition(definition, card_snapshot, extra_root):
    code = str((card_snapshot or {}).get('code') or '')
    expected_key = TOKEN_USAGE_CARD_KEYS.get(code)
    if not expected_key:
        return None
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else None
    expected_id = f'{code.lower()}-function'
    valid = bool(
        extra_root == set()
        and definition.get('token_key') == expected_key
        and definition.get('token_usage') == ['token', 'counter']
        and ability and ability.get('id') == expected_id
        and ability.get('kind') == 'function'
        and ability.get('mode') == 'continuous'
        and ability.get('timing') == 'function'
        and ability.get('trigger') is None
        and ability.get('effects') == [{
            'op': 'static_rule', 'rules': ['token_usage'],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                expected_id, False,
                reason='토큰·카운터 마커 정의가 일치하지 않습니다.',
            )],
            f'{code} 토큰 사용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    scenarios = []
    for name, owner, zone, create, delete in (
        ('owner-p1-existing-lumen-token-can-be-deleted', 'p1', 'lumen', False, True),
        ('owner-p2-existing-passive-counter-marker-is-preserved', 'p2', 'passive', False, False),
        ('owner-p1-created-token-inherits-release-metadata', 'p1', 'lumen', True, True),
        ('owner-p2-created-counter-marker-inherits-release-metadata', 'p2', 'passive', True, False),
    ):
        first = _run_token_usage_scenario(
            definition, card_snapshot, owner,
            zone=zone, create=create, delete=delete,
        )
        second = _run_token_usage_scenario(
            definition, card_snapshot, owner,
            zone=zone, create=create, delete=delete,
        )
        deterministic = _canonical(first) == _canonical(second)
        scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['token_key'] == expected_key
                and first['token_usage'] == ['token', 'counter']
                and first['zone'] == zone
                and first['zone_after'] == (None if delete else zone)
                and first['created_event'] is create
                and first['deleted_event'] is delete
                and (not create or first['kind'] == 'token')
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False,
        [AbilityReview(
            ability['id'], passed, scenarios,
            '' if passed else '토큰·카운터 런타임 메타데이터 검증에 실패했습니다.',
        )],
        '' if passed else f'{code} 토큰 사용 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _new_single_source(card_snapshot, owner):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-new-single', 'owner': owner,
        'type': '토큰', 'frame': None, 'damage': None,
        'pos': None, 'body': '', 'special': '',
        'character_key': None, 'face_up': False,
    })
    return source


def _run_new_single_form_scenario(
    definition, card_snapshot, owner, *, zone='hand', create=False,
    move_to_battle=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _new_single_source(card_snapshot, owner)
    opposing = _card(
        'REVIEW-NEW-SINGLE-FORM-OPPONENT', other,
        f'{other}-new-single-form-opponent',
    )
    source_zone = 'side' if create else zone
    state = _state(source, opposing, owner, source_zone=source_zone)
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'new-single-form:{owner}:{zone}:{create}:{move_to_battle}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    if create:
        live = engine.create_token(owner, {
            'code': source['code'], 'name': source.get('name'),
            'type': '토큰', 'zone': zone,
        })
    else:
        live = engine._find_card(source['instance_id'])
    legal_ready = engine._legal_ready_card(live)
    if move_to_battle:
        engine.move_card(live['instance_id'], 'battle', reason='ready')
        live = engine._find_card(live['instance_id'])
    return {
        'type': live.get('type'), 'frame': live.get('frame'),
        'character_key': live.get('character_key'),
        'token_key': live.get('token_key'), 'kind': live.get('kind'),
        'legal_ready': legal_ready,
        'zone': engine._find_location(live['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_new_single_attached_scenario(
    definition, card_snapshot, owner, *, attached=True, host_cmyk=True,
    candidates=1, choose_index=0, break_protected=False,
    numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    token = _new_single_source(card_snapshot, owner)
    host = _card(
        'REVIEW-NEW-SINGLE-HOST', owner,
        f'{owner}-new-single-host',
    )
    host.update({
        'name': 'CMYK 세트 대상',
        'character_key': 'cmyk' if host_cmyk else 'other',
    })
    opposing = _card(
        'REVIEW-NEW-SINGLE-OPPONENT', other,
        f'{other}-new-single-opponent',
    )
    list_cards = []
    for index in range(candidates):
        candidate = _card(
            f'REVIEW-NEW-SINGLE-CANDIDATE-{index + 1}', owner,
            f'{owner}-new-single-candidate-{index + 1}',
        )
        candidate.update({
            'name': f'CMYK 후보 {index + 1}', 'character_key': 'cmyk',
        })
        list_cards.append(candidate)
    wrong = _card(
        'REVIEW-NEW-SINGLE-WRONG', owner,
        f'{owner}-new-single-wrong',
    )
    wrong.update({'name': '다른 캐릭터 후보', 'character_key': 'other'})
    replenish = _card(
        'REVIEW-NEW-SINGLE-REPLENISH', owner,
        f'{owner}-new-single-replenish',
    )
    state = _state(host, opposing, owner)
    state['players'][owner]['zones']['list'] = [
        *(copy.deepcopy(card) for card in list_cards), copy.deepcopy(wrong),
    ]
    state['players'][owner]['zones']['side'] = [copy.deepcopy(replenish)]
    runtime_definition = copy.deepcopy(definition)
    if break_protected:
        runtime_definition['break_rules'] = {'forbidden_zones': ['battle']}
    no_effect = _st1_001_no_effect_definition()
    ruleset_cards = {
        token['code']: {
            **copy.deepcopy(token),
            'effect_definition': runtime_definition,
        },
    }
    for card in [host, opposing, *list_cards, wrong, replenish]:
        ruleset_cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'new-single-attached:{owner}:{attached}:{host_cmyk}:'
            f'{candidates}:{choose_index}:{break_protected}:'
            f'{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_token = engine.create_token(owner, {
        'code': token['code'], 'name': token.get('name'),
        'type': '토큰', 'zone': 'hand',
    })
    engine.move_card(live_token['instance_id'], 'battle', reason='effect')
    if attached:
        engine.attach_card(
            live_token['instance_id'], host['instance_id'],
            controller=owner, face_up=True,
        )
    live_token = engine._find_card(live_token['instance_id'])
    if numbered_effects_negated:
        live_token['numbered_effects_negated'] = True
    live_host = engine._find_card(host['instance_id'])
    engine._fire('use', {
        'controller': owner,
        'source_card_instance_id': host['instance_id'],
        'source_card': copy.deepcopy(live_host),
        'opponent_card': copy.deepcopy(engine._find_card(opposing['instance_id'])),
        'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    option_ids = [
        str(item.get('id')) for item in (decision or {}).get('options') or []
    ]
    selected_id = None
    if decision and option_ids:
        selected_id = option_ids[min(choose_index, len(option_ids) - 1)]
        engine._submit_decision(owner, decision['id'], [selected_id])
    token_location = engine._find_location(live_token['instance_id'])
    return {
        'token_zone': token_location[1],
        'token_type_at_use': live_token.get('type'),
        'decision_owner': (decision or {}).get('owner'),
        'decision_kind': (decision or {}).get('kind'),
        'option_ids': option_ids, 'selected_id': selected_id,
        'selected_zone': (
            engine._find_location(selected_id)[1] if selected_id else None
        ),
        'wrong_zone': engine._find_location(wrong['instance_id'])[1],
        'side_zone': engine._find_location(replenish['instance_id'])[1],
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'dfr-tk-001-n1'
            for event in engine.events
        ),
        'break_prevented': any(
            event.get('type') == 'card_break_prevented'
            and (event.get('payload') or {}).get('card_instance_id')
            == live_token['instance_id']
            for event in engine.events
        ),
        'replenishment_offered': bool(
            decision and decision.get('kind') == 'break_replenish'
        ) or any(
            event.get('type') == 'decision_created'
            and (event.get('payload') or {}).get('kind') == 'break_replenish'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_dfr_tk_001_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'DFR-TK-001':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('dfr-tk-001-function')
    attached = by_id.get('dfr-tk-001-n1')
    card_form = {
        'active_zones': ['hand'], 'token_key': 'new_single',
        'frame': 1, 'character_key': 'cmyk', 'type': '공격',
    }
    attached_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals',
                'left': 'context.source_card.attached_to',
                'right': {'path': 'context.event_card.instance_id'},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.event_card'},
                'where': {'character_key': 'cmyk'},
            },
        ],
    }
    acquire_choice = {
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '리스트에서 획득할 CMYK 기술을 선택하세요.',
        'selector': {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['list'], 'min': 0, 'max': 1,
            'where': {'character_key': 'cmyk'},
        },
        'selection_key': 'new_single_acquire', 'default': [],
        'optional': True,
        'then': [{
            'op': 'move_card', 'selection_key': 'new_single_acquire',
            'to_zone': 'hand',
        }],
    }
    expected_effects = [
        {
            'op': 'break_card',
            'card_instance_id': {'path': 'context.source_card_instance_id'},
            'result_key': 'new_single_broken',
        },
        {
            'op': 'conditional',
            'condition': {
                'op': 'equals',
                'left': {
                    'op': 'selection_count',
                    'selection_key': 'new_single_broken',
                },
                'right': 1,
            },
            'then': [acquire_choice],
        },
    ]
    valid = bool(
        extra_root == {'card_form'}
        and definition.get('token_key') == 'new_single'
        and definition.get('card_form') == card_form
        and len(abilities) == 2 and function and attached
        and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['card_form'],
        }]
        and attached.get('mode') == 'mandatory'
        and attached.get('trigger') == {'event': 'use'}
        and attached.get('condition') == attached_condition
        and attached.get('active_when_attached') is True
        and attached.get('effects') == expected_effects
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'dfr-tk-001', False,
                reason='뉴 싱글의 패 기술 취급·세트 브레이크·획득 정의가 일치하지 않습니다.',
            )],
            'DFR-TK-001 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    form_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-hand-is-speed-one-cmyk-attack', 'p1', {
            'zone': 'hand',
        }, ('공격', 1, True, 'hand')),
        ('owner-p2-created-hand-token-inherits-form', 'p2', {
            'zone': 'hand', 'create': True,
        }, ('공격', 1, True, 'hand')),
        ('list-token-keeps-printed-token-form', 'p1', {
            'zone': 'list',
        }, ('토큰', None, False, 'list')),
        ('played-hand-form-persists-in-battle', 'p2', {
            'zone': 'hand', 'move_to_battle': True,
        }, ('공격', 1, True, 'battle')),
    ):
        first = _run_new_single_form_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_new_single_form_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_type, expected_frame, expected_legal, expected_zone = expected
        form_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['type'] == expected_type
                and first['frame'] == expected_frame
                and first['legal_ready'] is expected_legal
                and first['zone'] == expected_zone
                and first['token_key'] == 'new_single'
                and (
                    expected_type != '공격'
                    or first['character_key'] == 'cmyk'
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    attached_scenarios = []
    specs = (
        ('owner-p1-chooses-second-cmyk-after-token-break', 'p1', {
            'candidates': 2, 'choose_index': 1,
        }, {'resolved': True, 'token_zone': 'break', 'choice': True}),
        ('owner-p2-chooses-cmyk-after-token-break', 'p2', {
            'candidates': 1,
        }, {'resolved': True, 'token_zone': 'break', 'choice': True}),
        ('no-list-candidate-breaks-without-empty-choice', 'p1', {
            'candidates': 0,
        }, {'resolved': True, 'token_zone': 'break', 'choice': False}),
        ('unattached-token-does-not-react', 'p2', {
            'attached': False,
        }, {'resolved': False, 'token_zone': 'battle', 'choice': False}),
        ('non-cmyk-host-does-not-trigger', 'p1', {
            'host_cmyk': False,
        }, {'resolved': False, 'token_zone': 'battle', 'choice': False}),
        ('prevented-break-stops-then-acquisition', 'p2', {
            'break_protected': True,
        }, {'resolved': True, 'token_zone': 'battle', 'choice': False}),
        ('numbered-negation-disables-attached-effect', 'p1', {
            'numbered_effects_negated': True,
        }, {'resolved': False, 'token_zone': 'battle', 'choice': False}),
    )
    for name, owner, kwargs, expected in specs:
        first = _run_new_single_attached_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_new_single_attached_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        has_choice = first['decision_kind'] == 'effect_choice'
        choice_ok = True
        if expected['choice']:
            choice_ok = bool(
                has_choice and first['decision_owner'] == owner
                and len(first['option_ids']) == kwargs.get('candidates', 1)
                and first['selected_zone'] == 'hand'
            )
        else:
            choice_ok = not has_choice and first['selected_id'] is None
        attached_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['resolved'] is expected['resolved']
                and first['token_zone'] == expected['token_zone']
                and choice_ok and first['wrong_zone'] == 'list'
                and first['side_zone'] == 'side'
                and not first['replenishment_offered']
                and not first['pending']
                and (
                    not kwargs.get('break_protected')
                    or first['break_prevented']
                )
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            function['id'], all(item['passed'] for item in form_scenarios),
            form_scenarios,
            '' if all(item['passed'] for item in form_scenarios)
            else '뉴 싱글의 패 한정 1속도 CMYK 공격 취급 검증에 실패했습니다.',
        ),
        AbilityReview(
            attached['id'],
            all(item['passed'] for item in attached_scenarios),
            attached_scenarios,
            '' if all(item['passed'] for item in attached_scenarios)
            else '뉴 싱글의 세트 브레이크 및 선택 획득 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        item.passed and len(item.scenarios) >= 3 for item in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '뉴 싱글의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _dfr_at_002_source(card_snapshot, owner, instance_id=None):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': instance_id or f'{owner}-intro-drum',
        'owner': owner, 'type': '공격', 'frame': 6, 'damage': 200,
        'pos': '하단', 'body': '손', 'special': '',
        'hit': '1', 'guard': '-4', 'counter': '2',
        'character_key': 'cmyk', 'face_up': True,
    })
    return source


def _run_dfr_at_002_drum_scenario(
    definition, card_snapshot, owner, *, event_type='use', attached=True,
    host_character='cmyk', copies=1, numbered_effects_negated=False,
    attached_multiplier=1, ability_id='dfr-at-002-n1',
):
    other = 'p2' if owner == 'p1' else 'p1'
    host = _card(
        'REVIEW-INTRO-DRUM-HOST', owner, f'{owner}-intro-drum-host',
    )
    host.update({
        'name': 'CMYK 세트 호스트', 'character_key': host_character,
        'frame': 9, 'damage': 500,
    })
    opposing = _card(
        'REVIEW-INTRO-DRUM-OPPONENT', other,
        f'{other}-intro-drum-opponent',
    )
    sources = []
    for index in range(copies):
        source = _dfr_at_002_source(
            card_snapshot, owner, f'{owner}-intro-drum-{index + 1}',
        )
        if attached:
            source.update({
                'attached_to': host['instance_id'],
                'attachment_expires': 'battle',
            })
        if numbered_effects_negated:
            source['numbered_effects_negated'] = True
        sources.append(source)
    state = _state(host, opposing, owner)
    state['players'][owner]['zones']['list'] = copy.deepcopy(sources)
    no_effect = _st1_001_no_effect_definition()
    host_definition = copy.deepcopy(no_effect)
    if attached_multiplier != 1:
        host_definition['attached_effect_multiplier'] = {
            'event': 'use', 'value': attached_multiplier,
        }
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                sources[0]['code']: {
                    **copy.deepcopy(sources[0]),
                    'effect_definition': definition,
                },
                host['code']: {
                    **copy.deepcopy(host),
                    'effect_definition': host_definition,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'intro-drum:{owner}:{event_type}:{attached}:{host_character}:'
            f'{copies}:{numbered_effects_negated}:{attached_multiplier}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    before_fp = engine.state['players'][owner]['fp']
    live_host = engine._find_card(host['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': host['instance_id'],
        'source_card': copy.deepcopy(live_host),
        'opponent_card': copy.deepcopy(
            engine._find_card(opposing['instance_id'])
        ),
        'source_only_event': True,
    })
    return {
        'before_fp': before_fp,
        'after_fp': engine.state['players'][owner]['fp'],
        'fp_gained': engine.state['players'][owner]['fp'] - before_fp,
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == ability_id
            for event in engine.events
        ),
        'attached_count': sum(
            engine._find_card(card['instance_id']).get('attached_to')
            == host['instance_id']
            for card in sources
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_dfr_at_002_catch_scenario(
    definition, card_snapshot, owner, *, event_type='hit',
    candidate_zone='list', numbered_effects_negated=False,
    fast_speed_delta=0, normal_speed_delta=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _dfr_at_002_source(card_snapshot, owner)
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-INTRO-CATCH-OPPONENT', other,
        f'{other}-intro-catch-opponent',
    )
    normal = _card(
        'REVIEW-INTRO-CATCH-NORMAL', owner,
        f'{owner}-intro-catch-normal',
    )
    normal.update({
        'name': '6속도 CMYK 세트 기술', 'frame': 6,
        'character_key': 'cmyk', 'attached_to': source['instance_id'],
        'attachment_expires': 'battle',
    })
    fast = _card(
        'REVIEW-INTRO-CATCH-FAST', owner,
        f'{owner}-intro-catch-fast',
    )
    fast.update({
        'name': '7속도 CMYK 세트 기술', 'frame': 7,
        'character_key': 'cmyk', 'attached_to': source['instance_id'],
        'attachment_expires': 'battle',
    })
    wrong_character = _card(
        'REVIEW-INTRO-CATCH-WRONG', owner,
        f'{owner}-intro-catch-wrong',
    )
    wrong_character.update({
        'name': '다른 캐릭터 세트 기술', 'frame': 5,
        'character_key': 'other', 'attached_to': source['instance_id'],
        'attachment_expires': 'battle',
    })
    unattached = _card(
        'REVIEW-INTRO-CATCH-UNATTACHED', owner,
        f'{owner}-intro-catch-unattached',
    )
    unattached.update({
        'name': '세트되지 않은 CMYK 기술', 'frame': 5,
        'character_key': 'cmyk',
    })
    candidates = [normal, fast, wrong_character, unattached]
    state = _state(source, opposing, owner)
    state['players'][owner]['zones'][candidate_zone].extend(
        copy.deepcopy(candidates)
    )
    no_effect = _st1_001_no_effect_definition()
    ruleset_cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': definition,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    for card in candidates:
        ruleset_cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': ruleset_cards},
        seed=(
            f'intro-catch:{owner}:{event_type}:{candidate_zone}:'
            f'{numbered_effects_negated}:{fast_speed_delta}:'
            f'{normal_speed_delta}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    for card, amount in (
        (normal, normal_speed_delta), (fast, fast_speed_delta),
    ):
        if amount:
            engine.add_modifier({
                'op': 'modify_stat', 'controller': owner, 'player': owner,
                'source': source['instance_id'], 'stat': 'frame',
                'amount': amount, 'duration': 'battle',
                'where': {'instance_id': card['instance_id']},
            })
    live_source = engine._find_card(source['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(
            engine._find_card(opposing['instance_id'])
        ),
        'source_only_event': True,
    })
    grants = copy.deepcopy(engine.engine_state.get('granted_catches') or [])
    legal_ids = []
    if grants:
        legal_ids = [
            card['instance_id']
            for card in engine._legal_catch_cards(owner, grants[0])
        ]
    return {
        'grant_count': len(grants),
        'grant_owner': (grants[0] if grants else {}).get('owner'),
        'grant_where': (grants[0] if grants else {}).get('where'),
        'allow_zones': (grants[0] if grants else {}).get('allow_zones'),
        'max_speed': (grants[0] if grants else {}).get('max_speed'),
        'legal_ids': legal_ids,
        'normal_id': normal['instance_id'],
        'fast_id': fast['instance_id'],
        'wrong_character_id': wrong_character['instance_id'],
        'unattached_id': unattached['instance_id'],
        'normal_speed': engine.card_stat(
            engine._find_card(normal['instance_id']), 'frame', owner,
            include_fp=False,
        ),
        'fast_speed': engine.card_stat(
            engine._find_card(fast['instance_id']), 'frame', owner,
            include_fp=False,
        ),
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'dfr-at-002-n2'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_dfr_at_002_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'DFR-AT-002':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    drum = by_id.get('dfr-at-002-n1')
    catch = by_id.get('dfr-at-002-n2')
    attached_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals',
                'left': 'context.source_card.attached_to',
                'right': {'path': 'context.event_card.instance_id'},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.event_card'},
                'where': {'character_key': 'cmyk'},
            },
        ],
    }
    catch_effect = {
        'op': 'grant_catch', 'player': {'controller': True},
        'allow_zones': [
            'character', 'passive', 'list', 'break', 'ultimate',
            'hand', 'side', 'battle', 'lumen',
        ],
        'max_speed': 6, 'where': {'character_key': 'cmyk'},
        'source_attached': True,
    }
    valid = bool(
        not extra_root and len(abilities) == 2 and drum and catch
        and drum.get('kind') == 'effect'
        and drum.get('mode') == 'mandatory'
        and drum.get('timing') == 'use'
        and drum.get('trigger') == {'event': 'use'}
        and drum.get('condition') == attached_condition
        and drum.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True}, 'amount': 1,
        }]
        and drum.get('active_when_attached') is True
        and drum.get('dedupe_trigger_key') == 'cmyk:set:drum'
        and catch.get('kind') == 'effect'
        and catch.get('mode') == 'mandatory'
        and catch.get('timing') == 'hit_counter'
        and catch.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and catch.get('effects') == [catch_effect]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'dfr-at-002', False,
                reason='인트로 드럼의 세트 드럼·캐치 정의가 일치하지 않습니다.',
            )],
            'DFR-AT-002 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    drum_scenarios = []
    for name, owner, kwargs, expected_gain, expected_resolved in (
        ('owner-p1-attached-cmyk-use-gains-one-fp', 'p1', {}, 1, 1),
        ('owner-p2-attached-cmyk-use-gains-one-fp', 'p2', {}, 1, 1),
        ('two-drum-copies-do-not-stack', 'p1', {'copies': 2}, 1, 1),
        ('non-cmyk-host-does-not-trigger', 'p2', {
            'host_character': 'other',
        }, 0, 0),
        ('unattached-drum-does-not-trigger', 'p1', {
            'attached': False,
        }, 0, 0),
        ('numbered-negation-disables-drum', 'p2', {
            'numbered_effects_negated': True,
        }, 0, 0),
        ('vocal-host-doubles-drum-number', 'p1', {
            'attached_multiplier': 2,
        }, 2, 1),
    ):
        first = _run_dfr_at_002_drum_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_dfr_at_002_drum_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        drum_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['fp_gained'] == expected_gain
                and first['resolved_count'] == expected_resolved
                and first['attached_count']
                == (kwargs.get('copies', 1) if kwargs.get('attached', True) else 0)
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    catch_scenarios = []
    for name, owner, kwargs, expected_kind in (
        ('owner-p1-hit-offers-only-attached-speed-six-cmyk', 'p1', {}, 'normal'),
        ('owner-p2-counter-works-from-battle-zone', 'p2', {
            'event_type': 'counter', 'candidate_zone': 'battle',
        }, 'normal'),
        ('effect-speed-change-is-used-for-six-speed-limit', 'p1', {
            'fast_speed_delta': -1, 'normal_speed_delta': 1,
        }, 'fast'),
        ('wrong-trigger-does-not-grant-catch', 'p2', {
            'event_type': 'guard',
        }, None),
        ('numbered-negation-does-not-grant-catch', 'p1', {
            'numbered_effects_negated': True,
        }, None),
    ):
        first = _run_dfr_at_002_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_dfr_at_002_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        expected_ids = []
        if expected_kind == 'normal':
            expected_ids = [first['normal_id']]
        elif expected_kind == 'fast':
            expected_ids = [first['fast_id']]
        active = expected_kind is not None
        catch_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['grant_count'] == (1 if active else 0)
                and first['resolved'] is active
                and first['legal_ids'] == expected_ids
                and (
                    not active
                    or (
                        first['grant_owner'] == owner
                        and first['grant_where'] == {
                            'character_key': 'cmyk',
                            'attached_to': f'{owner}-intro-drum',
                        }
                        and first['max_speed'] == 6
                        and first['allow_zones'] == catch_effect['allow_zones']
                        and first['wrong_character_id'] not in first['legal_ids']
                        and first['unattached_id'] not in first['legal_ids']
                    )
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            drum['id'], all(item['passed'] for item in drum_scenarios),
            drum_scenarios,
            '' if all(item['passed'] for item in drum_scenarios)
            else '인트로 드럼의 세트 드럼 비중첩 검증에 실패했습니다.',
        ),
        AbilityReview(
            catch['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
            '' if all(item['passed'] for item in catch_scenarios)
            else '인트로 드럼의 세트 카드 캐치 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        item.passed and len(item.scenarios) >= 3 for item in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '인트로 드럼의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


