def _run_dfr_at_003_bass_scenario(
    definition, card_snapshot, owner, *, event_type='hit', attached=True,
    host_character='cmyk', copies=1, numbered_effects_negated=False,
    ability_id='dfr-at-003-n1',
):
    other = 'p2' if owner == 'p1' else 'p1'
    host = _card(
        'REVIEW-WALKING-BASS-HOST', owner,
        f'{owner}-walking-bass-host',
    )
    host.update({
        'name': 'CMYK 세트 호스트', 'character_key': host_character,
        'frame': 9, 'damage': 500,
    })
    opposing = _card(
        'REVIEW-WALKING-BASS-OPPONENT', other,
        f'{other}-walking-bass-opponent',
    )
    sources = []
    for index in range(copies):
        source = _dfr_at_003_source(
            card_snapshot, owner, f'{owner}-walking-bass-{index + 1}',
        )
        if attached:
            source.update({
                'attached_to': host['instance_id'],
                'attachment_expires': 'battle',
            })
        if numbered_effects_negated:
            source['numbered_effects_negated'] = True
        sources.append(source)
    state = _state(host, opposing, owner)
    state['players'][owner]['zones']['list'] = copy.deepcopy(sources)
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                sources[0]['code']: {
                    **copy.deepcopy(sources[0]),
                    'effect_definition': definition,
                },
                host['code']: {
                    **copy.deepcopy(host), 'effect_definition': no_effect,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'walking-bass:{owner}:{event_type}:{attached}:{host_character}:'
            f'{copies}:{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    before_fp = engine.state['players'][owner]['fp']
    live_host = engine._find_card(host['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': host['instance_id'],
        'source_card': copy.deepcopy(live_host),
        'opponent_card': copy.deepcopy(
            engine._find_card(opposing['instance_id'])
        ),
        'source_only_event': True,
    })
    return {
        'fp_gained': engine.state['players'][owner]['fp'] - before_fp,
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == ability_id
            for event in engine.events
        ),
        'attached_count': sum(
            engine._find_card(card['instance_id']).get('attached_to')
            == host['instance_id']
            for card in sources
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_dfr_at_003_catch_speed_scenario(
    definition, card_snapshot, owner, *, maximum=5,
    numbered_effects_negated=False, play=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _dfr_at_003_source(card_snapshot, owner)
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-WALKING-CATCH-OPPONENT', other,
        f'{other}-walking-catch-opponent',
    )
    state = _state(source, opposing, owner, source_zone='hand')
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': definition,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'walking-catch:{owner}:{maximum}:'
            f'{numbered_effects_negated}:{play}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    rules = engine._catch_rules(owner, live_source)
    grant = {
        'owner': owner, 'allow_zones': ['hand'], 'max_speed': maximum,
        'where': {'instance_id': source['instance_id']},
        'source': opposing['instance_id'],
    }
    options = engine._legal_catch_options(owner, grant)
    option_fixed_speed = (
        options[0].get('fixed_speed') if options else None
    )
    if play and options:
        engine.engine_state['catch'] = copy.deepcopy(grant)
        engine._play_catch(
            owner, source['instance_id'],
            catch_rule_index=options[0].get('catch_rule_index'),
        )
    live_after = engine._find_card(source['instance_id'])
    return {
        'rule_count': len(rules),
        'rule_numbered': bool(rules and rules[0].get('numbered_effect')),
        'option_count': len(options),
        'option_fixed_speed': option_fixed_speed,
        'zone_after': engine._find_location(source['instance_id'])[1],
        'speed_after': engine.card_stat(
            live_after, 'frame', owner, include_fp=False,
        ),
        'pipeline_kind': (
            engine.engine_state.get('pipeline') or {}
        ).get('kind'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_dfr_at_003_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'DFR-AT-003':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    bass = by_id.get('dfr-at-003-n1')
    catch_speed = by_id.get('dfr-at-003-n2')
    attached_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals',
                'left': 'context.source_card.attached_to',
                'right': {'path': 'context.event_card.instance_id'},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.event_card'},
                'where': {'character_key': 'cmyk'},
            },
        ],
    }
    catch_rule = {'fixed_speed': 5, 'numbered_effect': True}
    valid = bool(
        extra_root == {'catch_rules'}
        and definition.get('catch_rules') == [catch_rule]
        and len(abilities) == 2 and bass and catch_speed
        and bass.get('kind') == 'effect'
        and bass.get('mode') == 'mandatory'
        and bass.get('timing') == 'hit_counter'
        and bass.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and bass.get('condition') == attached_condition
        and bass.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True}, 'amount': 1,
        }]
        and bass.get('active_when_attached') is True
        and bass.get('dedupe_trigger_key') == 'cmyk:set:base'
        and catch_speed.get('kind') == 'effect'
        and catch_speed.get('mode') == 'mandatory'
        and catch_speed.get('timing') == 'catch'
        and catch_speed.get('trigger') == {'event': 'catch'}
        and catch_speed.get('effects') == [{
            'op': 'static_rule', 'rules': ['catch_rules'],
        }]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'dfr-at-003', False,
                reason='워킹 베이스의 세트 베이스·캐치 속도 정의가 일치하지 않습니다.',
            )],
            'DFR-AT-003 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    bass_scenarios = []
    for name, owner, kwargs, expected_gain, expected_resolved in (
        ('owner-p1-attached-cmyk-hit-gains-one-fp', 'p1', {}, 1, 1),
        ('owner-p2-attached-cmyk-counter-gains-one-fp', 'p2', {
            'event_type': 'counter',
        }, 1, 1),
        ('two-bass-copies-do-not-stack', 'p1', {'copies': 2}, 1, 1),
        ('non-cmyk-host-does-not-trigger', 'p2', {
            'host_character': 'other',
        }, 0, 0),
        ('unattached-bass-does-not-trigger', 'p1', {
            'attached': False,
        }, 0, 0),
        ('wrong-trigger-does-not-trigger', 'p2', {
            'event_type': 'use',
        }, 0, 0),
        ('numbered-negation-disables-bass', 'p1', {
            'numbered_effects_negated': True,
        }, 0, 0),
    ):
        first = _run_dfr_at_003_bass_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_dfr_at_003_bass_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        bass_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['fp_gained'] == expected_gain
                and first['resolved_count'] == expected_resolved
                and first['attached_count']
                == (kwargs.get('copies', 1) if kwargs.get('attached', True) else 0)
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    catch_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-printed-six-is-fixed-to-five-and-played', 'p1', {
            'maximum': 5, 'play': True,
        }, (1, 5, 'battle', 5)),
        ('owner-p2-speed-five-fits-exact-limit', 'p2', {
            'maximum': 5,
        }, (1, 5, 'hand', 6)),
        ('fixed-five-does-not-fit-speed-four-limit', 'p1', {
            'maximum': 4,
        }, (0, None, 'hand', 6)),
        ('numbered-negation-restores-six-and-misses-five-limit', 'p2', {
            'maximum': 5, 'numbered_effects_negated': True,
        }, (0, None, 'hand', 6)),
        ('numbered-negation-can-still-catch-at-printed-six', 'p1', {
            'maximum': 6, 'numbered_effects_negated': True,
        }, (1, None, 'hand', 6)),
    ):
        first = _run_dfr_at_003_catch_speed_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_dfr_at_003_catch_speed_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        option_count, fixed_speed, zone, speed = expected
        negated = kwargs.get('numbered_effects_negated', False)
        catch_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['rule_count'] == (0 if negated else 1)
                and first['rule_numbered'] is (not negated)
                and first['option_count'] == option_count
                and first['option_fixed_speed'] == fixed_speed
                and first['zone_after'] == zone
                and first['speed_after'] == speed
                and (
                    not kwargs.get('play')
                    or first['pipeline_kind'] == 'catch_resolution'
                )
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })

    reviews = [
        AbilityReview(
            bass['id'], all(item['passed'] for item in bass_scenarios),
            bass_scenarios,
            '' if all(item['passed'] for item in bass_scenarios)
            else '워킹 베이스의 세트 베이스 비중첩 검증에 실패했습니다.',
        ),
        AbilityReview(
            catch_speed['id'],
            all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
            '' if all(item['passed'] for item in catch_scenarios)
            else '워킹 베이스의 캐치 고정 속도 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        item.passed and len(item.scenarios) >= 3 for item in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '워킹 베이스의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


