def _run_dfr_at_004_combo_speed_scenario(
    definition, card_snapshot, owner, *, last_speed,
    selected_speed=None, numbered_effects_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _dfr_at_004_source(card_snapshot, owner)
    if numbered_effects_negated:
        source['numbered_effects_negated'] = True
    combo_source = _card(
        'REVIEW-BACKING-COMBO-SOURCE', owner,
        f'{owner}-backing-combo-source',
    )
    combo_source.update({'frame': last_speed, 'damage': 500})
    opposing = _card(
        'REVIEW-BACKING-COMBO-OPPONENT', other,
        f'{other}-backing-combo-opponent',
    )
    state = _state(combo_source, opposing, owner)
    state['players'][owner]['zones']['hand'] = [copy.deepcopy(source)]
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': definition,
                },
                combo_source['code']: {
                    **copy.deepcopy(combo_source),
                    'effect_definition': no_effect,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'backing-combo:{owner}:{last_speed}:{selected_speed}:'
            f'{numbered_effects_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    combo = {
        'owner': owner, 'source': combo_source['instance_id'],
        'used': [], 'last_speed': last_speed, 'next_penalty': 100,
        'proposal_submitted': False,
    }
    rules = engine._combo_rules(owner, live_source, combo)
    options = engine._combo_speed_options(owner, live_source, combo, rules=rules)
    legal = (
        engine._combo_card_legal(
            owner, live_source, combo, selected_speed=selected_speed,
        )
        if selected_speed is not None else bool(options)
    )
    return {
        'rule_count': len(rules),
        'rule_numbered': bool(rules and rules[0].get('numbered_effect')),
        'speed_options': options,
        'selected_speed': selected_speed,
        'legal': legal,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


