def _run_dfr_at_34_no_dodge_scenario(
    definition, card_snapshot, owner, *, controller_fp=8,
    opponent_fp=3, event_type='before_judgment', negated=False,
    expire=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _dfr_at_34_source(card_snapshot, owner, negated=negated)
    opposing = _card(
        'REVIEW-PUNISHMENT-OPPONENT', other,
        f'{other}-punishment-opponent',
    )
    opposing['special'] = '상단 회피'
    unrelated = _card(
        'REVIEW-PUNISHMENT-UNRELATED', other,
        f'{other}-punishment-unrelated',
    )
    unrelated['special'] = '하단 회피'
    state = _state(source, opposing, owner, source_zone='battle')
    state['players'][owner]['fp'] = controller_fp
    state['players'][other]['fp'] = opponent_fp
    no_effect = _st1_001_no_effect_definition()
    engine = AutomaticGameEngine(
        state,
        {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source), 'effect_definition': definition,
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
                unrelated['code']: {
                    **copy.deepcopy(unrelated), 'effect_definition': no_effect,
                },
            },
        },
        seed=(
            f'punishment-no-dodge:{owner}:{controller_fp}:{opponent_fp}:'
            f'{event_type}:{negated}:{expire}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(live_opposing),
    })
    blocked_before_expiry = engine._rule_blocked(
        'dodge', other, live_opposing, live_source,
    )
    unrelated_blocked = engine._rule_blocked(
        'dodge', other, unrelated, live_source,
    )
    if expire:
        engine._expire_modifiers('battle')
    return {
        'blocked_before_expiry': blocked_before_expiry,
        'blocked_after_expiry': engine._rule_blocked(
            'dodge', other, live_opposing, live_source,
        ),
        'unrelated_blocked': unrelated_blocked,
        'resolved': any(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'dfr-at-34-n1'
            for event in engine.events
        ),
        'replacement_count': len(engine.engine_state.get('replacements') or []),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


