def _run_st2_005_catch_scenario(
    definition, card_snapshot, owner, *, source_zone='hand',
    catch_min=None, catch_max=10, numbered_negated=False, execute=False,
):
    engine, source, _opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    catch = {'owner': owner, 'allow_zones': ['hand']}
    if catch_min is not None:
        catch['min_speed'] = catch_min
    if catch_max is not None:
        catch['max_speed'] = catch_max
    engine.engine_state['catch'] = copy.deepcopy(catch)
    engine.engine_state['step'] = 'catch'
    options = [
        option for option in engine._legal_catch_options(owner, catch)
        if (option.get('card') or {}).get('instance_id')
        == source['instance_id']
    ]
    fixed_options = [option.get('fixed_speed') for option in options]
    if execute and options:
        engine._play_catch(owner, source['instance_id'])
    live = engine._find_card(source['instance_id'])
    pipeline = engine.engine_state.get('pipeline') or {}
    return {
        'option_count': len(options), 'fixed_options': fixed_options,
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pipeline_fixed_speed': pipeline.get('fixed_speed'),
        'live_speed': (
            engine.card_stat(live, 'frame', owner, include_fp=False)
            if live else None
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_st2_005_fixed_scenario(
    definition, card_snapshot, owner, *, charge=True,
    numbered_negated=False, source_zone='battle', source_delta=0,
    opponent_speed=13, opponent_delta=0, pre_fixed_opponent=None,
    owner_fp=0, opponent_fp=0, opposing_effect=False,
    source_priority=True, judge=False, opponent_special='',
):
    other = 'p2' if owner == 'p1' else 'p1'
    opponent_definition = None
    if opposing_effect:
        opponent_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [], 'qna_ids': [500]},
            'abilities': [{
                'id': 'review-st2-005-opponent-speed-change',
                'label': '판정 전 자신의 속도 8 증가',
                'kind': 'effect', 'mode': 'mandatory',
                'timing': 'before_judgment', 'visibility': 'public',
                'active_zones': ['battle'],
                'source_refs': {'rulebook_pages': [], 'qna_ids': [500]},
                'trigger': {'event': 'before_judgment'},
                'effects': [{
                    'op': 'modify_stat',
                    'player': {'controller': True},
                    'target_card': 'event_card',
                    'stat': 'frame', 'amount': -8,
                    'duration': 'battle',
                }],
            }],
        }
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, charge=charge,
        opponent_frame=opponent_speed, opponent_special=opponent_special,
        opponent_definition=opponent_definition,
        priority=owner if source_priority else other,
        owner_fp=owner_fp, opponent_fp=opponent_fp,
    )
    if source_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-st2-005-source-delta',
            'where': {'instance_id': source['instance_id']},
            'stat': 'frame', 'amount': source_delta,
            'duration': 'battle',
        })
    if opponent_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': other, 'player': other,
            'source': f'{other}-st2-005-opponent-delta',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'amount': opponent_delta,
            'duration': 'battle',
        })
    if pre_fixed_opponent is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': other,
            'source': f'{other}-st2-005-pre-fixed',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'value': pre_fixed_opponent,
            'duration': 'battle',
        })
    if source_zone == 'battle':
        engine._battle_trigger('before_judgment')
    owner_speed = engine.card_stat(
        source, 'frame', owner, include_fp=False,
    )
    other_speed = engine.card_stat(
        opposing, 'frame', other, include_fp=False,
    )
    owner_fixed = engine._fixed_stat(source, 'frame', owner)
    other_fixed = engine._fixed_stat(opposing, 'frame', other)
    result = None
    final_speeds = None
    if judge and source_zone == 'battle':
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        result = copy.deepcopy(engine.engine_state['battle']['result'])
        final_speeds = copy.deepcopy(engine.engine_state['battle']['speed'])
    return {
        'owner_speed': owner_speed, 'opponent_speed': other_speed,
        'owner_fixed': owner_fixed, 'opponent_fixed': other_fixed,
        'guard_blocked': engine._rule_blocked(
            'guard', other, opposing, source,
        ),
        'clash_blocked': engine._rule_blocked(
            'clash', other, opposing, source,
        ),
        'dodge_blocked': engine._rule_blocked(
            'dodge', other, opposing, source,
        ),
        'result': result, 'final_speeds': final_speeds,
        'resolved': _st2_resolution_count(engine, 'st2-005-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


