            ('minimum-eleven-cannot-use-fixed-ten', 'p2', {
                'catch_min': 11, 'catch_max': 15,
            }, {'option_count': 0}),
            ('catch-play-fixes-live-card-to-ten', 'p1', {'execute': True}, {
                'source_zone': 'battle', 'pipeline_fixed_speed': 10,
                'live_speed': 10,
            }),
            ('numbered-negation-restores-printed-nine-catch', 'p2', {
                'catch_max': 9, 'numbered_negated': True,
            }, {'option_count': 1, 'fixed_options': [None]}),
            ('catch-does-not-add-list-permission', 'p1', {
                'source_zone': 'list',
            }, {'option_count': 0, 'source_zone': 'list'}),
