def _st3_007_engine(
    definition, card_snapshot, owner, *, source_zone='battle',
    opponent_type='공격', opponent_speed=8, opponent_position='상단',
    opponent_fp=0, opponent_speed_delta=0, negated=False,
    include_down_stance_trait=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-deldmil', 'kind': 'card', 'owner': owner,
        'code': 'ST3-007', 'name': '델드밀', 'type': '공격',
        'frame': 11, 'damage': 600, 'pos': '중단', 'body': '발',
        'special': '상단 회피', 'hit': '5', 'guard': '-7',
        'counter': '콤보', 'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-ST3-007-OPPONENT', other,
        f'{other}-deldmil-opponent',
    )
    opposing.update({
        'type': opponent_type, 'frame': opponent_speed,
        'pos': opponent_position, 'face_up': True,
    })
    support = None
    battle_source = source
    if source_zone != 'battle':
        support = _card(
            'REVIEW-ST3-007-SUPPORT', owner,
            f'{owner}-deldmil-support',
        )
        battle_source = support
    state = _state(source, opposing, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [
            copy.deepcopy(support),
        ]
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = opponent_fp
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    if include_down_stance_trait:
        trait = _card(
            'ST3-PS1', owner, f'{owner}-down-stance-trait',
        )
        trait.update({
            'name': '「다운 스탠스」', 'type': '특성',
            'frame': None, 'damage': None, 'special': '',
        })
        state['players'][owner]['zones']['passive'].append(
            copy.deepcopy(trait),
        )
        cards[trait['code']] = {
            **copy.deepcopy(trait),
            'effect_definition': _st3_007_down_stance_definition(),
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st3-007:{owner}:{source_zone}:{opponent_type}:'
            f'{opponent_speed}:{opponent_position}:{opponent_fp}:'
            f'{opponent_speed_delta}:{negated}:{include_down_stance_trait}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': battle_source['instance_id'],
            'card': copy.deepcopy(battle_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(opposing),
        },
    }
    if opponent_speed_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': other,
            'source': f'{owner}-review-st3-007-speed',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'amount': opponent_speed_delta,
            'duration': 'battle',
        })
    return engine, source, opposing


def _run_st3_007_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    opponent_type='공격', opponent_speed=8, opponent_position='상단',
    opponent_fp=0, opponent_speed_delta=0, negated=False,
    event_type='before_judgment', resolve_judgment=True,
    check_down_stance=False,
):
    engine, source, opposing = _st3_007_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        opponent_type=opponent_type, opponent_speed=opponent_speed,
        opponent_position=opponent_position, opponent_fp=opponent_fp,
        opponent_speed_delta=opponent_speed_delta, negated=negated,
        include_down_stance_trait=check_down_stance,
    )
    other = 'p2' if owner == 'p1' else 'p1'
    engine._refresh_continuous_rules()
    battle_source = engine.engine_state['battle'][owner]['card']
    battle_opponent = engine.engine_state['battle'][other]['card']
    reference_speed = engine.card_stat(
        battle_opponent, 'frame', other, include_fp=False,
    )
    final_speed = engine.card_stat(
        battle_opponent, 'frame', other, include_fp=True,
    )
    event_source = source if source_zone != 'battle' else battle_source
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(event_source),
        'opponent_card': copy.deepcopy(battle_opponent),
        'controller_speed': engine.card_stat(
            battle_source, 'frame', owner, include_fp=False,
        ),
        'opponent_speed': reference_speed,
        'source_battle_card_only': True,
    })
    battle_source = engine.engine_state['battle'][owner]['card']
    battle_opponent = engine.engine_state['battle'][other]['card']
    special_result = _special_result(battle_source, opponent_position)
    dodge_allowed = bool(
        special_result == 'dodge'
        and engine._defense_judgment_allowed(
            battle_source, battle_opponent, 'dodge', other,
        )
    )
    result = {
        'special': battle_source.get('special'),
        'special_result': special_result,
        'dodge_allowed': dodge_allowed,
        'opponent_reference_speed': reference_speed,
        'opponent_final_speed': final_speed,
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st3-007-n1'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }
    if resolve_judgment and source_zone == 'battle':
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        battle_result = engine.engine_state['battle'].get('result') or {}
        result.update({
            'owner_result': battle_result.get(owner),
            'opponent_result': battle_result.get(other),
        })
    if check_down_stance and source_zone == 'battle':
        engine._fire('after_use', {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': copy.deepcopy(battle_source),
            'source_battle_card_only': True,
        })
        result['down_stance'] = bool(
            engine.state['players'][owner]['passive_state']
            .get('down_stance', {}).get('value')
        )
    return result


def _review_st3_007_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST3-007':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st3-007-function')
    change = by_id.get('st3-007-n1')
    qna_ids = [156, 291]
    expected_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'card_matches',
                'card': {'path': 'context.opponent_card'},
                'where': {'type_contains': '공격'},
            },
            {
                'op': 'lte', 'left': 'context.opponent_speed', 'right': 6,
            },
        ],
    }
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('defense_rules') == [{'max_speed': 8}]
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('active_zones') == ['battle']
        and not function.get('trigger') and not function.get('condition')
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and change and change.get('kind') == 'effect'
        and change.get('mode') == 'mandatory'
        and change.get('timing') == 'before_judgment'
        and change.get('active_zones') == ['battle']
        and change.get('trigger') == {'event': 'before_judgment'}
        and change.get('condition') == expected_condition
        and change.get('effects') == [{
            'op': 'modify_judgment',
            'player': {'controller': True},
            'field': 'special', 'value': '중단 회피',
        }]
        and int((card_snapshot or {}).get('frame') or 0) == 11
        and int((card_snapshot or {}).get('damage') or 0) == 600
        and str((card_snapshot or {}).get('pos') or '') == '중단'
        and str((card_snapshot or {}).get('special') or '') == '상단 회피'
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st3-007', False,
                reason=(
                    '8속도 회피 제한, 6속도 이하 공격의 중단 회피 변경, '
                    '활성 영역 또는 Q&A 156/291 출처가 일치하지 않습니다.'
                ),
            )], 'ST3-007 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    function_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-eight-speed-upper-dodges', 'p1', {}, {
            'special': '상단 회피', 'dodge_allowed': True,
            'opponent_reference_speed': 8,
            'owner_result': 'counter', 'opponent_result': 'countered',
        }),
        ('owner-p2-eight-speed-upper-dodges', 'p2', {}, {
            'special': '상단 회피', 'dodge_allowed': True,
            'opponent_reference_speed': 8,
            'owner_result': 'counter', 'opponent_result': 'countered',
        }),
        ('nine-speed-upper-cannot-be-dodged', 'p1', {
            'opponent_speed': 9,
        }, {'dodge_allowed': False, 'opponent_reference_speed': 9,
            'owner_result': 'countered', 'opponent_result': 'counter'}),
        ('effect-speed-nine-to-eight-can-be-dodged', 'p2', {
            'opponent_speed': 9, 'opponent_speed_delta': -1,
        }, {'dodge_allowed': True, 'opponent_reference_speed': 8,
            'owner_result': 'counter', 'opponent_result': 'countered'}),
        ('fp-nine-to-one-still-exceeds-reference-limit', 'p1', {
            'opponent_speed': 9, 'opponent_fp': 8,
        }, {'dodge_allowed': False, 'opponent_reference_speed': 9,
            'opponent_final_speed': 1}),
        ('middle-position-is-not-printed-upper-dodge', 'p2', {
            'opponent_position': '중단',
        }, {'special_result': '', 'dodge_allowed': False}),
        ('numbered-negation-keeps-numberless-eight-limit', 'p1', {
            'opponent_speed': 9, 'negated': True,
        }, {'special': '상단 회피', 'dodge_allowed': False,
            'opponent_reference_speed': 9}),
    ):
        first = _run_st3_007_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_007_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        function_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    change_scenarios = []
    for name, owner, kwargs, expected in (
        ('qna-291-owner-p1-six-speed-upper-wins-against-deldmil', 'p1', {
            'opponent_speed': 6,
        }, {'special': '중단 회피', 'resolved_count': 1,
            'dodge_allowed': False, 'owner_result': 'countered',
            'opponent_result': 'counter'}),
        ('qna-291-owner-p2-six-speed-upper-wins-against-deldmil', 'p2', {
            'opponent_speed': 6,
        }, {'special': '중단 회피', 'resolved_count': 1,
            'dodge_allowed': False, 'owner_result': 'countered',
            'opponent_result': 'counter'}),
        ('qna-291-five-speed-upper-also-changes', 'p1', {
            'opponent_speed': 5,
        }, {'special': '중단 회피', 'resolved_count': 1,
            'owner_result': 'countered', 'opponent_result': 'counter'}),
        ('seven-speed-upper-keeps-printed-dodge', 'p2', {
            'opponent_speed': 7,
        }, {'special': '상단 회피', 'resolved_count': 0,
            'dodge_allowed': True, 'owner_result': 'counter',
            'opponent_result': 'countered'}),
        ('six-speed-middle-changes-and-dodges', 'p1', {
            'opponent_speed': 6, 'opponent_position': '중단',
        }, {'special': '중단 회피', 'resolved_count': 1,
            'dodge_allowed': True, 'owner_result': 'counter',
            'opponent_result': 'countered'}),
        ('six-speed-defense-does-not-satisfy-attack-ruling', 'p2', {
            'opponent_speed': 6, 'opponent_type': '수비',
        }, {'special': '상단 회피', 'resolved_count': 0}),
        ('effect-speed-seven-to-six-triggers', 'p1', {
            'opponent_speed': 7, 'opponent_speed_delta': -1,
        }, {'special': '중단 회피', 'resolved_count': 1,
            'opponent_reference_speed': 6}),
        ('effect-speed-six-to-seven-does-not-trigger', 'p2', {
            'opponent_speed': 6, 'opponent_speed_delta': 1,
        }, {'special': '상단 회피', 'resolved_count': 0,
            'opponent_reference_speed': 7}),
        ('fp-seven-to-six-does-not-trigger', 'p1', {
            'opponent_speed': 7, 'opponent_fp': 1,
        }, {'special': '상단 회피', 'resolved_count': 0,
            'opponent_reference_speed': 7, 'opponent_final_speed': 6}),
        ('wrong-timing-does-not-change', 'p2', {
            'opponent_speed': 6, 'event_type': 'use',
        }, {'special': '상단 회피', 'resolved_count': 0}),
        ('source-in-hand-does-not-change-battle-support', 'p1', {
            'source_zone': 'hand', 'opponent_speed': 6,
            'resolve_judgment': False,
        }, {'special': '', 'resolved_count': 0}),
        ('numbered-negation-keeps-upper-dodge', 'p2', {
            'opponent_speed': 6, 'negated': True,
        }, {'special': '상단 회피', 'resolved_count': 0,
            'dodge_allowed': True, 'owner_result': 'counter'}),
        ('qna-156-changed-middle-does-not-enter-down-stance', 'p1', {
            'opponent_speed': 6, 'check_down_stance': True,
        }, {'special': '중단 회피', 'resolved_count': 1,
            'down_stance': False}),
        ('unchanged-upper-enters-down-stance-control', 'p2', {
            'opponent_speed': 7, 'check_down_stance': True,
        }, {'special': '상단 회피', 'resolved_count': 0,
            'down_stance': True}),
    ):
        first = _run_st3_007_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_007_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        change_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            function['id'], all(item['passed'] for item in function_scenarios),
            function_scenarios,
        ),
        AbilityReview(
            change['id'], all(item['passed'] for item in change_scenarios),
            change_scenarios,
        ),
    ]
    passed = all(review.passed and len(review.scenarios) >= 3 for review in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST3-007 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_st3_008_clash_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    opponent_body='손', hand_count=2, protected_indexes=None,
    selected_index=0, event_type='clash', event_controller=None,
    negated=False, replenish=False, resolve_judgment=True,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-raging-punch', 'kind': 'card',
        'owner': owner, 'code': 'ST3-008', 'name': '레이징 펀치',
        'type': '공격', 'frame': 12, 'damage': 500, 'pos': '중단',
        'body': '손', 'special': '중단 상쇄', 'hit': '콤보',
        'guard': '-9', 'counter': '1', 'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-ST3-008-OPPONENT', other,
        f'{other}-raging-punch-opponent',
    )
    opposing.update({
        'frame': 6, 'pos': '중단', 'body': opponent_body,
        'face_up': True,
    })
    support = None
    battle_source = source
    if source_zone != 'battle':
        support = _card(
            'REVIEW-ST3-008-SUPPORT', owner,
            f'{owner}-raging-punch-support',
        )
        battle_source = support
    hand_cards = []
    for index in range(hand_count):
        card = _card(
            f'REVIEW-ST3-008-HAND-{index + 1}', owner,
            f'{owner}-raging-punch-hand-{index + 1}',
        )
        card.update({'name': f'패 기술 {index + 1}', 'frame': index + 2})
        hand_cards.append(card)
    side_card = _card(
        'REVIEW-ST3-008-SIDE', owner,
        f'{owner}-raging-punch-side',
    )
    side_card['name'] = '보충 기술'
    state = _state(source, opposing, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [
            copy.deepcopy(support),
        ]
    state['players'][owner]['zones']['hand'].extend(
        copy.deepcopy(hand_cards),
    )
    state['players'][owner]['zones']['side'] = [copy.deepcopy(side_card)]
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = 0
    no_effect = _st1_001_no_effect_definition()
    protected_definition = {
        **copy.deepcopy(no_effect),
        'break_rules': {'forbidden_zones': ['hand']},
    }
    protected_indexes = set(protected_indexes or [])
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
        side_card['code']: {
            **copy.deepcopy(side_card), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    for index, card in enumerate(hand_cards):
        cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(
                protected_definition if index in protected_indexes
                else no_effect
            ),
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st3-008-clash:{owner}:{source_zone}:{opponent_body}:'
            f'{hand_count}:{sorted(protected_indexes)}:{selected_index}:'
            f'{event_type}:{event_controller}:{negated}:{replenish}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': battle_source['instance_id'],
            'card': copy.deepcopy(battle_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(opposing),
        },
    }
    battle_result = {}
    if resolve_judgment and source_zone == 'battle':
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        battle_result = copy.deepcopy(
            engine.engine_state['battle'].get('result') or {},
        )
    event_owner = event_controller or owner
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    trace = []
    for _index in range(6):
        decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
        if not decision:
            break
        option_ids = [
            str(item.get('id')) for item in decision.get('options') or []
        ]
        trace.append({
            'kind': decision.get('kind'),
            'option_ids': option_ids,
        })
        if decision.get('kind') == 'effect_choice':
            selected = [
                option_ids[min(selected_index, len(option_ids) - 1)],
            ]
        elif decision.get('kind') == 'break_replenish':
            selectable = [item for item in option_ids if item != 'decline']
            selected = (
                [selectable[0]] if replenish and selectable else ['decline']
            )
        else:
            selected = option_ids[:1]
        engine._submit_decision(owner, decision['id'], selected)
        engine._continue()
    zones = engine.state['players'][owner]['zones']
    return {
        'battle_owner_result': battle_result.get(owner),
        'battle_opponent_result': battle_result.get(other),
        'decision_kinds': [item['kind'] for item in trace],
        'first_option_ids': trace[0]['option_ids'] if trace else [],
        'break_ids': sorted(
            card.get('instance_id') for card in zones['break']
        ),
        'hand_ids': sorted(
            card.get('instance_id') for card in zones['hand']
        ),
        'list_ids': sorted(
            card.get('instance_id') for card in zones['list']
        ),
        'side_ids': sorted(
            card.get('instance_id') for card in zones['side']
        ),
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st3-008-n1'
            for event in engine.events
        ),
        'choice_skipped_count': sum(
            event.get('type') == 'effect_choice_skipped'
            and (event.get('payload') or {}).get('ability_id')
            == 'st3-008-n1'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_st3_008_combo_scenario(
    definition, card_snapshot, owner, *, setup='normal_source',
    combo_card_count=2, ignore_index=None, negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    raging = _sandbox_source_snapshot(card_snapshot)
    raging.update({
        'instance_id': f'{owner}-raging-punch', 'kind': 'card',
        'owner': owner, 'code': 'ST3-008', 'name': '레이징 펀치',
        'type': '공격', 'frame': 12, 'damage': 500, 'pos': '중단',
        'body': '손', 'special': '중단 상쇄', 'hit': '콤보',
        'guard': '-9', 'counter': '1', 'face_up': True,
    })
    if negated:
        raging['numbered_effects_negated'] = True
    support = _card(
        'REVIEW-ST3-008-COMBO-SOURCE', owner,
        f'{owner}-raging-punch-combo-source',
    )
    support.update({
        'name': '콤보 시동 기술', 'frame': 10, 'hit': '콤보',
    })
    opposing = _card(
        'REVIEW-ST3-008-COMBO-OPPONENT', other,
        f'{other}-raging-punch-combo-opponent',
    )
    followers = []
    for index in range(combo_card_count):
        card = _card(
            f'REVIEW-ST3-008-COMBO-{index + 1}', owner,
            f'{owner}-raging-punch-combo-{index + 1}',
        )
        card.update({
            'name': f'후속 콤보 {index + 1}',
            'frame': 13 + index, 'damage': 500,
        })
        followers.append(card)
    if setup == 'normal_source':
        battle_source = raging
        proposal_cards = followers
        hand_cards = followers
        special = False
    elif setup == 'special_first':
        battle_source = support
        proposal_cards = [raging, *followers[:1]]
        hand_cards = proposal_cards
        special = True
    else:
        battle_source = support
        proposal_cards = [raging, *followers[:1]]
        hand_cards = proposal_cards
        special = False
    state = _state(battle_source, opposing, owner)
    state['players'][owner]['zones']['hand'] = copy.deepcopy(hand_cards)
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = 0
    no_effect = _st1_001_no_effect_definition()
    cards = {
        raging['code']: {
            **copy.deepcopy(raging),
            'effect_definition': copy.deepcopy(definition),
        },
        support['code']: {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    for card in followers:
        cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st3-008-combo:{owner}:{setup}:{combo_card_count}:'
            f'{ignore_index}:{negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(battle_source['instance_id'])
    live_opponent = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_source['instance_id'],
            'card': live_source,
        },
        other: {
            'instance_id': live_opponent['instance_id'],
            'card': live_opponent,
        },
    }
    engine.grant_combo(
        owner, source=live_source['instance_id'], special=special,
    )
    pending_after_open = bool(engine.engine_state.get('pending_decision'))
    target_ids = [card['instance_id'] for card in proposal_cards]
    action_types = (
        {'play_combo_pair', 'play_combo_sequence'}
        if len(target_ids) > 1 else {'play_combo_card'}
    )
    actions = []
    for action in engine.legal_actions(owner):
        if action.get('type') not in action_types:
            continue
        payload = action.get('payload') or {}
        action_ids = (
            payload.get('card_instance_ids')
            or [payload.get('card_instance_id')]
        )
        if action_ids == target_ids:
            actions.append(action)
    ignore_patterns = sorted({
        tuple(bool(value) for value in (
            (action.get('payload') or {}).get('ignore_damage_penalty') or []
        ))
        for action in actions
    })
    desired = tuple(
        index == ignore_index for index in range(len(target_ids))
    )
    selected_action = next((
        action for action in actions
        if tuple(bool(value) for value in (
            (action.get('payload') or {}).get('ignore_damage_penalty') or []
        )) == desired
    ), None)
    if selected_action:
        engine.submit_action(
            owner, selected_action['action_id'], {},
            command_id=f'st3-008:{owner}:{setup}:{ignore_index}',
        )
    damage_amounts = [
        (event.get('payload') or {}).get('amount')
        for event in engine.events
        if event.get('type') == 'damage_dealt'
        and (event.get('payload') or {}).get('source') == 'combo'
    ]
    get_skip_events = [
        event for event in engine.events
        if event.get('type') == 'combo_rule_get_skip_scheduled'
    ]
    get_order = list(engine.engine_state.get('get_order') or [])
    return {
        'pending_after_open': pending_after_open,
        'ignore_patterns': [list(item) for item in ignore_patterns],
        'selected_action_found': selected_action is not None,
        'damage_amounts': damage_amounts,
        'opponent_hp': engine.state['players'][other]['hp'],
        'get_skip_event_count': len(get_skip_events),
        'get_skipped': bool(
            get_skip_events
            and (
                engine.state.get('phase') != 'get'
                or owner not in get_order
            )
        ),
        'phase': engine.state.get('phase'),
        'get_order': get_order,
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st3-008-n2'
            for event in engine.events
        ),
        'usage_count': sum(
            event.get('type') == 'limited_use_consumed'
            and str((event.get('payload') or {}).get('usage_key') or '')
            .startswith('st3-008-ignore-penalty:')
            for event in engine.events
        ),
        'modifier_remaining': any(
            modifier.get('op') == 'modify_combo'
            and str(modifier.get('usage_key') or '')
            == 'st3-008-ignore-penalty'
            for modifier in engine.engine_state.get('modifiers') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st3_008_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST3-008':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    clash = by_id.get('st3-008-n1')
    combo = by_id.get('st3-008-n2')
    qna_ids = [288, 583, 650]
    selection_key = 'st3_008_hand_break_target'
    expected_clash_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals', 'left': 'context.event_controller',
                'right': {'controller': True},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.opponent_card'},
                'where': {'body': '손'},
            },
        ],
    }
    expected_clash_effects = [{
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '브레이크할 자신의 패 1장을 선택하세요.',
        'selector': {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['hand'], 'min': 1, 'max': 1,
            'as_operation': 'break_card',
        },
        'selection_key': selection_key, 'default': [],
        'then': [{
            'op': 'break_card', 'selection_key': selection_key,
        }],
    }]
    expected_combo_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals',
                'left': 'context.event_card_instance_id',
                'right': {'path': 'context.source_card_instance_id'},
            },
            {
                'op': 'any',
                'conditions': [
                    {
                        'op': 'equals',
                        'left': 'context.combo_number', 'right': 1,
                    },
                    {
                        'op': 'not',
                        'condition': {
                            'op': 'exists',
                            'left': 'context.combo_number',
                        },
                    },
                ],
            },
        ],
    }
    expected_combo_effects = [{
        'op': 'modify_combo', 'player': {'controller': True},
        'optional_ignore_damage_penalty': True,
        'after_source_sequence': True, 'skip_get_on_use': True,
        'usage_key': 'st3-008-ignore-penalty',
        'usage_key_source_scoped': True,
        'usage_scope': 'battle', 'max_uses': 1,
        'duration': 'combo',
    }]
    valid = bool(
        extra_root == set() and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and 'combo_rules' not in definition
        and clash and clash.get('kind') == 'effect'
        and clash.get('mode') == 'mandatory'
        and clash.get('timing') == 'clash'
        and clash.get('active_zones') == ['battle']
        and clash.get('trigger') == {'event': 'clash'}
        and clash.get('condition') == expected_clash_condition
        and clash.get('effects') == expected_clash_effects
        and combo and combo.get('kind') == 'effect'
        and combo.get('mode') == 'mandatory'
        and combo.get('timing') == 'combo'
        and combo.get('active_zones') == ['battle']
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('condition') == expected_combo_condition
        and combo.get('effects') == expected_combo_effects
        and int((card_snapshot or {}).get('frame') or 0) == 12
        and int((card_snapshot or {}).get('damage') or 0) == 500
        and str((card_snapshot or {}).get('special') or '') == '중단 상쇄'
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st3-008', False,
                reason=(
                    '손 판정 상쇄의 패 선택 브레이크, 1콤보 한 장 보정 '
                    '면제/Get 스킵 또는 Q&A 288/583/650 출처가 일치하지 '
                    '않습니다.'
                ),
            )], 'ST3-008 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    clash_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-selects-second-hand-card-and-replenishes', 'p1', {
            'selected_index': 1, 'replenish': True,
        }, {'battle_owner_result': 'clash',
            'battle_opponent_result': 'clash',
            'decision_kinds': ['effect_choice', 'break_replenish'],
            'break_ids': ['p1-raging-punch-hand-2'],
            'list_ids': ['p1-raging-punch-side'], 'resolved_count': 1}),
        ('owner-p2-selects-first-hand-card', 'p2', {}, {
            'battle_owner_result': 'clash',
            'battle_opponent_result': 'clash',
            'decision_kinds': ['effect_choice', 'break_replenish'],
            'break_ids': ['p2-raging-punch-hand-1'],
            'resolved_count': 1}),
        ('qna-288-foot-technique-clashes-without-break', 'p1', {
            'opponent_body': '발',
        }, {'battle_owner_result': 'clash',
            'battle_opponent_result': 'clash',
            'decision_kinds': [], 'break_ids': [], 'resolved_count': 0}),
        ('qna-288-no-body-clashes-without-break', 'p2', {
            'opponent_body': '',
        }, {'battle_owner_result': 'clash',
            'battle_opponent_result': 'clash',
            'decision_kinds': [], 'break_ids': [], 'resolved_count': 0}),
        ('qna-583-empty-hand-keeps-clash-and-fizzles', 'p1', {
            'hand_count': 0,
        }, {'battle_owner_result': 'clash',
            'battle_opponent_result': 'clash',
            'decision_kinds': [], 'break_ids': [], 'resolved_count': 1,
            'choice_skipped_count': 1}),
        ('all-protected-hand-cards-are-not-offered', 'p2', {
            'protected_indexes': [0, 1],
        }, {'decision_kinds': [], 'break_ids': [],
            'resolved_count': 1, 'choice_skipped_count': 1}),
        ('one-protected-card-leaves-only-legal-option', 'p1', {
            'protected_indexes': [0],
        }, {'first_option_ids': ['p1-raging-punch-hand-2'],
            'break_ids': ['p1-raging-punch-hand-2'],
            'resolved_count': 1}),
        ('wrong-event-does-not-break', 'p2', {
            'event_type': 'hit',
        }, {'decision_kinds': [], 'break_ids': [], 'resolved_count': 0}),
        ('opponent-timing-slot-does-not-break', 'p1', {
            'event_controller': 'p2',
        }, {'decision_kinds': [], 'break_ids': [], 'resolved_count': 0}),
        ('source-in-hand-does-not-trigger', 'p2', {
            'source_zone': 'hand', 'resolve_judgment': False,
        }, {'decision_kinds': [], 'break_ids': [], 'resolved_count': 0}),
        ('numbered-negation-does-not-break', 'p1', {
            'negated': True,
        }, {'decision_kinds': [], 'break_ids': [], 'resolved_count': 0}),
    ):
        first = _run_st3_008_clash_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_008_clash_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        clash_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    combo_scenarios = []
    for name, owner, kwargs, expected in (
        ('qna-650-owner-p1-can-choose-second-card-later', 'p1', {
            'ignore_index': 1,
        }, {'pending_after_open': False,
            'selected_action_found': True,
            'damage_amounts': [400, 500], 'opponent_hp': 3100,
            'get_skip_event_count': 1, 'get_skipped': True,
            'usage_count': 1, 'resolved_count': 1,
            'modifier_remaining': False}),
        ('qna-650-owner-p2-can-choose-first-card', 'p2', {
            'ignore_index': 0,
        }, {'selected_action_found': True,
            'damage_amounts': [500, 300], 'opponent_hp': 3200,
            'get_skip_event_count': 1, 'get_skipped': True,
            'usage_count': 1, 'resolved_count': 1}),
        ('declining-waiver-keeps-both-normal-penalties', 'p1', {}, {
            'selected_action_found': True,
            'damage_amounts': [400, 300], 'opponent_hp': 3300,
            'get_skip_event_count': 0, 'get_skipped': False,
            'usage_count': 0, 'resolved_count': 1}),
        ('one-followup-offers-decline-or-that-card', 'p2', {
            'combo_card_count': 1, 'ignore_index': 0,
        }, {'ignore_patterns': [[False], [True]],
            'damage_amounts': [500], 'opponent_hp': 3500,
            'get_skip_event_count': 1, 'usage_count': 1}),
        ('pair-offers-at-most-one-waiver', 'p1', {}, {
            'ignore_patterns': [
                [False, False], [False, True], [True, False],
            ],
        }),
        ('numbered-negation-removes-waiver', 'p2', {
            'negated': True,
        }, {'ignore_patterns': [[False, False]],
            'resolved_count': 0, 'get_skip_event_count': 0}),
        ('special-combo-raging-as-one-combo-previews-followup', 'p1', {
            'setup': 'special_first', 'combo_card_count': 1,
            'ignore_index': 1,
        }, {'ignore_patterns': [[False, False], [False, True]],
            'selected_action_found': True,
            'damage_amounts': [500, 500], 'opponent_hp': 3000,
            'get_skip_event_count': 1, 'usage_count': 1,
            'resolved_count': 1}),
        ('raging-used-as-two-combo-does-not-grant-waiver', 'p2', {
            'setup': 'normal_second', 'combo_card_count': 1,
        }, {'ignore_patterns': [[False, False]],
            'damage_amounts': [400, 300], 'opponent_hp': 3300,
            'get_skip_event_count': 0, 'resolved_count': 0}),
    ):
        first = _run_st3_008_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_008_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            clash['id'], all(item['passed'] for item in clash_scenarios),
            clash_scenarios,
        ),
        AbilityReview(
            combo['id'], all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
        ),
    ]
    passed = all(review.passed and len(review.scenarios) >= 3 for review in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST3-008 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_st3_009_defense_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    opponent_speed=9, opponent_fp=0, opponent_speed_delta=0,
    negated=False, resolve_judgment=True,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-sky-smashing', 'kind': 'card',
        'owner': owner, 'code': 'ST3-009', 'name': '스카이 스매싱',
        'type': '공격', 'frame': 13, 'damage': 500, 'pos': '상단',
        'body': '손', 'special': '하단 회피', 'hit': '4',
        'guard': '-3', 'counter': '6', 'face_up': True,
    })
    if negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-ST3-009-OPPONENT', other,
        f'{other}-sky-smashing-opponent',
    )
    opposing.update({
        'type': '공격', 'frame': opponent_speed, 'damage': 500,
        'pos': '하단', 'body': '발', 'special': '', 'face_up': True,
    })
    support = None
    battle_source = source
    if source_zone != 'battle':
        support = _card(
            'REVIEW-ST3-009-SUPPORT', owner,
            f'{owner}-sky-smashing-support',
        )
        support.update({'special': '하단 회피', 'frame': 7})
        battle_source = support
    state = _state(source, opposing, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [
            copy.deepcopy(support),
        ]
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = opponent_fp
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st3-009-defense:{owner}:{source_zone}:{opponent_speed}:'
            f'{opponent_fp}:{opponent_speed_delta}:{negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(battle_source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': live_opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    if opponent_speed_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': other,
            'source': f'{owner}-st3-009-speed-modifier',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'amount': opponent_speed_delta,
            'duration': 'battle',
        })
    engine._refresh_continuous_rules()
    battle_source = engine.engine_state['battle'][owner]['card']
    battle_opponent = engine.engine_state['battle'][other]['card']
    reference_speed = engine.card_stat(
        battle_opponent, 'frame', other, include_fp=False,
    )
    final_speed = engine.card_stat(
        battle_opponent, 'frame', other, include_fp=True,
    )
    dodge_allowed = engine._defense_judgment_allowed(
        battle_source, battle_opponent, 'dodge', other,
    )
    result = {
        'dodge_allowed': dodge_allowed,
        'opponent_reference_speed': reference_speed,
        'opponent_final_speed': final_speed,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }
    if resolve_judgment:
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        battle_result = engine.engine_state['battle'].get('result') or {}
        result.update({
            'owner_result': battle_result.get(owner),
            'opponent_result': battle_result.get(other),
        })
    return result


def _st3_009_qualifier_text(mode):
    if mode == 'prefix':
        return '[[state:down_stance]]: 이 기술을 사용할 수 있다.'
    if mode == 'numbered_prefix':
        return '① [[state:down_stance]]: 이 기술을 사용할 수 있다.'
    if mode == 'mention':
        return '이 기술은 [[state:down_stance]]의 영향을 받지 않는다.'
    return '다운 스탠스와 관계없는 기술이다.'


def _run_st3_009_combo_scenario(
    definition, card_snapshot, owner, *, setup='normal_pair',
    qualifier_mode='prefix', qualifier_speed=5, later_speed=None,
    negated=False, down_stance=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    sky = _sandbox_source_snapshot(card_snapshot)
    sky.update({
        'instance_id': f'{owner}-sky-smashing', 'kind': 'card',
        'owner': owner, 'code': 'ST3-009', 'name': '스카이 스매싱',
        'type': '공격', 'frame': 13, 'damage': 500, 'pos': '상단',
        'body': '손', 'special': '하단 회피', 'hit': '4',
        'guard': '-3', 'counter': '6', 'face_up': True,
    })
    if negated:
        sky['numbered_effects_negated'] = True
    support = _card(
        'REVIEW-ST3-009-COMBO-SOURCE', owner,
        f'{owner}-sky-smashing-combo-source',
    )
    support.update({
        'name': '콤보 시동 기술', 'frame': 10, 'damage': 600,
        'hit': '콤보',
    })
    qualifier = _card(
        'REVIEW-ST3-009-QUALIFIER', owner,
        f'{owner}-sky-smashing-qualifier',
    )
    qualifier.update({
        'name': '다운 자세 후속 기술', 'frame': qualifier_speed,
        'damage': 600, 'text': _st3_009_qualifier_text(qualifier_mode),
    })
    opposing = _card(
        'REVIEW-ST3-009-COMBO-OPPONENT', other,
        f'{other}-sky-smashing-combo-opponent',
    )
    later = None
    filler = None
    rock = None
    if later_speed is not None:
        later = _card(
            'REVIEW-ST3-009-LATER', owner,
            f'{owner}-sky-smashing-later',
        )
        later.update({
            'name': '그 다음 기술', 'frame': later_speed,
            'damage': 700,
        })
    if setup == 'rock_armbar':
        filler = _card(
            'REVIEW-ST3-009-FILLER', owner,
            f'{owner}-sky-smashing-filler',
        )
        filler.update({'name': '2콤보 기술', 'frame': 11, 'damage': 700})
        rock = _card(
            'ST3-004', owner, f'{owner}-sky-smashing-rock-armbar',
        )
        rock.update({
            'name': '록 암바', 'frame': 8, 'damage': 700,
            'special': '그랩',
            'text': (
                '[[state:down_stance]]: 이 기술은 4콤보 이상에만 '
                '사용할 수 있다.'
            ),
        })
    if setup == 'ready_source':
        battle_source = sky
        proposal_cards = [qualifier]
        special = False
    elif setup == 'special_pair':
        battle_source = support
        proposal_cards = [sky, qualifier]
        special = True
    elif setup == 'rock_armbar':
        battle_source = support
        proposal_cards = [filler, sky, rock]
        special = False
    else:
        battle_source = support
        proposal_cards = [sky, qualifier]
        if later:
            proposal_cards.append(later)
        special = False
    state = _state(battle_source, opposing, owner)
    state['players'][owner]['zones']['hand'] = copy.deepcopy(proposal_cards)
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = 0
    if down_stance:
        state['players'][owner]['passive_state']['down_stance'] = {
            'value': True,
        }
    no_effect = _st1_001_no_effect_definition()
    cards = {
        sky['code']: {
            **copy.deepcopy(sky),
            'effect_definition': copy.deepcopy(definition),
        },
        support['code']: {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
        qualifier['code']: {
            **copy.deepcopy(qualifier), 'effect_definition': no_effect,
        },
    }
    if later:
        cards[later['code']] = {
            **copy.deepcopy(later), 'effect_definition': no_effect,
        }
    if filler:
        cards[filler['code']] = {
            **copy.deepcopy(filler), 'effect_definition': no_effect,
        }
    if rock:
        down_condition = {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'down_stance',
        }
        rock_definition = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [422]},
            'abilities': [],
            'play_condition': down_condition,
            'combo_rules': [{
                'min_combo': 4,
                'end_after_use': True, 'numbered_effect': True,
            }],
        }
        cards[rock['code']] = {
            **copy.deepcopy(rock), 'effect_definition': rock_definition,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st3-009-combo:{owner}:{setup}:{qualifier_mode}:'
            f'{qualifier_speed}:{later_speed}:{negated}:{down_stance}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(battle_source['instance_id'])
    live_opponent = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_source['instance_id'], 'card': live_source,
        },
        other: {
            'instance_id': live_opponent['instance_id'],
            'card': live_opponent,
        },
    }
    if later is not None:
        engine.add_modifier({
            'op': 'modify_combo', 'controller': owner, 'player': owner,
            'source': f'{owner}-st3-009-four-combo',
            'max_combo': 4, 'duration': 'battle',
        })
    engine.grant_combo(
        owner, source=live_source['instance_id'], special=special,
    )
    pending_after_open = bool(engine.engine_state.get('pending_decision'))
    target_ids = [card['instance_id'] for card in proposal_cards]

    def action_ids(action):
        payload = action.get('payload') or {}
        return (
            payload.get('card_instance_ids')
            or [payload.get('card_instance_id')]
        )

    combo_actions = [
        action for action in engine.legal_actions(owner)
        if action.get('type') in {
            'play_combo_card', 'play_combo_pair', 'play_combo_sequence',
        }
    ]
    selected_action = next((
        action for action in combo_actions if action_ids(action) == target_ids
    ), None)
    prefix_ids = target_ids[:2]
    prefix_action = next((
        action for action in combo_actions if action_ids(action) == prefix_ids
    ), None)
    if selected_action:
        engine.submit_action(
            owner, selected_action['action_id'], {},
            command_id=f'st3-009:{owner}:{setup}:{later_speed}',
        )
    modifier_events = [
        copy.deepcopy((event.get('payload') or {}).get('modifier') or {})
        for event in engine.events
        if event.get('type') == 'modifier_added'
        and ((event.get('payload') or {}).get('modifier') or {}).get('source')
        == sky['instance_id']
        and ((event.get('payload') or {}).get('modifier') or {}).get('op')
        == 'modify_combo'
    ]
    used_ids = [
        (event.get('payload') or {}).get('card_instance_id')
        for event in engine.events
        if event.get('type') == 'combo_card_used'
    ]
    return {
        'pending_after_open': pending_after_open,
        'selected_action_found': selected_action is not None,
        'prefix_action_found': prefix_action is not None,
        'used_ids': used_ids,
        'target_ids': target_ids,
        'damage_amounts': [
            (event.get('payload') or {}).get('amount')
            for event in engine.events
            if event.get('type') == 'damage_dealt'
            and (event.get('payload') or {}).get('source') == 'combo'
        ],
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st3-009-n1'
            for event in engine.events
        ),
        'modifier_count': len(modifier_events),
        'modifier_where': (
            modifier_events[0].get('where') if modifier_events else None
        ),
        'modifier_after_where': (
            modifier_events[0].get('after_where')
            if modifier_events else None
        ),
        'modifier_remaining': any(
            modifier.get('op') == 'modify_combo'
            and modifier.get('source') == sky['instance_id']
            for modifier in engine.engine_state.get('modifiers') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st3_009_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST3-009':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st3-009-function')
    combo = by_id.get('st3-009-n1')
    qna_ids = [20, 152, 158, 422]
    expected_combo_effects = [{
        'op': 'modify_combo', 'player': {'controller': True},
        'where': {'text_effect_prefix': '[[state:down_stance]]'},
        'after_source': True, 'ignore_speed': True,
        'duration': 'combo',
    }]
    valid = bool(
        extra_root == {'defense_rules'} and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and 'combo_rules' not in definition
        and definition.get('defense_rules') == [{'min_speed': 9}]
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('active_zones') == ['battle']
        and not function.get('trigger')
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and combo and combo.get('kind') == 'effect'
        and combo.get('mode') == 'mandatory'
        and combo.get('timing') == 'combo'
        and combo.get('active_zones') == ['battle']
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('effects') == expected_combo_effects
        and int((card_snapshot or {}).get('frame') or 0) == 13
        and int((card_snapshot or {}).get('damage') or 0) == 500
        and str((card_snapshot or {}).get('special') or '') == '하단 회피'
        and str((card_snapshot or {}).get('g_bot') or '') == '회피'
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st3-009', False,
                reason=(
                    '9속도 이상 회피 제한, 바로 다음 다운 스탠스 효과 '
                    '기술의 속도 예외 또는 Q&A 20/152/158/422 출처가 '
                    '일치하지 않습니다.'
                ),
            )], 'ST3-009 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-nine-speed-can-be-dodged', 'p1', {}, {
            'dodge_allowed': True, 'opponent_reference_speed': 9,
            'opponent_final_speed': 9, 'owner_result': 'counter',
            'opponent_result': 'countered',
        }),
        ('owner-p2-nine-speed-can-be-dodged', 'p2', {}, {
            'dodge_allowed': True, 'owner_result': 'counter',
            'opponent_result': 'countered',
        }),
        ('eight-speed-cannot-be-dodged', 'p1', {
            'opponent_speed': 8,
        }, {'dodge_allowed': False, 'owner_result': 'countered',
            'opponent_result': 'counter'}),
        ('twelve-speed-can-be-dodged', 'p2', {
            'opponent_speed': 12,
        }, {'dodge_allowed': True, 'owner_result': 'counter',
            'opponent_result': 'countered'}),
        ('effect-speed-eight-to-nine-enables-dodge', 'p1', {
            'opponent_speed': 8, 'opponent_speed_delta': 1,
        }, {'dodge_allowed': True, 'opponent_reference_speed': 9}),
        ('positive-fp-nine-to-eight-keeps-reference-eligible', 'p2', {
            'opponent_speed': 9, 'opponent_fp': 1,
        }, {'dodge_allowed': True, 'opponent_reference_speed': 9,
            'opponent_final_speed': 8}),
        ('negative-fp-eight-to-nine-does-not-change-reference', 'p1', {
            'opponent_speed': 8, 'opponent_fp': -1,
        }, {'dodge_allowed': False, 'opponent_reference_speed': 8,
            'opponent_final_speed': 9}),
        ('source-in-hand-does-not-limit-support-dodge', 'p2', {
            'source_zone': 'hand', 'opponent_speed': 8,
        }, {'dodge_allowed': True}),
        ('numbered-negation-keeps-numberless-speed-limit', 'p1', {
            'opponent_speed': 8, 'negated': True,
        }, {'dodge_allowed': False}),
    ):
        first = _run_st3_009_defense_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_009_defense_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    combo_scenarios = []
    for name, owner, kwargs, expected in (
        ('ready-source-one-combo-allows-slower-followup', 'p1', {
            'setup': 'ready_source',
        }, {'selected_action_found': True,
            'used_ids': ['p1-sky-smashing-qualifier'],
            'damage_amounts': [500], 'resolved_count': 1,
            'modifier_count': 1, 'modifier_remaining': False}),
        ('qna-158-owner-p1-joint-two-three-combo', 'p1', {}, {
            'selected_action_found': True,
            'used_ids': [
                'p1-sky-smashing', 'p1-sky-smashing-qualifier',
            ],
            'damage_amounts': [400, 400], 'resolved_count': 1,
            'modifier_count': 1}),
        ('qna-158-owner-p2-does-not-require-down-state', 'p2', {}, {
            'selected_action_found': True,
            'used_ids': [
                'p2-sky-smashing', 'p2-sky-smashing-qualifier',
            ],
            'damage_amounts': [400, 400], 'resolved_count': 1}),
        ('numbered-down-stance-prefix-qualifies', 'p1', {
            'qualifier_mode': 'numbered_prefix',
        }, {'selected_action_found': True, 'resolved_count': 1}),
        ('qna-152-state-mention-is-not-an-effect-prefix', 'p2', {
            'qualifier_mode': 'mention',
        }, {'selected_action_found': False, 'resolved_count': 0}),
        ('unrelated-card-does-not-get-speed-exception', 'p1', {
            'qualifier_mode': 'none',
        }, {'selected_action_found': False, 'resolved_count': 0}),
        ('numbered-negation-removes-next-card-exception', 'p2', {
            'negated': True,
        }, {'selected_action_found': False, 'resolved_count': 0,
            'modifier_count': 0}),
        ('special-combo-one-two-pair-is-previewed', 'p1', {
            'setup': 'special_pair',
        }, {'selected_action_found': True,
            'damage_amounts': [500, 500], 'resolved_count': 1}),
        ('qna-20-slower-card-after-exempt-card-is-rejected', 'p2', {
            'later_speed': 4,
        }, {'selected_action_found': False, 'prefix_action_found': True,
            'resolved_count': 0}),
        ('qna-20-faster-card-after-exempt-card-uses-normal-rule', 'p1', {
            'later_speed': 6,
        }, {'selected_action_found': True,
            'damage_amounts': [400, 400, 400], 'resolved_count': 1}),
        ('qna-422-rock-armbar-qualifies-when-own-condition-is-met', 'p2', {
            'setup': 'rock_armbar', 'down_stance': True,
        }, {'selected_action_found': True,
            'damage_amounts': [600, 300, 400], 'resolved_count': 1}),
        ('qna-422-rock-armbar-still-needs-own-condition', 'p1', {
            'setup': 'rock_armbar',
        }, {'selected_action_found': False,
            'prefix_action_found': True, 'resolved_count': 0}),
    ):
        first = _run_st3_009_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_009_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        structural_ok = True
        if first.get('modifier_count'):
            structural_ok = bool(
                first.get('modifier_where')
                == {'text_effect_prefix': '[[state:down_stance]]'}
                and first.get('modifier_after_where')
                == {'instance_id': f'{owner}-sky-smashing'}
            )
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and structural_ok
                and not first['pending'] and not first['pending_after_open']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            function['id'],
            all(item['passed'] for item in defense_scenarios),
            defense_scenarios,
        ),
        AbilityReview(
            combo['id'], all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
        ),
    ]
    passed = all(review.passed and len(review.scenarios) >= 3 for review in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST3-009 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st3_010_source(card_snapshot, owner, *, zone='battle', negated=False):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-paki-defense', 'kind': 'card',
        'owner': owner, 'code': 'ST3-010', 'name': '파키 디펜스',
        'type': '수비', 'frame': None, 'damage': None, 'pos': None,
        'body': '', 'special': '', 'hit': None, 'guard': None,
        'counter': None, 'g_top': '상쇄', 'g_mid': '상쇄',
        'g_bot': '상쇄', 'face_up': zone in {'battle', 'list'},
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _run_st3_010_clash_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    opponent_type='공격', hit='0', counter='0', live_hit=None,
    live_counter=None, event_type='clash', event_controller=None,
    negated=False, expire_turn=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st3_010_source(
        card_snapshot, owner, zone=source_zone, negated=negated,
    )
    opposing = _card(
        'REVIEW-ST3-010-OPPONENT', other,
        f'{other}-paki-defense-opponent',
    )
    opposing.update({
        'type': opponent_type,
        'frame': 7 if opponent_type == '공격' else None,
        'damage': 800 if opponent_type == '공격' else None,
        'pos': '중단', 'hit': hit, 'counter': counter,
        'face_up': True,
    })
    support = None
    battle_source = source
    if source_zone != 'battle':
        support = _card(
            'REVIEW-ST3-010-SUPPORT', owner,
            f'{owner}-paki-defense-support',
        )
        support.update({
            'type': '수비', 'frame': None, 'damage': None,
            'g_top': '상쇄', 'g_mid': '상쇄', 'g_bot': '상쇄',
        })
        battle_source = support
    state = _state(source, opposing, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [
            copy.deepcopy(support),
        ]
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st3-010-clash:{owner}:{source_zone}:{opponent_type}:{hit}:'
            f'{counter}:{live_hit}:{live_counter}:{event_type}:'
            f'{event_controller}:{negated}:{expire_turn}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_battle_source = engine._find_card(battle_source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    if live_hit is not None:
        live_opposing['hit'] = live_hit
    if live_counter is not None:
        live_opposing['counter'] = live_counter
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_battle_source['instance_id'],
            'card': live_battle_source,
        },
        other: {
            'instance_id': live_opposing['instance_id'],
            'card': live_opposing,
        },
    }
    live_source = engine._find_card(
        source['instance_id'], owner=owner, zone=source_zone,
    )
    engine._fire(event_type, {
        'controller': event_controller or owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(live_source),
        'opponent_card': copy.deepcopy(live_opposing),
        'source_battle_card_only': True,
    })
    damage = engine.card_stat(live_opposing, 'damage', other)
    hit_after = engine.engine_state['battle'][other]['card'].get('hit')
    catch_blocked = engine._rule_blocked('catch', owner)
    catch_after_expiry = catch_blocked
    if expire_turn:
        engine._expire_modifiers('turn')
        catch_after_expiry = engine._rule_blocked('catch', owner)
    return {
        'damage': damage, 'hit': hit_after,
        'counter': engine.engine_state['battle'][other]['card'].get('counter'),
        'catch_blocked': catch_blocked,
        'catch_blocked_after_turn_expiry': catch_after_expiry,
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st3-010-clash'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _st3_010_rocket_definition():
    return {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [524]},
        'abilities': [{
            'id': 'review-st3-010-rocket-penalty',
            'label': '고유 콤보 데미지 감소',
            'kind': 'effect', 'mode': 'mandatory', 'timing': 'combo',
            'visibility': 'public',
            'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [524]},
            'active_zones': ['battle'], 'trigger': {'event': 'combo'},
            'effects': [{
                'op': 'modify_stat', 'player': {'controller': True},
                'stat': 'damage', 'amount': -400, 'duration': 'battle',
            }],
        }],
    }


def _run_st3_010_combo_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    combo_owner='opponent', card_count=2, ignore_index=None,
    negated=False, rocket=False, max_combo=None, second_combo=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    actor = other if combo_owner == 'opponent' else owner
    target = 'p1' if actor == 'p2' else 'p2'
    paki = _st3_010_source(
        card_snapshot, owner, zone=source_zone, negated=negated,
    )
    combo_source = _card(
        'REVIEW-ST3-010-COMBO-SOURCE', actor,
        f'{actor}-paki-combo-source',
    )
    combo_source.update({
        'name': '콤보 시동 기술', 'frame': 2, 'damage': 600,
        'hit': '콤보',
    })
    support = None
    owner_battle = paki
    if source_zone != 'battle':
        support = _card(
            'REVIEW-ST3-010-COMBO-SUPPORT', owner,
            f'{owner}-paki-combo-support',
        )
        support.update({
            'type': '수비', 'frame': None, 'damage': None,
            'g_top': '상쇄', 'g_mid': '상쇄', 'g_bot': '상쇄',
        })
        owner_battle = support
    combo_cards = []
    for index in range(card_count):
        card = _card(
            f'REVIEW-ST3-010-COMBO-{index + 1}', actor,
            f'{actor}-paki-combo-{index + 1}',
        )
        card.update({
            'name': f'콤보 기술 {index + 2}',
            'frame': 3 + index,
            'damage': 1200 if rocket and index == 0 else 500,
        })
        combo_cards.append(card)
    state = _state(paki, combo_source, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [
            copy.deepcopy(support),
        ]
    actor_battle = [copy.deepcopy(combo_source)]
    if actor == owner and source_zone == 'battle':
        actor_battle.insert(0, copy.deepcopy(paki))
    state['players'][actor]['zones']['battle'] = actor_battle
    state['players'][actor]['zones']['hand'] = copy.deepcopy(combo_cards)
    no_effect = _st1_001_no_effect_definition()
    cards = {
        paki['code']: {
            **copy.deepcopy(paki),
            'effect_definition': copy.deepcopy(definition),
        },
        combo_source['code']: {
            **copy.deepcopy(combo_source), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    for index, card in enumerate(combo_cards):
        cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': (
                _st3_010_rocket_definition()
                if rocket and index == 0 else no_effect
            ),
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st3-010-combo:{owner}:{source_zone}:{combo_owner}:'
            f'{card_count}:{ignore_index}:{negated}:{rocket}:'
            f'{max_combo}:{second_combo}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_owner_battle = engine._find_card(owner_battle['instance_id'])
    live_combo_source = engine._find_card(combo_source['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_owner_battle['instance_id'],
            'card': live_owner_battle,
        },
        actor: {
            'instance_id': live_combo_source['instance_id'],
            'card': live_combo_source,
        },
    }
    if max_combo is not None:
        engine.add_modifier({
            'op': 'modify_combo', 'controller': actor, 'player': actor,
            'source': f'{actor}-st3-010-max-combo',
            'max_combo': max_combo, 'duration': 'battle',
        })
    engine.grant_combo(actor, source=live_combo_source['instance_id'])
    target_ids = [card['instance_id'] for card in combo_cards]

    def ids(action):
        payload = action.get('payload') or {}
        return payload.get('card_instance_ids') or [
            payload.get('card_instance_id'),
        ]

    actions = [
        action for action in engine.legal_actions(actor)
        if action.get('type') in {
            'play_combo_card', 'play_combo_pair', 'play_combo_sequence',
        }
        and ids(action) == target_ids
    ]
    patterns = sorted({
        tuple(bool(value) for value in (
            (action.get('payload') or {}).get('ignore_damage_penalty') or []
        ))
        for action in actions
    })
    desired = tuple(
        index == ignore_index for index in range(len(target_ids))
    )
    selected_action = next((
        action for action in actions
        if tuple(bool(value) for value in (
            (action.get('payload') or {}).get('ignore_damage_penalty') or []
        )) == desired
    ), None)
    if selected_action:
        engine.submit_action(
            actor, selected_action['action_id'], {},
            command_id=(
                f'st3-010:{owner}:{source_zone}:{combo_owner}:'
                f'{ignore_index}:{rocket}'
            ),
        )
    second_patterns = []
    if second_combo:
        second_card = _card(
            'REVIEW-ST3-010-SECOND-COMBO', actor,
            f'{actor}-paki-second-combo',
        )
        second_card.update({'frame': 5, 'damage': 500})
        engine.state['players'][actor]['zones']['hand'].append(second_card)
        engine.ruleset['cards'][second_card['code']] = {
            **copy.deepcopy(second_card), 'effect_definition': no_effect,
        }
        engine.state['phase'] = 'battle'
        engine.grant_combo(actor, source=combo_source['instance_id'])
        for action in engine.legal_actions(actor):
            if action.get('type') != 'play_combo_card':
                continue
            if ids(action) != [second_card['instance_id']]:
                continue
            second_patterns.append(tuple(bool(value) for value in (
                (action.get('payload') or {}).get(
                    'ignore_damage_penalty'
                ) or []
            )))
        second_patterns = sorted(set(second_patterns))
    return {
        'patterns': [list(item) for item in patterns],
        'selected_action_found': selected_action is not None,
        'damage_amounts': [
            (event.get('payload') or {}).get('amount')
            for event in engine.events
            if event.get('type') == 'damage_dealt'
            and (event.get('payload') or {}).get('source') == 'combo'
        ],
        'target_hp': engine.state['players'][target]['hp'],
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'st3-010-opponent-combo'
            for event in engine.events
        ),
        'modifier_count': sum(
            event.get('type') == 'modifier_added'
            and ((event.get('payload') or {}).get('modifier') or {}).get(
                'source'
            ) == paki['instance_id']
            for event in engine.events
        ),
        'limited_use_count': sum(
            event.get('type') == 'limited_use_consumed'
            and str((event.get('payload') or {}).get('usage_key') or '')
            .startswith('st3-010-opponent-ignore-penalty')
            for event in engine.events
        ),
        'second_patterns': [list(item) for item in second_patterns],
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st3_010_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST3-010':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    clash = by_id.get('st3-010-clash')
    opponent_combo = by_id.get('st3-010-opponent-combo')
    qna_ids = [147, 195, 236, 255, 334, 341, 389, 469, 524, 542, 592, 650]
    expected_clash_condition = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals', 'left': 'context.event_controller',
                'right': {'controller': True},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.opponent_card'},
                'where': {'type_contains': '공격'},
            },
            {
                'op': 'not',
                'condition': {
                    'op': 'card_matches',
                    'card': {'path': 'context.opponent_card'},
                    'where': {'judgment_contains': '콤보'},
                },
            },
        ],
    }
    expected_clash_effects = [
        {
            'op': 'modify_stat', 'player': {'opponent': True},
            'stat': 'damage', 'amount': -500, 'duration': 'battle',
        },
        {
            'op': 'modify_judgment', 'player': {'opponent': True},
            'field': 'hit', 'value': '-5',
        },
        {
            'op': 'prevent', 'kind': 'catch',
            'player': {'controller': True}, 'duration': 'turn',
        },
    ]
    expected_combo_effects = [{
        'op': 'modify_combo', 'player': {'opponent': True},
        'optional_ignore_damage_penalty': True,
        'duration': 'combo',
    }]
    valid = bool(
        not extra_root and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and 'combo_rules' not in definition
        and clash and clash.get('kind') == 'effect'
        and clash.get('mode') == 'mandatory'
        and clash.get('timing') == 'clash'
        and clash.get('active_zones') == ['battle', 'list']
        and clash.get('trigger') == {'event': 'clash'}
        and clash.get('recheck_condition') is True
        and clash.get('condition') == expected_clash_condition
        and clash.get('effects') == expected_clash_effects
        and opponent_combo and opponent_combo.get('kind') == 'effect'
        and opponent_combo.get('mode') == 'mandatory'
        and opponent_combo.get('timing') == 'combo'
        and opponent_combo.get('active_zones') == ['battle', 'list']
        and opponent_combo.get('trigger') == {'event': 'combo'}
        and opponent_combo.get('dedupe_trigger_key')
        == 'st3-010-opponent-combo'
        and opponent_combo.get('condition') == {
            'op': 'equals', 'left': 'context.event_controller',
            'right': {'opponent': True},
        }
        and opponent_combo.get('effects') == expected_combo_effects
        and str((card_snapshot or {}).get('type') or '') == '수비'
        and all(
            str((card_snapshot or {}).get(field) or '') == '상쇄'
            for field in ('g_top', 'g_mid', 'g_bot')
        )
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st3-010', False,
                reason=(
                    '라이브 히트/카운터 콤보 판정, 리스트 발동, 상대 '
                    '콤보별 한 장 보정 면제 또는 연결 Q&A 출처가 '
                    '일치하지 않습니다.'
                ),
            )], 'ST3-010 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    clash_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-no-combo-reduces-and-blocks-catch', 'p1', {}, {
            'damage': 300, 'hit': '-5', 'catch_blocked': True,
            'resolved_count': 1,
        }),
        ('owner-p2-no-combo-reduces-and-blocks-catch', 'p2', {}, {
            'damage': 300, 'hit': '-5', 'catch_blocked': True,
            'resolved_count': 1,
        }),
        ('qna-389-hit-combo-prevents-effect', 'p1', {
            'hit': '콤보',
        }, {'damage': 800, 'hit': '콤보', 'catch_blocked': False,
            'resolved_count': 0}),
        ('qna-389-counter-only-combo-prevents-effect', 'p2', {
            'counter': '콤보',
        }, {'damage': 800, 'counter': '콤보', 'catch_blocked': False,
            'resolved_count': 0}),
        ('qna-236-effect-added-combo-is-read-live', 'p1', {
            'live_hit': '콤보',
        }, {'damage': 800, 'hit': '콤보', 'resolved_count': 0}),
        ('qna-236-effect-removed-combo-is-read-live', 'p2', {
            'hit': '콤보', 'live_hit': '0',
        }, {'damage': 300, 'hit': '-5', 'resolved_count': 1}),
        ('qna-195-earlier-hit-change-is-replaced-by-minus-five', 'p1', {
            'hit': '-4',
        }, {'damage': 300, 'hit': '-5', 'resolved_count': 1}),
        ('qna-592-list-source-still-resolves', 'p2', {
            'source_zone': 'list',
        }, {'damage': 300, 'hit': '-5', 'catch_blocked': True,
            'resolved_count': 1}),
        ('source-in-hand-is-inactive', 'p1', {
            'source_zone': 'hand',
        }, {'damage': 800, 'hit': '0', 'catch_blocked': False,
            'resolved_count': 0}),
        ('opposing-defense-is-not-an-attack', 'p2', {
            'opponent_type': '수비',
        }, {'damage': 0, 'hit': '0', 'resolved_count': 0}),
        ('wrong-event-does-not-resolve', 'p1', {
            'event_type': 'guard',
        }, {'damage': 800, 'hit': '0', 'resolved_count': 0}),
        ('opponent-timing-slot-does-not-resolve', 'p2', {
            'event_controller': 'p1',
        }, {'damage': 800, 'hit': '0', 'resolved_count': 0}),
        ('numbered-negation-suppresses-effect', 'p1', {
            'negated': True,
        }, {'damage': 800, 'hit': '0', 'catch_blocked': False,
            'resolved_count': 0}),
        ('catch-prohibition-expires-at-turn-end', 'p2', {
            'expire_turn': True,
        }, {'catch_blocked': True,
            'catch_blocked_after_turn_expiry': False,
            'resolved_count': 1}),
    ):
        first = _run_st3_010_clash_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_010_clash_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        clash_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    combo_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-opponent-chooses-second-card', 'p1', {
            'ignore_index': 1,
        }, {'patterns': [
            [False, False], [False, True], [True, False],
        ], 'selected_action_found': True,
            'damage_amounts': [400, 500], 'target_hp': 3100,
            'resolved_count': 1, 'modifier_count': 1,
            'limited_use_count': 0}),
        ('owner-p2-opponent-chooses-first-card', 'p2', {
            'ignore_index': 0,
        }, {'selected_action_found': True,
            'damage_amounts': [500, 300], 'target_hp': 3200,
            'resolved_count': 1}),
        ('opponent-may-decline-waiver', 'p1', {}, {
            'selected_action_found': True,
            'damage_amounts': [400, 300], 'target_hp': 3300,
            'resolved_count': 1}),
        ('qna-334-four-combo-can-select-last-card', 'p2', {
            'card_count': 3, 'ignore_index': 2, 'max_combo': 4,
        }, {'patterns': [
            [False, False, False], [False, False, True],
            [False, True, False], [True, False, False],
        ], 'damage_amounts': [400, 300, 500],
            'target_hp': 2800, 'resolved_count': 1}),
        ('qna-524-own-rocket-minus-four-hundred-still-applies', 'p1', {
            'card_count': 1, 'ignore_index': 0, 'rocket': True,
        }, {'patterns': [[False], [True]],
            'damage_amounts': [800], 'target_hp': 3200,
            'resolved_count': 1}),
        ('qna-542-list-source-applies-to-catch-created-combo', 'p2', {
            'source_zone': 'list', 'card_count': 1, 'ignore_index': 0,
        }, {'patterns': [[False], [True]],
            'damage_amounts': [500], 'resolved_count': 1}),
        ('owners-own-combo-does-not-receive-permission', 'p1', {
            'combo_owner': 'owner',
        }, {'patterns': [[False, False]], 'resolved_count': 0,
            'modifier_count': 0}),
        ('source-in-hand-is-inactive', 'p2', {
            'source_zone': 'hand',
        }, {'patterns': [[False, False]], 'resolved_count': 0}),
        ('numbered-negation-removes-opponent-permission', 'p1', {
            'negated': True,
        }, {'patterns': [[False, False]], 'resolved_count': 0}),
        ('qna-650-one-card-combo-offers-decline-or-use', 'p2', {
            'card_count': 1, 'ignore_index': 0,
        }, {'patterns': [[False], [True]],
            'damage_amounts': [500], 'resolved_count': 1}),
        ('each-later-combo-receives-a-fresh-one-card-choice', 'p1', {
            'source_zone': 'list', 'card_count': 1,
            'ignore_index': 0, 'second_combo': True,
        }, {'second_patterns': [[False], [True]],
            'resolved_count': 2, 'modifier_count': 2,
            'limited_use_count': 0}),
    ):
        first = _run_st3_010_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st3_010_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        combo_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            clash['id'], all(item['passed'] for item in clash_scenarios),
            clash_scenarios,
        ),
        AbilityReview(
            opponent_combo['id'],
            all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
        ),
    ]
    passed = all(review.passed and len(review.scenarios) >= 3 for review in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST3-010 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st4_001_review_fixture(
    definition, card_snapshot, owner, *, source_speed=4,
    proposal_speeds=(5,), appearance_index=0, filler_count=0,
    numbered_negated=False, external_max_combo=None, damage_bonus=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _card(
        'REVIEW-APPEARANCE-SOURCE', owner,
        f'{owner}-appearance-source',
    )
    source.update({'frame': source_speed, 'damage': 400, 'face_up': True})
    opposing = _card(
        'REVIEW-APPEARANCE-OPPONENT', other,
        f'{other}-appearance-opponent',
    )
    appearance = _card('ST4-001', owner, f'{owner}-appearance-blade')
    appearance.update(copy.deepcopy(card_snapshot or {}))
    appearance.update({
        'instance_id': f'{owner}-appearance-blade', 'owner': owner,
        'code': 'ST4-001', 'name': '어피어런스 블레이드',
        'type': '공격', 'frame': 5, 'damage': 400,
        'pos': '중단', 'body': '손', 'face_up': False,
    })
    if numbered_negated:
        appearance['numbered_effects_negated'] = True
    proposal = []
    for index, speed in enumerate(proposal_speeds):
        if index == appearance_index:
            card = copy.deepcopy(appearance)
        else:
            card = _card(
                f'REVIEW-APPEARANCE-COMBO-{index + 2}', owner,
                f'{owner}-appearance-combo-{index + 2}',
            )
            card.update({
                'name': f'검토 콤보 {index + 2}',
                'frame': speed, 'damage': 500, 'face_up': False,
            })
        proposal.append(card)
    fillers = []
    for index in range(filler_count):
        filler = _card(
            f'REVIEW-APPEARANCE-FILLER-{index + 1}', owner,
            f'{owner}-appearance-filler-{index + 1}',
        )
        filler.update({
            'name': f'검토 패 수비 {index + 1}', 'type': '수비',
            'frame': None, 'damage': None, 'g_top': '방어',
            'face_up': False,
        })
        fillers.append(filler)
    state = _state(source, opposing, owner)
    state['players'][owner]['zones']['hand'] = copy.deepcopy([
        *proposal, *fillers,
    ])
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []},
        'abilities': [],
    }
    released_cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(no_effect),
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': copy.deepcopy(no_effect),
        },
        appearance['code']: {
            **copy.deepcopy(appearance),
            'effect_definition': copy.deepcopy(definition),
        },
    }
    for card in [*proposal, *fillers]:
        if card.get('code') == 'ST4-001':
            continue
        released_cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(no_effect),
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': released_cards},
        seed=(
            f'st4-001:{owner}:{source_speed}:{proposal_speeds}:'
            f'{appearance_index}:{filler_count}:{numbered_negated}:'
            f'{external_max_combo}:{damage_bonus}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(source['instance_id'])
    live_opponent = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_source['instance_id'], 'card': live_source,
        },
        other: {
            'instance_id': live_opponent['instance_id'],
            'card': live_opponent,
        },
    }
    if external_max_combo is not None:
        engine.add_modifier({
            'op': 'modify_combo', 'controller': owner, 'player': owner,
            'source': f'{owner}-appearance-external-combo',
            'max_combo': external_max_combo, 'duration': 'battle',
        })
    if damage_bonus:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-appearance-damage-bonus',
            'where': {'instance_id': appearance['instance_id']},
            'stat': 'damage', 'amount': damage_bonus,
            'duration': 'battle',
        })
    engine.grant_combo(
        owner, source=source['instance_id'], trigger_event=False,
    )
    return engine, proposal, appearance


def _st4_001_action_card_ids(action):
    payload = action.get('payload') or {}
    return list(
        payload.get('card_instance_ids')
        or ([payload.get('card_instance_id')]
            if payload.get('card_instance_id') else [])
    )


def _run_st4_001_combo_scenario(
    definition, card_snapshot, owner, *, source_speed=4,
    proposal_speeds=(5,), appearance_index=0, filler_count=0,
    numbered_negated=False, external_max_combo=None, damage_bonus=0,
    execute=True,
):
    engine, proposal, appearance = _st4_001_review_fixture(
        definition, card_snapshot, owner,
        source_speed=source_speed, proposal_speeds=proposal_speeds,
        appearance_index=appearance_index, filler_count=filler_count,
        numbered_negated=numbered_negated,
        external_max_combo=external_max_combo, damage_bonus=damage_bonus,
    )
    target_ids = [card['instance_id'] for card in proposal]
    maximum = engine._combo_maximum(
        owner, engine.engine_state.get('combo') or {},
    )
    actions = engine._combo_actions(
        owner, engine.engine_state.get('combo') or {},
    )
    action = next((
        item for item in actions
        if _st4_001_action_card_ids(item) == target_ids
    ), None)
    result = {
        'legal': action is not None, 'maximum': maximum,
        'target_ids': target_ids,
        'matching_action_count': sum(
            _st4_001_action_card_ids(item) == target_ids
            for item in actions
        ),
        'appearance_damage': None, 'combo_used_ids': [],
        'combo_ended': False,
    }
    if action is None or not execute:
        return result
    payload = action.get('payload') or {}
    engine._play_combo(
        owner, target_ids,
        payload.get('combo_speeds') or [payload.get('combo_speed')],
        payload.get('ignore_damage_penalty') or [],
        payload.get('ignore_speed') or [],
    )
    engine._continue()
    combo_events = [
        event for event in engine.events
        if event.get('type') == 'combo_card_used'
    ]
    result.update({
        'appearance_damage': next((
            (event.get('payload') or {}).get('damage')
            for event in combo_events
            if (event.get('payload') or {}).get('card_instance_id')
            == appearance['instance_id']
        ), None),
        'combo_used_ids': [
            (event.get('payload') or {}).get('card_instance_id')
            for event in combo_events
        ],
        'combo_ended': any(
            event.get('type') == 'combo_ended' for event in engine.events
        ),
    })
    return result


def _review_st4_001_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-001':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    speed = by_id.get('st4-001-n1')
    damage = by_id.get('st4-001-n2')
    qna_ids = [20, 102, 578]
    four_plus = {
        'op': 'gte', 'left': 'context.combo_number', 'right': 4,
    }
    hand_after_proposal = {
        'op': 'zone_count', 'player': {'controller': True},
        'zone': 'hand', 'max': 3,
        'exclude_source': True, 'exclude_combo_proposed': True,
    }
    combo_rules = [
        {
            'min_combo': 4,
            'ignore_speed': True, 'numbered_effect': True,
            'condition': four_plus,
        },
        {
            'ignore_damage_penalty': True, 'numbered_effect': True,
            'condition': hand_after_proposal,
        },
    ]
    valid = bool(
        extra_root == {'combo_rules'}
        and definition.get('combo_rules') == combo_rules
        and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and speed and speed.get('kind') == 'effect'
        and speed.get('mode') == 'continuous'
        and speed.get('timing') == 'combo'
        and not speed.get('trigger')
        and not speed.get('active_zones')
        and speed.get('condition') == four_plus
        and speed.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and damage and damage.get('kind') == 'effect'
        and damage.get('mode') == 'continuous'
        and damage.get('timing') == 'combo'
        and not damage.get('trigger')
        and not damage.get('active_zones')
        and damage.get('condition') == hand_after_proposal
        and damage.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and int((card_snapshot or {}).get('frame') or 0) == 5
        and int((card_snapshot or {}).get('damage') or 0) == 400
        and str((card_snapshot or {}).get('pos') or '') == '중단'
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st4-001', False,
                reason=(
                    '어피어런스 블레이드의 4콤보 속도 예외 또는 '
                    '동시 제시 후 패 매수 보정 무시 정의가 일치하지 않습니다.'
                ),
            )],
            'ST4-001 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    speed_scenarios = []
    for name, owner, kwargs, expected in (
        ('qna-102-normal-two-combo-speed-five-is-legal', 'p1', {
            'source_speed': 4, 'proposal_speeds': (5,),
        }, {'legal': True, 'maximum': None}),
        ('qna-102-two-combo-still-requires-speed-rise', 'p2', {
            'source_speed': 5, 'proposal_speeds': (5,),
        }, {'legal': False, 'maximum': None}),
        ('owner-p1-four-combo-ignores-predecessor-speed', 'p1', {
            'source_speed': 5, 'proposal_speeds': (6, 8, 5),
            'appearance_index': 2,
        }, {'legal': True, 'maximum': None}),
        ('owner-p2-four-combo-ignores-predecessor-speed', 'p2', {
            'source_speed': 5, 'proposal_speeds': (6, 8, 5),
            'appearance_index': 2,
        }, {'legal': True, 'maximum': None}),
        ('numbered-negation-removes-four-combo-extension', 'p1', {
            'source_speed': 5, 'proposal_speeds': (6, 8, 5),
            'appearance_index': 2, 'numbered_negated': True,
        }, {'legal': False, 'maximum': None}),
        ('qna-20-following-card-uses-normal-rising-speed', 'p2', {
            'source_speed': 5, 'proposal_speeds': (6, 8, 5, 6),
            'appearance_index': 2, 'external_max_combo': 5,
        }, {'legal': True, 'maximum': 5}),
        ('qna-20-following-equal-speed-is-illegal', 'p1', {
            'source_speed': 5, 'proposal_speeds': (6, 8, 5, 5),
            'appearance_index': 2, 'external_max_combo': 5,
        }, {'legal': False, 'maximum': 5}),
    ):
        first = _run_st4_001_combo_scenario(
            definition, card_snapshot, owner, execute=False, **kwargs,
        )
        second = _run_st4_001_combo_scenario(
            definition, card_snapshot, owner, execute=False, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        speed_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    damage_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-two-combo-remaining-hand-three-no-penalty', 'p1', {
            'source_speed': 4, 'proposal_speeds': (5,),
            'filler_count': 3,
        }, {'legal': True, 'appearance_damage': 400}),
        ('owner-p2-two-combo-remaining-hand-three-no-penalty', 'p2', {
            'source_speed': 4, 'proposal_speeds': (5,),
            'filler_count': 3,
        }, {'legal': True, 'appearance_damage': 400}),
        ('remaining-hand-four-keeps-normal-two-combo-penalty', 'p1', {
            'source_speed': 4, 'proposal_speeds': (5,),
            'filler_count': 4,
        }, {'legal': True, 'appearance_damage': 300}),
        ('qna-578-future-third-card-is-not-counted-in-hand', 'p2', {
            'source_speed': 4, 'proposal_speeds': (5, 6),
            'appearance_index': 0, 'filler_count': 3,
        }, {'legal': True, 'appearance_damage': 400}),
        ('qna-578-used-as-third-also-ignores-penalty', 'p1', {
            'source_speed': 3, 'proposal_speeds': (4, 5),
            'appearance_index': 1, 'filler_count': 3,
        }, {'legal': True, 'appearance_damage': 400}),
        ('four-combo-applies-both-numbered-effects', 'p2', {
            'source_speed': 5, 'proposal_speeds': (6, 8, 5),
            'appearance_index': 2, 'filler_count': 3,
        }, {'legal': True, 'appearance_damage': 400}),
        ('external-damage-bonus-remains-when-penalty-is-ignored', 'p1', {
            'source_speed': 4, 'proposal_speeds': (5,),
            'filler_count': 3, 'damage_bonus': 100,
        }, {'legal': True, 'appearance_damage': 500}),
        ('numbered-negation-restores-normal-penalty', 'p2', {
            'source_speed': 4, 'proposal_speeds': (5,),
            'filler_count': 3, 'numbered_negated': True,
        }, {'legal': True, 'appearance_damage': 300}),
    ):
        first = _run_st4_001_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_001_combo_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
                and (
                    not first.get('legal')
                    or f'{owner}-appearance-blade'
                    in (first.get('combo_used_ids') or [])
                )
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            speed['id'], all(item['passed'] for item in speed_scenarios),
            speed_scenarios,
        ),
        AbilityReview(
            damage['id'], all(item['passed'] for item in damage_scenarios),
            damage_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST4-001 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st4_002_review_fixture(
    definition, card_snapshot, owner, *, source_zone='battle',
    opponent_speed=9, opponent_speed_delta=0, opponent_fp=0,
    owner_fp=0, opponent_special='', numbered_negated=False,
    list_speeds=(6, 7), list_speed_delta=0, include_hand_six=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _card('ST4-002', owner, f'{owner}-belgian-kick')
    source.update(copy.deepcopy(card_snapshot or {}))
    source.update({
        'instance_id': f'{owner}-belgian-kick', 'owner': owner,
        'code': 'ST4-002', 'name': '벨지언 킥', 'type': '공격',
        'frame': 6, 'damage': 500, 'pos': '하단', 'body': '발',
        'special': '상단 회피', 'hit': '2', 'guard': '-6',
        'counter': '3', 'face_up': source_zone == 'battle',
    })
    if numbered_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-BELGIAN-OPPONENT', other,
        f'{other}-belgian-opponent',
    )
    opposing.update({
        'name': '벨지언 상대 기술', 'type': '공격',
        'frame': opponent_speed, 'damage': 500, 'pos': '상단',
        'special': opponent_special, 'face_up': True,
    })
    support = None
    battle_source = source
    if source_zone != 'battle':
        support = _card(
            'REVIEW-BELGIAN-SUPPORT', owner,
            f'{owner}-belgian-support',
        )
        support.update({
            'name': '벨지언 검토 대체 기술', 'frame': 7,
            'damage': 400, 'pos': '하단', 'face_up': True,
        })
        battle_source = support
    state = _state(source, opposing, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [copy.deepcopy(support)]
    state['players'][owner]['fp'] = owner_fp
    state['players'][other]['fp'] = opponent_fp
    list_cards = []
    for index, speed in enumerate(list_speeds):
        card = _card(
            f'REVIEW-BELGIAN-CATCH-{index + 1}', owner,
            f'{owner}-belgian-catch-{index + 1}',
        )
        card.update({
            'name': f'리스트 캐치 {speed}속도', 'type': '공격',
            'frame': speed, 'damage': 300, 'hit': '2',
            'face_up': True,
        })
        list_cards.append(card)
    state['players'][owner]['zones']['list'] = copy.deepcopy(list_cards)
    hand_card = None
    if include_hand_six:
        hand_card = _card(
            'REVIEW-BELGIAN-HAND-CATCH', owner,
            f'{owner}-belgian-hand-catch',
        )
        hand_card.update({
            'name': '패의 6속도 기술', 'frame': 6,
            'damage': 300, 'face_up': False,
        })
        state['players'][owner]['zones']['hand'] = [copy.deepcopy(hand_card)]
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    for card in [*list_cards, *([hand_card] if hand_card else [])]:
        cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st4-002:{owner}:{source_zone}:{opponent_speed}:'
            f'{opponent_speed_delta}:{opponent_fp}:{owner_fp}:'
            f'{opponent_special}:{numbered_negated}:{list_speeds}:'
            f'{list_speed_delta}:{include_hand_six}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_source = engine._find_card(battle_source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_source['instance_id'],
            'card': copy.deepcopy(live_source),
        },
        other: {
            'instance_id': live_opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    if opponent_speed_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': other,
            'source': f'{owner}-belgian-opponent-speed',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'amount': opponent_speed_delta,
            'duration': 'battle',
        })
    if list_speed_delta and list_cards:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-belgian-list-speed',
            'where': {'instance_id': list_cards[0]['instance_id']},
            'stat': 'frame', 'amount': list_speed_delta,
            'duration': 'battle',
        })
    return engine, source, opposing, list_cards, hand_card


def _run_st4_002_defense_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    opponent_speed=9, opponent_speed_delta=0, opponent_fp=0,
    opponent_special='', numbered_negated=False,
):
    engine, source, opposing, _list_cards, _hand_card = (
        _st4_002_review_fixture(
            definition, card_snapshot, owner, source_zone=source_zone,
            opponent_speed=opponent_speed,
            opponent_speed_delta=opponent_speed_delta,
            opponent_fp=opponent_fp, opponent_special=opponent_special,
            numbered_negated=numbered_negated, list_speeds=(),
        )
    )
    other = 'p2' if owner == 'p1' else 'p1'
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    if not live_source:
        live_source = copy.deepcopy(source)
    engine._refresh_continuous_rules()
    reference_speed = engine.card_stat(
        live_opposing, 'frame', other, include_fp=False,
    )
    final_speed = engine.card_stat(
        live_opposing, 'frame', other, include_fp=True,
    )
    dodge_allowed = engine._defense_judgment_allowed(
        live_source, live_opposing, 'dodge', other,
    )
    result = {
        'dodge_allowed': dodge_allowed,
        'opponent_reference_speed': reference_speed,
        'opponent_final_speed': final_speed,
    }
    if source_zone == 'battle':
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        battle_result = engine.engine_state['battle'].get('result') or {}
        result.update({
            'owner_result': battle_result.get(owner),
            'opponent_result': battle_result.get(other),
            'trigger_sequence': [
                event_type for event_type, _context
                in engine.engine_state['battle'].get('trigger_sequence') or []
            ],
        })
    return result


def _run_st4_002_catch_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    event_type='dodge', mutual_dodge=False, numbered_negated=False,
    list_speeds=(6, 7), list_speed_delta=0, include_hand_six=False,
    owner_fp=5, opponent_fp=4, choose_index=None, decline=False,
):
    opponent_special = '하단 회피' if mutual_dodge else ''
    engine, source, opposing, list_cards, hand_card = (
        _st4_002_review_fixture(
            definition, card_snapshot, owner, source_zone=source_zone,
            opponent_speed=9, opponent_special=opponent_special,
            numbered_negated=numbered_negated,
            list_speeds=list_speeds, list_speed_delta=list_speed_delta,
            include_hand_six=include_hand_six,
            owner_fp=owner_fp, opponent_fp=opponent_fp,
        )
    )
    other = 'p2' if owner == 'p1' else 'p1'
    if mutual_dodge:
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        for trigger, context in (
            engine.engine_state['battle'].get('trigger_sequence') or []
        ):
            engine._fire(trigger, context)
    else:
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': copy.deepcopy(source),
            'opponent_card': copy.deepcopy(opposing),
            'source_battle_card_only': True,
        })
    granted = copy.deepcopy(engine.engine_state.get('granted_catches') or [])
    result = {
        'granted_count': len(granted), 'catch_ids': [],
        'hand_id': hand_card.get('instance_id') if hand_card else None,
        'selected_id': None, 'selected_zone': None,
        'owner_fp': engine.state['players'][owner]['fp'],
        'opponent_fp': engine.state['players'][other]['fp'],
        'battle_result': copy.deepcopy(
            engine.engine_state.get('battle', {}).get('result') or {}
        ),
        'resolution_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id') == 'st4-002-n1'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }
    if not granted:
        return result
    engine._open_catch_or_cleanup()
    actions = engine.legal_actions(owner)
    catch_actions = [
        action for action in actions
        if action.get('type') == 'play_catch_card'
    ]
    result['catch_ids'] = [
        (action.get('payload') or {}).get('card_instance_id')
        for action in catch_actions
    ]
    action = None
    if decline:
        action = next((
            item for item in actions if item.get('type') == 'decline_catch'
        ), None)
    elif choose_index is not None and catch_actions:
        action = catch_actions[min(choose_index, len(catch_actions) - 1)]
        result['selected_id'] = (
            action.get('payload') or {}
        ).get('card_instance_id')
    if action:
        engine.submit_action(
            owner, action['action_id'], {},
            command_id=(
                f'st4-002:{owner}:{event_type}:{mutual_dodge}:'
                f'{choose_index}:{decline}'
            ),
        )
    selected_id = result.get('selected_id')
    result.update({
        'selected_zone': (
            engine._find_location(selected_id)[1] if selected_id else None
        ),
        'owner_fp': engine.state['players'][owner]['fp'],
        'opponent_fp': engine.state['players'][other]['fp'],
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
        'catch_ended': any(
            event.get('type') == 'catch_ended' for event in engine.events
        ),
    })
    return result


def _review_st4_002_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-002':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st4-002-function')
    catch = by_id.get('st4-002-n1')
    qna_ids = [103, 270, 388, 398]
    catch_effect = {
        'op': 'grant_catch', 'player': {'controller': True},
        'allow_zones': ['list'], 'max_speed': 6,
        'break_after_use': True,
    }
    valid = bool(
        extra_root == {'defense_rules'}
        and definition.get('defense_rules') == [{'min_speed': 9}]
        and len(abilities) == 2
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('active_zones') == ['battle']
        and not function.get('trigger')
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['defense_rules'],
        }]
        and catch and catch.get('kind') == 'effect'
        and catch.get('mode') == 'mandatory'
        and catch.get('timing') == 'dodge'
        and catch.get('active_zones') == ['battle']
        and catch.get('trigger') == {'event': 'dodge'}
        and catch.get('effects') == [catch_effect]
        and int((card_snapshot or {}).get('frame') or 0) == 6
        and int((card_snapshot or {}).get('damage') or 0) == 500
        and str((card_snapshot or {}).get('pos') or '') == '하단'
        and str((card_snapshot or {}).get('special') or '') == '상단 회피'
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st4-002', False,
                reason=(
                    '벨지언 킥의 9속도 회피 제한 또는 리스트 6속도 '
                    '효과 캐치·사용 후 브레이크 정의가 일치하지 않습니다.'
                ),
            )],
            'ST4-002 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    defense_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-nine-speed-boundary-dodges', 'p1', {}, {
            'dodge_allowed': True, 'opponent_reference_speed': 9,
            'owner_result': 'counter', 'opponent_result': 'countered',
        }),
        ('owner-p2-nine-speed-boundary-dodges', 'p2', {}, {
            'dodge_allowed': True, 'owner_result': 'counter',
            'opponent_result': 'countered',
        }),
        ('eight-speed-cannot-be-dodged', 'p1', {
            'opponent_speed': 8,
        }, {'dodge_allowed': False}),
        ('twelve-speed-can-be-dodged', 'p2', {
            'opponent_speed': 12,
        }, {'dodge_allowed': True}),
        ('effect-speed-eight-to-nine-enables-dodge', 'p1', {
            'opponent_speed': 8, 'opponent_speed_delta': 1,
        }, {'dodge_allowed': True, 'opponent_reference_speed': 9}),
        ('positive-fp-does-not-change-reference-speed', 'p2', {
            'opponent_speed': 9, 'opponent_fp': 2,
        }, {'dodge_allowed': True, 'opponent_reference_speed': 9,
            'opponent_final_speed': 7}),
        ('qna-270-dodge-precedes-opponents-low-clash', 'p1', {
            'opponent_special': '하단 상쇄',
        }, {'owner_result': 'counter', 'opponent_result': 'countered'}),
    ):
        first = _run_st4_002_defense_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_002_defense_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        defense_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    catch_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-selects-list-six-and-breaks-after-use', 'p1', {
            'choose_index': 0,
        }, {'granted_count': 1, 'owner_fp': 2, 'opponent_fp': 0,
            'selected_zone': 'break', 'source_zone': 'hand',
            'pending': False}),
        ('owner-p2-selects-list-six-and-breaks-after-use', 'p2', {
            'choose_index': 0,
        }, {'granted_count': 1, 'owner_fp': 2, 'opponent_fp': 0,
            'selected_zone': 'break', 'pending': False}),
        ('speed-seven-list-card-is-not-offered', 'p1', {}, {
            'granted_count': 1,
        }),
        ('hand-speed-six-is-not-offered', 'p2', {
            'include_hand_six': True,
        }, {'granted_count': 1}),
        ('effect-speed-seven-to-six-is-offered', 'p1', {
            'list_speeds': (7,), 'list_speed_delta': -1,
        }, {'granted_count': 1}),
        ('qna-398-nonzero-fp-does-not-block-effect-catch', 'p2', {
            'owner_fp': 8, 'opponent_fp': 6, 'choose_index': 0,
        }, {'owner_fp': 2, 'opponent_fp': 0,
            'selected_zone': 'break'}),
        ('qna-103-mutual-dodge-still-grants-own-catch', 'p1', {
            'mutual_dodge': True,
        }, {'granted_count': 1,
            'battle_result': {'p1': 'dodge', 'p2': 'dodge'}}),
        ('declining-catch-keeps-fp-and-list-card', 'p2', {
            'owner_fp': 5, 'opponent_fp': 4, 'decline': True,
        }, {'owner_fp': 5, 'opponent_fp': 4, 'catch_ended': True}),
        ('numbered-negation-suppresses-catch-grant', 'p1', {
            'numbered_negated': True,
        }, {'granted_count': 0, 'resolution_count': 0}),
        ('wrong-result-event-does-not-grant-catch', 'p2', {
            'event_type': 'hit',
        }, {'granted_count': 0, 'resolution_count': 0}),
        ('catch-effect-is-inactive-outside-battle', 'p1', {
            'source_zone': 'list',
        }, {'granted_count': 0, 'resolution_count': 0}),
    ):
        first = _run_st4_002_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_002_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        extra_ok = True
        if name.startswith('speed-seven'):
            extra_ok = f'{owner}-belgian-catch-2' not in first['catch_ids']
        elif name.startswith('hand-speed'):
            extra_ok = first['hand_id'] not in first['catch_ids']
        elif name.startswith('effect-speed'):
            extra_ok = f'{owner}-belgian-catch-1' in first['catch_ids']
        catch_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and extra_ok
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            function['id'],
            all(item['passed'] for item in defense_scenarios),
            defense_scenarios,
        ),
        AbilityReview(
            catch['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST4-002 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st4_003_review_fixture(
    definition, card_snapshot, owner, *, source_zone='hand',
    advance_notice=False, numbered_negated=False, external_bonus=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _card('ST4-003', owner, f'{owner}-detroit-rabbit')
    source.update(copy.deepcopy(card_snapshot or {}))
    source.update({
        'instance_id': f'{owner}-detroit-rabbit', 'owner': owner,
        'code': 'ST4-003', 'name': '디트로이트 래빗', 'type': '공격',
        'frame': 7, 'damage': 500, 'pos': '중단', 'body': '',
        'special': '', 'hit': '2', 'guard': '-8', 'counter': '2',
        'face_up': source_zone == 'battle',
    })
    if numbered_negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-DETROIT-OPPONENT', other,
        f'{other}-detroit-opponent',
    )
    opposing.update({
        'name': '디트로이트 상대 기술', 'frame': 8,
        'damage': 600, 'pos': '상단', 'special': '중단 상쇄',
        'face_up': True,
    })
    support = None
    battle_source = source
    if source_zone != 'battle':
        support = _card(
            'REVIEW-DETROIT-SUPPORT', owner,
            f'{owner}-detroit-support',
        )
        support.update({
            'name': '디트로이트 콤보 시동', 'frame': 6,
            'damage': 500, 'pos': '하단', 'face_up': True,
        })
        battle_source = support
    state = _state(source, opposing, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [copy.deepcopy(support)]
    if advance_notice:
        state['players'][owner]['passive_state']['advance_notice'] = {
            'value': True,
        }
    other_catch = _card(
        'REVIEW-DETROIT-OTHER-CATCH', owner,
        f'{owner}-detroit-other-catch',
    )
    other_catch.update({
        'name': '다른 캐치 후보', 'frame': 6,
        'damage': 400, 'face_up': False,
    })
    if source_zone != 'hand':
        state['players'][owner]['zones']['hand'] = [copy.deepcopy(other_catch)]
    else:
        state['players'][owner]['zones']['hand'].append(copy.deepcopy(other_catch))
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
        other_catch['code']: {
            **copy.deepcopy(other_catch), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'st4-003:{owner}:{source_zone}:{advance_notice}:'
            f'{numbered_negated}:{external_bonus}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_battle_source = engine._find_card(battle_source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_battle_source['instance_id'],
            'card': copy.deepcopy(live_battle_source),
        },
        other: {
            'instance_id': live_opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
    }
    if external_bonus:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-detroit-external-bonus',
            'where': {'instance_id': source['instance_id']},
            'stat': 'damage', 'amount': external_bonus,
            'duration': 'battle',
        })
    return engine, source, opposing, other_catch, support


def _run_st4_003_function_scenario(
    definition, card_snapshot, owner, *, source_zone='hand',
    numbered_negated=False, resolve_battle=False,
):
    engine, source, opposing, other_catch, _support = (
        _st4_003_review_fixture(
            definition, card_snapshot, owner, source_zone=source_zone,
            numbered_negated=numbered_negated,
        )
    )
    other = 'p2' if owner == 'p1' else 'p1'
    live_source = engine._find_card(source['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    live_other = engine._find_card(other_catch['instance_id'])
    engine._refresh_continuous_rules()
    result = {
        'ready_allowed': engine._card_use_allowed(live_source, owner, 'ready'),
        'combo_allowed': engine._card_use_allowed(live_source, owner, 'combo'),
        'catch_allowed': engine._card_use_allowed(live_source, owner, 'catch'),
        'detroit_catch_blocked': engine._rule_blocked(
            'catch', owner, live_source, live_opposing,
        ),
        'other_catch_blocked': engine._rule_blocked(
            'catch', owner, live_other, live_opposing,
        ),
        'opponent_clash_blocked': engine._rule_blocked(
            'clash', other, live_opposing, live_source,
        ),
        'other_clash_blocked': engine._rule_blocked(
            'clash', other, live_opposing, live_other,
        ),
    }
    if resolve_battle:
        engine._capture_battle_speed()
        engine._resolve_battle_judgment()
        battle_result = engine.engine_state['battle'].get('result') or {}
        result.update({
            'owner_result': battle_result.get(owner),
            'opponent_result': battle_result.get(other),
        })
    return result


def _run_st4_003_damage_scenario(
    definition, card_snapshot, owner, *, source_zone='hand',
    advance_notice=False, numbered_negated=False, external_bonus=0,
    combo_six=False,
):
    engine, source, _opposing, _other_catch, support = (
        _st4_003_review_fixture(
            definition, card_snapshot, owner, source_zone=source_zone,
            advance_notice=advance_notice,
            numbered_negated=numbered_negated,
            external_bonus=external_bonus,
        )
    )
    live_source = engine._find_card(source['instance_id'])
    engine._refresh_continuous_rules()
    current_damage = engine.card_stat(live_source, 'damage', owner)
    projected = engine._project_card_for_use(live_source, owner, 'combo')
    projected_damage = engine.card_stat(projected, 'damage', owner)
    result = {
        'current_damage': current_damage,
        'projected_damage': projected_damage,
        'combo_legal': None, 'combo_damage': None,
    }
    if not combo_six:
        return result
    combo = {
        'owner': owner,
        'source': support['instance_id'] if support else source['instance_id'],
        'special': False,
        'used': [
            f'{owner}-detroit-prior-{index}' for index in range(4)
        ],
        'next_penalty': 500, 'last_speed': 6,
        'max_combo': 6, 'proposal_submitted': True,
        'proposed_card_ids': [source['instance_id']],
    }
    engine.engine_state['combo'] = copy.deepcopy(combo)
    legal = engine._combo_card_legal(
        owner, projected, combo, selected_speed=7,
    )
    result['combo_legal'] = legal
    if not legal:
        return result
    engine._start_combo_card(owner, [source['instance_id']], [7], [False], [])
    engine._continue()
    result['combo_damage'] = next((
        (event.get('payload') or {}).get('damage')
        for event in engine.events
        if event.get('type') == 'combo_card_used'
        and (event.get('payload') or {}).get('card_instance_id')
        == source['instance_id']
    ), None)
    return result


def _review_st4_003_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-003':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('st4-003-function')
    damage = by_id.get('st4-003-n1')
    qna_ids = [402]
    play_condition = {
        'op': 'not_equals',
        'left': 'context.use_context', 'right': 'catch',
    }
    function_effects = [
        {
            'op': 'prevent', 'kind': 'catch',
            'player': {'controller': True},
            'where': {'code': 'ST4-003'},
            'duration': 'continuous',
        },
        {
            'op': 'prevent', 'kind': 'clash',
            'player': {'opponent': True},
            'against_where': {'code': 'ST4-003'},
            'duration': 'continuous',
        },
    ]
    notice = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'advance_notice',
    }
    valid = bool(
        extra_root == {'play_condition'}
        and definition.get('play_condition') == play_condition
        and len(abilities) == 2
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and not function.get('trigger')
        and not function.get('active_zones')
        and function.get('effects') == function_effects
        and damage and damage.get('kind') == 'effect'
        and damage.get('mode') == 'continuous'
        and damage.get('timing') == 'function'
        and damage.get('active_zones') == ['battle']
        and not damage.get('trigger')
        and damage.get('condition') == notice
        and damage.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': 200,
            'duration': 'continuous',
        }]
        and int((card_snapshot or {}).get('frame') or 0) == 7
        and int((card_snapshot or {}).get('damage') or 0) == 500
        and str((card_snapshot or {}).get('pos') or '') == '중단'
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st4-003', False,
                reason=(
                    '디트로이트 래빗의 캐치·상쇄 금지 범위 또는 '
                    '예고 상태 배틀 존 데미지 정의가 일치하지 않습니다.'
                ),
            )],
            'ST4-003 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    function_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-cannot-catch-but-can-ready-and-combo', 'p1', {}, {
            'ready_allowed': True, 'combo_allowed': True,
            'catch_allowed': False, 'detroit_catch_blocked': True,
        }),
        ('owner-p2-cannot-catch-but-can-ready-and-combo', 'p2', {}, {
            'ready_allowed': True, 'combo_allowed': True,
            'catch_allowed': False, 'detroit_catch_blocked': True,
        }),
        ('catch-prohibition-does-not-block-another-card', 'p1', {}, {
            'other_catch_blocked': False,
        }),
        ('opponent-clash-against-detroit-is-blocked', 'p2', {
            'source_zone': 'battle',
        }, {'opponent_clash_blocked': True}),
        ('clash-prohibition-does-not-cover-another-card', 'p1', {}, {
            'other_clash_blocked': False,
        }),
        ('actual-battle-resolves-counter-instead-of-clash', 'p2', {
            'source_zone': 'battle', 'resolve_battle': True,
        }, {'owner_result': 'counter', 'opponent_result': 'countered'}),
        ('numbered-negation-does-not-remove-numberless-functions', 'p1', {
            'source_zone': 'battle', 'numbered_negated': True,
        }, {'catch_allowed': False, 'opponent_clash_blocked': True}),
    ):
        first = _run_st4_003_function_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_003_function_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        function_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    damage_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-hand-card-is-still-printed-five-hundred', 'p1', {
            'advance_notice': True,
        }, {'current_damage': 500, 'projected_damage': 700}),
        ('owner-p2-hand-card-is-still-printed-five-hundred', 'p2', {
            'advance_notice': True,
        }, {'current_damage': 500, 'projected_damage': 700}),
        ('battle-card-gains-two-hundred-with-advance-notice', 'p1', {
            'source_zone': 'battle', 'advance_notice': True,
        }, {'current_damage': 700, 'projected_damage': 700}),
        ('without-advance-notice-damage-remains-five-hundred', 'p2', {}, {
            'current_damage': 500, 'projected_damage': 500,
        }),
        ('numbered-negation-removes-advance-notice-bonus', 'p1', {
            'advance_notice': True, 'numbered_negated': True,
        }, {'current_damage': 500, 'projected_damage': 500}),
        ('external-damage-bonus-stacks-with-advance-notice', 'p2', {
            'source_zone': 'battle', 'advance_notice': True,
            'external_bonus': 100,
        }, {'current_damage': 800, 'projected_damage': 800}),
        ('qna-402-six-combo-is-legal-after-projected-bonus', 'p1', {
            'advance_notice': True, 'combo_six': True,
        }, {'combo_legal': True, 'combo_damage': 200}),
        ('qna-402-six-combo-is-illegal-without-bonus', 'p2', {
            'combo_six': True,
        }, {'combo_legal': False, 'combo_damage': None}),
    ):
        first = _run_st4_003_damage_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_003_damage_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            function['id'],
            all(item['passed'] for item in function_scenarios),
            function_scenarios,
        ),
        AbilityReview(
            damage['id'], all(item['passed'] for item in damage_scenarios),
            damage_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST4-003 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st4_ss_no_effect_definition():
    return {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []},
        'abilities': [],
    }


def _st4_ss_token(card_snapshot, owner, *, zone='lumen', negated=False):
    source = copy.deepcopy(card_snapshot or {})
    source.update({
        'instance_id': f'{owner}-{source.get("code", "st4-ss").lower()}-token',
        'owner': owner, 'kind': 'card', 'token_key': 'calling_card',
        'face_up': zone == 'lumen',
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _st4_ss_technique(
    owner, instance_id, *, code=None, card_type='공격', frame=8,
    damage=400, pos='중단', body='손',
):
    card = _card(code or f'REVIEW-ST4-SS-{instance_id}', owner, instance_id)
    card.update({
        'name': instance_id, 'type': card_type,
        'frame': frame if card_type == '공격' else None,
        'damage': damage if card_type == '공격' else None,
        'pos': pos if card_type == '공격' else None,
        'body': body if card_type == '공격' else '',
        'special': '', 'hit': '+3', 'guard': '-5', 'counter': '+4',
        'g_top': None, 'g_mid': None, 'g_bot': None,
        'character_key': 'kiss', 'face_up': True,
    })
    if card_type == '수비':
        card.update({
            'special': None, 'hit': None, 'guard': None, 'counter': None,
            'g_top': '방어', 'g_mid': '방어', 'g_bot': '방어',
        })
    return card


def _st4_ss_ruleset_entry(card, definition):
    return {
        **copy.deepcopy(card),
        'effect_definition': copy.deepcopy(definition),
    }


def _st4_ss_resolution_count(engine, ability_id):
    return sum(
        event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') == ability_id
        for event in engine.events
    )


def _st4_ss_engine(
    definition, card_snapshot, owner, *, source_zone='lumen', negated=False,
    owner_hand_types=(), opponent_hand_types=(), owner_position='중단',
    opponent_position='중단', owner_card_type='공격',
    opponent_card_type='공격', seed='st4-ss', owner_hand_count=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _st4_ss_token(
        card_snapshot, owner, zone=source_zone, negated=negated,
    )
    owner_card = _st4_ss_technique(
        owner, f'{owner}-st4-ss-owner-technique',
        code='REVIEW-ST4-SS-OWNER', card_type=owner_card_type,
        pos=owner_position,
    )
    opposing = _st4_ss_technique(
        other, f'{other}-st4-ss-opponent-technique',
        code='REVIEW-ST4-SS-OPPONENT', card_type=opponent_card_type,
        pos=opponent_position,
    )
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = 'battle'
    state['players'][owner]['hp'] = 5000
    state['players'][other]['hp'] = 5000
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = 0
    state['players'][owner]['zones']['battle'] = [copy.deepcopy(owner_card)]
    owner_hand = []
    for index, card_type in enumerate(owner_hand_types):
        owner_hand.append(_st4_ss_technique(
            owner, f'{owner}-st4-ss-owner-hand-{index}',
            code=f'REVIEW-ST4-SS-OWNER-HAND-{index}',
            card_type=card_type,
        ))
    for index in range(owner_hand_count):
        owner_hand.append(_st4_ss_technique(
            owner, f'{owner}-st4-ss-owner-count-{index}',
            code=f'REVIEW-ST4-SS-OWNER-COUNT-{index}',
        ))
    opponent_hand = [
        _st4_ss_technique(
            other, f'{other}-st4-ss-opponent-hand-{index}',
            code=f'REVIEW-ST4-SS-OPPONENT-HAND-{index}',
            card_type=card_type,
        )
        for index, card_type in enumerate(opponent_hand_types)
    ]
    state['players'][owner]['zones']['hand'] = copy.deepcopy(owner_hand)
    state['players'][other]['zones']['hand'] = copy.deepcopy(opponent_hand)
    no_effect = _st4_ss_no_effect_definition()
    cards = {
        source['code']: _st4_ss_ruleset_entry(source, definition),
        owner_card['code']: _st4_ss_ruleset_entry(owner_card, no_effect),
        opposing['code']: _st4_ss_ruleset_entry(opposing, no_effect),
    }
    for card in [*owner_hand, *opponent_hand]:
        cards[card['code']] = _st4_ss_ruleset_entry(card, no_effect)
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=seed, now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_owner = engine._find_card(owner_card['instance_id'])
    live_opposing = engine._find_card(opposing['instance_id'])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': live_owner['instance_id'],
            'card': copy.deepcopy(live_owner),
        },
        other: {
            'instance_id': live_opposing['instance_id'],
            'card': copy.deepcopy(live_opposing),
        },
        'actual_damage_received': {side: 0 for side in PLAYER_SIDES},
    }
    return engine, source, live_owner, live_opposing


def _st4_ss_event_context(controller, source_card, opponent_card, event):
    return {
        'controller': controller,
        'source_card_instance_id': source_card.get('instance_id'),
        'source_card': copy.deepcopy(source_card),
        'opponent_card': copy.deepcopy(opponent_card),
        'source_battle_card_only': True, 'result': event,
    }


def _run_st4_ss1_judgment_scenario(
    definition, card_snapshot, owner, *, event='hit', event_owner='owner',
    event_card_type='공격', source_zone='lumen', negated=False,
):
    engine, source, owner_card, opposing = _st4_ss_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        negated=negated, owner_card_type=event_card_type,
        seed=(
            f'st4-ss1-judgment:{owner}:{event}:{event_owner}:'
            f'{event_card_type}:{source_zone}:{negated}'
        ),
    )
    other = 'p2' if owner == 'p1' else 'p1'
    event_side = owner if event_owner == 'owner' else other
    event_card = owner_card if event_owner == 'owner' else opposing
    other_card = opposing if event_owner == 'owner' else owner_card
    hp_before = {
        side: engine.state['players'][side]['hp'] for side in PLAYER_SIDES
    }
    engine._fire(
        event,
        _st4_ss_event_context(event_side, event_card, other_card, event),
    )
    return {
        'owner_hp_loss': (
            hp_before[owner] - engine.state['players'][owner]['hp']
        ),
        'opponent_hp_loss': (
            hp_before[other] - engine.state['players'][other]['hp']
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st4_ss_resolution_count(
            engine, 'st4-ss1-hit-counter-damage',
        ),
    }


def _run_st4_ss1_damage_scenario(
    definition, card_snapshot, owner, *, attacker='opponent', target='owner',
    amount=300, source_zone='lumen', negated=False, pre_hit=False,
):
    engine, source, owner_card, opposing = _st4_ss_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        negated=negated,
        seed=(
            f'st4-ss1-damage:{owner}:{attacker}:{target}:{amount}:'
            f'{source_zone}:{negated}:{pre_hit}'
        ),
    )
    other = 'p2' if owner == 'p1' else 'p1'
    hp_before = {
        side: engine.state['players'][side]['hp'] for side in PLAYER_SIDES
    }
    if pre_hit:
        engine._fire(
            'hit', _st4_ss_event_context(
                owner, owner_card, opposing, 'hit',
            ),
        )
    attacker_side = owner if attacker == 'owner' else other
    target_side = owner if target == 'owner' else other
    damage_source = owner_card if attacker_side == owner else opposing
    engine.deal_damage(
        target_side, amount, source='review-st4-ss1',
        context={
            'controller': attacker_side,
            'source_card_instance_id': damage_source['instance_id'],
            'source_card': copy.deepcopy(damage_source),
            'result': 'hit',
        },
    )
    return {
        'owner_hp_loss': (
            hp_before[owner] - engine.state['players'][owner]['hp']
        ),
        'opponent_hp_loss': (
            hp_before[other] - engine.state['players'][other]['hp']
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st4_ss_resolution_count(
            engine, 'st4-ss1-opponent-damage-return',
        ),
        'bonus_resolved': _st4_ss_resolution_count(
            engine, 'st4-ss1-hit-counter-damage',
        ),
    }


def _run_st4_ss2_scenario(
    definition, card_snapshot, owner, *, event='dodge',
    event_owner='owner', hand_types=('수비',), source_zone='lumen',
    negated=False,
):
    engine, source, owner_card, opposing = _st4_ss_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        negated=negated, opponent_hand_types=hand_types,
        seed=(
            f'st4-ss2:{owner}:{event}:{event_owner}:{hand_types}:'
            f'{source_zone}:{negated}'
        ),
    )
    other = 'p2' if owner == 'p1' else 'p1'
    event_side = owner if event_owner == 'owner' else other
    event_card = owner_card if event_owner == 'owner' else opposing
    other_card = opposing if event_owner == 'owner' else owner_card
    engine._fire(
        event,
        _st4_ss_event_context(event_side, event_card, other_card, event),
    )
    random_events = [
        event_item for event_item in engine.events
        if event_item.get('type') == 'random_resolved'
    ]
    return {
        'opponent_hand_count': len(engine._zone(other, 'hand')),
        'opponent_list_types': sorted(
            str(card.get('type')) for card in engine._zone(other, 'list')
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'opponent_get_skipped': bool(
            (engine.engine_state.get('skip_get') or {}).get(other)
        ),
        'resolved': _st4_ss_resolution_count(
            engine, 'st4-ss2-dodge-guard-random-discard',
        ),
        'random_event_count': len(random_events),
        'random_visibility': (
            random_events[0].get('visibility') if random_events else None
        ),
    }


def _run_st4_ss3_speed_scenario(
    definition, card_snapshot, owner, *, owner_position='중단',
    opponent_position='중단', owner_card_type='공격',
    opponent_card_type='공격', event_owner='owner', source_zone='lumen',
    negated=False, external_delta=0, owner_fp=0,
):
    engine, source, owner_card, opposing = _st4_ss_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        negated=negated, owner_position=owner_position,
        opponent_position=opponent_position,
        owner_card_type=owner_card_type,
        opponent_card_type=opponent_card_type,
        seed=(
            f'st4-ss3-speed:{owner}:{owner_position}:{opponent_position}:'
            f'{owner_card_type}:{opponent_card_type}:{event_owner}:'
            f'{source_zone}:{negated}:{external_delta}:{owner_fp}'
        ),
    )
    other = 'p2' if owner == 'p1' else 'p1'
    engine.state['players'][owner]['fp'] = owner_fp
    if external_delta:
        engine.add_modifier({
            'op': 'modify_stat', 'controller': owner, 'player': owner,
            'source': f'{owner}-st4-ss3-external',
            'where': {'instance_id': owner_card['instance_id']},
            'stat': 'frame', 'amount': external_delta,
            'duration': 'battle',
        })
    event_side = owner if event_owner == 'owner' else other
    event_card = owner_card if event_owner == 'owner' else opposing
    other_card = opposing if event_owner == 'owner' else owner_card
    engine._fire(
        'before_judgment',
        _st4_ss_event_context(
            event_side, event_card, other_card, 'before_judgment',
        ),
    )
    return {
        'owner_reference_speed': engine.card_stat(
            owner_card, 'frame', owner, include_fp=False,
        ),
        'owner_final_speed': engine.card_stat(
            owner_card, 'frame', owner, include_fp=True,
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st4_ss_resolution_count(
            engine, 'st4-ss3-matching-position-speed',
        ),
    }


def _run_st4_ss3_hand_scenario(
    definition, card_snapshot, owner, *, initial_hand=4,
    action='move_owner', source_zone='lumen', negated=False,
):
    engine, source, _owner_card, _opposing = _st4_ss_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        negated=negated, owner_hand_count=initial_hand,
        seed=(
            f'st4-ss3-hand:{owner}:{initial_hand}:{action}:'
            f'{source_zone}:{negated}'
        ),
    )
    other = 'p2' if owner == 'p1' else 'p1'
    no_effect = _st4_ss_no_effect_definition()
    if action == 'enter_lumen':
        engine.move_card(source['instance_id'], 'lumen', reason='review-enter')
    else:
        moving_owner = owner if action == 'move_owner' else other
        moving = _st4_ss_technique(
            moving_owner, f'{moving_owner}-st4-ss3-moving',
            code=f'REVIEW-ST4-SS3-MOVING-{moving_owner}',
        )
        engine._zone(moving_owner, 'side').append(copy.deepcopy(moving))
        engine.ruleset['cards'][moving['code']] = _st4_ss_ruleset_entry(
            moving, no_effect,
        )
        engine.move_card(moving['instance_id'], 'hand', reason='review-hand')
    return {
        'owner_hand_count': len(engine._zone(owner, 'hand')),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st4_ss_resolution_count(
            engine, 'st4-ss3-hand-threshold-return',
        ),
    }


def _st4_ss_scenarios(runner, definition, card_snapshot, cases):
    results = []
    for name, owner, kwargs, expected in cases:
        first = runner(definition, card_snapshot, owner, **kwargs)
        second = runner(definition, card_snapshot, owner, **kwargs)
        deterministic = _canonical(first) == _canonical(second)
        results.append({
            'name': name,
            'passed': bool(
                deterministic and all(
                    first.get(key) == value for key, value in expected.items()
                )
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })
    return results


def _st4_ss_base_snapshot_matches(card_snapshot, code, name, body):
    expected = {
        'code': code, 'name': name, 'type': '특수',
        'frame': None, 'damage': None, 'pos': None, 'body': body,
        'special': None, 'hit': None, 'guard': None, 'counter': None,
        'g_top': None, 'g_mid': None, 'g_bot': None, 'character_id': 5,
    }
    return all((card_snapshot or {}).get(key) == value for key, value in expected.items())


def _review_st4_ss1_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-SS1':
        return None
    qna_ids = [100, 484, 243, 72]
    by_id = {
        ability.get('id'): ability
        for ability in definition.get('abilities') or []
    }
    damage = by_id.get('st4-ss1-hit-counter-damage')
    leave = by_id.get('st4-ss1-opponent-damage-return')
    exact = bool(
        not extra_root
        and definition.get('token_key') == 'calling_card'
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and set(by_id) == {
            'st4-ss1-hit-counter-damage',
            'st4-ss1-opponent-damage-return',
        }
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            and ability.get('kind') == 'function'
            and ability.get('mode') == 'mandatory'
            and ability.get('active_zones') == ['lumen']
            for ability in by_id.values()
        )
        and damage.get('timing') == 'hit_counter'
        and damage.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and damage.get('condition') == {
            'op': 'all', 'conditions': [
                {
                    'op': 'equals', 'left': 'context.event_controller',
                    'right': {'controller': True},
                },
                {
                    'op': 'card_matches',
                    'card': {'path': 'context.event_card'},
                    'where': {
                        'type_contains': '공격', 'is_technique': True,
                    },
                },
            ],
        }
        and damage.get('effects') == [{
            'op': 'deal_damage', 'player': {'opponent': True}, 'amount': 100,
        }]
        and leave.get('timing') == 'result'
        and leave.get('trigger') == {'event': 'damage_after'}
        and leave.get('condition') == {
            'op': 'all', 'conditions': [
                {
                    'op': 'equals', 'left': 'context.event_controller',
                    'right': {'opponent': True},
                },
                {
                    'op': 'equals', 'left': 'context.player',
                    'right': {'controller': True},
                },
                {'op': 'gt', 'left': 'context.amount', 'right': 0},
            ],
        }
        and leave.get('effects') == [{'op': 'move_card', 'to_zone': 'side'}]
        and _st4_ss_base_snapshot_matches(
            card_snapshot, 'ST4-SS1', '환상의 쟈르갈', None,
        )
    )
    if not exact:
        return DefinitionReview(
            False, False, reason='ST4-SS1 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    damage_scenarios = _st4_ss_scenarios(
        _run_st4_ss1_judgment_scenario, definition, card_snapshot,
        (
            ('owner-p1-hit-deals-one-hundred', 'p1', {}, {
                'opponent_hp_loss': 100, 'resolved': 1,
                'source_zone': 'lumen',
            }),
            ('owner-p2-counter-deals-one-hundred', 'p2', {
                'event': 'counter',
            }, {'opponent_hp_loss': 100, 'resolved': 1}),
            ('qna-243-combo-is-not-hit-or-counter', 'p1', {
                'event': 'combo',
            }, {'opponent_hp_loss': 0, 'resolved': 0}),
            ('opponent-hit-does-not-use-owner-calling-card', 'p2', {
                'event_owner': 'opponent',
            }, {'opponent_hp_loss': 0, 'owner_hp_loss': 0, 'resolved': 0}),
            ('defense-card-event-is-not-an-attacking-technique', 'p1', {
                'event_card_type': '수비',
            }, {'opponent_hp_loss': 0, 'resolved': 0}),
            ('source-outside-lumen-is-inactive', 'p2', {
                'source_zone': 'side',
            }, {'opponent_hp_loss': 0, 'resolved': 0}),
            ('numbered-negation-does-not-disable-numberless-function', 'p1', {
                'negated': True,
            }, {'opponent_hp_loss': 100, 'resolved': 1}),
        ),
    )
    leave_scenarios = _st4_ss_scenarios(
        _run_st4_ss1_damage_scenario, definition, card_snapshot,
        (
            ('owner-p1-receives-opponent-damage-and-returns', 'p1', {}, {
                'owner_hp_loss': 300, 'source_zone': 'side', 'resolved': 1,
            }),
            ('owner-p2-receives-opponent-damage-and-returns', 'p2', {}, {
                'owner_hp_loss': 300, 'source_zone': 'side', 'resolved': 1,
            }),
            ('self-inflicted-damage-does-not-return-card', 'p1', {
                'attacker': 'owner',
            }, {'owner_hp_loss': 300, 'source_zone': 'lumen', 'resolved': 0}),
            ('damage-to-opponent-does-not-return-card', 'p2', {
                'attacker': 'owner', 'target': 'opponent',
            }, {
                'opponent_hp_loss': 300, 'source_zone': 'lumen',
                'resolved': 0,
            }),
            ('zero-damage-does-not-return-card', 'p1', {'amount': 0}, {
                'owner_hp_loss': 0, 'source_zone': 'lumen', 'resolved': 0,
            }),
            ('source-outside-lumen-cannot-return-again', 'p2', {
                'source_zone': 'side',
            }, {'owner_hp_loss': 300, 'source_zone': 'side', 'resolved': 0}),
            ('qna-100-hit-bonus-resolves-before-card-returns', 'p1', {
                'pre_hit': True,
            }, {
                'opponent_hp_loss': 100, 'owner_hp_loss': 300,
                'bonus_resolved': 1, 'source_zone': 'side', 'resolved': 1,
            }),
            ('numbered-negation-does-not-disable-return-function', 'p2', {
                'negated': True,
            }, {'source_zone': 'side', 'resolved': 1}),
        ),
    )
    reviews = [
        AbilityReview(
            damage['id'], all(item['passed'] for item in damage_scenarios),
            damage_scenarios,
        ),
        AbilityReview(
            leave['id'], all(item['passed'] for item in leave_scenarios),
            leave_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '환상의 쟈르갈 카드별 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _review_st4_ss2_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-SS2':
        return None
    qna_ids = [285, 316, 484, 242, 72]
    abilities = definition.get('abilities') or []
    ability = abilities[0] if len(abilities) == 1 else None
    effects = (ability or {}).get('effects') or []
    random_key = 'st4_ss2_random_hand'
    discarded_key = 'st4_ss2_discarded_hand'
    exact = bool(
        not extra_root
        and definition.get('token_key') == 'calling_card'
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and ability
        and ability.get('id') == 'st4-ss2-dodge-guard-random-discard'
        and (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
        and ability.get('kind') == 'function'
        and ability.get('mode') == 'mandatory'
        and ability.get('timing') == 'result'
        and ability.get('active_zones') == ['lumen']
        and ability.get('trigger') == {
            'event': 'dodge', 'events': ['dodge', 'guard'],
        }
        and ability.get('condition') == {
            'op': 'equals', 'left': 'context.event_controller',
            'right': {'controller': True},
        }
        and len(effects) == 4
        and effects[0] == {
            'op': 'random_select',
            'selector': {
                'kind': 'card', 'player': {'opponent': True},
                'zones': ['hand'], 'min': 0, 'max': 1,
                'as_operation': 'discard',
            },
            'count': 1, 'selection_key': random_key,
            'visibility': 'private',
        }
        and effects[1] == {
            'op': 'discard', 'selection_key': random_key,
            'result_key': discarded_key,
        }
        and effects[2] == {
            'op': 'conditional',
            'condition': {
                'op': 'gte',
                'left': {
                    'op': 'selection_count',
                    'selection_key': discarded_key,
                    'where': {'type_contains': '수비'},
                },
                'right': 1,
            },
            'then': [{'op': 'skip_get', 'player': {'opponent': True}}],
            'else': [],
        }
        and effects[3] == {
            'op': 'conditional',
            'condition': {
                'op': 'gte',
                'left': {
                    'op': 'selection_count',
                    'selection_key': discarded_key,
                    'where': {'type_contains': '공격'},
                },
                'right': 1,
            },
            'then': [{'op': 'move_card', 'to_zone': 'side'}],
            'else': [],
        }
        and _st4_ss_base_snapshot_matches(
            card_snapshot, 'ST4-SS2', '매혹의 로돌라', '',
        )
    )
    if not exact:
        return DefinitionReview(
            False, False, reason='ST4-SS2 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    scenarios = _st4_ss_scenarios(
        _run_st4_ss2_scenario, definition, card_snapshot,
        (
            ('owner-p1-dodge-discards-defense-and-skips-get', 'p1', {}, {
                'opponent_hand_count': 0, 'opponent_list_types': ['수비'],
                'opponent_get_skipped': True, 'source_zone': 'lumen',
                'resolved': 1, 'random_event_count': 1,
                'random_visibility': 'private',
            }),
            ('owner-p2-guard-discards-defense-and-skips-get', 'p2', {
                'event': 'guard',
            }, {
                'opponent_list_types': ['수비'],
                'opponent_get_skipped': True, 'source_zone': 'lumen',
                'resolved': 1,
            }),
            ('attack-discard-returns-calling-card-without-get-skip', 'p1', {
                'hand_types': ('공격',),
            }, {
                'opponent_list_types': ['공격'],
                'opponent_get_skipped': False, 'source_zone': 'side',
                'resolved': 1,
            }),
            ('empty-opponent-hand-resolves-without-branch', 'p2', {
                'hand_types': (),
            }, {
                'opponent_hand_count': 0, 'opponent_list_types': [],
                'opponent_get_skipped': False, 'source_zone': 'lumen',
                'resolved': 1, 'random_event_count': 1,
            }),
            ('opponent-dodge-does-not-trigger-owner-card', 'p1', {
                'event_owner': 'opponent',
            }, {
                'opponent_hand_count': 1, 'opponent_list_types': [],
                'resolved': 0, 'random_event_count': 0,
            }),
            ('combo-is-not-dodge-or-guard', 'p2', {'event': 'combo'}, {
                'opponent_hand_count': 1, 'resolved': 0,
                'random_event_count': 0,
            }),
            ('source-outside-lumen-is-inactive', 'p1', {
                'source_zone': 'side',
            }, {'opponent_hand_count': 1, 'resolved': 0}),
            ('numbered-negation-does-not-disable-random-function', 'p2', {
                'negated': True,
            }, {
                'opponent_hand_count': 0, 'opponent_get_skipped': True,
                'resolved': 1,
            }),
        ),
    )
    passed = all(item['passed'] for item in scenarios)
    return DefinitionReview(
        passed, False, [AbilityReview(ability['id'], passed, scenarios)],
        '' if passed else '매혹의 로돌라 카드별 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _review_st4_ss3_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-SS3':
        return None
    qna_ids = [101, 484, 72]
    by_id = {
        ability.get('id'): ability
        for ability in definition.get('abilities') or []
    }
    speed = by_id.get('st4-ss3-matching-position-speed')
    leave = by_id.get('st4-ss3-hand-threshold-return')
    exact = bool(
        not extra_root
        and definition.get('token_key') == 'calling_card'
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and set(by_id) == {
            'st4-ss3-matching-position-speed',
            'st4-ss3-hand-threshold-return',
        }
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            and ability.get('kind') == 'function'
            and ability.get('mode') == 'mandatory'
            and ability.get('active_zones') == ['lumen']
            for ability in by_id.values()
        )
        and speed.get('timing') == 'before_judgment'
        and speed.get('trigger') == {'event': 'before_judgment'}
        and speed.get('condition') == {
            'op': 'all', 'conditions': [
                {
                    'op': 'equals', 'left': 'context.event_controller',
                    'right': {'controller': True},
                },
                {
                    'op': 'card_matches',
                    'card': {'path': 'context.event_card'},
                    'where': {
                        'type_contains': '공격', 'is_technique': True,
                    },
                },
                {
                    'op': 'card_matches',
                    'card': {'path': 'context.opponent_card'},
                    'where': {
                        'type_contains': '공격', 'is_technique': True,
                    },
                },
                {
                    'op': 'equals',
                    'left': {'path': 'context.event_card.pos'},
                    'right': {'path': 'context.opponent_card.pos'},
                },
            ],
        }
        and speed.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'target_card': 'event_card', 'stat': 'frame',
            'amount': -3, 'duration': 'battle',
        }]
        and leave.get('timing') == 'result'
        and leave.get('trigger') == {'event': 'card_moved'}
        and leave.get('condition') == {
            'op': 'all', 'conditions': [
                {
                    'op': 'equals', 'left': 'context.event_controller',
                    'right': {'controller': True},
                },
                {
                    'op': 'zone_count', 'player': {'controller': True},
                    'zone': 'hand', 'min': 5,
                },
            ],
        }
        and leave.get('effects') == [{'op': 'move_card', 'to_zone': 'side'}]
        and _st4_ss_base_snapshot_matches(
            card_snapshot, 'ST4-SS3', '소원의 가온', '',
        )
    )
    if not exact:
        return DefinitionReview(
            False, False, reason='ST4-SS3 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    speed_scenarios = _st4_ss_scenarios(
        _run_st4_ss3_speed_scenario, definition, card_snapshot,
        (
            ('owner-p1-same-position-speeds-up-three', 'p1', {}, {
                'owner_reference_speed': 5, 'resolved': 1,
            }),
            ('owner-p2-same-position-speeds-up-three', 'p2', {}, {
                'owner_reference_speed': 5, 'resolved': 1,
            }),
            ('different-position-does-not-speed-up', 'p1', {
                'opponent_position': '상단',
            }, {'owner_reference_speed': 8, 'resolved': 0}),
            ('owner-defense-is-not-an-attack-technique', 'p2', {
                'owner_card_type': '수비',
            }, {'resolved': 0}),
            ('opponent-defense-is-not-an-attack-technique', 'p1', {
                'opponent_card_type': '수비',
            }, {'owner_reference_speed': 8, 'resolved': 0}),
            ('opponent-timing-slot-does-not-modify-owner-technique', 'p2', {
                'event_owner': 'opponent',
            }, {'owner_reference_speed': 8, 'resolved': 0}),
            ('source-outside-lumen-is-inactive', 'p1', {
                'source_zone': 'side',
            }, {'owner_reference_speed': 8, 'resolved': 0}),
            ('qna-101-external-speed-effect-stacks-in-chosen-order', 'p2', {
                'external_delta': -2,
            }, {'owner_reference_speed': 3, 'resolved': 1}),
            ('fp-does-not-change-reference-speed-condition', 'p1', {
                'owner_fp': 4,
            }, {
                'owner_reference_speed': 5, 'owner_final_speed': 1,
                'resolved': 1,
            }),
            ('numbered-negation-does-not-disable-speed-function', 'p2', {
                'negated': True,
            }, {'owner_reference_speed': 5, 'resolved': 1}),
        ),
    )
    hand_scenarios = _st4_ss_scenarios(
        _run_st4_ss3_hand_scenario, definition, card_snapshot,
        (
            ('owner-p1-hand-reaches-five-and-card-returns', 'p1', {}, {
                'owner_hand_count': 5, 'source_zone': 'side', 'resolved': 1,
            }),
            ('owner-p2-hand-reaches-five-and-card-returns', 'p2', {}, {
                'owner_hand_count': 5, 'source_zone': 'side', 'resolved': 1,
            }),
            ('hand-reaches-only-four-and-card-remains', 'p1', {
                'initial_hand': 3,
            }, {'owner_hand_count': 4, 'source_zone': 'lumen', 'resolved': 0}),
            ('opponent-card-move-does-not-trigger-owner-threshold', 'p2', {
                'initial_hand': 5, 'action': 'move_opponent',
            }, {'owner_hand_count': 5, 'source_zone': 'lumen', 'resolved': 0}),
            ('entering-lumen-with-five-cards-returns-immediately', 'p1', {
                'initial_hand': 5, 'action': 'enter_lumen',
                'source_zone': 'side',
            }, {'owner_hand_count': 5, 'source_zone': 'side', 'resolved': 1}),
            ('source-outside-lumen-is-inactive', 'p2', {
                'source_zone': 'side',
            }, {'owner_hand_count': 5, 'source_zone': 'side', 'resolved': 0}),
            ('numbered-negation-does-not-disable-threshold-function', 'p1', {
                'negated': True,
            }, {'source_zone': 'side', 'resolved': 1}),
        ),
    )
    reviews = [
        AbilityReview(
            speed['id'], all(item['passed'] for item in speed_scenarios),
            speed_scenarios,
        ),
        AbilityReview(
            leave['id'], all(item['passed'] for item in hand_scenarios),
            hand_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '소원의 가온 카드별 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _st4_ps1_review_fixture(
    definition, card_snapshot, owner, *, hand_count=4,
    calling_lumen=0, calling_side=3, numbered_negated=False,
    normal_side=2, global_trait_negation=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    trait = _card('ST4-PS1', owner, f'{owner}-notice-trait')
    trait.update(copy.deepcopy(card_snapshot or {}))
    trait.update({
        'instance_id': f'{owner}-notice-trait', 'owner': owner,
        'code': 'ST4-PS1', 'name': '예고', 'type': '특성',
        'face_up': True,
    })
    if numbered_negated:
        trait['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-NOTICE-OPPONENT', other,
        f'{other}-notice-opponent',
    )
    state = _state(trait, opposing, owner, source_zone='passive')
    state['phase'] = 'lumen'
    calling_cards = []
    calling_codes = ('ST4-SS1', 'ST4-SS2', 'ST4-SS3')
    for index in range(calling_lumen + calling_side):
        card = _card(
            calling_codes[index % len(calling_codes)], owner,
            f'{owner}-calling-{index + 1}',
        )
        card.update({
            'name': f'예고장 {index + 1}', 'type': '특수',
            'frame': None, 'damage': None, 'pos': None,
            'token_key': 'calling_card', 'face_up': index < calling_lumen,
        })
        calling_cards.append(card)
    state['players'][owner]['zones']['lumen'] = [
        copy.deepcopy(card) for card in calling_cards[:calling_lumen]
    ]
    state['players'][owner]['zones']['side'] = [
        copy.deepcopy(card) for card in calling_cards[calling_lumen:]
    ]
    normal_cards = []
    for index in range(normal_side):
        card = _card(
            f'REVIEW-NOTICE-SIDE-{index + 1}', owner,
            f'{owner}-notice-side-{index + 1}',
        )
        card.update({
            'name': f'사이드 기술 {index + 1}',
            'type': '공격' if index % 2 == 0 else '수비',
            'face_up': False,
        })
        normal_cards.append(card)
        state['players'][owner]['zones']['side'].append(copy.deepcopy(card))
    hand_cards = []
    for index in range(hand_count):
        card = _card(
            f'REVIEW-NOTICE-HAND-{index + 1}', owner,
            f'{owner}-notice-hand-{index + 1}',
        )
        card['face_up'] = False
        hand_cards.append(card)
    state['players'][owner]['zones']['hand'] = [
        copy.deepcopy(card) for card in hand_cards
    ]
    no_effect = {
        'schema_version': 1, 'reviewed': True, 'no_effect': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []},
        'abilities': [],
    }
    released_cards = {
        trait['code']: {
            **copy.deepcopy(trait),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing),
            'effect_definition': copy.deepcopy(no_effect),
        },
    }
    for card in [*calling_cards, *normal_cards, *hand_cards]:
        released_cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(no_effect),
        }
    if global_trait_negation:
        charm = _card(
            'REVIEW-NOTICE-CHARM', other,
            f'{other}-notice-charm',
        )
        charm.update({'type': '특수', 'face_up': True})
        state['players'][other]['zones']['lumen'].append(copy.deepcopy(charm))
        released_cards[charm['code']] = {
            **copy.deepcopy(charm),
            'effect_definition': {
                **copy.deepcopy(no_effect),
                'no_effect': False,
                'trait_negation': {
                    'players': 'both', 'active_zones': ['lumen'],
                },
            },
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': released_cards},
        seed=(
            f'st4-ps1:{owner}:{hand_count}:{calling_lumen}:'
            f'{calling_side}:{numbered_negated}:{normal_side}:'
            f'{global_trait_negation}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, trait, calling_cards, normal_cards, opposing


def _st4_ps1_resolved_count(engine, ability_id):
    return sum(
        event.get('type') == 'effect_resolved'
        and (event.get('payload') or {}).get('ability_id') == ability_id
        for event in engine.events
    )


def _run_st4_ps1_place_scenario(
    definition, card_snapshot, owner, *, hand_count=4,
    calling_lumen=0, calling_side=3, previous_index=None,
    choose_index=0, phase='lumen', numbered_negated=False,
    protect_after_choice=False,
):
    engine, _trait, calling_cards, _normal, _opposing = (
        _st4_ps1_review_fixture(
            definition, card_snapshot, owner,
            hand_count=hand_count, calling_lumen=calling_lumen,
            calling_side=calling_side, numbered_negated=numbered_negated,
        )
    )
    engine.state['phase'] = phase
    if previous_index is not None and calling_cards:
        remembered = calling_cards[min(previous_index, len(calling_cards) - 1)]
        engine.engine_state.setdefault('effect_memory', {}).setdefault(
            owner, {},
        )['st4_ps1_last_calling_card'] = remembered['instance_id']
    engine._fire('phase_start', {'phase': phase})
    decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    option_ids = [str(item.get('id')) for item in decision.get('options') or []]
    selected_id = None
    if decision:
        selected_id = option_ids[min(choose_index, len(option_ids) - 1)]
        if protect_after_choice:
            selected = engine._find_card(selected_id)
            released = (engine.ruleset.get('cards') or {}).get(
                str((selected or {}).get('code') or ''),
            )
            if released is not None:
                released['effect_definition'] = {
                    'schema_version': 1, 'reviewed': True,
                    'no_effect': False,
                    'source_refs': {'rulebook_pages': [], 'qna_ids': []},
                    'abilities': [],
                    'effect_immunity': {'scope': 'other_cards'},
                }
        engine._submit_decision(owner, decision['id'], [selected_id])
    lumen = engine._zone(owner, 'lumen')
    remembered = (
        (engine.engine_state.get('effect_memory') or {})
        .get(owner, {}).get('st4_ps1_last_calling_card')
    )
    has_notice = condition_matches(
        {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'advance_notice',
        },
        engine.state, {'controller': owner},
    )
    return {
        'decision_kind': decision.get('kind'),
        'decision_owner': decision.get('owner'),
        'option_ids': option_ids, 'selected_id': selected_id,
        'lumen_ids': [card.get('instance_id') for card in lumen],
        'lumen_face_up': [bool(card.get('face_up')) for card in lumen],
        'remembered': remembered, 'has_notice': has_notice,
        'resolution_count': _st4_ps1_resolved_count(
            engine, 'st4-ps1-n1-place',
        ),
        'choice_skipped': any(
            event.get('type') == 'effect_choice_skipped'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_st4_ps1_limit_scenario(
    definition, card_snapshot, owner, *, numbered_negated=False,
    unrelated=False, remove_existing=False,
):
    engine, _trait, calling_cards, normal_cards, opposing = (
        _st4_ps1_review_fixture(
            definition, card_snapshot, owner,
            calling_lumen=1, calling_side=1,
            numbered_negated=numbered_negated, normal_side=1,
        )
    )
    existing = calling_cards[0]
    if remove_existing:
        engine.move_card(existing['instance_id'], 'side', reason='review-remove')
    target = normal_cards[0] if unrelated else calling_cards[1]
    before_zone = engine._find_location(target['instance_id'])[1]
    moved = engine.move_card(
        target['instance_id'], 'lumen', reason='review-external-effect',
        effect_controller=owner,
        effect_source=opposing['instance_id'],
    )
    return {
        'before_zone': before_zone,
        'after_zone': engine._find_location(target['instance_id'])[1],
        'moved': moved is not None,
        'calling_count': sum(
            card.get('token_key') == 'calling_card'
            for card in engine._zone(owner, 'lumen')
        ),
        'prevented': any(
            event.get('type') == 'card_move_prevented'
            and (event.get('payload') or {}).get('card_instance_id')
            == target['instance_id']
            for event in engine.events
        ),
    }


def _run_st4_ps1_state_scenario(
    definition, card_snapshot, owner, *, calling_lumen=1,
    numbered_negated=False, global_trait_negation=False,
    remove_calling=False,
):
    engine, _trait, calling_cards, _normal, _opposing = (
        _st4_ps1_review_fixture(
            definition, card_snapshot, owner,
            calling_lumen=calling_lumen, calling_side=max(0, 1 - calling_lumen),
            numbered_negated=numbered_negated,
            global_trait_negation=global_trait_negation,
        )
    )
    state_condition = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'advance_notice',
    }
    engine._refresh_continuous_state_grants()
    before = condition_matches(
        state_condition, engine.state, {'controller': owner},
    )
    if remove_calling and calling_cards:
        engine.move_card(
            calling_cards[0]['instance_id'], 'side', reason='review-remove',
        )
    engine._refresh_continuous_state_grants()
    after = condition_matches(
        state_condition, engine.state, {'controller': owner},
    )
    grants = copy.deepcopy(
        ((engine.engine_state.get('continuous_states') or {}).get(owner) or {})
        .get('advance_notice') or []
    )
    return {'before': before, 'after': after, 'grant_sources': grants}


def _run_st4_ps1_break_scenario(
    definition, card_snapshot, owner, *, event_owner='owner',
    calling=True, normal_side=2, choose_index=0,
    no_candidate=False, protect_index=None, protect_after_choice=False,
    invalid_list_move=False, numbered_negated=False, starting_fp=5,
):
    actual_event_owner = owner if event_owner == 'owner' else (
        'p2' if owner == 'p1' else 'p1'
    )
    engine, _trait, calling_cards, normal_cards, opposing = (
        _st4_ps1_review_fixture(
            definition, card_snapshot, owner,
            calling_lumen=1 if actual_event_owner == owner else 0,
            calling_side=0, numbered_negated=numbered_negated,
            normal_side=0 if no_candidate else normal_side,
        )
    )
    engine.state['players'][owner]['fp'] = starting_fp
    event_card = calling_cards[0] if calling_cards else None
    if actual_event_owner != owner:
        event_card = _card(
            'ST4-SS1', actual_event_owner,
            f'{actual_event_owner}-foreign-calling',
        )
        event_card.update({
            'name': '상대 예고장', 'type': '특수',
            'token_key': 'calling_card', 'face_up': True,
        })
        engine._zone(actual_event_owner, 'lumen').append(event_card)
        engine.ruleset.setdefault('cards', {})[event_card['code']] = {
            **copy.deepcopy(event_card),
            'effect_definition': {
                'schema_version': 1, 'reviewed': True, 'no_effect': True,
                'source_refs': {'rulebook_pages': [], 'qna_ids': []},
                'abilities': [],
            },
        }
    if not calling:
        event_card = _card(
            'REVIEW-NOTICE-NON-CALLING', actual_event_owner,
            f'{actual_event_owner}-non-calling',
        )
        event_card.update({'type': '특수', 'face_up': True})
        engine._zone(actual_event_owner, 'lumen').append(event_card)
        engine.ruleset.setdefault('cards', {})[event_card['code']] = {
            **copy.deepcopy(event_card),
            'effect_definition': {
                'schema_version': 1, 'reviewed': True, 'no_effect': True,
                'source_refs': {'rulebook_pages': [], 'qna_ids': []},
                'abilities': [],
            },
        }
    if protect_index is not None and normal_cards:
        protected = normal_cards[min(protect_index, len(normal_cards) - 1)]
        engine.ruleset['cards'][protected['code']]['effect_definition'] = {
            'schema_version': 1, 'reviewed': True, 'no_effect': False,
            'source_refs': {'rulebook_pages': [], 'qna_ids': []},
            'abilities': [], 'effect_immunity': {'scope': 'other_cards'},
        }
    if invalid_list_move:
        engine.move_card(
            event_card['instance_id'], 'list', reason='review-invalid-special',
            effect_controller=(
                'p2' if actual_event_owner == 'p1' else 'p1'
            ),
            effect_source=opposing['instance_id'],
        )
    else:
        engine.break_card(
            event_card['instance_id'], reason='review-calling-break',
            effect_controller=(
                'p2' if actual_event_owner == 'p1' else 'p1'
            ),
            effect_source=opposing['instance_id'],
        )
    decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    option_ids = [str(item.get('id')) for item in decision.get('options') or []]
    selected_id = None
    if decision:
        selected_id = option_ids[min(choose_index, len(option_ids) - 1)]
        if protect_after_choice:
            selected = engine._find_card(selected_id)
            engine.ruleset['cards'][selected['code']]['effect_definition'] = {
                'schema_version': 1, 'reviewed': True, 'no_effect': False,
                'source_refs': {'rulebook_pages': [], 'qna_ids': []},
                'abilities': [], 'effect_immunity': {'scope': 'other_cards'},
            }
        engine._submit_decision(owner, decision['id'], [selected_id])
    selected_zone = (
        engine._find_location(selected_id)[1] if selected_id else None
    )
    return {
        'fp': engine.state['players'][owner]['fp'],
        'event_zone': engine._find_location(event_card['instance_id'])[1],
        'decision_kind': decision.get('kind'),
        'decision_owner': decision.get('owner'),
        'option_ids': option_ids, 'selected_id': selected_id,
        'selected_zone': selected_zone,
        'resolution_count': _st4_ps1_resolved_count(
            engine, 'st4-ps1-n3-calling-card-broken',
        ),
        'replenishment_count': sum(
            event.get('type') == 'decision_requested'
            and (event.get('payload') or {}).get('kind') == 'break_replenish'
            for event in engine.events
        ),
        'choice_skipped': any(
            event.get('type') == 'effect_choice_skipped'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_st4_ps1_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'ST4-PS1':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    deck_rule = by_id.get('st4-ps1-deck-rule')
    placement = by_id.get('st4-ps1-n1-place')
    zone_limit = by_id.get('st4-ps1-n1-limit')
    state_grant = by_id.get('st4-ps1-n2-advance-notice')
    break_effect = by_id.get('st4-ps1-n3-calling-card-broken')
    qna_ids = [97, 98, 282, 376, 383, 484, 537, 695]
    expected_deck_rules = {
        'supplements': [{
            'where': {'token_key': 'calling_card'},
            'max_count': 3, 'same_name_limit': 3,
            'allow_foreign_mark': True, 'allow_non_technique': True,
            'allow_base_copies': True,
        }],
        'main_size': {
            'min': 20, 'max': 23, 'base_excludes_supplements': True,
        },
    }
    expected_zone_limits = [{
        'zone': 'lumen', 'max': 1,
        'where': {'token_key': 'calling_card'},
    }]
    calling_condition = {
        'op': 'zone_count', 'player': {'controller': True},
        'zone': 'lumen', 'min': 1,
        'where': {'token_key': 'calling_card'},
    }
    valid = bool(
        extra_root == {
            'deck_rules', 'state_grants', 'trait_state_keys', 'zone_limits',
        }
        and definition.get('deck_rules') == expected_deck_rules
        and definition.get('zone_limits') == expected_zone_limits
        and definition.get('trait_state_keys') == ['advance_notice']
        and definition.get('state_grants') == [{
            'states': ['advance_notice'],
            'active_zones': ['passive'], 'player': 'controller',
            'numbered_effect': True, 'condition': calling_condition,
        }]
        and len(abilities) == 5
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and deck_rule and deck_rule.get('kind') == 'function'
        and deck_rule.get('mode') == 'continuous'
        and deck_rule.get('active_zones') == ['passive']
        and deck_rule.get('effects') == [{
            'op': 'static_rule', 'rules': ['deck_rules'],
        }]
        and placement and placement.get('kind') == 'effect'
        and placement.get('mode') == 'mandatory'
        and placement.get('active_zones') == ['passive']
        and placement.get('trigger') == {'event': 'phase_start'}
        and placement.get('recheck_condition') is True
        and placement.get('condition') == {
            'op': 'all', 'conditions': [
                {'op': 'phase_is', 'phase': 'lumen'},
                {
                    'op': 'zone_count', 'player': {'controller': True},
                    'zone': 'hand', 'max': 4,
                },
                {
                    'op': 'zone_count', 'player': {'controller': True},
                    'zone': 'lumen', 'max': 0,
                    'where': {'token_key': 'calling_card'},
                },
            ],
        }
        and len(placement.get('effects') or []) == 1
        and (placement.get('effects') or [{}])[0].get('op')
        == 'request_choice'
        and ((placement.get('effects') or [{}])[0].get('selector') or {}).get(
            'as_operation'
        ) == 'move_card'
        and ((placement.get('effects') or [{}])[0].get('selector') or {}).get(
            'to_zone'
        ) == 'lumen'
        and (((placement.get('effects') or [{}])[0].get('selector') or {})
             .get('where') or {}).get('instance_id_not') == {
                 'op': 'memory_value',
                 'player': {'controller': True},
                 'key': 'st4_ps1_last_calling_card',
             }
        and any(
            node.get('op') == 'set_memory'
            and node.get('key') == 'st4_ps1_last_calling_card'
            for node in _effect_nodes(placement.get('effects') or [])
        )
        and any(
            node.get('op') == 'reveal'
            for node in _effect_nodes(placement.get('effects') or [])
        )
        and zone_limit and zone_limit.get('kind') == 'effect'
        and zone_limit.get('mode') == 'continuous'
        and zone_limit.get('active_zones') == ['passive']
        and zone_limit.get('effects') == [{
            'op': 'static_rule', 'rules': ['zone_limits'],
        }]
        and state_grant and state_grant.get('kind') == 'effect'
        and state_grant.get('mode') == 'continuous'
        and state_grant.get('active_zones') == ['passive']
        and state_grant.get('condition') == calling_condition
        and state_grant.get('effects') == [{
            'op': 'static_rule', 'rules': ['state_grants'],
        }]
        and break_effect and break_effect.get('kind') == 'effect'
        and break_effect.get('mode') == 'mandatory'
        and break_effect.get('active_zones') == ['passive']
        and break_effect.get('trigger') == {'event': 'card_broken'}
        and [node.get('op') for node in break_effect.get('effects') or []]
        == ['change_fp', 'request_choice']
        and (break_effect.get('effects') or [{}])[0] == {
            'op': 'change_fp', 'player': {'controller': True}, 'amount': -2,
        }
        and (((break_effect.get('effects') or [{}, {}])[1]
             .get('selector') or {}).get('where') == {'is_technique': True})
        and (((break_effect.get('effects') or [{}, {}])[1]
             .get('selector') or {}).get('as_operation') == 'break_card')
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'st4-ps1', False,
                reason=(
                    '예고의 추가 편성, 직전 예고장 기억, 루멘 1장 제한, '
                    '지속 상태 또는 브레이크 강제 선택 정의가 일치하지 않습니다.'
                ),
            )],
            'ST4-PS1 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    supplement = expected_deck_rules['supplements']
    deck_scenarios = []
    for name, total, matching, character_total, expected in (
        ('owner-p1-base-twenty-plus-three-supplements', 23, 3, 13, {
            'allocated': [3], 'base_size': 20, 'base_character': 10,
        }),
        ('qna-484-two-base-plus-three-extra-calling-cards', 23, 5, 15, {
            'allocated': [3], 'base_size': 20, 'base_character': 12,
        }),
        ('qna-537-extra-cards-do-not-satisfy-character-minimum', 23, 3, 10, {
            'allocated': [3], 'base_size': 20, 'base_character': 7,
        }),
        ('twenty-three-cards-need-three-eligible-supplements', 23, 2, 12, {
            'allocated': [2], 'base_size': 21, 'base_character': 10,
        }),
    ):
        allocated = allocate_supplement_counts(
            total, 20, supplement, [matching],
        )
        actual = {
            'allocated': allocated,
            'base_size': total - sum(allocated),
            'base_character': character_total - min(
                allocated[0], matching,
            ),
        }
        deck_scenarios.append({
            'name': name, 'passed': actual == expected,
            'deterministic': True, 'expected': expected, **actual,
        })

    placement_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-selects-second-and-places-face-up', 'p1', {
            'choose_index': 1,
        }, {'decision_owner': 'p1', 'resolution_count': 1,
            'has_notice': True, 'pending': False}),
        ('owner-p2-selects-first-and-places-face-up', 'p2', {}, {
            'decision_owner': 'p2', 'resolution_count': 1,
            'has_notice': True, 'pending': False}),
        ('qna-98-previous-calling-card-is-excluded', 'p1', {
            'previous_index': 0,
        }, {'resolution_count': 1, 'pending': False}),
        ('only-previous-card-remains-skips-safely', 'p2', {
            'calling_side': 1, 'previous_index': 0,
        }, {'resolution_count': 1, 'choice_skipped': True,
            'has_notice': False, 'pending': False}),
        ('hand-five-does-not-trigger', 'p1', {'hand_count': 5}, {
            'resolution_count': 0, 'has_notice': False}),
        ('existing-calling-card-blocks-placement', 'p2', {
            'calling_lumen': 1, 'calling_side': 1,
        }, {'resolution_count': 0, 'has_notice': True}),
        ('wrong-phase-does-not-trigger', 'p1', {'phase': 'ready'}, {
            'resolution_count': 0, 'has_notice': False}),
        ('numbered-negation-suppresses-placement', 'p2', {
            'numbered_negated': True,
        }, {'resolution_count': 0, 'has_notice': False}),
        ('late-move-immunity-keeps-card-and-memory-empty', 'p1', {
            'protect_after_choice': True,
        }, {'resolution_count': 1, 'has_notice': False,
            'remembered': None, 'pending': False}),
    ):
        first = _run_st4_ps1_place_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_ps1_place_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        extra_ok = True
        if name.startswith('owner-'):
            extra_ok = bool(
                first['selected_id'] in first['lumen_ids']
                and first['lumen_face_up'] == [True]
                and first['remembered'] == first['selected_id']
            )
        elif name.startswith('qna-98'):
            remembered_id = f'{owner}-calling-1'
            extra_ok = bool(
                remembered_id not in first['option_ids']
                and first['selected_id'] != remembered_id
                and first['remembered'] == first['selected_id']
            )
        elif name.startswith('late-move'):
            extra_ok = first['selected_id'] not in first['lumen_ids']
        placement_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and extra_ok
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    limit_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-second-calling-card-is-blocked', 'p1', {}, {
            'moved': False, 'after_zone': 'side', 'calling_count': 1,
        }),
        ('owner-p2-second-calling-card-is-blocked', 'p2', {}, {
            'moved': False, 'after_zone': 'side', 'calling_count': 1,
        }),
        ('unrelated-card-can-enter-lumen', 'p1', {'unrelated': True}, {
            'moved': True, 'after_zone': 'lumen', 'calling_count': 1,
        }),
        ('after-existing-card-leaves-new-calling-can-enter', 'p2', {
            'remove_existing': True,
        }, {'moved': True, 'after_zone': 'lumen', 'calling_count': 1}),
        ('numbered-negation-removes-the-zone-limit', 'p1', {
            'numbered_negated': True,
        }, {'moved': True, 'after_zone': 'lumen', 'calling_count': 2}),
    ):
        first = _run_st4_ps1_limit_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_ps1_limit_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        limit_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    state_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-calling-in-lumen-grants-state', 'p1', {}, {
            'before': True, 'after': True,
        }),
        ('owner-p2-calling-in-lumen-grants-state', 'p2', {}, {
            'before': True, 'after': True,
        }),
        ('qna-282-external-placement-also-grants-state', 'p1', {}, {
            'before': True, 'after': True,
        }),
        ('no-calling-in-lumen-does-not-grant-state', 'p2', {
            'calling_lumen': 0,
        }, {'before': False, 'after': False}),
        ('state-disappears-when-calling-card-leaves', 'p1', {
            'remove_calling': True,
        }, {'before': True, 'after': False}),
        ('qna-383-trait-negation-keeps-card-but-removes-state', 'p2', {
            'global_trait_negation': True,
        }, {'before': False, 'after': False}),
        ('numbered-negation-removes-state-grant', 'p1', {
            'numbered_negated': True,
        }, {'before': False, 'after': False}),
    ):
        first = _run_st4_ps1_state_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_ps1_state_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        state_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    break_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-selects-second-side-technique', 'p1', {
            'choose_index': 1,
        }, {'fp': 3, 'event_zone': 'break', 'decision_owner': 'p1',
            'selected_zone': 'break', 'resolution_count': 1,
            'replenishment_count': 0, 'pending': False}),
        ('owner-p2-selects-first-side-technique', 'p2', {}, {
            'fp': 3, 'event_zone': 'break', 'decision_owner': 'p2',
            'selected_zone': 'break', 'resolution_count': 1,
            'replenishment_count': 0, 'pending': False}),
        ('qna-376-invalid-special-list-move-triggers-break-effect', 'p1', {
            'invalid_list_move': True,
        }, {'fp': 3, 'event_zone': 'break', 'resolution_count': 1,
            'selected_zone': 'break', 'replenishment_count': 0}),
        ('non-calling-card-break-does-not-trigger', 'p2', {
            'calling': False,
        }, {'fp': 5, 'resolution_count': 0}),
        ('opponents-calling-break-does-not-trigger-own-trait', 'p1', {
            'event_owner': 'opponent',
        }, {'fp': 5, 'resolution_count': 0}),
        ('no-side-technique-still-loses-two-fp', 'p2', {
            'no_candidate': True,
        }, {'fp': 3, 'resolution_count': 1,
            'choice_skipped': True, 'pending': False}),
        ('protected-side-technique-is-excluded', 'p1', {
            'protect_index': 0, 'choose_index': 0,
        }, {'fp': 3, 'resolution_count': 1,
            'selected_zone': 'break', 'pending': False}),
        ('late-break-immunity-keeps-selected-card-in-side', 'p2', {
            'protect_after_choice': True,
        }, {'fp': 3, 'resolution_count': 1,
            'selected_zone': 'side', 'replenishment_count': 0,
            'pending': False}),
        ('numbered-negation-suppresses-break-penalty', 'p1', {
            'numbered_negated': True,
        }, {'fp': 5, 'resolution_count': 0}),
        ('fp-loss-can-produce-negative-fp', 'p2', {'starting_fp': 1}, {
            'fp': -1, 'resolution_count': 1,
            'selected_zone': 'break', 'pending': False}),
    ):
        first = _run_st4_ps1_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_st4_ps1_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        extra_ok = True
        if name.startswith('protected-side'):
            extra_ok = f'{owner}-notice-side-1' not in first['option_ids']
        break_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and extra_ok
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            deck_rule['id'], all(item['passed'] for item in deck_scenarios),
            deck_scenarios,
        ),
        AbilityReview(
            placement['id'],
            all(item['passed'] for item in placement_scenarios),
            placement_scenarios,
        ),
        AbilityReview(
            zone_limit['id'], all(item['passed'] for item in limit_scenarios),
            limit_scenarios,
        ),
        AbilityReview(
            state_grant['id'], all(item['passed'] for item in state_scenarios),
            state_scenarios,
        ),
        AbilityReview(
            break_effect['id'], all(item['passed'] for item in break_scenarios),
            break_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else 'ST4-PS1 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def review_simple_definition(definition, *, card_has_text=False):
    """Run three scenarios per simple ability; complex definitions stay pending."""
    issues = validate_effect_definition(definition, card_has_text=card_has_text)
    if issues:
        return DefinitionReview(False, False, reason='DSL 스키마 오류가 있습니다.')
    extra_root = set(definition) - SIMPLE_ROOT_FIELDS
    abilities = definition.get('abilities') or []
    if not abilities:
        if definition.get('no_effect') is True:
            empty = AbilityReview('no-effect', True, [
                {'name': 'owner-p1', 'passed': True},
                {'name': 'owner-p2', 'passed': True},
                {'name': 'no-command', 'passed': True},
            ])
            return DefinitionReview(True, True, [empty])
        return DefinitionReview(False, False, reason='능력 또는 효과 없음 선언이 필요합니다.')
    reviewed = [_review_ability(definition, ability) for ability in abilities]
    abilities_are_simple = all(not item.reason or item.scenarios for item in reviewed)
    if extra_root:
        return DefinitionReview(
            False, False, reviewed,
            reason=f'최상위 규칙({", ".join(sorted(extra_root))})은 카드별 검토가 필요합니다.',
        )
    simple = abilities_are_simple
    return DefinitionReview(
        bool(simple and all(item.passed for item in reviewed)), simple, reviewed,
        '' if simple else '하나 이상의 복합 효과가 카드별 검토 대상입니다.',
    )


def _lmi_at_011_source(card_snapshot, owner, source_zone='lumen', *, negated=False):
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-exceed-protocol', 'owner': owner,
        'kind': 'card', 'type': '특수', 'frame': None, 'damage': None,
        'pos': None, 'body': '', 'special': None, 'hit': None,
        'guard': None, 'counter': None, 'character_id': 2,
        'character_key': 'nya', 'face_up': source_zone != 'side',
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _lmi_at_011_engine(
    definition, card_snapshot, owner, *, source_zone='lumen', ability_ids=None,
    extras=None, phase='battle', negated=False, extra_definitions=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_011_source(
        card_snapshot, owner, source_zone, negated=negated,
    )
    opposing = _card(
        'REVIEW-EXCEED-OPPONENT', other, f'{other}-exceed-opponent',
    )
    isolated = copy.deepcopy(definition)
    if ability_ids is not None:
        isolated['abilities'] = [
            ability for ability in isolated.get('abilities') or []
            if ability.get('id') in set(ability_ids)
        ]
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['phase'] = phase
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    for zone, card in extras or []:
        state['players'][card['owner']]['zones'][zone].append(
            copy.deepcopy(card),
        )
        cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(
                (extra_definitions or {}).get(card['code']) or no_effect
            ),
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'exceed:{owner}:{source_zone}:{phase}:{negated}:'
            f'{sorted(ability_ids or [])}:'
            f'{[(zone, card.get("instance_id")) for zone, card in extras or []]}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, source, opposing


def _run_lmi_at_011_immunity_scenario(
    definition, card_snapshot, owner, *, mode,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source_zone = 'side' if mode in {'owner_other_effect', 'own_effect'} else 'lumen'
    ally = _card(
        'REVIEW-EXCEED-ALLY', owner, f'{owner}-exceed-ally',
    )
    enemy = _card(
        'REVIEW-EXCEED-ENEMY', other, f'{other}-exceed-enemy',
    )
    engine, source, _opposing = _lmi_at_011_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-011-function'],
        extras=[('hand', ally), ('hand', enemy)],
    )
    if mode == 'owner_other_effect':
        moved = engine.move_card(
            source['instance_id'], 'lumen', reason='review-other-effect',
            effect_controller=owner, effect_source=ally['instance_id'],
        )
    elif mode == 'opponent_other_effect':
        moved = engine.move_card(
            source['instance_id'], 'list', reason='review-help-catcher',
            effect_controller=other, effect_source=enemy['instance_id'],
        )
    elif mode == 'own_effect':
        moved = engine.move_card(
            source['instance_id'], 'lumen', reason='review-own-effect',
            effect_controller=owner, effect_source=source['instance_id'],
        )
    else:
        moved = engine.move_card(
            source['instance_id'], 'break', reason='review-core-move',
        )
    return {
        'zone': engine._find_location(source['instance_id'])[1],
        'moved': moved is not None,
        'ignored_count': sum(
            event.get('type') == 'card_effect_ignored'
            and (event.get('payload') or {}).get('card_instance_id')
            == source['instance_id']
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_011_placement_scenario(
    definition, card_snapshot, owner, *, state='over_limit',
    state_player=None, source_zone='side', accept=True, repeat=False,
    negated=False, move_before_battle_end=False,
):
    state_player = state_player or owner
    engine, source, _opposing = _lmi_at_011_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-011-n1'], negated=negated,
    )
    engine.set_passive(state_player, state, value=True)
    scheduled_after_first = len(engine.engine_state.get('scheduled') or [])
    if repeat:
        engine.set_passive(state_player, state, value=False)
        engine.set_passive(state_player, state, value=True)
    scheduled_after_repeat = len(engine.engine_state.get('scheduled') or [])
    if move_before_battle_end:
        engine.move_card(source['instance_id'], 'break', reason='review-core-left')
    engine._fire('battle_end', {'controller': owner})
    decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    if decision:
        selected = [source['instance_id']] if accept else []
        engine._submit_decision(owner, decision['id'], selected)
        engine._continue()
    return {
        'scheduled_after_first': scheduled_after_first,
        'scheduled_after_repeat': scheduled_after_repeat,
        'decision_kind': decision.get('kind'),
        'decision_range': (decision.get('min'), decision.get('max')),
        'zone': engine._find_location(source['instance_id'])[1],
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-011-n1'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_011_rule_scenario(
    definition, card_snapshot, owner, *, mode, source_zone='lumen',
    negated=False, cannon_other_count=0,
):
    other = 'p2' if owner == 'p1' else 'p1'
    starter = _card(
        'REVIEW-EXCEED-STARTER', owner, f'{owner}-exceed-starter',
    )
    starter.update({'frame': 4, 'damage': 500, 'hit': '콤보'})
    nya_a = _card('REVIEW-EXCEED-NYA-A', owner, f'{owner}-exceed-nya-a')
    nya_a.update({'character_key': 'nya', 'frame': 6, 'damage': 500})
    nya_b = _card('REVIEW-EXCEED-NYA-B', owner, f'{owner}-exceed-nya-b')
    nya_b.update({'character_key': 'nya', 'frame': 7, 'damage': 500})
    neutral = _card(
        'REVIEW-EXCEED-NEUTRAL', owner, f'{owner}-exceed-neutral',
    )
    neutral['character_key'] = 'neutral'
    extras = [('battle', starter), ('lumen', nya_a), ('lumen', nya_b)]
    if mode in {'non_nya_own_break', 'combo'}:
        extras.append(('lumen', neutral))
    else:
        extras.append(('hand', neutral))
    cannon = None
    extra_definitions = {}
    if mode == 'qna_88':
        cannon = _card('AWL-AT-015', owner, f'{owner}-exceed-cannon')
        cannon.update({
            'name': '라이! 레피! 캐논!', 'character_key': 'nya',
            'frame': 10, 'damage': 700,
        })
        extras = [('battle', starter), ('lumen', cannon)]
        for index in range(cannon_other_count):
            filler = _card(
                f'REVIEW-EXCEED-FILLER-{index}', owner,
                f'{owner}-exceed-filler-{index}',
            )
            filler['character_key'] = 'neutral'
            extras.append(('lumen', filler))
        extra_definitions[cannon['code']] = {
            **_st1_001_no_effect_definition(),
            'no_effect': False,
            'play_condition': {
                'op': 'zone_count', 'player': {'controller': True},
                'zone': 'lumen', 'where': {'type_in': ['공격', '수비']},
                'min': 6, 'exclude_source': True,
            },
        }
    engine, source, opposing = _lmi_at_011_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-011-lumen-rules'], extras=extras,
        negated=negated, extra_definitions=extra_definitions,
    )
    engine._refresh_continuous_rules()
    result = {
        'threshold': condition_matches(
            {
                'op': 'zone_count', 'player': owner, 'zone': 'lumen',
                'min': 0,
            },
            engine.state, {'controller': owner},
        ),
        'state_rule_value': None, 'target_zone': None,
        'prevented_count': 0, 'nya_legal': False,
        'neutral_legal': False, 'two_lumen_pair_legal': False,
        'cannon_legal': False, 'used_zone': None,
        'pending': False,
    }
    from .effects import resolve_value
    result['state_rule_value'] = resolve_value({
        'op': 'state_rule_value', 'player': {'controller': True},
        'state': 'over_limit', 'field': 'release_lumen_count', 'default': 8,
    }, engine.state, {'controller': owner})
    target = nya_a
    if mode == 'own_effect_break':
        engine.break_card(
            target['instance_id'], reason='review-own-effect',
            effect_controller=owner, effect_source=neutral['instance_id'],
        )
    elif mode == 'own_direct_break':
        engine.break_card(
            target['instance_id'], reason='review-own-direct',
            direct_controller=owner,
        )
    elif mode == 'opponent_effect_break':
        engine.break_card(
            target['instance_id'], reason='review-opponent-effect',
            effect_controller=other, effect_source=opposing['instance_id'],
        )
    elif mode == 'core_result_move':
        engine.move_card(
            target['instance_id'], 'break', reason='defense_over',
        )
    elif mode == 'non_nya_own_break':
        target = neutral
        engine.break_card(
            target['instance_id'], reason='review-own-effect',
            effect_controller=owner, effect_source=source['instance_id'],
        )
    elif mode in {'combo', 'source_inactive', 'qna_88'}:
        engine.grant_combo(owner, source=starter['instance_id'])
        actions = engine.legal_actions(owner)
        result['nya_legal'] = any(
            action.get('type') == 'play_combo_card'
            and (action.get('payload') or {}).get('card_instance_id')
            == nya_a['instance_id']
            for action in actions
        )
        result['neutral_legal'] = any(
            action.get('type') in {'play_combo_card', 'play_combo_pair', 'play_combo_sequence'}
            and neutral['instance_id'] in (
                (action.get('payload') or {}).get('card_instance_ids')
                or [(action.get('payload') or {}).get('card_instance_id')]
            )
            for action in actions
        )
        result['two_lumen_pair_legal'] = any(
            action.get('type') in {'play_combo_pair', 'play_combo_sequence'}
            and {nya_a['instance_id'], nya_b['instance_id']}.issubset(set(
                (action.get('payload') or {}).get('card_instance_ids') or []
            ))
            for action in actions
        )
        if cannon:
            result['cannon_legal'] = any(
                action.get('type') == 'play_combo_card'
                and (action.get('payload') or {}).get('card_instance_id')
                == cannon['instance_id']
                for action in actions
            )
        elif mode == 'combo' and result['nya_legal']:
            action = next(
                action for action in actions
                if action.get('type') == 'play_combo_card'
                and (action.get('payload') or {}).get('card_instance_id')
                == nya_a['instance_id']
            )
            engine.submit_action(
                owner, action['action_id'], action.get('payload') or {},
                command_id=f'exceed-combo:{owner}',
            )
            result['used_zone'] = engine._find_location(nya_a['instance_id'])[1]
    if mode in {
        'own_effect_break', 'own_direct_break', 'opponent_effect_break',
        'core_result_move', 'non_nya_own_break',
    }:
        result['target_zone'] = engine._find_location(target['instance_id'])[1]
        result['prevented_count'] = sum(
            event.get('type') == 'card_break_prevented'
            for event in engine.events
        )
    result['pending'] = bool(engine.engine_state.get('pending_decision'))
    return result


def _run_lmi_at_011_get_scenario(
    definition, card_snapshot, owner, *, candidate_count=2, accept=True,
    choose_index=0, phase='get', source_zone='lumen', skipped=False,
    negated=False, protected_index=None, protect_after_choice=False,
    include_standard_get=False,
):
    candidates = []
    extras = []
    definitions = {}
    for index in range(candidate_count):
        card = _card(
            f'REVIEW-EXCEED-GET-{index}', owner,
            f'{owner}-exceed-get-{index}',
        )
        card['character_key'] = 'nya'
        candidates.append(card)
        extras.append(('lumen', card))
        if protected_index == index:
            definitions[card['code']] = {
                **_st1_001_no_effect_definition(), 'no_effect': False,
                'effect_immunity': {'scope': 'other_cards'},
            }
    wrong = _card(
        'REVIEW-EXCEED-GET-WRONG', owner, f'{owner}-exceed-get-wrong',
    )
    wrong['character_key'] = 'neutral'
    special = _card(
        'REVIEW-EXCEED-GET-SPECIAL', owner,
        f'{owner}-exceed-get-special',
    )
    special.update({'character_key': 'nya', 'type': '특수'})
    extras.extend([('lumen', wrong), ('lumen', special)])
    standard = _card(
        'REVIEW-EXCEED-STANDARD-GET', owner,
        f'{owner}-exceed-standard-get',
    )
    if include_standard_get:
        extras.append(('hand', standard))
    engine, source, _opposing = _lmi_at_011_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-011-get'], extras=extras, phase=phase,
        negated=negated, extra_definitions=definitions,
    )
    if skipped:
        engine.engine_state['get_skipped_players'] = [owner]
    if phase == 'get':
        engine._advance_phase('recovery')
    else:
        engine._fire('phase_end', {'phase': phase})
    decisions = []
    decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    if decision:
        decisions.append({
            'kind': decision.get('kind'),
            'option_ids': [
                str(option.get('id')) for option in decision.get('options') or []
            ],
        })
    if decision.get('kind') == 'optional_effect':
        engine._submit_decision(
            owner, decision['id'], ['accept'] if accept else ['decline'],
        )
        engine._continue()
        decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
        if decision:
            decisions.append({
                'kind': decision.get('kind'),
                'option_ids': [
                    str(option.get('id'))
                    for option in decision.get('options') or []
                ],
            })
    selected_id = None
    if decision.get('kind') == 'effect_choice':
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        if option_ids:
            selected_id = option_ids[min(choose_index, len(option_ids) - 1)]
            if protect_after_choice:
                selected = engine._find_card(selected_id)
                engine.ruleset['cards'][selected['code']]['effect_definition'] = {
                    **_st1_001_no_effect_definition(), 'no_effect': False,
                    'effect_immunity': {'scope': 'other_cards'},
                }
            engine._submit_decision(owner, decision['id'], [selected_id])
            engine._continue()
    return {
        'decisions': decisions, 'selected_id': selected_id,
        'candidate_ids': [card['instance_id'] for card in candidates],
        'zones': {
            card['instance_id']: engine._find_location(card['instance_id'])[1]
            for card in candidates
        },
        'wrong_offered': any(
            wrong['instance_id'] in item['option_ids'] for item in decisions
        ),
        'special_offered': any(
            special['instance_id'] in item['option_ids'] for item in decisions
        ),
        'standard_in_hand': bool(engine._find_card(
            standard['instance_id'], owner=owner, zone='hand',
        )) if include_standard_get else False,
        'phase': engine.state.get('phase'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_011_state_lost_scenario(
    definition, card_snapshot, owner, *, state='over_limit',
    state_player=None, source_zone='lumen', negated=False,
):
    state_player = state_player or owner
    engine, source, _opposing = _lmi_at_011_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-011-over-limit-lost'], negated=negated,
    )
    engine.state['players'][state_player]['passive_state'][state] = {
        'value': True, 'label': state,
    }
    before = engine.state['players'][owner]['hp']
    engine.set_passive(state_player, state, value=False)
    return {
        'damage': before - engine.state['players'][owner]['hp'],
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved_count': sum(
            event.get('type') == 'effect_resolved'
            and (event.get('payload') or {}).get('ability_id')
            == 'lmi-at-011-over-limit-lost'
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_011_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-011':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('lmi-at-011-function')
    placement = by_id.get('lmi-at-011-n1')
    rules = by_id.get('lmi-at-011-lumen-rules')
    get_effect = by_id.get('lmi-at-011-get')
    lost = by_id.get('lmi-at-011-over-limit-lost')
    qna_ids = [88, 414, 417, 494, 530, 597, 603, 649, 663]
    placement_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['side'], 'min': 0, 'max': 1,
        'as_operation': 'move_card', 'to_zone': 'lumen',
        'where': {
            'instance_id': {'path': 'context.source_card_instance_id'},
        },
    }
    get_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['lumen'], 'min': 1, 'max': 1,
        'where': {'character_key': 'nya'},
        'as_operation': 'move_card', 'to_zone': 'hand',
    }
    owner_state_condition = {
        'op': 'all', 'conditions': [
            {
                'op': 'equals', 'left': 'context.state',
                'right': 'over_limit',
            },
            {
                'op': 'equals', 'left': 'context.player',
                'right': {'controller': True},
            },
        ],
    }
    expected_rules = [
        {
            'op': 'modify_state_rule', 'player': {'controller': True},
            'state': 'over_limit', 'field': 'release_lumen_count',
            'value': 11, 'mode': 'minimum', 'duration': 'continuous',
        },
        {
            'op': 'prevent', 'kind': 'break',
            'player': {'controller': True},
            'where': {'character_key': 'nya'},
            'target_zones': ['lumen'], 'duration': 'continuous',
            'controller_only': True,
        },
        {
            'op': 'modify_combo', 'player': {'controller': True},
            'allow_zones': ['lumen'], 'where': {'character_key': 'nya'},
            'break_after_use': True,
            'usage_key': 'lmi-at-011-lumen-combo',
            'usage_scope': 'battle', 'max_uses': 1,
            'duration': 'continuous',
        },
    ]
    valid = bool(
        extra_root == {'effect_immunity'} and len(abilities) == 5
        and definition.get('effect_immunity') == {'scope': 'other_cards'}
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and (definition.get('source_refs') or {}).get('detail_text') is True
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids and (ability.get('source_refs') or {}).get('detail_text') is True
            for ability in abilities
        )
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['effect_immunity'],
        }]
        and not function.get('active_zones') and not function.get('trigger')
        and placement and placement.get('kind') == 'effect'
        and placement.get('mode') == 'mandatory'
        and placement.get('trigger') == {'event': 'state_gained'}
        and placement.get('active_zones') == ['side']
        and placement.get('condition') == owner_state_condition
        and placement.get('limit') == {
            'scope': 'game', 'max': 1,
            'key': 'lmi-at-011-first-over-limit',
        }
        and placement.get('effects') == [{
            'op': 'schedule', 'when': {'event': 'battle_end'},
            'duration': 'turn', 'effect': {
                'op': 'request_choice', 'player': {'controller': True},
                'prompt': '프로토콜: 익시드를 루멘 존에 배치할 수 있습니다.',
                'selector': placement_selector,
                'selection_key': 'lmi_at_011_place_from_side',
                'default': [], 'optional': True,
                'then': [{
                    'op': 'move_card',
                    'selection_key': 'lmi_at_011_place_from_side',
                    'to_zone': 'lumen',
                }],
            },
        }]
        and rules and rules.get('kind') == 'effect'
        and rules.get('mode') == 'continuous'
        and rules.get('timing') == 'function'
        and rules.get('active_zones') == ['lumen']
        and rules.get('effects') == expected_rules
        and get_effect and get_effect.get('kind') == 'effect'
        and get_effect.get('mode') == 'optional'
        and get_effect.get('trigger') == {'event': 'phase_end'}
        and get_effect.get('active_zones') == ['lumen']
        and get_effect.get('availability_selector') == get_selector
        and get_effect.get('condition') == {
            'op': 'all', 'conditions': [
                {'op': 'phase_is', 'phase': 'get'},
                {
                    'op': 'zone_count', 'player': {'controller': True},
                    'zone': 'lumen', 'min': 1,
                    'where': {'character_key': 'nya'},
                },
            ],
        }
        and get_effect.get('effects') == [{
            'op': 'request_choice', 'player': {'controller': True},
            'prompt': '획득할 냐 기술을 선택하세요.',
            'selector': get_selector,
            'selection_key': 'lmi_at_011_get_card', 'default': [],
            'then': [{
                'op': 'move_card', 'selection_key': 'lmi_at_011_get_card',
                'to_zone': 'hand',
            }],
        }]
        and lost and lost.get('kind') == 'effect'
        and lost.get('mode') == 'mandatory'
        and lost.get('trigger') == {'event': 'state_lost'}
        and lost.get('active_zones') == ['lumen']
        and lost.get('condition') == owner_state_condition
        and lost.get('effects') == [{
            'op': 'deal_damage', 'player': {'controller': True},
            'amount': 500,
        }]
        and str((card_snapshot or {}).get('name') or '') == '프로토콜: 익시드'
        and str((card_snapshot or {}).get('type') or '') == '특수'
        and (card_snapshot or {}).get('frame') is None
        and (card_snapshot or {}).get('damage') is None
        and (card_snapshot or {}).get('pos') is None
        and str((card_snapshot or {}).get('body') or '') == ''
        and (card_snapshot or {}).get('special') is None
        and (card_snapshot or {}).get('hit') is None
        and (card_snapshot or {}).get('guard') is None
        and (card_snapshot or {}).get('counter') is None
        and int((card_snapshot or {}).get('character_id') or 0) == 2
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-011', False,
                reason='프로토콜: 익시드의 면역·최초 배치·루멘 규칙·Get·해제 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-011 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    reviews = []
    immunity_specs = (
        ('side-owner-other-card-effect-is-ignored', 'p1', 'owner_other_effect', 'side', False, 1),
        ('qna-649-opponent-move-effect-is-ignored-in-lumen', 'p2', 'opponent_other_effect', 'lumen', False, 1),
        ('own-placement-effect-remains-applicable', 'p1', 'own_effect', 'lumen', True, 0),
        ('core-movement-is-not-another-technique-effect', 'p2', 'core', 'break', True, 0),
    )
    immunity_scenarios = []
    for name, owner, mode, zone, moved, ignored in immunity_specs:
        first = _run_lmi_at_011_immunity_scenario(
            definition, card_snapshot, owner, mode=mode,
        )
        second = _run_lmi_at_011_immunity_scenario(
            definition, card_snapshot, owner, mode=mode,
        )
        deterministic = _canonical(first) == _canonical(second)
        immunity_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['zone'] == zone
                and first['moved'] is moved
                and first['ignored_count'] == ignored and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        function['id'], all(item['passed'] for item in immunity_scenarios),
        immunity_scenarios,
        '' if all(item['passed'] for item in immunity_scenarios)
        else '전 영역 다른 기술 효과 면역 검증에 실패했습니다.',
    ))

    placement_specs = (
        ('owner-p1-first-over-limit-accepts-at-battle-end', 'p1', {}, 1, 1, 'effect_choice', 'lumen'),
        ('owner-p2-first-over-limit-may-decline', 'p2', {'accept': False}, 1, 1, 'effect_choice', 'side'),
        ('game-limit-keeps-only-first-over-limit-schedule', 'p1', {'repeat': True}, 1, 1, 'effect_choice', 'lumen'),
        ('wrong-state-does-not-schedule', 'p1', {'state': 'intimidation'}, 0, 0, None, 'side'),
        ('opponent-state-does-not-schedule', 'p2', {'state_player': 'p1'}, 0, 0, None, 'side'),
        ('source-outside-side-does-not-schedule', 'p1', {'source_zone': 'lumen'}, 0, 0, None, 'lumen'),
        ('numbered-negation-does-not-schedule', 'p1', {'negated': True}, 0, 0, None, 'side'),
        ('source-left-before-battle-end-has-no-stale-choice', 'p2', {'move_before_battle_end': True}, 1, 1, None, 'break'),
    )
    placement_scenarios = []
    for name, owner, kwargs, first_count, repeat_count, kind, zone in placement_specs:
        first = _run_lmi_at_011_placement_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_011_placement_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        placement_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and first['scheduled_after_first'] == first_count
                and first['scheduled_after_repeat'] == repeat_count
                and first['decision_kind'] == kind
                and first['zone'] == zone and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        placement['id'], all(item['passed'] for item in placement_scenarios),
        placement_scenarios,
        '' if all(item['passed'] for item in placement_scenarios)
        else '첫 오버 리미트 턴 배틀 종료 배치 검증에 실패했습니다.',
    ))

    rule_specs = (
        ('lumen-threshold-is-eleven', 'p1', {'mode': 'threshold'}, {'state_rule_value': 11}),
        ('source-outside-lumen-keeps-threshold-eight', 'p2', {'mode': 'source_inactive', 'source_zone': 'side'}, {'state_rule_value': 8, 'nya_legal': False}),
        ('numbered-negation-disables-all-lumen-rules', 'p1', {'mode': 'source_inactive', 'negated': True}, {'state_rule_value': 8, 'nya_legal': False}),
        ('qna-530-owner-effect-cannot-break-own-nya', 'p1', {'mode': 'own_effect_break'}, {'target_zone': 'lumen', 'prevented_count': 1}),
        ('owner-direct-choice-cannot-break-own-nya', 'p2', {'mode': 'own_direct_break'}, {'target_zone': 'lumen', 'prevented_count': 1}),
        ('opponent-effect-may-break-nonimmune-nya', 'p1', {'mode': 'opponent_effect_break'}, {'target_zone': 'break', 'prevented_count': 0}),
        ('qna-649-core-result-move-bypasses-break-attempt-lock', 'p2', {'mode': 'core_result_move'}, {'target_zone': 'break', 'prevented_count': 0}),
        ('own-effect-may-break-non-nya', 'p1', {'mode': 'non_nya_own_break'}, {'target_zone': 'break', 'prevented_count': 0}),
        ('lumen-nya-combo-is-used-once-and-breaks', 'p2', {'mode': 'combo'}, {'nya_legal': True, 'neutral_legal': False, 'two_lumen_pair_legal': False, 'used_zone': 'break'}),
        ('qna-88-cannon-plus-five-other-techniques-is-illegal', 'p1', {'mode': 'qna_88', 'cannon_other_count': 5}, {'cannon_legal': False}),
        ('qna-88-cannon-plus-six-other-techniques-is-legal', 'p2', {'mode': 'qna_88', 'cannon_other_count': 6}, {'cannon_legal': True}),
    )
    rule_scenarios = []
    for name, owner, kwargs, expected in rule_specs:
        first = _run_lmi_at_011_rule_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_011_rule_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        rule_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic
                and all(first.get(key) == value for key, value in expected.items())
                and not first['pending']
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })
    reviews.append(AbilityReview(
        rules['id'], all(item['passed'] for item in rule_scenarios),
        rule_scenarios,
        '' if all(item['passed'] for item in rule_scenarios)
        else '오버 리미트 11장·제어자 브레이크 제한·루멘 콤보 검증에 실패했습니다.',
    ))

    get_specs = (
        ('qna-414-after-standard-get-owner-selects-first-nya', 'p1', {'include_standard_get': True, 'choose_index': 0}, {'decision_kinds': ['optional_effect', 'effect_choice'], 'selected_zone': 'hand', 'standard_in_hand': True}),
        ('owner-p2-selects-second-of-multiple-nya', 'p2', {'candidate_count': 2, 'choose_index': 1}, {'decision_kinds': ['optional_effect', 'effect_choice'], 'selected_zone': 'hand'}),
        ('optional-get-may-be-declined', 'p1', {'accept': False}, {'decision_kinds': ['optional_effect'], 'selected_zone': None}),
        ('qna-417-603-skipped-get-has-no-protocol-trigger', 'p2', {'skipped': True}, {'decision_kinds': [], 'selected_zone': None}),
        ('wrong-phase-does-not-trigger-get', 'p1', {'phase': 'ready'}, {'decision_kinds': [], 'selected_zone': None}),
        ('source-outside-lumen-does-not-trigger-get', 'p2', {'source_zone': 'side'}, {'decision_kinds': [], 'selected_zone': None}),
        ('numbered-negation-does-not-trigger-get', 'p1', {'negated': True}, {'decision_kinds': [], 'selected_zone': None}),
        ('move-immune-candidate-is-not-offered', 'p2', {'protected_index': 0, 'candidate_count': 2}, {'decision_kinds': ['optional_effect', 'effect_choice'], 'selected_zone': 'hand'}),
        ('no-movable-normal-nya-skips-activation', 'p1', {'protected_index': 0, 'candidate_count': 1}, {'decision_kinds': [], 'selected_zone': None}),
        ('movement-protection-added-after-choice-is-rechecked', 'p2', {'candidate_count': 1, 'protect_after_choice': True}, {'decision_kinds': ['optional_effect', 'effect_choice'], 'selected_zone': 'lumen'}),
    )
    get_scenarios = []
    for name, owner, kwargs, expected in get_specs:
        first = _run_lmi_at_011_get_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_011_get_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        kinds = [item['kind'] for item in first['decisions']]
        selected_zone = (
            first['zones'].get(first['selected_id'])
            if first['selected_id'] else None
        )
        protected_not_offered = bool(
            kwargs.get('protected_index') is None
            or not first['decisions']
            or first['candidate_ids'][kwargs['protected_index']]
            not in first['decisions'][-1]['option_ids']
        )
        get_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and kinds == expected['decision_kinds']
                and selected_zone == expected['selected_zone']
                and (
                    'standard_in_hand' not in expected
                    or first['standard_in_hand'] is expected['standard_in_hand']
                )
                and protected_not_offered
                and not first['wrong_offered'] and not first['special_offered']
                and not first['pending']
            ),
            'deterministic': deterministic,
            'decision_kinds': kinds, 'selected_zone': selected_zone,
            'protected_not_offered': protected_not_offered,
            **first,
        })
    reviews.append(AbilityReview(
        get_effect['id'], all(item['passed'] for item in get_scenarios),
        get_scenarios,
        '' if all(item['passed'] for item in get_scenarios)
        else '일반 Get 후 선택 획득·Get 스킵·이동 재검사 검증에 실패했습니다.',
    ))

    lost_specs = (
        ('owner-p1-over-limit-loss-takes-five-hundred', 'p1', {}, 500, 1),
        ('owner-p2-over-limit-loss-takes-five-hundred', 'p2', {}, 500, 1),
        ('wrong-state-loss-does-not-deal-damage', 'p1', {'state': 'intimidation'}, 0, 0),
        ('opponent-state-loss-does-not-deal-damage', 'p2', {'state_player': 'p1'}, 0, 0),
        ('source-outside-lumen-does-not-deal-damage', 'p1', {'source_zone': 'side'}, 0, 0),
        ('numbered-negation-does-not-deal-damage', 'p2', {'negated': True}, 0, 0),
    )
    lost_scenarios = []
    for name, owner, kwargs, damage, resolved in lost_specs:
        first = _run_lmi_at_011_state_lost_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_011_state_lost_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        lost_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['damage'] == damage
                and first['resolved_count'] == resolved
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        lost['id'], all(item['passed'] for item in lost_scenarios),
        lost_scenarios,
        '' if all(item['passed'] for item in lost_scenarios)
        else '오버 리미트 해제 후 500 효과 데미지 검증에 실패했습니다.',
    ))

    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '프로토콜: 익시드의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _lmi_at_012_source(card_snapshot, owner, source_zone, *, negated=False):
    source = copy.deepcopy(card_snapshot or {})
    source.update({
        'instance_id': f'{owner}-rai-lefi-rush', 'owner': owner,
        'kind': 'card', 'code': 'LMI-AT-012',
        'name': '라이! 레피! 러시!', 'type': '공격',
        'frame': 10, 'damage': 300, 'pos': '상단', 'body': '',
        'special': None, 'hit': '콤보', 'guard': '-5', 'counter': '4',
        'character_id': 2, 'character_key': 'nya',
        'face_up': source_zone != 'hand',
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _lmi_at_012_engine(
    definition, card_snapshot, owner, *, source_zone='battle',
    ability_ids=None, extras=None, negated=False, extra_definitions=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_012_source(
        card_snapshot, owner, source_zone, negated=negated,
    )
    opposing = _card(
        'REVIEW-RUSH-OPPONENT', other, f'{other}-rush-opponent',
    )
    isolated = copy.deepcopy(definition)
    if ability_ids is not None:
        allowed = set(ability_ids)
        isolated['abilities'] = [
            ability for ability in isolated.get('abilities') or []
            if ability.get('id') in allowed
        ]
    state = _state(source, opposing, owner, source_zone=source_zone)
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = 0
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source), 'effect_definition': isolated,
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    for zone, card in extras or []:
        state['players'][card['owner']]['zones'][zone].append(
            copy.deepcopy(card),
        )
        cards[card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': copy.deepcopy(
                (extra_definitions or {}).get(card['code']) or no_effect
            ),
        }
    engine = AutomaticGameEngine(
        state,
        {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'rai-lefi-rush:{owner}:{source_zone}:{negated}:'
            f'{sorted(ability_ids or [])}:'
            f'{[(zone, card.get("instance_id")) for zone, card in extras or []]}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    return engine, source, opposing


def _lmi_at_012_context(engine, source, opposing, owner):
    return {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(engine._find_card(source['instance_id'])),
        'opponent_card': copy.deepcopy(
            engine._find_card(opposing['instance_id'])
        ),
        'source_battle_card_only': True,
        'use_context': 'ready',
    }


def _run_lmi_at_012_break_scenario(
    definition, card_snapshot, owner, *, source_zone='lumen',
    mode='owner_effect', negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    ally = _card('REVIEW-RUSH-ALLY', owner, f'{owner}-rush-ally')
    enemy = _card('REVIEW-RUSH-ENEMY', other, f'{other}-rush-enemy')
    engine, source, _opposing = _lmi_at_012_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-012-function'],
        extras=[('hand', ally), ('hand', enemy)], negated=negated,
    )
    kwargs = {}
    if mode == 'owner_effect':
        kwargs.update({
            'effect_controller': owner, 'effect_source': ally['instance_id'],
        })
    elif mode == 'opponent_effect':
        kwargs.update({
            'effect_controller': other, 'effect_source': enemy['instance_id'],
        })
    else:
        kwargs['direct_controller'] = owner
    moved = engine.break_card(
        source['instance_id'], reason=f'review-{mode}', **kwargs,
    )
    return {
        'zone': engine._find_location(source['instance_id'])[1],
        'moved': moved is not None,
        'prevented_count': sum(
            event.get('type') == 'card_break_prevented'
            and (event.get('payload') or {}).get('card_instance_id')
            == source['instance_id']
            for event in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_012_move_scenario(
    definition, card_snapshot, owner, *, candidate_zones=('hand',),
    accept=True, choose_index=0, source_zone='battle', event='use',
    negated=False, protected_indices=(), protect_after_choice=False,
    special_index=None,
):
    candidates = []
    extras = []
    extra_definitions = {}
    for index, zone in enumerate(candidate_zones):
        card = _card(
            f'REVIEW-RUSH-MOVE-{index}', owner,
            f'{owner}-rush-move-{index}',
        )
        card['character_key'] = 'nya'
        if special_index == index:
            card.update({
                'type': '특수', 'frame': None, 'damage': None,
                'pos': None, 'body': '', 'special': None,
                'hit': None, 'guard': None, 'counter': None,
            })
        candidates.append(card)
        extras.append((zone, card))
        if index in set(protected_indices):
            extra_definitions[card['code']] = {
                **_st1_001_no_effect_definition(), 'no_effect': False,
                'effect_immunity': {'scope': 'other_cards'},
            }
    engine, source, opposing = _lmi_at_012_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-012-n1'], extras=extras,
        negated=negated, extra_definitions=extra_definitions,
    )
    engine._fire(
        event, _lmi_at_012_context(engine, source, opposing, owner),
    )
    decisions = []
    decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
    if decision:
        decisions.append({
            'kind': decision.get('kind'),
            'option_ids': [
                str(option.get('id')) for option in decision.get('options') or []
            ],
        })
    if decision.get('kind') == 'optional_effect':
        engine._submit_decision(
            owner, decision['id'], ['accept'] if accept else ['decline'],
        )
        engine._continue()
        decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
        if decision:
            decisions.append({
                'kind': decision.get('kind'),
                'option_ids': [
                    str(option.get('id'))
                    for option in decision.get('options') or []
                ],
            })
    selected_id = None
    if decision.get('kind') == 'effect_choice':
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        if option_ids:
            selected_id = option_ids[min(choose_index, len(option_ids) - 1)]
            if protect_after_choice:
                selected = engine._find_card(selected_id)
                engine.ruleset['cards'][selected['code']]['effect_definition'] = {
                    **_st1_001_no_effect_definition(), 'no_effect': False,
                    'effect_immunity': {'scope': 'other_cards'},
                }
            engine._submit_decision(owner, decision['id'], [selected_id])
            engine._continue()
    return {
        'decisions': decisions,
        'selected_id': selected_id,
        'candidate_ids': [card['instance_id'] for card in candidates],
        'zones': {
            card['instance_id']: engine._find_location(card['instance_id'])[1]
            for card in candidates
        },
        'protected_not_offered': all(
            not decisions
            or candidates[index]['instance_id']
            not in decisions[-1]['option_ids']
            for index in protected_indices
        ),
        'resolved_count': sum(
            event_item.get('type') == 'effect_resolved'
            and (event_item.get('payload') or {}).get('ability_id')
            == 'lmi-at-012-n1'
            for event_item in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _lmi_at_012_lumen_cards(owner, count, *, include_non_technique=False):
    cards = []
    for index in range(count):
        card = _card(
            f'REVIEW-RUSH-LUMEN-{index}', owner,
            f'{owner}-rush-lumen-{index}',
        )
        card['character_key'] = 'nya'
        cards.append(card)
    if include_non_technique:
        non_technique = _card(
            'REVIEW-RUSH-NON-TECHNIQUE', owner,
            f'{owner}-rush-non-technique',
        )
        non_technique.update({
            'type': '캐릭터', 'frame': None, 'damage': None,
            'pos': None, 'body': '', 'special': None,
            'hit': None, 'guard': None, 'counter': None,
        })
        cards.append(non_technique)
    return cards


def _run_lmi_at_012_damage_scenario(
    definition, card_snapshot, owner, *, lumen_count=0,
    over_limit=True, source_zone='battle', negated=False,
    dynamic_add=False, include_non_technique=False,
):
    lumen_cards = _lmi_at_012_lumen_cards(
        owner, lumen_count, include_non_technique=include_non_technique,
    )
    extras = [('lumen', card) for card in lumen_cards]
    added = None
    if dynamic_add:
        added = _card(
            'REVIEW-RUSH-DYNAMIC', owner, f'{owner}-rush-dynamic',
        )
        extras.append(('hand', added))
    engine, source, _opposing = _lmi_at_012_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=['lmi-at-012-n2'], extras=extras, negated=negated,
    )
    if over_limit:
        engine.state['players'][owner]['passive_state']['over_limit'] = {
            'value': True, 'label': 'over_limit',
        }
    engine._refresh_continuous_rules()
    live_source = engine._find_card(source['instance_id'])
    before = engine.card_stat(live_source, 'damage', owner)
    after = before
    if added:
        engine.move_card(
            added['instance_id'], 'lumen', reason='review-dynamic-count',
        )
        engine._refresh_continuous_rules()
        after = engine.card_stat(live_source, 'damage', owner)
    return {
        'damage': before, 'damage_after_add': after,
        'lumen_count': len(engine._zone(owner, 'lumen')),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_012_fp_scenario(
    definition, card_snapshot, owner, *, lumen_count=0,
    event='before_judgment', source_zone='battle', negated=False,
    use_move=False, after_use_add=False,
):
    lumen_cards = _lmi_at_012_lumen_cards(owner, lumen_count)
    extras = [('lumen', card) for card in lumen_cards]
    move_candidate = None
    if use_move:
        move_candidate = _card(
            'REVIEW-RUSH-USE-MOVE', owner, f'{owner}-rush-use-move',
        )
        extras.append(('hand', move_candidate))
    late_candidate = None
    if after_use_add:
        late_candidate = _card(
            'REVIEW-RUSH-AFTER-USE', owner,
            f'{owner}-rush-after-use',
        )
        extras.append(('hand', late_candidate))
    ability_ids = ['lmi-at-012-n3']
    if use_move:
        ability_ids.insert(0, 'lmi-at-012-n1')
    engine, source, opposing = _lmi_at_012_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        ability_ids=ability_ids, extras=extras, negated=negated,
    )
    context = _lmi_at_012_context(engine, source, opposing, owner)
    decisions = []
    if use_move:
        engine._fire('use', context)
        decision = copy.deepcopy(engine.engine_state.get('pending_decision') or {})
        if decision:
            decisions.append(decision.get('kind'))
        if decision.get('kind') == 'optional_effect':
            engine._submit_decision(owner, decision['id'], ['accept'])
            engine._continue()
            decision = copy.deepcopy(
                engine.engine_state.get('pending_decision') or {},
            )
            if decision:
                decisions.append(decision.get('kind'))
        if decision.get('kind') == 'effect_choice':
            engine._submit_decision(
                owner, decision['id'], [move_candidate['instance_id']],
            )
            engine._continue()
    before = engine.state['players'][owner]['fp']
    engine._fire(event, context)
    gain = engine.state['players'][owner]['fp'] - before
    live_source = engine._find_card(source['instance_id'])
    reference_speed = engine.card_stat(
        live_source, 'frame', owner, include_fp=False,
    )
    fp_speed = engine.card_stat(
        live_source, 'frame', owner, include_fp=True,
    )
    if late_candidate:
        engine.move_card(
            late_candidate['instance_id'], 'lumen',
            reason='review-after-use-passive',
        )
    return {
        'fp_gain': gain, 'fp_total': engine.state['players'][owner]['fp'],
        'reference_speed': reference_speed, 'fp_speed': fp_speed,
        'lumen_count': len(engine._zone(owner, 'lumen')),
        'decision_kinds': decisions,
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_lmi_at_012_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-012':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('lmi-at-012-function')
    move_to_lumen = by_id.get('lmi-at-012-n1')
    damage_bonus = by_id.get('lmi-at-012-n2')
    fp_bonus = by_id.get('lmi-at-012-n3')
    qna_ids = [235, 431]
    grouped_count = {
        'op': 'floor_divide',
        'left': {
            'op': 'zone_count', 'player': {'controller': True},
            'zone': 'lumen', 'where': {'is_technique': True},
        },
        'right': 3,
    }
    move_selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['hand', 'list'], 'min': 1, 'max': 1,
        'where': {'is_technique': True},
        'as_operation': 'move_card', 'to_zone': 'lumen',
    }
    valid = bool(
        extra_root == {'break_rules'} and len(abilities) == 4
        and definition.get('break_rules') == {
            'forbidden_zones': ['lumen'],
        }
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == qna_ids
        and (definition.get('source_refs') or {}).get('detail_text') is True
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids
            and (ability.get('source_refs') or {}).get('detail_text') is True
            for ability in abilities
        )
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('effects') == [{
            'op': 'static_rule', 'rules': ['break_rules'],
        }]
        and not function.get('active_zones') and not function.get('trigger')
        and move_to_lumen and move_to_lumen.get('kind') == 'effect'
        and move_to_lumen.get('mode') == 'optional'
        and move_to_lumen.get('timing') == 'use'
        and move_to_lumen.get('active_zones') == ['battle']
        and move_to_lumen.get('trigger') == {'event': 'use'}
        and move_to_lumen.get('availability_selector') == move_selector
        and move_to_lumen.get('effects') == [{
            'op': 'request_choice', 'player': {'controller': True},
            'prompt': '루멘 존으로 보낼 기술을 선택하세요.',
            'selector': move_selector,
            'selection_key': 'lmi_at_012_move_to_lumen',
            'default': [],
            'then': [{
                'op': 'move_card',
                'selection_key': 'lmi_at_012_move_to_lumen',
                'to_zone': 'lumen',
            }],
        }]
        and damage_bonus and damage_bonus.get('kind') == 'effect'
        and damage_bonus.get('mode') == 'continuous'
        and damage_bonus.get('timing') == 'function'
        and damage_bonus.get('active_zones') == ['battle']
        and not damage_bonus.get('trigger')
        and damage_bonus.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'over_limit',
        }
        and damage_bonus.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'duration': 'continuous',
            'amount': {
                'op': 'multiply', 'values': [grouped_count, 100],
            },
        }]
        and fp_bonus and fp_bonus.get('kind') == 'effect'
        and fp_bonus.get('mode') == 'mandatory'
        and fp_bonus.get('timing') == 'before_judgment'
        and fp_bonus.get('active_zones') == ['battle']
        and fp_bonus.get('trigger') == {'event': 'before_judgment'}
        and not fp_bonus.get('condition')
        and fp_bonus.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True},
            'amount': {
                'op': 'multiply', 'values': [grouped_count, 2],
            },
        }]
        and str((card_snapshot or {}).get('name') or '')
        == '라이! 레피! 러시!'
        and str((card_snapshot or {}).get('type') or '') == '공격'
        and (card_snapshot or {}).get('frame') == 10
        and (card_snapshot or {}).get('damage') == 300
        and str((card_snapshot or {}).get('pos') or '') == '상단'
        and str((card_snapshot or {}).get('body') or '') == ''
        and (card_snapshot or {}).get('special') is None
        and str((card_snapshot or {}).get('hit') or '') == '콤보'
        and str((card_snapshot or {}).get('guard') or '') == '-5'
        and str((card_snapshot or {}).get('counter') or '') == '4'
        and int((card_snapshot or {}).get('character_id') or 0) == 2
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-012', False,
                reason='라이! 레피! 러시!의 브레이크·이동·루멘 배수 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-012 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    reviews = []
    break_specs = (
        ('owner-effect-cannot-break-from-lumen', 'p1', {'mode': 'owner_effect'}, 'lumen', False, 1),
        ('opponent-effect-cannot-break-from-lumen', 'p2', {'mode': 'opponent_effect'}, 'lumen', False, 1),
        ('owner-direct-cannot-break-from-lumen', 'p1', {'mode': 'owner_direct'}, 'lumen', False, 1),
        ('outside-lumen-may-be-broken', 'p2', {'mode': 'owner_effect', 'source_zone': 'list'}, 'break', True, 0),
        ('numbered-negation-keeps-numberless-break-rule', 'p1', {'mode': 'owner_effect', 'negated': True}, 'lumen', False, 1),
    )
    break_scenarios = []
    for name, owner, kwargs, zone, moved, prevented in break_specs:
        first = _run_lmi_at_012_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_012_break_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        break_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['zone'] == zone
                and first['moved'] is moved
                and first['prevented_count'] == prevented
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        function['id'], all(item['passed'] for item in break_scenarios),
        break_scenarios,
        '' if all(item['passed'] for item in break_scenarios)
        else '루멘 존 브레이크 금지 기능 검증에 실패했습니다.',
    ))

    move_specs = (
        ('owner-p1-selects-hand-technique', 'p1', {}, ['optional_effect', 'effect_choice'], 'lumen'),
        ('owner-p2-selects-second-list-technique', 'p2', {'candidate_zones': ('list', 'list'), 'choose_index': 1}, ['optional_effect', 'effect_choice'], 'lumen'),
        ('optional-use-may-be-declined', 'p1', {'accept': False}, ['optional_effect'], None),
        ('no-candidate-skips-activation', 'p2', {'candidate_zones': ()}, [], None),
        ('protected-candidate-is-not-offered', 'p1', {'candidate_zones': ('hand', 'list'), 'protected_indices': (0,)}, ['optional_effect', 'effect_choice'], 'lumen'),
        ('only-protected-candidate-skips-activation', 'p2', {'protected_indices': (0,)}, [], None),
        ('movement-protection-added-after-choice-is-rechecked', 'p1', {'protect_after_choice': True}, ['optional_effect', 'effect_choice'], 'hand'),
        ('wrong-event-does-not-trigger', 'p2', {'event': 'hit'}, [], None),
        ('source-outside-battle-does-not-trigger', 'p1', {'source_zone': 'hand'}, [], None),
        ('numbered-negation-does-not-trigger', 'p2', {'negated': True}, [], None),
        ('special-technique-may-be-sent-to-lumen', 'p1', {'special_index': 0}, ['optional_effect', 'effect_choice'], 'lumen'),
    )
    move_scenarios = []
    for name, owner, kwargs, kinds, selected_zone in move_specs:
        first = _run_lmi_at_012_move_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_012_move_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        actual_kinds = [item['kind'] for item in first['decisions']]
        actual_zone = (
            first['zones'].get(first['selected_id'])
            if first['selected_id'] else None
        )
        move_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and actual_kinds == kinds
                and actual_zone == selected_zone
                and first['protected_not_offered']
                and not first['pending']
            ),
            'deterministic': deterministic,
            'decision_kinds': actual_kinds, 'selected_zone': actual_zone,
            **first,
        })
    reviews.append(AbilityReview(
        move_to_lumen['id'], all(item['passed'] for item in move_scenarios),
        move_scenarios,
        '' if all(item['passed'] for item in move_scenarios)
        else '사용 시 선택 이동·후보 보호 재검사 검증에 실패했습니다.',
    ))

    damage_specs = (
        ('zero-lumen-keeps-three-hundred', 'p1', {'lumen_count': 0}, 300, 300),
        ('two-lumen-keeps-three-hundred', 'p2', {'lumen_count': 2}, 300, 300),
        ('three-lumen-adds-one-hundred', 'p1', {'lumen_count': 3}, 400, 400),
        ('five-lumen-still-adds-one-hundred', 'p2', {'lumen_count': 5}, 400, 400),
        ('six-lumen-adds-two-hundred', 'p1', {'lumen_count': 6}, 500, 500),
        ('eight-lumen-still-adds-two-hundred', 'p2', {'lumen_count': 8}, 500, 500),
        ('without-over-limit-keeps-printed-damage', 'p1', {'lumen_count': 6, 'over_limit': False}, 300, 300),
        ('source-outside-battle-keeps-printed-damage', 'p2', {'lumen_count': 6, 'source_zone': 'hand'}, 300, 300),
        ('numbered-negation-keeps-printed-damage', 'p1', {'lumen_count': 6, 'negated': True}, 300, 300),
        ('live-two-to-three-count-updates-damage', 'p2', {'lumen_count': 2, 'dynamic_add': True}, 300, 400),
        ('non-technique-in-lumen-is-not-counted', 'p1', {'lumen_count': 2, 'include_non_technique': True}, 300, 300),
    )
    damage_scenarios = []
    for name, owner, kwargs, damage, damage_after in damage_specs:
        first = _run_lmi_at_012_damage_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_012_damage_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        damage_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['damage'] == damage
                and first['damage_after_add'] == damage_after
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        damage_bonus['id'], all(item['passed'] for item in damage_scenarios),
        damage_scenarios,
        '' if all(item['passed'] for item in damage_scenarios)
        else '오버 리미트 루멘 3장당 데미지 검증에 실패했습니다.',
    ))

    fp_specs = (
        ('zero-lumen-gains-zero-fp', 'p1', {'lumen_count': 0}, 0, 10),
        ('two-lumen-gains-zero-fp', 'p2', {'lumen_count': 2}, 0, 10),
        ('three-lumen-gains-two-fp', 'p1', {'lumen_count': 3}, 2, 8),
        ('five-lumen-still-gains-two-fp', 'p2', {'lumen_count': 5}, 2, 8),
        ('qna-235-six-lumen-gains-four-fp-before-speed', 'p1', {'lumen_count': 6}, 4, 6),
        ('eight-lumen-still-gains-four-fp', 'p2', {'lumen_count': 8}, 4, 6),
        ('wrong-event-gains-no-fp', 'p1', {'lumen_count': 6, 'event': 'hit'}, 0, 10),
        ('source-outside-battle-gains-no-fp', 'p2', {'lumen_count': 6, 'source_zone': 'hand'}, 0, 10),
        ('numbered-negation-gains-no-fp', 'p1', {'lumen_count': 6, 'negated': True}, 0, 10),
        ('qna-431-use-move-two-to-three-counts-before-judgment', 'p2', {'lumen_count': 2, 'use_move': True}, 2, 8),
        ('qna-431-after-use-passive-addition-is-too-late', 'p1', {'lumen_count': 1, 'use_move': True, 'after_use_add': True}, 0, 10),
    )
    fp_scenarios = []
    for name, owner, kwargs, gain, speed in fp_specs:
        first = _run_lmi_at_012_fp_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_012_fp_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        fp_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and first['fp_gain'] == gain
                and first['reference_speed'] == 10
                and first['fp_speed'] == speed
                and not first['pending']
            ),
            'deterministic': deterministic, **first,
        })
    reviews.append(AbilityReview(
        fp_bonus['id'], all(item['passed'] for item in fp_scenarios),
        fp_scenarios,
        '' if all(item['passed'] for item in fp_scenarios)
        else '판정 전 루멘 3장당 FP와 속도 적용 검증에 실패했습니다.',
    ))

    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '라이! 레피! 러시!의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _lmi_at_019_source(card_snapshot, owner, source_zone, *, negated=False):
    source = copy.deepcopy(card_snapshot or {})
    source.update({
        'instance_id': f'{owner}-club-kick', 'owner': owner,
        'kind': 'card', 'code': 'LMI-AT-019', 'name': '클럽 킥',
        'type': '공격', 'frame': 7, 'damage': 400,
        'pos': '하단', 'body': '발', 'special': None,
        'hit': '2', 'guard': '-6', 'counter': '3',
        'character_id': 4, 'character_key': 'tao',
        'face_up': source_zone != 'hand',
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


def _lmi_at_019_engine(
    definition, card_snapshot, owner, *, source_zone='battle',
    down_stance=False, negated=False, opponent_pos='상단',
    opponent_type='공격', prior_specs=None,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _lmi_at_019_source(
        card_snapshot, owner, source_zone, negated=negated,
    )
    opposing = _card(
        'REVIEW-CLUB-KICK-OPPONENT', other,
        f'{other}-club-kick-opponent',
    )
    opposing.update({'pos': opponent_pos, 'type': opponent_type})
    support = None
    battle_source = source
    if source_zone != 'battle':
        support = _card(
            'REVIEW-CLUB-KICK-SUPPORT', owner,
            f'{owner}-club-kick-support',
        )
        battle_source = support
    state = _state(source, opposing, owner, source_zone=source_zone)
    if support:
        state['players'][owner]['zones']['battle'] = [copy.deepcopy(support)]
    state['players'][owner]['fp'] = 0
    state['players'][other]['fp'] = 0
    if down_stance:
        state['players'][owner]['passive_state']['down_stance'] = {
            'value': True, 'label': 'down_stance',
        }
    no_effect = _st1_001_no_effect_definition()
    cards = {
        source['code']: {
            **copy.deepcopy(source),
            'effect_definition': copy.deepcopy(definition),
        },
        opposing['code']: {
            **copy.deepcopy(opposing), 'effect_definition': no_effect,
        },
    }
    if support:
        cards[support['code']] = {
            **copy.deepcopy(support), 'effect_definition': no_effect,
        }
    prior_cards = []
    for index, spec in enumerate(prior_specs or []):
        prior_owner = spec.get('owner') or owner
        card = _card(
            f'REVIEW-CLUB-KICK-PRIOR-{index}', prior_owner,
            f'{prior_owner}-club-kick-prior-{index}',
        )
        card.update({
            'pos': spec.get('pos', '중단'),
            'type': spec.get('type', '공격'),
        })
        prior_cards.append((card, copy.deepcopy(spec)))
        state['players'][prior_owner]['zones']['list'].append(
            copy.deepcopy(card),
        )
        cards[card['code']] = {
            **copy.deepcopy(card), 'effect_definition': no_effect,
        }
    engine = AutomaticGameEngine(
        state, {'version': AUTOMATIC_SCENARIO_VERSION, 'cards': cards},
        seed=(
            f'club-kick:{owner}:{source_zone}:{down_stance}:{negated}:'
            f'{opponent_pos}:{opponent_type}:{prior_specs or []}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': battle_source['instance_id'],
            'card': copy.deepcopy(battle_source),
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': copy.deepcopy(opposing),
        },
    }
    for card, spec in prior_cards:
        engine._mark_card_used(
            card, spec.get('owner') or owner,
            spec.get('use_context', 'ready'),
        )
        if spec.get('previous_turn'):
            engine.engine_state['card_use_history'][-1]['turn'] = max(
                0, int(engine.state.get('turn') or 1) - 1,
            )
    return engine, source, opposing


def _run_lmi_at_019_fp_scenario(
    definition, card_snapshot, owner, *, down_stance=True,
    opponent_pos='상단', opponent_type='공격',
    event='before_judgment', source_zone='battle', negated=False,
):
    engine, source, opposing = _lmi_at_019_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        down_stance=down_stance, negated=negated,
        opponent_pos=opponent_pos, opponent_type=opponent_type,
    )
    before = engine.state['players'][owner]['fp']
    engine._fire(event, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(engine._find_card(source['instance_id'])),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
        'use_context': 'ready',
    })
    live_source = engine._find_card(source['instance_id'])
    return {
        'fp_gain': engine.state['players'][owner]['fp'] - before,
        'reference_speed': engine.card_stat(
            live_source, 'frame', owner, include_fp=False,
        ),
        'fp_speed': engine.card_stat(
            live_source, 'frame', owner, include_fp=True,
        ),
        'resolved_count': sum(
            item.get('type') == 'effect_resolved'
            and (item.get('payload') or {}).get('ability_id')
            == 'lmi-at-019-n1'
            for item in engine.events
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_lmi_at_019_catch_scenario(
    definition, card_snapshot, owner, *, prior_specs=None,
    negated=False, max_speed=7, selection=None,
    clear_history_after_declaration=False,
):
    engine, source, _opposing = _lmi_at_019_engine(
        definition, card_snapshot, owner, source_zone='hand',
        negated=negated, prior_specs=prior_specs,
    )
    other = 'p2' if owner == 'p1' else 'p1'
    catch = {
        'owner': owner, 'source': 'review-catch-window',
        'allow_zones': ['hand'], 'max_speed': max_speed,
    }
    options = [
        option for option in engine._legal_catch_options(owner, catch)
        if (option.get('card') or {}).get('instance_id')
        == source['instance_id']
    ]
    variants = sorted(
        [
            {
                'rule_index': option.get('catch_rule_index'),
                'fixed_speed': option.get('fixed_speed'),
            }
            for option in options
        ],
        key=lambda item: (
            item.get('fixed_speed') is not None,
            int(item.get('fixed_speed') or 0),
        ),
    )
    live_source = engine._find_card(source['instance_id'])
    result = {
        'variants': variants,
        'rule_count': len(engine._catch_rules(owner, live_source)),
        'played': False, 'pending': False,
    }
    desired_rule = None if selection == 'printed' else 0
    selected = next((
        option for option in options
        if selection in {'printed', 'optional'}
        and option.get('catch_rule_index') == desired_rule
    ), None)
    if selected is None:
        return result
    engine.engine_state.update({
        'catch': copy.deepcopy(catch), 'catch_queue': [],
        'granted_catches': [], 'catch_fp_history': [], 'step': 'catch',
    })
    engine._play_catch(
        owner, source['instance_id'],
        catch_rule_index=selected.get('catch_rule_index'),
    )
    pipeline = engine.engine_state.get('pipeline') or {}
    moved_source = engine._find_card(source['instance_id'])
    result.update({
        'played': True,
        'selected_rule_index': pipeline.get('catch_rule_index'),
        'selected_fixed_speed': pipeline.get('fixed_speed'),
        'effective_speed': engine.card_stat(
            moved_source, 'frame', owner, include_fp=False,
        ),
    })
    if clear_history_after_declaration:
        engine.engine_state['card_use_history'] = []
    engine._continue()
    moved_source = engine._find_card(source['instance_id'])
    result.update({
        'damage_after_effect': engine.card_stat(
            moved_source, 'damage', owner,
        ) if moved_source else None,
        'damage_amounts': [
            (item.get('payload') or {}).get('amount')
            for item in engine.events
            if item.get('type') == 'damage_dealt'
            and (item.get('payload') or {}).get('source') == 'catch'
        ],
        'opponent_hp': engine.state['players'][other]['hp'],
        'resolved_count': sum(
            item.get('type') == 'effect_resolved'
            and (item.get('payload') or {}).get('ability_id')
            == 'lmi-at-019-n2'
            for item in engine.events
        ),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    })
    return result


def _review_lmi_at_019_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'LMI-AT-019':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    fp_effect = by_id.get('lmi-at-019-n1')
    catch_effect = by_id.get('lmi-at-019-n2')
    used_middle_attack = {
        'op': 'used_card', 'player': {'controller': True},
        'where': {'pos': '중단', 'type_contains': '공격'}, 'min': 1,
    }
    catch_rules = [{
        'optional_fixed_speed': 3,
        'condition': used_middle_attack,
        'numbered_effect': True,
    }]
    catch_selection = {
        'op': 'all',
        'conditions': [
            {
                'op': 'equals',
                'left': 'context.catch_rule_index', 'right': 0,
            },
            {
                'op': 'equals',
                'left': 'context.fixed_speed', 'right': 3,
            },
        ],
    }
    valid = bool(
        extra_root == {'catch_rules'} and len(abilities) == 2
        and definition.get('catch_rules') == catch_rules
        and (definition.get('source_refs') or {}).get('qna_ids') == []
        and (definition.get('source_refs') or {}).get('detail_text') is True
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == []
            and (ability.get('source_refs') or {}).get('detail_text') is True
            for ability in abilities
        )
        and fp_effect and fp_effect.get('kind') == 'effect'
        and fp_effect.get('mode') == 'mandatory'
        and fp_effect.get('timing') == 'before_judgment'
        and fp_effect.get('active_zones') == ['battle']
        and fp_effect.get('trigger') == {'event': 'before_judgment'}
        and fp_effect.get('condition') == {
            'op': 'all',
            'conditions': [
                {
                    'op': 'card_matches',
                    'card': {'path': 'context.opponent_card'},
                    'where': {'pos': '상단', 'type_contains': '공격'},
                },
                {
                    'op': 'has_state',
                    'player': {'controller': True},
                    'state': 'down_stance',
                },
            ],
        }
        and fp_effect.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True}, 'amount': 1,
        }]
        and catch_effect and catch_effect.get('kind') == 'effect'
        and catch_effect.get('mode') == 'mandatory'
        and catch_effect.get('timing') == 'catch'
        and catch_effect.get('active_zones') == ['battle']
        and catch_effect.get('trigger') == {'event': 'catch'}
        and catch_effect.get('condition') == catch_selection
        and catch_effect.get('effects') == [{
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': -200, 'duration': 'battle',
        }]
        and str((card_snapshot or {}).get('name') or '') == '클럽 킥'
        and str((card_snapshot or {}).get('type') or '') == '공격'
        and int((card_snapshot or {}).get('frame') or 0) == 7
        and int((card_snapshot or {}).get('damage') or 0) == 400
        and str((card_snapshot or {}).get('pos') or '') == '하단'
        and str((card_snapshot or {}).get('body') or '') == '발'
        and (card_snapshot or {}).get('special') is None
        and str((card_snapshot or {}).get('hit') or '') == '2'
        and str((card_snapshot or {}).get('guard') or '') == '-6'
        and str((card_snapshot or {}).get('counter') or '') == '3'
        and int((card_snapshot or {}).get('character_id') or 0) == 4
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'lmi-at-019', False,
                reason='클럽 킥의 다운 자세 FP와 조건부 3속도 캐치 정의가 일치하지 않습니다.',
            )],
            'LMI-AT-019 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    fp_scenarios = []
    for name, owner, kwargs, expected in (
        ('owner-p1-down-upper-attack-gains-one-fp', 'p1', {}, {'fp_gain': 1, 'reference_speed': 7, 'fp_speed': 6, 'resolved_count': 1}),
        ('owner-p2-down-upper-attack-gains-one-fp', 'p2', {}, {'fp_gain': 1, 'reference_speed': 7, 'fp_speed': 6, 'resolved_count': 1}),
        ('without-down-stance-gains-no-fp', 'p1', {'down_stance': False}, {'fp_gain': 0, 'fp_speed': 7, 'resolved_count': 0}),
        ('middle-attack-gains-no-fp', 'p2', {'opponent_pos': '중단'}, {'fp_gain': 0, 'resolved_count': 0}),
        ('upper-defense-gains-no-fp', 'p1', {'opponent_type': '수비'}, {'fp_gain': 0, 'resolved_count': 0}),
        ('wrong-event-gains-no-fp', 'p2', {'event': 'use'}, {'fp_gain': 0, 'resolved_count': 0}),
        ('source-outside-battle-gains-no-fp', 'p1', {'source_zone': 'hand'}, {'fp_gain': 0, 'resolved_count': 0}),
        ('numbered-negation-gains-no-fp', 'p2', {'negated': True}, {'fp_gain': 0, 'resolved_count': 0}),
    ):
        first = _run_lmi_at_019_fp_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_019_fp_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        fp_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    middle_attack = [{'pos': '중단', 'type': '공격'}]
    catch_scenarios = []
    base_variant = {'rule_index': None, 'fixed_speed': None}
    optional_variant = {'rule_index': 0, 'fixed_speed': 3}
    for name, owner, kwargs, expected in (
        ('owner-p1-middle-attack-offers-printed-and-three', 'p1', {'prior_specs': middle_attack}, {'variants': [base_variant, optional_variant], 'rule_count': 1}),
        ('owner-p2-middle-attack-offers-printed-and-three', 'p2', {'prior_specs': middle_attack}, {'variants': [base_variant, optional_variant], 'rule_count': 1}),
        ('without-middle-attack-only-printed-seven', 'p1', {}, {'variants': [base_variant], 'rule_count': 0}),
        ('middle-defense-does-not-unlock-three', 'p2', {'prior_specs': [{'pos': '중단', 'type': '수비'}]}, {'variants': [base_variant], 'rule_count': 0}),
        ('upper-attack-does-not-unlock-three', 'p1', {'prior_specs': [{'pos': '상단', 'type': '공격'}]}, {'variants': [base_variant], 'rule_count': 0}),
        ('opponent-middle-attack-does-not-unlock-three', 'p2', {'prior_specs': [{'owner': 'p1', 'pos': '중단', 'type': '공격'}]}, {'variants': [base_variant], 'rule_count': 0}),
        ('previous-turn-middle-attack-does-not-unlock-three', 'p1', {'prior_specs': [{'pos': '중단', 'type': '공격', 'previous_turn': True}]}, {'variants': [base_variant], 'rule_count': 0}),
        ('numbered-negation-removes-three-speed', 'p2', {'prior_specs': middle_attack, 'negated': True}, {'variants': [base_variant], 'rule_count': 0}),
        ('speed-six-window-only-allows-three', 'p1', {'prior_specs': middle_attack, 'max_speed': 6}, {'variants': [optional_variant], 'rule_count': 1}),
        ('speed-two-window-allows-neither-variant', 'p2', {'prior_specs': middle_attack, 'max_speed': 2}, {'variants': [], 'rule_count': 1}),
        ('printed-seven-deals-four-hundred', 'p1', {'prior_specs': middle_attack, 'selection': 'printed'}, {'played': True, 'selected_rule_index': None, 'selected_fixed_speed': None, 'effective_speed': 7, 'damage_amounts': [400], 'resolved_count': 0}),
        ('selected-three-deals-two-hundred', 'p2', {'prior_specs': middle_attack, 'selection': 'optional'}, {'played': True, 'selected_rule_index': 0, 'selected_fixed_speed': 3, 'effective_speed': 3, 'damage_amounts': [200], 'resolved_count': 1}),
        ('selected-three-keeps-penalty-after-history-clears', 'p1', {'prior_specs': middle_attack, 'selection': 'optional', 'clear_history_after_declaration': True}, {'played': True, 'effective_speed': 3, 'damage_amounts': [200], 'resolved_count': 1}),
    ):
        first = _run_lmi_at_019_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        second = _run_lmi_at_019_catch_scenario(
            definition, card_snapshot, owner, **kwargs,
        )
        deterministic = _canonical(first) == _canonical(second)
        catch_scenarios.append({
            'name': name,
            'passed': bool(
                deterministic and not first['pending']
                and all(first.get(key) == value for key, value in expected.items())
            ),
            'deterministic': deterministic, 'expected': expected, **first,
        })

    reviews = [
        AbilityReview(
            fp_effect['id'], all(item['passed'] for item in fp_scenarios),
            fp_scenarios,
            '' if all(item['passed'] for item in fp_scenarios)
            else '다운 자세·상단 공격 판정 전 FP 검증에 실패했습니다.',
        ),
        AbilityReview(
            catch_effect['id'],
            all(item['passed'] for item in catch_scenarios), catch_scenarios,
            '' if all(item['passed'] for item in catch_scenarios)
            else '이번 턴 중단 공격·선택 3속도·데미지 -200 검증에 실패했습니다.',
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '클럽 킥의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _lmi_at_020_source(card_snapshot, owner, source_zone, *, negated=False):
    source = copy.deepcopy(card_snapshot or {})
    source.update({
        'instance_id': f'{owner}-street-rule', 'owner': owner,
        'kind': 'card', 'code': 'LMI-AT-020', 'name': '스트리트 룰',
        'type': '수비', 'frame': None, 'damage': None,
        'pos': None, 'body': '', 'special': None,
        'hit': None, 'guard': None, 'counter': None,
        'g_top': '상쇄', 'g_mid': '상쇄', 'g_bot': None,
        'character_id': 4, 'character_key': 'delphi',
        'face_up': source_zone != 'hand',
    })
    if negated:
        source['numbered_effects_negated'] = True
    return source


