def _run_cb02_at_042_scenario(
    definition, card_snapshot, owner, *, hand_speeds=(4,),
    selected_index=0, declaration='even', accept_effect=True,
    disaster=True, event_type='counter', source_zone='battle',
    negated=False, opponent_guard='+3', opponent_initial_fp=1,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated, opponent_fp=opponent_initial_fp,
    )
    opposing['guard'] = opponent_guard
    battle_opposing = (
        ((engine.engine_state.get('battle') or {}).get(other) or {}).get('card')
    )
    if isinstance(battle_opposing, dict):
        battle_opposing['guard'] = opponent_guard
    hand_cards = []
    for index, speed in enumerate(hand_speeds):
        card = _card(
            f'REVIEW-CB02-AT-042-HAND-{index + 1}', other,
            f'{other}-philiada-hand-{index + 1}',
        )
        card.update({
            'name': f'필리아다 상대 패 {index + 1}',
            'frame': speed, 'face_up': False,
        })
        hand_cards.append(card)
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }
    engine.state['players'][other]['zones']['hand'] = copy.deepcopy(hand_cards)
    if disaster:
        engine.state['players'][owner]['passive_state']['disaster_one'] = {
            'value': True, 'label': '재앙Ⅰ',
        }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    decision_kinds = []
    hand_option_ids = []
    guard = 0
    while engine.engine_state.get('pending_decision') and guard < 10:
        guard += 1
        decision = copy.deepcopy(engine.engine_state['pending_decision'])
        kind = decision.get('kind')
        decision_kinds.append(kind)
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        if kind == 'optional_effect':
            selected = 'accept' if accept_effect else 'decline'
        elif kind == 'hand_guess_card':
            hand_option_ids = option_ids
            preferred = (
                hand_cards[selected_index]['instance_id']
                if 0 <= selected_index < len(hand_cards) else None
            )
            selected = preferred if preferred in option_ids else option_ids[0]
        elif kind == 'hand_guess_parity':
            selected = declaration
        else:
            break
        engine._submit_decision(decision.get('owner'), decision['id'], [selected])
    guesses = [
        event for event in engine.events
        if event.get('type') == 'card_guess_resolved'
    ]
    live_source = engine._find_card(source['instance_id']) or source
    return {
        'decision_kinds': decision_kinds,
        'hand_option_ids': hand_option_ids,
        'hand_option_count': len(hand_option_ids),
        'guess_count': len(guesses),
        'correct_values': [
            bool((event.get('payload') or {}).get('correct'))
            for event in guesses
        ],
        'opponent_fp': engine.state['players'][other]['fp'],
        'damage': engine.card_stat(live_source, 'damage', owner),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st2_resolution_count(engine, 'cb02-at-042-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
        'guard_exhausted': guard >= 10,
    }


