def _run_cb02_at_043_setup_scenario(
    definition, card_snapshot, owner, *, event_type='game_start',
    source_zone='side', negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-atelier-of-pain', 'owner': owner,
        'kind': 'card', 'face_up': source_zone != 'side',
    })
    if negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-CB02-AT-043-OPPONENT', other,
        f'{other}-atelier-opponent',
    )
    state = _state(source, opposing, owner, source_zone=source_zone)
    no_effect = _st2_no_effect_definition()
    engine = AutomaticGameEngine(
        state, {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing), 'effect_definition': no_effect,
                },
            },
        },
        seed=f'cb02-at-043-setup:{owner}:{event_type}:{source_zone}:{negated}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    engine._fire(event_type, {'controller': owner})
    return {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st2_resolution_count(engine, 'cb02-at-043-function'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_043_battle_end_scenario(
    definition, card_snapshot, owner, *, owner_fp=6, opponent_fp=2,
    owner_hp=3000, used_ezebel=True, accept_effect=True,
    event_type='battle_end', source_zone='lumen', negated=False,
):
    engine, source, _opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated, owner_fp=owner_fp,
        opponent_fp=opponent_fp,
    )
    engine.state['players'][owner]['hp'] = owner_hp
    if used_ezebel:
        used = _card(
            'REVIEW-CB02-AT-043-USED', owner,
            f'{owner}-atelier-used-ezebel',
        )
        used.update({'character_key': 'ezebel', 'name': '이제벨 기술'})
        engine._mark_card_used(used, owner, 'ready')
    engine._fire(event_type, {'controller': owner})
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    if decision and decision.get('kind') == 'optional_effect':
        engine._submit_decision(
            decision.get('owner'), decision['id'],
            ['accept' if accept_effect else 'decline'],
        )
    return {
        'decision_kind': (decision or {}).get('kind'),
        'hp': engine.state['players'][owner]['hp'],
        'fp': engine.state['players'][owner]['fp'],
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st2_resolution_count(engine, 'cb02-at-043-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_043_recovery_scenario(
    definition, card_snapshot, owner, *, spider_count=8,
    wrong_token_count=0, owner_hp=3000, phase='recovery',
    event_type='phase_start', source_zone='lumen', negated=False,
):
    engine, source, _opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated,
    )
    engine.state['players'][owner]['hp'] = owner_hp
    engine.state['phase'] = phase
    tokens = []
    for index in range(spider_count + wrong_token_count):
        token = {
            'instance_id': f'{owner}-atelier-token-{index + 1}',
            'owner': owner, 'kind': 'token', 'type': '특수',
            'code': f'REVIEW-ATELIER-TOKEN-{index + 1}',
            'name': '거미 토큰' if index < spider_count else '다른 토큰',
            'token_key': 'spider' if index < spider_count else 'other',
            'frame': None, 'damage': None, 'pos': '', 'body': '',
            'hit': '0', 'guard': '0', 'counter': '0', 'face_up': True,
        }
        tokens.append(token)
        engine.ruleset['cards'][token['code']] = {
            **copy.deepcopy(token),
            'effect_definition': _st2_no_effect_definition(),
        }
    engine.state['players'][owner]['zones']['lumen'].extend(
        copy.deepcopy(tokens)
    )
    engine._fire(event_type, {'controller': owner, 'phase': phase})
    return {
        'hp': engine.state['players'][owner]['hp'],
        'source_zone': engine._find_location(source['instance_id'])[1],
        'spider_count': sum(
            card.get('token_key') == 'spider'
            for card in engine.state['players'][owner]['zones']['lumen']
        ),
        'resolved': _st2_resolution_count(engine, 'cb02-at-043-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb02_at_043_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB02-AT-043':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    setup = by_id.get('cb02-at-043-function')
    battle_end = by_id.get('cb02-at-043-n1')
    recovery = by_id.get('cb02-at-043-n2')
    battle_condition = {
        'op': 'all', 'conditions': [
            {
                'op': 'gte', 'left': 'context.controller_fp',
                'right': {
                    'op': 'add', 'values': [
                        {'path': 'context.opponent_fp'}, 4,
                    ],
                },
            },
            {
                'op': 'gte', 'left': 'context.controller_hp',
                'right': 200,
            },
        ],
    }
    recovery_condition = {
        'op': 'all', 'conditions': [
            {'op': 'phase_is', 'phase': 'recovery'},
            {
                'op': 'zone_count', 'player': {'controller': True},
                'zone': 'lumen', 'min': 8,
                'where': {'token_key': 'spider'},
            },
        ],
    }
    valid = bool(
        not extra_root and set(by_id) == {
            'cb02-at-043-function', 'cb02-at-043-n1', 'cb02-at-043-n2',
        }
        and not (definition.get('source_refs') or {}).get('qna_ids')
        and setup and setup.get('kind') == 'function'
        and setup.get('mode') == 'mandatory'
        and setup.get('timing') == 'function'
        and setup.get('active_zones') == ['side']
        and setup.get('trigger') == {'event': 'game_start'}
        and setup.get('effects') == [{'op': 'move_card', 'to_zone': 'lumen'}]
        and battle_end and battle_end.get('kind') == 'effect'
        and battle_end.get('mode') == 'optional'
        and battle_end.get('timing') == 'cleanup'
        and battle_end.get('active_zones') == ['lumen']
        and battle_end.get('trigger') == {'event': 'battle_end'}
        and battle_end.get('condition') == battle_condition
        and battle_end.get('cost') == [{
            'op': 'change_hp', 'player': {'controller': True}, 'amount': -200,
        }]
        and battle_end.get('effects') == [{
            'op': 'conditional',
            'condition': {
                'op': 'used_card', 'player': {'controller': True},
                'where': {'character_key': 'ezebel'}, 'min': 1,
            },
            'then': [{
                'op': 'change_fp',
                'player': {'controller': True}, 'amount': 1,
            }],
            'else': [],
        }]
        and recovery and recovery.get('kind') == 'effect'
        and recovery.get('mode') == 'mandatory'
        and recovery.get('timing') == 'function'
        and recovery.get('active_zones') == ['lumen']
        and recovery.get('trigger') == {'event': 'phase_start'}
        and recovery.get('condition') == recovery_condition
        and recovery.get('effects') == [
            {
                'op': 'change_hp',
                'player': {'controller': True}, 'amount': 400,
            },
            {'op': 'break_card'},
        ]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB02-AT-043', 'name': '아틀리에 오브 페인',
            'type': '특수', 'frame': None, 'damage': None,
            'pos': None, 'body': '', 'special': None,
            'hit': '0', 'guard': '0', 'counter': '0',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 13, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb02-at-043', False,
                reason='아틀리에 오브 페인의 시작 배치·FP 조건·거미 토큰 정의가 일치하지 않습니다.',
            )], 'CB02-AT-043 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    setup_scenarios = _st2_scenarios(
        _run_cb02_at_043_setup_scenario, definition, card_snapshot,
        (
            ('owner-p1-moves-from-side-at-game-start', 'p1', {}, {
                'source_zone': 'lumen', 'resolved': 1, 'pending': False,
            }),
            ('owner-p2-moves-from-side-at-game-start', 'p2', {}, {
                'source_zone': 'lumen', 'resolved': 1,
            }),
            ('wrong-event-keeps-card-in-side', 'p1', {
                'event_type': 'turn_start',
            }, {'source_zone': 'side', 'resolved': 0}),
            ('setup-is-inactive-outside-side', 'p2', {
                'source_zone': 'lumen',
            }, {'source_zone': 'lumen', 'resolved': 0}),
            ('numbered-negation-does-not-disable-numberless-setup', 'p1', {
                'negated': True,
            }, {'source_zone': 'lumen', 'resolved': 1}),
        ),
    )
    battle_scenarios = _st2_scenarios(
        _run_cb02_at_043_battle_end_scenario, definition, card_snapshot,
        (
            ('owner-p1-pays-and-gains-fp-after-ezebel-use', 'p1', {}, {
                'decision_kind': 'optional_effect', 'hp': 2800,
                'fp': 7, 'resolved': 1, 'pending': False,
            }),
            ('owner-p2-pays-and-gains-fp-after-ezebel-use', 'p2', {
                'owner_fp': 8, 'opponent_fp': 2,
            }, {'hp': 2800, 'fp': 9, 'resolved': 1}),
            ('payment-without-ezebel-use-gains-no-fp', 'p1', {
                'used_ezebel': False,
            }, {'hp': 2800, 'fp': 6, 'resolved': 1}),
            ('declining-effect-pays-nothing', 'p2', {
                'accept_effect': False,
            }, {'hp': 3000, 'fp': 6, 'resolved': 0}),
            ('exact-four-fp-advantage-is-eligible', 'p1', {
                'owner_fp': 5, 'opponent_fp': 1,
            }, {'decision_kind': 'optional_effect', 'hp': 2800,
                'fp': 6, 'resolved': 1}),
            ('three-fp-advantage-is-ineligible', 'p2', {
                'owner_fp': 5, 'opponent_fp': 2,
            }, {'decision_kind': None, 'hp': 3000, 'fp': 5,
                'resolved': 0}),
            ('one-hundred-ninety-nine-hp-cannot-pay', 'p1', {
                'owner_hp': 199,
            }, {'decision_kind': None, 'hp': 199, 'fp': 6,
                'resolved': 0}),
            ('wrong-event-does-not-offer-effect', 'p2', {
                'event_type': 'phase_end',
            }, {'decision_kind': None, 'hp': 3000, 'resolved': 0}),
            ('source-outside-lumen-is-inactive', 'p1', {
                'source_zone': 'side',
            }, {'decision_kind': None, 'source_zone': 'side',
                'hp': 3000, 'resolved': 0}),
            ('numbered-negation-does-not-offer-effect', 'p2', {
                'negated': True,
            }, {'decision_kind': None, 'hp': 3000, 'resolved': 0}),
        ),
    )
    recovery_scenarios = _st2_scenarios(
        _run_cb02_at_043_recovery_scenario, definition, card_snapshot,
        (
            ('owner-p1-eight-spiders-heals-and-breaks', 'p1', {}, {
                'hp': 3400, 'source_zone': 'break',
                'spider_count': 8, 'resolved': 1, 'pending': False,
            }),
            ('owner-p2-nine-spiders-heals-and-breaks', 'p2', {
                'spider_count': 9,
            }, {'hp': 3400, 'source_zone': 'break',
                'spider_count': 9, 'resolved': 1}),
            ('seven-spiders-plus-other-token-does-not-count', 'p1', {
                'spider_count': 7, 'wrong_token_count': 3,
            }, {'hp': 3000, 'source_zone': 'lumen',
                'spider_count': 7, 'resolved': 0}),
            ('wrong-phase-does-not-heal-or-break', 'p2', {
                'phase': 'get',
            }, {'hp': 3000, 'source_zone': 'lumen', 'resolved': 0}),
            ('wrong-event-does-not-heal-or-break', 'p1', {
                'event_type': 'phase_end',
            }, {'hp': 3000, 'source_zone': 'lumen', 'resolved': 0}),
            ('source-outside-lumen-is-inactive', 'p2', {
                'source_zone': 'side',
            }, {'hp': 3000, 'source_zone': 'side', 'resolved': 0}),
            ('numbered-negation-keeps-source-in-lumen', 'p1', {
                'negated': True,
            }, {'hp': 3000, 'source_zone': 'lumen', 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            setup['id'], all(item['passed'] for item in setup_scenarios),
            setup_scenarios,
        ),
        AbilityReview(
            battle_end['id'],
            all(item['passed'] for item in battle_scenarios),
            battle_scenarios,
        ),
        AbilityReview(
            recovery['id'],
            all(item['passed'] for item in recovery_scenarios),
            recovery_scenarios,
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '아틀리에 오브 페인의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _cb02_at_001_mark_card(owner, index, character_id, *, original=None):
    card = _card(
        f'REVIEW-CB02-AT-001-MARK-{index}', owner,
        f'{owner}-yanartas-mark-{index}',
    )
    card.update({
        'name': f'검토 마크 {index}', 'type': '공격',
        'character_id': character_id, 'frame': 6, 'damage': 400,
        'face_up': True,
    })
    if original is not None:
        card['original_character_id'] = original
    return card


def _run_cb02_at_001_function_scenario(
    definition, card_snapshot, owner, *, mark_count=9, neutral_count=0,
    duplicate_transformed=False, defense='dodge', source_zone='battle',
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        opponent_type='수비',
    )
    opposing['g_mid'] = '회피' if defense == 'dodge' else '상쇄'
    marks = [
        _cb02_at_001_mark_card(owner, index + 1, index + 2)
        for index in range(mark_count)
    ]
    if duplicate_transformed and marks:
        marks.append(_cb02_at_001_mark_card(
            owner, 80, 15, original=marks[0]['character_id'],
        ))
    marks.extend(
        _cb02_at_001_mark_card(owner, 90 + index, 1)
        for index in range(neutral_count)
    )
    engine.state['players'][owner]['zones']['break'] = copy.deepcopy(marks)
    engine._refresh_continuous_rules()
    result = engine._attack_vs_defense(
        source, opposing, owner, 'p2' if owner == 'p1' else 'p1',
    )
    return {
        'use_allowed': engine._card_use_allowed(source, owner, 'ready'),
        'result': list(result),
        'dodge_preventions': sum(
            item.get('kind') == 'dodge'
            for item in engine.engine_state.get('replacements') or []
        ),
        'clash_preventions': sum(
            item.get('kind') == 'clash'
            for item in engine.engine_state.get('replacements') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_001_combo_scenario(
    definition, card_snapshot, owner, *, used_count=1, mark_count=9,
    numbered_negated=False, source_zone='hand', last_speed=3,
):
    engine, source, _opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    marks = [
        _cb02_at_001_mark_card(owner, index + 1, index + 2)
        for index in range(mark_count)
    ]
    engine.state['players'][owner]['zones']['break'] = copy.deepcopy(marks)
    combo = {
        'owner': owner, 'source': 'review-combo-source',
        'used': [f'{owner}-used-{index}' for index in range(used_count)],
        'last_speed': last_speed, 'next_penalty': 100 * (used_count + 1),
        'max_combo': 3, 'proposal_submitted': False,
    }
    rules = engine._combo_rules(owner, source, combo)
    return {
        'rule_count': len(rules),
        'ignore_speed': any(rule.get('ignore_speed') for rule in rules),
        'legal': engine._combo_card_legal(owner, source, combo),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_001_finish_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    source_zone='battle', numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    return {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'end_battle_requested': bool(
            engine.engine_state.get('end_battle_requested')
        ),
        'resolved': _st2_resolution_count(engine, 'cb02-at-001-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb02_at_001_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB02-AT-001':
        return None
    qna_ids = [686, 687, 688, 689, 690]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('cb02-at-001-function')
    combo = by_id.get('cb02-at-001-n1')
    finish = by_id.get('cb02-at-001-n2')
    play_condition = {
        'op': 'gte',
        'left': {
            'op': 'zone_distinct_count',
            'player': {'controller': True}, 'zone': 'break',
            'field': 'printed_character_id', 'exclude_values': [1],
            'where': {'is_technique': True},
        },
        'right': 9,
    }
    combo_rules = [{
        'min_combo': 3, 'max_combo': 3, 'ignore_speed': True,
        'numbered_effect': True,
    }]
    valid = bool(
        extra_root == {'play_condition', 'combo_rules'}
        and set(by_id) == {
            'cb02-at-001-function', 'cb02-at-001-n1', 'cb02-at-001-n2',
        }
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and definition.get('play_condition') == play_condition
        and definition.get('combo_rules') == combo_rules
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('active_zones') == ['battle']
        and not function.get('trigger')
        and function.get('effects') == [
            {
                'op': 'prevent', 'kind': 'dodge',
                'player': {'opponent': True}, 'duration': 'continuous',
            },
            {
                'op': 'prevent', 'kind': 'clash',
                'player': {'opponent': True}, 'duration': 'continuous',
            },
        ]
        and combo and combo.get('kind') == 'effect'
        and combo.get('mode') == 'mandatory'
        and combo.get('timing') == 'combo'
        and combo.get('active_zones') == ['hand', 'list', 'lumen', 'battle']
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('effects') == [{
            'op': 'static_rule', 'rules': ['combo_rules'],
        }]
        and finish and finish.get('kind') == 'effect'
        and finish.get('mode') == 'mandatory'
        and finish.get('timing') == 'after_use'
        and finish.get('active_zones') == ['battle']
        and finish.get('trigger') == {'event': 'after_use'}
        and finish.get('effects') == [
            {'op': 'break_card', 'continue_resolution': True},
            {'op': 'end_battle'},
        ]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB02-AT-001', 'name': '야나르타쉬',
            'type': '공격', 'frame': 9, 'damage': 900,
            'pos': '중단', 'body': '', 'special': None,
            'hit': '9', 'guard': '9', 'counter': '9',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 15, 'ultimate': True,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb02-at-001', False,
                reason='야나르타쉬의 마크·회피/상쇄·3콤보·배틀 종료 정의가 일치하지 않습니다.',
            )], 'CB02-AT-001 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    function_scenarios = _st2_scenarios(
        _run_cb02_at_001_function_scenario, definition, card_snapshot,
        (
            ('owner-p1-nine-marks-prevents-dodge', 'p1', {}, {
                'use_allowed': True, 'result': ['hit', 'failed_defense'],
                'dodge_preventions': 1, 'clash_preventions': 1,
                'pending': False,
            }),
            ('owner-p2-nine-marks-prevents-clash', 'p2', {
                'defense': 'clash',
            }, {'use_allowed': True, 'result': ['hit', 'failed_defense']}),
            ('eight-distinct-marks-do-not-meet-play-condition', 'p1', {
                'mark_count': 8,
            }, {'use_allowed': False}),
            ('neutral-mark-does-not-make-the-ninth-kind', 'p2', {
                'mark_count': 8, 'neutral_count': 2,
            }, {'use_allowed': False}),
            ('chimera-treatment-does-not-add-a-second-mark', 'p1', {
                'mark_count': 8, 'duplicate_transformed': True,
            }, {'use_allowed': False}),
            ('function-is-inactive-outside-battle', 'p2', {
                'source_zone': 'hand',
            }, {
                'result': ['opponent_dodge', 'dodge'],
                'dodge_preventions': 0, 'clash_preventions': 0,
            }),
        ),
    )
    combo_scenarios = _st2_scenarios(
        _run_cb02_at_001_combo_scenario, definition, card_snapshot,
        (
            ('owner-p1-can-use-as-third-combo-ignoring-speed', 'p1', {}, {
                'rule_count': 1, 'ignore_speed': True, 'legal': True,
            }),
            ('owner-p2-can-use-as-third-combo-ignoring-speed', 'p2', {}, {
                'rule_count': 1, 'legal': True,
            }),
            ('cannot-use-as-second-combo', 'p1', {
                'used_count': 0,
            }, {'legal': False}),
            ('cannot-use-after-third-combo', 'p2', {
                'used_count': 2,
            }, {'legal': False}),
            ('numbered-negation-removes-combo-exception', 'p1', {
                'numbered_negated': True, 'last_speed': 10,
            }, {'rule_count': 0, 'ignore_speed': False, 'legal': False}),
            ('nine-mark-play-condition-still-applies-in-combo', 'p2', {
                'mark_count': 8,
            }, {'legal': False}),
        ),
    )
    finish_scenarios = _st2_scenarios(
        _run_cb02_at_001_finish_scenario, definition, card_snapshot,
        (
            ('owner-p1-breaks-source-and-ends-battle', 'p1', {}, {
                'source_zone': 'break', 'end_battle_requested': True,
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-breaks-source-and-ends-battle', 'p2', {}, {
                'source_zone': 'break', 'end_battle_requested': True,
                'resolved': 1,
            }),
            ('wrong-event-does-not-end-battle', 'p1', {
                'event_type': 'use',
            }, {'source_zone': 'battle', 'end_battle_requested': False,
                'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'source_zone': 'hand', 'end_battle_requested': False,
                'resolved': 0}),
            ('numbered-negation-keeps-battle-running', 'p1', {
                'numbered_negated': True,
            }, {'source_zone': 'battle', 'end_battle_requested': False,
                'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            function['id'], all(item['passed'] for item in function_scenarios),
            function_scenarios,
        ),
        AbilityReview(
            combo['id'], all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
        ),
        AbilityReview(
            finish['id'], all(item['passed'] for item in finish_scenarios),
            finish_scenarios,
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '야나르타쉬의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_cb02_at_002_protection_scenario(
    definition, card_snapshot, owner, *, source_zone='lumen',
    movement='opponent_effect', numbered_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, source_type='특수',
    )
    engine.state['players'][owner]['character'] = {
        'id': 15, 'hand_table': {'5000': 5},
    }
    if movement == 'opponent_effect':
        moved = engine.move_card(
            source['instance_id'], 'break', effect_controller=other,
            effect_source=opposing['instance_id'], reason='review-effect',
        )
    elif movement == 'own_other_effect':
        moved = engine.move_card(
            source['instance_id'], 'break', effect_controller=owner,
            effect_source=opposing['instance_id'], reason='review-effect',
        )
    else:
        moved = engine.move_card(
            source['instance_id'], 'break', reason='review-core',
        )
    return {
        'moved': moved is not None,
        'source_zone': engine._find_location(source['instance_id'])[1],
        'ignored_count': sum(
            event.get('type') == 'card_effect_ignored'
            for event in engine.events
        ),
        'hand_limit': engine._current_hand_limit(owner),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_002_setup_scenario(
    definition, card_snapshot, owner, *, source_zone='side',
    event_type='game_start', numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, source_type='특수',
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source), 'source_only_event': True,
        'opponent_card': copy.deepcopy(opposing),
    })
    return {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st2_resolution_count(
            engine, 'cb02-at-002-function-2',
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_002_acquire_scenario(
    definition, card_snapshot, owner, *, list_count=2, select_index=0,
    accept_effect=True, event_owner='self', event_technique=True,
    combo_active=False, source_zone='lumen', event_type='card_broken',
    numbered_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, source_type='특수',
    )
    engine.state['players'][owner]['character'] = {
        'id': 15, 'hand_table': {'5000': 5},
    }
    candidates = []
    for index in range(list_count):
        card = _card(
            f'REVIEW-CB02-AT-002-LIST-{index + 1}', owner,
            f'{owner}-providence-list-{index + 1}',
        )
        card.update({
            'name': f'획득 후보 {index + 1}', 'type': '공격',
            'frame': 5 + index, 'damage': 400, 'face_up': True,
        })
        candidates.append(card)
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }
    engine.state['players'][owner]['zones']['list'] = copy.deepcopy(candidates)
    event_side = owner if event_owner == 'self' else other
    event_card = _card(
        'REVIEW-CB02-AT-002-BROKEN', event_side,
        f'{event_side}-providence-broken',
    )
    if not event_technique:
        event_card.update({'kind': 'token', 'type': '토큰'})
    if combo_active:
        engine.engine_state['combo'] = {
            'owner': owner, 'source': 'review-combo', 'used': [],
        }
    engine._fire(event_type, {
        'controller': event_side,
        'source_card_instance_id': event_card['instance_id'],
        'source_card': copy.deepcopy(event_card),
    })
    outer = copy.deepcopy(engine.engine_state.get('pending_decision'))
    choice = None
    option_ids = []
    selected_id = (
        candidates[select_index]['instance_id']
        if 0 <= select_index < len(candidates) else None
    )
    if outer and outer.get('kind') == 'optional_effect':
        engine._submit_decision(
            outer['owner'], outer['id'],
            ['accept' if accept_effect else 'decline'],
        )
        choice = copy.deepcopy(engine.engine_state.get('pending_decision'))
    if choice and choice.get('kind') == 'effect_choice':
        option_ids = [
            str(option.get('id')) for option in choice.get('options') or []
        ]
        if selected_id not in option_ids:
            selected_id = option_ids[0] if option_ids else None
        engine._submit_decision(
            choice['owner'], choice['id'], [selected_id] if selected_id else [],
        )
    return {
        'outer_kind': (outer or {}).get('kind'),
        'choice_kind': (choice or {}).get('kind'),
        'option_count': len(option_ids),
        'selected_zone': (
            engine._find_location(selected_id)[1] if selected_id else None
        ),
        'hand_limit': engine._current_hand_limit(owner),
        'resolved': _st2_resolution_count(engine, 'cb02-at-002-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb02_at_002_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB02-AT-002':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    protected = by_id.get('cb02-at-002-function')
    setup = by_id.get('cb02-at-002-function-2')
    acquire = by_id.get('cb02-at-002-n1')
    selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['list'], 'min': 1, 'max': 1,
        'as_operation': 'move_card', 'to_zone': 'hand',
    }
    acquire_condition = {
        'op': 'all', 'conditions': [
            {
                'op': 'equals', 'left': 'context.event_controller',
                'right': {'controller': True},
            },
            {
                'op': 'card_matches',
                'card': {'path': 'context.event_card'},
                'where': {'is_technique': True},
            },
            {
                'op': 'equals', 'left': {'path': 'engine.combo'},
                'right': None,
            },
        ],
    }
    valid = bool(
        extra_root == {
            'effect_immunity', 'deck_rules_when_included', 'hand_limit_bonus',
        }
        and set(by_id) == {
            'cb02-at-002-function', 'cb02-at-002-function-2',
            'cb02-at-002-n1',
        }
        and not (definition.get('source_refs') or {}).get('qna_ids')
        and definition.get('effect_immunity') == {
            'scope': 'other_cards', 'active_zones': ['lumen'],
        }
        and definition.get('deck_rules_when_included') == {
            'special_allowed_character_ids': [15],
        }
        and definition.get('hand_limit_bonus') == 1
        and protected and protected.get('kind') == 'function'
        and protected.get('mode') == 'continuous'
        and protected.get('timing') == 'function'
        and protected.get('active_zones') == ['lumen']
        and not protected.get('trigger')
        and protected.get('effects') == [{
            'op': 'static_rule',
            'rules': ['effect_immunity', 'deck_rules_when_included'],
        }]
        and setup and setup.get('kind') == 'function'
        and setup.get('mode') == 'mandatory'
        and setup.get('timing') == 'function'
        and setup.get('active_zones') == ['side']
        and setup.get('trigger') == {'event': 'game_start'}
        and setup.get('effects') == [{'op': 'move_card', 'to_zone': 'lumen'}]
        and acquire and acquire.get('kind') == 'effect'
        and acquire.get('mode') == 'optional'
        and acquire.get('timing') == 'cleanup'
        and acquire.get('active_zones') == ['lumen']
        and acquire.get('trigger') == {'event': 'card_broken'}
        and acquire.get('condition') == acquire_condition
        and acquire.get('availability_selector') == selector
        and acquire.get('recheck_condition') is True
        and acquire.get('effects') == [{
            'op': 'request_choice', 'player': {'controller': True},
            'prompt': '리스트에서 획득할 기술을 선택하세요.',
            'selector': selector, 'selection_key': 'cb02_at_002_acquire',
            'default': [],
            'then': [{
                'op': 'move_card', 'selection_key': 'cb02_at_002_acquire',
                'to_zone': 'hand',
            }],
        }]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB02-AT-002', 'name': '섭리의 궤', 'type': '특수',
            'frame': None, 'damage': None, 'pos': None, 'body': '',
            'special': None, 'hit': '0', 'guard': '0', 'counter': '0',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 15, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb02-at-002', False,
                reason='섭리의 궤의 편성·보호·시작 배치·획득 정의가 일치하지 않습니다.',
            )], 'CB02-AT-002 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    protection_scenarios = _st2_scenarios(
        _run_cb02_at_002_protection_scenario, definition, card_snapshot,
        (
            ('owner-p1-lumen-card-ignores-opponent-effect', 'p1', {}, {
                'moved': False, 'source_zone': 'lumen', 'ignored_count': 1,
                'hand_limit': 6, 'pending': False,
            }),
            ('owner-p2-lumen-card-ignores-opponent-effect', 'p2', {}, {
                'moved': False, 'source_zone': 'lumen', 'ignored_count': 1,
            }),
            ('lumen-card-also-ignores-another-own-card-effect', 'p1', {
                'movement': 'own_other_effect',
            }, {'moved': False, 'source_zone': 'lumen', 'ignored_count': 1}),
            ('core-movement-is-not-another-card-effect', 'p2', {
                'movement': 'core',
            }, {'moved': True, 'source_zone': 'break', 'ignored_count': 0}),
            ('protection-and-hand-bonus-require-lumen-zone', 'p1', {
                'source_zone': 'side',
            }, {'moved': True, 'source_zone': 'break', 'hand_limit': 5}),
            ('numbered-negation-does-not-disable-unnumbered-protection', 'p2', {
                'numbered_negated': True,
            }, {'moved': False, 'source_zone': 'lumen', 'ignored_count': 1}),
        ),
    )
    setup_scenarios = _st2_scenarios(
        _run_cb02_at_002_setup_scenario, definition, card_snapshot,
        (
            ('owner-p1-moves-side-card-to-lumen-at-start', 'p1', {}, {
                'source_zone': 'lumen', 'resolved': 1, 'pending': False,
            }),
            ('owner-p2-moves-side-card-to-lumen-at-start', 'p2', {}, {
                'source_zone': 'lumen', 'resolved': 1,
            }),
            ('wrong-event-keeps-card-in-side', 'p1', {
                'event_type': 'turn_start',
            }, {'source_zone': 'side', 'resolved': 0}),
            ('source-already-outside-side-does-not-run-setup', 'p2', {
                'source_zone': 'lumen',
            }, {'source_zone': 'lumen', 'resolved': 0}),
            ('numbered-negation-does-not-disable-setup-function', 'p1', {
                'numbered_negated': True,
            }, {'source_zone': 'lumen', 'resolved': 1}),
        ),
    )
    acquire_scenarios = _st2_scenarios(
        _run_cb02_at_002_acquire_scenario, definition, card_snapshot,
        (
            ('owner-p1-selects-a-real-list-card-to-acquire', 'p1', {}, {
                'outer_kind': 'optional_effect', 'choice_kind': 'effect_choice',
                'option_count': 2, 'selected_zone': 'hand',
                'hand_limit': 6, 'resolved': 1, 'pending': False,
            }),
            ('owner-p2-selects-the-second-real-list-card', 'p2', {
                'select_index': 1,
            }, {'selected_zone': 'hand', 'resolved': 1}),
            ('declining-keeps-the-list-card', 'p1', {
                'accept_effect': False,
            }, {'choice_kind': None, 'selected_zone': 'list', 'resolved': 0}),
            ('empty-list-offers-no-effect', 'p2', {
                'list_count': 0,
            }, {'outer_kind': None, 'choice_kind': None, 'resolved': 0}),
            ('opponent-technique-break-does-not-trigger', 'p1', {
                'event_owner': 'opponent',
            }, {'outer_kind': None, 'resolved': 0}),
            ('non-technique-break-does-not-trigger', 'p2', {
                'event_technique': False,
            }, {'outer_kind': None, 'resolved': 0}),
            ('combo-time-break-does-not-trigger', 'p1', {
                'combo_active': True,
            }, {'outer_kind': None, 'resolved': 0}),
            ('source-outside-lumen-is-inactive', 'p2', {
                'source_zone': 'side',
            }, {'outer_kind': None, 'hand_limit': 5, 'resolved': 0}),
            ('numbered-negation-disables-acquisition', 'p1', {
                'numbered_negated': True,
            }, {'outer_kind': None, 'resolved': 0}),
            ('wrong-event-does-not-trigger', 'p2', {
                'event_type': 'card_discarded',
            }, {'outer_kind': None, 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            protected['id'],
            all(item['passed'] for item in protection_scenarios),
            protection_scenarios,
        ),
        AbilityReview(
            setup['id'], all(item['passed'] for item in setup_scenarios),
            setup_scenarios,
        ),
        AbilityReview(
            acquire['id'], all(item['passed'] for item in acquire_scenarios),
            acquire_scenarios,
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '섭리의 궤의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_cb02_at_012_discard_scenario(
    definition, card_snapshot, owner, *, hand_count=3, select_reverse=False,
    event_type='guard', source_zone='battle', numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, source_type='수비',
    )
    hand = []
    for index in range(hand_count):
        card = _card(
            f'REVIEW-CB02-AT-012-HAND-{index + 1}', owner,
            f'{owner}-friends-shield-hand-{index + 1}',
        )
        card.update({'name': f'버림 후보 {index + 1}', 'face_up': False})
        hand.append(card)
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }
    engine.state['players'][owner]['zones']['hand'] = copy.deepcopy(hand)
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    decision = copy.deepcopy(engine.engine_state.get('pending_decision'))
    option_ids = [
        str(option.get('id')) for option in (decision or {}).get('options') or []
    ]
    if decision and decision.get('kind') == 'effect_choice':
        selected = list(reversed(option_ids)) if select_reverse else option_ids
        selected = selected[:int(decision.get('maximum') or 0)]
        engine._submit_decision(
            decision['owner'], decision['id'], selected,
        )
    list_ids = {
        card.get('instance_id')
        for card in engine.state['players'][owner]['zones']['list']
    }
    return {
        'decision_kind': (decision or {}).get('kind'),
        'minimum': (decision or {}).get('minimum'),
        'maximum': (decision or {}).get('maximum'),
        'option_count': len(option_ids),
        'discarded_count': sum(
            card['instance_id'] in list_ids for card in hand
        ),
        'hand_count': len(engine.state['players'][owner]['zones']['hand']),
        'resolved': _st2_resolution_count(engine, 'cb02-at-012-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_012_clash_scenario(
    definition, card_snapshot, owner, *, opponent_hit='콤보',
    event_type='clash', source_zone='battle', numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, source_type='수비',
        opponent_hit=opponent_hit,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    return {
        'opponent_hit': opposing.get('hit'),
        'resolved': _st2_resolution_count(engine, 'cb02-at-012-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_012_return_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    source_zone='battle', numbered_negated=False, test_expiry=True,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, source_type='수비',
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    initial_zone = engine._find_location(source['instance_id'])[1]
    live = engine._find_card(source['instance_id'])
    blocked_through = (
        (live or {}).get('move_to_hand_blocked_through_turn')
    )
    current_blocked = next_blocked = after_next_moved = None
    if test_expiry and initial_zone == 'list':
        current_blocked = engine.move_card(
            source['instance_id'], 'hand', reason='review-current-turn',
        ) is None
        engine._complete_turn()
        next_blocked = engine.move_card(
            source['instance_id'], 'hand', reason='review-next-turn',
        ) is None
        engine._complete_turn()
        after_next_moved = engine.move_card(
            source['instance_id'], 'hand', reason='review-after-next-turn',
        ) is not None
    return {
        'initial_zone': initial_zone,
        'blocked_through': blocked_through,
        'current_turn_blocked': current_blocked,
        'next_turn_blocked': next_blocked,
        'after_next_turn_moved': after_next_moved,
        'final_zone': engine._find_location(source['instance_id'])[1],
        'resolved': _st2_resolution_count(engine, 'cb02-at-012-n3'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


