def _run_cb02_at_035_catch_scenario(
    definition, card_snapshot, owner, *, saintess=True,
    initially_revealed=False, accept_effect=True, event_type='guard',
    source_zone='hand', numbered_negated=False,
):
    engine, source, event_card = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    live_source = engine._find_card(source['instance_id'])
    if live_source:
        live_source['face_up'] = bool(initially_revealed)
    if saintess:
        engine.set_passive(owner, 'saintess', value=True)
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': event_card['instance_id'],
        'source_card': copy.deepcopy(event_card),
    })
    outer = copy.deepcopy(engine.engine_state.get('pending_decision'))
    if outer and outer.get('kind') == 'optional_effect':
        engine._submit_decision(
            outer['owner'], outer['id'],
            ['accept' if accept_effect else 'decline'],
        )
    grants = list(engine.engine_state.get('granted_catches') or [])
    catch_options = (
        engine._legal_catch_options(owner, grants[0]) if grants else []
    )
    return {
        'outer_kind': (outer or {}).get('kind'),
        'face_up': bool((engine._find_card(source['instance_id']) or {}).get('face_up')),
        'grant_count': len(grants),
        'catch_option_ids': [
            (option.get('card') or {}).get('instance_id')
            for option in catch_options
        ],
        'resolved': _st2_resolution_count(engine, 'cb02-at-035-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_035_fp_scenario(
    definition, card_snapshot, owner, *, event_type='hit', owner_fp=1,
    already_skipped=False, accept_effect=True, source_zone='battle',
    numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, owner_fp=owner_fp,
    )
    if already_skipped:
        engine.engine_state.setdefault('skip_get', {})[owner] = True
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    outer = copy.deepcopy(engine.engine_state.get('pending_decision'))
    if outer and outer.get('kind') == 'optional_effect':
        engine._submit_decision(
            outer['owner'], outer['id'],
            ['accept' if accept_effect else 'decline'],
        )
    return {
        'outer_kind': (outer or {}).get('kind'),
        'fp': engine.state['players'][owner]['fp'],
        'skip_get': bool(
            (engine.engine_state.get('skip_get') or {}).get(owner)
        ),
        'resolved': _st2_resolution_count(engine, 'cb02-at-035-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_035_restriction_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    source_zone='battle', numbered_negated=False, expire_turn=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    plain = _card(
        'REVIEW-CB02-AT-035-PLAIN', owner,
        f'{owner}-shootingstar-plain',
    )
    plain.update({'name': '일반 기술', 'text': '일반 효과', 'face_up': False})
    saintess_card = _card(
        'REVIEW-CB02-AT-035-SAINTESS', owner,
        f'{owner}-shootingstar-saintess',
    )
    saintess_card.update({
        'name': '성녀 기술', 'text': '①[[state:saintess]]: 검토 효과',
        'face_up': False,
    })
    opponent_plain = _card(
        'REVIEW-CB02-AT-035-OPPONENT-PLAIN', other,
        f'{other}-shootingstar-plain',
    )
    opponent_plain.update({'name': '상대 일반 기술', 'text': '일반 효과'})
    engine.state['players'][owner]['zones']['hand'].extend([
        copy.deepcopy(plain), copy.deepcopy(saintess_card),
    ])
    for card in (plain, saintess_card, opponent_plain):
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    blocked_plain = engine._rule_blocked('use_card', owner, plain)
    blocked_saintess = engine._rule_blocked(
        'use_card', owner, saintess_card,
    )
    blocked_opponent = engine._rule_blocked(
        'use_card', other, opponent_plain,
    )
    after_turn_blocked = None
    if expire_turn:
        engine._complete_turn()
        after_turn_blocked = engine._rule_blocked('use_card', owner, plain)
    return {
        'plain_blocked': blocked_plain,
        'saintess_blocked': blocked_saintess,
        'opponent_blocked': blocked_opponent,
        'after_turn_blocked': after_turn_blocked,
        'modifier_count': sum(
            item.get('kind') == 'use_card'
            and item.get('player') == owner
            for item in engine.engine_state.get('replacements') or []
        ),
        'resolved': _st2_resolution_count(engine, 'cb02-at-035-n3'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb02_at_035_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB02-AT-035':
        return None
    qna_ids = [384, 406, 641, 677, 678]
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    catch = by_id.get('cb02-at-035-n1')
    fp = by_id.get('cb02-at-035-n2')
    restriction = by_id.get('cb02-at-035-n3')
    valid = bool(
        not extra_root
        and set(by_id) == {
            'cb02-at-035-n1', 'cb02-at-035-n2', 'cb02-at-035-n3',
        }
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == qna_ids
            for ability in abilities
        )
        and catch and catch.get('kind') == 'effect'
        and catch.get('mode') == 'optional'
        and catch.get('timing') == 'guard'
        and catch.get('active_zones') == ['hand']
        and catch.get('trigger') == {
            'event': 'guard', 'events': ['guard', 'clash'],
        }
        and catch.get('condition') == {
            'op': 'all', 'conditions': [
                {
                    'op': 'has_state', 'player': {'controller': True},
                    'state': 'saintess',
                },
                {
                    'op': 'equals', 'left': 'context.source_card.face_up',
                    'right': False,
                },
            ],
        }
        and catch.get('recheck_condition') is True
        and catch.get('effects') == [
            {
                'op': 'reveal',
                'card_instance_id': {
                    'path': 'context.source_card_instance_id',
                },
            },
            {
                'op': 'grant_catch', 'player': {'controller': True},
                'allow_zones': ['hand'], 'source_only': True,
            },
        ]
        and fp and fp.get('kind') == 'effect'
        and fp.get('mode') == 'optional'
        and fp.get('timing') == 'hit_counter'
        and fp.get('active_zones') == ['battle']
        and fp.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and fp.get('effects') == [
            {'op': 'skip_get', 'player': {'controller': True}},
            {
                'op': 'change_fp', 'player': {'controller': True},
                'amount': 2,
            },
        ]
        and restriction and restriction.get('kind') == 'effect'
        and restriction.get('mode') == 'mandatory'
        and restriction.get('timing') == 'after_use'
        and restriction.get('active_zones') == ['battle']
        and restriction.get('trigger') == {'event': 'after_use'}
        and restriction.get('effects') == [{
            'op': 'prevent', 'kind': 'use_card',
            'player': {'controller': True}, 'duration': 'turn',
            'where': {'text_not_contains': '[[state:saintess]]'},
        }]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB02-AT-035', 'name': '슈팅스타', 'type': '공격',
            'frame': 8, 'damage': 200, 'pos': '상단', 'body': '',
            'special': None, 'hit': '3', 'guard': '-3', 'counter': '9',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 9, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb02-at-035', False,
                reason='슈팅스타의 공개 캐치·Get 스킵·성녀 사용 제한 정의가 일치하지 않습니다.',
            )], 'CB02-AT-035 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    catch_scenarios = _st2_scenarios(
        _run_cb02_at_035_catch_scenario, definition, card_snapshot,
        (
            ('owner-p1-reveals-and-gains-source-only-catch', 'p1', {}, {
                'outer_kind': 'optional_effect', 'face_up': True,
                'grant_count': 1,
                'catch_option_ids': ['p1-CB02-AT-035-source'],
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-reveals-on-clash-and-gains-catch', 'p2', {
                'event_type': 'clash',
            }, {'face_up': True, 'grant_count': 1,
                'catch_option_ids': ['p2-CB02-AT-035-source'],
                'resolved': 1}),
            ('declining-keeps-card-hidden-and-grants-no-catch', 'p1', {
                'accept_effect': False,
            }, {'face_up': False, 'grant_count': 0, 'resolved': 0}),
            ('already-revealed-card-cannot-be-revealed-again-qna678', 'p2', {
                'initially_revealed': True,
            }, {'outer_kind': None, 'face_up': True,
                'grant_count': 0, 'resolved': 0}),
            ('saintess-state-is-required', 'p1', {
                'saintess': False,
            }, {'outer_kind': None, 'face_up': False,
                'grant_count': 0, 'resolved': 0}),
            ('wrong-event-does-not-offer-catch', 'p2', {
                'event_type': 'hit',
            }, {'outer_kind': None, 'grant_count': 0, 'resolved': 0}),
            ('source-outside-hand-is-inactive', 'p1', {
                'source_zone': 'list',
            }, {'outer_kind': None, 'grant_count': 0, 'resolved': 0}),
            ('numbered-negation-disables-reveal-catch', 'p2', {
                'numbered_negated': True,
            }, {'outer_kind': None, 'grant_count': 0, 'resolved': 0}),
        ),
    )
    fp_scenarios = _st2_scenarios(
        _run_cb02_at_035_fp_scenario, definition, card_snapshot,
        (
            ('owner-p1-hit-skips-get-and-gains-two-fp', 'p1', {}, {
                'outer_kind': 'optional_effect', 'fp': 3, 'skip_get': True,
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-counter-skips-get-and-gains-two-fp', 'p2', {
                'event_type': 'counter', 'owner_fp': 4,
            }, {'fp': 6, 'skip_get': True, 'resolved': 1}),
            ('already-skipped-get-can-be-skipped-again-qna677', 'p1', {
                'already_skipped': True,
            }, {'fp': 3, 'skip_get': True, 'resolved': 1}),
            ('declining-does-not-change-fp-or-get', 'p2', {
                'accept_effect': False,
            }, {'fp': 1, 'skip_get': False, 'resolved': 0}),
            ('wrong-event-does-not-offer-effect', 'p1', {
                'event_type': 'guard',
            }, {'outer_kind': None, 'fp': 1, 'skip_get': False,
                'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'outer_kind': None, 'fp': 1, 'resolved': 0}),
            ('numbered-negation-disables-fp-effect', 'p1', {
                'numbered_negated': True,
            }, {'outer_kind': None, 'fp': 1, 'skip_get': False,
                'resolved': 0}),
        ),
    )
    restriction_scenarios = _st2_scenarios(
        _run_cb02_at_035_restriction_scenario, definition, card_snapshot,
        (
            ('owner-p1-can-only-use-saintess-techniques-this-turn', 'p1', {}, {
                'plain_blocked': True, 'saintess_blocked': False,
                'opponent_blocked': False, 'modifier_count': 1,
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-can-only-use-saintess-techniques-this-turn', 'p2', {}, {
                'plain_blocked': True, 'saintess_blocked': False,
                'opponent_blocked': False, 'resolved': 1,
            }),
            ('restriction-expires-at-turn-end', 'p1', {
                'expire_turn': True,
            }, {'plain_blocked': True, 'after_turn_blocked': False,
                'modifier_count': 0, 'resolved': 1}),
            ('wrong-event-does-not-create-restriction', 'p2', {
                'event_type': 'use',
            }, {'plain_blocked': False, 'modifier_count': 0,
                'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p1', {
                'source_zone': 'hand',
            }, {'plain_blocked': False, 'modifier_count': 0,
                'resolved': 0}),
            ('numbered-negation-disables-restriction', 'p2', {
                'numbered_negated': True,
            }, {'plain_blocked': False, 'modifier_count': 0,
                'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            catch['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
        ),
        AbilityReview(
            fp['id'], all(item['passed'] for item in fp_scenarios),
            fp_scenarios,
        ),
        AbilityReview(
            restriction['id'],
            all(item['passed'] for item in restriction_scenarios),
            restriction_scenarios,
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '슈팅스타의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_cb02_ps_001_scenario(
    definition, card_snapshot, owner, *, foreign_character_id=9,
    foreign_type='공격', foreign_ultimate=False, cleanup=False,
    numbered_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    trait = _sandbox_source_snapshot(card_snapshot)
    trait.update({
        'instance_id': f'{owner}-CB02-PS-001-source',
        'owner': owner, 'kind': 'card', 'type': '특성',
        'character_id': 15, 'face_up': True,
    })
    if numbered_negated:
        trait['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-CHIMERA-OPPONENT', other,
        f'{other}-chimera-opponent',
    )
    foreign = _card(
        'REVIEW-CHIMERA-FOREIGN', owner,
        f'{owner}-chimera-imported',
    )
    foreign.update({
        'name': '도입 검토 기술', 'type': foreign_type,
        'character_id': foreign_character_id,
        'ultimate': bool(foreign_ultimate), 'face_up': True,
    })
    if foreign_type != '공격':
        foreign.update({'frame': None, 'damage': None, 'pos': None})
    state = _state(trait, opposing, owner, source_zone='passive')
    state['players'][owner]['character'] = {'id': 15}
    state['players'][other]['character'] = {'id': 2}
    state['players'][owner]['zones']['battle'].append(copy.deepcopy(foreign))
    foreign_definition = {
        'schema_version': 1, 'reviewed': True,
        'source_refs': {'rulebook_pages': [48], 'qna_ids': []},
        'abilities': [{
            'id': 'review-foreign-use', 'kind': 'effect',
            'mode': 'mandatory', 'timing': 'use',
            'visibility': 'public', 'active_zones': ['battle'],
            'trigger': {'event': 'use'},
            'effects': [{
                'op': 'change_fp', 'player': {'controller': True},
                'amount': 5,
            }],
        }],
    }
    deck_rules = copy.deepcopy(definition.get('deck_rules') or {})
    ruleset = {
        'version': AUTOMATIC_SCENARIO_VERSION,
        'characters': {
            '2': {'id': 2, 'key': 'opponent'},
            str(foreign_character_id): {
                'id': foreign_character_id,
                'key': f'foreign-{foreign_character_id}',
            },
            '15': {'id': 15, 'key': 'chimera', 'deck_rules': deck_rules},
        },
        'cards': {
            trait['code']: {
                **copy.deepcopy(trait),
                'effect_definition': copy.deepcopy(definition),
            },
            opposing['code']: {
                **copy.deepcopy(opposing),
                'effect_definition': _st2_no_effect_definition(),
            },
            foreign['code']: {
                **copy.deepcopy(foreign),
                'effect_definition': foreign_definition,
            },
        },
    }
    engine = AutomaticGameEngine(
        state, ruleset,
        seed=(
            f'cb02-ps-001:{owner}:{foreign_character_id}:{foreign_type}:'
            f'{foreign_ultimate}:{cleanup}:{numbered_negated}'
        ),
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    live_foreign = engine._find_card(foreign['instance_id'])
    before_fp = engine.state['players'][owner]['fp']
    engine._fire('use', {
        'controller': owner,
        'source_card_instance_id': foreign['instance_id'],
        'source_card': copy.deepcopy(live_foreign),
        'source_only_event': True,
    })
    fp_delta = engine.state['players'][owner]['fp'] - before_fp
    if cleanup:
        pipeline = {
            'kind': 'battle_cleanup', 'stage': 'cards',
            'used_order': [(owner, foreign['instance_id'], 'hand')],
            'index': 0, 'defense_over': False,
        }
        engine._advance_cleanup_pipeline(pipeline)
    live_foreign = engine._find_card(foreign['instance_id'])
    return {
        'trait_zone': engine._find_location(trait['instance_id'])[1],
        'original_character_id': (live_foreign or {}).get(
            'original_character_id'
        ),
        'character_id': (live_foreign or {}).get('character_id'),
        'character_key': (live_foreign or {}).get('character_key'),
        'effects_negated': bool((live_foreign or {}).get('effects_negated')),
        'break_after_use': bool((live_foreign or {}).get('break_after_use')),
        'fp_delta': fp_delta,
        'foreign_zone': engine._find_location(foreign['instance_id'])[1],
        'main_min': (deck_rules.get('main_size') or {}).get('min'),
        'main_max': (deck_rules.get('main_size') or {}).get('max'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb02_ps_001_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB02-PS-001':
        return None
    qna_ids = [688]
    abilities = definition.get('abilities') or []
    trait = abilities[0] if len(abilities) == 1 else None
    deck_rules = {
        'main_size': {'min': 30, 'max': 30},
        'other_character_cards': {
            'allowed_types': ['공격'], 'exclude_ultimate': True,
            'exclude_character_ids': [1], 'max_per_character': 3,
            'treat_as_own_character': True, 'negate_effects': True,
            'break_after_use': True,
        },
    }
    valid = bool(
        extra_root == {'deck_rules'} and trait
        and (definition.get('source_refs') or {}).get('qna_ids') == qna_ids
        and (trait.get('source_refs') or {}).get('qna_ids') == qna_ids
        and definition.get('deck_rules') == deck_rules
        and trait.get('id') == 'cb02-ps-001-function'
        and trait.get('kind') == 'function'
        and trait.get('mode') == 'continuous'
        and trait.get('timing') == 'function'
        and trait.get('active_zones') == ['passive']
        and not trait.get('trigger')
        and trait.get('effects') == [{
            'op': 'static_rule', 'rules': ['deck_rules'],
        }]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB02-PS-001', 'name': '하요트 하 코데쉬',
            'type': '특성', 'frame': None, 'damage': None,
            'pos': None, 'body': '', 'special': None,
            'hit': '0', 'guard': '0', 'counter': '0',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 15, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb02-ps-001-function', False,
                reason='하요트 하 코데쉬의 30장 편성·도입 기술 변환 정의가 일치하지 않습니다.',
            )], 'CB02-PS-001 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    scenarios = _st2_scenarios(
        _run_cb02_ps_001_scenario, definition, card_snapshot,
        (
            ('owner-p1-imported-attack-becomes-negated-chimera-technique', 'p1', {}, {
                'trait_zone': 'passive', 'original_character_id': 9,
                'character_id': 15, 'character_key': 'chimera',
                'effects_negated': True, 'break_after_use': True,
                'fp_delta': 0, 'main_min': 30, 'main_max': 30,
                'pending': False,
            }),
            ('owner-p2-imported-attack-becomes-negated-chimera-technique', 'p2', {
                'foreign_character_id': 11,
            }, {'original_character_id': 11, 'character_id': 15,
                'effects_negated': True, 'break_after_use': True,
                'fp_delta': 0}),
            ('imported-attack-breaks-during-use-cleanup', 'p1', {
                'cleanup': True,
            }, {'foreign_zone': 'break', 'effects_negated': True,
                'break_after_use': True}),
            ('foreign-defense-is-not-importable', 'p2', {
                'foreign_type': '수비',
            }, {'original_character_id': None, 'character_id': 9,
                'effects_negated': False, 'break_after_use': False,
                'fp_delta': 5}),
            ('foreign-ultimate-attack-is-not-importable', 'p1', {
                'foreign_ultimate': True,
            }, {'original_character_id': None, 'character_id': 9,
                'effects_negated': False, 'break_after_use': False,
                'fp_delta': 5}),
            ('neutral-mark-attack-is-not-treated-as-imported', 'p2', {
                'foreign_character_id': 1,
            }, {'original_character_id': None, 'character_id': 1,
                'effects_negated': False, 'break_after_use': False,
                'fp_delta': 5}),
            ('own-character-attack-is-not-rewritten', 'p1', {
                'foreign_character_id': 15,
            }, {'original_character_id': None, 'character_id': 15,
                'effects_negated': False, 'break_after_use': False,
                'fp_delta': 5}),
            ('numbered-negation-does-not-disable-trait-deck-rule', 'p2', {
                'numbered_negated': True, 'foreign_character_id': 14,
            }, {'original_character_id': 14, 'character_id': 15,
                'effects_negated': True, 'break_after_use': True,
                'fp_delta': 0}),
        ),
    )
    review = AbilityReview(
        trait['id'], all(item['passed'] for item in scenarios), scenarios,
    )
    passed = bool(review.passed and len(review.scenarios) >= 3)
    return DefinitionReview(
        passed, False, [review],
        '' if passed else '하요트 하 코데쉬의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_cb02_at_036_unavoidable_scenario(
    definition, card_snapshot, owner, *, guardian=True,
    source_zone='battle', negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated, opponent_type='수비',
    )
    opposing['g_top'] = '회피'
    if guardian:
        engine.set_passive(owner, 'guardian', value=True)
    engine._refresh_continuous_rules()
    result = engine._attack_vs_defense(
        source, opposing, owner, 'p2' if owner == 'p1' else 'p1',
    )
    return {
        'result': list(result),
        'replacement_count': sum(
            replacement.get('kind') == 'dodge'
            and replacement.get('player') != owner
            for replacement in engine.engine_state.get('replacements') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_036_discard_scenario(
    definition, card_snapshot, owner, *, candidate_count=2,
    select_index=0, accept_effect=True, source_zone='battle',
    event_type='after_use', negated=False,
    protect_initial_index=None, protect_after_choice=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated,
    )
    candidates = []
    protected_definition = _dfr_at_027_protected_definition()
    no_effect = _st2_no_effect_definition()
    for index in range(candidate_count):
        card = _card(
            f'REVIEW-CB02-AT-036-SAINTESS-{index + 1}', owner,
            f'{owner}-discipline-saintess-{index + 1}',
        )
        card.update({
            'name': f'성녀 효과 기술 {index + 1}',
            'type': '공격', 'text': '①[[state:saintess]]: 검증 효과',
            'frame': 5 + index, 'damage': 400, 'face_up': False,
        })
        candidates.append(card)
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': (
                copy.deepcopy(protected_definition)
                if protect_initial_index == index else copy.deepcopy(no_effect)
            ),
        }
    wrong = _card(
        'REVIEW-CB02-AT-036-WRONG', owner,
        f'{owner}-discipline-wrong-hand',
    )
    wrong.update({
        'name': '성녀 효과 없는 기술', 'type': '공격',
        'text': '일반 효과', 'frame': 4, 'damage': 400,
        'face_up': False,
    })
    engine.ruleset['cards'][wrong['code']] = {
        **copy.deepcopy(wrong), 'effect_definition': copy.deepcopy(no_effect),
    }
    engine.state['players'][owner]['zones']['hand'] = [
        *(copy.deepcopy(card) for card in candidates), copy.deepcopy(wrong),
    ]
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    outer = copy.deepcopy(engine.engine_state.get('pending_decision'))
    choice = None
    option_ids = []
    selected_id = (
        candidates[select_index]['instance_id']
        if 0 <= select_index < len(candidates) else None
    )
    if outer and outer.get('kind') == 'optional_effect':
        engine._submit_decision(
            outer.get('owner'), outer['id'],
            ['accept' if accept_effect else 'decline'],
        )
        choice = copy.deepcopy(engine.engine_state.get('pending_decision'))
    if choice and choice.get('kind') == 'effect_choice':
        option_ids = [
            str(option.get('id')) for option in choice.get('options') or []
        ]
        if selected_id not in option_ids:
            selected_id = option_ids[0] if option_ids else None
        if protect_after_choice and selected_id:
            selected_card = engine._find_card(selected_id)
            if selected_card:
                engine.ruleset['cards'][selected_card['code']][
                    'effect_definition'
                ] = copy.deepcopy(protected_definition)
        engine._submit_decision(
            choice.get('owner'), choice['id'],
            [selected_id] if selected_id else [],
        )
    catch_card = _card(
        'REVIEW-CB02-AT-036-CATCH', other,
        f'{other}-discipline-catch',
    )
    selected_zone = (
        engine._find_location(selected_id)[1] if selected_id else None
    )
    return {
        'outer_kind': (outer or {}).get('kind'),
        'choice_kind': (choice or {}).get('kind'),
        'option_ids': option_ids, 'option_count': len(option_ids),
        'wrong_id': wrong['instance_id'], 'selected_id': selected_id,
        'selected_zone': selected_zone,
        'skip_get': bool(
            (engine.engine_state.get('skip_get') or {}).get(owner)
        ),
        'opponent_catch_blocked': engine._rule_blocked(
            'catch', other, catch_card, source,
        ),
        'resolved': _st2_resolution_count(engine, 'cb02-at-036-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb02_at_036_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB02-AT-036':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    unavoidable = by_id.get('cb02-at-036-n1')
    discard = by_id.get('cb02-at-036-n2')
    selected_key = 'cb02_at_036_saintess_discard'
    discarded_key = 'cb02_at_036_saintess_discarded'
    selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['hand'], 'min': 1, 'max': 1,
        'where': {
            'is_technique': True,
            'text_contains': '[[state:saintess]]',
        },
        'as_operation': 'discard',
    }
    expected_discard = [{
        'op': 'request_choice', 'player': {'controller': True},
        'prompt': '버릴 성녀 효과 기술을 선택하세요.',
        'selector': copy.deepcopy(selector),
        'selection_key': selected_key, 'default': [],
        'then': [
            {
                'op': 'discard', 'selection_key': selected_key,
                'result_key': discarded_key,
            },
            {
                'op': 'conditional',
                'condition': {
                    'op': 'gte',
                    'left': {
                        'op': 'selection_count',
                        'selection_key': discarded_key,
                    },
                    'right': 1,
                },
                'then': [
                    {
                        'op': 'skip_get',
                        'player': {'controller': True},
                    },
                    {
                        'op': 'prevent', 'kind': 'catch',
                        'player': {'opponent': True}, 'duration': 'turn',
                    },
                ],
                'else': [],
            },
        ],
    }]
    valid = bool(
        not extra_root and set(by_id) == {
            'cb02-at-036-n1', 'cb02-at-036-n2',
        }
        and not (definition.get('source_refs') or {}).get('qna_ids')
        and unavoidable and unavoidable.get('kind') == 'effect'
        and unavoidable.get('mode') == 'continuous'
        and unavoidable.get('timing') == 'function'
        and unavoidable.get('active_zones') == ['battle']
        and not unavoidable.get('trigger')
        and unavoidable.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'guardian',
        }
        and unavoidable.get('effects') == [{
            'op': 'prevent', 'kind': 'dodge',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and discard and discard.get('kind') == 'effect'
        and discard.get('mode') == 'optional'
        and discard.get('timing') == 'after_use'
        and discard.get('active_zones') == ['battle']
        and discard.get('trigger') == {'event': 'after_use'}
        and discard.get('availability_selector') == selector
        and discard.get('recheck_condition') is True
        and discard.get('effects') == expected_discard
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB02-AT-036', 'name': '몰아치는 규율',
            'type': '공격', 'frame': 12, 'damage': 500,
            'pos': '상단', 'body': '손', 'special': None,
            'hit': '5', 'guard': '-7', 'counter': '7',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 9, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb02-at-036', False,
                reason='몰아치는 규율의 가디언 회피 금지·성녀 버림 선택 정의가 일치하지 않습니다.',
            )], 'CB02-AT-036 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    unavoidable_scenarios = _st2_scenarios(
        _run_cb02_at_036_unavoidable_scenario, definition, card_snapshot,
        (
            ('owner-p1-guardian-prevents-top-dodge', 'p1', {}, {
                'result': ['hit', 'failed_defense'],
                'replacement_count': 1, 'pending': False,
            }),
            ('owner-p2-guardian-prevents-top-dodge', 'p2', {}, {
                'result': ['hit', 'failed_defense'],
                'replacement_count': 1,
            }),
            ('without-guardian-opponent-dodges', 'p1', {
                'guardian': False,
            }, {'result': ['opponent_dodge', 'dodge'],
                'replacement_count': 0}),
            ('numbered-negation-disables-unavoidable-effect', 'p2', {
                'negated': True,
            }, {'result': ['opponent_dodge', 'dodge'],
                'replacement_count': 0}),
            ('source-outside-battle-does-not-prevent-dodge', 'p1', {
                'source_zone': 'hand',
            }, {'result': ['opponent_dodge', 'dodge'],
                'replacement_count': 0}),
        ),
    )
    discard_scenarios = _st2_scenarios(
        _run_cb02_at_036_discard_scenario, definition, card_snapshot,
        (
            ('owner-p1-selects-first-saintess-and-applies-followups', 'p1', {}, {
                'outer_kind': 'optional_effect',
                'choice_kind': 'effect_choice', 'option_count': 2,
                'selected_zone': 'list', 'skip_get': True,
                'opponent_catch_blocked': True,
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-selects-second-saintess-and-applies-followups', 'p2', {
                'select_index': 1,
            }, {'selected_zone': 'list', 'skip_get': True,
                'opponent_catch_blocked': True, 'resolved': 1}),
            ('declining-effect-keeps-card-and-rules-unchanged', 'p1', {
                'accept_effect': False,
            }, {'choice_kind': None, 'selected_zone': 'hand',
                'skip_get': False, 'opponent_catch_blocked': False,
                'resolved': 0}),
            ('empty-saintess-candidate-set-offers-no-effect', 'p2', {
                'candidate_count': 0,
            }, {'outer_kind': None, 'choice_kind': None,
                'skip_get': False, 'resolved': 0}),
            ('initially-protected-card-is-not-an-option', 'p1', {
                'candidate_count': 1, 'protect_initial_index': 0,
            }, {'outer_kind': None, 'option_count': 0,
                'skip_get': False, 'resolved': 0}),
            ('late-protection-prevents-discard-and-followups', 'p2', {
                'candidate_count': 1, 'protect_after_choice': True,
            }, {'selected_zone': 'hand', 'skip_get': False,
                'opponent_catch_blocked': False, 'resolved': 1}),
            ('wrong-event-does-not-offer-choice', 'p1', {
                'event_type': 'use',
            }, {'outer_kind': None, 'skip_get': False, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'outer_kind': None, 'skip_get': False, 'resolved': 0}),
            ('numbered-negation-does-not-offer-choice', 'p1', {
                'negated': True,
            }, {'outer_kind': None, 'skip_get': False, 'resolved': 0}),
        ),
    )
    for scenario in discard_scenarios:
        scenario['passed'] = bool(
            scenario['passed']
            and scenario.get('wrong_id') not in scenario.get('option_ids', [])
        )
    reviews = [
        AbilityReview(
            unavoidable['id'],
            all(item['passed'] for item in unavoidable_scenarios),
            unavoidable_scenarios,
        ),
        AbilityReview(
            discard['id'], all(item['passed'] for item in discard_scenarios),
            discard_scenarios,
        ),
    ]
    passed = all(item.passed and len(item.scenarios) >= 3 for item in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '몰아치는 규율의 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _cb02_at_038_rin_card(owner, index, *, frame=6, character='rin'):
    card = _card(
        f'REVIEW-CB02-AT-038-RIN-{index}', owner,
        f'{owner}-rakshasa-break-{index}',
    )
    card.update({
        'name': f'린 브레이크 기술 {index}',
        'type': '공격', 'character_key': character,
        'frame': frame, 'damage': 900, 'pos': '상단',
        'body': '손', 'hit': '3', 'guard': '-3', 'counter': '4',
        'face_up': True,
    })
    return card


def _run_cb02_at_038_speed_scenario(
    definition, card_snapshot, owner, *, rin_count=0,
    wrong_count=0, event_type='before_judgment',
    source_zone='battle', negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated,
    )
    cards = [
        _cb02_at_038_rin_card(owner, index + 1)
        for index in range(rin_count)
    ]
    cards.extend(
        _cb02_at_038_rin_card(
            owner, rin_count + index + 1, character='other',
        )
        for index in range(wrong_count)
    )
    engine.state['players'][owner]['zones']['break'] = copy.deepcopy(cards)
    for card in cards:
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    live_source = engine._find_card(source['instance_id']) or source
    return {
        'speed': engine.card_stat(live_source, 'frame', owner),
        'resolved': _st2_resolution_count(engine, 'cb02-at-038-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb02_at_038_counter_scenario(
    definition, card_snapshot, owner, *, eligible_count=2,
    event_type='counter', source_zone='battle', negated=False,
    extend_combo=False, finish_combo=False, combo_owner='self',
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated,
    )
    eligible = [
        _cb02_at_038_rin_card(
            owner, index + 1, frame=4 + index,
        )
        for index in range(eligible_count)
    ]
    too_fast = _cb02_at_038_rin_card(
        owner, 90, frame=9,
    )
    wrong_character = _cb02_at_038_rin_card(
        owner, 91, frame=7, character='other',
    )
    defense = _cb02_at_038_rin_card(owner, 92, frame=5)
    defense.update({'type': '수비', 'damage': None, 'frame': None})
    break_cards = [*eligible, too_fast, wrong_character, defense]
    engine.state['players'][owner]['zones']['break'] = copy.deepcopy(
        break_cards
    )
    for card in break_cards:
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }
    token = {
        'instance_id': f'{owner}-rakshasa-battle-token',
        'owner': owner, 'kind': 'token', 'type': '토큰',
        'code': 'REVIEW-CB02-AT-038-TOKEN', 'name': '배틀 토큰',
        'frame': None, 'damage': None, 'pos': '', 'body': '',
        'hit': '0', 'guard': '0', 'counter': '0', 'face_up': True,
    }
    engine.state['players'][owner]['zones']['battle'].append(
        copy.deepcopy(token)
    )
    engine.ruleset['cards'][token['code']] = {
        **copy.deepcopy(token),
        'effect_definition': _st2_no_effect_definition(),
    }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_only_event': True,
    })
    if extend_combo:
        engine.add_modifier({
            'op': 'modify_combo', 'controller': owner, 'player': owner,
            'max_combo': 5, 'duration': 'turn',
            'source': 'review-combo-extension',
        })
    combo = {
        'owner': owner, 'source': source['instance_id'],
        'used': [], 'next_penalty': 100, 'last_speed': 10,
        'max_combo': 3, 'proposal_submitted': False,
    }
    actions = engine._combo_actions(owner, combo)
    sequences = []
    for action in actions:
        payload = action.get('payload') or {}
        ids = payload.get('card_instance_ids')
        if not isinstance(ids, list):
            instance_id = payload.get('card_instance_id')
            ids = [instance_id] if instance_id else []
        sequences.append(ids)
    eligible_ids = [card['instance_id'] for card in eligible]
    offered_ids = {
        instance_id for sequence in sequences for instance_id in sequence
    }
    pair_offered = bool(
        len(eligible_ids) >= 2
        and any(
            set(sequence) == set(eligible_ids[:2])
            for sequence in sequences if len(sequence) == 2
        )
    )
    before_finish = {
        'source_zone': engine._find_location(source['instance_id'])[1],
        'opponent_zone': engine._find_location(opposing['instance_id'])[1],
        'token_zone': engine._find_location(token['instance_id'])[1],
    }
    if finish_combo:
        ending_owner = owner if combo_owner == 'self' else other
        engine._fire('combo_end', {
            'controller': ending_owner, 'combo_owner': ending_owner,
        })
    return {
        'eligible_offered_count': sum(
            instance_id in offered_ids for instance_id in eligible_ids
        ),
        'pair_offered': pair_offered,
        'maximum_sequence_length': max(
            [len(sequence) for sequence in sequences] or [0]
        ),
        'too_fast_offered': too_fast['instance_id'] in offered_ids,
        'wrong_character_offered': (
            wrong_character['instance_id'] in offered_ids
        ),
        'defense_offered': defense['instance_id'] in offered_ids,
        'modifier_count': sum(
            modifier.get('usage_key') == 'cb02-at-038-break-combo'
            for modifier in engine.engine_state.get('modifiers') or []
        ),
        'scheduled': len(engine.engine_state.get('scheduled') or []),
        'source_zone_before_finish': before_finish['source_zone'],
        'source_zone': engine._find_location(source['instance_id'])[1],
        'opponent_zone': engine._find_location(opposing['instance_id'])[1],
        'token_zone': engine._find_location(token['instance_id'])[1],
        'resolved': _st2_resolution_count(engine, 'cb02-at-038-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


