def _run_cb02_at_005_catch_scenario(
    definition, card_snapshot, owner, *, max_speed=7,
    selection=None, negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    source = _sandbox_source_snapshot(card_snapshot)
    source.update({
        'instance_id': f'{owner}-low-kick', 'owner': owner,
        'kind': 'card', 'face_up': False,
    })
    if negated:
        source['numbered_effects_negated'] = True
    opposing = _card(
        'REVIEW-CB02-AT-005-OPPONENT', other,
        f'{other}-low-kick-opponent',
    )
    opposing.update({'frame': 6, 'damage': 300, 'pos': '중단'})
    state = _state(source, opposing, owner, source_zone='hand')
    state['phase'] = 'battle'
    no_effect = _st2_no_effect_definition()
    engine = AutomaticGameEngine(
        state, {
            'version': AUTOMATIC_SCENARIO_VERSION,
            'cards': {
                source['code']: {
                    **copy.deepcopy(source),
                    'effect_definition': copy.deepcopy(definition),
                },
                opposing['code']: {
                    **copy.deepcopy(opposing),
                    'effect_definition': no_effect,
                },
            },
        },
        seed=f'cb02-at-005-catch:{owner}:{max_speed}:{selection}:{negated}',
        now=datetime(2026, 6, 1, tzinfo=timezone.utc),
    )
    catch = {
        'owner': owner, 'source': 'fp', 'allow_zones': ['hand'],
        'max_speed': max_speed,
    }
    options = [
        option for option in engine._legal_catch_options(owner, catch)
        if (option.get('card') or {}).get('instance_id')
        == source['instance_id']
    ]
    variants = sorted(
        [{
            'rule_index': option.get('catch_rule_index'),
            'fixed_speed': option.get('fixed_speed'),
        } for option in options],
        key=lambda item: (
            item.get('fixed_speed') is not None,
            int(item.get('fixed_speed') or 0),
        ),
    )
    result = {
        'variants': variants,
        'rule_count': len(engine._catch_rules(
            owner, engine._find_card(source['instance_id']),
        )),
        'played': False, 'resolved': 0, 'hit_changed_to': None,
        'damage': 0,
    }
    desired_rule = None if selection == 'printed' else 0
    selected = next((
        option for option in options
        if selection in {'printed', 'optional'}
        and option.get('catch_rule_index') == desired_rule
    ), None)
    if selected is None:
        return result
    hp_before = int(engine.state['players'][other]['hp'])
    engine.engine_state.update({
        'catch': copy.deepcopy(catch), 'catch_queue': [],
        'granted_catches': [], 'catch_fp_history': [], 'step': 'catch',
    })
    engine._play_catch(
        owner, source['instance_id'],
        catch_rule_index=selected.get('catch_rule_index'),
    )
    pipeline = engine.engine_state.get('pipeline') or {}
    result.update({
        'played': True,
        'selected_rule_index': pipeline.get('catch_rule_index'),
        'selected_fixed_speed': pipeline.get('fixed_speed'),
        'effective_speed': engine.card_stat(
            engine._find_card(source['instance_id']), 'frame', owner,
            include_fp=False,
        ),
    })
    engine._continue()
    hit_events = [
        event.get('payload') or {}
        for event in engine.events
        if event.get('type') == 'judgment_modified'
        and (event.get('payload') or {}).get('field') == 'hit'
        and (event.get('payload') or {}).get('card_instance_id')
        == source['instance_id']
    ]
    result.update({
        'resolved': _st2_resolution_count(engine, 'cb02-at-005-n1'),
        'hit_changed_to': hit_events[-1].get('after') if hit_events else None,
        'damage': hp_before - int(engine.state['players'][other]['hp']),
        'source_zone': engine._find_location(source['instance_id'])[1],
        'pending': bool(engine.engine_state.get('pending_decision')),
    })
    return result


