def _run_cb03_at_010_defense_scenario(
    definition, card_snapshot, owner, *, opponent_speed=9,
    opponent_fp=0, negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, numbered_negated=negated,
        source_special='하단 회피', opponent_frame=opponent_speed,
        opponent_pos='하단', opponent_fp=opponent_fp,
    )
    return {
        'allowed': bool(
            _special_result(source, '하단') == 'dodge'
            and engine._defense_judgment_allowed(
                source, opposing, 'dodge', other,
            )
        ),
        'reference_speed': engine.card_stat(
            opposing, 'frame', other, include_fp=False,
        ),
        'final_speed': engine.card_stat(
            opposing, 'frame', other, include_fp=True,
        ),
    }


def _run_cb03_at_010_effect_scenario(
    definition, card_snapshot, owner, *, ability_id, event_type,
    source_zone='battle', negated=False, high_tension=False,
    initial_fp=0,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=negated, owner_fp=initial_fp,
    )
    if high_tension:
        engine.set_passive(owner, 'high_tension', value=True)
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    return {
        'damage': engine.card_stat(source, 'damage', owner),
        'fp': int(engine.state['players'][owner].get('fp') or 0),
        'resolved': _st2_resolution_count(engine, ability_id),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


