    if str((card_snapshot or {}).get('code') or '') != 'CB03-AT-012':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    unavoidable = by_id.get('cb03-at-012-function')
