def _run_crs_at_053_combo_cap_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    source_zone='battle', numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.add_modifier({
        'op': 'modify_combo', 'controller': owner, 'player': owner,
        'source': 'review-crs-at-053-extension',
        'max_combo': 6, 'duration': 'game',
    })
    engine._fire(event_type, {
        'controller': owner, 'event_controller': owner,
        'source_card': source,
        'source_card_instance_id': source['instance_id'],
        'opponent_card': opposing, 'source_only_event': True,
    })
    combo = {'owner': owner, 'used': [], 'max_combo': 3}
    active_maximum = engine._combo_maximum(owner, combo)
    cap_count = sum(
        modifier.get('op') == 'modify_combo'
        and modifier.get('player') == owner
        and modifier.get('max_combo_cap') == 3
        and modifier.get('duration') == 'turn'
        for modifier in engine.engine_state.get('modifiers') or []
    )
    engine._expire_modifiers('turn')
    after_expiry_maximum = engine._combo_maximum(owner, combo)
    return {
        'active_maximum': active_maximum,
        'after_expiry_maximum': after_expiry_maximum,
        'cap_count': cap_count,
        'resolved': _st2_resolution_count(engine, 'crs-at-053-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


