def _run_pmp_at_051_scenario(
    definition, card_snapshot, owner, *, ability='combo', event_type=None,
    opponent_type='공격', opponent_hit='3', opponent_counter='4',
    opponent_present=True, source_zone='battle', numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, opponent_type=opponent_type,
        opponent_hit=opponent_hit, opponent_counter=opponent_counter,
    )
    other = 'p2' if owner == 'p1' else 'p1'
    if not opponent_present and source_zone == 'battle':
        engine.engine_state['battle'][other] = {
            'instance_id': None, 'card': None,
        }
        opponent_context = None
    else:
        opponent_context = copy.deepcopy(opposing)
    selected_event = event_type or (
        'use' if ability == 'combo' else 'counter'
    )
    engine._fire(selected_event, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': opponent_context,
        'source_battle_card_only': True,
    })
    engine._continue()
    live_source = engine._find_card(source['instance_id']) or source
    ability_id = (
        'pmp-at-051-n1' if ability == 'combo' else 'pmp-at-051-n2'
    )
    return {
        'hit': live_source.get('hit'),
        'damage': engine.card_stat(live_source, 'damage', owner),
        'resolved': _st2_resolution_count(engine, ability_id),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


