def _run_pmp_at_032_judgment_scenario(
    definition, card_snapshot, owner, *, event_type='use',
    lumen_feathers=1, source_zone='battle', numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    for index in range(lumen_feathers):
        feather = _card(
            'LMI-AT-041', owner,
            f'{owner}-pmp-032-lumen-feather-{index + 1}',
        )
        feather.update({
            'name': '검은 깃털', 'type': '루멘', 'face_up': True,
        })
        engine._zone(owner, 'lumen').append(feather)
    engine.ruleset['cards']['LMI-AT-041'] = {
        'code': 'LMI-AT-041',
        'effect_definition': _st2_no_effect_definition(),
    }
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    live = engine._find_card(source['instance_id']) or source
    return {
        'hit': live.get('hit'),
        'resolved': _st2_resolution_count(engine, 'pmp-at-032-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_pmp_at_032_feather_scenario(
    definition, card_snapshot, owner, *, event_type='hit', side_count=2,
    accept=True, choose_index=-1, source_zone='battle',
    numbered_negated=False, event_owner=None,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    for index in range(side_count):
        feather = _card(
            'LMI-AT-041', owner,
            f'{owner}-pmp-032-side-feather-{index + 1}',
        )
        feather.update({
            'name': f'검은 깃털 {index + 1}',
            'type': '루멘', 'face_up': False,
        })
        engine._zone(owner, 'side').append(feather)
    engine.ruleset['cards']['LMI-AT-041'] = {
        'code': 'LMI-AT-041',
        'effect_definition': _st2_no_effect_definition(),
    }
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    offered = False
    chosen = None
    decision = engine.engine_state.get('pending_decision') or {}
    if decision.get('kind') == 'optional_effect':
        offered = True
        engine._submit_decision(
            owner, decision.get('id'),
            ['accept' if accept else 'decline'],
        )
        engine._continue()
    decision = engine.engine_state.get('pending_decision') or {}
    if decision.get('kind') == 'effect_choice':
        options = [
            str(item.get('id')) for item in decision.get('options') or []
        ]
        if options:
            chosen = options[choose_index]
            engine._submit_decision(owner, decision.get('id'), [chosen])
            engine._continue()
    return {
        'offered': offered, 'chosen': chosen,
        'side_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'side')
            if card.get('code') == 'LMI-AT-041'
        ),
        'lumen_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'lumen')
            if card.get('code') == 'LMI-AT-041'
        ),
        'resolved': _st2_resolution_count(engine, 'pmp-at-032-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


