def _run_pmp_at_032_combo_scenario(
    definition, card_snapshot, owner, *, lumen_count=2, side_count=1,
    accept_dark=True, source_zone='battle', numbered_negated=False,
    event_owner=None, include_black_feather=False,
    initial_dark_night=False, accept_black_feather=True,
    expire_turn=False,
):
    event_owner = event_owner or owner
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    if initial_dark_night:
        engine.state['players'][owner]['passive_state']['dark_night'] = {
            'value': True, 'label': '암야', 'owner': owner,
        }
    for zone, count in (('lumen', lumen_count), ('side', side_count)):
        for index in range(count):
            dagger = _card(
                'LMI-AT-059', owner,
                f'{owner}-pmp-032-{zone}-dagger-{index + 1}',
            )
            dagger.update({
                'name': f'단검 {zone} {index + 1}',
                'kind': 'token', 'type': '토큰', 'token_key': 'dagger',
                'face_up': zone == 'lumen',
            })
            engine._zone(owner, zone).append(dagger)
    engine.ruleset['cards']['LMI-AT-059'] = {
        'code': 'LMI-AT-059',
        'effect_definition': {
            **_st2_no_effect_definition(), 'token_key': 'dagger',
        },
    }
    if include_black_feather:
        feather = _card(
            'LMI-AT-041', owner, f'{owner}-pmp-032-black-feather',
        )
        feather.update({
            'name': '검은 깃털', 'type': '루멘', 'face_up': True,
        })
        engine._zone(owner, 'lumen').append(feather)
        engine.ruleset['cards']['LMI-AT-041'] = {
            **copy.deepcopy(feather),
            'effect_definition': _pmp_at_032_black_feather_support_definition(),
        }
    hp_before = int(engine.state['players'][other]['hp'])
    engine._fire('combo', {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    decisions = []
    for _step in range(20):
        decision = copy.deepcopy(
            engine.engine_state.get('pending_decision') or {}
        )
        if not decision:
            break
        kind = decision.get('kind')
        selected = []
        if kind == 'effect_order':
            preferred = next((
                option for option in decision.get('options') or []
                if option.get('ability_id') == 'pmp-at-032-n3'
            ), None)
            preferred = preferred or (decision.get('options') or [None])[0]
            selected = [str(preferred.get('id'))] if preferred else []
        elif kind == 'effect_choice':
            options = sorted(
                str(option.get('id'))
                for option in decision.get('options') or []
            )
            count = int(decision.get('minimum') or 0)
            selected = options[-count:] if count else []
        elif kind == 'effect_branch':
            selected = ['accept'] if accept_dark else []
        elif kind == 'optional_effect':
            selected = [
                'accept' if accept_black_feather else 'decline'
            ]
        else:
            break
        decisions.append({
            'kind': kind, 'prompt': decision.get('prompt'),
            'selected': copy.deepcopy(selected),
        })
        engine._submit_decision(owner, decision.get('id'), selected)
        engine._continue()
    dark_state = (
        engine.state['players'][owner]['passive_state'].get('dark_night') or {}
    )
    dark_before_expiry = bool(dark_state.get('value'))
    if expire_turn:
        engine._fire('turn_end', {'controller': owner})
        engine._continue()
    dark_state = (
        engine.state['players'][owner]['passive_state'].get('dark_night') or {}
    )
    return {
        'lumen_daggers': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'lumen')
            if card.get('token_key') == 'dagger'
        ),
        'side_daggers': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'side')
            if card.get('token_key') == 'dagger'
        ),
        'deleted_count': sum(
            event.get('type') == 'token_deleted' for event in engine.events
        ),
        'break_count': len(engine._zone(owner, 'break')),
        'dark_night': dark_before_expiry,
        'dark_night_after_expiry': bool(dark_state.get('value')),
        'opponent_hp_loss': (
            hp_before - int(engine.state['players'][other]['hp'])
        ),
        'decisions': decisions,
        'resolved': _st2_resolution_count(engine, 'pmp-at-032-n3'),
        'feather_resolved': _st2_resolution_count(
            engine, 'lmi-at-041-dark-night-combo',
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_pmp_at_032_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'PMP-AT-032':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    judgment = by_id.get('pmp-at-032-n1')
    feather = by_id.get('pmp-at-032-n2')
    combo = by_id.get('pmp-at-032-n3')
    own_event, feather_selector, combo_effects = _pmp_at_032_expected_parts()
    valid = bool(
        not extra_root
        and set(by_id) == {
            'pmp-at-032-n1', 'pmp-at-032-n2', 'pmp-at-032-n3',
        }
        and sorted(
            (definition.get('source_refs') or {}).get('qna_ids') or []
        ) == [609, 634, 639]
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == [609, 634, 639] for ability in abilities
        )
        and judgment and judgment.get('kind') == 'effect'
        and judgment.get('mode') == 'mandatory'
        and judgment.get('timing') == 'use'
        and judgment.get('active_zones') == ['battle']
        and judgment.get('trigger') == {'event': 'use'}
        and judgment.get('condition') == {
            'op': 'all', 'conditions': [
                copy.deepcopy(own_event),
                {
                    'op': 'zone_count', 'player': {'controller': True},
                    'zone': 'lumen', 'min': 1,
                    'where': {'code': 'LMI-AT-041'},
                },
            ],
        }
        and judgment.get('effects') == [{
            'op': 'modify_judgment', 'player': {'controller': True},
            'field': 'hit', 'value': '콤보', 'duration': 'battle',
        }]
        and feather and feather.get('kind') == 'effect'
        and feather.get('mode') == 'optional'
        and feather.get('timing') == 'hit_counter'
        and feather.get('active_zones') == ['battle']
        and feather.get('trigger') == {'event': 'hit'}
        and feather.get('condition') == own_event
        and feather.get('recheck_condition') is True
        and feather.get('availability_selector') == feather_selector
        and len(feather.get('effects') or []) == 1
        and (feather.get('effects') or [{}])[0].get('selector')
        == feather_selector
        and [
            effect.get('op') for effect in
            ((feather.get('effects') or [{}])[0].get('then') or [])
        ] == ['move_card']
        and combo and combo.get('kind') == 'effect'
        and combo.get('mode') == 'mandatory'
        and combo.get('timing') == 'combo'
        and combo.get('active_zones') == ['battle']
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('condition') == own_event
        and combo.get('effects') == combo_effects
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'PMP-AT-032', 'name': '벤전스', 'type': '공격',
            'frame': 9, 'damage': 600, 'pos': '중단', 'body': None,
            'special': '중단 상쇄', 'hit': '4', 'guard': '-9',
            'counter': '콤보', 'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 10, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'pmp-at-032', False,
                reason='벤전스의 깃털·단검·암야 정의가 일치하지 않습니다.',
            )], 'PMP-AT-032 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    judgment_scenarios = _st2_scenarios(
        _run_pmp_at_032_judgment_scenario, definition, card_snapshot, (
            ('owner-p1-lumen-feather-changes-hit-to-combo', 'p1', {}, {
                'hit': '콤보', 'resolved': 1, 'pending': False,
            }),
            ('owner-p2-lumen-feather-changes-hit-to-combo', 'p2', {}, {
                'hit': '콤보', 'resolved': 1,
            }),
            ('qna-634-no-feather-at-use-keeps-printed-hit', 'p1', {
                'lumen_feathers': 0,
            }, {'hit': '4', 'resolved': 0}),
            ('wrong-hit-event-does-not-change-judgment', 'p2', {
                'event_type': 'hit',
            }, {'hit': '4', 'resolved': 0}),
            ('numbered-negation-disables-judgment-change', 'p1', {
                'numbered_negated': True,
            }, {'hit': '4', 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'hit': '4', 'resolved': 0}),
        ),
    )
    feather_scenarios = _st2_scenarios(
        _run_pmp_at_032_feather_scenario, definition, card_snapshot, (
            ('owner-p1-chooses-physical-side-feather', 'p1', {}, {
                'offered': True,
                'chosen': 'p1-pmp-032-side-feather-2',
                'lumen_ids': ['p1-pmp-032-side-feather-2'],
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-chooses-first-side-feather', 'p2', {
                'choose_index': 0,
            }, {
                'offered': True,
                'chosen': 'p2-pmp-032-side-feather-1', 'resolved': 1,
            }),
            ('declining-keeps-both-side-feathers', 'p1', {
                'accept': False,
            }, {
                'offered': True, 'chosen': None,
                'side_ids': [
                    'p1-pmp-032-side-feather-1',
                    'p1-pmp-032-side-feather-2',
                ],
                'resolved': 0,
            }),
            ('no-side-feather-offers-no-effect', 'p2', {
                'side_count': 0,
            }, {'offered': False, 'resolved': 0}),
            ('counter-result-does-not-place-feather', 'p1', {
                'event_type': 'counter',
            }, {'offered': False, 'resolved': 0}),
            ('opponent-hit-does-not-place-owner-feather', 'p2', {
                'event_owner': 'p1',
            }, {'offered': False, 'resolved': 0}),
            ('numbered-negation-disables-feather-placement', 'p1', {
                'numbered_negated': True,
            }, {'offered': False, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'offered': False, 'resolved': 0}),
        ),
    )
    combo_scenarios = _st2_scenarios(
        _run_pmp_at_032_combo_scenario, definition, card_snapshot, (
            ('owner-p1-places-selected-dagger-and-gains-dark-night', 'p1', {}, {
                'lumen_daggers': [], 'deleted_count': 3,
                'break_count': 0, 'dark_night': True,
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-existing-three-can-gain-dark-without-side', 'p2', {
                'lumen_count': 3, 'side_count': 0,
            }, {
                'lumen_daggers': [], 'deleted_count': 3,
                'dark_night': True, 'resolved': 1,
            }),
            ('declining-dark-branch-keeps-newly-placed-three', 'p1', {
                'accept_dark': False,
            }, {
                'lumen_daggers': [
                    'p1-pmp-032-lumen-dagger-1',
                    'p1-pmp-032-lumen-dagger-2',
                    'p1-pmp-032-side-dagger-1',
                ],
                'deleted_count': 0, 'dark_night': False, 'resolved': 1,
            }),
            ('six-lumen-cap-skips-placement-before-dark-choice', 'p2', {
                'lumen_count': 6, 'side_count': 1,
            }, {
                'side_daggers': ['p2-pmp-032-side-dagger-1'],
                'lumen_daggers': [
                    'p2-pmp-032-lumen-dagger-1',
                    'p2-pmp-032-lumen-dagger-2',
                    'p2-pmp-032-lumen-dagger-3',
                ],
                'deleted_count': 3, 'dark_night': True,
            }),
            ('two-existing-without-side-cannot-open-dark-branch', 'p1', {
                'lumen_count': 2, 'side_count': 0,
            }, {'deleted_count': 0, 'dark_night': False, 'resolved': 1}),
            ('opponent-combo-event-does-not-resolve', 'p2', {
                'event_owner': 'p1',
            }, {'deleted_count': 0, 'dark_night': False, 'resolved': 0}),
            ('numbered-negation-disables-combo-effect', 'p1', {
                'numbered_negated': True,
            }, {'deleted_count': 0, 'dark_night': False, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'deleted_count': 0, 'dark_night': False, 'resolved': 0}),
            ('qna-609-vengeance-delete-does-not-trigger-feather-damage', 'p1', {
                'include_black_feather': True, 'initial_dark_night': True,
                'lumen_count': 3, 'side_count': 0,
            }, {
                'deleted_count': 3, 'opponent_hp_loss': 0,
                'feather_resolved': 0,
            }),
            ('qna-639-feather-can-use-newly-placed-third-dagger', 'p2', {
                'include_black_feather': True, 'initial_dark_night': True,
                'accept_dark': False,
            }, {
                'deleted_count': 3, 'opponent_hp_loss': 200,
                'feather_resolved': 1,
            }),
            ('turn-end-removes-new-dark-night-state', 'p1', {
                'expire_turn': True,
            }, {
                'dark_night': True, 'dark_night_after_expiry': False,
                'deleted_count': 3,
            }),
        ),
    )
    reviews = [
        AbilityReview(
            judgment['id'], all(item['passed'] for item in judgment_scenarios),
            judgment_scenarios,
        ),
        AbilityReview(
            feather['id'], all(item['passed'] for item in feather_scenarios),
            feather_scenarios,
        ),
        AbilityReview(
            combo['id'], all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '벤전스 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _pmp_review_counter(engine, owner, key):
    state = (
        engine.state['players'][owner].get('passive_state') or {}
    ).get(key) or {}
    return int(state.get('count') or 0)


def _run_pmp_at_036_function_scenario(
    definition, card_snapshot, owner, *, yin=4, source_zone='battle',
    numbered_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.change_counter(owner, 'yin', yin, absolute=True)
    engine._refresh_continuous_rules()
    replacements = engine.engine_state.get('replacements') or []
    return {
        'use_allowed': engine._card_use_allowed(source, owner, 'ready'),
        'opponent_dodge_blocked': engine._rule_blocked(
            'dodge', other, opposing, source,
        ),
        'continuous_prevents': sum(
            item.get('kind') == 'dodge' for item in replacements
        ),
    }


def _run_pmp_at_036_yin_block_scenario(
    definition, card_snapshot, owner, *, event_type='use', event_owner=None,
    source_zone='battle', numbered_negated=False, expire_turn=False,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.change_counter(owner, 'yin', 4, absolute=True)
    engine.change_counter(owner, 'yang', 1, absolute=True)
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    before_yin = _pmp_review_counter(engine, owner, 'yin')
    engine.change_counter(owner, 'yin', 1)
    engine.change_counter(owner, 'yang', 1)
    blocked_yin = _pmp_review_counter(engine, owner, 'yin')
    if expire_turn:
        engine._expire_modifiers('turn')
        engine.change_counter(owner, 'yin', 1)
    replacements = engine.engine_state.get('replacements') or []
    return {
        'before_yin': before_yin,
        'yin': _pmp_review_counter(engine, owner, 'yin'),
        'blocked_yin': blocked_yin,
        'yang': _pmp_review_counter(engine, owner, 'yang'),
        'prevents': sum(
            item.get('kind') == 'counter_gain' for item in replacements
        ),
        'resolved': _st2_resolution_count(engine, 'pmp-at-036-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_pmp_at_036_slow_scenario(
    definition, card_snapshot, owner, *, event_type='before_judgment',
    event_owner=None, source_zone='battle', numbered_negated=False,
    opponent_frame=6, yin=4, yang=0, fixed_before=None,
    fixed_after=None,
):
    event_owner = event_owner or owner
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, opponent_frame=opponent_frame,
    )
    engine.change_counter(owner, 'yin', yin, absolute=True)
    engine.change_counter(owner, 'yang', yang, absolute=True)
    if fixed_before is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': other,
            'source': 'review-fixed-before',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'value': fixed_before, 'duration': 'battle',
        })
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    if fixed_after is not None:
        engine.add_modifier({
            'op': 'fix_speed', 'controller': other, 'player': other,
            'source': 'review-fixed-after',
            'where': {'instance_id': opposing['instance_id']},
            'stat': 'frame', 'value': fixed_after, 'duration': 'battle',
        })
    return {
        'yin': _pmp_review_counter(engine, owner, 'yin'),
        'yang': _pmp_review_counter(engine, owner, 'yang'),
        'opponent_speed': engine.card_stat(
            opposing, 'frame', other, include_fp=False,
        ),
        'resolved': _st2_resolution_count(engine, 'pmp-at-036-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_pmp_at_036_yang_block_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    event_owner=None, source_zone='battle', numbered_negated=False,
    expire_turn=False,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.change_counter(owner, 'yin', 1, absolute=True)
    engine.change_counter(owner, 'yang', 3, absolute=True)
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    after_effect = _pmp_review_counter(engine, owner, 'yang')
    engine.change_counter(owner, 'yang', 1)
    after_gain = _pmp_review_counter(engine, owner, 'yang')
    if expire_turn:
        engine._expire_modifiers('turn')
        engine._expire_modifiers('battle')
        engine.change_counter(owner, 'yang', 1)
    engine.change_counter(owner, 'yin', 1)
    replacements = engine.engine_state.get('replacements') or []
    return {
        'after_effect': after_effect, 'after_gain': after_gain,
        'yang': _pmp_review_counter(engine, owner, 'yang'),
        'yin': _pmp_review_counter(engine, owner, 'yin'),
        'prevents': sum(
            item.get('kind') == 'counter_gain' for item in replacements
        ),
        'resolved': _st2_resolution_count(engine, 'pmp-at-036-n3'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_pmp_at_036_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'PMP-AT-036':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('pmp-at-036-function')
    block_yin = by_id.get('pmp-at-036-n1')
    remove_yin = by_id.get('pmp-at-036-n2')
    block_yang = by_id.get('pmp-at-036-n3')
    own_event = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'controller': True},
    }
    valid = bool(
        extra_root == {'play_condition'}
        and set(by_id) == {
            'pmp-at-036-function', 'pmp-at-036-n1',
            'pmp-at-036-n2', 'pmp-at-036-n3',
        }
        and sorted(
            (definition.get('source_refs') or {}).get('qna_ids') or []
        ) == [644, 647, 683]
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == [644, 647, 683] for ability in abilities
        )
        and definition.get('play_condition') == {
            'op': 'counter_at_least', 'player': {'controller': True},
            'counter': 'yin', 'value': 4,
        }
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('active_zones') == ['battle']
        and function.get('effects') == [
            {
                'op': 'prevent', 'kind': 'dodge',
                'player': {'opponent': True}, 'duration': 'continuous',
            },
            {'op': 'static_rule', 'rules': ['play_condition']},
        ]
        and block_yin and block_yin.get('kind') == 'effect'
        and block_yin.get('mode') == 'mandatory'
        and block_yin.get('timing') == 'use'
        and block_yin.get('active_zones') == ['battle']
        and block_yin.get('trigger') == {'event': 'use'}
        and block_yin.get('condition') == own_event
        and block_yin.get('effects') == [{
            'op': 'prevent', 'kind': 'counter_gain',
            'player': {'controller': True}, 'duration': 'turn',
            'where': {'counter': 'yin'},
        }]
        and remove_yin and remove_yin.get('kind') == 'effect'
        and remove_yin.get('mode') == 'mandatory'
        and remove_yin.get('timing') == 'before_judgment'
        and remove_yin.get('active_zones') == ['battle']
        and remove_yin.get('trigger') == {'event': 'before_judgment'}
        and remove_yin.get('condition') == own_event
        and remove_yin.get('effects') == [
            {
                'op': 'set_counter', 'player': {'controller': True},
                'counter': 'yin', 'value': 0, 'min': 0,
            },
            {
                'op': 'modify_stat', 'player': {'opponent': True},
                'stat': 'frame', 'amount': 12, 'duration': 'battle',
            },
        ]
        and block_yang and block_yang.get('kind') == 'effect'
        and block_yang.get('mode') == 'mandatory'
        and block_yang.get('timing') == 'after_use'
        and block_yang.get('active_zones') == ['battle']
        and block_yang.get('trigger') == {'event': 'after_use'}
        and block_yang.get('condition') == own_event
        and block_yang.get('effects') == [
            {
                'op': 'prevent', 'kind': 'counter_gain',
                'player': {'controller': True}, 'duration': 'game',
                'where': {'counter': 'yang'},
            },
            {
                'op': 'set_counter', 'player': {'controller': True},
                'counter': 'yang', 'value': 0, 'min': 0,
            },
        ]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'PMP-AT-036', 'name': '음극 나선축퇴권',
            'type': '공격', 'frame': 13, 'damage': 400,
            'pos': '중단', 'body': None, 'special': None,
            'hit': '3', 'guard': '-7', 'counter': '5',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 8, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'pmp-at-036', False,
                reason='음극 나선축퇴권의 음양·속도 정의가 일치하지 않습니다.',
            )], 'PMP-AT-036 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    function_scenarios = _st2_scenarios(
        _run_pmp_at_036_function_scenario, definition, card_snapshot, (
            ('four-yin-allows-use-and-blocks-p1-opponent-dodge', 'p1', {}, {
                'use_allowed': True, 'opponent_dodge_blocked': True,
                'continuous_prevents': 1,
            }),
            ('four-yin-allows-use-and-blocks-p2-opponent-dodge', 'p2', {}, {
                'use_allowed': True, 'opponent_dodge_blocked': True,
            }),
            ('three-yin-rejects-use', 'p1', {'yin': 3}, {
                'use_allowed': False, 'opponent_dodge_blocked': True,
            }),
            ('numberless-rules-survive-numbered-negation', 'p2', {
                'numbered_negated': True,
            }, {'use_allowed': True, 'opponent_dodge_blocked': True}),
            ('dodge-block-is-inactive-outside-battle', 'p1', {
                'source_zone': 'hand',
            }, {'use_allowed': True, 'opponent_dodge_blocked': False}),
        ),
    )
    yin_scenarios = _st2_scenarios(
        _run_pmp_at_036_yin_block_scenario, definition, card_snapshot, (
            ('p1-use-blocks-yin-but-not-yang', 'p1', {}, {
                'before_yin': 4, 'blocked_yin': 4, 'yang': 2,
                'prevents': 1, 'resolved': 1, 'pending': False,
            }),
            ('p2-use-blocks-yin', 'p2', {}, {
                'blocked_yin': 4, 'resolved': 1,
            }),
            ('turn-end-restores-yin-gain', 'p1', {
                'expire_turn': True,
            }, {'yin': 5, 'prevents': 0}),
            ('wrong-event-does-not-block-yin', 'p2', {
                'event_type': 'hit',
            }, {'yin': 5, 'resolved': 0}),
            ('opponent-use-does-not-block-yin', 'p1', {
                'event_owner': 'p2',
            }, {'yin': 5, 'resolved': 0}),
            ('numbered-negation-disables-yin-block', 'p2', {
                'numbered_negated': True,
            }, {'yin': 5, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p1', {
                'source_zone': 'hand',
            }, {'yin': 5, 'resolved': 0}),
        ),
    )
    slow_scenarios = _st2_scenarios(
        _run_pmp_at_036_slow_scenario, definition, card_snapshot, (
            ('p1-removes-yin-and-slows-opponent-by-twelve', 'p1', {}, {
                'yin': 0, 'opponent_speed': 18, 'resolved': 1,
            }),
            ('p2-removes-yin-and-slows-opponent-by-twelve', 'p2', {
                'opponent_frame': 8,
            }, {'yin': 0, 'opponent_speed': 20, 'resolved': 1}),
            ('qna-644-earlier-fixed-speed-ignores-slowing', 'p1', {
                'fixed_before': 7,
            }, {'yin': 0, 'opponent_speed': 7, 'resolved': 1}),
            ('qna-644-later-fixed-speed-overrides-slowing', 'p2', {
                'fixed_after': 7,
            }, {'yin': 0, 'opponent_speed': 7, 'resolved': 1}),
            ('qna-647-existing-yang-remains-until-after-use', 'p1', {
                'yang': 3,
            }, {'yin': 0, 'yang': 3, 'resolved': 1}),
            ('wrong-event-does-not-remove-or-slow', 'p2', {
                'event_type': 'use',
            }, {'yin': 4, 'opponent_speed': 6, 'resolved': 0}),
            ('opponent-event-does-not-remove-or-slow', 'p1', {
                'event_owner': 'p2',
            }, {'yin': 4, 'opponent_speed': 6, 'resolved': 0}),
            ('numbered-negation-disables-removal-and-slowing', 'p2', {
                'numbered_negated': True,
            }, {'yin': 4, 'opponent_speed': 6, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p1', {
                'source_zone': 'hand',
            }, {'yin': 4, 'opponent_speed': 6, 'resolved': 0}),
        ),
    )
    yang_scenarios = _st2_scenarios(
        _run_pmp_at_036_yang_block_scenario, definition, card_snapshot, (
            ('p1-after-use-removes-and-blocks-yang', 'p1', {}, {
                'after_effect': 0, 'after_gain': 0, 'yang': 0, 'yin': 2,
                'prevents': 1, 'resolved': 1,
            }),
            ('p2-after-use-removes-and-blocks-yang', 'p2', {}, {
                'after_effect': 0, 'after_gain': 0, 'resolved': 1,
            }),
            ('game-duration-block-survives-turn-and-battle-expiry', 'p1', {
                'expire_turn': True,
            }, {'yang': 0, 'prevents': 1}),
            ('wrong-event-preserves-and-allows-yang', 'p2', {
                'event_type': 'use',
            }, {'after_effect': 3, 'yang': 4, 'resolved': 0}),
            ('opponent-event-preserves-and-allows-yang', 'p1', {
                'event_owner': 'p2',
            }, {'after_effect': 3, 'yang': 4, 'resolved': 0}),
            ('numbered-negation-disables-permanent-block', 'p2', {
                'numbered_negated': True,
            }, {'after_effect': 3, 'yang': 4, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p1', {
                'source_zone': 'hand',
            }, {'after_effect': 3, 'yang': 4, 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            function['id'], all(item['passed'] for item in function_scenarios),
            function_scenarios,
        ),
        AbilityReview(
            block_yin['id'], all(item['passed'] for item in yin_scenarios),
            yin_scenarios,
        ),
        AbilityReview(
            remove_yin['id'], all(item['passed'] for item in slow_scenarios),
            slow_scenarios,
        ),
        AbilityReview(
            block_yang['id'], all(item['passed'] for item in yang_scenarios),
            yang_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '음극 나선축퇴권 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_pmp_at_044_break_scenario(
    definition, card_snapshot, owner, *, event_type='hit', event_owner=None,
    source_zone='battle', numbered_negated=False, accept=True,
    candidates=((11, '공격'), (11, '공격')), selected_indices=(0, 1),
    initial_ember=0, late_protect_index=None,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.change_counter(owner, 'ember', initial_ember, absolute=True)
    cards = []
    for index, (character_id, card_type) in enumerate(candidates):
        card = _card(
            f'REVIEW-PMP-044-{index + 1}', owner,
            f'{owner}-pmp-044-list-{index + 1}',
        )
        card.update({
            'name': f'검토 기술 {index + 1}', 'type': card_type,
            'character_id': character_id, 'face_up': True,
        })
        cards.append(card)
        engine._zone(owner, 'list').append(card)
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    trace = []
    for _step in range(20):
        decision = copy.deepcopy(
            engine.engine_state.get('pending_decision') or {}
        )
        if not decision:
            break
        kind = decision.get('kind')
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        if kind == 'optional_effect':
            selected = ['accept' if accept else 'decline']
        elif kind == 'effect_choice':
            selected = [
                cards[index]['instance_id'] for index in selected_indices
                if 0 <= index < len(cards)
                and cards[index]['instance_id'] in option_ids
            ]
            if (
                late_protect_index is not None
                and 0 <= late_protect_index < len(cards)
            ):
                protected_id = cards[late_protect_index]['instance_id']
                engine.engine_state.setdefault('replacements', []).append({
                    'op': 'prevent', 'kind': 'break', 'player': owner,
                    'where': {'instance_id': protected_id},
                    'controller': owner, 'source': 'review-late-protect',
                    'duration': 'game',
                })
        elif kind == 'break_replenish':
            selected = ['decline']
        else:
            selected = option_ids[:1]
        trace.append({
            'kind': kind, 'options': option_ids,
            'selected': copy.deepcopy(selected),
            'range': (decision.get('minimum'), decision.get('maximum')),
        })
        engine._submit_decision(owner, decision.get('id'), selected)
        engine._continue()
    locations = {}
    for card in cards:
        location = engine._find_location(card['instance_id'])
        locations[card['instance_id']] = location[1] if location else None
    return {
        'decision_kinds': [item['kind'] for item in trace],
        'choice_options': next((
            item['options'] for item in trace
            if item['kind'] == 'effect_choice'
        ), []),
        'choice_range': next((
            item['range'] for item in trace
            if item['kind'] == 'effect_choice'
        ), None),
        'selected_ids': next((
            item['selected'] for item in trace
            if item['kind'] == 'effect_choice'
        ), []),
        'locations': locations,
        'broken_ids': sorted(
            instance_id for instance_id, zone in locations.items()
            if zone == 'break'
        ),
        'ember': _pmp_review_counter(engine, owner, 'ember'),
        'resolved': _st2_resolution_count(engine, 'pmp-at-044-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_pmp_at_044_catch_scenario(
    definition, card_snapshot, owner, *, source_zone='hand',
    numbered_negated=False, min_speed=None, max_speed=8,
    allow_zones=None, event_type='catch', fire_event=True,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    catch = {
        'owner': owner,
        'allow_zones': list(allow_zones or ['hand']),
    }
    if min_speed is not None:
        catch['min_speed'] = min_speed
    if max_speed is not None:
        catch['max_speed'] = max_speed
    options = engine._legal_catch_options(owner, catch)
    selected = next((
        item for item in options
        if (item.get('card') or {}).get('instance_id')
        == source['instance_id']
    ), None)
    rules = engine._catch_rules(owner, source)
    if fire_event:
        if source_zone != 'battle':
            engine.move_card(source['instance_id'], 'battle', reason='review')
            source = engine._find_card(source['instance_id']) or source
            engine.engine_state.setdefault('battle', {})[owner] = {
                'instance_id': source['instance_id'], 'card': source,
            }
        engine._fire(event_type, {
            'controller': owner,
            'source_card_instance_id': source['instance_id'],
            'source_card': copy.deepcopy(source),
            'opponent_card': copy.deepcopy(opposing),
            'source_battle_card_only': True,
        })
    return {
        'legal': selected is not None,
        'fixed_speed': selected.get('fixed_speed') if selected else None,
        'rules': copy.deepcopy(rules),
        'resolved': _st2_resolution_count(engine, 'pmp-at-044-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_pmp_at_044_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'PMP-AT-044':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    break_list = by_id.get('pmp-at-044-n1')
    catch = by_id.get('pmp-at-044-n2')
    own_event = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'controller': True},
    }
    selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['list'], 'min': 1, 'max': 2,
        'where': {'is_technique': True},
        'as_operation': 'break_card',
    }
    effects = (break_list or {}).get('effects') or []
    choice = effects[0] if len(effects) == 1 else {}
    followups = choice.get('then') or []
    reward = followups[1] if len(followups) == 2 else {}
    valid = bool(
        extra_root == {'catch_rules'}
        and set(by_id) == {'pmp-at-044-n1', 'pmp-at-044-n2'}
        and sorted(
            (definition.get('source_refs') or {}).get('qna_ids') or []
        ) == [646]
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == [646] for ability in abilities
        )
        and definition.get('catch_rules') == [{
            'fixed_speed': 8, 'numbered_effect': True,
        }]
        and break_list and break_list.get('kind') == 'effect'
        and break_list.get('mode') == 'optional'
        and break_list.get('timing') == 'hit_counter'
        and break_list.get('active_zones') == ['battle']
        and break_list.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter'],
        }
        and break_list.get('condition') == own_event
        and break_list.get('recheck_condition') is True
        and break_list.get('availability_selector') == selector
        and choice.get('op') == 'request_choice'
        and choice.get('selector') == selector
        and choice.get('selection_key') == 'pmp_at_044_list_cards'
        and [item.get('op') for item in followups]
        == ['break_cards', 'conditional']
        and followups[0].get('selection_key') == 'pmp_at_044_list_cards'
        and followups[0].get('result_key') == 'pmp_at_044_broken_cards'
        and reward.get('condition') == {
            'op': 'all', 'conditions': [
                {
                    'op': 'equals',
                    'left': {
                        'op': 'selection_count',
                        'selection_key': 'pmp_at_044_broken_cards',
                    },
                    'right': 2,
                },
                {
                    'op': 'equals',
                    'left': {
                        'op': 'selection_count',
                        'selection_key': 'pmp_at_044_broken_cards',
                        'where': {
                            'character_id': 11, 'is_technique': True,
                        },
                    },
                    'right': 2,
                },
            ],
        }
        and reward.get('then') == [{
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'ember', 'amount': 2, 'min': 0,
        }]
        and catch and catch.get('kind') == 'effect'
        and catch.get('mode') == 'mandatory'
        and catch.get('timing') == 'catch'
        and catch.get('active_zones') == ['battle']
        and catch.get('trigger') == {'event': 'catch'}
        and catch.get('condition') == own_event
        and catch.get('effects') == [{
            'op': 'static_rule', 'rules': ['catch_rules'],
        }]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'PMP-AT-044', 'name': '초염상룡권', 'type': '공격',
            'frame': 9, 'damage': 500, 'pos': '하단', 'body': None,
            'special': None, 'hit': '4', 'guard': '-6', 'counter': '5',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 11, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'pmp-at-044', False,
                reason='초염상룡권의 리스트 브레이크·캐치 정의가 일치하지 않습니다.',
            )], 'PMP-AT-044 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    break_scenarios = _st2_scenarios(
        _run_pmp_at_044_break_scenario, definition, card_snapshot, (
            ('p1-hit-breaks-two-physical-rin-techniques-for-two-ember', 'p1', {}, {
                'selected_ids': [
                    'p1-pmp-044-list-1', 'p1-pmp-044-list-2',
                ],
                'broken_ids': [
                    'p1-pmp-044-list-1', 'p1-pmp-044-list-2',
                ],
                'ember': 2, 'resolved': 1, 'pending': False,
            }),
            ('p2-counter-breaks-two-rin-techniques', 'p2', {
                'event_type': 'counter',
            }, {'ember': 2, 'resolved': 1}),
            ('one-rin-technique-does-not-gain-ember', 'p1', {
                'candidates': ((11, '공격'),), 'selected_indices': (0,),
            }, {'ember': 0, 'resolved': 1}),
            ('mixed-character-techniques-do-not-gain-ember', 'p2', {
                'candidates': ((11, '공격'), (12, '공격')),
            }, {'ember': 0, 'resolved': 1}),
            ('non-technique-is-not-offered', 'p1', {
                'candidates': ((11, '공격'), (11, '캐릭터')),
                'selected_indices': (0,),
            }, {
                'choice_options': ['p1-pmp-044-list-1'],
                'ember': 0, 'resolved': 1,
            }),
            ('declining-keeps-list-unchanged', 'p2', {
                'accept': False,
            }, {'broken_ids': [], 'ember': 0, 'resolved': 0}),
            ('late-protection-counts-only-actual-breaks', 'p1', {
                'late_protect_index': 1,
            }, {
                'broken_ids': ['p1-pmp-044-list-1'],
                'ember': 0, 'resolved': 1,
            }),
            ('qna-646-reward-adds-to-four-prior-ember', 'p2', {
                'initial_ember': 4,
            }, {'ember': 6, 'resolved': 1}),
            ('wrong-event-does-not-offer-effect', 'p1', {
                'event_type': 'use',
            }, {'decision_kinds': [], 'broken_ids': [], 'resolved': 0}),
            ('opponent-hit-does-not-offer-effect', 'p2', {
                'event_owner': 'p1',
            }, {'decision_kinds': [], 'broken_ids': [], 'resolved': 0}),
            ('numbered-negation-disables-break-effect', 'p1', {
                'numbered_negated': True,
            }, {'decision_kinds': [], 'broken_ids': [], 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'decision_kinds': [], 'broken_ids': [], 'resolved': 0}),
        ),
    )
    catch_scenarios = _st2_scenarios(
        _run_pmp_at_044_catch_scenario, definition, card_snapshot, (
            ('fixed-eight-is-legal-at-maximum-eight', 'p1', {}, {
                'legal': True, 'fixed_speed': 8,
                'rules': [{'fixed_speed': 8, 'numbered_effect': True}],
                'resolved': 1,
            }),
            ('fixed-eight-works-for-p2', 'p2', {}, {
                'legal': True, 'fixed_speed': 8, 'resolved': 1,
            }),
            ('maximum-seven-rejects-fixed-eight', 'p1', {
                'max_speed': 7,
            }, {'legal': False, 'fixed_speed': None}),
            ('minimum-nine-rejects-fixed-eight', 'p2', {
                'min_speed': 9, 'max_speed': None,
            }, {'legal': False, 'fixed_speed': None}),
            ('qna-646-break-zone-grant-can-catch-at-eight', 'p1', {
                'source_zone': 'break', 'allow_zones': ['break'],
            }, {'legal': True, 'fixed_speed': 8, 'resolved': 1}),
            ('numbered-negation-uses-printed-nine-and-misses-eight', 'p2', {
                'numbered_negated': True,
            }, {'legal': False, 'rules': [], 'resolved': 0}),
            ('wrong-event-does-not-resolve-numbered-effect', 'p1', {
                'event_type': 'use',
            }, {'legal': True, 'resolved': 0}),
            ('list-zone-is-not-legal-with-hand-only-grant', 'p2', {
                'source_zone': 'list', 'fire_event': False,
            }, {'legal': False, 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            break_list['id'], all(item['passed'] for item in break_scenarios),
            break_scenarios,
        ),
        AbilityReview(
            catch['id'], all(item['passed'] for item in catch_scenarios),
            catch_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '초염상룡권 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _pmp_review_add_spiders(engine, owner, count, *, token_key='spider'):
    for index in range(count):
        token = _card(
            'PMP-AT-053', owner,
            f'{owner}-pmp-review-{token_key}-{index + 1}',
        )
        token.update({
            'name': '거미 토큰' if token_key == 'spider' else '다른 토큰',
            'kind': 'token', 'type': '토큰', 'token_key': token_key,
            'face_up': True,
        })
        engine._zone(owner, 'lumen').append(token)
    engine.ruleset['cards']['PMP-AT-053'] = {
        'code': 'PMP-AT-053', 'token_key': 'spider',
        'effect_definition': _st2_no_effect_definition(),
    }


def _run_pmp_at_006_payment_scenario(
    definition, card_snapshot, owner, *, owner_hp=1200,
    selected='pay_once', event_type='use', event_owner=None,
    source_zone='battle', numbered_negated=False,
):
    event_owner = event_owner or owner
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.state['players'][owner]['hp'] = owner_hp
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    decision = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    options = [
        str(option.get('id')) for option in decision.get('options') or []
    ]
    if decision.get('kind') == 'effect_branch':
        choice = [selected] if selected in options else []
        engine._submit_decision(owner, decision.get('id'), choice)
        engine._continue()
    return {
        'decision_kind': decision.get('kind'), 'options': options,
        'hp': engine.state['players'][owner]['hp'],
        'damage': engine.card_stat(source, 'damage', owner, include_fp=False),
        'winner': engine.engine_state.get('winner'),
        'reason': engine.engine_state.get('reason'),
        'expected_winner': other,
        'resolved': _st2_resolution_count(engine, 'pmp-at-006-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_pmp_at_006_speed_scenario(
    definition, card_snapshot, owner, *, spider_count=3,
    event_type='before_judgment', event_owner=None,
    source_zone='battle', numbered_negated=False,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    _pmp_review_add_spiders(engine, owner, spider_count)
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    return {
        'speed': engine.card_stat(source, 'frame', owner, include_fp=False),
        'resolved': _st2_resolution_count(engine, 'pmp-at-006-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


