def _cb01_review_card(code, owner, instance_id, *, card_type='공격'):
    card = _card(code, owner, instance_id)
    card.update({
        'name': f'CB01 검토 카드 {instance_id}', 'type': card_type,
        'frame': 7 if card_type == '공격' else None,
        'damage': 400 if card_type == '공격' else None,
        'face_up': False,
    })
    return card


def _cb01_register_cards(engine, cards):
    for card in cards:
        engine.ruleset['cards'][card['code']] = {
            **copy.deepcopy(card),
            'effect_definition': _st2_no_effect_definition(),
        }


def _run_cb01_at_013_play_scenario(
    definition, card_snapshot, owner, *, hp=2500,
    source_zone='hand', numbered_negated=False,
):
    engine, source, _opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.state['players'][owner]['hp'] = hp
    return {
        'ready_allowed': engine._card_use_allowed(source, owner, 'ready'),
        'combo_allowed': engine._card_use_allowed(source, owner, 'combo'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_013_place_scenario(
    definition, card_snapshot, owner, *, hand_count=4,
    selected_indices=(0, 2, 3), event_type='use', event_owner=None,
    source_zone='battle', numbered_negated=False,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    cards = [
        _cb01_review_card(
            f'REVIEW-CB01-013-HAND-{index + 1}', owner,
            f'{owner}-cb01-013-hand-{index + 1}',
        )
        for index in range(hand_count)
    ]
    engine._zone(owner, 'hand').extend(cards)
    _cb01_register_cards(engine, cards)
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    decision = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    option_ids = [
        str(option.get('id')) for option in decision.get('options') or []
    ]
    selected_ids = [
        cards[index]['instance_id'] for index in selected_indices
        if 0 <= index < len(cards)
        and cards[index]['instance_id'] in option_ids
    ]
    if decision.get('kind') == 'effect_choice':
        engine._submit_decision(owner, decision.get('id'), selected_ids)
        engine._continue()
    locations = {
        card['instance_id']: (
            (engine._find_location(card['instance_id']) or (None, None))[1]
        )
        for card in cards
    }
    return {
        'decision_kind': decision.get('kind'),
        'options': option_ids, 'selected_ids': selected_ids,
        'lumen_ids': sorted(
            instance_id for instance_id, zone in locations.items()
            if zone == 'lumen'
        ),
        'hand_ids': sorted(
            instance_id for instance_id, zone in locations.items()
            if zone == 'hand'
        ),
        'all_lumen_face_down': all(
            card.get('face_up') is False
            for card in engine._zone(owner, 'lumen')
            if card.get('instance_id') in selected_ids
        ),
        'resolved': _st2_resolution_count(engine, 'cb01-at-013-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_013_speed_scenario(
    definition, card_snapshot, owner, *, owner_hand=1, opponent_hand=4,
    event_type='before_judgment', event_owner=None,
    source_zone='battle', numbered_negated=False,
):
    event_owner = event_owner or owner
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    owner_cards = [
        _cb01_review_card(
            f'REVIEW-CB01-013-OWN-{index + 1}', owner,
            f'{owner}-cb01-013-own-{index + 1}',
        )
        for index in range(owner_hand)
    ]
    opponent_cards = [
        _cb01_review_card(
            f'REVIEW-CB01-013-OPP-{index + 1}', other,
            f'{other}-cb01-013-opp-{index + 1}',
        )
        for index in range(opponent_hand)
    ]
    engine._zone(owner, 'hand').extend(owner_cards)
    engine._zone(other, 'hand').extend(opponent_cards)
    _cb01_register_cards(engine, [*owner_cards, *opponent_cards])
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    return {
        'speed': engine.card_stat(source, 'frame', owner, include_fp=False),
        'resolved': _st2_resolution_count(engine, 'cb01-at-013-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_013_recover_scenario(
    definition, card_snapshot, owner, *, hidden_count=3,
    face_up_count=1, selected_indices=(0, 2), event_type='after_use',
    event_owner=None, source_zone='battle', numbered_negated=False,
    replenish=False,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    hidden = [
        _cb01_review_card(
            f'REVIEW-CB01-013-HIDDEN-{index + 1}', owner,
            f'{owner}-cb01-013-hidden-{index + 1}',
        )
        for index in range(hidden_count)
    ]
    face_up = [
        _cb01_review_card(
            f'REVIEW-CB01-013-FACE-UP-{index + 1}', owner,
            f'{owner}-cb01-013-face-up-{index + 1}',
        )
        for index in range(face_up_count)
    ]
    for card in face_up:
        card['face_up'] = True
    replacement = _cb01_review_card(
        'REVIEW-CB01-013-REPLACEMENT', owner,
        f'{owner}-cb01-013-replacement',
    )
    engine._zone(owner, 'lumen').extend([*hidden, *face_up])
    if replenish:
        engine._zone(owner, 'side').append(replacement)
    _cb01_register_cards(engine, [*hidden, *face_up, replacement])
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    trace = []
    selected_ids = []
    for _step in range(10):
        decision = copy.deepcopy(
            engine.engine_state.get('pending_decision') or {}
        )
        if not decision:
            break
        option_ids = [
            str(option.get('id')) for option in decision.get('options') or []
        ]
        if decision.get('kind') == 'effect_choice':
            selected_ids = [
                hidden[index]['instance_id'] for index in selected_indices
                if 0 <= index < len(hidden)
                and hidden[index]['instance_id'] in option_ids
            ]
            selected = selected_ids
        elif decision.get('kind') == 'break_replenish':
            selected = (
                [replacement['instance_id']]
                if replenish and replacement['instance_id'] in option_ids
                else ['decline']
            )
        else:
            break
        trace.append({
            'kind': decision.get('kind'), 'options': option_ids,
            'selected': copy.deepcopy(selected),
        })
        engine._submit_decision(owner, decision.get('id'), selected)
        engine._continue()
    source_location = engine._find_location(source['instance_id'])
    replacement_location = engine._find_location(replacement['instance_id'])
    return {
        'decision_kinds': [item['kind'] for item in trace],
        'choice_options': next((
            item['options'] for item in trace
            if item['kind'] == 'effect_choice'
        ), []),
        'selected_ids': selected_ids,
        'hand_hidden_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'hand')
            if card.get('instance_id') in {
                item['instance_id'] for item in hidden
            }
        ),
        'face_up_stays_lumen': all(
            (engine._find_location(card['instance_id']) or (None, None))[1]
            == 'lumen' for card in face_up
        ),
        'source_zone': source_location[1] if source_location else None,
        'replacement_zone': (
            replacement_location[1] if replacement_location else None
        ),
        'resolved': _st2_resolution_count(engine, 'cb01-at-013-n3'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb01_at_013_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-013':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    play = by_id.get('cb01-at-013-function')
    place = by_id.get('cb01-at-013-n1')
    speed = by_id.get('cb01-at-013-n2')
    recover = by_id.get('cb01-at-013-n3')
    qna_ids = [659, 660, 661, 664, 666]
    own_event = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'controller': True},
    }
    place_choice = ((place or {}).get('effects') or [{}])[0]
    recover_choice = ((recover or {}).get('effects') or [{}])[0]
    valid = bool(
        extra_root == {'play_condition'}
        and set(by_id) == {
            'cb01-at-013-function', 'cb01-at-013-n1',
            'cb01-at-013-n2', 'cb01-at-013-n3',
        }
        and sorted(
            (definition.get('source_refs') or {}).get('qna_ids') or []
        ) == qna_ids
        and all(
            sorted((ability.get('source_refs') or {}).get('qna_ids') or [])
            == qna_ids for ability in abilities
        )
        and definition.get('play_condition') == {
            'op': 'lte', 'left': 'context.controller_hp', 'right': 2500,
        }
        and play and play.get('kind') == 'function'
        and play.get('mode') == 'continuous'
        and play.get('effects') == [{
            'op': 'static_rule', 'rules': ['play_condition'],
        }]
        and place and place.get('kind') == 'effect'
        and place.get('mode') == 'mandatory'
        and place.get('timing') == 'use'
        and place.get('active_zones') == ['battle']
        and place.get('trigger') == {'event': 'use'}
        and place.get('condition') == {
            'op': 'all', 'conditions': [
                copy.deepcopy(own_event),
                {
                    'op': 'zone_count', 'player': {'controller': True},
                    'zone': 'hand', 'min': 3,
                },
            ],
        }
        and place.get('recheck_condition') is True
        and place_choice.get('op') == 'request_choice'
        and place_choice.get('selector') == {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['hand'], 'min': 3, 'max': 3,
            'as_operation': 'move_card', 'to_zone': 'lumen',
        }
        and [item.get('op') for item in place_choice.get('then') or []]
        == ['move_card', 'hide']
        and speed and speed.get('kind') == 'effect'
        and speed.get('mode') == 'mandatory'
        and speed.get('timing') == 'before_judgment'
        and speed.get('active_zones') == ['battle']
        and speed.get('trigger') == {'event': 'before_judgment'}
        and speed.get('condition') == {
            'op': 'all', 'conditions': [
                copy.deepcopy(own_event),
                {
                    'op': 'lt',
                    'left': {
                        'op': 'zone_count',
                        'player': {'controller': True}, 'zone': 'hand',
                    },
                    'right': {
                        'op': 'zone_count',
                        'player': {'opponent': True}, 'zone': 'hand',
                    },
                },
            ],
        }
        and ((speed.get('effects') or [{}])[0]).get('amount') == {
            'op': 'multiply', 'values': [
                -1,
                {
                    'op': 'subtract',
                    'left': {
                        'op': 'zone_count',
                        'player': {'opponent': True}, 'zone': 'hand',
                    },
                    'right': {
                        'op': 'zone_count',
                        'player': {'controller': True}, 'zone': 'hand',
                    },
                },
            ],
        }
        and recover and recover.get('kind') == 'effect'
        and recover.get('mode') == 'mandatory'
        and recover.get('timing') == 'after_use'
        and recover.get('active_zones') == ['battle']
        and recover.get('trigger') == {'event': 'after_use'}
        and recover.get('condition') == own_event
        and recover_choice.get('op') == 'request_choice'
        and recover_choice.get('optional') is True
        and recover_choice.get('selector') == {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['lumen'], 'min': 0, 'max': 99,
            'where': {'face_up': False},
            'as_operation': 'move_card', 'to_zone': 'hand',
        }
        and [item.get('op') for item in recover_choice.get('then') or []]
        == ['move_card', 'break_card']
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB01-AT-013', 'name': '임파서블 엑시트',
            'type': '공격', 'frame': 11, 'damage': 800,
            'pos': '상단', 'body': None, 'special': None,
            'hit': '8', 'guard': '-3', 'counter': '콤보',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 5, 'ultimate': True,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb01-at-013', False,
                reason='임파서블 엑시트의 사용 조건·뒷면 이동·속도·브레이크 정의가 일치하지 않습니다.',
            )], 'CB01-AT-013 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    play_scenarios = _st2_scenarios(
        _run_cb01_at_013_play_scenario, definition, card_snapshot, (
            ('p1-two-thousand-five-hundred-allows-ready', 'p1', {}, {
                'ready_allowed': True, 'combo_allowed': True,
            }),
            ('p2-below-limit-allows-ready', 'p2', {'hp': 1800}, {
                'ready_allowed': True,
            }),
            ('two-thousand-five-hundred-one-rejects-ready', 'p1', {
                'hp': 2501,
            }, {'ready_allowed': False, 'combo_allowed': False}),
            ('numberless-condition-survives-numbered-negation', 'p2', {
                'numbered_negated': True,
            }, {'ready_allowed': True}),
        ),
    )
    place_scenarios = _st2_scenarios(
        _run_cb01_at_013_place_scenario, definition, card_snapshot, (
            ('p1-selects-three-physical-hand-cards', 'p1', {}, {
                'decision_kind': 'effect_choice',
                'selected_ids': [
                    'p1-cb01-013-hand-1', 'p1-cb01-013-hand-3',
                    'p1-cb01-013-hand-4',
                ],
                'lumen_ids': [
                    'p1-cb01-013-hand-1', 'p1-cb01-013-hand-3',
                    'p1-cb01-013-hand-4',
                ],
                'all_lumen_face_down': True, 'resolved': 1,
            }),
            ('p2-selects-another-three-card-set', 'p2', {
                'selected_indices': (0, 1, 2),
            }, {'resolved': 1, 'pending': False}),
            ('exactly-three-hand-cards-are-all-options', 'p1', {
                'hand_count': 3, 'selected_indices': (0, 1, 2),
            }, {'resolved': 1, 'hand_ids': []}),
            ('two-hand-cards-cannot-pay-mandatory-move', 'p2', {
                'hand_count': 2,
            }, {'decision_kind': None, 'resolved': 0}),
            ('wrong-event-does-not-place-cards', 'p1', {
                'event_type': 'hit',
            }, {'decision_kind': None, 'resolved': 0}),
            ('opponent-use-does-not-place-cards', 'p2', {
                'event_owner': 'p1',
            }, {'decision_kind': None, 'resolved': 0}),
            ('numbered-negation-disables-placement', 'p1', {
                'numbered_negated': True,
            }, {'decision_kind': None, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'decision_kind': None, 'resolved': 0}),
        ),
    )
    speed_scenarios = _st2_scenarios(
        _run_cb01_at_013_speed_scenario, definition, card_snapshot, (
            ('p1-three-card-deficit-speeds-up-by-three', 'p1', {}, {
                'speed': 8, 'resolved': 1,
            }),
            ('p2-two-card-deficit-speeds-up-by-two', 'p2', {
                'owner_hand': 2, 'opponent_hand': 4,
            }, {'speed': 9, 'resolved': 1}),
            ('equal-hands-do-not-change-speed', 'p1', {
                'owner_hand': 3, 'opponent_hand': 3,
            }, {'speed': 11, 'resolved': 0}),
            ('larger-owner-hand-does-not-change-speed', 'p2', {
                'owner_hand': 5, 'opponent_hand': 2,
            }, {'speed': 11, 'resolved': 0}),
            ('zero-versus-five-reaches-speed-six', 'p1', {
                'owner_hand': 0, 'opponent_hand': 5,
            }, {'speed': 6, 'resolved': 1}),
            ('wrong-event-does-not-change-speed', 'p2', {
                'event_type': 'use',
            }, {'speed': 11, 'resolved': 0}),
            ('opponent-event-does-not-change-speed', 'p1', {
                'event_owner': 'p2',
            }, {'speed': 11, 'resolved': 0}),
            ('numbered-negation-disables-speed-change', 'p2', {
                'numbered_negated': True,
            }, {'speed': 11, 'resolved': 0}),
        ),
    )
    recover_scenarios = _st2_scenarios(
        _run_cb01_at_013_recover_scenario, definition, card_snapshot, (
            ('p1-selects-two-hidden-cards-then-breaks', 'p1', {}, {
                'selected_ids': [
                    'p1-cb01-013-hidden-1', 'p1-cb01-013-hidden-3',
                ],
                'hand_hidden_ids': [
                    'p1-cb01-013-hidden-1', 'p1-cb01-013-hidden-3',
                ],
                'face_up_stays_lumen': True,
                'source_zone': 'break', 'resolved': 1,
            }),
            ('p2-may-select-zero-and-still-break', 'p2', {
                'selected_indices': (),
            }, {
                'selected_ids': [], 'hand_hidden_ids': [],
                'source_zone': 'break', 'resolved': 1,
            }),
            ('qna-666-ultimate-attack-break-can-replenish', 'p1', {
                'replenish': True, 'selected_indices': (1,),
            }, {
                'source_zone': 'break', 'replacement_zone': 'list',
                'resolved': 1,
            }),
            ('no-hidden-card-still-processes-following-break', 'p2', {
                'hidden_count': 0, 'selected_indices': (),
            }, {'source_zone': 'break', 'resolved': 1}),
            ('face-up-lumen-card-is-never-an-option', 'p1', {
                'hidden_count': 1, 'face_up_count': 2,
                'selected_indices': (0,),
            }, {
                'choice_options': ['p1-cb01-013-hidden-1'],
                'face_up_stays_lumen': True,
            }),
            ('opponent-after-use-does-not-recover-or-break', 'p2', {
                'event_owner': 'p1',
            }, {'source_zone': 'battle', 'resolved': 0}),
            ('numbered-negation-disables-recovery-and-break', 'p1', {
                'numbered_negated': True,
            }, {'source_zone': 'battle', 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand',
            }, {'source_zone': 'hand', 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            play['id'], all(item['passed'] for item in play_scenarios),
            play_scenarios,
        ),
        AbilityReview(
            place['id'], all(item['passed'] for item in place_scenarios),
            place_scenarios,
        ),
        AbilityReview(
            speed['id'], all(item['passed'] for item in speed_scenarios),
            speed_scenarios,
        ),
        AbilityReview(
            recover['id'], all(item['passed'] for item in recover_scenarios),
            recover_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '임파서블 엑시트 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_cb01_at_014_guard_scenario(
    definition, card_snapshot, owner, *, source_zone='battle',
    numbered_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine._refresh_continuous_rules()
    return {
        'guard_blocked': engine._rule_blocked(
            'guard', other, opposing, source,
        ),
        'guard_preventions': sum(
            item.get('kind') == 'guard'
            for item in engine.engine_state.get('replacements') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_014_grab_scenario(
    definition, card_snapshot, owner, *, initial_fp=7,
    event_type='grab_negated', event_owner=None,
    source_zone='battle', numbered_negated=False,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.state['players'][owner]['fp'] = initial_fp
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
    })
    return {
        'fp': engine.state['players'][owner]['fp'],
        'resolved': _st2_resolution_count(
            engine, 'cb01-at-014-function-2',
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_014_dodge_scenario(
    definition, card_snapshot, owner, *, advance_notice=False,
    calling_cards=2, selected_index=1, opponent_initial_fp=0,
    event_type='opponent_dodge', event_owner=None,
    source_zone='battle', numbered_negated=False,
):
    event_owner = event_owner or owner
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
        opponent_fp=opponent_initial_fp,
    )
    if advance_notice:
        engine.state['players'][owner]['passive_state']['advance_notice'] = {
            'value': True, 'label': '예고',
        }
    tokens = []
    for index in range(calling_cards):
        token = _cb01_review_card(
            f'REVIEW-CB01-014-CALLING-{index + 1}', owner,
            f'{owner}-cb01-014-calling-{index + 1}', card_type='특수',
        )
        token.update({
            'name': f'예고장 {index + 1}',
            'kind': 'token', 'token_key': 'calling_card',
            'face_up': True,
        })
        tokens.append(token)
    engine._zone(owner, 'lumen').extend(tokens)
    _cb01_register_cards(engine, tokens)
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    decision = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    options = [
        str(option.get('id')) for option in decision.get('options') or []
    ]
    chosen = None
    if decision.get('kind') == 'effect_choice' and options:
        chosen = (
            tokens[selected_index]['instance_id']
            if 0 <= selected_index < len(tokens)
            and tokens[selected_index]['instance_id'] in options
            else options[0]
        )
        engine._submit_decision(owner, decision.get('id'), [chosen])
        engine._continue()
    return {
        'decision_kind': decision.get('kind'),
        'options': options, 'chosen': chosen,
        'opponent_fp': engine.state['players'][other]['fp'],
        'lumen_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'lumen')
            if card.get('token_key') == 'calling_card'
        ),
        'side_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'side')
            if card.get('token_key') == 'calling_card'
        ),
        'resolved': _st2_resolution_count(engine, 'cb01-at-014-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb01_at_014_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-014':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    guard = by_id.get('cb01-at-014-function')
    grab = by_id.get('cb01-at-014-function-2')
    dodge = by_id.get('cb01-at-014-n1')
    own_event = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'controller': True},
    }
    dodge_conditional = ((dodge or {}).get('effects') or [{}])[0]
    token_conditional = (
        (dodge_conditional.get('then') or [{}])[0]
        if dodge_conditional else {}
    )
    token_choice = (
        (token_conditional.get('then') or [{}])[0]
        if token_conditional else {}
    )
    valid = bool(
        not extra_root
        and set(by_id) == {
            'cb01-at-014-function', 'cb01-at-014-function-2',
            'cb01-at-014-n1',
        }
        and (definition.get('source_refs') or {}).get('qna_ids') == []
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == []
            for ability in abilities
        )
        and guard and guard.get('kind') == 'function'
        and guard.get('mode') == 'continuous'
        and guard.get('timing') == 'function'
        and guard.get('active_zones') == ['battle']
        and guard.get('effects') == [{
            'op': 'prevent', 'kind': 'guard',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and grab and grab.get('kind') == 'function'
        and grab.get('mode') == 'mandatory'
        and grab.get('timing') == 'result'
        and grab.get('trigger') == {'event': 'grab_negated'}
        and grab.get('condition') == own_event
        and grab.get('active_zones') is None
        and grab.get('effects') == [{
            'op': 'change_fp', 'player': {'controller': True},
            'amount': -4,
        }]
        and dodge and dodge.get('kind') == 'effect'
        and dodge.get('mode') == 'mandatory'
        and dodge.get('timing') == 'opponent_dodge'
        and dodge.get('active_zones') == ['battle']
        and dodge.get('trigger') == {'event': 'opponent_dodge'}
        and dodge.get('condition') == own_event
        and dodge_conditional.get('op') == 'conditional'
        and dodge_conditional.get('condition') == {
            'op': 'has_state', 'player': {'controller': True},
            'state': 'advance_notice',
        }
        and token_conditional.get('op') == 'conditional'
        and token_conditional.get('condition') == {
            'op': 'zone_count', 'player': {'controller': True},
            'zone': 'lumen', 'min': 1,
            'where': {'token_key': 'calling_card'},
        }
        and token_choice.get('op') == 'request_choice'
        and token_choice.get('selector') == {
            'kind': 'card', 'player': {'controller': True},
            'zones': ['lumen'], 'min': 1, 'max': 1,
            'where': {'token_key': 'calling_card'},
            'as_operation': 'move_card', 'to_zone': 'side',
        }
        and [item.get('op') for item in token_choice.get('then') or []]
        == ['move_card']
        and dodge_conditional.get('else') == [{
            'op': 'change_fp', 'player': {'opponent': True},
            'amount': 4,
        }]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB01-AT-014', 'name': '캐치 더 문',
            'type': '공격', 'frame': 9, 'damage': 500,
            'pos': '상단', 'body': None, 'special': '그랩',
            'hit': '2', 'guard': 'X', 'counter': '9',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 5, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb01-at-014', False,
                reason='캐치 더 문의 방어 금지·그랩 무효·예고장 대체 정의가 일치하지 않습니다.',
            )], 'CB01-AT-014 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    guard_scenarios = _st2_scenarios(
        _run_cb01_at_014_guard_scenario, definition, card_snapshot, (
            ('p1-opponent-cannot-guard', 'p1', {}, {
                'guard_blocked': True, 'guard_preventions': 1,
            }),
            ('p2-opponent-cannot-guard', 'p2', {}, {
                'guard_blocked': True, 'guard_preventions': 1,
            }),
            ('numberless-guard-block-survives-numbered-negation', 'p1', {
                'numbered_negated': True,
            }, {'guard_blocked': True}),
            ('guard-block-is-inactive-outside-battle', 'p2', {
                'source_zone': 'hand',
            }, {'guard_blocked': False, 'guard_preventions': 0}),
        ),
    )
    grab_scenarios = _st2_scenarios(
        _run_cb01_at_014_grab_scenario, definition, card_snapshot, (
            ('p1-grab-negation-loses-four-fp', 'p1', {}, {
                'fp': 3, 'resolved': 1,
            }),
            ('p2-four-fp-loss-can-produce-negative-fp', 'p2', {
                'initial_fp': 3,
            }, {
                'fp': -1, 'resolved': 1,
            }),
            ('numberless-penalty-survives-numbered-negation', 'p1', {
                'numbered_negated': True,
            }, {'fp': 3, 'resolved': 1}),
            ('opponent-grab-negation-does-not-penalize-owner', 'p2', {
                'event_owner': 'p1',
            }, {'fp': 7, 'resolved': 0}),
            ('wrong-event-does-not-penalize-owner', 'p1', {
                'event_type': 'counter',
            }, {'fp': 7, 'resolved': 0}),
        ),
    )
    dodge_scenarios = _st2_scenarios(
        _run_cb01_at_014_dodge_scenario, definition, card_snapshot, (
            ('normal-p1-dodge-gives-opponent-four-fp', 'p1', {
                'advance_notice': False,
            }, {'opponent_fp': 4, 'decision_kind': None, 'resolved': 1}),
            ('normal-p2-dodge-adds-to-existing-fp', 'p2', {
                'advance_notice': False, 'opponent_initial_fp': 2,
            }, {'opponent_fp': 6, 'resolved': 1}),
            ('advance-notice-chooses-one-of-two-physical-cards', 'p1', {
                'advance_notice': True,
            }, {
                'decision_kind': 'effect_choice',
                'chosen': 'p1-cb01-014-calling-2',
                'side_ids': ['p1-cb01-014-calling-2'],
                'opponent_fp': 0, 'resolved': 1,
            }),
            ('advance-notice-p2-chooses-only-card', 'p2', {
                'advance_notice': True, 'calling_cards': 1,
                'selected_index': 0,
            }, {
                'options': ['p2-cb01-014-calling-1'],
                'side_ids': ['p2-cb01-014-calling-1'],
                'opponent_fp': 0,
            }),
            ('advance-notice-without-card-does-not-fall-back-to-fp', 'p1', {
                'advance_notice': True, 'calling_cards': 0,
            }, {'decision_kind': None, 'opponent_fp': 0, 'resolved': 1}),
            ('opponent-event-does-not-trigger-owner-effect', 'p2', {
                'event_owner': 'p1', 'advance_notice': False,
            }, {'opponent_fp': 0, 'resolved': 0}),
            ('numbered-negation-disables-dodge-effect', 'p1', {
                'numbered_negated': True, 'advance_notice': False,
            }, {'opponent_fp': 0, 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p2', {
                'source_zone': 'hand', 'advance_notice': False,
            }, {'opponent_fp': 0, 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            guard['id'], all(item['passed'] for item in guard_scenarios),
            guard_scenarios,
        ),
        AbilityReview(
            grab['id'], all(item['passed'] for item in grab_scenarios),
            grab_scenarios,
        ),
        AbilityReview(
            dodge['id'], all(item['passed'] for item in dodge_scenarios),
            dodge_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '캐치 더 문 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _cb01_at_015_engine(
    definition, card_snapshot, owner, *, source_zone='lumen',
    numbered_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    event_card = _cb01_review_card(
        'REVIEW-CB01-015-EVENT', owner,
        f'{owner}-cb01-015-event-card',
    )
    event_card.update({'face_up': True, 'hit': '콤보', 'counter': '콤보'})
    engine._zone(owner, 'battle').append(event_card)
    _cb01_register_cards(engine, [event_card])
    engine.engine_state['battle'] = {
        owner: {
            'instance_id': event_card['instance_id'],
            'card': event_card,
        },
        other: {
            'instance_id': opposing['instance_id'],
            'card': opposing,
        },
        'actual_damage_received': {side: 0 for side in PLAYER_SIDES},
    }
    return engine, source, event_card, opposing


def _run_cb01_at_015_discard_scenario(
    definition, card_snapshot, owner, *, hand_count=2,
    selected_index=1, event_type='hit', event_owner=None,
    source_zone='lumen', numbered_negated=False,
):
    event_owner = event_owner or owner
    engine, source, event_card, opposing = _cb01_at_015_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    cards = [
        _cb01_review_card(
            f'REVIEW-CB01-015-HAND-{index + 1}', owner,
            f'{owner}-cb01-015-hand-{index + 1}',
        )
        for index in range(hand_count)
    ]
    engine._zone(owner, 'hand').extend(cards)
    _cb01_register_cards(engine, cards)
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': event_card['instance_id'],
        'source_card': copy.deepcopy(event_card),
        'opponent_card': copy.deepcopy(opposing),
    })
    decision = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    options = [
        str(option.get('id')) for option in decision.get('options') or []
    ]
    chosen = None
    if decision.get('kind') == 'effect_choice' and options:
        chosen = (
            cards[selected_index]['instance_id']
            if 0 <= selected_index < len(cards)
            and cards[selected_index]['instance_id'] in options
            else options[0]
        )
        engine._submit_decision(owner, decision.get('id'), [chosen])
        engine._continue()
    return {
        'decision_kind': decision.get('kind'),
        'options': options, 'chosen': chosen,
        'hand_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'hand')
            if card.get('instance_id') in {
                item['instance_id'] for item in cards
            }
        ),
        'discarded_ids': sorted(
            card.get('instance_id') for zone in ('list', 'break')
            for card in engine._zone(owner, zone)
            if card.get('instance_id') in {
                item['instance_id'] for item in cards
            }
        ),
        'resolved': _st2_resolution_count(engine, 'cb01-at-015-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_015_combo_scenario(
    definition, card_snapshot, owner, *, hand_count=3,
    combo_number=1, event_owner=None, source_zone='lumen',
    numbered_negated=False, thief_extension=False,
    event_type='combo',
):
    event_owner = event_owner or owner
    engine, source, event_card, opposing = _cb01_at_015_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    hand_cards = [
        _cb01_review_card(
            f'REVIEW-CB01-015-COMBO-HAND-{index + 1}', owner,
            f'{owner}-cb01-015-combo-hand-{index + 1}',
        )
        for index in range(hand_count)
    ]
    list_card = _cb01_review_card(
        'REVIEW-CB01-015-COMBO-LIST', owner,
        f'{owner}-cb01-015-combo-list',
    )
    engine._zone(owner, 'hand').extend(hand_cards)
    engine._zone(owner, 'list').append(list_card)
    _cb01_register_cards(engine, [*hand_cards, list_card])
    combo = {
        'owner': owner, 'source': event_card['instance_id'],
        'special': False, 'used': [], 'next_penalty': 100,
        'last_speed': 7, 'proposal_submitted': False,
    }
    engine.engine_state['combo'] = combo
    engine.engine_state['step'] = 'combo'
    if thief_extension:
        engine.add_modifier({
            'op': 'modify_combo', 'controller': owner, 'player': owner,
            'allow_zones': ['list'],
            'duration': 'battle', 'source': 'review-thief-gimmick',
        })
    engine._fire(event_type, {
        'controller': event_owner, 'combo_number': combo_number,
        'source_card_instance_id': event_card['instance_id'],
        'source_card': copy.deepcopy(event_card),
        'opponent_card': copy.deepcopy(opposing),
    })
    live_list = engine._find_card(list_card['instance_id'])
    return {
        'hand_count': len(engine._zone(owner, 'hand')),
        'maximum': engine._combo_maximum(owner, combo),
        'list_allowed': engine._combo_zone_allowed(
            owner, live_list, 'list', combo,
        ),
        'combo_modifiers': sum(
            item.get('op') == 'modify_combo'
            for item in engine.engine_state.get('modifiers') or []
        ),
        'resolved': _st2_resolution_count(engine, 'cb01-at-015-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_015_acquire_scenario(
    definition, card_snapshot, owner, *, list_count=4,
    selected_indices=(0, 2, 3), event_owner=None,
    combo_owner=None, source_zone='lumen', numbered_negated=False,
    event_type='combo_end', trait_count=0,
):
    event_owner = event_owner or owner
    combo_owner = combo_owner or event_owner
    engine, source, event_card, opposing = _cb01_at_015_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    cards = [
        _cb01_review_card(
            f'REVIEW-CB01-015-LIST-{index + 1}', owner,
            f'{owner}-cb01-015-list-{index + 1}',
        )
        for index in range(list_count)
    ]
    traits = [
        _cb01_review_card(
            f'REVIEW-CB01-015-TRAIT-{index + 1}', owner,
            f'{owner}-cb01-015-trait-{index + 1}', card_type='특성',
        )
        for index in range(trait_count)
    ]
    engine._zone(owner, 'list').extend([*cards, *traits])
    _cb01_register_cards(engine, [*cards, *traits])
    engine._fire(event_type, {
        'controller': event_owner, 'combo_owner': combo_owner,
        'source_card_instance_id': event_card['instance_id'],
        'source_card': copy.deepcopy(event_card),
        'opponent_card': copy.deepcopy(opposing),
    })
    decision = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    options = [
        str(option.get('id')) for option in decision.get('options') or []
    ]
    selected_ids = [
        cards[index]['instance_id'] for index in selected_indices
        if 0 <= index < len(cards)
        and cards[index]['instance_id'] in options
    ]
    if decision.get('kind') == 'effect_choice':
        engine._submit_decision(owner, decision.get('id'), selected_ids)
        engine._continue()
    return {
        'decision_kind': decision.get('kind'),
        'options': options, 'selected_ids': selected_ids,
        'hand_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'hand')
            if card.get('instance_id') in {
                item['instance_id'] for item in cards
            }
        ),
        'battle_card_offered': event_card['instance_id'] in options,
        'trait_offered': any(
            card['instance_id'] in options for card in traits
        ),
        'resolved': _st2_resolution_count(engine, 'cb01-at-015-n3'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_015_recovery_scenario(
    definition, card_snapshot, owner, *, damage_received=500,
    phase='recovery', source_zone='lumen', numbered_negated=False,
):
    engine, source, _event_card, _opposing = _cb01_at_015_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.state['phase'] = phase
    engine.engine_state.setdefault('turn_damage_received', {})[owner] = (
        damage_received
    )
    engine._fire('phase_start', {'phase': phase})
    location = engine._find_location(source['instance_id'])
    return {
        'source_zone': location[1] if location else None,
        'resolved': _st2_resolution_count(engine, 'cb01-at-015-n4'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


