def _run_cb01_at_027_counter_scenario(
    definition, card_snapshot, owner, *, yin=1, yang=1,
    selected='yin', accept=True, event_type='hit', event_owner=None,
    source_zone='battle', numbered_negated=False, run_recovery=True,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.change_counter(owner, 'yin', yin, absolute=True)
    engine.change_counter(owner, 'yang', yang, absolute=True)
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
        'combo_number': 1,
    })
    optional = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    branch = {}
    if optional.get('kind') == 'optional_effect':
        engine._submit_decision(
            owner, optional.get('id'),
            ['accept' if accept else 'decline'],
        )
        engine._continue()
        branch = copy.deepcopy(
            engine.engine_state.get('pending_decision') or {}
        )
        branch_options = [
            str(option.get('id'))
            for option in branch.get('options') or []
        ]
        if (
            accept and branch.get('kind') == 'effect_branch'
            and selected in branch_options
        ):
            engine._submit_decision(
                owner, branch.get('id'), [selected],
            )
            engine._continue()
    branch_options = [
        str(option.get('id')) for option in branch.get('options') or []
    ]
    fp_before_recovery = engine.state['players'][owner]['fp']
    scheduled_before_recovery = len(
        engine.engine_state.get('scheduled') or []
    )
    if run_recovery:
        engine.state['phase'] = 'recovery'
        engine._fire('phase_start', {
            'phase': 'recovery', 'controller': owner,
        })
    return {
        'optional_kind': optional.get('kind'),
        'branch_kind': branch.get('kind'),
        'branch_options': branch_options,
        'yin': _pmp_review_counter(engine, owner, 'yin'),
        'yang': _pmp_review_counter(engine, owner, 'yang'),
        'damage': engine.card_stat(source, 'damage', owner),
        'fp_before_recovery': fp_before_recovery,
        'fp_after_recovery': engine.state['players'][owner]['fp'],
        'scheduled_before_recovery': scheduled_before_recovery,
        'scheduled_after_recovery': len(
            engine.engine_state.get('scheduled') or []
        ),
        'resolved': _st2_resolution_count(engine, 'cb01-at-027-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


