def _review_cb01_at_012_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-012':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    function = by_id.get('cb01-at-012-function')
    grab_negated = by_id.get('cb01-at-012-n1')
    down_stance = {
        'op': 'has_state', 'player': {'controller': True},
        'state': 'down_stance',
    }
    own_event = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'controller': True},
    }
    valid = bool(
        extra_root == {'play_condition'}
        and set(by_id) == {
            'cb01-at-012-function', 'cb01-at-012-n1',
        }
        and (definition.get('source_refs') or {}).get('qna_ids') == []
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == []
            for ability in abilities
        )
        and definition.get('play_condition') == down_stance
        and function and function.get('kind') == 'function'
        and function.get('mode') == 'continuous'
        and function.get('timing') == 'function'
        and function.get('active_zones') == ['battle']
        and not function.get('trigger')
        and function.get('effects') == [{
            'op': 'prevent', 'kind': 'guard',
            'player': {'opponent': True}, 'duration': 'continuous',
        }]
        and grab_negated and grab_negated.get('kind') == 'effect'
        and grab_negated.get('mode') == 'mandatory'
        and grab_negated.get('timing') == 'result'
        and grab_negated.get('active_zones') == ['battle']
        and grab_negated.get('trigger') == {'event': 'grab_negated'}
        and grab_negated.get('condition') == {
            'op': 'all', 'conditions': [own_event, down_stance],
        }
        and grab_negated.get('effects') == [{
            'op': 'change_fp', 'player': {'opponent': True}, 'amount': 5,
        }]
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CB01-AT-012', 'name': '테크니컬 도저',
            'type': '공격', 'frame': 11, 'damage': 400,
            'pos': '하단', 'body': '손', 'special': '그랩',
            'hit': '2', 'guard': 'X', 'counter': '콤보',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 4, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb01-at-012', False,
                reason='테크니컬 도저의 다운 사용 조건·방어 금지·그랩 무효 FP 정의가 일치하지 않습니다.',
            )], 'CB01-AT-012 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    function_scenarios = _st2_scenarios(
        _run_cb01_at_012_function_scenario,
        definition, card_snapshot, (
            ('p1-down-allows-use-and-blocks-opponent-guard', 'p1', {}, {
                'ready_allowed': True, 'combo_allowed': True,
                'opponent_guard_blocked': True,
                'owner_guard_blocked': False,
            }),
            ('p2-down-allows-use-and-blocks-opponent-guard', 'p2', {}, {
                'ready_allowed': True, 'combo_allowed': True,
                'opponent_guard_blocked': True,
                'owner_guard_blocked': False,
            }),
            ('without-down-use-is-illegal-but-numberless-guard-lock-remains', 'p1', {
                'down_stance': False,
            }, {
                'ready_allowed': False, 'combo_allowed': False,
                'opponent_guard_blocked': True,
            }),
            ('numbered-negation-keeps-numberless-function', 'p2', {
                'numbered_negated': True,
            }, {
                'ready_allowed': True,
                'opponent_guard_blocked': True,
            }),
            ('source-outside-battle-does-not-block-guard', 'p1', {
                'source_zone': 'hand',
            }, {
                'ready_allowed': True,
                'opponent_guard_blocked': False,
            }),
        ),
    )
    grab_scenarios = _st2_scenarios(
        _run_cb01_at_012_grab_scenario,
        definition, card_snapshot, (
            ('p1-down-grab-negated-gives-opponent-five-fp', 'p1', {}, {
                'opponent_fp': 5, 'resolved': 1,
            }),
            ('p2-down-grab-negated-adds-five-to-existing-fp', 'p2', {
                'opponent_fp': 2,
            }, {'opponent_fp': 7, 'resolved': 1}),
            ('without-down-does-not-give-fp', 'p1', {
                'down_stance': False,
            }, {'opponent_fp': 0, 'resolved': 0}),
            ('wrong-event-does-not-give-fp', 'p2', {
                'event_type': 'after_use',
            }, {'opponent_fp': 0, 'resolved': 0}),
            ('opponent-owned-event-does-not-give-fp', 'p1', {
                'event_owner': 'p2',
            }, {'opponent_fp': 0, 'resolved': 0}),
            ('numbered-negation-disables-grab-effect', 'p2', {
                'numbered_negated': True,
            }, {'opponent_fp': 0, 'resolved': 0}),
            ('source-outside-battle-does-not-give-fp', 'p1', {
                'source_zone': 'hand',
            }, {'opponent_fp': 0, 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            function['id'],
            all(item['passed'] for item in function_scenarios),
            function_scenarios,
        ),
        AbilityReview(
            grab_negated['id'],
            all(item['passed'] for item in grab_scenarios),
            grab_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '테크니컬 도저 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_pmp_at_037_function_scenario(
    definition, card_snapshot, owner, *, yang_count=4,
    numbered_negated=False,
):
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone='hand',
        numbered_negated=numbered_negated,
    )
    engine.state['players'][owner]['passive_state']['yang'] = {
        'count': yang_count, 'label': '양',
    }
    combo = {
        'owner': owner, 'source': opposing['instance_id'], 'used': [],
        'last_speed': 11, 'next_penalty': 100,
        'proposal_submitted': False,
    }
    rules = engine._combo_rules(owner, source, combo)
    return {
        'ready_allowed': engine._card_use_allowed(source, owner, 'ready'),
        'combo_allowed': engine._combo_card_legal(
            owner, source, combo, selected_speed=12,
        ),
        'ignore_damage_penalty': any(
            rule.get('ignore_damage_penalty') for rule in rules
        ),
        'applied_penalty': engine._combo_applied_penalty(
            owner, source, combo, 100, rules=rules,
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_pmp_at_037_damage_scenario(
    definition, card_snapshot, owner, *, yang_count=4,
    event_type='hit', event_owner=None, source_zone='battle',
    numbered_negated=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.state['players'][owner]['passive_state']['yang'] = {
        'count': yang_count, 'label': '양',
    }
    before_hp = int(engine.state['players'][other]['hp'])
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    return {
        'opponent_hp_loss': (
            before_hp - int(engine.state['players'][other]['hp'])
        ),
        'yang_count': int(
            engine.state['players'][owner]['passive_state']
            .get('yang', {}).get('count') or 0
        ),
        'damage_events': sum(
            event.get('type') == 'damage_dealt'
            for event in engine.events
        ),
        'resolved': _st2_resolution_count(engine, 'pmp-at-037-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_pmp_at_037_cleanup_scenario(
    definition, card_snapshot, owner, *, yin_count=3,
    combo_active=True, event_type='after_use', event_owner=None,
    source_zone='battle', numbered_negated=False,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    engine.state['players'][owner]['passive_state']['yin'] = {
        'count': yin_count, 'label': '음',
    }
    if combo_active:
        engine.engine_state['combo'] = {
            'owner': owner, 'source': source['instance_id'], 'used': [],
            'last_speed': 12, 'next_penalty': 100,
            'proposal_submitted': False,
        }
        engine.engine_state['step'] = 'combo'
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    engine.change_counter(owner, 'yin', 2)
    engine._expire_modifiers('turn')
    engine.change_counter(owner, 'yin', 1)
    return {
        'yin_count': int(
            engine.state['players'][owner]['passive_state']
            .get('yin', {}).get('count') or 0
        ),
        'combo_active': bool(engine.engine_state.get('combo')),
        'counter_gain_preventions': sum(
            replacement.get('op') == 'prevent'
            and replacement.get('kind') == 'counter_gain'
            and (replacement.get('where') or {}).get('counter') == 'yin'
            for replacement in engine.engine_state.get('replacements') or []
        ),
        'resolved': _st2_resolution_count(engine, 'pmp-at-037-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


