def _run_crs_at_006_hand_break_scenario(
    definition, card_snapshot, owner, *, hand_count=2, selected_index=0,
    combat_sense_index=None, event_type='use', event_owner=None,
    source_zone='battle', numbered_negated=False, initial_fp=0,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, owner_fp=initial_fp,
    )
    candidates = []
    for index in range(hand_count):
        is_combat_sense = index == combat_sense_index
        code = 'CRS-AT-052' if is_combat_sense else (
            f'REVIEW-CRS-006-HAND-{index + 1}'
        )
        card = _card(code, owner, f'{owner}-crs-006-hand-{index + 1}')
        card.update({
            'name': '컴뱃센스' if is_combat_sense else f'검토 패 {index + 1}',
            'type': '수비' if is_combat_sense else '특수 공격',
            'frame': None if is_combat_sense else 7,
            'damage': None if is_combat_sense else 300,
            'pos': None if is_combat_sense else '상단',
            'body': None, 'special': None, 'face_up': False,
        })
        candidates.append(card)
        engine._zone(owner, 'hand').append(card)
        engine.ruleset['cards'][code] = {
            **copy.deepcopy(card),
            'effect_definition': (
                _crs_at_006_combat_sense_definition()
                if is_combat_sense else _st2_no_effect_definition()
            ),
        }
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    decision = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    options = sorted(
        str(option.get('id')) for option in decision.get('options') or []
    )
    chosen = None
    if decision.get('kind') == 'effect_choice' and options:
        requested = (
            candidates[selected_index]['instance_id']
            if 0 <= selected_index < len(candidates) else None
        )
        chosen = requested if requested in options else options[0]
        engine._submit_decision(owner, decision.get('id'), [chosen])
        engine._continue()
    return {
        'decision_kind': decision.get('kind'), 'options': options,
        'chosen': chosen,
        'hand_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'hand')
            if card.get('instance_id') in {
                candidate['instance_id'] for candidate in candidates
            }
        ),
        'break_ids': sorted(
            card.get('instance_id') for card in engine._zone(owner, 'break')
            if card.get('instance_id') in {
                candidate['instance_id'] for candidate in candidates
            }
        ),
        'fp': int(engine.state['players'][owner]['fp']),
        'resolved': _st2_resolution_count(engine, 'crs-at-006-n1'),
        'combat_sense_resolved': _st2_resolution_count(
            engine, 'crs-at-052-n1',
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_crs_at_006_combo_scenario(
    definition, card_snapshot, owner, *, accept=True, event_type='combo',
    event_owner=None, source_zone='battle', numbered_negated=False,
    initial_ember=0,
):
    event_owner = event_owner or owner
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated,
    )
    if initial_ember:
        engine.state['players'][owner]['passive_state']['ember'] = {
            'count': initial_ember, 'label': '불씨',
        }
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    decision = copy.deepcopy(
        engine.engine_state.get('pending_decision') or {}
    )
    if decision.get('kind') == 'optional_effect':
        engine._submit_decision(
            owner, decision.get('id'),
            ['accept' if accept else 'decline'],
        )
        engine._continue()
    location = engine._find_location(source['instance_id'])
    return {
        'decision_kind': decision.get('kind'),
        'source_zone': location[1] if location else None,
        'ember': int(
            engine.state['players'][owner]['passive_state']
            .get('ember', {}).get('count') or 0
        ),
        'resolved': _st2_resolution_count(engine, 'crs-at-006-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_crs_at_006_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CRS-AT-006':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    on_use = by_id.get('crs-at-006-n1')
    combo = by_id.get('crs-at-006-n2')
    own_event = {
        'op': 'equals', 'left': 'context.event_controller',
        'right': {'controller': True},
    }
    selector = {
        'kind': 'card', 'player': {'controller': True},
        'zones': ['hand'], 'min': 1, 'max': 1,
        'as_operation': 'break_card',
    }
    hand_choice = ((on_use or {}).get('effects') or [{}])[0]
    valid = bool(
        not extra_root
        and set(by_id) == {'crs-at-006-n1', 'crs-at-006-n2'}
        and (definition.get('source_refs') or {}).get('qna_ids') == [523]
        and all(
            (ability.get('source_refs') or {}).get('qna_ids') == [523]
            for ability in abilities
        )
        and on_use and on_use.get('kind') == 'effect'
        and on_use.get('mode') == 'mandatory'
        and on_use.get('timing') == 'use'
        and on_use.get('active_zones') == ['battle']
        and on_use.get('trigger') == {'event': 'use'}
        and on_use.get('condition') == own_event
        and on_use.get('availability_selector') == selector
        and hand_choice.get('op') == 'request_choice'
        and hand_choice.get('selector') == selector
        and hand_choice.get('selection_key') == 'crs_at_006_hand_break'
        and hand_choice.get('default') == []
        and hand_choice.get('then') == [{
            'op': 'break_card',
            'selection_key': 'crs_at_006_hand_break',
            'result_key': 'crs_at_006_hand_broken',
        }]
        and combo and combo.get('kind') == 'effect'
        and combo.get('mode') == 'optional'
        and combo.get('timing') == 'combo'
        and combo.get('active_zones') == ['battle']
        and combo.get('trigger') == {'event': 'combo'}
        and combo.get('condition') == own_event
        and [effect.get('op') for effect in combo.get('effects') or []]
        == ['break_card', 'conditional']
        and (combo.get('effects') or [{}])[0].get('result_key')
        == 'crs_at_006_self_broken'
        and (combo.get('effects') or [{}])[0].get('continue_resolution')
        is True
        and (((combo.get('effects') or [{}, {}])[1].get('then') or [{}])[0])
        == {
            'op': 'change_counter', 'player': {'controller': True},
            'counter': 'ember', 'amount': 1, 'min': 0,
        }
        and _st2_snapshot_matches(card_snapshot, {
            'code': 'CRS-AT-006', 'name': '작열대선풍',
            'type': '공격', 'frame': 9, 'damage': 600,
            'pos': '중단', 'body': None, 'special': None,
            'hit': '콤보', 'guard': '-8', 'counter': '콤보',
            'g_top': None, 'g_mid': None, 'g_bot': None,
            'character_id': 11, 'ultimate': False,
        })
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'crs-at-006', False,
                reason='작열대선풍의 강제 패 선택·자기 브레이크·불씨 정의가 일치하지 않습니다.',
            )], 'CRS-AT-006 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    hand_scenarios = _st2_scenarios(
        _run_crs_at_006_hand_break_scenario,
        definition, card_snapshot, (
            ('p1-chooses-first-of-two-hand-cards', 'p1', {}, {
                'decision_kind': 'effect_choice',
                'chosen': 'p1-crs-006-hand-1',
                'break_ids': ['p1-crs-006-hand-1'],
                'hand_ids': ['p1-crs-006-hand-2'],
                'resolved': 1, 'pending': False,
            }),
            ('p2-chooses-second-of-two-hand-cards', 'p2', {
                'selected_index': 1,
            }, {
                'chosen': 'p2-crs-006-hand-2',
                'break_ids': ['p2-crs-006-hand-2'], 'resolved': 1,
            }),
            ('no-legal-hand-card-opens-no-impossible-choice', 'p1', {
                'hand_count': 0,
            }, {'decision_kind': None, 'resolved': 0, 'pending': False}),
            ('qna523-breaking-combat-sense-gains-fp-immediately', 'p2', {
                'combat_sense_index': 1, 'selected_index': 1,
                'initial_fp': 2,
            }, {
                'chosen': 'p2-crs-006-hand-2', 'fp': 3,
                'combat_sense_resolved': 1, 'resolved': 1,
            }),
            ('opponent-use-event-does-not-break-owner-hand', 'p1', {
                'event_owner': 'p2',
            }, {'decision_kind': None, 'break_ids': [], 'resolved': 0}),
            ('numbered-negation-disables-use-cost', 'p2', {
                'numbered_negated': True,
            }, {'decision_kind': None, 'break_ids': [], 'resolved': 0}),
            ('source-outside-battle-is-inactive', 'p1', {
                'source_zone': 'hand',
            }, {'decision_kind': None, 'break_ids': [], 'resolved': 0}),
        ),
    )
    combo_scenarios = _st2_scenarios(
        _run_crs_at_006_combo_scenario,
        definition, card_snapshot, (
            ('p1-accepts-break-and-gains-one-ember', 'p1', {}, {
                'decision_kind': 'optional_effect',
                'source_zone': 'break', 'ember': 1,
                'resolved': 1, 'pending': False,
            }),
            ('p2-adds-ember-to-existing-counter', 'p2', {
                'initial_ember': 2,
            }, {'source_zone': 'break', 'ember': 3, 'resolved': 1}),
            ('decline-keeps-card-and-gains-no-ember', 'p1', {
                'accept': False,
            }, {'source_zone': 'battle', 'ember': 0, 'resolved': 0}),
            ('wrong-event-does-not-offer-effect', 'p2', {
                'event_type': 'hit',
            }, {'decision_kind': None, 'source_zone': 'battle', 'resolved': 0}),
            ('opponent-combo-does-not-offer-effect', 'p1', {
                'event_owner': 'p2',
            }, {'decision_kind': None, 'source_zone': 'battle', 'resolved': 0}),
            ('numbered-negation-disables-combo-effect', 'p2', {
                'numbered_negated': True,
            }, {'decision_kind': None, 'source_zone': 'battle', 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            on_use['id'], all(item['passed'] for item in hand_scenarios),
            hand_scenarios,
        ),
        AbilityReview(
            combo['id'], all(item['passed'] for item in combo_scenarios),
            combo_scenarios,
        ),
    ]
    passed = all(
        review.passed and len(review.scenarios) >= 3 for review in reviews
    )
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '작열대선풍 카드별 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _run_crs_at_007_before_scenario(
    definition, card_snapshot, owner, *, ember=0, opponent_frame=8,
    opponent_pos='중단', opponent_fp=0, source_zone='battle',
    numbered_negated=False, event_type='before_judgment', event_owner=None,
):
    event_owner = event_owner or owner
    other = 'p2' if owner == 'p1' else 'p1'
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner, source_zone=source_zone,
        numbered_negated=numbered_negated, opponent_frame=opponent_frame,
        opponent_pos=opponent_pos, opponent_fp=opponent_fp,
    )
    if ember:
        engine.state['players'][owner]['passive_state']['ember'] = {
            'count': ember, 'label': '불씨',
        }
    engine._fire(event_type, {
        'controller': event_owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': copy.deepcopy(source),
        'opponent_card': copy.deepcopy(opposing),
        'source_battle_card_only': True,
    })
    live = (engine.engine_state.get('battle') or {}).get(owner, {}).get(
        'card', source,
    )
    special_result = _special_result(live, opposing.get('pos'))
    return {
        'speed': engine.card_stat(live, 'frame', owner, include_fp=False),
        'special': live.get('special'),
        'special_result': special_result,
        'dodge_allowed': bool(
            special_result == 'dodge'
            and engine._defense_judgment_allowed(
                live, opposing, 'dodge', other,
            )
        ),
        'reference_opponent_speed': engine.card_stat(
            opposing, 'frame', other, include_fp=False,
        ),
        'fp_opponent_speed': engine.card_stat(
            opposing, 'frame', other, include_fp=True,
        ),
        'resolved': _st2_resolution_count(engine, 'crs-at-007-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _crs_at_007_gear_change_definition():
    return {
        'schema_version': 1, 'reviewed': True, 'no_effect': False,
        'source_refs': {'rulebook_pages': [48, 49], 'qna_ids': [669]},
        'abilities': [{
            'id': 'unc-at-018-n1', 'kind': 'effect',
            'mode': 'mandatory', 'timing': 'before_judgment',
            'visibility': 'public', 'active_zones': ['battle'],
            'trigger': {'event': 'before_judgment'},
            'condition': {
                'op': 'card_matches',
                'card': {'path': 'context.opponent_card'},
                'where': {'battle_judgment_contains': '회피'},
            },
            'effects': [{
                'op': 'modify_judgment',
                'player': {'controller': True},
                'field': 'pos', 'value': '중단',
            }],
        }],
    }


def _run_crs_at_007_priority_scenario(
    definition, card_snapshot, owner, *, priority_owner=True,
):
    other = 'p2' if owner == 'p1' else 'p1'
    priority = owner if priority_owner else other
    engine, source, opposing = _st2_battle_engine(
        definition, card_snapshot, owner,
        opponent_frame=6, opponent_damage=400,
        opponent_pos='상단', opponent_body='손',
        opponent_definition=_crs_at_007_gear_change_definition(),
        priority=priority,
    )
    engine.state['phase'] = 'battle'
    engine.state['players'][owner]['passive_state']['ember'] = {
        'count': 9, 'label': '불씨',
    }
    engine._battle_trigger('before_judgment')
    source_live = engine.engine_state['battle'][owner]['card']
    gear_live = engine.engine_state['battle'][other]['card']
    result = _special_result(source_live, gear_live.get('pos'))
    return {
        'priority': priority, 'gear_position': gear_live.get('pos'),
        'source_special': source_live.get('special'),
        'dodge_result': result,
        'dodge_allowed': bool(
            result == 'dodge'
            and engine._defense_judgment_allowed(
                source_live, gear_live, 'dodge', other,
            )
        ),
        'source_resolved': _st2_resolution_count(
            engine, 'crs-at-007-n1',
        ),
        'gear_resolved': _st2_resolution_count(engine, 'unc-at-018-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


