def _run_cb01_at_009_speed_scenario(
    definition, card_snapshot, owner, *, source_zone='lumen',
    numbered_negated=False, effect_source_code='ST2-PS1',
):
    target = _card(
        'REVIEW-CB01-AT-009-TARGET', owner,
        f'{owner}-cb01-at-009-target',
    )
    target.update({'frame': 6, 'damage': 400, 'face_up': True})
    engine, _source, _opposing = _cb01_final_engine(
        definition, card_snapshot, owner, source_zone=source_zone, hp=2000,
        numbered_negated=numbered_negated,
        extra_cards=[('battle', target, None)],
    )
    engine._refresh_continuous_rules()
    live_target = engine._find_card(target['instance_id'])
    effect_source = {
        'instance_id': f'{owner}-cb01-at-009-stat-source',
        'code': effect_source_code, 'owner': owner, 'type': '특성',
    }
    context = {
        'controller': owner,
        'source_card': effect_source,
        'source_card_instance_id': effect_source['instance_id'],
        'event_card': live_target,
    }
    engine.resolver.execute_effects([
        {
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'frame', 'amount': 2, 'duration': 'battle',
            'target_card': 'event_card',
        },
        {
            'op': 'modify_stat', 'player': {'controller': True},
            'stat': 'damage', 'amount': 200, 'duration': 'battle',
            'target_card': 'event_card',
        },
    ], context)
    return {
        'frame': engine.card_stat(live_target, 'frame', owner),
        'damage': engine.card_stat(live_target, 'damage', owner),
        'immunity_count': sum(
            item.get('op') == 'grant_effect_immunity'
            for item in engine.engine_state.get('replacements') or []
        ),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_009_release_scenario(
    definition, card_snapshot, owner, *, with_all_in=True,
    choice='place_all_in', event_state='charge', numbered_negated=False,
):
    all_in = _card(
        'AWL-SP-001', owner, f'{owner}-cb01-at-009-all-in',
    )
    all_in.update({
        'name': '올인 차지', 'type': '특수', 'special': '특수',
        'frame': None, 'damage': None, 'face_up': False,
    })
    extras = [('side', all_in, None)] if with_all_in else []
    engine, source, _opposing = _cb01_final_engine(
        definition, card_snapshot, owner, source_zone='lumen', hp=2000,
        numbered_negated=numbered_negated, extra_cards=extras,
    )
    engine._fire('state_lost', {
        'controller': owner, 'player': owner, 'state': event_state,
    })
    decisions = []
    if engine.engine_state.get('pending_decision'):
        decision = engine.engine_state['pending_decision']
        options = [str(item.get('id')) for item in decision.get('options') or []]
        selected = choice if choice in options else options[0]
        decisions.append(_cb01_final_submit(engine, owner, selected))
    if engine.engine_state.get('pending_decision'):
        decisions.append(_cb01_final_submit(
            engine, owner, all_in['instance_id'],
        ))
    source_location = engine._find_location(source['instance_id'])
    all_in_location = engine._find_location(all_in['instance_id'])
    return {
        'decisions': decisions,
        'source_zone': source_location[1] if source_location else None,
        'all_in_zone': all_in_location[1] if all_in_location else None,
        'resolved': _st2_resolution_count(engine, 'cb01-at-009-n2-release'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


