def _run_cb01_at_022_state_scenario(
    definition, card_snapshot, owner, *, event_owner=None,
    numbered_negated=False, recovery_ends=0,
):
    engine, source, opposing = _cb01_final_engine(
        definition, card_snapshot, owner, source_zone='battle', hp=2000,
        numbered_negated=numbered_negated,
    )
    actor = event_owner or owner
    event_source = source if actor == owner else opposing
    engine._fire('use', {
        'controller': actor,
        'source_card_instance_id': event_source['instance_id'],
        'source_card': event_source,
    })
    for _index in range(recovery_ends):
        engine._expire_state_durations('phase_end', phase='recovery')
    state_entry = engine.state['players'][owner]['passive_state'].get(
        'dark_night', {}
    )
    expiration = next((
        item for item in engine.engine_state.get('state_expirations') or []
        if item.get('player') == owner and item.get('state') == 'dark_night'
    ), None)
    return {
        'active': bool(state_entry.get('value')),
        'remaining': (expiration or {}).get('remaining'),
        'resolved': _st2_resolution_count(engine, 'cb01-at-022-n1'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_022_get_scenario(
    definition, card_snapshot, owner, *, dark_night=True,
    event_type='hit', numbered_negated=False, blocked=False,
    fire_twice=False,
):
    other = 'p2' if owner == 'p1' else 'p1'
    list_cards = []
    for index in range(1 if blocked else 3):
        card = _card(
            f'REVIEW-CB01-AT-022-LIST-{index}', other,
            f'{other}-cb01-at-022-list-{index}',
        )
        card.update({'name': f'상대 리스트 {index}', 'face_up': True})
        list_cards.append(card)
    engine, source, _opposing = _cb01_final_engine(
        definition, card_snapshot, owner, source_zone='battle', hp=2000,
        numbered_negated=numbered_negated,
        extra_cards=[('list', card, None) for card in list_cards],
    )
    if dark_night:
        engine.state['players'][owner]['passive_state']['dark_night'] = {
            'value': True,
        }
    event_context = {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': source,
    }
    engine._fire(event_type, event_context)
    if fire_twice:
        engine._fire('combo', event_context)
    scheduled_before_get = len(engine.engine_state.get('scheduled') or [])
    if blocked:
        engine.engine_state.setdefault('replacements', []).append({
            'op': 'prevent', 'kind': 'get_card', 'player': other,
            'where': {'instance_id': list_cards[0]['instance_id']},
            'duration': 'turn', 'controller': owner,
            'source': source['instance_id'],
        })
    engine.state['phase'] = 'get'
    engine.engine_state.update({
        'step': 'get_actions', 'get_order': [other, owner],
        'current_actor': other, 'get_done': [],
    })
    engine._fire('phase_start', {'phase': 'get'})
    engine._continue()
    hand = engine._zone(other, 'hand')
    remaining_list = engine._zone(other, 'list')
    return {
        'scheduled_before_get': scheduled_before_get,
        'hand_count': len(hand), 'list_count': len(remaining_list),
        'public_hand_count': sum(bool(card.get('face_up')) for card in hand),
        'face_down_list_count': sum(not card.get('face_up') for card in remaining_list),
        'get_done': other in (engine.engine_state.get('get_done') or []),
        'resolved': _st2_resolution_count(engine, 'cb01-at-022-n2'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_022_break_scenario(
    definition, card_snapshot, owner, *, event_type='after_use',
    numbered_negated=False,
):
    engine, source, _opposing = _cb01_final_engine(
        definition, card_snapshot, owner, source_zone='battle', hp=2000,
        numbered_negated=numbered_negated,
    )
    engine._fire(event_type, {
        'controller': owner,
        'source_card_instance_id': source['instance_id'],
        'source_card': source,
    })
    location = engine._find_location(source['instance_id'])
    return {
        'source_zone': location[1] if location else None,
        'resolved': _st2_resolution_count(engine, 'cb01-at-022-n3'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb01_at_022_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-022':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    state = by_id.get('cb01-at-022-n1')
    get_effect = by_id.get('cb01-at-022-n2')
    broken = by_id.get('cb01-at-022-n3')
    get_nodes = list(_effect_nodes((get_effect or {}).get('effects') or []))
    valid = bool(
        extra_root == {'play_condition'}
        and definition.get('play_condition') == {
            'op': 'lte', 'left': 'context.controller_hp', 'right': 2000,
        }
        and set(by_id) == {
            'cb01-at-022-n1', 'cb01-at-022-n2', 'cb01-at-022-n3',
        }
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == [652, 659, 660, 661, 666, 674]
        and state and state.get('trigger') == {'event': 'use'}
        and any(
            node.get('op') == 'gain_state'
            and node.get('state') == 'dark_night'
            and node.get('expires') == {
                'event': 'phase_end', 'phase': 'recovery', 'occurrences': 2,
            }
            for node in _effect_nodes(state.get('effects') or [])
        )
        and get_effect and get_effect.get('trigger') == {
            'event': 'hit', 'events': ['hit', 'counter', 'combo'],
        }
        and any(node.get('op') == 'random_select' for node in get_nodes)
        and any(
            node.get('op') == 'move_card'
            and node.get('as_get') is True
            for node in get_nodes
        )
        and any(node.get('op') == 'replace_get' for node in get_nodes)
        and broken and broken.get('trigger') == {'event': 'after_use'}
        and broken.get('effects') == [{'op': 'break_card'}]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb01-at-022', False,
                reason='블랙아웃의 상태·무작위 Get·사용 후 브레이크 정의가 일치하지 않습니다.',
            )], 'CB01-AT-022 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    state_scenarios = _cb01_final_scenarios(
        _run_cb01_at_022_state_scenario, definition, card_snapshot, (
            ('owner-p1-gains-dark-night-for-two-recoveries', 'p1', {}, {
                'active': True, 'remaining': 2, 'resolved': 1,
            }),
            ('owner-p2-state-remains-after-first-recovery', 'p2', {
                'recovery_ends': 1,
            }, {'active': True, 'remaining': 1, 'resolved': 1}),
            ('state-expires-after-second-recovery', 'p1', {
                'recovery_ends': 2,
            }, {'active': False, 'remaining': None, 'resolved': 1}),
            ('opponent-use-does-not-grant-state', 'p1', {
                'event_owner': 'p2',
            }, {'active': False, 'remaining': None, 'resolved': 0}),
            ('numbered-negation-disables-state', 'p2', {
                'numbered_negated': True,
            }, {'active': False, 'remaining': None, 'resolved': 0}),
        ),
    )
    get_scenarios = _cb01_final_scenarios(
        _run_cb01_at_022_get_scenario, definition, card_snapshot, (
            ('owner-p1-random-get-is-public-and-replaced', 'p1', {}, {
                'scheduled_before_get': 1, 'hand_count': 1,
                'list_count': 2, 'public_hand_count': 1,
                'face_down_list_count': 2, 'get_done': True,
                'resolved': 1, 'pending': False,
            }),
            ('owner-p2-counter-also-replaces-get', 'p2', {
                'event_type': 'counter',
            }, {'scheduled_before_get': 1, 'hand_count': 1, 'get_done': True}),
            ('qna652-blocked-card-returns-face-down-and-get-ends', 'p1', {
                'blocked': True,
            }, {'scheduled_before_get': 1, 'hand_count': 0, 'list_count': 1,
                'face_down_list_count': 1, 'get_done': True}),
            ('hit-and-combo-schedule-only-once', 'p2', {
                'fire_twice': True,
            }, {'scheduled_before_get': 1, 'hand_count': 1, 'resolved': 1}),
            ('without-dark-night-does-not-schedule', 'p1', {
                'dark_night': False,
            }, {'scheduled_before_get': 0, 'hand_count': 0, 'get_done': False,
                'resolved': 0}),
            ('numbered-negation-does-not-schedule', 'p2', {
                'numbered_negated': True,
            }, {'scheduled_before_get': 0, 'hand_count': 0, 'resolved': 0}),
        ),
    )
    break_scenarios = _cb01_final_scenarios(
        _run_cb01_at_022_break_scenario, definition, card_snapshot, (
            ('owner-p1-breaks-after-use', 'p1', {}, {
                'source_zone': 'break', 'resolved': 1,
            }),
            ('owner-p2-breaks-after-use', 'p2', {}, {
                'source_zone': 'break', 'resolved': 1,
            }),
            ('wrong-event-does-not-break', 'p1', {'event_type': 'use'}, {
                'source_zone': 'battle', 'resolved': 0,
            }),
            ('numbered-negation-does-not-break', 'p2', {
                'numbered_negated': True,
            }, {'source_zone': 'battle', 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(state['id'], all(item['passed'] for item in state_scenarios), state_scenarios),
        AbilityReview(get_effect['id'], all(item['passed'] for item in get_scenarios), get_scenarios),
        AbilityReview(broken['id'], all(item['passed'] for item in break_scenarios), break_scenarios),
    ]
    passed = all(review.passed and len(review.scenarios) >= 3 for review in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '블랙아웃 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


def _cb01_at_025_bagua_definition():
    return {
        'schema_version': 1, 'reviewed': True,
        'source_refs': {'rulebook_pages': [], 'qna_ids': []},
        'abilities': [{
            'id': 'review-unc-ps-001-bagua',
            'label': '검토용 팔괘 카운터 획득',
            'kind': 'effect', 'mode': 'mandatory', 'timing': 'result',
            'visibility': 'public', 'active_zones': ['passive'],
            'trigger': {'event': 'damage_after'},
            'handler': 'tao_bagua_counter_gain',
        }],
    }


def _run_cb01_at_025_activation_scenario(
    definition, card_snapshot, owner, *, hp=3000, choice='activate',
    numbered_negated=False, event_player=None, test_bagua=False,
    bagua_choice='yang', frame=7,
):
    passive = _card(
        'UNC-PS-001', owner, f'{owner}-cb01-at-025-bagua',
    )
    passive.update({'type': '특성', 'frame': None, 'damage': None})
    extras = [
        ('passive', passive, _cb01_at_025_bagua_definition()),
    ] if test_bagua else []
    engine, _source, _opposing = _cb01_final_engine(
        definition, card_snapshot, owner, source_zone='ultimate', hp=hp,
        numbered_negated=numbered_negated, extra_cards=extras,
    )
    engine.state['phase'] = 'lumen'
    if event_player is None:
        engine._fire('phase_start', {'phase': 'lumen'})
    else:
        engine._fire('hp_changed', {
            'controller': event_player, 'player': event_player,
            'before': hp + 100, 'after': hp, 'amount': -100,
        })
    activation_decision = None
    if engine.engine_state.get('pending_decision'):
        activation_decision = _cb01_final_submit(engine, owner, choice)
    bagua_decision = None
    if test_bagua and choice == 'activate':
        event_card = _card(
            'REVIEW-CB01-AT-025-TAO', owner,
            f'{owner}-cb01-at-025-tao',
        )
        event_card.update({'character_key': 'tao', 'frame': frame})
        engine._fire('damage_after', {
            'controller': owner,
            'player': 'p2' if owner == 'p1' else 'p1', 'amount': 100,
            'source_card_instance_id': event_card['instance_id'],
            'source_card': event_card, 'event_card': event_card,
        })
        if engine.engine_state.get('pending_decision'):
            bagua_decision = _cb01_final_submit(
                engine, owner, bagua_choice,
            )
    passive_state = engine.state['players'][owner]['passive_state']
    return {
        'activation_decision': activation_decision,
        'bagua_decision': bagua_decision,
        'active': bool((passive_state.get('mujin_active') or {}).get('value')),
        'declined': bool((passive_state.get('mujin_declined') or {}).get('value')),
        'yin': int((passive_state.get('yin') or {}).get('count') or 0),
        'yang': int((passive_state.get('yang') or {}).get('count') or 0),
        'resolved': _st2_resolution_count(engine, 'cb01-at-025-n1-activate'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _run_cb01_at_025_break_scenario(
    definition, card_snapshot, owner, *, hp=3000, active=True,
    counter='yin', before=1, amount=-1, numbered_negated=False,
):
    engine, source, _opposing = _cb01_final_engine(
        definition, card_snapshot, owner, source_zone='ultimate', hp=hp,
        numbered_negated=numbered_negated,
    )
    if active:
        engine.state['players'][owner]['passive_state']['mujin_active'] = {
            'value': True,
        }
    engine.state['players'][owner]['passive_state'][counter] = {
        'count': before,
    }
    engine.change_counter(owner, counter, amount)
    location = engine._find_location(source['instance_id'])
    entry = engine.state['players'][owner]['passive_state'].get(counter) or {}
    return {
        'source_zone': location[1] if location else None,
        'counter_count': int(entry.get('count') or 0),
        'resolved': _st2_resolution_count(engine, 'cb01-at-025-n1-break'),
        'pending': bool(engine.engine_state.get('pending_decision')),
    }


def _review_cb01_at_025_definition(definition, card_snapshot, extra_root):
    if str((card_snapshot or {}).get('code') or '') != 'CB01-AT-025':
        return None
    abilities = definition.get('abilities') or []
    by_id = {ability.get('id'): ability for ability in abilities}
    activation = by_id.get('cb01-at-025-n1-activate')
    broken = by_id.get('cb01-at-025-n1-break')
    valid = bool(
        not extra_root
        and set(by_id) == {
            'cb01-at-025-n1-activate', 'cb01-at-025-n1-break',
        }
        and sorted((definition.get('source_refs') or {}).get('qna_ids') or [])
        == [659, 666, 676]
        and activation and activation.get('mode') == 'mandatory'
        and activation.get('active_zones') == ['ultimate']
        and activation.get('trigger') == {
            'event': 'game_start',
            'events': ['game_start', 'hp_changed', 'phase_start'],
        }
        and any(
            node.get('op') == 'choose_effect'
            and [option.get('id') for option in node.get('options') or []]
            == ['activate', 'decline']
            for node in _effect_nodes(activation.get('effects') or [])
        )
        and broken and broken.get('trigger') == {'event': 'counter_changed'}
        and broken.get('effects') == [{'op': 'break_card'}]
    )
    if not valid:
        return DefinitionReview(
            False, False, [AbilityReview(
                'cb01-at-025', False,
                reason='무진의 적용 선택·팔괘 선택·0 카운터 브레이크 정의가 일치하지 않습니다.',
            )], 'CB01-AT-025 전용 정의 검증에 실패했습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    activation_scenarios = _cb01_final_scenarios(
        _run_cb01_at_025_activation_scenario, definition, card_snapshot, (
            ('owner-p1-activates-at-three-thousand', 'p1', {}, {
                'active': True, 'declined': False, 'resolved': 1,
            }),
            ('owner-p2-can-decline-for-future-events', 'p2', {
                'choice': 'decline',
            }, {'active': False, 'declined': True, 'resolved': 1}),
            ('above-threshold-does-not-offer', 'p1', {'hp': 3001}, {
                'active': False, 'declined': False, 'resolved': 0,
            }),
            ('opponent-hp-change-does-not-offer', 'p1', {
                'event_player': 'p2',
            }, {'active': False, 'declined': False, 'resolved': 0}),
            ('numbered-negation-does-not-offer', 'p2', {
                'numbered_negated': True,
            }, {'active': False, 'declined': False, 'resolved': 0}),
            ('qna676-odd-tao-can-choose-yang', 'p1', {
                'test_bagua': True, 'frame': 7, 'bagua_choice': 'yang',
            }, {'active': True, 'yin': 0, 'yang': 1, 'pending': False}),
            ('even-tao-can-choose-yin', 'p2', {
                'test_bagua': True, 'frame': 8, 'bagua_choice': 'yin',
            }, {'active': True, 'yin': 1, 'yang': 0, 'pending': False}),
        ),
    )
    break_scenarios = _cb01_final_scenarios(
        _run_cb01_at_025_break_scenario, definition, card_snapshot, (
            ('owner-p1-yin-reaching-zero-breaks-source', 'p1', {}, {
                'source_zone': 'break', 'counter_count': 0, 'resolved': 1,
            }),
            ('owner-p2-yang-reaching-zero-breaks-source', 'p2', {
                'counter': 'yang',
            }, {'source_zone': 'break', 'counter_count': 0, 'resolved': 1}),
            ('gain-from-zero-does-not-count-as-reaching-zero', 'p1', {
                'before': 0, 'amount': 1,
            }, {'source_zone': 'ultimate', 'counter_count': 1, 'resolved': 0}),
            ('inactive-mujin-does-not-break', 'p2', {'active': False}, {
                'source_zone': 'ultimate', 'counter_count': 0, 'resolved': 0}),
            ('above-threshold-does-not-apply-break', 'p1', {'hp': 3001}, {
                'source_zone': 'ultimate', 'counter_count': 0, 'resolved': 0}),
            ('unrelated-counter-does-not-break', 'p2', {
                'counter': 'ember',
            }, {'source_zone': 'ultimate', 'counter_count': 0, 'resolved': 0}),
            ('numbered-negation-does-not-break', 'p1', {
                'numbered_negated': True,
            }, {'source_zone': 'ultimate', 'counter_count': 0, 'resolved': 0}),
        ),
    )
    reviews = [
        AbilityReview(
            activation['id'],
            all(item['passed'] for item in activation_scenarios),
            activation_scenarios,
        ),
        AbilityReview(
            broken['id'], all(item['passed'] for item in break_scenarios),
            break_scenarios,
        ),
    ]
    passed = all(review.passed and len(review.scenarios) >= 3 for review in reviews)
    return DefinitionReview(
        passed, False, reviews,
        '' if passed else '음양순환극 무진 시나리오 검증에 실패했습니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )


_CARD_SPECIFIC_REVIEW_EXCLUSIONS = frozenset({
    '_review_multi_position_defense_definition',
    '_review_owner_direct_break_definition',
    '_review_simple_defense_definition',
    '_review_play_condition_definition',
    '_review_combo_definition',
    '_review_catch_definition',
    '_review_token_usage_definition',
})


def review_automatic_definition(
    definition, *, card_has_text=False, card_snapshot=None,
):
    """Run schema checks, card-specific scenarios, then generic fallbacks."""
    issues = validate_effect_definition(definition, card_has_text=card_has_text)
    if issues:
        return DefinitionReview(
            False, False, reason='DSL 스키마 오류가 있습니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    extra_root = set(definition) - SIMPLE_ROOT_FIELDS
    token_usage_review = _review_token_usage_definition(
        definition, card_snapshot, extra_root,
    )
    if token_usage_review is not None:
        return token_usage_review

    for name, reviewer in tuple(globals().items()):
        if (
            not name.startswith('_review_')
            or not name.endswith('_definition')
            or name in _CARD_SPECIFIC_REVIEW_EXCLUSIONS
            or not callable(reviewer)
        ):
            continue
        code = getattr(reviewer, '__code__', None)
        if code is None or code.co_argcount != 3:
            continue
        result = reviewer(definition, card_snapshot, extra_root)
        if result is not None:
            return result

    break_review = _review_owner_direct_break_definition(
        definition, card_snapshot, extra_root,
    )
    if break_review is not None:
        return break_review
    defense_review = _review_simple_defense_definition(
        definition, card_snapshot, extra_root,
    )
    if defense_review is not None:
        return defense_review
    play_condition_review = _review_play_condition_definition(
        definition, card_snapshot, extra_root,
    )
    if play_condition_review is not None:
        return play_condition_review
    combo_review = _review_combo_definition(definition, card_snapshot, extra_root)
    if combo_review is not None:
        return combo_review
    catch_review = _review_catch_definition(definition, card_snapshot, extra_root)
    if catch_review is not None:
        return catch_review

    abilities = definition.get('abilities') or []
    if not abilities:
        if definition.get('no_effect') is True:
            empty = AbilityReview('no-effect', True, [
                {'name': 'owner-p1', 'passed': True},
                {'name': 'owner-p2', 'passed': True},
                {'name': 'no-command', 'passed': True},
            ])
            return DefinitionReview(
                True, True, [empty], method=AUTOMATIC_SCENARIO_VERSION,
            )
        return DefinitionReview(
            False, False, reason='능력 또는 효과 없음 선언이 필요합니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )

    reviewed = []
    simple_flags = []
    for ability in abilities:
        cost_review = _review_optional_hp_cost_opponent_fp_ability(
            definition, ability, card_snapshot,
        )
        if cost_review is not None:
            reviewed.append(cost_review)
            simple_flags.append(False)
            continue
        catch_review = _review_optional_self_break_list_catch_ability(
            definition, ability, card_snapshot,
        )
        if catch_review is not None:
            reviewed.append(catch_review)
            simple_flags.append(False)
            continue
        catch_review = _review_state_hit_counter_character_catch_ability(
            definition, ability, card_snapshot,
        )
        if catch_review is not None:
            reviewed.append(catch_review)
            simple_flags.append(False)
            continue
        random_review = _review_clash_random_discard_skip_ability(
            definition, ability, card_snapshot,
        )
        if random_review is not None:
            reviewed.append(random_review)
            simple_flags.append(False)
            continue
        catch_review = _review_conditional_lumen_card_catch_ability(
            definition, ability, card_snapshot,
        )
        if catch_review is not None:
            reviewed.append(catch_review)
            simple_flags.append(False)
            continue
        catch_review = _review_lumen_card_catch_damage_ability(
            definition, ability, card_snapshot,
        )
        if catch_review is not None:
            reviewed.append(catch_review)
            simple_flags.append(False)
            continue
        catch_review = _review_triggered_hand_catch_speed_ability(
            definition, ability, card_snapshot,
        )
        if catch_review is not None:
            reviewed.append(catch_review)
            simple_flags.append(False)
            continue
        qna_discard_review = _review_qna_242_mandatory_discard_ability(
            definition, ability, card_snapshot,
        )
        if qna_discard_review is not None:
            reviewed.append(qna_discard_review)
            simple_flags.append(False)
            continue
        triggered_prevent_review = _review_triggered_turn_catch_prevent_ability(
            definition, ability, card_snapshot,
        )
        if triggered_prevent_review is not None:
            reviewed.append(triggered_prevent_review)
            simple_flags.append(False)
            continue
        speed_lock_review = _review_special_judgment_speed_lock_ability(
            definition, ability, card_snapshot,
        )
        if speed_lock_review is not None:
            reviewed.append(speed_lock_review)
            simple_flags.append(False)
            continue
        qna_review = _review_crs_at_003_qna_224_ability(
            definition, ability, card_snapshot,
        )
        if qna_review is not None:
            reviewed.append(qna_review)
            simple_flags.append(False)
            continue
        qna_review = _review_st5_003_qna_ability(
            definition, ability, card_snapshot,
        )
        if qna_review is not None:
            reviewed.append(qna_review)
            simple_flags.append(False)
            continue
        repeat_damage_review = _review_state_capped_repeat_damage_ability(
            definition, ability, card_snapshot,
        )
        if repeat_damage_review is not None:
            reviewed.append(repeat_damage_review)
            simple_flags.append(False)
            continue
        recovery_review = _review_delayed_recovery_fp_ability(
            definition, ability, card_snapshot,
        )
        if recovery_review is not None:
            reviewed.append(recovery_review)
            simple_flags.append(False)
            continue
        break_followup_review = _review_optional_list_break_followup_ability(
            definition, ability, card_snapshot,
        )
        if break_followup_review is not None:
            reviewed.append(break_followup_review)
            simple_flags.append(False)
            continue
        catch_bonus_review = _review_next_catch_damage_ability(
            definition, ability, card_snapshot,
        )
        if catch_bonus_review is not None:
            reviewed.append(catch_bonus_review)
            simple_flags.append(False)
            continue
        discard_review = _review_mandatory_hand_discard_self_move_ability(
            definition, ability, card_snapshot,
        )
        if discard_review is not None:
            reviewed.append(discard_review)
            simple_flags.append(False)
            continue
        discard_review = _review_mandatory_hand_discard_repeat_damage_ability(
            definition, ability, card_snapshot,
        )
        if discard_review is not None:
            reviewed.append(discard_review)
            simple_flags.append(False)
            continue
        discard_review = _review_optional_character_discard_repeat_damage_ability(
            definition, ability, card_snapshot,
        )
        if discard_review is not None:
            reviewed.append(discard_review)
            simple_flags.append(False)
            continue
        discard_review = _review_discard_damage_ability(
            definition, ability, card_snapshot,
        )
        if discard_review is not None:
            reviewed.append(discard_review)
            simple_flags.append(False)
            continue
        branch_review = _review_damage_limited_choice_ability(
            definition, ability, card_snapshot,
        )
        if branch_review is not None:
            reviewed.append(branch_review)
            simple_flags.append(False)
            continue
        modifier_review = _review_continuous_modifier_ability(
            definition, ability, card_snapshot,
        )
        if modifier_review is not None:
            reviewed.append(modifier_review)
            simple_flags.append(False)
            continue
        special_prevent_review = _review_special_continuous_prevent_ability(
            definition, ability, card_snapshot,
        )
        if special_prevent_review is not None:
            reviewed.append(special_prevent_review)
            simple_flags.append(False)
            continue
        continuous_review = _review_continuous_prevent_ability(
            definition, ability, card_snapshot,
        )
        if continuous_review is not None:
            reviewed.append(continuous_review)
            simple_flags.append(False)
            continue
        simple_reason = _simple_ability_reason(ability)
        if not simple_reason:
            reviewed.append(_review_ability(definition, ability))
            simple_flags.append(True)
            continue
        structured_reason = _structured_ability_reason(ability)
        if not structured_reason:
            reviewed.append(_review_structured_ability(
                definition, ability, card_snapshot,
            ))
            simple_flags.append(False)
            continue
        reviewed.append(AbilityReview(
            str(ability.get('id') or ''), False, reason=structured_reason,
        ))
        simple_flags.append(False)

    if extra_root:
        return DefinitionReview(
            False, False, reviewed,
            reason=f'최상위 규칙({", ".join(sorted(extra_root))})은 카드별 검토가 필요합니다.',
            method=AUTOMATIC_SCENARIO_VERSION,
        )
    covered = all(item.scenarios for item in reviewed)
    passed = bool(covered and all(item.passed for item in reviewed))
    return DefinitionReview(
        passed, bool(all(simple_flags)), reviewed,
        '' if passed else '하나 이상의 복합 효과가 카드별 검토 대상입니다.',
        method=AUTOMATIC_SCENARIO_VERSION,
    )
